<?php
declare(strict_types=1);

/**
 * Destructive real WordPress/MySQL acceptance proof for the set-oriented FTS backend.
 *
 * This file is intentionally not part of tests/run.php. Use the Docker wrapper,
 * which supplies a disposable WordPress database, a source-bound release ZIP,
 * explicit cgroup limits, and an evidence directory. Every phase fails when its
 * prerequisites are absent; this proof never reports a successful skip.
 */

const WP_FTS_WC_EVIDENCE_SCHEMA = 'relational-fts-evidence-v5';
const WP_FTS_WC_MANIFEST_OPTION = 'wp_fts_relational_wc_manifest';
const WP_FTS_WC_MAX_VALID_SEED_OPTION = 'wp_fts_relational_wc_max_valid_seed';
const WP_FTS_WC_POST_TITLE_PREFIX = 'WP FTS relational worst case ';
const WP_FTS_WC_INDEX_POST_TYPES = ['post', 'page', 'attachment'];
const WP_FTS_WC_INDEX_POST_STATUSES = ['publish', 'draft', 'pending', 'future', 'private'];
const WP_FTS_WC_DEPENDENCY_LOB_BYTES = 262144;
const WP_FTS_WC_DEPENDENCY_ACCEPTED_UNSELECTED_ROWS = 511;
const WP_FTS_WC_DEPENDENCY_OVERFLOW_UNSELECTED_ROWS = 512;
const WP_FTS_WC_COLD_EVICTION_BYTES = 536870912;
const WP_FTS_WC_COLD_EVICTION_ROW_BYTES = 65536;
const WP_FTS_WC_WARMUP_COUNT = 20;
const WP_FTS_WC_WARM_SAMPLE_COUNT = 200;
const WP_FTS_WC_COLD_SAMPLE_COUNT = 10;
const WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT = 100;
const WP_FTS_WC_PERFORMANCE_SCHEMA_SQL_TEXT_BYTES = 32768;
const WP_FTS_WC_PERFORMANCE_SCHEMA_HISTORY_LONG_EVENTS = 2048;
const WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_HISTORY_EVENTS = 0;
const WP_FTS_WC_PERFORMANCE_SCHEMA_DIGESTS = 0;
const WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES = 128;
// Two complete 1.9-MiB canonical rows cross mysqlnd, wpdb, and WP_Post in one
// bounded page; ordinary search cases retain their separate 16-MiB cap.
const WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES = 25165824;
const WP_FTS_WC_UNUSED_PERFORMANCE_SCHEMA_CAPACITIES = [
    'accounts' => 0,
    'hosts' => 0,
    'users' => 0,
    'session_connect_attrs' => 0,
    'stages_history_long' => 0,
    'stages_history' => 0,
    'transactions_history_long' => 0,
    'transactions_history' => 0,
    'waits_history_long' => 0,
    'waits_history' => 0,
];
const WP_FTS_WC_FAILED_SEARCH_MIN_CONTROL_STATEMENTS = 2;
const WP_FTS_WC_FAILED_SEARCH_MAX_CONTROL_STATEMENTS = 4;
const WP_FTS_WC_FAILED_SEARCH_MAX_PLUGIN_STATEMENTS = 5;
const WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS = [
    'plan' => 5,
    'rank' => 6,
    'hydrate' => 7,
];
const WP_FTS_WC_DENSE_CANDIDATE_TERMS = 4000;
const WP_FTS_WC_DENSE_PREFIX_DOCUMENTS = 2000;
const WP_FTS_WC_DENSE_PREFIX_COMPLETIONS = [
    'prefixprobedenseaaqx',
    'prefixprobedensebbqx',
    'prefixprobedenseccqx',
];
const WP_FTS_WC_TERMINAL_QUERY_TERM = 'visibilityprobe';
const WP_FTS_WC_WORK_TYPE_POST = 'post';

try {
    $phase = wp_fts_wc_required_env('WP_FTS_WC_PHASE');
    if ($phase === 'scope-ddl-writer') {
        $result = wp_fts_wc_scope_ddl_writer();
    } else {
        wp_fts_wc_bootstrap_wordpress();
        $result = match ($phase) {
            'setup' => wp_fts_wc_setup(),
            'indexing-prepare' => wp_fts_wc_indexing_prepare(),
            'initial-index-drain' => wp_fts_wc_reindex_drain(true),
            'reindex-drain' => wp_fts_wc_reindex_drain(),
            'runtime-profile' => wp_fts_wc_runtime_profile(),
            'wpcli-adapter' => wp_fts_wc_wpcli_adapter(),
            'cold-ready-request' => wp_fts_wc_cold_ready_request(),
            'validate' => wp_fts_wc_validate(),
            'concurrency-setup' => wp_fts_wc_concurrency_setup(),
            'idle-http' => wp_fts_wc_idle_http(),
            'cold-prepare' => wp_fts_wc_cold_prepare(),
            'cold-sample' => wp_fts_wc_cold_sample(),
            'cold-cleanup' => wp_fts_wc_cold_cleanup(),
            'concurrent-writer' => wp_fts_wc_concurrent_writer(),
            'scope-proof' => wp_fts_wc_scope_proof(),
            'transaction-crash' => wp_fts_wc_transaction_crash(),
            'verify-transaction-crash' => wp_fts_wc_verify_transaction_crash(),
            'dependency-lob' => wp_fts_wc_dependency_lob(),
            'writer-aggregate' => wp_fts_wc_writer_aggregate(),
            'max-valid-seed' => wp_fts_wc_max_valid_seed(),
            'max-valid-setup' => wp_fts_wc_max_valid_setup(),
            'max-valid-search' => wp_fts_wc_max_valid_search(),
            'search-memory-sample' => wp_fts_wc_search_memory_sample(),
            'drain' => wp_fts_wc_drain(),
            'finalize' => wp_fts_wc_finalize(),
            default => throw new RuntimeException("Unknown worst-case phase: {$phase}"),
        };
    }
    echo json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR) . "\n";
} catch (Throwable $error) {
    fwrite(STDERR, 'FAIL: relational FTS worst-case proof: ' . $error->getMessage() . "\n");
    exit(1);
}

/**
 * Seed a deterministic corpus into canonical wp_posts without invoking 100k
 * synchronous hook stacks. The subsequent wrapper command sends every row
 * through the production WP-CLI extractor/analyzer/index writer.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_setup(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    if (get_option(WP_FTS_WC_MANIFEST_OPTION, null) !== null) {
        throw new RuntimeException('Worst-case corpus already exists; the proof requires a fresh disposable database.');
    }

    $schemaRepair = WP_FTS_Plugin::repair_schema();
    wp_fts_wc_assert(empty($schemaRepair['skipped_locked']), 'Clean-install schema repair unexpectedly lost its writer lease.');
    wp_fts_wc_enable_search_settings();
    $packEvidence = wp_fts_wc_enable_all_runtime_lemma_packs();

    $postTypePlaceholders = implode(',', array_fill(0, count(WP_FTS_WC_INDEX_POST_TYPES), '%s'));
    $indexedPostTypePredicate = $wpdb->prepare(
        'post_type IN (' . $postTypePlaceholders . ')',
        ...WP_FTS_WC_INDEX_POST_TYPES
    );
    wp_fts_wc_assert(is_string($indexedPostTypePredicate) && $indexedPostTypePredicate !== '', 'Could not prepare the configured post-type cleanup predicate.');
    $existingPostIds = $wpdb->get_col("SELECT ID FROM {$wpdb->posts} WHERE {$indexedPostTypePredicate} ORDER BY ID ASC");
    if (!is_array($existingPostIds) || trim((string) $wpdb->last_error) !== '') {
        throw new RuntimeException('Could not enumerate the configured post-type fixture namespace: ' . trim((string) $wpdb->last_error));
    }
    foreach ($existingPostIds as $postId) {
        wp_delete_post((int) $postId, true);
    }
    $remainingIndexedPosts = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM {$wpdb->posts} WHERE {$indexedPostTypePredicate}",
        'configured post-type fixture namespace after cleanup'
    );
    wp_fts_wc_assert($remainingIndexedPosts === 0, 'Configured post-type rows remain before deterministic corpus insertion.');

    $profile = wp_fts_wc_profile();
    $token = 'wpftswc' . substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . $profile['name'] . '|relational-worst-case-v1'), 0, 10);
    $started = hrtime(true);
    $firstId = 0;
    $lastId = 0;
    $inserted = 0;

    for ($start = 1; $start <= $profile['documents']; $start += 200) {
        $end = min($profile['documents'], $start + 199);
        $rows = [];
        $values = [];
        for ($ordinal = $start; $ordinal <= $end; $ordinal++) {
            $document = wp_fts_wc_document($ordinal, $profile, $token);
            $rows[] = '(%d,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%d,%s,%s,%d)';
            array_push(
                $values,
                1,
                $document['date'],
                $document['date'],
                $document['content'],
                $document['title'],
                $document['excerpt'],
                $document['status'],
                'closed',
                'closed',
                $document['password'],
                $document['slug'],
                $document['date'],
                $document['date'],
                '',
                '',
                '',
                0,
                $document['guid'],
                'post',
                0
            );
        }

        $sql = $wpdb->prepare(
            "INSERT INTO {$wpdb->posts}
(post_author,post_date,post_date_gmt,post_content,post_title,post_excerpt,post_status,comment_status,ping_status,post_password,post_name,post_modified,post_modified_gmt,post_content_filtered,to_ping,pinged,post_parent,guid,post_type,comment_count)
VALUES " . implode(',', $rows),
            ...$values
        );
        $affected = $wpdb->query($sql);
        if ($affected !== count($rows)) {
            throw new RuntimeException('Corpus batch insert failed: ' . (string) $wpdb->last_error);
        }
        $inserted += (int) $affected;
        $batchFirstId = (int) $wpdb->insert_id;
        if ($firstId === 0) {
            $firstId = $batchFirstId;
        }
        $lastId = $batchFirstId + count($rows) - 1;
    }

    $actualIds = array_map('intval', $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts} WHERE post_title LIKE %s ORDER BY ID ASC",
        WP_FTS_WC_POST_TITLE_PREFIX . $wpdb->esc_like($token) . '%'
    )) ?: []);
    wp_fts_wc_assert(count($actualIds) === $profile['documents'], 'Inserted corpus count does not match the profile.');
    wp_fts_wc_assert($inserted === $profile['documents'], 'Batch insert affected-row count does not match the profile.');
    wp_fts_wc_assert($actualIds[0] === $firstId && $actualIds[array_key_last($actualIds)] === $lastId, 'Corpus auto-increment IDs were not contiguous in the disposable database.');

    // Attach one real taxonomy term to the entire corpus without firing 100k
    // foreground hooks. The later scope proof calls wp_update_term() and proves
    // that its real pre/post lifecycle remains two bounded work UPSERTs.
    $taxonomyRow = $wpdb->get_row("SELECT term_id,term_taxonomy_id FROM {$wpdb->term_taxonomy} WHERE taxonomy = 'category' ORDER BY term_taxonomy_id ASC LIMIT 1", ARRAY_A);
    wp_fts_wc_assert(is_array($taxonomyRow) && (int) ($taxonomyRow['term_id'] ?? 0) > 0 && (int) ($taxonomyRow['term_taxonomy_id'] ?? 0) > 0, 'The disposable WordPress site has no category term for the scope fixture.');
    $termId = (int) $taxonomyRow['term_id'];
    $termTaxonomyId = (int) $taxonomyRow['term_taxonomy_id'];
    foreach (array_chunk($actualIds, 500) as $chunk) {
        $relationshipRows = [];
        $relationshipArgs = [];
        foreach ($chunk as $postId) {
            $relationshipRows[] = '(%d,%d,0)';
            array_push($relationshipArgs, $postId, $termTaxonomyId);
        }
        $relationshipSql = $wpdb->prepare(
            "INSERT IGNORE INTO {$wpdb->term_relationships} (object_id,term_taxonomy_id,term_order) VALUES " . implode(',', $relationshipRows),
            ...$relationshipArgs
        );
        if ($wpdb->query($relationshipSql) === false) {
            throw new RuntimeException('Could not create the worst-case taxonomy fanout: ' . (string) $wpdb->last_error);
        }
    }
    $wpdb->query($wpdb->prepare(
        "UPDATE {$wpdb->term_taxonomy} SET count = %d WHERE term_taxonomy_id = %d",
        count($actualIds),
        $termTaxonomyId
    ));
    $relationshipCount = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->term_relationships} WHERE term_taxonomy_id = %d",
        $termTaxonomyId
    ));
    wp_fts_wc_assert($relationshipCount === count($actualIds), 'Worst-case taxonomy relationship count is incomplete.');

    // Activation and the analyzer-pack changes coalesce into one current-profile
    // corpus scope. Keep that clean-install work as the initial-index producer;
    // issuing a second filtered CLI scope here would process the same corpus twice.
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    // Deleting WordPress's starter posts above correctly enqueues direct and
    // taxonomy work. Those rows predate this corpus. Remove that setup work,
    // then ask the current profile detector for one authoritative corpus scope.
    wp_fts_wc_assert(
        $wpdb->query("DELETE FROM `{$work}` WHERE kind IN ('post','scope')") !== false,
        'Could not remove starter-post setup work before the clean-install index.'
    );
    WP_FTS_Plugin::reset_request_caches();
    WP_FTS_Plugin::detect_index_profile_drift();
    $derivedRows = [
        'terms' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$terms}`", 'terms before the initial current index'),
        'postings' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$postings}`", 'postings before the initial current index'),
        'documents' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documents}`", 'documents before the initial current index'),
    ];
    wp_fts_wc_assert($derivedRows === ['terms' => 0, 'postings' => 0, 'documents' => 0], 'The clean install contains derived rows before its initial index.');
    $initialWork = [
        'post' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='post'", 'post work before the clean-install index'),
        'scope' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope'", 'scope work before the clean-install index'),
        'corpus' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope' AND scope_coverage='corpus'", 'corpus work before the clean-install index'),
        'filtered' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope' AND scope_coverage='filtered'", 'filtered work before the clean-install index'),
    ];
    wp_fts_wc_assert(
        $initialWork === ['post' => 0, 'scope' => 1, 'corpus' => 1, 'filtered' => 0],
        'Clean installation must retain exactly one current-profile corpus scope before indexing.'
    );

    $manifest = [
        'schema' => 'relational-worst-case-corpus-v1',
        'seed' => 'relational-worst-case-v1',
        'profile' => $profile,
        'token' => $token,
        'first_post_id' => $firstId,
        'last_post_id' => $lastId,
        'term_id' => $termId,
        'term_taxonomy_id' => $termTaxonomyId,
        'distributable_pack_count' => count($packEvidence['expected']),
        'distributable_packs' => $packEvidence['expected'],
        'active_pack_count' => count($packEvidence['active']),
        'active_packs' => $packEvidence['active'],
        'expected_pack_set_sha256' => $packEvidence['expected_sha256'],
        'active_pack_set_sha256' => $packEvidence['active_sha256'],
        'pack_activation_gates' => $packEvidence['gates'],
        'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
        'zip_sha256' => wp_fts_wc_required_env('WP_FTS_ZIP_SHA256'),
        'harness_sha256' => wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256'),
        'lane_id' => wp_fts_wc_required_env('WP_FTS_WC_LANE_ID'),
        'generation_ms' => wp_fts_wc_elapsed_ms($started),
    ];
    $manifest['sha256'] = wp_fts_wc_canonical_hash($manifest);
    update_option(WP_FTS_WC_MANIFEST_OPTION, $manifest, false);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/corpus-manifest.json', $manifest);

    return ['status' => 'PASS', 'phase' => 'setup', 'manifest' => $manifest];
}

/**
 * Force the timed current-version reindex to rebuild every derived document.
 *
 * The initial clean-install index has already produced current hashes, so
 * merely enqueueing the corpus would benchmark the unchanged fast path. The complete
 * derived state is signed before every posting impact, document hash, snippet,
 * and timestamp is poisoned. A hash-only shortcut cannot restore that state:
 * the timed command has to extract and analyze every source and commit its
 * posting impacts and snippet sidecar through the bounded relational writer.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_indexing_prepare(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $manifest = wp_fts_wc_manifest();
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $marker = sha1('wp-fts-forced-full-rebuild|' . wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . (string) $manifest['profile']['name']);
    $preRebuildSignature = wp_fts_wc_complete_index_signature();
    $expectedDocuments = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='post' AND post_status IN ('publish','draft','pending','future','private') AND post_password=''",
        'eligible canonical documents before the forced rebuild'
    );
    $derivedDocuments = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documents}`", 'derived documents before the forced rebuild');
    $existingMarkers = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documents}` WHERE content_hash=%s OR snippet_text=%s", $marker, $marker),
        'pre-existing forced-rebuild markers'
    );
    $nonPositiveImpacts = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$postings}` WHERE impact<=0", 'non-positive posting impacts before the forced rebuild');
    $postingRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$postings}`", 'postings before the forced rebuild');
    $workRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work before the forced rebuild');
    $preRebuildPostingKinds = wp_fts_wc_posting_kind_counts();
    wp_fts_wc_assert($expectedDocuments > 0, 'The forced rebuild has no eligible canonical documents.');
    wp_fts_wc_assert($derivedDocuments === $expectedDocuments, 'The forced rebuild did not start from one derived row per eligible canonical document.');
    wp_fts_wc_assert($existingMarkers === 0, 'The forced-rebuild marker already exists in derived state.');
    wp_fts_wc_assert($postingRows > 0 && $nonPositiveImpacts === 0, 'The forced rebuild must start from a complete positive-impact posting relation.');
    wp_fts_wc_assert($workRows === 0, 'The forced rebuild must start with an empty durable work queue.');

    $poisonedPostings = $wpdb->query("UPDATE `{$postings}` SET impact=0");
    wp_fts_wc_assert(is_int($poisonedPostings) && $poisonedPostings === $postingRows, 'Could not poison every posting impact for the timed full rebuild.');
    $updated = $wpdb->query($wpdb->prepare(
        "UPDATE `{$documents}` SET content_hash=%s,snippet_text=%s,indexed_at=0",
        $marker,
        $marker
    ));
    wp_fts_wc_assert(is_int($updated) && $updated === $derivedDocuments, 'Could not invalidate every derived document for the timed full rebuild.');
    $markerRows = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documents}` WHERE content_hash=%s", $marker),
        'forced-rebuild markers after invalidation'
    );
    $zeroTimestamps = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documents}` WHERE indexed_at=0", 'zero timestamps after forced-rebuild invalidation');
    $markerSnippets = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documents}` WHERE snippet_text=%s", $marker),
        'forced-rebuild snippet markers after invalidation'
    );
    $zeroImpacts = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$postings}` WHERE impact=0", 'zero posting impacts after forced-rebuild invalidation');
    $gates = [
        wp_fts_wc_gate('full_rebuild_canonical_document_count', $expectedDocuments, $derivedDocuments, $derivedDocuments === $expectedDocuments),
        wp_fts_wc_gate('full_rebuild_initial_work_rows', 0, $workRows, $workRows === 0),
        wp_fts_wc_gate('full_rebuild_hashes_invalidated', $derivedDocuments, $markerRows, $markerRows === $derivedDocuments),
        wp_fts_wc_gate('full_rebuild_snippets_invalidated', $derivedDocuments, $markerSnippets, $markerSnippets === $derivedDocuments),
        wp_fts_wc_gate('full_rebuild_timestamps_invalidated', $derivedDocuments, $zeroTimestamps, $zeroTimestamps === $derivedDocuments),
        wp_fts_wc_gate('full_rebuild_posting_impacts_invalidated', $postingRows, $zeroImpacts, $zeroImpacts === $postingRows),
        wp_fts_wc_gate('full_rebuild_pre_state_signature_complete', ['documents' => $derivedDocuments, 'postings' => $postingRows], ['documents' => $preRebuildSignature['tables']['documents']['rows'], 'postings' => $preRebuildSignature['tables']['postings']['rows']], $preRebuildSignature['tables']['documents']['rows'] === $derivedDocuments && $preRebuildSignature['tables']['postings']['rows'] === $postingRows),
        wp_fts_wc_gate('full_rebuild_pre_surface_rows_present', '> 0', $preRebuildPostingKinds['surface']['posting_rows'], $preRebuildPostingKinds['surface']['posting_rows'] > 0),
        wp_fts_wc_gate('full_rebuild_pre_posting_kind_totals', $postingRows, $preRebuildPostingKinds['total_posting_rows'], $preRebuildPostingKinds['total_posting_rows'] === $postingRows),
        wp_fts_wc_gate('full_rebuild_pre_doc_freq_matches_physical_rows', $preRebuildPostingKinds['physical_by_kind'], $preRebuildPostingKinds['doc_freq_by_kind'], $preRebuildPostingKinds['physical_by_kind'] === $preRebuildPostingKinds['doc_freq_by_kind']),
    ];
    $evidence = [
        'schema' => 'relational-fts-indexing-prepare-v2',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'indexing-prepare',
        'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
        'profile' => $manifest['profile']['name'],
        'documents' => $derivedDocuments,
        'postings' => $postingRows,
        'marker_sha256' => hash('sha256', $marker),
        'pre_rebuild_signature' => $preRebuildSignature,
        'pre_rebuild_posting_kinds' => $preRebuildPostingKinds,
        'gates' => $gates,
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/indexing-prepare.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Forced full-rebuild preparation failed.');
    }

    return ['status' => 'PASS', 'phase' => 'indexing-prepare', 'documents' => $derivedDocuments];
}

/**
 * Drain the asynchronous WP-CLI scope through repeated bounded production
 * worker passes in one PHP process. A shell loop would launch one WordPress
 * container for every 100 documents and measure orchestration rather than the
 * indexer; this retains the production batch boundary without that distortion.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_reindex_drain(bool $initialIndex = false): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    if ($initialIndex) {
        $expectedDocuments = wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='post' AND post_status IN ('publish','draft','pending','future','private') AND post_password=''",
            'eligible canonical documents before the initial index'
        );
    } else {
        $preparation = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/indexing-prepare.json');
        wp_fts_wc_require_evidence_gates(
            $preparation,
            'forced full-rebuild preparation',
            [
                'full_rebuild_canonical_document_count',
                'full_rebuild_initial_work_rows',
                'full_rebuild_hashes_invalidated',
                'full_rebuild_snippets_invalidated',
                'full_rebuild_timestamps_invalidated',
                'full_rebuild_posting_impacts_invalidated',
                'full_rebuild_pre_state_signature_complete',
                'full_rebuild_pre_surface_rows_present',
                'full_rebuild_pre_posting_kind_totals',
                'full_rebuild_pre_doc_freq_matches_physical_rows',
            ],
            'relational-fts-indexing-prepare-v2'
        );
        $expectedDocuments = (int) ($preparation['documents'] ?? 0);
    }
    wp_fts_wc_assert($expectedDocuments > 0, 'The asynchronous reindex drain has no target documents.');
    $expectedCommittedDocuments = $initialIndex
        ? $expectedDocuments
        : wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type='post' AND post_status IN ('publish','draft','pending','future','private')",
            'canonical documents selected by the filtered reindex scope'
        );
    $expectedDeletedDocuments = $expectedCommittedDocuments - $expectedDocuments;
    wp_fts_wc_assert($expectedDeletedDocuments >= 0, 'The filtered reindex scope selected fewer rows than the indexable corpus.');
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $initial = [
        'post' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='post'", 'post work after the WP-CLI reindex enqueue'),
        'scope' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope'", 'scope work after the WP-CLI reindex enqueue'),
        'corpus' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope' AND scope_coverage='corpus'", 'corpus work before the asynchronous drain'),
        'filtered' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope' AND scope_coverage='filtered'", 'filtered work before the asynchronous drain'),
    ];
    $expectedInitial = $initialIndex
        ? ['post' => 0, 'scope' => 1, 'corpus' => 1, 'filtered' => 0]
        : ['post' => 0, 'scope' => 1, 'corpus' => 0, 'filtered' => 1];
    wp_fts_wc_assert(
        $initial === $expectedInitial,
        $initialIndex
            ? 'Clean installation must begin with one corpus scope and no materialized post work.'
            : 'WP-CLI reindex must enqueue one filtered scope and no materialized post work.'
    );

    $started = hrtime(true);
    $deadline = microtime(true) + 21600.0;
    $batches = [];
    $totals = array_fill_keys([
        'attempted',
        'committed',
        'superseded',
        'indexed',
        'analyzed',
        'unchanged',
        'deleted',
        'permanently_rejected',
        'retryable_failures',
        'deferred',
        'empty_terms_cleaned',
        'backfill_scanned',
        'backfill_queued',
        'backfill_processed',
        'last_batch_failures',
    ], 0);
    $scopeCompletions = 0;
    $lockSkips = 0;
    $terminalCleanupStarted = false;
    while (true) {
        wp_fts_wc_assert(microtime(true) < $deadline, 'Asynchronous full-reindex drain exceeded six hours.');
        $batchStarted = hrtime(true);
        $summary = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-full-reindex',
            'batch_size' => 100,
            'time_budget' => 20.0,
        ]);
        foreach (array_keys($totals) as $field) {
            $totals[$field] += max(0, (int) ($summary[$field] ?? 0));
        }
        $scopeCompletions += !empty($summary['scope_completed']) ? 1 : 0;
        $lockSkips += !empty($summary['skipped_locked']) ? 1 : 0;
        $batches[] = [
            'iteration' => count($batches) + 1,
            'duration_ms' => wp_fts_wc_elapsed_ms($batchStarted),
            'status' => $summary['status'] ?? null,
            'attempted' => (int) ($summary['attempted'] ?? 0),
            'committed' => (int) ($summary['committed'] ?? 0),
            'analyzed' => (int) ($summary['analyzed'] ?? 0),
            'backfill_scanned' => (int) ($summary['backfill_scanned'] ?? 0),
            'backfill_queued' => (int) ($summary['backfill_queued'] ?? 0),
            'scope_completed' => !empty($summary['scope_completed']),
            'cleanup_pending' => !empty($summary['cleanup_pending']),
            'empty_terms_cleaned' => (int) ($summary['empty_terms_cleaned'] ?? 0),
            'has_more' => !empty($summary['has_more']),
            'skipped_locked' => !empty($summary['skipped_locked']),
            'stopped_by_budget' => !empty($summary['stopped_by_budget']),
            'stop_reason' => $summary['stop_reason'] ?? null,
            'failures' => (int) ($summary['last_batch_failures'] ?? 0),
        ];
        WP_FTS_Plugin::reset_request_caches();
        gc_collect_cycles();

        if (!empty($summary['has_more']) || !empty($summary['cleanup_pending'])) {
            continue;
        }
        $remaining = wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
            'asynchronous full-reindex work at a terminal worker boundary'
        );
        if ($remaining > 0) {
            continue;
        }
        if (!$terminalCleanupStarted) {
            // A final empty worker pass proves bounded dictionary cleanup is
            // complete after the last scope/post acknowledgement.
            $terminalCleanupStarted = true;
            continue;
        }
        break;
    }

    $initialReadiness = null;
    if ($initialIndex) {
        // Production publishes search readiness from the maintenance callback
        // that the completed corpus scope schedules. Run that callback now;
        // this harness must not depend on ambient WP-Cron timing.
        WP_FTS_Plugin::run_scheduled_schema_repair();
        WP_FTS_Plugin::reset_request_caches();
        $initialReadiness = WP_FTS_Plugin::search_takeover_status(false);
    }

    $remaining = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        'final asynchronous full-reindex work'
    );
    $statuses = array_values(array_unique(array_map(static fn(array $batch): string => (string) ($batch['status'] ?? ''), $batches)));
    // A worker may analyze a bounded suffix before its time budget expires and
    // then analyze that suffix again on the next pass. Those temporary deferrals
    // are not terminal failures when every document is eventually committed.
    $analysisCeiling = $expectedDocuments + $totals['deferred'];
    $terminalFailures = $totals['superseded']
        + $totals['permanently_rejected']
        + $totals['retryable_failures']
        + $totals['last_batch_failures'];
    // Scope scans and document writes take separate worker turns. Bound both
    // from the measured rows, then allow setup and terminal cleanup turns.
    $workerPassCeiling = (int) ceil($totals['backfill_scanned'] / 100)
        + (int) ceil($totals['committed'] / 100)
        + 5;
    $gates = [
        wp_fts_wc_gate('reindex_enqueue_constant_scope', $expectedInitial, $initial, $initial === $expectedInitial),
        wp_fts_wc_gate('reindex_committed_documents', $expectedCommittedDocuments, $totals['committed'], $totals['committed'] === $expectedCommittedDocuments),
        wp_fts_wc_gate('reindex_deleted_documents', $expectedDeletedDocuments, $totals['deleted'], $totals['deleted'] === $expectedDeletedDocuments),
        wp_fts_wc_gate('reindex_analyzed_documents', "{$expectedDocuments}..{$analysisCeiling}", $totals['analyzed'], $totals['analyzed'] >= $expectedDocuments && $totals['analyzed'] <= $analysisCeiling),
        wp_fts_wc_gate('reindex_indexed_documents', $expectedDocuments, $totals['indexed'], $totals['indexed'] === $expectedDocuments),
        wp_fts_wc_gate('reindex_scope_completion', 1, $scopeCompletions, $scopeCompletions === 1),
        wp_fts_wc_gate('reindex_terminal_failures', 0, $terminalFailures, $terminalFailures === 0),
        wp_fts_wc_gate('reindex_worker_statuses', ['success'], $statuses, $statuses === ['success']),
        wp_fts_wc_gate('reindex_lock_skips', 0, $lockSkips, $lockSkips === 0),
        wp_fts_wc_gate('reindex_worker_passes', '<= ' . $workerPassCeiling, count($batches), count($batches) <= $workerPassCeiling),
        wp_fts_wc_gate('reindex_remaining_work', 0, $remaining, $remaining === 0),
        wp_fts_wc_gate('reindex_terminal_cleanup_pass', true, $terminalCleanupStarted, $terminalCleanupStarted),
        wp_fts_wc_gate('reindex_php_peak_bytes', '<= 268435456', memory_get_peak_usage(true), memory_get_peak_usage(true) <= 268435456),
        wp_fts_wc_gate('reindex_rss_peak_bytes', '<= 536870912', wp_fts_wc_rss_bytes('VmHWM'), wp_fts_wc_rss_bytes('VmHWM') <= 536870912),
    ];
    if ($initialIndex) {
        $gates[] = wp_fts_wc_gate(
            'initial_index_search_ready',
            ['ready' => true, 'reason' => 'ready'],
            [
                'ready' => $initialReadiness['ready'] ?? null,
                'reason' => $initialReadiness['reason'] ?? null,
            ],
            ($initialReadiness['ready'] ?? false) === true
                && ($initialReadiness['reason'] ?? '') === 'ready'
        );
    }
    $evidence = [
        'schema' => $initialIndex ? 'relational-fts-initial-index-drain-v1' : 'relational-fts-reindex-drain-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => $initialIndex ? 'initial-index-drain' : 'reindex-drain',
        'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
        'profile' => wp_fts_wc_required_env('WP_FTS_WC_PROFILE'),
        'expected_documents' => $expectedDocuments,
        'expected_committed_documents' => $expectedCommittedDocuments,
        'expected_deleted_documents' => $expectedDeletedDocuments,
        'initial_work' => $initial,
        'elapsed_ms' => wp_fts_wc_elapsed_ms($started),
        'batch_count' => count($batches),
        'batches' => $batches,
        'totals' => $totals,
        'scope_completions' => $scopeCompletions,
        'lock_skips' => $lockSkips,
        'remaining_work' => $remaining,
        'php_peak_bytes' => memory_get_peak_usage(true),
        'rss_peak_bytes' => wp_fts_wc_rss_bytes('VmHWM'),
        'gates' => $gates,
    ];
    $artifact = $initialIndex ? '/initial-index-drain.json' : '/reindex-drain.json';
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . $artifact, $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Asynchronous full-reindex drain failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return ['status' => 'PASS', 'phase' => $initialIndex ? 'initial-index-drain' : 'reindex-drain', 'documents' => $totals['indexed'], 'batches' => count($batches)];
}

/**
 * Sign every row of the three persistent derived relations in primary-key
 * order. Keyset chunks keep the PHP working set constant even for the 100k
 * lane; length-prefixed canonical rows prevent separator ambiguity.
 *
 * indexed_at is deliberately excluded because a successful rebuild changes
 * it. The source hash, snippet digest, term dictionary, and every posting
 * impact must otherwise return byte-for-byte to the pre-rebuild state.
 *
 * @return array{schema:string,tables:array<string,array{rows:int,sha256:string}>,sha256:string}
 */
function wp_fts_wc_complete_index_signature(): array
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $chunk = 5000;
    $tableEvidence = [];

    $context = hash_init('sha256');
    $rowsSeen = 0;
    $lastTermId = 0;
    do {
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT term_id,lang,kind,HEX(term) term_hex,doc_freq FROM `{$terms}` WHERE term_id>%d ORDER BY term_id ASC LIMIT {$chunk}",
            $lastTermId
        ), ARRAY_A);
        wp_fts_wc_assert(is_array($rows) && trim((string) $wpdb->last_error) === '', 'Could not stream the term dictionary for the rebuild signature.');
        foreach ($rows as $row) {
            wp_fts_wc_signature_update($context, [
                (int) $row['term_id'],
                (string) $row['lang'],
                (int) $row['kind'],
                (string) $row['term_hex'],
                (int) $row['doc_freq'],
            ]);
            $lastTermId = (int) $row['term_id'];
            $rowsSeen++;
        }
    } while (count($rows) === $chunk);
    $tableEvidence['terms'] = ['rows' => $rowsSeen, 'sha256' => hash_final($context)];

    $context = hash_init('sha256');
    $rowsSeen = 0;
    $lastTermId = 0;
    $lastPostId = 0;
    do {
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT term_id,post_id,impact FROM `{$postings}` WHERE term_id>%d OR (term_id=%d AND post_id>%d) ORDER BY term_id ASC,post_id ASC LIMIT {$chunk}",
            $lastTermId,
            $lastTermId,
            $lastPostId
        ), ARRAY_A);
        wp_fts_wc_assert(is_array($rows) && trim((string) $wpdb->last_error) === '', 'Could not stream postings for the rebuild signature.');
        foreach ($rows as $row) {
            wp_fts_wc_signature_update($context, [(int) $row['term_id'], (int) $row['post_id'], (int) $row['impact']]);
            $lastTermId = (int) $row['term_id'];
            $lastPostId = (int) $row['post_id'];
            $rowsSeen++;
        }
    } while (count($rows) === $chunk);
    $tableEvidence['postings'] = ['rows' => $rowsSeen, 'sha256' => hash_final($context)];

    $context = hash_init('sha256');
    $rowsSeen = 0;
    $lastPostId = 0;
    do {
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT post_id,primary_lang,HEX(content_hash) content_hash_hex,SHA2(COALESCE(snippet_text,''),256) snippet_sha256 FROM `{$documents}` WHERE post_id>%d ORDER BY post_id ASC LIMIT {$chunk}",
            $lastPostId
        ), ARRAY_A);
        wp_fts_wc_assert(is_array($rows) && trim((string) $wpdb->last_error) === '', 'Could not stream documents for the rebuild signature.');
        foreach ($rows as $row) {
            wp_fts_wc_signature_update($context, [(int) $row['post_id'], (string) $row['primary_lang'], (string) $row['content_hash_hex'], (string) $row['snippet_sha256']]);
            $lastPostId = (int) $row['post_id'];
            $rowsSeen++;
        }
    } while (count($rows) === $chunk);
    $tableEvidence['documents'] = ['rows' => $rowsSeen, 'sha256' => hash_final($context)];

    $signature = [
        'schema' => 'relational-fts-complete-index-signature-v1',
        'tables' => $tableEvidence,
    ];
    $signature['sha256'] = wp_fts_wc_canonical_hash($signature);

    return $signature;
}

/**
 * Count lexical and normalized-surface rows independently.
 *
 * The dictionary sums are a second source of truth for the physical posting
 * counts. A writer that misses or duplicates a surface posting therefore
 * cannot make the storage evidence look smaller than the table really is.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_posting_kind_counts(): array
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $dictionaryRows = $wpdb->get_results(
        "SELECT kind,COUNT(*) term_rows,COALESCE(SUM(doc_freq),0) doc_freq_rows
FROM `{$terms}`
WHERE kind IN (0,1)
GROUP BY kind
ORDER BY kind",
        ARRAY_A
    ) ?: [];
    $physicalRows = $wpdb->get_results(
        "SELECT t.kind,COUNT(*) posting_rows
FROM `{$terms}` t FORCE INDEX (PRIMARY)
STRAIGHT_JOIN `{$postings}` p FORCE INDEX (PRIMARY) ON p.term_id=t.term_id
WHERE t.kind IN (0,1)
GROUP BY t.kind
ORDER BY t.kind",
        ARRAY_A
    ) ?: [];
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not count normalized-surface posting amplification.');

    $byKind = [
        0 => ['term_rows' => 0, 'doc_freq_rows' => 0, 'posting_rows' => 0],
        1 => ['term_rows' => 0, 'doc_freq_rows' => 0, 'posting_rows' => 0],
    ];
    foreach ($dictionaryRows as $row) {
        $kind = (int) ($row['kind'] ?? -1);
        if (isset($byKind[$kind])) {
            $byKind[$kind]['term_rows'] = max(0, (int) ($row['term_rows'] ?? 0));
            $byKind[$kind]['doc_freq_rows'] = max(0, (int) ($row['doc_freq_rows'] ?? 0));
        }
    }
    foreach ($physicalRows as $row) {
        $kind = (int) ($row['kind'] ?? -1);
        if (isset($byKind[$kind])) {
            $byKind[$kind]['posting_rows'] = max(0, (int) ($row['posting_rows'] ?? 0));
        }
    }

    return [
        'lexical' => $byKind[0],
        'surface' => $byKind[1],
        'physical_by_kind' => [0 => $byKind[0]['posting_rows'], 1 => $byKind[1]['posting_rows']],
        'doc_freq_by_kind' => [0 => $byKind[0]['doc_freq_rows'], 1 => $byKind[1]['doc_freq_rows']],
        'total_term_rows' => $byKind[0]['term_rows'] + $byKind[1]['term_rows'],
        'total_posting_rows' => $byKind[0]['posting_rows'] + $byKind[1]['posting_rows'],
    ];
}

/** @param resource|HashContext $context */
function wp_fts_wc_signature_update(mixed $context, array $row): void
{
    $encoded = json_encode($row, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    hash_update($context, pack('N', strlen($encoded)) . $encoded);
}

/**
 * Record the complete current index profile from one production PHP runtime.
 * The wrapper invokes this once through the web image and once through a real
 * WP-CLI bootstrap; differing analyzer behavior must not be hidden behind an
 * otherwise successful reindex command.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_runtime_profile(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $role = wp_fts_wc_required_env('WP_FTS_WC_RUNTIME_ROLE');
    if (!in_array($role, ['web', 'wpcli'], true)) {
        throw new RuntimeException("Unsupported runtime-profile role: {$role}");
    }

    $plugin = new ReflectionClass(WP_FTS_Plugin::class);
    $currentProfile = $plugin->getMethod('current_index_profile');
    $currentProfile->setAccessible(true);
    $profile = $currentProfile->invoke(null);
    wp_fts_wc_assert(is_array($profile), 'The production current index profile is not an array.');
    $analyzerSignature = is_scalar($profile['analyzer_signature'] ?? null)
        ? (string) $profile['analyzer_signature']
        : '';
    $profileHash = is_scalar($profile['hash'] ?? null) ? (string) $profile['hash'] : '';
    wp_fts_wc_assert($analyzerSignature !== '' && $profileHash !== '', 'The production index profile omitted its analyzer signature or hash.');

    $evidence = [
        'role' => $role,
        'profile' => $profile,
        'profile_hash' => $profileHash,
        'analyzer_signature' => $analyzerSignature,
        'unicode_normalizer_signature' => (new WP_FTS_Normalizer())->index_signature(),
        'runtime' => [
            'php_version' => PHP_VERSION,
            'php_sapi' => PHP_SAPI,
            'wp_cli' => defined('WP_CLI') && WP_CLI,
            'intl_icu_version' => defined('INTL_ICU_VERSION') ? (string) constant('INTL_ICU_VERSION') : null,
        ],
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . "/runtime-profile-{$role}.json", $evidence);

    return ['status' => 'PASS', 'phase' => 'runtime-profile', 'role' => $role, 'profile_hash' => $profileHash, 'analyzer_signature' => $analyzerSignature];
}

/**
 * Invoke the installed command handler under a real WP-CLI bootstrap while the
 * query filter records the statements actually sent through wpdb. The command
 * explain field is evidence output, not the source of the query-count claim.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_wpcli_adapter(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();
    if (!defined('WP_CLI') || !WP_CLI) {
        throw new RuntimeException('WP-CLI adapter proof requires a real WP-CLI bootstrap.');
    }

    $manifest = wp_fts_wc_manifest();
    $definition = wp_fts_wc_case_definitions($manifest)['common_or'];
    $command = new WP_FTS_WPCLI_Command();
    $recorded = wp_fts_wc_record_queries(static function () use ($command, $definition): void {
        $command->search([(string) $definition['query']], [
            'mode' => 'OR',
            'limit' => '20',
            'lang' => 'en',
            'prefix_matching' => '1',
            'format' => 'json',
            'explain' => '1',
        ]);
    });
    $ftsQueries = array_values(array_filter(
        $recorded['queries'],
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:')
    ));
    $queries = array_values($recorded['queries']);
    $events = array_map(static fn(string $sql): array => ['sql' => $sql], $queries);
    $shape = wp_fts_wc_statement_shape($events);
    $schemaStatements = count(array_filter($queries, 'wp_fts_wc_is_physical_schema_statement'));
    $maxSqlBytes = max(array_map('strlen', $queries) ?: [0]);
    $gates = [
        wp_fts_wc_gate('actual_wpcli_query_count', 3, count($queries), count($queries) === 3),
        wp_fts_wc_gate('actual_wpcli_fts_query_count', 3, count($ftsQueries), count($ftsQueries) === 3),
        wp_fts_wc_gate('actual_wpcli_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 1], $shape, $shape === ['plan' => 1, 'rank' => 1, 'hydrate' => 1]),
        wp_fts_wc_gate('actual_wpcli_schema_statements', 0, $schemaStatements, $schemaStatements === 0),
        wp_fts_wc_gate('actual_wpcli_max_sql_bytes', '<= 32768', $maxSqlBytes, $maxSqlBytes <= 32768),
    ];
    $evidence = [
        'schema' => 'relational-fts-wpcli-adapter-v2',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'statement_scope' => 'all_recorded_wpdb_including_transaction_control',
        'statement_shape' => $shape,
        'query_count' => count($queries),
        'fts_query_count' => count($ftsQueries),
        'schema_statement_count' => $schemaStatements,
        'max_sql_bytes' => $maxSqlBytes,
        'sql_sha256' => array_map('hash', array_fill(0, count($queries), 'sha256'), $queries),
        'gates' => $gates,
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/wpcli-adapter.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('WP-CLI adapter proof failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return ['status' => 'PASS', 'phase' => 'wpcli-adapter', 'query_count' => count($queries)];
}

/**
 * Prove the steady-state request SQL bound from the beginning of fresh web
 * requests, not from an in-process query filter installed after bootstrap.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_cold_ready_request(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $optionNames = wp_fts_wc_cold_request_option_names();
    $optionRows = wp_fts_wc_cold_option_rows($optionNames);
    wp_fts_wc_assert(count($optionRows) === count($optionNames), 'Cold-request proof requires every current request option.');
    $schemaVersion = (int) maybe_unserialize((string) $optionRows[WP_FTS_Plugin::SCHEMA_VERSION_OPTION]['option_value']);
    $acceptedProfile = wp_fts_wc_current_index_profile_hash();
    $takeover = WP_FTS_Plugin::search_takeover_status(false);
    $autoloadValues = function_exists('wp_autoload_values_to_autoload')
        ? array_map('strval', wp_autoload_values_to_autoload())
        : ['yes'];
    $autoloadActual = [];
    foreach ($optionNames as $name) {
        $autoloadActual[$name] = (string) ($optionRows[$name]['autoload'] ?? '');
    }
    $autoloaded = count(array_filter(
        $autoloadActual,
        static fn(string $value): bool => !in_array($value, $autoloadValues, true)
    )) === 0;

    $attributionPlugin = wp_fts_wc_install_request_attribution_mu_plugin();
    register_shutdown_function(static function () use ($attributionPlugin): void {
        @unlink($attributionPlugin);
    });

    try {
        $cas = wp_fts_wc_cold_ready_cas_visibility();
        $cases = [];
        foreach (['ready', 'impossible', 'nonhydrate', 'hydrated'] as $caseId) {
            $cases[$caseId] = wp_fts_wc_measure_cold_ready_http($caseId);
        }

        $caseThreads = array_map(static fn(array $case): int => (int) ($case['attribution']['thread_id'] ?? 0), $cases);
        $freshConnections = count(array_unique($caseThreads)) === count($cases)
            && count(array_filter($caseThreads, static fn(int $thread): bool => $thread <= 0)) === 0;
        $freshWebRequests = true;
        $currentSchemaRequests = true;
        $externalObjectCaches = [];
        $directOptionEvents = [];
        $networkTokenEvents = [];
        foreach ($cases as $caseId => $case) {
            $response = is_array($case['response'] ?? null) ? $case['response'] : [];
            $attribution = is_array($case['attribution'] ?? null) ? $case['attribution'] : [];
            $freshWebRequests = $freshWebRequests
                && ($case['status'] ?? null) === 200
                && ($response['case'] ?? null) === $caseId
                && ($response['request_id'] ?? null) === ($case['request_id'] ?? null)
                && ($response['method'] ?? null) === 'GET'
                && is_string($response['sapi'] ?? null)
                && ($response['sapi'] ?? null) !== 'cli'
                && ($response['ready'] ?? null) === true
                && ($attribution['schema'] ?? null) === 'relational-fts-http-attribution-v1'
                && ($attribution['terminal_event_count'] ?? null) === 1
                && (int) ($attribution['first_connection_event_id'] ?? 0) > 0
                && (int) ($attribution['first_connection_event_id'] ?? PHP_INT_MAX) <= (int) ($attribution['tagged_start_event_id'] ?? 0)
                && (int) ($attribution['tagged_start_event_id'] ?? PHP_INT_MAX) <= (int) ($attribution['end_event_id'] ?? 0);
            $currentSchemaRequests = $currentSchemaRequests
                && ($response['schema_version'] ?? null) === WP_FTS_Plugin::SCHEMA_VERSION;
            $externalObjectCaches[$caseId] = $response['external_object_cache'] ?? null;
            foreach (is_array($case['direct_option_events'] ?? null) ? $case['direct_option_events'] : [] as $event) {
                $directOptionEvents[] = ['case' => $caseId, 'event' => $event];
            }
            foreach (is_array($case['network_token_events'] ?? null) ? $case['network_token_events'] : [] as $event) {
                $networkTokenEvents[] = ['case' => $caseId, 'event' => $event];
            }
        }

        $readyShape = $cases['ready']['statement_shape'] ?? null;
        $impossibleShape = $cases['impossible']['statement_shape'] ?? null;
        $nonhydrateShape = $cases['nonhydrate']['statement_shape'] ?? null;
        $hydratedShape = $cases['hydrated']['statement_shape'] ?? null;
        $gates = [
            wp_fts_wc_gate('cold_ready_current_schema_option', WP_FTS_Plugin::SCHEMA_VERSION, $schemaVersion, $schemaVersion === WP_FTS_Plugin::SCHEMA_VERSION),
            wp_fts_wc_gate('cold_ready_current_schema_requests', true, $currentSchemaRequests, $currentSchemaRequests),
            wp_fts_wc_gate('cold_ready_request_autoloaded_options', ['names' => $optionNames, 'autoload_values' => $autoloadValues], ['names' => array_keys($optionRows), 'autoload' => $autoloadActual], $autoloaded && array_keys($optionRows) === $optionNames),
            wp_fts_wc_gate('cold_ready_cas_index_health_alloptions_visibility', true, $cas['index_health'] ?? null, ($cas['index_health'] ?? null) === true),
            wp_fts_wc_gate('cold_ready_cas_search_capability_alloptions_visibility', true, $cas['search_capability'] ?? null, ($cas['search_capability'] ?? null) === true),
            wp_fts_wc_gate('cold_ready_request_fresh_connections', ['four unique DB threads', 'four fresh web requests', $acceptedProfile], [$caseThreads, $freshWebRequests, $takeover['ready'] ?? null], $freshConnections && $freshWebRequests && $acceptedProfile !== '' && ($takeover['ready'] ?? null) === true),
            wp_fts_wc_gate('cold_ready_request_no_external_object_cache', array_fill_keys(array_keys($cases), false), $externalObjectCaches, $externalObjectCaches === array_fill_keys(array_keys($cases), false)),
            wp_fts_wc_gate('cold_ready_request_no_option_or_sitemeta_sql', 0, count($directOptionEvents), $directOptionEvents === []),
            wp_fts_wc_gate('cold_ready_request_no_network_token_select', 0, count($networkTokenEvents), $networkTokenEvents === []),
            wp_fts_wc_gate('cold_ready_request_zero_plugin_sql', ['shape' => ['plan' => 0, 'rank' => 0, 'hydrate' => 0], 'total' => 0], ['shape' => $readyShape, 'total' => $cases['ready']['plugin_statement_count'] ?? null], $readyShape === ['plan' => 0, 'rank' => 0, 'hydrate' => 0] && ($cases['ready']['plugin_statement_count'] ?? null) === 0),
            wp_fts_wc_gate('cold_ready_request_impossible_statement_shape', ['shape' => ['plan' => 1, 'rank' => 0, 'hydrate' => 0], 'total' => 1], ['shape' => $impossibleShape, 'total' => $cases['impossible']['plugin_statement_count'] ?? null], $impossibleShape === ['plan' => 1, 'rank' => 0, 'hydrate' => 0] && ($cases['impossible']['plugin_statement_count'] ?? null) === 1),
            wp_fts_wc_gate('cold_ready_request_nonhydrate_statement_shape', ['shape' => ['plan' => 1, 'rank' => 1, 'hydrate' => 0], 'total' => 2], ['shape' => $nonhydrateShape, 'total' => $cases['nonhydrate']['plugin_statement_count'] ?? null], $nonhydrateShape === ['plan' => 1, 'rank' => 1, 'hydrate' => 0] && ($cases['nonhydrate']['plugin_statement_count'] ?? null) === 2),
            wp_fts_wc_gate('cold_ready_request_hydrated_statement_shape', ['shape' => ['plan' => 1, 'rank' => 1, 'hydrate' => 1], 'total' => 3], ['shape' => $hydratedShape, 'total' => $cases['hydrated']['plugin_statement_count'] ?? null], $hydratedShape === ['plan' => 1, 'rank' => 1, 'hydrate' => 1] && ($cases['hydrated']['plugin_statement_count'] ?? null) === 3),
            wp_fts_wc_gate('cold_ready_request_result_semantics', ['impossible' => 0, 'normal' => '> 0 and identical IDs', 'hydrated_snippets' => true], ['impossible' => $cases['impossible']['response']['result_count'] ?? null, 'nonhydrate' => $cases['nonhydrate']['response']['result_ids'] ?? null, 'hydrated' => $cases['hydrated']['response']['result_ids'] ?? null, 'hydrated_snippets' => $cases['hydrated']['response']['all_results_have_snippets'] ?? null], ($cases['impossible']['response']['result_count'] ?? null) === 0 && is_array($cases['nonhydrate']['response']['result_ids'] ?? null) && ($cases['nonhydrate']['response']['result_ids'] ?? []) !== [] && ($cases['nonhydrate']['response']['result_ids'] ?? null) === ($cases['hydrated']['response']['result_ids'] ?? null) && ($cases['hydrated']['response']['all_results_have_snippets'] ?? null) === true),
        ];
        wp_fts_wc_assert(array_column($gates, 'id') === wp_fts_wc_cold_ready_gate_ids(), 'Cold-request producer gate inventory drifted from its validation consumer.');

        $evidence = [
            'schema' => 'relational-fts-cold-ready-request-v2',
            'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
            'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
            'zip_sha256' => wp_fts_wc_required_env('WP_FTS_ZIP_SHA256'),
            'option_names' => $optionNames,
            'current_schema' => [
                'stored_version' => $schemaVersion,
                'expected_version' => WP_FTS_Plugin::SCHEMA_VERSION,
                'rows' => wp_fts_wc_cold_option_row_evidence($optionRows),
            ],
            'cas' => $cas,
            'autoload' => [
                'accepted_values' => $autoloadValues,
                'rows' => wp_fts_wc_cold_option_row_evidence($optionRows),
            ],
            'cases' => $cases,
            'gates' => $gates,
        ];
        $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
        wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/cold-ready-request.json', $evidence);
        if ($evidence['status'] !== 'PASS') {
            throw new RuntimeException('Cold ready-request proof failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
        }

        return ['status' => 'PASS', 'phase' => 'cold-ready-request', 'cases' => array_keys($cases), 'gate_failures' => []];
    } finally {
        @unlink($attributionPlugin);
    }
}

/** @return string[] */
function wp_fts_wc_cold_request_option_names(): array
{
    return [
        WP_FTS_Plugin::SCHEMA_VERSION_OPTION,
        WP_FTS_Plugin::INDEX_HEALTH_OPTION,
        WP_FTS_Plugin::READINESS_INCARNATION_OPTION,
        WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION,
        WP_FTS_Plugin::SETTINGS_OPTION,
        WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION,
        WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION,
    ];
}

/** @return string[] */
function wp_fts_wc_cold_ready_gate_ids(): array
{
    return [
        'cold_ready_current_schema_option',
        'cold_ready_current_schema_requests',
        'cold_ready_request_autoloaded_options',
        'cold_ready_cas_index_health_alloptions_visibility',
        'cold_ready_cas_search_capability_alloptions_visibility',
        'cold_ready_request_fresh_connections',
        'cold_ready_request_no_external_object_cache',
        'cold_ready_request_no_option_or_sitemeta_sql',
        'cold_ready_request_no_network_token_select',
        'cold_ready_request_zero_plugin_sql',
        'cold_ready_request_impossible_statement_shape',
        'cold_ready_request_nonhydrate_statement_shape',
        'cold_ready_request_hydrated_statement_shape',
        'cold_ready_request_result_semantics',
    ];
}

/** @param string[] $names @return array<string,array{option_name:string,option_value:string,autoload:string}> */
function wp_fts_wc_cold_option_rows(array $names): array
{
    global $wpdb;

    $table = wp_fts_wc_identifier((string) $wpdb->options);
    $placeholders = implode(',', array_fill(0, count($names), '%s'));
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT option_name,option_value,autoload FROM `{$table}` WHERE option_name IN ({$placeholders})",
        ...$names
    ), ARRAY_A) ?: [];
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not read the cold-request option rows.');
    $byName = [];
    foreach ($rows as $row) {
        $name = (string) ($row['option_name'] ?? '');
        if (!in_array($name, $names, true) || isset($byName[$name])) {
            throw new RuntimeException('Cold-request option query returned an unexpected or duplicate row.');
        }
        $byName[$name] = [
            'option_name' => $name,
            'option_value' => (string) ($row['option_value'] ?? ''),
            'autoload' => (string) ($row['autoload'] ?? ''),
        ];
    }
    $ordered = [];
    foreach ($names as $name) {
        if (isset($byName[$name])) {
            $ordered[$name] = $byName[$name];
        }
    }

    return $ordered;
}

/** @param array<string,array{option_name:string,option_value:string,autoload:string}> $rows @return array<string,array<string,mixed>> */
function wp_fts_wc_cold_option_row_evidence(array $rows): array
{
    $evidence = [];
    foreach ($rows as $name => $row) {
        $raw = (string) $row['option_value'];
        $evidence[$name] = [
            'autoload' => (string) $row['autoload'],
            'value_bytes' => strlen($raw),
            'value_sha256' => hash('sha256', $raw),
        ];
    }

    return $evidence;
}

/** Read the production profile identity without duplicating its private derivation. */
function wp_fts_wc_current_index_profile_hash(): string
{
    $read = Closure::bind(
        static fn(): string => WP_FTS_Plugin::current_index_profile_hash(),
        null,
        WP_FTS_Plugin::class
    );
    wp_fts_wc_assert($read instanceof Closure, 'Could not bind the production index-profile reader.');
    $hash = $read();
    wp_fts_wc_assert(
        preg_match('/^[a-f0-9]{40}$/D', $hash) === 1,
        'Production index-profile reader returned an invalid SHA-1 profile hash.'
    );

    return $hash;
}

/** @return array{indexer:string} */
function wp_fts_wc_indexer_signature_evidence(): array
{
    $indexer = (new ReflectionClass(WP_FTS_Indexer::class))->getConstant('INDEX_SIGNATURE_VERSION');
    return [
        'indexer' => is_string($indexer) ? $indexer : '',
    ];
}

/** @return array{index_health:bool,search_capability:bool} */
function wp_fts_wc_cold_ready_cas_visibility(): array
{
    wp_load_alloptions();
    $healthBefore = get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null);
    $capabilityBefore = get_option(WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION, null);
    wp_fts_wc_assert(is_array($healthBefore) && is_array($capabilityBefore), 'Cold-request CAS proof requires array-valued ready state.');
    $nonce = bin2hex(random_bytes(8));
    $healthReplacement = $healthBefore;
    $healthReplacement['last_mode'] = 'cold-ready-cas-' . $nonce;
    $capabilityReplacement = $capabilityBefore;
    $capabilityReplacement['_cold_ready_cas'] = $nonce;
    $casHealth = Closure::bind(
        static fn(mixed $expected, array $replacement): bool => WP_FTS_Plugin::compare_and_swap_index_health($expected, $replacement),
        null,
        WP_FTS_Plugin::class
    );
    $casCapability = Closure::bind(
        static fn(mixed $expected, mixed $replacement): bool => WP_FTS_Plugin::compare_and_swap_search_ready_capability($expected, $replacement),
        null,
        WP_FTS_Plugin::class
    );
    wp_fts_wc_assert($casHealth instanceof Closure && $casCapability instanceof Closure, 'Could not bind the production readiness CAS writers.');

    $healthPublished = $casHealth($healthBefore, $healthReplacement);
    $healthVisible = get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null) === $healthReplacement;
    $healthRestored = $casHealth($healthReplacement, $healthBefore);
    $healthRestoreVisible = get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null) === $healthBefore;
    $capabilityPublished = $casCapability($capabilityBefore, $capabilityReplacement);
    $capabilityVisible = get_option(WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION, null) === $capabilityReplacement;
    $capabilityRestored = $casCapability($capabilityReplacement, $capabilityBefore);
    $capabilityRestoreVisible = get_option(WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION, null) === $capabilityBefore;

    return [
        'index_health' => $healthPublished && $healthVisible && $healthRestored && $healthRestoreVisible,
        'search_capability' => $capabilityPublished && $capabilityVisible && $capabilityRestored && $capabilityRestoreVisible,
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_measure_cold_ready_http(string $caseId): array
{
    $requestId = bin2hex(random_bytes(16));
    $started = hrtime(true);
    $response = wp_remote_get(add_query_arg('wp_fts_wc_cold_request', $requestId, home_url('/')), [
        'headers' => [
            'X-WP-FTS-WC-Request-ID' => $requestId,
            'X-WP-FTS-WC-Cold-Case' => $caseId,
            'Connection' => 'close',
            'User-Agent' => 'wp-fts-cold-ready-proof',
        ],
        'timeout' => 60,
        'redirection' => 0,
    ]);
    $durationMs = wp_fts_wc_elapsed_ms($started);
    if (is_wp_error($response)) {
        throw new RuntimeException("Cold ready-request {$caseId} failed: " . $response->get_error_message());
    }
    $body = (string) wp_remote_retrieve_body($response);
    $decoded = json_decode($body, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($decoded), "Cold ready-request {$caseId} did not return an object payload.");
    $attribution = wp_fts_wc_performance_schema_request_events($requestId, true);
    $classified = wp_fts_wc_classify_cold_request_events($attribution);

    return [
        'status' => (int) wp_remote_retrieve_response_code($response),
        'duration_ms' => $durationMs,
        'request_id' => $requestId,
        'response' => $decoded,
        'attribution' => $attribution,
        ...$classified,
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_classify_cold_request_events(array $attribution): array
{
    global $wpdb;

    $events = is_array($attribution['all_connection_events'] ?? null) ? array_values($attribution['all_connection_events']) : [];
    $optionNames = [...wp_fts_wc_cold_request_option_names(), 'wp_fts_network_activation_token'];
    $optionsTable = strtolower((string) $wpdb->options);
    $siteMetaTable = strtolower((string) $wpdb->sitemeta);
    $ftsPrefix = strtolower((string) $wpdb->prefix . 'fts_');
    $directOptionEvents = [];
    $networkTokenEvents = [];
    $ftsTableEvents = [];
    $pluginEvents = [];
    foreach ($events as $event) {
        $sql = (string) ($event['sql'] ?? '');
        $lower = strtolower($sql);
        $literals = wp_fts_wc_sql_string_literals($sql);
        $referenced = array_values(array_intersect($optionNames, $literals));
        $searchStatement = wp_fts_wc_search_statement_kind($sql) !== null;
        $pluginAttributed = str_contains($sql, 'wp_fts_wc_plugin_query');
        if ($pluginAttributed) {
            $pluginEvents[(int) ($event['event_id'] ?? 0)] = $event;
        }
        if ($pluginAttributed && !$searchStatement && (str_contains($lower, $optionsTable) || str_contains($lower, $siteMetaTable))) {
            $event['referenced_option_names'] = $referenced;
            $directOptionEvents[] = $event;
            if (in_array('wp_fts_network_activation_token', $referenced, true)) {
                $networkTokenEvents[] = $event;
            }
        }
        if (str_contains($lower, $ftsPrefix)) {
            $ftsTableEvents[] = $event;
        }
    }
    ksort($pluginEvents, SORT_NUMERIC);
    $searchEvents = array_values(array_filter(
        $ftsTableEvents,
        static fn(array $event): bool => wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))
    ));

    return [
        'plugin_statement_count' => count($pluginEvents),
        'statement_shape' => wp_fts_wc_statement_shape($searchEvents),
        'plugin_events' => array_values($pluginEvents),
        'direct_option_events' => $directOptionEvents,
        'network_token_events' => $networkTokenEvents,
        'fts_table_events' => $ftsTableEvents,
        'search_events' => $searchEvents,
    ];
}

/** @return string[] */
function wp_fts_wc_sql_string_literals(string $sql): array
{
    $literals = [];
    $length = strlen($sql);
    for ($index = 0; $index < $length; $index++) {
        if ($sql[$index] !== "'") {
            continue;
        }
        $value = '';
        for ($index++; $index < $length; $index++) {
            $character = $sql[$index];
            if ($character === '\\' && $index + 1 < $length) {
                $value .= $sql[++$index];
                continue;
            }
            if ($character !== "'") {
                $value .= $character;
                continue;
            }
            if ($index + 1 < $length && $sql[$index + 1] === "'") {
                $value .= "'";
                $index++;
                continue;
            }
            $literals[] = $value;
            break;
        }
    }

    return $literals;
}

/**
 * Run structural, correctness, performance, SQL-shape, and failure gates.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_validate(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $manifest = wp_fts_wc_manifest();
    $profile = $manifest['profile'];
    $schemaEvidence = wp_fts_wc_assert_relational_schema();
    $tables = $schemaEvidence['tables'];
    $indexingPrepare = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/indexing-prepare.json');
    $postRebuildSignature = wp_fts_wc_complete_index_signature();
    $preRebuildSignature = is_array($indexingPrepare['pre_rebuild_signature'] ?? null)
        ? $indexingPrepare['pre_rebuild_signature']
        : [];
    $preRebuildPostingKinds = is_array($indexingPrepare['pre_rebuild_posting_kinds'] ?? null)
        ? $indexingPrepare['pre_rebuild_posting_kinds']
        : [];
    $postRebuildPostingKinds = wp_fts_wc_posting_kind_counts();
    $postingKindsRestored = $preRebuildPostingKinds !== []
        && $postRebuildPostingKinds === $preRebuildPostingKinds;
    $rebuildMarker = sha1('wp-fts-forced-full-rebuild|' . wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . (string) $profile['name']);
    $documentsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $postingsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $remainingRebuildMarkers = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documentsTable}` WHERE content_hash=%s", $rebuildMarker),
        'forced-rebuild hash markers immediately after timed indexing'
    );
    $remainingRebuildSnippetMarkers = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documentsTable}` WHERE snippet_text=%s", $rebuildMarker),
        'forced-rebuild snippet markers immediately after timed indexing'
    );
    $remainingZeroTimestamps = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$documentsTable}` WHERE indexed_at=0",
        'zero timestamps immediately after timed indexing'
    );
    $remainingNonPositiveImpacts = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$postingsTable}` WHERE impact<=0",
        'non-positive posting impacts immediately after timed indexing'
    );
    $rebuiltDocumentRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documentsTable}`", 'derived documents immediately after timed indexing');
    $invalidRebuiltHashes = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$documentsTable}` WHERE content_hash IS NULL OR OCTET_LENGTH(content_hash)<>40",
        'invalid content hashes immediately after timed indexing'
    );
    $signatureRestored = $preRebuildSignature !== [] && $postRebuildSignature === $preRebuildSignature;
    $rebuildFullyRestored = $signatureRestored
        && $postingKindsRestored
        && $remainingRebuildMarkers === 0
        && $remainingRebuildSnippetMarkers === 0
        && $remainingZeroTimestamps === 0
        && $remainingNonPositiveImpacts === 0
        && $invalidRebuiltHashes === 0
        && $rebuiltDocumentRows === (int) ($indexingPrepare['documents'] ?? -1)
        && (int) ($postRebuildSignature['tables']['postings']['rows'] ?? -1) === (int) ($indexingPrepare['postings'] ?? -2);
    // Restoring every poisoned posting impact and snippet is only possible
    // after each source crossed both analysis and the relational commit path.
    $analyzedDocuments = $rebuildFullyRestored ? $rebuiltDocumentRows : 0;
    $committedDocuments = $rebuildFullyRestored ? $rebuiltDocumentRows : 0;
    $postRebuildProof = [
        'pre_signature' => $preRebuildSignature,
        'post_signature' => $postRebuildSignature,
        'signature_restored' => $signatureRestored,
        'posting_kinds_restored' => $postingKindsRestored,
        'pre_posting_kinds' => $preRebuildPostingKinds,
        'post_posting_kinds' => $postRebuildPostingKinds,
        'hash_markers_remaining' => $remainingRebuildMarkers,
        'snippet_markers_remaining' => $remainingRebuildSnippetMarkers,
        'zero_timestamps_remaining' => $remainingZeroTimestamps,
        'non_positive_impacts_remaining' => $remainingNonPositiveImpacts,
        'invalid_content_hashes' => $invalidRebuiltHashes,
        'analyzed_documents' => $analyzedDocuments,
        'committed_documents' => $committedDocuments,
    ];
    $corpusFrequencyEvidence = wp_fts_wc_adversarial_frequency_proof($manifest);
    $surfaceStorageEvidence = wp_fts_wc_surface_storage_proof($manifest, $postRebuildPostingKinds);
    $storage = wp_fts_wc_storage_fixture(false);
    if (!interface_exists('WP_FTS_Set_Oriented_Search_Storage') || !($storage instanceof WP_FTS_Set_Oriented_Search_Storage)) {
        throw new RuntimeException('The relational storage does not implement WP_FTS_Set_Oriented_Search_Storage. This is a hard backend dependency, not a skipped proof.');
    }

    $searcher = new WP_FTS_Searcher($storage, new WP_FTS_Analyzer(WP_FTS_Plugin::runtime_analyzer_options()));
    $identityEpochEngineEvidence = wp_fts_wc_identity_epoch_engine_proof($searcher, $storage);
    $analysisEvidence = wp_fts_wc_analysis_proof();
    $oracleEvidence = wp_fts_wc_oracle_proof($searcher, $manifest);
    $cursorEvidence = wp_fts_wc_cursor_proof($searcher, $manifest);
    $terminalOracleEvidence = wp_fts_wc_terminal_streaming_oracle($searcher, $manifest);
    $writeEvidence = wp_fts_wc_write_path_proof($manifest);
    $availabilityEvidence = wp_fts_wc_missing_table_and_lock_proof($manifest);
    $faultEvidence = wp_fts_wc_failure_recovery_proof($manifest);
    $dirtyEvidence = wp_fts_wc_enqueue_dirty_head($manifest);

    $caseDefinitions = wp_fts_wc_case_definitions($manifest);
    $cases = [];
    $gates = [];
    $mutationFence = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/mutation-fence-concurrency.json');
    $resourcesForMutationFence = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/resources.json');
    $gates[] = wp_fts_wc_gate(
