    $gates[] = wp_fts_wc_gate('resource_evidence_binding', [$profile['name'], $profile['documents'], wp_fts_wc_required_env('WP_FTS_WC_ENGINE'), wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256')], [$resources['profile'] ?? null, (int) ($resources['documents'] ?? -1), $resources['engine'] ?? null, $resources['harness_sha256'] ?? null], ($resources['schema'] ?? null) === 'relational-fts-resources-v2' && ($resources['status'] ?? null) === 'PASS' && ($resources['profile'] ?? null) === $profile['name'] && (int) ($resources['documents'] ?? -1) === $profile['documents'] && ($resources['engine'] ?? null) === wp_fts_wc_required_env('WP_FTS_WC_ENGINE') && ($resources['harness_sha256'] ?? null) === wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256'));
    // The local 2k profile keeps the same fixed maximum-width and dense-prefix
    // fixtures as the scale lanes, so their constant rows dominate its ratio.
    $bytesPerDocumentLimit = $profile['name'] === '2k' ? 24576 : 14336;
    $gates[] = wp_fts_wc_gate('storage_bytes_per_doc', "<= {$bytesPerDocumentLimit}", $bytesPerDoc, $bytesPerDoc <= $bytesPerDocumentLimit);
    $gates[] = wp_fts_wc_gate('storage_total_bytes', '<= 1342177280', $storageBytes['total_bytes'], $storageBytes['total_bytes'] <= 1342177280);
    $gates[] = wp_fts_wc_gate('indexing_docs_per_second', '>= 20', $throughput, $throughput >= 20.0);
    $gates[] = wp_fts_wc_gate('indexing_postings_per_second', ">= {$minimumPostingThroughput}", $postingThroughput, $postingThroughput >= $minimumPostingThroughput);
    $distributablePacks = is_array($manifest['distributable_packs'] ?? null) ? array_values($manifest['distributable_packs']) : [];
    $activePacks = is_array($manifest['active_packs'] ?? null) ? array_values($manifest['active_packs']) : [];
    $expectedPackHash = wp_fts_wc_canonical_hash($distributablePacks);
    $activePackHash = wp_fts_wc_canonical_hash($activePacks);
    $gates[] = wp_fts_wc_gate('all_distributable_pack_cardinality_active', count($distributablePacks), count($activePacks), $distributablePacks !== [] && count($activePacks) === count($distributablePacks) && (int) ($manifest['distributable_pack_count'] ?? -1) === count($distributablePacks) && (int) ($manifest['active_pack_count'] ?? -1) === count($activePacks));
    $gates[] = wp_fts_wc_gate('all_distributable_pack_identities_active', $distributablePacks, $activePacks, $activePacks === $distributablePacks);
    $packActivationGates = is_array($manifest['pack_activation_gates'] ?? null) ? $manifest['pack_activation_gates'] : [];
    $runtimePackStatusGate = array_values(array_filter($packActivationGates, static fn(mixed $gate): bool => is_array($gate) && ($gate['id'] ?? null) === 'all_distributable_pack_runtime_statuses_active'));
    $gates[] = wp_fts_wc_gate('all_distributable_pack_manifest_digest_set_active', $expectedPackHash, $activePackHash, ($manifest['expected_pack_set_sha256'] ?? null) === $expectedPackHash && ($manifest['active_pack_set_sha256'] ?? null) === $activePackHash && hash_equals($expectedPackHash, $activePackHash) && count($packActivationGates) === 4 && wp_fts_wc_gates_pass($packActivationGates));
    $gates[] = wp_fts_wc_gate('all_distributable_pack_runtime_statuses_active', true, $runtimePackStatusGate[0]['passed'] ?? null, count($runtimePackStatusGate) === 1 && ($runtimePackStatusGate[0]['passed'] ?? null) === true);
    $gates[] = wp_fts_wc_gate('failure_recovery_progress', true, $faultEvidence['passed'], $faultEvidence['passed'] === true);
    array_push($gates, ...$identityEpochEngineEvidence['gates'], ...$analysisEvidence['gates'], ...$oracleEvidence['gates'], ...$cursorEvidence['gates'], ...$terminalOracleEvidence['gates'], ...$writeEvidence['gates'], ...$availabilityEvidence['gates'], ...$faultEvidence['gates']);
    array_push($gates, ...$corpusFrequencyEvidence['gates'], ...$surfaceStorageEvidence['gates']);

    wp_fts_wc_assert_runtime();
    $runtimeRecord = wp_fts_wc_runtime_evidence();
    $expectedConsumers = [
        'events_statements_current' => 'YES',
        'events_statements_history' => 'NO',
        'events_statements_history_long' => 'YES',
    ];
    $runtimeIntegrity = [
        'performance_schema_statement_consumers' => $runtimeRecord['performance_schema_statement_consumers'] ?? null,
        'performance_schema_max_thread_instances' => $runtimeRecord['performance_schema_max_thread_instances'] ?? null,
        'performance_schema_unused_capacities' => $runtimeRecord['performance_schema_unused_capacities'] ?? null,
        'performance_schema_instrumented_threads' => $runtimeRecord['performance_schema_instrumented_threads'] ?? null,
        'performance_schema_thread_instances_lost' => $runtimeRecord['performance_schema_thread_instances_lost'] ?? null,
    ];
    $gates[] = wp_fts_wc_gate(
        'runtime_performance_schema_integrity',
        [
            'performance_schema_statement_consumers' => $expectedConsumers,
            'performance_schema_max_thread_instances' => WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES,
            'performance_schema_unused_capacities' => WP_FTS_WC_UNUSED_PERFORMANCE_SCHEMA_CAPACITIES,
            'performance_schema_instrumented_threads' => '< ' . WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES,
            'performance_schema_thread_instances_lost' => 0,
        ],
        $runtimeIntegrity,
        ($runtimeIntegrity['performance_schema_statement_consumers'] ?? null) === $expectedConsumers
            && ($runtimeIntegrity['performance_schema_max_thread_instances'] ?? null) === WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES
            && ($runtimeIntegrity['performance_schema_unused_capacities'] ?? null) === WP_FTS_WC_UNUSED_PERFORMANCE_SCHEMA_CAPACITIES
            && is_int($runtimeIntegrity['performance_schema_instrumented_threads'] ?? null)
            && $runtimeIntegrity['performance_schema_instrumented_threads'] < WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES
            && ($runtimeIntegrity['performance_schema_thread_instances_lost'] ?? null) === 0
    );

    $validationGateIds = array_map(static fn(array $gate): string => (string) ($gate['id'] ?? ''), $gates);
    wp_fts_wc_assert(
        $validationGateIds !== []
            && !in_array('', $validationGateIds, true)
            && !in_array('evidence_gate_ids_unique', $validationGateIds, true)
            && count(array_unique($validationGateIds)) === count($validationGateIds),
        'Validation gate IDs must be nonempty, unique, and must reserve the finalizer uniqueness gate.'
    );
    wp_fts_wc_assert(
        wp_fts_wc_gate_inventory_fingerprint_matches($validationGateIds, 'preliminary'),
        'Validation gate IDs differ from the exact source-reviewed preliminary inventory: count='
            . count($validationGateIds)
            . ' sha256='
            . wp_fts_wc_canonical_hash($validationGateIds)
    );
    $validationSections = wp_fts_wc_validation_section_ids();
    $validationInventory = [
        'schema' => 'relational-fts-validation-inventory-v1',
        'section_ids' => $validationSections,
        'case_ids' => array_keys($caseDefinitions),
        'gate_ids' => $validationGateIds,
        'gate_count' => count($validationGateIds),
        'gate_ids_sha256' => wp_fts_wc_canonical_hash($validationGateIds),
    ];

    $evidence = [
        'schema' => WP_FTS_WC_EVIDENCE_SCHEMA,
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
        'zip_sha256' => wp_fts_wc_required_env('WP_FTS_ZIP_SHA256'),
        'source_dirty' => wp_fts_wc_required_env('WP_FTS_SOURCE_DIRTY') === '1',
        'acceptance_lane' => wp_fts_wc_required_env('WP_FTS_WC_ALLOW_DIRTY') !== '1',
        'lane_id' => wp_fts_wc_required_env('WP_FTS_WC_LANE_ID'),
        'completed' => false,
        'engine' => wp_fts_wc_required_env('WP_FTS_WC_ENGINE'),
        'runtime' => $runtimeRecord,
        'runtime_profile_parity' => $runtimeParity,
        'mutation_fence_concurrency' => $mutationFence,
        'actual_wpcli_adapter' => $wpcliAdapter,
        'cold_ready_requests' => $coldReady,
        'resource_limits' => $resources,
        'manifest' => $manifest,
        'tables' => $tables,
        'physical_schema' => $schemaEvidence,
        'storage' => $storageBytes + ['bytes_per_eligible_doc' => $bytesPerDoc],
        'indexing' => $indexing + ['docs_per_second' => $throughput, 'postings_per_second' => $postingThroughput, 'rebuild_amplification' => $rebuildAmplification, 'preparation' => $indexingPrepare, 'drain' => $reindexDrain, 'rebuild_proof' => $postRebuildProof],
        'dirty_head' => $dirtyEvidence,
        'adversarial_frequencies' => $corpusFrequencyEvidence,
        'surface_storage' => $surfaceStorageEvidence,
        'identity_epoch_engine' => $identityEpochEngineEvidence,
        'analysis' => $analysisEvidence,
        'oracle' => $oracleEvidence,
        'cursor_traversal' => $cursorEvidence,
        'terminal_streaming_oracle' => $terminalOracleEvidence,
        'write_paths' => $writeEvidence,
        'availability_faults' => $availabilityEvidence,
        'failure_recovery' => $faultEvidence,
        'cases' => $cases,
        'pack_cardinality' => $packCardinality,
        'public_adapters' => $publicAdapters,
        'actual_http_adapters' => $httpAdapters,
        'adapter_oracle' => $adapterOracle,
        'explosive_input' => $containment,
        'dependency_lob' => $dependencyLob,
        'validation_inventory' => $validationInventory,
        'gates' => $gates,
        'concurrency' => null,
    ];
    $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
    wp_fts_wc_write_json(wp_fts_wc_evidence_path(), $evidence);

    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException(
            'Validation evidence has failed gates: ' . implode(', ', wp_fts_wc_gate_failures($gates))
        );
    }

    return ['status' => 'PASS', 'phase' => 'validate', 'evidence_path' => wp_fts_wc_evidence_path(), 'gate_failures' => []];
}

/**
 * Exercise the real WordPress postmeta table at the exact dependency-row edge.
 *
 * One post has 511 unselected 256 KiB values followed by one selected value and
 * must index. A second has 512 such values followed by the selected value and
 * must be durably rejected as row overflow. A third grows a selected multibyte
 * value between measurement and hydration: the first generation must remain
 * dirty and hidden after a strict byte-bounded read, then an unchanged retry
 * must commit the exact new value. Worker statements are tagged and measured
 * on both required engines; fixture creation and cleanup are outside the timed
 * regions.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_dependency_lob(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    wp_fts_wc_assert((int) $wpdb->get_var("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')") === 0, 'Dependency LOB proof requires an empty production work table.');

    $customOption = WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION;
    $customOptionExists = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name=%s",
        $customOption
    )) === 1;
    $customOptionBefore = get_option($customOption, null);
    $healthOptionExists = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name=%s",
        WP_FTS_Plugin::INDEX_HEALTH_OPTION
    )) === 1;
    $healthBefore = get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null);
    $cronBefore = function_exists('wp_next_scheduled') ? wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) : false;
    $postIds = [];
    $cleaned = false;

    try {
        update_option($customOption, ['selected_signal'], false);
        WP_FTS_Plugin::reset_request_caches();

        $suffix = substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . wp_fts_wc_required_env('WP_FTS_WC_ENGINE')), 0, 12);
        $acceptedToken = 'wpftslobselected' . $suffix;
        $overflowToken = 'wpftsloboverflow' . $suffix;
        $growthOldToken = 'wpftslobgrowthold' . $suffix;
        $growthNewToken = 'wpftslobgrowthnew' . $suffix;
        $acceptedValue = $acceptedToken . ' 😀漢字é';
        $growthOldValue = $growthOldToken . ' 😀漢字é';
        $growthNewValue = $growthNewToken . ' ' . str_repeat("😀.", 16384);
        $acceptedId = wp_fts_wc_insert_dependency_lob_post('accepted-' . $suffix, 'Bounded dependency source without the selected token.');
        $overflowId = wp_fts_wc_insert_dependency_lob_post('overflow-' . $suffix, 'Overflow dependency source ' . $overflowToken . '.');
        $growthId = wp_fts_wc_insert_dependency_lob_post('growth-' . $suffix, 'Concurrent-growth dependency source without either selected token.');
        $postIds = [$acceptedId, $overflowId, $growthId];

        wp_fts_wc_insert_unselected_lobs($acceptedId, WP_FTS_WC_DEPENDENCY_ACCEPTED_UNSELECTED_ROWS, 'A');
        $acceptedSelectedMetaId = wp_fts_wc_insert_selected_dependency_value($acceptedId, $acceptedValue);
        wp_fts_wc_insert_unselected_lobs($overflowId, WP_FTS_WC_DEPENDENCY_OVERFLOW_UNSELECTED_ROWS, 'B');
        $overflowSelectedMetaId = wp_fts_wc_insert_selected_dependency_value($overflowId, $overflowToken);
        $growthSelectedMetaId = wp_fts_wc_insert_selected_dependency_value($growthId, $growthOldValue);

        $acceptedFixture = wp_fts_wc_dependency_lob_fixture_shape($acceptedId);
        $overflowFixture = wp_fts_wc_dependency_lob_fixture_shape($overflowId);
        $queued = WP_FTS_Plugin::enqueue_posts_for_reindex([$acceptedId, $overflowId], ['document_lang' => 'en']);
        $measurement = wp_fts_wc_measure_dependency_lob_worker();
        $summary = is_array($measurement['summary'] ?? null) ? $measurement['summary'] : [];

        $acceptedWorkAfterRejection = $wpdb->get_row($wpdb->prepare(
            "SELECT state,generation,claimed_generation FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $acceptedId
        ), ARRAY_A);
        $overflowWorkAfterRejection = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $overflowId
        ));
        $acceptedSuccessorStarted = hrtime(true);
        $acceptedSuccessorSummary = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'wc-dependency-lob-accepted-successor',
            'batch_size' => 1,
            'time_budget' => 300.0,
        ]);
        $acceptedSuccessorMs = wp_fts_wc_elapsed_ms($acceptedSuccessorStarted);

        $measurementSql = is_string($measurement['measurement_sql'] ?? null) ? $measurement['measurement_sql'] : '';
        $valueSql = is_string($measurement['value_sql'] ?? null) ? $measurement['value_sql'] : '';
        $measurementExplain = $measurementSql === '' ? [] : wp_fts_wc_explain_dependency_sql($measurementSql, ['pm', 'postmeta']);
        $valueExplain = $valueSql === '' ? [] : wp_fts_wc_explain_dependency_sql($valueSql, ['pm', 'postmeta']);
        $measurementAccess = is_array($measurementExplain['matched_table_access'] ?? null) ? $measurementExplain['matched_table_access'] : [];
        $valueAccess = is_array($valueExplain['matched_table_access'] ?? null) ? $valueExplain['matched_table_access'] : [];
        $measurementIndexed = count($measurementAccess) === 1
            && count(array_filter($measurementAccess, static fn(array $row): bool => strtoupper((string) ($row['access_type'] ?? '')) === 'ALL' || (string) ($row['key'] ?? '') !== 'post_id')) === 0;
        $valueIndexed = count($valueAccess) >= 1
            && count(array_filter($valueAccess, static fn(array $row): bool => strtoupper((string) ($row['access_type'] ?? '')) === 'ALL' || (string) ($row['key'] ?? '') !== 'PRIMARY')) === 0;

        $acceptedHydratedRow = null;
        if ($valueSql !== '') {
            $hydratedRows = $wpdb->get_results($valueSql);
            if (!is_array($hydratedRows) || trim((string) $wpdb->last_error) !== '') {
                throw new RuntimeException('Could not replay the accepted dependency value projection: ' . trim((string) $wpdb->last_error));
            }
            foreach ($hydratedRows as $hydratedRow) {
                if ((string) ($hydratedRow->source_kind ?? '') === 'meta' && (int) ($hydratedRow->source_id ?? 0) === $acceptedSelectedMetaId) {
                    $acceptedHydratedRow = $hydratedRow;
                    break;
                }
            }
        }
        $acceptedRoundTrip = is_object($acceptedHydratedRow)
            && (string) ($acceptedHydratedRow->item_value ?? '') === $acceptedValue
            && (int) ($acceptedHydratedRow->item_value_bytes ?? -1) === strlen($acceptedValue)
            && strlen((string) ($acceptedHydratedRow->item_value ?? '')) === strlen($acceptedValue);

        $acceptedSearch = WP_FTS_Plugin::search($acceptedToken, [
            'lang' => 'en',
            'mode' => 'OR',
            'limit' => 20,
            'prefix_matching' => false,
            'post_types' => ['post'],
            'post_statuses' => ['publish'],
            'include_snippets' => false,
        ]);
        $acceptedSearchIds = array_map('intval', array_column($acceptedSearch, 'doc_id'));
        $documentRows = array_map('intval', $wpdb->get_col($wpdb->prepare(
            "SELECT post_id FROM `{$documents}` WHERE post_id IN (%d,%d) ORDER BY post_id",
            $acceptedId,
            $overflowId
        )) ?: []);
        $fixtureWorkRows = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE post_id IN (%d,%d)",
            $acceptedId,
            $overflowId
        ));
        $failureRecords = is_array($summary['failure_records'] ?? null) ? $summary['failure_records'] : [];
        $overflowRejected = count(array_filter($failureRecords, static fn(array $record): bool =>
            (int) ($record['post_id'] ?? 0) === $overflowId
            && ($record['status'] ?? null) === 'rejected'
            && str_contains((string) ($record['error_message'] ?? ''), 'more than 512')
        )) === 1;
        $rejectionPhaseOutcome = [
            'status' => $summary['status'] ?? null,
            'attempted' => (int) ($summary['attempted'] ?? -1),
            'committed' => (int) ($summary['committed'] ?? -1),
            'queue_processed' => (int) ($summary['queue_processed'] ?? -1),
            'indexed' => (int) ($summary['indexed'] ?? -1),
            'analyzed' => (int) ($summary['analyzed'] ?? -1),
            'unchanged' => (int) ($summary['unchanged'] ?? -1),
            'deleted' => (int) ($summary['deleted'] ?? -1),
            'permanently_rejected' => (int) ($summary['permanently_rejected'] ?? -1),
            'superseded' => (int) ($summary['superseded'] ?? -1),
            'retryable_failures' => (int) ($summary['retryable_failures'] ?? -1),
            'deferred' => (int) ($summary['deferred'] ?? -1),
            'last_batch_failures' => (int) ($summary['last_batch_failures'] ?? -1),
        ];
        $expectedRejectionPhaseOutcome = [
            'status' => 'failed',
            'attempted' => 1,
            'committed' => 1,
            'queue_processed' => 1,
            'indexed' => 0,
            'analyzed' => 1,
            'unchanged' => 0,
            'deleted' => 0,
            'permanently_rejected' => 1,
            'superseded' => 0,
            'retryable_failures' => 0,
            'deferred' => 1,
            'last_batch_failures' => 1,
        ];
        $rejectionPhaseIsolated = is_array($acceptedWorkAfterRejection)
            && (string) ($acceptedWorkAfterRejection['state'] ?? '') === 'ready'
            && (int) ($acceptedWorkAfterRejection['generation'] ?? 0) > 0
            && (int) ($acceptedWorkAfterRejection['claimed_generation'] ?? -1) === 0
            && $overflowWorkAfterRejection === 0;
        $acceptedSuccessorOutcome = [
            'status' => $acceptedSuccessorSummary['status'] ?? null,
            'attempted' => (int) ($acceptedSuccessorSummary['attempted'] ?? -1),
            'committed' => (int) ($acceptedSuccessorSummary['committed'] ?? -1),
            'queue_processed' => (int) ($acceptedSuccessorSummary['queue_processed'] ?? -1),
            'indexed' => (int) ($acceptedSuccessorSummary['indexed'] ?? -1),
            'analyzed' => (int) ($acceptedSuccessorSummary['analyzed'] ?? -1),
            'unchanged' => (int) ($acceptedSuccessorSummary['unchanged'] ?? -1),
            'deleted' => (int) ($acceptedSuccessorSummary['deleted'] ?? -1),
            'permanently_rejected' => (int) ($acceptedSuccessorSummary['permanently_rejected'] ?? -1),
            'superseded' => (int) ($acceptedSuccessorSummary['superseded'] ?? -1),
            'retryable_failures' => (int) ($acceptedSuccessorSummary['retryable_failures'] ?? -1),
            'deferred' => (int) ($acceptedSuccessorSummary['deferred'] ?? -1),
            'last_batch_failures' => (int) ($acceptedSuccessorSummary['last_batch_failures'] ?? -1),
        ];
        $expectedAcceptedSuccessorOutcome = [
            'status' => 'success',
            'attempted' => 1,
            'committed' => 1,
            'queue_processed' => 1,
            'indexed' => 1,
            'analyzed' => 1,
            'unchanged' => 0,
            'deleted' => 0,
            'permanently_rejected' => 0,
            'superseded' => 0,
            'retryable_failures' => 0,
            'deferred' => 0,
            'last_batch_failures' => 0,
        ];

        $growthBaselineQueued = WP_FTS_Plugin::enqueue_posts_for_reindex([$growthId], ['document_lang' => 'en']);
        $growthBaselineSummary = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-dependency-growth-baseline',
            'batch_size' => 1,
            'time_budget' => 300.0,
        ]);
        $growthOldBeforeIds = wp_fts_wc_dependency_search_ids($growthOldToken);
        $growthRequeued = WP_FTS_Plugin::enqueue_posts_for_reindex([$growthId], ['document_lang' => 'en']);
        $growthOldBytes = strlen($growthOldValue);
        $growthBucket = wp_fts_wc_dependency_value_bucket($growthOldBytes);
        $growthMeasurement = wp_fts_wc_measure_dependency_growth_worker(
            $growthSelectedMetaId,
            $growthNewValue
        );
        $growthSummary = is_array($growthMeasurement['summary'] ?? null) ? $growthMeasurement['summary'] : [];
        $growthValueSql = is_string($growthMeasurement['value_sql'] ?? null) ? $growthMeasurement['value_sql'] : '';
        $growthProjection = $wpdb->get_row($wpdb->prepare(
            "SELECT OCTET_LENGTH(pm.meta_value) current_value_bytes,
       OCTET_LENGTH(LEFT(CAST(pm.meta_value AS BINARY), %d)) projected_value_bytes
FROM {$wpdb->postmeta} pm
WHERE pm.meta_id=%d",
            $growthBucket,
            $growthSelectedMetaId
        ), ARRAY_A);
        if (!is_array($growthProjection) || trim((string) $wpdb->last_error) !== '') {
            throw new RuntimeException('Could not measure the concurrent dependency byte projection: ' . trim((string) $wpdb->last_error));
        }
        $growthWorkAfterDeferred = $wpdb->get_row($wpdb->prepare(
            "SELECT state,generation,claimed_generation FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $growthId
        ), ARRAY_A);
        $growthOldAfterDeferredIds = wp_fts_wc_dependency_search_ids($growthOldToken);
        $growthNewAfterDeferredIds = wp_fts_wc_dependency_search_ids($growthNewToken);

        $growthRetryStarted = hrtime(true);
        $growthRetrySummary = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-dependency-growth-retry',
            'batch_size' => 1,
            'time_budget' => 300.0,
        ]);
        $growthRetryMs = wp_fts_wc_elapsed_ms($growthRetryStarted);
        $growthOldAfterRetryIds = wp_fts_wc_dependency_search_ids($growthOldToken);
        $growthNewAfterRetryIds = wp_fts_wc_dependency_search_ids($growthNewToken);
        $growthWorkAfterRetry = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $growthId
        ));
        $growthStoredValue = $wpdb->get_var($wpdb->prepare(
            "SELECT meta_value FROM {$wpdb->postmeta} WHERE meta_id=%d",
            $growthSelectedMetaId
        ));

