/** @return int[] */
function wp_fts_wc_dependency_search_ids(string $token): array
{
    $results = WP_FTS_Plugin::search($token, [
        'lang' => 'en',
        'mode' => 'OR',
        'limit' => 20,
        'prefix_matching' => false,
        'post_types' => ['post'],
        'post_statuses' => ['publish'],
        'include_snippets' => false,
    ]);

    return array_map('intval', array_column($results, 'doc_id'));
}

/** Bucket LOB sizes logarithmically so evidence stays bounded but catches growth. */
function wp_fts_wc_dependency_value_bucket(int $bytes): int
{
    if ($bytes <= 0) {
        return 0;
    }

    $bucket = 1;
    while ($bucket < $bytes && $bucket < WP_FTS_WC_DEPENDENCY_LOB_BYTES) {
        $bucket *= 2;
    }

    return min(WP_FTS_WC_DEPENDENCY_LOB_BYTES, $bucket);
}

/** @return array<string,mixed> */
function wp_fts_wc_measure_dependency_growth_worker(int $metaId, string $grownValue): array
{
    global $wpdb;

    $mutationRows = 0;
    $mutationStarted = false;
    $mutationFilter = static function (string $sql) use ($wpdb, $metaId, $grownValue, &$mutationRows, &$mutationStarted): string {
        if ($mutationStarted || !str_contains($sql, 'wp_fts:dependency_values')) {
            return $sql;
        }

        // The query filter runs immediately before wpdb executes the captured
        // value statement. Set the guard first so the nested UPDATE cannot
        // recursively mutate, then grow the real source row in that interval.
        $mutationStarted = true;
        $updated = $wpdb->update(
            $wpdb->postmeta,
            ['meta_value' => $grownValue],
            ['meta_id' => $metaId],
            ['%s'],
            ['%d']
        );
        if ($updated === false || trim((string) $wpdb->last_error) !== '') {
            throw new RuntimeException('Could not grow the selected dependency between measurement and hydration: ' . trim((string) $wpdb->last_error));
        }
        $mutationRows += (int) $updated;

        return $sql;
    };

    $phpLifetimePeakBeforeReset = memory_get_peak_usage(true);
    wp_fts_wc_reset_php_peak_usage();
    gc_collect_cycles();
    $memoryBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $started = hrtime(true);
    add_filter('query', $mutationFilter, 0, 1);
    try {
        $recorded = wp_fts_wc_record_queries(static fn(): array => WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-dependency-growth-race',
            'batch_size' => 1,
            'time_budget' => 300.0,
        ]));
    } finally {
        remove_filter('query', $mutationFilter, 0);
    }
    $durationMs = wp_fts_wc_elapsed_ms($started);
    $rssAfter = wp_fts_wc_rss_bytes('VmRSS');
    $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
    $measurementQueries = array_values(array_filter(
        $recorded['queries'],
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_measurement')
    ));
    $valueQueries = array_values(array_filter(
        $recorded['queries'],
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_values')
    ));

    return [
        'summary' => is_array($recorded['result']) ? $recorded['result'] : [],
        'duration_ms' => $durationMs,
        'php_memory_delta_bytes' => max(0, memory_get_usage(true) - $memoryBefore),
        'php_peak_delta_bytes' => max(0, memory_get_peak_usage(true) - $memoryBefore),
        'rss_delta_bytes' => max(0, $rssAfter - $rssBefore),
        'rss_before_bytes' => $rssBefore,
        'rss_peak_delta_bytes' => max(0, $rssPeakAfter - $rssBefore),
        'rss_peak_bytes' => $rssPeakAfter,
        'rss_peak_delta_attribution' => 'conservative_vmhwm_after_minus_vmrss_before',
        'query_count' => count($recorded['queries']),
        'mutation_rows' => $mutationRows,
        'measurement_statement_count' => count($measurementQueries),
        'value_statement_count' => count($valueQueries),
        'measurement_sql' => $measurementQueries[0] ?? '',
        'value_sql' => $valueQueries[0] ?? '',
    ];
}

/** Seed one canonical post whose large source is controlled by the LOB proof. */
function wp_fts_wc_insert_dependency_lob_post(string $slug, string $content): int
{
    global $wpdb;

    $inserted = $wpdb->insert($wpdb->posts, [
        'post_author' => 1,
        'post_date' => '2020-02-01 12:00:00',
        'post_date_gmt' => '2020-02-01 12:00:00',
        'post_content' => $content,
        'post_title' => 'WP FTS dependency LOB ' . $slug,
        'post_excerpt' => '',
        'post_status' => 'publish',
        'comment_status' => 'closed',
        'ping_status' => 'closed',
        'post_password' => '',
        'post_name' => 'wp-fts-dependency-lob-' . $slug,
        'post_modified' => '2020-02-01 12:00:00',
        'post_modified_gmt' => '2020-02-01 12:00:00',
        'post_parent' => 0,
        'guid' => 'https://example.invalid/wp-fts-dependency-lob-' . $slug,
        'post_type' => 'post',
        'comment_count' => 0,
    ]);
    if ($inserted !== 1 || (int) $wpdb->insert_id <= 0) {
        throw new RuntimeException('Could not insert the dependency LOB fixture post: ' . (string) $wpdb->last_error);
    }

    return (int) $wpdb->insert_id;
}

/** Add large decoy metadata rows that the selected dependency path must not fetch. */
function wp_fts_wc_insert_unselected_lobs(int $postId, int $rows, string $marker): void
{
    global $wpdb;

    for ($offset = 0; $offset < $rows; $offset += 16) {
        $count = min(16, $rows - $offset);
        $values = [];
        $args = [];
        for ($row = 0; $row < $count; $row++) {
            $values[] = '(%d,%s,REPEAT(%s,%d))';
            array_push($args, $postId, 'wp_fts_wc_ignored_lob', $marker, WP_FTS_WC_DEPENDENCY_LOB_BYTES);
        }
        $statement = $wpdb->prepare(
            "INSERT INTO {$wpdb->postmeta} (post_id,meta_key,meta_value) VALUES " . implode(',', $values),
            ...$args
        );
        if ($wpdb->query($statement) !== $count) {
            throw new RuntimeException('Could not insert actual 256 KiB dependency LOB rows: ' . (string) $wpdb->last_error);
        }
    }
}

/** Retain the selected row identity for exact measurement-versus-hydration evidence. */
function wp_fts_wc_insert_selected_dependency_value(int $postId, string $value): int
{
    global $wpdb;

    if ($wpdb->insert($wpdb->postmeta, [
        'post_id' => $postId,
        'meta_key' => 'selected_signal',
        'meta_value' => $value,
    ]) !== 1 || (int) $wpdb->insert_id <= 0) {
        throw new RuntimeException('Could not insert selected dependency value: ' . (string) $wpdb->last_error);
    }

    return (int) $wpdb->insert_id;
}

/** @return array<string,int> */
function wp_fts_wc_dependency_lob_fixture_shape(int $postId): array
{
    global $wpdb;

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT COUNT(*) total_rows,
       SUM(meta_key='wp_fts_wc_ignored_lob') unselected_rows,
       SUM(meta_key='selected_signal') selected_rows,
       MIN(CASE WHEN meta_key='wp_fts_wc_ignored_lob' THEN OCTET_LENGTH(meta_value) END) unselected_min_bytes,
       MAX(CASE WHEN meta_key='wp_fts_wc_ignored_lob' THEN OCTET_LENGTH(meta_value) END) unselected_max_bytes
FROM {$wpdb->postmeta}
WHERE post_id=%d",
        $postId
    ), ARRAY_A);
    if (!is_array($row) || trim((string) $wpdb->last_error) !== '') {
        throw new RuntimeException('Could not validate the actual dependency LOB fixture: ' . trim((string) $wpdb->last_error));
    }

    return array_map('intval', $row);
}

/** @return array<string,mixed> */
function wp_fts_wc_measure_dependency_lob_worker(): array
{
    global $wpdb;

    $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()');
    wp_fts_wc_assert($threadId > 0, 'Could not map the dependency LOB worker to Performance Schema.');
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $threadId
    ));
    $beforeHandlers = wp_fts_wc_handler_status();
    wp_fts_wc_reset_php_peak_usage();
    gc_collect_cycles();
    $memoryBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $started = hrtime(true);
    $recorded = wp_fts_wc_record_queries(static fn(): array => WP_FTS_Plugin::process_manual_index_batch([
        'source' => 'worst-case-dependency-lob',
        'batch_size' => 2,
        'time_budget' => 300.0,
    ]));
    $durationMs = wp_fts_wc_elapsed_ms($started);
    $rssAfter = wp_fts_wc_rss_bytes('VmRSS');
    $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
    $afterHandlers = wp_fts_wc_handler_status();
    $events = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,LOCK_TIME,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $taggedEvents = array_values(array_filter($events, static fn(array $event): bool => str_contains((string) ($event['SQL_TEXT'] ?? ''), 'wp_fts:dependency_')));
    $measurementQueries = array_values(array_filter($recorded['queries'], static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_measurement')));
    $valueQueries = array_values(array_filter($recorded['queries'], static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_values')));
    $handlerDelta = [];
    foreach ($afterHandlers as $name => $value) {
        $handlerDelta[$name] = max(0, $value - ($beforeHandlers[$name] ?? 0));
    }

    return [
        'summary' => is_array($recorded['result']) ? $recorded['result'] : [],
        'duration_ms' => $durationMs,
        'php_memory_delta_bytes' => max(0, memory_get_usage(true) - $memoryBefore),
        'php_peak_delta_bytes' => max(0, memory_get_peak_usage(true) - $memoryBefore),
        'rss_delta_bytes' => max(0, $rssAfter - $rssBefore),
        'rss_before_bytes' => $rssBefore,
        'rss_peak_delta_bytes' => max(0, $rssPeakAfter - $rssBefore),
        'rss_peak_bytes' => $rssPeakAfter,
        'rss_peak_delta_attribution' => 'conservative_vmhwm_after_minus_vmrss_before',
        'handler_read_delta' => $handlerDelta,
        'handler_read_operations' => array_sum($handlerDelta),
        'measurement_statement_count' => count($measurementQueries),
        'value_statement_count' => count($valueQueries),
        'measurement_sql' => $measurementQueries[0] ?? '',
        'value_sql' => $valueQueries[0] ?? '',
        'performance_schema_events' => $taggedEvents,
        'tag_metrics' => [
            'measurement' => wp_fts_wc_dependency_tag_metrics($taggedEvents, 'wp_fts:dependency_measurement'),
            'values' => wp_fts_wc_dependency_tag_metrics($taggedEvents, 'wp_fts:dependency_values'),
        ],
    ];
}

/** @param array<int,array<string,mixed>> $events @return array<string,int> */
function wp_fts_wc_dependency_tag_metrics(array $events, string $tag): array
{
    $matching = array_values(array_filter($events, static fn(array $event): bool => str_contains((string) ($event['SQL_TEXT'] ?? ''), $tag)));

    return [
        'events' => count($matching),
        'rows_examined' => array_sum(array_map(static fn(array $event): int => (int) ($event['ROWS_EXAMINED'] ?? 0), $matching)),
        'rows_sent' => array_sum(array_map(static fn(array $event): int => (int) ($event['ROWS_SENT'] ?? 0), $matching)),
        'created_tmp_disk_tables' => array_sum(array_map(static fn(array $event): int => (int) ($event['CREATED_TMP_DISK_TABLES'] ?? 0), $matching)),
        'sort_merge_passes' => array_sum(array_map(static fn(array $event): int => (int) ($event['SORT_MERGE_PASSES'] ?? 0), $matching)),
        'no_index_used' => array_sum(array_map(static fn(array $event): int => (int) ($event['NO_INDEX_USED'] ?? 0), $matching)),
        'no_good_index_used' => array_sum(array_map(static fn(array $event): int => (int) ($event['NO_GOOD_INDEX_USED'] ?? 0), $matching)),
    ];
}

/** @param string[] $tableNames @return array<string,mixed> */
function wp_fts_wc_explain_dependency_sql(string $sql, array $tableNames): array
{
    global $wpdb;

    $json = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
    wp_fts_wc_assert(is_string($json) && $json !== '', 'Dependency LOB EXPLAIN FORMAT=JSON returned no plan.');
    $plan = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($plan), 'Dependency LOB EXPLAIN JSON is malformed.');
    $access = [];
    wp_fts_wc_collect_database_table_access($plan, $access);
    $matched = array_values(array_filter($access, static function (array $row) use ($tableNames): bool {
        $actual = strtolower((string) ($row['table_name'] ?? ''));
        foreach ($tableNames as $name) {
            $name = strtolower($name);
            if ($actual === $name || str_ends_with($actual, $name)) {
                return true;
            }
        }
        return false;
    }));

    return ['plan' => $plan, 'table_access' => $access, 'matched_table_access' => $matched];
}

/** @param array<string|int,mixed> $node @param array<int,array<string,mixed>> $access */
function wp_fts_wc_collect_database_table_access(array $node, array &$access): void
{
    if (isset($node['table_name']) && is_scalar($node['table_name'])) {
        $rows = $node['rows'] ?? $node['rows_examined_per_scan'] ?? null;
        $access[] = [
            'table_name' => (string) $node['table_name'],
            'access_type' => is_scalar($node['access_type'] ?? null) ? (string) $node['access_type'] : '',
            'possible_keys' => is_array($node['possible_keys'] ?? null) ? array_values($node['possible_keys']) : [],
            'key' => is_scalar($node['key'] ?? null) ? (string) $node['key'] : '',
            'rows' => is_numeric($rows) ? (int) $rows : null,
            'materialized' => is_array($node['materialized_from_subquery'] ?? null),
            'range_checked_for_each_record' => is_scalar($node['range_checked_for_each_record'] ?? null)
                ? (string) $node['range_checked_for_each_record']
                : '',
        ];
    }
    foreach ($node as $child) {
        if (is_array($child)) {
            wp_fts_wc_collect_database_table_access($child, $access);
        }
    }
}

/** @param int[] $postIds @return array<string,int> */
function wp_fts_wc_cleanup_dependency_lob_fixture(array $postIds, string $documents, string $postings, string $work): array
{
    global $wpdb;

    $postIds = array_values(array_unique(array_filter(array_map('intval', $postIds), static fn(int $postId): bool => $postId > 0)));
    if ($postIds === []) {
        return ['posts' => 0, 'postmeta' => 0, 'documents' => 0, 'postings' => 0, 'work' => 0];
    }
    // Fixture cleanup is intentionally isolated from the production factory:
    // the proof owns this disposable database and records writer SQL directly.
    $storage = new WP_FTS_Relational_Storage($wpdb);
    $storage->replace_prepared_documents([], $postIds);
    $storage->cleanup_empty_terms();
    $placeholders = implode(',', array_fill(0, count($postIds), '%d'));
    foreach ([$work, wp_fts_wc_identifier($wpdb->postmeta), wp_fts_wc_identifier($wpdb->posts)] as $table) {
        $column = $table === $work ? 'post_id' : ($table === wp_fts_wc_identifier($wpdb->postmeta) ? 'post_id' : 'ID');
        if ($wpdb->query($wpdb->prepare("DELETE FROM `{$table}` WHERE {$column} IN ({$placeholders})", ...$postIds)) === false) {
            throw new RuntimeException('Could not clean the dependency LOB fixture: ' . (string) $wpdb->last_error);
        }
    }
    $counts = [
        'posts' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->posts} WHERE ID IN ({$placeholders})", ...$postIds)),
        'postmeta' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE post_id IN ({$placeholders})", ...$postIds)),
        'documents' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$documents}` WHERE post_id IN ({$placeholders})", ...$postIds)),
        'postings' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$postings}` WHERE post_id IN ({$placeholders})", ...$postIds)),
        'work' => (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE post_id IN ({$placeholders})", ...$postIds)),
    ];
    if (trim((string) $wpdb->last_error) !== '') {
        throw new RuntimeException('Could not verify dependency LOB cleanup: ' . trim((string) $wpdb->last_error));
    }

    return $counts;
}

/** Restore both option value and prior absence after an isolated mutation proof. */
function wp_fts_wc_restore_option(string $name, bool $existed, mixed $value): void
{
    if ($existed) {
        update_option($name, $value, false);
    } else {
        delete_option($name);
    }
}

/**
 * Prove every relational-writer cardinality boundary against real wpdb.
 *
 * The fixture distinguishes three independent contracts instead of hiding them
 * behind one small shared vocabulary: the 4,096 lexical and 4,096 normalized
 * surface limits for one document, the 50,000-posting batch limit, and the
 * 8,192-distinct-identity batch limit. Every rejection and split must happen
 * before SQL; every admitted maximum is then committed, counted by kind,
 * checked against document frequencies, and deleted again.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_writer_aggregate(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $termsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postingsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $documentsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $base = (int) $wpdb->get_var("SELECT COALESCE(MAX(post_id),0) FROM `{$documentsTable}`") + 100000;
    $postIds = range($base + 1, $base + 8);
    $fixturePrefix = 'wcwriter' . substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')), 0, 12);
    $recordingWpdb = new WP_FTS_WC_Recording_WPDB($wpdb);
    $storage = new WP_FTS_Relational_Storage($recordingWpdb);
    $cleaned = false;

    try {
        $postingLexical = wp_fts_wc_writer_frequency_map($fixturePrefix . 'pl', 4096);
        $postingSurfaces = wp_fts_wc_writer_frequency_map($fixturePrefix . 'ps', 4096);

        // These are valid maps plus exactly one extra identity. Both poison
        // documents must be rejected by the pure-PHP per-document preflight.
        $lexicalOverflow = $postingLexical;
        $lexicalOverflow[WP_FTS_TermNamespace::namespace_term('en', $fixturePrefix . 'pl-overflow')] = 1;
        $surfaceOverflow = $postingSurfaces;
        $surfaceOverflow[WP_FTS_TermNamespace::namespace_term('en', $fixturePrefix . 'ps-overflow')] = 1;
        $documentRejections = [
            'lexical' => wp_fts_wc_writer_rejection(
                $storage,
                $recordingWpdb,
                wp_fts_wc_writer_document($postIds[6], $lexicalOverflow, [], 'Lexical overflow'),
                'term_limit'
            ),
            'surface' => wp_fts_wc_writer_rejection(
                $storage,
                $recordingWpdb,
                wp_fts_wc_writer_document($postIds[7], [], $surfaceOverflow, 'Surface overflow'),
                'surface_limit'
            ),
        ];
        unset($lexicalOverflow, $surfaceOverflow);

        // Six documents share the same complete identity set. The tail reuses
        // that lexical vocabulary, so 50,001 crosses only the posting frontier
        // rather than disguising an 8,193rd dictionary identity.
        $fullDocuments = [];
        for ($offset = 0; $offset < 6; $offset++) {
            $fullDocuments[] = wp_fts_wc_writer_document(
                $postIds[$offset],
                $postingLexical,
                $postingSurfaces,
                "100% aggregate O'Reilly post {$postIds[$offset]}"
            );
        }
        $partial848 = array_slice($postingLexical, 0, 848, true);
        $partial849 = array_slice($postingLexical, 0, 849, true);
        $exactTail = wp_fts_wc_writer_document($postIds[6], $partial848, [], 'Exact 50,000-posting tail');
        $overflowTail = wp_fts_wc_writer_document($postIds[6], $partial849, [], '50,001-posting split tail');

        $postingSplit = wp_fts_wc_writer_split(
            $storage,
            $recordingWpdb,
            [...$fullDocuments, $overflowTail],
            'postings',
            50001,
            8192,
            6
        );

        $postingBoundaryPart = wp_fts_wc_record_writer_transaction(
            $storage,
            $recordingWpdb,
            [...$fullDocuments, $exactTail],
            'exact 50,000-posting boundary'
        );
        wp_fts_wc_assert($postingBoundaryPart['postings'] === 50000, 'The exact posting boundary did not write 50,000 rows.');
        wp_fts_wc_assert($postingBoundaryPart['terms'] === 8192, 'The exact posting boundary did not retain 8,192 identities.');
        $postingBoundaryStored = wp_fts_wc_writer_stored_counts(
            $fixturePrefix . 'p',
            array_slice($postIds, 0, 7),
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        wp_fts_wc_assert($postingBoundaryStored['documents'] === 7, 'The exact posting boundary lost a document.');
        wp_fts_wc_assert($postingBoundaryStored['postings'] === 50000, 'The exact posting boundary lost a posting.');
        wp_fts_wc_assert(
            $postingBoundaryStored['kinds'] === [
                0 => ['terms' => 4096, 'postings' => 25424],
                1 => ['terms' => 4096, 'postings' => 24576],
            ],
            'The exact posting boundary did not retain the expected lexical/surface rows.'
        );
        wp_fts_wc_assert($postingBoundaryStored['bad_doc_freqs'] === 0, 'The exact posting boundary produced incorrect document frequencies.');
        wp_fts_wc_assert(
            $postingBoundaryStored['snippet'] === "100% aggregate O'Reilly post {$postIds[0]}",
            'The percent-heavy writer snippet did not round-trip exactly.'
        );
        wp_fts_wc_writer_cleanup(
            $storage,
            $recordingWpdb,
            [array_slice($postIds, 0, 7)],
            $fixturePrefix . 'p',
            $termsTable,
            $postingsTable,
            $documentsTable
        );

        // Execute the typed split as well as merely observing it. All six
        // maximum documents share their identities, so this is a posting-only
        // overflow rather than a disguised dictionary overflow.
        $postingSplitParts = [
            wp_fts_wc_record_writer_transaction(
                $storage,
                $recordingWpdb,
                $fullDocuments,
                '50,001-posting first partition'
            ),
            wp_fts_wc_record_writer_transaction(
                $storage,
                $recordingWpdb,
                [$overflowTail],
                '50,001-posting tail partition'
            ),
        ];
        wp_fts_wc_assert(array_column($postingSplitParts, 'postings') === [49152, 849], 'The posting split did not retain its exact 49,152/849 partition.');
        $postingSplitStored = wp_fts_wc_writer_stored_counts(
            $fixturePrefix . 'p',
            array_slice($postIds, 0, 7),
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        wp_fts_wc_assert($postingSplitStored['documents'] === 7, 'The posting split lost a document.');
        wp_fts_wc_assert($postingSplitStored['postings'] === 50001, 'The posting split lost a posting.');
        wp_fts_wc_assert(
            $postingSplitStored['kinds'] === [
                0 => ['terms' => 4096, 'postings' => 25425],
                1 => ['terms' => 4096, 'postings' => 24576],
            ],
            'The posting split did not retain the expected lexical/surface rows.'
        );
        wp_fts_wc_assert($postingSplitStored['bad_doc_freqs'] === 0, 'The posting split produced incorrect document frequencies.');
        wp_fts_wc_writer_cleanup(
            $storage,
            $recordingWpdb,
            [array_slice($postIds, 0, 6), [$postIds[6]]],
            $fixturePrefix . 'p',
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        unset($postingLexical, $postingSurfaces, $partial848, $partial849, $fullDocuments, $exactTail, $overflowTail);

        // A separate disjoint vocabulary crosses only the batch identity
        // frontier. Its first document is itself the exact combined maximum.
        $identityLexical = wp_fts_wc_writer_frequency_map($fixturePrefix . 'il', 4096);
        $identitySurfaces = wp_fts_wc_writer_frequency_map($fixturePrefix . 'is', 4096);
        $identityFull = wp_fts_wc_writer_document(
            $postIds[3],
            $identityLexical,
            $identitySurfaces,
            'Exact 8,192-identity document'
        );
        $identityTail = wp_fts_wc_writer_document(
            $postIds[4],
            [WP_FTS_TermNamespace::namespace_term('en', $fixturePrefix . 'identity-tail') => 1],
            [],
            '8,193rd identity'
        );
        $identitySplit = wp_fts_wc_writer_split(
            $storage,
            $recordingWpdb,
            [$identityFull, $identityTail],
            'terms',
            8193,
            8193,
            1
        );
        $identityParts = [
            wp_fts_wc_record_writer_transaction(
                $storage,
                $recordingWpdb,
                [$identityFull],
                'exact 8,192-identity document'
            ),
            wp_fts_wc_record_writer_transaction(
                $storage,
                $recordingWpdb,
                [$identityTail],
                '8,193-identity tail partition'
            ),
        ];
        wp_fts_wc_assert(array_column($identityParts, 'postings') === [8192, 1], 'The identity split did not retain all 8,193 postings.');
        wp_fts_wc_assert(array_column($identityParts, 'terms') === [8192, 1], 'The identity split did not retain all 8,193 dictionary identities.');
        $identityStored = wp_fts_wc_writer_stored_counts(
            $fixturePrefix . 'i',
            [$postIds[3], $postIds[4]],
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        wp_fts_wc_assert($identityStored['documents'] === 2, 'The identity split lost a document.');
        wp_fts_wc_assert($identityStored['postings'] === 8193, 'The identity split lost a posting.');
        wp_fts_wc_assert(
            $identityStored['kinds'] === [
                0 => ['terms' => 4097, 'postings' => 4097],
                1 => ['terms' => 4096, 'postings' => 4096],
            ],
            'The identity split did not retain the expected lexical/surface rows.'
        );
        wp_fts_wc_assert($identityStored['bad_doc_freqs'] === 0, 'The identity split produced incorrect document frequencies.');
        wp_fts_wc_writer_cleanup(
            $storage,
            $recordingWpdb,
            [[$postIds[3], $postIds[4]]],
            $fixturePrefix . 'i',
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        unset($identityLexical, $identitySurfaces, $identityFull, $identityTail);

        // Short analyzer tokens do not exercise the resolver packet frontier.
        // Fill every accepted identity byte: a 32-byte canonical language and
        // a 255-byte raw term produce the writer's 288-byte input maximum.
        // The real server must still resolve all 8,192 identities in one
        // statement under the same packet, latency, row, and memory limits.
        $maximumWidthLanguage = WP_FTS_TermNamespace::canonicalize_lang(
            'en-x-abcdefgh-abcdefgh-abcdef-ab',
            'und'
        );
        wp_fts_wc_assert(strlen($maximumWidthLanguage) === 32, 'Maximum-width writer language is not exactly 32 bytes.');
        $maximumWidthLexical = wp_fts_wc_writer_maximum_width_frequency_map($maximumWidthLanguage, 'l');
        $maximumWidthSurfaces = wp_fts_wc_writer_maximum_width_frequency_map($maximumWidthLanguage, 's');
        $maximumWidthLexicalSample = WP_FTS_TermNamespace::split_term((string) array_key_first($maximumWidthLexical));
        wp_fts_wc_assert(
            count($maximumWidthLexical) === 4096
                && count($maximumWidthSurfaces) === 4096
                && array_intersect_key($maximumWidthLexical, $maximumWidthSurfaces) === [],
            'Maximum-width writer fixture does not contain 8,192 distinct valid identities.'
        );
        wp_fts_wc_assert(
            is_array($maximumWidthLexicalSample)
                && str_contains($maximumWidthLexicalSample['term'], "'")
                && str_contains($maximumWidthLexicalSample['term'], "\\")
                && str_contains($maximumWidthLexicalSample['term'], "\x01"),
            'Maximum-width lexical identities do not exercise quote, backslash, and control bytes.'
        );
        $maximumWidthDocument = wp_fts_wc_writer_document(
            $postIds[5],
            $maximumWidthLexical,
            $maximumWidthSurfaces,
            'Maximum-width 8,192-identity resolver'
        );
        $maximumWidthDocument['primary_lang'] = $maximumWidthLanguage;
        $maximumWidthPart = wp_fts_wc_record_writer_transaction(
            $storage,
            $recordingWpdb,
            [$maximumWidthDocument],
            'maximum-width 8,192-identity document',
            true
        );
        $maximumWidthStored = wp_fts_wc_writer_maximum_width_stored_counts(
            $postIds[5],
            $maximumWidthLanguage,
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        wp_fts_wc_assert($maximumWidthPart['terms'] === 8192, 'Maximum-width writer did not resolve all 8,192 identities.');
        wp_fts_wc_assert($maximumWidthPart['postings'] === 8192, 'Maximum-width writer did not insert all 8,192 postings.');
        wp_fts_wc_assert(
            $maximumWidthStored['kinds'] === [
                0 => ['terms' => 4096, 'postings' => 4096, 'minimum_term_bytes' => 255, 'maximum_term_bytes' => 255],
                1 => ['terms' => 4096, 'postings' => 4096, 'minimum_term_bytes' => 255, 'maximum_term_bytes' => 255],
            ],
            'Maximum-width writer did not retain the exact lexical/surface identity boundary.'
        );
        wp_fts_wc_assert($maximumWidthStored['documents'] === 1, 'Maximum-width writer lost its document row.');
        wp_fts_wc_assert($maximumWidthStored['language_bytes'] === 32, 'Maximum-width writer did not retain the 32-byte language partition.');
        $storage->replace_prepared_documents([], [$postIds[5]]);
        $storage->cleanup_empty_terms();
        $maximumWidthCleanup = wp_fts_wc_writer_maximum_width_stored_counts(
            $postIds[5],
            $maximumWidthLanguage,
            $termsTable,
            $postingsTable,
            $documentsTable
        );
        wp_fts_wc_assert(
            $maximumWidthCleanup === ['documents' => 0, 'postings' => 0, 'terms' => 0, 'language_bytes' => 0, 'kinds' => []],
            'Maximum-width writer fixture did not clean up completely.'
        );
        unset($maximumWidthLexical, $maximumWidthSurfaces, $maximumWidthDocument);
        $cleaned = true;

        $allTransactions = [$postingBoundaryPart, ...$postingSplitParts, ...$identityParts, $maximumWidthPart];
        $peakBytes = memory_get_peak_usage(true);
        $rssPeakBytes = wp_fts_wc_rss_bytes('VmHWM');
        wp_fts_wc_assert($peakBytes <= 134217728, "Aggregate writer exceeded the 128 MiB PHP memory contract: {$peakBytes} bytes.");
        wp_fts_wc_assert($rssPeakBytes <= 134217728, "Aggregate writer exceeded the 128 MiB RSS contract: {$rssPeakBytes} bytes.");
        $evidence = [
            'schema' => 'relational-fts-writer-aggregate-v5',
            'status' => 'PASS',
            'phase' => 'writer-aggregate',
            'limits' => [
                'lexical_per_document' => WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_TERMS,
                'surface_per_document' => WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_SURFACES,
                'postings_per_document' => WP_FTS_Relational_Storage::MAX_DOCUMENT_POSTINGS,
                'postings_per_batch' => WP_FTS_Relational_Storage::MAX_BATCH_POSTINGS,
                'identities_per_batch' => WP_FTS_Relational_Storage::MAX_BATCH_TERMS,
            ],
            'document_rejections' => $documentRejections,
            'posting_capacity' => [
                'split' => $postingSplit,
                'exact_boundary_part' => $postingBoundaryPart,
                'exact_boundary_stored' => $postingBoundaryStored,
                'split_parts' => $postingSplitParts,
                'split_stored' => $postingSplitStored,
            ],
            'identity_capacity' => [
                'split' => $identitySplit,
                'parts' => $identityParts,
                'stored' => $identityStored,
            ],
            'maximum_width_identity_capacity' => [
                'language' => $maximumWidthLanguage,
                'language_bytes' => strlen($maximumWidthLanguage),
                'raw_term_bytes' => 255,
                'identity_input_bytes' => 288,
                'distinct_identity_count' => 8192,
                'lexical_quote_backslash_control_bytes' => true,
                'transaction' => $maximumWidthPart,
                'stored' => $maximumWidthStored,
                'cleanup' => $maximumWidthCleanup,
            ],
            'max_transaction_statement_count' => max(array_column($allTransactions, 'statement_count')),
            'max_transaction_statement_bytes' => max(array_column($allTransactions, 'max_statement_bytes')),
            'max_transaction_duration_ms' => max(array_column($allTransactions, 'duration_ms')),
            'php_peak_bytes' => $peakBytes,
            'rss_peak_bytes' => $rssPeakBytes,
        ];

        wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/writer-aggregate.json', $evidence);
        return $evidence;
    } finally {
        if (!$cleaned) {
            try {
                foreach ($postIds as $postId) {
                    $storage->replace_prepared_documents([], [$postId]);
                }
                $storage->cleanup_empty_terms();
            } catch (Throwable) {
                // Preserve the original hard proof failure.
            }
        }
    }
}

/** @return array<string,int> */
function wp_fts_wc_writer_frequency_map(string $prefix, int $count): array
{
    $frequencies = [];
    for ($offset = 0; $offset < $count; $offset++) {
        $term = $prefix . str_pad((string) $offset, 5, '0', STR_PAD_LEFT);
        $frequencies[WP_FTS_TermNamespace::namespace_term('en', $term)] = 1;
    }
    return $frequencies;
}

/** @return array<string,int> */
function wp_fts_wc_writer_maximum_width_frequency_map(string $language, string $kindPrefix): array
{
    wp_fts_wc_assert(strlen($language) === 32, 'Maximum-width identity map requires a 32-byte language.');
    wp_fts_wc_assert(strlen($kindPrefix) === 1, 'Maximum-width identity map requires a one-byte kind prefix.');
    $frequencies = [];
    $fillerPattern = $kindPrefix === 'l' ? "'\\%\x01" : "\"\\_\x02";
    $filler = substr(str_repeat($fillerPattern, 63), 0, 250);
    for ($offset = 0; $offset < 4096; $offset++) {
        $term = $kindPrefix
            . str_pad(dechex($offset), 4, '0', STR_PAD_LEFT)
            . $filler;
        $key = WP_FTS_TermNamespace::namespace_term($language, $term);
        wp_fts_wc_assert(strlen($term) === 255 && strlen($key) === 288, 'Maximum-width identity fixture has the wrong byte width.');
        $frequencies[$key] = 1;
    }

    return $frequencies;
}

/** @param array<string,int> $lexical @param array<string,int> $surfaces @return array<string,mixed> */
function wp_fts_wc_writer_document(int $postId, array $lexical, array $surfaces, string $snippet): array
{
    return [
        'doc_id' => $postId,
        'primary_lang' => 'en',
        'content_hash' => sha1($snippet . '|' . $postId),
        'snippet_text' => $snippet,
        'term_frequencies' => $lexical,
        'surface_frequencies' => $surfaces,
    ];
}

/** @param array<string,mixed> $document @return array<string,mixed> */
function wp_fts_wc_writer_rejection(
    WP_FTS_Relational_Storage $storage,
    WP_FTS_WC_Recording_WPDB $recordingWpdb,
    array $document,
    string $expectedReason
): array {
    $before = count($recordingWpdb->queries);
    $rejection = null;
    try {
        $storage->replace_prepared_documents([$document]);
    } catch (WP_FTS_Prepared_Document_Rejected $error) {
        $rejection = $error;
    }
    $issued = count($recordingWpdb->queries) - $before;
    wp_fts_wc_assert($rejection instanceof WP_FTS_Prepared_Document_Rejected, "Writer did not reject {$expectedReason} poison input.");
    wp_fts_wc_assert($rejection->reason_code === $expectedReason, "Writer rejected {$expectedReason} poison input with the wrong reason.");
    wp_fts_wc_assert($issued === 0, "Writer issued SQL before rejecting {$expectedReason} poison input.");

    return [
        'post_id' => $rejection->post_id,
        'reason_code' => $rejection->reason_code,
        'pre_sql_query_count' => $issued,
    ];
}

/** @param array<int,array<string,mixed>> $documents @return array<string,int|string> */
function wp_fts_wc_writer_split(
    WP_FTS_Relational_Storage $storage,
    WP_FTS_WC_Recording_WPDB $recordingWpdb,
    array $documents,
    string $expectedKind,
    int $expectedPostings,
    int $expectedTerms,
    int $expectedSplitAfter
): array {
    $before = count($recordingWpdb->queries);
    $split = null;
    try {
        $storage->replace_prepared_documents($documents);
    } catch (WP_FTS_Prepared_Batch_Split_Required $error) {
        $split = $error;
    }
    $issued = count($recordingWpdb->queries) - $before;
    wp_fts_wc_assert($split instanceof WP_FTS_Prepared_Batch_Split_Required, "Writer did not signal the {$expectedKind} aggregate split.");
    wp_fts_wc_assert($split->limit_kind === $expectedKind, "Writer signalled the wrong {$expectedKind} aggregate limit.");
    wp_fts_wc_assert($split->document_count === count($documents), "Writer reported the wrong {$expectedKind} split document count.");
    wp_fts_wc_assert($split->posting_count === $expectedPostings, "Writer reported the wrong {$expectedKind} split posting count.");
    wp_fts_wc_assert($split->term_count === $expectedTerms, "Writer reported the wrong {$expectedKind} split identity count.");
    wp_fts_wc_assert($split->posting_limit === 50000, "Writer reported the wrong {$expectedKind} posting limit.");
    wp_fts_wc_assert($split->term_limit === 8192, "Writer reported the wrong {$expectedKind} identity limit.");
    wp_fts_wc_assert($split->split_after_documents === $expectedSplitAfter, "Writer reported the wrong {$expectedKind} split boundary.");
    wp_fts_wc_assert($issued === 0, "Writer signalled the {$expectedKind} aggregate split after SQL began.");

    return [
        'limit_kind' => $split->limit_kind,
        'document_count' => $split->document_count,
        'posting_count' => $split->posting_count,
        'posting_limit' => $split->posting_limit,
        'term_count' => $split->term_count,
        'term_limit' => $split->term_limit,
        'split_after_documents' => $split->split_after_documents,
        'pre_sql_query_count' => $issued,
    ];
}

/** @param array<int,array<string,mixed>> $documents @return array<string,mixed> */
function wp_fts_wc_record_writer_transaction(
    WP_FTS_Relational_Storage $storage,
    WP_FTS_WC_Recording_WPDB $recordingWpdb,
    array $documents,
    string $label,
    bool $captureResolverServerEvent = false
): array {
    global $wpdb;

    $serverThreadId = 0;
    $serverEventBefore = 0;
    if ($captureResolverServerEvent) {
        $serverThreadId = (int) $wpdb->get_var(
            'SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()'
        );
        wp_fts_wc_assert($serverThreadId > 0, "{$label} could not map its writer connection to Performance Schema.");
        $serverEventBefore = (int) $wpdb->get_var($wpdb->prepare(
            'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
            $serverThreadId
        ));
    }
    $before = count($recordingWpdb->queries);
    $queryEventsBefore = count($recordingWpdb->queryEvents);
    $started = hrtime(true);
    $result = $storage->replace_prepared_documents($documents);
    $durationMs = wp_fts_wc_elapsed_ms($started);
    $statements = array_slice($recordingWpdb->queries, $before);
    $queryEvents = array_slice($recordingWpdb->queryEvents, $queryEventsBefore);
    $resolverStatements = array_values(array_filter(
        $statements,
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:resolve-prepared-terms')
    ));
    $resolverServerEvents = [];
    if ($captureResolverServerEvent) {
        $events = $wpdb->get_results($wpdb->prepare(
            'SELECT SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,CREATED_TMP_TABLES,SORT_MERGE_PASSES,TIMER_WAIT
FROM performance_schema.events_statements_history_long
WHERE THREAD_ID=%d AND EVENT_ID>%d
ORDER BY EVENT_ID',
            $serverThreadId,
            $serverEventBefore
        ), ARRAY_A) ?: [];
        foreach ($events as $event) {
            if (!str_starts_with(ltrim((string) ($event['SQL_TEXT'] ?? '')), '/* wp_fts:resolve-prepared-terms */')) {
                continue;
            }
            $resolverServerEvents[] = [
                'duration_ms' => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
                'rows_examined' => max(0, (int) ($event['ROWS_EXAMINED'] ?? 0)),
                'rows_sent' => max(0, (int) ($event['ROWS_SENT'] ?? 0)),
                'created_tmp_disk_tables' => max(0, (int) ($event['CREATED_TMP_DISK_TABLES'] ?? 0)),
                'created_tmp_tables' => max(0, (int) ($event['CREATED_TMP_TABLES'] ?? 0)),
                'sort_merge_passes' => max(0, (int) ($event['SORT_MERGE_PASSES'] ?? 0)),
            ];
        }
    }
    $postingStatements = array_values(array_filter(
        $statements,
        static fn(string $sql): bool => str_starts_with($sql, "INSERT INTO {$wpdb->prefix}fts_postings ")
    ));
    $postingQueryEvents = array_values(array_filter(
        $queryEvents,
        static fn(array $event): bool => str_starts_with($event['sql'], "INSERT INTO {$wpdb->prefix}fts_postings ")
    ));
    $dictionaryIncrements = array_values(array_filter(
        $statements,
        static fn(string $sql): bool => str_contains($sql, '/* wp_fts:dictionary-increment */')
    ));
    $dictionaryDecrements = array_values(array_filter(
        $statements,
        static fn(string $sql): bool => str_contains($sql, '/* wp_fts:dictionary-decrement */')
    ));
    $boundedDeletes = array_values(array_filter(
        $statements,
        static fn(string $sql): bool => str_contains($sql, '/* wp_fts:bounded-index-delete */')
    ));
    $statementCount = count($statements);
    $maxStatementBytes = max(array_map('strlen', $statements));

    wp_fts_wc_assert($statementCount <= 12, "{$label} exceeded 12 total statements.");
    wp_fts_wc_assert($maxStatementBytes <= 4194304, "{$label} exceeded the 4 MiB statement limit.");
    wp_fts_wc_assert($durationMs <= 5000.0, "{$label} exceeded five seconds.");
    wp_fts_wc_assert(count($postingStatements) === 1, "{$label} did not use one posting INSERT.");
    wp_fts_wc_assert(count($postingQueryEvents) === 1, "{$label} did not expose one posting INSERT result.");
    wp_fts_wc_assert(count($dictionaryIncrements) === 1, "{$label} did not use one tagged dictionary increment.");
    wp_fts_wc_assert($dictionaryDecrements === [], "{$label} performed avoidable dictionary retirement for fresh documents.");
    wp_fts_wc_assert($boundedDeletes === [], "{$label} performed avoidable index deletion for fresh documents.");

    $postingValuesShape = wp_fts_wc_posting_values_shape($postingStatements[0]);
    $postingAffectedRows = is_int($postingQueryEvents[0]['result'] ?? null)
        ? (int) $postingQueryEvents[0]['result']
        : -1;
    wp_fts_wc_assert(
        $postingValuesShape['valid_flat_values']
            && $postingValuesShape['tuple_count'] === (int) ($result['postings'] ?? -1)
            && $postingValuesShape['minimum_columns'] === 3
            && $postingValuesShape['maximum_columns'] === 3
            && $postingValuesShape['maximum_parenthesis_depth'] === 1
            && $postingValuesShape['select_count'] === 0
            && $postingValuesShape['union_count'] === 0
            && $postingValuesShape['from_count'] === 0,
        "{$label} posting INSERT was not one flat three-column numeric VALUES relation."
    );
    wp_fts_wc_assert($postingAffectedRows === (int) ($result['postings'] ?? -1), "{$label} posting INSERT affected the wrong row count.");
    $usesBoundedBase64 = false;
    $serializesMetadata = false;
    foreach ($statements as $statement) {
        $usesBoundedBase64 = $usesBoundedBase64 || str_contains($statement, 'FROM_BASE64(');
        $serializesMetadata = $serializesMetadata || str_contains(strtolower($statement), 'metadata_json');
    }
    wp_fts_wc_assert($usesBoundedBase64, "{$label} did not use bounded base64 document SQL.");
    wp_fts_wc_assert(!$serializesMetadata, "{$label} serialized unbounded metadata JSON.");
    if ($captureResolverServerEvent) {
        $resolverBytes = $resolverStatements === [] ? 0 : max(array_map('strlen', $resolverStatements));
        wp_fts_wc_assert(count($resolverStatements) === 1, "{$label} did not use exactly one prepared-term resolver statement.");
        wp_fts_wc_assert($resolverBytes >= 3500000, "{$label} did not exercise the maximum-width resolver packet.");
        wp_fts_wc_assert($resolverBytes <= 4194304, "{$label} resolver exceeded the 4 MiB statement limit.");
        wp_fts_wc_assert(count($resolverServerEvents) === 1, "{$label} did not expose exactly one resolver event in Performance Schema.");
        wp_fts_wc_assert((int) $resolverServerEvents[0]['rows_sent'] === 8192, "{$label} resolver did not return all 8,192 dictionary identities.");
        wp_fts_wc_assert((int) $resolverServerEvents[0]['rows_examined'] <= 65536, "{$label} resolver examined more than 65,536 server rows.");
        wp_fts_wc_assert((int) $resolverServerEvents[0]['created_tmp_disk_tables'] === 0, "{$label} resolver created a disk temporary table.");
        wp_fts_wc_assert((float) $resolverServerEvents[0]['duration_ms'] <= 5000.0, "{$label} resolver exceeded five seconds of server time.");
    }

    $evidence = [
        'documents' => count($documents),
        'terms' => (int) ($result['terms'] ?? -1),
        'postings' => (int) ($result['postings'] ?? -1),
        'statement_count' => $statementCount,
        'max_statement_bytes' => $maxStatementBytes,
        'posting_statement_count' => count($postingStatements),
        'posting_statement_bytes' => strlen($postingStatements[0]),
        'posting_affected_rows' => $postingAffectedRows,
        'posting_values_shape' => $postingValuesShape,
        'dictionary_increment_statement_count' => count($dictionaryIncrements),
        'dictionary_increment_statement_bytes' => $dictionaryIncrements === [] ? 0 : max(array_map('strlen', $dictionaryIncrements)),
        'dictionary_decrement_statement_count' => count($dictionaryDecrements),
        'bounded_delete_statement_count' => count($boundedDeletes),
        'fresh_document_retirement_skipped' => $dictionaryDecrements === [] && $boundedDeletes === [],
        'resolver_statement_count' => count($resolverStatements),
        'resolver_statement_bytes' => $resolverStatements === [] ? 0 : max(array_map('strlen', $resolverStatements)),
        'resolver_server_events' => $resolverServerEvents,
        'duration_ms' => $durationMs,
    ];

    // The proof needs metrics, not retained multi-megabyte SQL strings.
    $recordingWpdb->queries = [];
    $recordingWpdb->queryEvents = [];
    return $evidence;
}

/** @param int[] $postIds @return array<string,mixed> */
function wp_fts_wc_writer_stored_counts(
    string $termPrefix,
    array $postIds,
    string $termsTable,
    string $postingsTable,
    string $documentsTable
): array {
    global $wpdb;

    $postIds = array_values(array_map('intval', $postIds));
    $idSql = implode(',', $postIds);
    $like = $wpdb->esc_like($termPrefix) . '%';
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT t.kind, COUNT(DISTINCT t.term_id) AS terms, COUNT(p.post_id) AS postings
FROM `{$termsTable}` t
INNER JOIN `{$postingsTable}` p ON p.term_id = t.term_id
WHERE t.lang = %s AND t.term LIKE %s AND p.post_id IN ({$idSql})
GROUP BY t.kind
ORDER BY t.kind",
        'en',
        $like
    ), ARRAY_A);
    wp_fts_wc_assert(is_array($rows), 'Could not count writer rows by kind: ' . (string) $wpdb->last_error);
    $kinds = [];
    foreach ($rows as $row) {
        $kinds[(int) $row['kind']] = [
            'terms' => (int) $row['terms'],
            'postings' => (int) $row['postings'],
        ];
    }
    $badDocumentFrequencies = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*)
FROM `{$termsTable}` t
INNER JOIN (
    SELECT p.term_id, COUNT(*) AS physical_rows
    FROM `{$postingsTable}` p
    WHERE p.post_id IN ({$idSql})
    GROUP BY p.term_id
) physical ON physical.term_id = t.term_id
WHERE t.lang = %s AND t.term LIKE %s AND t.doc_freq <> physical.physical_rows",
        'en',
        $like
    ));
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not verify writer document frequencies: ' . (string) $wpdb->last_error);

    return [
        'documents' => (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$documentsTable}` WHERE post_id IN ({$idSql})"),
        'postings' => (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$postingsTable}` WHERE post_id IN ({$idSql})"),
        'terms' => array_sum(array_column($kinds, 'terms')),
        'kinds' => $kinds,
        'bad_doc_freqs' => $badDocumentFrequencies,
        'snippet' => (string) $wpdb->get_var("SELECT snippet_text FROM `{$documentsTable}` WHERE post_id = {$postIds[0]}"),
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_writer_maximum_width_stored_counts(
    int $postId,
    string $language,
    string $termsTable,
    string $postingsTable,
    string $documentsTable
): array {
    global $wpdb;

    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT t.kind,
                COUNT(DISTINCT t.term_id) AS terms,
                COUNT(p.post_id) AS postings,
                MIN(OCTET_LENGTH(t.term)) AS minimum_term_bytes,
                MAX(OCTET_LENGTH(t.term)) AS maximum_term_bytes
FROM `{$postingsTable}` p
INNER JOIN `{$termsTable}` t ON t.term_id=p.term_id
WHERE p.post_id=%d AND t.lang=%s
GROUP BY t.kind
ORDER BY t.kind",
        $postId,
        $language
    ), ARRAY_A);
    wp_fts_wc_assert(is_array($rows) && trim((string) $wpdb->last_error) === '', 'Could not count maximum-width writer rows.');
    $kinds = [];
    foreach ($rows as $row) {
        $kinds[(int) $row['kind']] = [
            'terms' => (int) $row['terms'],
            'postings' => (int) $row['postings'],
            'minimum_term_bytes' => (int) $row['minimum_term_bytes'],
            'maximum_term_bytes' => (int) $row['maximum_term_bytes'],
        ];
    }
    $documents = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$documentsTable}` WHERE post_id=%d", $postId),
        'maximum-width writer documents'
    );
    $postings = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$postingsTable}` WHERE post_id=%d", $postId),
        'maximum-width writer postings'
    );
    $terms = array_sum(array_column($kinds, 'terms'));

    return [
        'documents' => $documents,
        'postings' => $postings,
        'terms' => $terms,
        'language_bytes' => $terms > 0 ? strlen($language) : 0,
        'kinds' => $kinds,
    ];
}

/** @param array<int,int[]> $postIdPartitions */
function wp_fts_wc_writer_cleanup(
    WP_FTS_Relational_Storage $storage,
    WP_FTS_WC_Recording_WPDB $recordingWpdb,
    array $postIdPartitions,
    string $termPrefix,
    string $termsTable,
    string $postingsTable,
    string $documentsTable
): void {
    global $wpdb;

    $postIds = [];
    foreach ($postIdPartitions as $partition) {
        $storage->replace_prepared_documents([], $partition);
        array_push($postIds, ...$partition);
    }
    $storage->cleanup_empty_terms();
    $recordingWpdb->queries = [];
    $recordingWpdb->queryEvents = [];
    $idSql = implode(',', array_map('intval', $postIds));
    $like = $wpdb->esc_like($termPrefix) . '%';
    wp_fts_wc_assert((int) $wpdb->get_var("SELECT COUNT(*) FROM `{$documentsTable}` WHERE post_id IN ({$idSql})") === 0, 'Writer cleanup left documents behind.');
    wp_fts_wc_assert((int) $wpdb->get_var("SELECT COUNT(*) FROM `{$postingsTable}` WHERE post_id IN ({$idSql})") === 0, 'Writer cleanup left postings behind.');
    wp_fts_wc_assert((int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM `{$termsTable}` WHERE lang = %s AND term LIKE %s",
        'en',
        $like
    )) === 0, 'Writer cleanup left dictionary identities behind.');
}

/** Seed twenty near-limit canonical rows in a dedicated process. */
function wp_fts_wc_max_valid_seed(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $preliminary = wp_fts_wc_preliminary_report_binding();
    $sourceBinding = wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256']);
    $processIdentity = wp_fts_wc_process_identity();
    wp_fts_wc_assert(wp_fts_wc_process_identity_valid($processIdentity), 'Near-limit seed requires an exact Linux process identity.');

    $contentBytes = 1900000;
    $visibleContent = '<p>maxsizeprobe</p>';
    $commentOpen = '<!--';
    $commentClose = '-->';
    $content = $visibleContent
        . $commentOpen
        . str_repeat('x', $contentBytes - strlen($visibleContent . $commentOpen . $commentClose))
        . $commentClose;
    wp_fts_wc_assert(strlen($content) === $contentBytes, 'Near-limit canonical source did not reach its exact byte boundary.');
    $contentHash = hash('sha256', $content);
    wp_fts_wc_assert($contentHash === wp_fts_wc_max_valid_content_sha256(), 'Near-limit canonical source changed from the independently reconstructed acceptance payload.');
    $ids = [];
    for ($index = 0; $index < 20; $index++) {
        $date = gmdate('Y-m-d H:i:s', 1800000000 + $index);
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO {$wpdb->posts}
(post_author,post_date,post_date_gmt,post_content,post_title,post_excerpt,post_status,comment_status,ping_status,post_password,post_name,post_modified,post_modified_gmt,post_type)
VALUES (%d,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
            1,
            $date,
            $date,
            $content,
            "Maximum valid FTS transport maxsizeprobe {$index}",
            '',
            'publish',
            'closed',
            'closed',
            '',
            'wp-fts-max-valid-' . $index,
            $date,
            $date,
            'post'
        ));
        wp_fts_wc_assert($inserted === 1, 'Could not insert a near-limit canonical post: ' . (string) $wpdb->last_error);
        $ids[] = (int) $wpdb->insert_id;
    }

    $seed = [
        'schema' => 'relational-fts-max-valid-seed-v1',
        'status' => 'PASS',
        ...$sourceBinding,
        'process_identity' => $processIdentity,
        'post_ids' => $ids,
        'content_bytes' => $contentBytes,
        'content_sha256' => $contentHash,
    ];
    $seed['seed_sha256'] = wp_fts_wc_canonical_hash($seed);
    wp_fts_wc_assert(
        add_option(WP_FTS_WC_MAX_VALID_SEED_OPTION, $seed, '', false),
        'Near-limit seed handoff already exists.'
    );
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/max-valid-seed.json', $seed);

    return $seed;
}

/** Index the near-limit seed through measured passes in a fresh process. */
function wp_fts_wc_max_valid_setup(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $seed = get_option(WP_FTS_WC_MAX_VALID_SEED_OPTION, null);
    wp_fts_wc_assert(is_array($seed), 'Near-limit worker requires the seed handoff.');
    $sourceBinding = wp_fts_wc_artifact_source_binding(
        $manifest,
        is_string($seed['validation_evidence_sha256'] ?? null) ? $seed['validation_evidence_sha256'] : ''
    );
    unset($manifest);
    $processIdentity = wp_fts_wc_process_identity();
    wp_fts_wc_assert(wp_fts_wc_process_identity_valid($processIdentity), 'Near-limit setup requires an exact Linux process identity.');

    $seedHashInput = $seed;
    $seedRecordedHash = $seedHashInput['seed_sha256'] ?? null;
    unset($seedHashInput['seed_sha256']);
    $seedProcessIdentity = is_array($seed['process_identity'] ?? null) ? $seed['process_identity'] : [];
    $ids = is_array($seed['post_ids'] ?? null) ? array_values($seed['post_ids']) : [];
    $contentBytes = $seed['content_bytes'] ?? null;
    $contentHash = $seed['content_sha256'] ?? null;
    $seedValid = array_keys($seed) === [
        'schema', 'status',
        'source_sha', 'zip_sha256', 'harness_sha256', 'lane_id', 'engine', 'profile', 'manifest_sha256', 'validation_evidence_sha256',
        'process_identity', 'post_ids', 'content_bytes', 'content_sha256', 'seed_sha256',
    ]
        && ($seed['schema'] ?? null) === 'relational-fts-max-valid-seed-v1'
        && ($seed['status'] ?? null) === 'PASS'
        && array_intersect_key($seed, $sourceBinding) === $sourceBinding
        && wp_fts_wc_process_identity_valid($seedProcessIdentity)
        && ($seedProcessIdentity['sha256'] ?? null) !== ($processIdentity['sha256'] ?? null)
        && count($ids) === 20
        && count(array_filter($ids, static fn(mixed $id): bool => is_int($id) && $id > 0)) === 20
        && count(array_unique($ids)) === 20
        && $contentBytes === 1900000
        && $contentHash === wp_fts_wc_max_valid_content_sha256()
        && wp_fts_wc_is_lowercase_sha256($seedRecordedHash)
        && hash_equals(wp_fts_wc_canonical_hash($seedHashInput), (string) $seedRecordedHash);
    wp_fts_wc_assert($seedValid, 'Near-limit seed handoff is incomplete or does not match this worker.');

    $idSql = implode(',', array_map('intval', $ids));
    $seedRows = $wpdb->get_results(
        "SELECT ID,OCTET_LENGTH(post_content) content_bytes,SHA2(post_content,256) content_sha256
FROM {$wpdb->posts}
WHERE ID IN ({$idSql})
ORDER BY ID",
        ARRAY_A
    );
    wp_fts_wc_assert(is_array($seedRows) && count($seedRows) === 20, 'Near-limit worker could not find every seeded post.');
    foreach ($seedRows as $seedRow) {
        wp_fts_wc_assert(
            is_array($seedRow)
                && isset($seedRow['ID'])
                && wp_fts_wc_is_ascii_digits((string) $seedRow['ID'])
                && in_array((int) $seedRow['ID'], $ids, true)
                && isset($seedRow['content_bytes'])
                && wp_fts_wc_is_ascii_digits((string) $seedRow['content_bytes'])
                && (int) $seedRow['content_bytes'] === $contentBytes
                && isset($seedRow['content_sha256'])
                && hash_equals($contentHash, strtolower((string) $seedRow['content_sha256'])),
            'Near-limit worker found a changed seeded post.'
        );
    }
    wp_fts_wc_assert(delete_option(WP_FTS_WC_MAX_VALID_SEED_OPTION), 'Near-limit worker could not consume the seed handoff.');

    unset($seed, $seedHashInput, $seedRows);
    $wpdb->flush();
    gc_collect_cycles();

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $unrelatedWorkBefore = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id NOT IN ({$idSql})",
        'near-limit unrelated work before setup'
    );
    $backlogDelaySeconds = 86400;
    // Validation deliberately retains the dirty-head backlog. Delay that work
    // for this focused phase, then reverse the exact offset before continuing.
    $deferredWork = $wpdb->query(
        "UPDATE `{$work}` SET available_at=available_at+{$backlogDelaySeconds}
WHERE kind='post' AND post_id NOT IN ({$idSql})"
    );
    wp_fts_wc_assert(
        is_int($deferredWork)
            && $deferredWork === $unrelatedWorkBefore
            && trim((string) $wpdb->last_error) === '',
        'Near-limit setup could not defer the retained dirty-head backlog.'
    );
    $queue = new WP_FTS_Index_Queue($wpdb);
    $enqueueStarted = hrtime(true);
    $enqueue = wp_fts_wc_record_queries(static fn() => $queue->enqueue_many($ids));
    $enqueueDuration = wp_fts_wc_elapsed_ms($enqueueStarted);
    $enqueueBytes = array_map('strlen', array_values($enqueue['queries']));
    $enqueueMaxBytes = max($enqueueBytes ?: [0]);
    wp_fts_wc_assert(count($enqueue['queries']) === 1, 'Near-limit posts were not queued with one bounded multi-row UPSERT.');
    $passes = [];
    $phpLifetimePeak = memory_get_peak_usage(true);
    for ($pass = 0; $pass < 100; $pass++) {
        if (wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE post_id IN ({$idSql})", 'near-limit setup work') === 0) {
            break;
        }
        gc_collect_cycles();
        $phpLifetimePeak = max($phpLifetimePeak, memory_get_peak_usage(true));
        wp_fts_wc_reset_php_peak_usage();
        $phpUsageBefore = memory_get_usage(true);
        $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
        $started = hrtime(true);
        $recorded = wp_fts_wc_record_queries(static fn(): array => WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-max-valid',
            'batch_size' => 100,
            'time_budget' => 20.0,
        ]));
        $duration = wp_fts_wc_elapsed_ms($started);
        $summary = is_array($recorded['result'] ?? null) ? $recorded['result'] : [];
        $queries = is_array($recorded['queries'] ?? null) ? array_values($recorded['queries']) : [];
        $statementBytes = array_map(static fn(string $sql): int => strlen($sql), $queries);
        $statementHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $queries);
        $statementRoles = wp_fts_wc_worker_statement_roles($queries);
        $phpPeakAfterReset = memory_get_peak_usage(true);
        $phpLifetimePeak = max($phpLifetimePeak, $phpPeakAfterReset);
        $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
        $passes[] = [
            'duration_ms' => $duration,
            'indexed' => (int) ($summary['indexed'] ?? 0),
            'failures' => (int) ($summary['last_batch_failures'] ?? 0),
            'skipped_locked' => !empty($summary['skipped_locked']),
            'statement_count' => count($queries),
            'statement_bytes' => $statementBytes,
            'statement_sha256' => $statementHashes,
            'max_statement_bytes' => max($statementBytes ?: [0]),
            'statement_roles' => $statementRoles['roles'],
            'unknown_statement_count' => count($statementRoles['unknown']),
            'php_usage_before_bytes' => $phpUsageBefore,
            'php_peak_after_reset_bytes' => $phpPeakAfterReset,
            'php_peak_delta_bytes' => max(0, $phpPeakAfterReset - $phpUsageBefore),
            'rss_before_bytes' => $rssBefore,
            'rss_peak_after_bytes' => $rssPeakAfter,
            'rss_peak_delta_bytes' => max(0, $rssPeakAfter - $rssBefore),
        ];
        wp_fts_wc_assert(empty($summary['skipped_locked']), 'Near-limit setup lost the only worker lease.');
        wp_fts_wc_assert(
            (int) ($summary['last_batch_failures'] ?? 0) === 0,
            'Near-limit setup produced a worker failure: '
                . (string) ($summary['last_error_class'] ?? '')
                . ': '
                . (string) ($summary['last_error_message'] ?? '')
        );
        unset($recorded, $summary, $queries, $statementBytes, $statementHashes, $statementRoles);
    }
    $remaining = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE post_id IN ({$idSql})", 'near-limit setup final work');
    $restoredWork = $wpdb->query(
        "UPDATE `{$work}` SET available_at=available_at-{$backlogDelaySeconds}
WHERE kind='post' AND post_id NOT IN ({$idSql})"
    );
    wp_fts_wc_assert(
        is_int($restoredWork)
            && $restoredWork === $unrelatedWorkBefore
            && trim((string) $wpdb->last_error) === '',
        'Near-limit setup could not restore the retained dirty-head backlog.'
    );
    $unrelatedWorkAfter = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id NOT IN ({$idSql})",
        'near-limit unrelated work after setup'
    );
    wp_fts_wc_assert($unrelatedWorkAfter === $unrelatedWorkBefore, 'Near-limit setup consumed unrelated durable work.');
    wp_fts_wc_assert(
        $remaining === 0,
        'Near-limit posts did not drain from durable work: remaining=' . $remaining
            . ', passes=' . count($passes)
            . ', indexed=' . array_sum(array_column($passes, 'indexed')) . '.'
    );
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $indexed = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documents}` WHERE post_id IN ({$idSql})", 'near-limit indexed documents');
    wp_fts_wc_assert($indexed === 20, 'Near-limit posts were not all indexed.');
    $workerStatementCountMax = max(array_column($passes, 'statement_count') ?: [0]);
    $workerStatementBytesMax = max(array_column($passes, 'max_statement_bytes') ?: [0]);
    $workerDurationMax = max(array_column($passes, 'duration_ms') ?: [0.0]);
    $workerPhpDeltaMax = max(array_column($passes, 'php_peak_delta_bytes') ?: [0]);
    $workerRssDeltaMax = max(array_column($passes, 'rss_peak_delta_bytes') ?: [0]);
    $workerPhpPeakMax = max(array_column($passes, 'php_peak_after_reset_bytes') ?: [0]);
    $workerRssPeakMax = max(array_column($passes, 'rss_peak_after_bytes') ?: [0]);
    $phpPeak = max($phpLifetimePeak, memory_get_peak_usage(true));
    $rssPeak = wp_fts_wc_rss_bytes('VmHWM');
    $workerIndexed = array_sum(array_column($passes, 'indexed'));
    $unknownStatements = array_sum(array_column($passes, 'unknown_statement_count'));
    $passCount = count($passes);
    $sourceBindingValid = array_keys($sourceBinding) === ['source_sha', 'zip_sha256', 'harness_sha256', 'lane_id', 'engine', 'profile', 'manifest_sha256', 'validation_evidence_sha256']
        && strlen($sourceBinding['source_sha']) === 40
        && wp_fts_wc_is_ascii_hex($sourceBinding['source_sha'])
        && wp_fts_wc_is_lowercase_sha256($sourceBinding['zip_sha256'])
        && wp_fts_wc_is_lowercase_sha256($sourceBinding['harness_sha256'])
        && wp_fts_wc_is_lowercase_sha256($sourceBinding['manifest_sha256'])
        && wp_fts_wc_is_lowercase_sha256($sourceBinding['validation_evidence_sha256'])
        && $sourceBinding['lane_id'] !== ''
        && $sourceBinding['engine'] !== ''
        && $sourceBinding['profile'] !== '';
    $gates = [
        wp_fts_wc_gate('max_valid_setup_source_binding', 'complete source binding and distinct Linux seed/worker processes', ['binding' => $sourceBinding, 'seed_process_identity' => $seedProcessIdentity, 'process_identity' => $processIdentity], $sourceBindingValid && wp_fts_wc_process_identity_valid($seedProcessIdentity) && wp_fts_wc_process_identity_valid($processIdentity) && ($seedProcessIdentity['sha256'] ?? null) !== ($processIdentity['sha256'] ?? null)),
        wp_fts_wc_gate('max_valid_setup_enqueue_bound', ['statements' => 1, 'max_bytes' => '<= 1048576', 'duration_ms' => '<= 5000'], ['statements' => count($enqueue['queries']), 'max_bytes' => $enqueueMaxBytes, 'duration_ms' => $enqueueDuration], count($enqueue['queries']) === 1 && $enqueueMaxBytes > 0 && $enqueueMaxBytes <= 1048576 && $enqueueDuration >= 0.0 && $enqueueDuration <= 5000.0),
        wp_fts_wc_gate('max_valid_setup_worker_progress', ['indexed' => 20, 'passes' => '1..100', 'failures' => 0, 'skipped_locked' => false], ['indexed' => $workerIndexed, 'passes' => $passCount, 'failures' => array_sum(array_column($passes, 'failures')), 'skipped_locked' => count(array_filter(array_column($passes, 'skipped_locked')))], $workerIndexed === 20 && $passCount > 0 && $passCount <= 100 && array_sum(array_column($passes, 'failures')) === 0 && count(array_filter(array_column($passes, 'skipped_locked'))) === 0),
        wp_fts_wc_gate('max_valid_setup_worker_statement_bound', ['per_pass' => '<= 20', 'unknown' => 0], ['max' => $workerStatementCountMax, 'unknown' => $unknownStatements], $workerStatementCountMax > 0 && $workerStatementCountMax <= 20 && $unknownStatements === 0),
        wp_fts_wc_gate('max_valid_setup_worker_sql_bound', '<= 4194304', $workerStatementBytesMax, $workerStatementBytesMax > 0 && $workerStatementBytesMax <= 4194304),
        wp_fts_wc_gate('max_valid_setup_worker_duration_bound', '<= 30000 ms', $workerDurationMax, $workerDurationMax >= 0.0 && $workerDurationMax <= 30000.0),
        wp_fts_wc_gate('max_valid_setup_worker_memory_bound', ['delta' => '<= 33554432', 'absolute' => '<= 134217728', 'aggregate_dominates_passes' => true], ['php_delta' => $workerPhpDeltaMax, 'rss_delta' => $workerRssDeltaMax, 'php_peak' => $phpPeak, 'rss_peak' => $rssPeak, 'max_pass_php_peak' => $workerPhpPeakMax, 'max_pass_rss_peak' => $workerRssPeakMax], $workerPhpDeltaMax <= 33554432 && $workerRssDeltaMax <= 33554432 && $phpPeak >= $workerPhpPeakMax && $phpPeak <= 134217728 && $rssPeak >= $workerRssPeakMax && $rssPeak <= 134217728),
    ];

    $evidence = [
        'schema' => 'relational-fts-max-valid-setup-v3',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'max-valid-setup',
        ...$sourceBinding,
        'seed_process_identity' => $seedProcessIdentity,
        'seed_sha256' => $seedRecordedHash,
        'process_identity' => $processIdentity,
        'measurement_method' => 'fresh_phase_process_per_pass_php_peak_reset_conservative_rss_hwm',
        'php_peak_delta_authoritative' => true,
        'rss_peak_delta_authoritative' => true,
        'post_ids' => $ids,
        'content_bytes' => $contentBytes,
        'content_sha256' => $contentHash,
        'enqueue_statements' => count($enqueue['queries']),
        'enqueue_max_statement_bytes' => $enqueueMaxBytes,
        'enqueue_duration_ms' => $enqueueDuration,
        'worker_passes' => $passes,
        'worker_statement_count_max' => $workerStatementCountMax,
        'worker_max_statement_bytes' => $workerStatementBytesMax,
        'worker_duration_ms_max' => $workerDurationMax,
        'worker_php_peak_delta_bytes' => $workerPhpDeltaMax,
        'worker_rss_peak_delta_bytes' => $workerRssDeltaMax,
        'php_peak_bytes' => $phpPeak,
        'rss_peak_bytes' => $rssPeak,
        'indexed' => $indexed,
        'gates' => $gates,
    ];
    $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/max-valid-setup.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Near-limit setup exceeded a hard worker bound: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return $evidence;
}

/** Reconstruct the accepted 1.9-MiB source without trusting its artifact. */
function wp_fts_wc_max_valid_content_sha256(): string
{
    $contentBytes = 1900000;
    $visibleContent = '<p>maxsizeprobe</p>';
    $commentOpen = '<!--';
    $commentClose = '-->';

    return hash('sha256', $visibleContent
        . $commentOpen
        . str_repeat('x', $contentBytes - strlen($visibleContent . $commentOpen . $commentClose))
        . $commentClose);
}

/**
 * Exercise the actual front-end adapter in a fresh process over max-valid LOBs.
 *
 * The 4 MiB canonical transport must shorten the page rather than truncate a
 * post. Signed cursors must still reach all twenty exact results in order.
 */
function wp_fts_wc_max_valid_search(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $manifest = wp_fts_wc_manifest();
    $setup = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/max-valid-setup.json');
    $sourceBinding = wp_fts_wc_artifact_source_binding(
        $manifest,
        is_string($setup['validation_evidence_sha256'] ?? null) ? $setup['validation_evidence_sha256'] : ''
    );
    unset($manifest);
    $processIdentity = wp_fts_wc_process_identity();
    $expectedIds = array_reverse(array_map('intval', $setup['post_ids'] ?? []));
    wp_fts_wc_assert(count($expectedIds) === 20 && count(array_unique($expectedIds)) === 20, 'Near-limit setup evidence is incomplete.');
    $expectedBytes = (int) ($setup['content_bytes'] ?? 0);
    $expectedHash = (string) ($setup['content_sha256'] ?? '');
    wp_fts_wc_assert($expectedBytes === 1900000 && $expectedHash === wp_fts_wc_max_valid_content_sha256(), 'Near-limit search setup does not describe the exact accepted canonical payload.');
    $forceFrontend = static fn(mixed $enabled, mixed ...$unused): bool => true;
    add_filter(WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER, $forceFrontend, PHP_INT_MAX, 2);
    $seen = [];
    $pages = [];
    $cursor = null;
    gc_collect_cycles();
    $processMemoryBefore = memory_get_usage(true);
    $phpLifetimePeakBeforeReset = memory_get_peak_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    try {
        for ($page = 1; $page <= 20; $page++) {
            $query = new class($page, $cursor) {
                /** @var array<string,mixed> */
                public array $query_vars;
                public int $found_posts = 0;
                public int $max_num_pages = 0;
                /** Model the exact adjacent-page WP_Query state consumed by the adapter. */
                public function __construct(int $page, ?string $cursor)
                {
                    $this->query_vars = [
                        's' => 'maxsizeprobe',
                        'posts_per_page' => 20,
                        'post_type' => 'post',
                        'post_status' => 'publish',
                        'paged' => $page,
                        'suppress_filters' => false,
                    ];
                    if ($cursor !== null) {
                        $this->query_vars['wp_fts_cursor'] = $cursor;
                        $this->query_vars['wp_fts_cursor_direction'] = 'after';
                    }
                }
                /** Match WP_Query's caller-supplied default semantics. */
                public function get(string $key, mixed $default = null): mixed { return $this->query_vars[$key] ?? $default; }
                /** Retain the signed cursor state written by the adapter. */
                public function set(string $key, mixed $value): void { $this->query_vars[$key] = $value; }
                /** Keep the fixture on the public-search ownership path. */
                public function is_search(): bool { return true; }
                /** Keep the fixture on the main-query ownership path. */
                public function is_main_query(): bool { return true; }
            };
            // A reset must not erase a peak reached while constructing a later
            // page request; retain the lifetime maximum immediately beforehand.
            $phpLifetimePeakBeforeReset = max($phpLifetimePeakBeforeReset, memory_get_peak_usage(true));
            wp_fts_wc_reset_php_peak_usage();
            gc_collect_cycles();
            $pageMemoryBefore = memory_get_usage(true);
            $pageRssBefore = wp_fts_wc_rss_bytes('VmRSS');
            $recorded = wp_fts_wc_record_queries(static function () use ($query): mixed {
                WP_FTS_Plugin::prepare_frontend_search_query($query);
                return WP_FTS_Plugin::replace_frontend_search_posts(null, $query);
            });
            $posts = is_array($recorded['result']) ? $recorded['result'] : [];
            wp_fts_wc_assert($posts !== [], 'Near-limit front-end cursor ended before all results were reached.');
            $ids = [];
            $results = [];
            foreach ($posts as $post) {
                wp_fts_wc_assert(is_object($post), 'Near-limit front-end result is not a post object.');
                $id = (int) ($post->ID ?? 0);
                $body = (string) ($post->post_content ?? '');
                $bodyBytes = strlen($body);
                $bodyHash = hash('sha256', $body);
                wp_fts_wc_assert($bodyBytes === $expectedBytes, 'Near-limit canonical content was truncated.');
                wp_fts_wc_assert(hash_equals($expectedHash, $bodyHash), 'Near-limit canonical content changed during transport.');
                wp_fts_wc_assert(!isset($seen[$id]), 'Near-limit cursor returned a duplicate post.');
                $seen[$id] = true;
                $ids[] = $id;
                $results[] = [
                    'post_id' => $id,
                    'content_bytes' => $bodyBytes,
                    'content_sha256' => $bodyHash,
                ];
            }
            $queries = array_values($recorded['queries']);
            $shape = [
                'plan' => count(array_filter($queries, static fn(string $sql): bool => str_contains($sql, 'wp_fts:plan'))),
                'rank' => count(array_filter($queries, static fn(string $sql): bool => str_contains($sql, 'wp_fts:rank'))),
                'hydrate' => count(array_filter($queries, static fn(string $sql): bool => str_contains($sql, 'wp_fts:hydrate'))),
            ];
            wp_fts_wc_assert(count($queries) === 3 && $shape === ['plan' => 1, 'rank' => 1, 'hydrate' => 1], 'Near-limit front-end page did not use exactly plan/rank/hydrate.');
            wp_fts_wc_assert(count($ids) <= 2, 'Near-limit page exceeded the 4 MiB canonical transport prefix.');
            $cursorValue = $query->get('wp_fts_next_cursor');
            $cursor = is_scalar($cursorValue) && trim((string) $cursorValue) !== '' ? (string) $cursorValue : null;
            $pageMemoryPhasePeak = memory_get_peak_usage(true);
            $pageRssAfter = wp_fts_wc_rss_bytes('VmRSS');
            $pages[] = [
                'page' => $page,
                'ids' => $ids,
                'results' => $results,
                'query_count' => count($queries),
                'shape' => $shape,
                'memory_before_bytes' => $pageMemoryBefore,
                'memory_peak_delta_bytes' => max(0, $pageMemoryPhasePeak - $pageMemoryBefore),
                'memory_phase_peak_bytes' => $pageMemoryPhasePeak,
                'rss_before_bytes' => $pageRssBefore,
                'rss_after_bytes' => $pageRssAfter,
                'rss_delta_bytes' => max(0, $pageRssAfter - $pageRssBefore),
                'has_more' => $cursor !== null,
            ];
            unset($posts, $recorded, $query);
            gc_collect_cycles();
            if ($cursor === null) {
                break;
            }
        }
    } finally {
        remove_filter(WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER, $forceFrontend, PHP_INT_MAX);
    }
    $actualIds = array_map('intval', array_keys($seen));
    wp_fts_wc_assert($actualIds === $expectedIds, 'Near-limit cursor membership or order differs from the canonical 20-row result.');
    $pageMeasurementsValid = $pages !== [];
    $retainedResults = [];
    foreach ($pages as $pageEvidence) {
        $pageResults = is_array($pageEvidence['results'] ?? null) ? array_values($pageEvidence['results']) : [];
        array_push($retainedResults, ...$pageResults);
        $pageMeasurementsValid = $pageMeasurementsValid
            && is_int($pageEvidence['memory_before_bytes'] ?? null)
            && is_int($pageEvidence['memory_phase_peak_bytes'] ?? null)
            && is_int($pageEvidence['memory_peak_delta_bytes'] ?? null)
            && $pageEvidence['memory_before_bytes'] > 0
            && $pageEvidence['memory_phase_peak_bytes'] >= $pageEvidence['memory_before_bytes']
            && $pageEvidence['memory_peak_delta_bytes'] === max(0, $pageEvidence['memory_phase_peak_bytes'] - $pageEvidence['memory_before_bytes'])
            && $pageEvidence['memory_peak_delta_bytes'] <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES
            && is_int($pageEvidence['rss_before_bytes'] ?? null)
            && is_int($pageEvidence['rss_after_bytes'] ?? null)
            && is_int($pageEvidence['rss_delta_bytes'] ?? null)
            && $pageEvidence['rss_before_bytes'] > 0
            && $pageEvidence['rss_after_bytes'] > 0
            && $pageEvidence['rss_delta_bytes'] === max(0, $pageEvidence['rss_after_bytes'] - $pageEvidence['rss_before_bytes'])
            && $pageEvidence['rss_delta_bytes'] <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES;
    }
    $phpPhasePeakAfter = max(array_column($pages, 'memory_phase_peak_bytes') ?: [PHP_INT_MAX]);
    $phpPeakBytes = max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter);
    $phpPeakDelta = max(0, $phpPhasePeakAfter - $processMemoryBefore);
    $maxRss = max(array_column($pages, 'rss_delta_bytes') ?: [PHP_INT_MAX]);
    $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
    $rssPeakDelta = max(0, $rssPeakAfter - $rssBefore);
    $retainedContentValid = count($retainedResults) === 20
        && count(array_filter($retainedResults, static fn(mixed $result): bool => is_array($result)
            && array_keys($result) === ['post_id', 'content_bytes', 'content_sha256']
            && is_int($result['post_id'] ?? null)
            && $result['post_id'] > 0
            && ($result['content_bytes'] ?? null) === 1900000
            && ($result['content_sha256'] ?? null) === wp_fts_wc_max_valid_content_sha256())) === 20;
    $setupSourceBinding = array_intersect_key($setup, $sourceBinding);
    $gates = [
        wp_fts_wc_gate('max_valid_frontend_source_binding', $sourceBinding, $setupSourceBinding, $sourceBinding === $setupSourceBinding),
        wp_fts_wc_gate('max_valid_frontend_validation_binding', $setup['validation_evidence_sha256'] ?? null, $sourceBinding['validation_evidence_sha256'], is_string($setup['validation_evidence_sha256'] ?? null) && hash_equals($setup['validation_evidence_sha256'], $sourceBinding['validation_evidence_sha256'])),
        wp_fts_wc_gate('max_valid_frontend_fresh_process_identity', 'positive pid/start ticks with a bound Linux boot identity', $processIdentity, wp_fts_wc_process_identity_valid($processIdentity)),
        wp_fts_wc_gate('max_valid_frontend_ids', $expectedIds, $actualIds, $actualIds === $expectedIds),
        wp_fts_wc_gate('max_valid_frontend_content', ['rows' => 20, 'bytes' => 1900000, 'sha256' => wp_fts_wc_max_valid_content_sha256()], ['rows' => count($retainedResults), 'sha256' => wp_fts_wc_canonical_hash($retainedResults)], $retainedContentValid),
        wp_fts_wc_gate('max_valid_frontend_pages', 10, count($pages), count($pages) === 10),
        wp_fts_wc_gate('max_valid_frontend_query_count', 3, max(array_column($pages, 'query_count') ?: [PHP_INT_MAX]), max(array_column($pages, 'query_count') ?: [PHP_INT_MAX]) === 3),
        wp_fts_wc_gate('max_valid_frontend_memory_peak_attribution', 'maximum resettable page peak minus live PHP usage before the complete ten-page workload', [$processMemoryBefore, $phpPhasePeakAfter, $phpPeakDelta], $processMemoryBefore > 0 && $phpPhasePeakAfter >= $processMemoryBefore && $phpPeakDelta === max(0, $phpPhasePeakAfter - $processMemoryBefore)),
        wp_fts_wc_gate('max_valid_frontend_memory_peak_delta', '<= 25165824 globally and on every reset page', $phpPeakDelta, $pageMeasurementsValid && $phpPeakDelta <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES),
        wp_fts_wc_gate('max_valid_frontend_php_peak', '0 < lifetime peak <= 134217728', $phpPeakBytes, $phpPeakBytes === max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter) && $phpPeakBytes > 0 && $phpPeakBytes <= 134217728),
        wp_fts_wc_gate('max_valid_frontend_rss_delta', '<= 25165824 using VmRSS after minus before on every page', $maxRss, $pageMeasurementsValid && $maxRss <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES),
        wp_fts_wc_gate('max_valid_frontend_rss_peak_attribution', 'Linux VmHWM after minus VmRSS before the complete ten-page workload', [$rssBefore, $rssPeakAfter, $rssPeakDelta], $rssBefore > 0 && $rssPeakAfter >= $rssBefore && $rssPeakDelta === max(0, $rssPeakAfter - $rssBefore)),
        wp_fts_wc_gate('max_valid_frontend_rss_peak_delta', '<= 25165824', $rssPeakDelta, $rssPeakDelta <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES),
        wp_fts_wc_gate('max_valid_frontend_rss_peak', '0 < VmHWM <= 134217728', $rssPeakAfter, $rssPeakAfter > 0 && $rssPeakAfter <= 134217728),
    ];
    $evidence = [
        'schema' => 'relational-fts-max-valid-search-v2',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'max-valid-search',
        ...$sourceBinding,
        'process_identity' => $processIdentity,
        'measurement_method' => 'fresh_process_conservative_peak_attribution',
        'content_bytes' => $expectedBytes,
        'content_sha256' => $expectedHash,
        'pages' => $pages,
        'actual_ids' => $actualIds,
        'php_usage_before_bytes' => $processMemoryBefore,
        'php_lifetime_peak_before_reset_bytes' => $phpLifetimePeakBeforeReset,
        'php_phase_peak_after_reset_bytes' => $phpPhasePeakAfter,
        'php_peak_bytes' => $phpPeakBytes,
        'memory_peak_delta_bytes' => $phpPeakDelta,
        'rss_before_bytes' => $rssBefore,
        'rss_source' => 'linux_proc_status',
        'rss_delta_bytes' => $maxRss,
        'rss_peak_bytes' => $rssPeakAfter,
        'rss_peak_delta_bytes' => $rssPeakDelta,
        'php_peak_delta_authoritative' => true,
        'rss_peak_delta_authoritative' => true,
        'gates' => $gates,
    ];
    $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/max-valid-search.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Near-limit front-end evidence failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return $evidence;
}

/** Measure one required production search shape in its own PHP process. */
function wp_fts_wc_search_memory_sample(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $caseId = wp_fts_wc_required_env('WP_FTS_WC_CASE');
    if (!in_array($caseId, wp_fts_wc_authoritative_search_memory_case_ids(), true)) {
        throw new RuntimeException("Unsupported authoritative search-memory case: {$caseId}");
    }
    $manifest = wp_fts_wc_manifest();
    $definitions = wp_fts_wc_case_definitions($manifest);
    $definition = $definitions[$caseId] ?? null;
    if (!is_array($definition)) {
        throw new RuntimeException("Required search-memory case definition is absent: {$caseId}");
    }
    $searchOptions = wp_fts_wc_search_ready_options($definition['options']);
    $processIdentity = wp_fts_wc_process_identity();
    $storage = wp_fts_wc_storage_fixture(false);
    if (!interface_exists('WP_FTS_Set_Oriented_Search_Storage') || !($storage instanceof WP_FTS_Set_Oriented_Search_Storage)) {
        throw new RuntimeException('Authoritative search-memory evidence requires the production set-oriented backend.');
    }
    $searcher = new WP_FTS_Searcher($storage, new WP_FTS_Analyzer(WP_FTS_Plugin::runtime_analyzer_options()));

    $phpLifetimePeakBeforeReset = memory_get_peak_usage(true);
    wp_fts_wc_reset_php_peak_usage();
    gc_collect_cycles();
    $phpUsageBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $searchOptions));
    $phpUsageAfter = memory_get_usage(true);
    $phpPhasePeakAfter = memory_get_peak_usage(true);
    $phpPeakBytes = max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter);
    $rssAfter = wp_fts_wc_rss_bytes('VmRSS');
    $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
    $phpDelta = max(0, $phpUsageAfter - $phpUsageBefore);
    $phpPeakDelta = max(0, $phpPhasePeakAfter - $phpUsageBefore);
    $rssDelta = max(0, $rssAfter - $rssBefore);
    $rssPeakDelta = max(0, $rssPeakAfter - $rssBefore);
    // Authenticate the large preliminary report only after freezing the
    // production-search counters so harness JSON is not charged to the query.
    $preliminary = wp_fts_wc_preliminary_report_binding();
    $preliminaryReport = $preliminary[array_key_first($preliminary)] ?? null;
    $expected = is_array($preliminaryReport) ? ($preliminaryReport['cases'][$caseId] ?? null) : null;
    if (!is_array($expected)) {
        throw new RuntimeException("Preliminary validation result is absent for search-memory case: {$caseId}");
    }
    $sourceBinding = wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256']);
    $payload = wp_fts_wc_payload($recorded['result']);
    $rows = wp_fts_wc_payload_results($payload);
    $queries = array_values($recorded['queries']);
    $statementShape = wp_fts_wc_statement_shape(array_map(static fn(string $sql): array => ['sql' => $sql], $queries));
    $definitionSha = wp_fts_wc_canonical_hash($definition);
    $expectedDefinition = ['query' => $expected['query'] ?? null, 'options' => $expected['options'] ?? null];
    $expectedDefinitionSha = wp_fts_wc_canonical_hash($expectedDefinition);
    $actualIds = array_map('intval', array_column($rows, 'doc_id'));
    $actualHash = wp_fts_wc_result_hash($rows);
    $actualScoreSignature = wp_fts_wc_ordered_score_signature($rows);
    $expectedQueryCount = (int) ($expected['max_total_query_count'] ?? -1);
    $gates = [
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_source_binding", $sourceBinding, wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256']), $sourceBinding === wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256'])),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_validation_binding", $preliminary['sha256'], $sourceBinding['validation_evidence_sha256'], hash_equals($preliminary['sha256'], $sourceBinding['validation_evidence_sha256'])),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_case_definition", $expectedDefinitionSha, $definitionSha, $definitionSha === $expectedDefinitionSha),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_result_parity", [$expected['result_ids'] ?? null, $expected['result_hash'] ?? null, $expected['result_score_signature'] ?? null], [$actualIds, $actualHash, $actualScoreSignature], $actualIds === ($expected['result_ids'] ?? null) && $actualHash === ($expected['result_hash'] ?? null) && $actualScoreSignature === ($expected['result_score_signature'] ?? null)),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_statement_shape", [$expectedQueryCount, $expected['statement_shape'] ?? null], [count($queries), $statementShape], $expectedQueryCount > 0 && count($queries) === $expectedQueryCount && $statementShape === ($expected['statement_shape'] ?? null)),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_fresh_process_identity", 'positive pid/start ticks with a bound Linux boot identity', $processIdentity, wp_fts_wc_process_identity_valid($processIdentity)),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_php_peak_attribution", 'resettable PHP phase peak after minus live usage before', [$phpUsageBefore, $phpPhasePeakAfter, $phpPeakDelta], $phpUsageBefore > 0 && $phpPhasePeakAfter >= $phpUsageBefore && $phpPeakDelta === max(0, $phpPhasePeakAfter - $phpUsageBefore)),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_php_delta", '<= 16777216 using live usage after minus before', [$phpUsageBefore, $phpUsageAfter, $phpDelta], $phpUsageAfter > 0 && $phpDelta === max(0, $phpUsageAfter - $phpUsageBefore) && $phpDelta <= 16777216),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_php_peak_delta", '<= 16777216', $phpPeakDelta, $phpPeakDelta <= 16777216),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_php_peak", '0 < lifetime peak <= 134217728', $phpPeakBytes, $phpPeakBytes === max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter) && $phpPeakBytes > 0 && $phpPeakBytes <= 134217728),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_rss_peak_attribution", 'Linux VmHWM after minus VmRSS before', [$rssBefore, $rssPeakAfter, $rssPeakDelta], $rssBefore > 0 && $rssPeakAfter >= $rssBefore && $rssPeakDelta === max(0, $rssPeakAfter - $rssBefore)),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_rss_delta", '<= 16777216 using VmRSS after minus before', [$rssBefore, $rssAfter, $rssDelta], $rssAfter > 0 && $rssDelta === max(0, $rssAfter - $rssBefore) && $rssDelta <= 16777216),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_rss_peak_delta", '<= 16777216', $rssPeakDelta, $rssPeakDelta <= 16777216),
        wp_fts_wc_gate("authoritative_search_memory_{$caseId}_rss_peak", '0 < VmHWM <= 134217728', $rssPeakAfter, $rssPeakAfter > 0 && $rssPeakAfter <= 134217728),
    ];
    wp_fts_wc_assert(array_column($gates, 'id') === wp_fts_wc_authoritative_search_memory_gate_ids($caseId), "Authoritative search-memory gate inventory drifted for {$caseId}.");
    $evidence = [
        'schema' => 'relational-fts-search-memory-sample-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'search-memory-sample',
        ...$sourceBinding,
        'case' => $caseId,
        'case_definition_sha256' => $definitionSha,
        'process_identity' => $processIdentity,
        'measurement_method' => 'fresh_process_conservative_peak_attribution',
        'php_peak_delta_authoritative' => true,
        'rss_peak_delta_authoritative' => true,
        'php_usage_before_bytes' => $phpUsageBefore,
        'php_usage_after_bytes' => $phpUsageAfter,
        'php_delta_bytes' => $phpDelta,
        'php_lifetime_peak_before_reset_bytes' => $phpLifetimePeakBeforeReset,
        'php_phase_peak_after_reset_bytes' => $phpPhasePeakAfter,
        'php_peak_bytes' => $phpPeakBytes,
        'php_peak_delta_bytes' => $phpPeakDelta,
        'rss_source' => 'linux_proc_status',
        'rss_before_bytes' => $rssBefore,
        'rss_after_bytes' => $rssAfter,
        'rss_delta_bytes' => $rssDelta,
        'rss_peak_bytes' => $rssPeakAfter,
        'rss_peak_delta_bytes' => $rssPeakDelta,
        'query_count' => count($queries),
        'statement_shape' => $statementShape,
        'max_sql_bytes' => max(array_map('strlen', $queries) ?: [0]),
        'result_ids' => $actualIds,
        'result_hash' => $actualHash,
        'result_score_signature' => $actualScoreSignature,
        'gates' => $gates,
    ];
    $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . "/search-memory-{$caseId}.json", $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException("Authoritative search-memory evidence failed for {$caseId}: " . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return ['status' => 'PASS', 'phase' => 'search-memory-sample', 'case' => $caseId, 'evidence_sha256' => $evidence['evidence_sha256']];
}

/** @return string[] */
function wp_fts_wc_authoritative_search_memory_case_ids(): array
{
    return [
        'common_or',
        'max_valid_or_prefix',
        'rare_anchor_and',
        'prefix_fanout',
        'surface_rarest_exact_anchor_and',
        'surface_dense_candidate_prefix_and',
        'selective_prefix_anchor_and',
        'hidden_dirty_head',
        'impossible_and',
        'all_packs',
        'ambiguous_morphology_or',
        'ambiguous_morphology_and',
        'field_impact',
    ];
}

/** @return string[] */
function wp_fts_wc_authoritative_search_memory_gate_ids(string $caseId): array
{
    if (!in_array($caseId, wp_fts_wc_authoritative_search_memory_case_ids(), true)) {
        throw new RuntimeException("Unknown authoritative search-memory gate inventory: {$caseId}");
    }
    return array_map(
        static fn(string $suffix): string => "authoritative_search_memory_{$caseId}_{$suffix}",
        [
            'source_binding',
            'validation_binding',
            'case_definition',
            'result_parity',
            'statement_shape',
            'fresh_process_identity',
            'php_peak_attribution',
            'php_delta',
            'php_peak_delta',
            'php_peak',
            'rss_peak_attribution',
            'rss_delta',
            'rss_peak_delta',
            'rss_peak',
        ]
    );
}

/** Authenticate the source-bound preliminary report consumed by later children. */
function wp_fts_wc_preliminary_report_binding(): array
{
    $evidence = wp_fts_wc_read_json(wp_fts_wc_evidence_path());
    $recordedHash = $evidence['evidence_sha256'] ?? null;
    $hashInput = $evidence;
    unset($hashInput['evidence_sha256']);
    $calculatedHash = wp_fts_wc_canonical_hash($hashInput);
    if (($evidence['schema'] ?? null) !== WP_FTS_WC_EVIDENCE_SCHEMA
        || ($evidence['status'] ?? null) !== 'PASS'
        || ($evidence['completed'] ?? null) !== false
        || !wp_fts_wc_is_lowercase_sha256($recordedHash)
        || !hash_equals($calculatedHash, (string) $recordedHash)
        || !wp_fts_wc_validation_inventory_matches($evidence)
        || ($evidence['source_sha'] ?? null) !== wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')
        || ($evidence['zip_sha256'] ?? null) !== wp_fts_wc_required_env('WP_FTS_ZIP_SHA256')
        || ($evidence['lane_id'] ?? null) !== wp_fts_wc_required_env('WP_FTS_WC_LANE_ID')
        || ($evidence['engine'] ?? null) !== wp_fts_wc_required_env('WP_FTS_WC_ENGINE')
    ) {
        throw new RuntimeException('Later-process evidence requires the complete source-bound preliminary validation report.');
    }

    return ['evidence' => $evidence, 'sha256' => (string) $recordedHash];
}

/** @return array<string,string> */
function wp_fts_wc_artifact_source_binding(array $manifest, string $validationHash): array
{
    return [
        'source_sha' => wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'),
        'zip_sha256' => wp_fts_wc_required_env('WP_FTS_ZIP_SHA256'),
        'harness_sha256' => wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256'),
        'lane_id' => wp_fts_wc_required_env('WP_FTS_WC_LANE_ID'),
        'engine' => wp_fts_wc_required_env('WP_FTS_WC_ENGINE'),
        'profile' => (string) ($manifest['profile']['name'] ?? ''),
        'manifest_sha256' => (string) ($manifest['sha256'] ?? ''),
        'validation_evidence_sha256' => $validationHash,
    ];
}

/** Bind a child to its actual Linux process lifetime, not merely a case label. */
function wp_fts_wc_process_identity(): array
{
    $stat = @file_get_contents('/proc/self/stat');
    $bootId = trim((string) @file_get_contents('/proc/sys/kernel/random/boot_id'));
    $closingParen = is_string($stat) ? strrpos($stat, ')') : false;
    $fields = is_int($closingParen)
        ? array_values(array_filter(explode(' ', trim(substr($stat, $closingParen + 1))), static fn(string $field): bool => $field !== ''))
        : false;
    $startTicks = is_array($fields) && isset($fields[19]) && wp_fts_wc_is_ascii_digits($fields[19]) ? (int) $fields[19] : 0;
    $pid = getmypid();
    $identity = [
        'pid' => $pid,
        'start_ticks' => $startTicks,
        'boot_id' => $bootId,
    ];
    $identity['sha256'] = hash('sha256', implode('|', [$bootId, (string) $pid, (string) $startTicks]));

    return $identity;
}

/** Validate the PID, Linux start tick, boot ID, and digest of one child identity. */
function wp_fts_wc_process_identity_valid(array $identity): bool
{
    $pid = $identity['pid'] ?? null;
    $startTicks = $identity['start_ticks'] ?? null;
    $bootId = $identity['boot_id'] ?? null;
    $sha = $identity['sha256'] ?? null;

    return is_int($pid) && $pid > 0
        && is_int($startTicks) && $startTicks > 0
        && is_string($bootId) && $bootId !== ''
        && wp_fts_wc_is_lowercase_sha256($sha)
        && hash_equals(hash('sha256', implode('|', [$bootId, (string) $pid, (string) $startTicks])), (string) $sha);
}

/** Resettable peak attribution is a hard requirement of the real-DB runtime. */
function wp_fts_wc_reset_php_peak_usage(): void
{
    if (!function_exists('memory_reset_peak_usage')) {
        throw new RuntimeException('Authoritative PHP peak attribution requires memory_reset_peak_usage().');
    }
    memory_reset_peak_usage();
}

/**
 * Exercise identity lookup, cursor invalidation, and transactional-engine
 * repair against the populated real database, restoring every fixture before
 * the timed search cases run.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_identity_epoch_engine_proof(
    WP_FTS_Searcher $searcher,
    WP_FTS_Relational_Storage $storage
): array {
    $identityBytes = wp_fts_wc_identity_bytes_proof($searcher);
    $deletedIdentityCursor = wp_fts_wc_deleted_identity_cursor_proof($searcher);
    $nontransactionalEngine = wp_fts_wc_nontransactional_engine_proof($storage);
    $gates = [
        ...$identityBytes['gates'],
        ...$deletedIdentityCursor['gates'],
        ...$nontransactionalEngine['gates'],
    ];

    return [
        'schema' => 'relational-fts-identity-epoch-engine-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'identity_bytes' => $identityBytes,
        'deleted_identity_cursor' => $deletedIdentityCursor,
        'nontransactional_engine' => $nontransactionalEngine,
        'gates' => $gates,
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_identity_bytes_proof(WP_FTS_Searcher $searcher): array
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $fixtureLang = 'x-wpfts-identity';
    $fixtureCount = 4096;
    $options = wp_fts_wc_search_ready_options([
        'query_lang' => 'en',
        'post_types' => ['post'],
        'post_statuses' => ['publish'],
        'limit' => 20,
        'mode' => 'OR',
        'prefix_matching' => false,
        'include_snippets' => false,
    ]);
    $baselinePayload = wp_fts_wc_payload($searcher->search('commonalpha', $options));
    $baselineSignature = wp_fts_wc_ordered_score_signature(wp_fts_wc_payload_results($baselinePayload));
    wp_fts_wc_assert($baselineSignature !== [], 'The identity-byte proof needs indexed commonalpha results.');

    $requested = $wpdb->get_row($wpdb->prepare(
        "SELECT term_id,HEX(lang) lang_hex,kind,HEX(term) term_hex,doc_freq
FROM `{$terms}`
WHERE lang=%s AND kind=0 AND term=%s",
        'en',
        'commonalpha'
    ), ARRAY_A);
    wp_fts_wc_assert(is_array($requested) && (int) ($requested['term_id'] ?? 0) > 0, 'The identity-byte proof could not resolve the requested dictionary row.');
    $termsBefore = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$terms}`", 'dictionary rows before identity-byte fixture');
    $fixtureBefore = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$terms}` WHERE lang=%s", $fixtureLang),
        'pre-existing identity-byte fixtures'
    );
    wp_fts_wc_assert($fixtureBefore === 0, 'The disposable database already contains identity-byte fixtures.');

    $inserted = 0;
    $cleanupRemaining = -1;
    $termsAfter = -1;
    $recorded = ['queries' => [], 'result' => []];
    $events = [];
    $planSql = '';
    $planExplain = [];
    $termAccess = [];
    try {
        for ($start = 0; $start < $fixtureCount; $start += 256) {
            $values = [];
            $args = [];
            $end = min($fixtureCount, $start + 256);
            for ($ordinal = $start; $ordinal < $end; $ordinal++) {
                $term = 'wpftsidentity' . str_pad((string) $ordinal, 4, '0', STR_PAD_LEFT);
                $values[] = '(UNHEX(%s),0,UNHEX(%s),0)';
                array_push($args, bin2hex($fixtureLang), bin2hex($term));
            }
            $affected = $wpdb->query($wpdb->prepare(
                "INSERT INTO `{$terms}` (lang,kind,term,doc_freq) VALUES " . implode(',', $values),
                ...$args
            ));
            if ($affected !== count($values)) {
                throw new RuntimeException('Could not insert the complete identity-byte fixture: ' . (string) $wpdb->last_error);
            }
            $inserted += (int) $affected;
        }
        wp_fts_wc_assert($inserted === $fixtureCount, 'The identity-byte fixture cardinality is incomplete.');

        $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()');
        wp_fts_wc_assert($threadId > 0, 'Could not map the identity-byte search to Performance Schema.');
        $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
            'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
            $threadId
        ));
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search('commonalpha', $options));
        $events = $wpdb->get_results($wpdb->prepare(
            'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
            $threadId,
            $beforeEvent
        ), ARRAY_A) ?: [];
        $planQueries = array_values(array_filter(
            $recorded['queries'],
            static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'plan'
        ));
        wp_fts_wc_assert(count($planQueries) === 1, 'The identity-byte search did not issue exactly one plan statement.');
        $planSql = $planQueries[0];
        $explainJson = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $planSql);
        wp_fts_wc_assert(is_string($explainJson) && $explainJson !== '', 'The identity-byte plan has no EXPLAIN JSON.');
        $planExplain = json_decode($explainJson, true, 512, JSON_THROW_ON_ERROR);
        wp_fts_wc_assert(is_array($planExplain), 'The identity-byte EXPLAIN JSON is malformed.');
        $access = [];
        wp_fts_wc_collect_database_table_access($planExplain, $access);
        $termAccess = array_values(array_filter($access, static function (array $row): bool {
            $table = strtolower(trim((string) ($row['table_name'] ?? ''), "` \t\n\r\0\x0B"));
            return $table === 'exact_term' || str_ends_with($table, 'fts_terms');
        }));
    } finally {
        if ($wpdb->query($wpdb->prepare("DELETE FROM `{$terms}` WHERE lang=%s", $fixtureLang)) === false) {
            throw new RuntimeException('Could not remove the identity-byte fixture: ' . (string) $wpdb->last_error);
        }
        $cleanupRemaining = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$terms}` WHERE lang=%s", $fixtureLang),
            'remaining identity-byte fixtures'
        );
        $termsAfter = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$terms}`", 'dictionary rows after identity-byte fixture');
    }

    $actualSignature = wp_fts_wc_ordered_score_signature(wp_fts_wc_payload_results(wp_fts_wc_payload($recorded['result'])));
    $planEvents = array_values(array_filter(
        $events,
        static fn(array $event): bool => wp_fts_wc_search_statement_kind((string) ($event['SQL_TEXT'] ?? '')) === 'plan'
    ));
    $planRowsSent = array_sum(array_map(static fn(array $event): int => (int) ($event['ROWS_SENT'] ?? 0), $planEvents));
    $usesUniqueIdentity = count(array_filter(
        $termAccess,
        static fn(array $row): bool => (string) ($row['key'] ?? '') === 'term_identity'
            && in_array(strtoupper((string) ($row['access_type'] ?? '')), ['EQ_REF', 'REF', 'CONST'], true)
    )) === 1;
    $gates = [
        wp_fts_wc_gate('identity_bytes_plan_rows_bounded', 1, $planRowsSent, count($planEvents) === 1 && $planRowsSent === 1),
        wp_fts_wc_gate('identity_bytes_membership_exact', $baselineSignature, $actualSignature, $actualSignature === $baselineSignature),
        wp_fts_wc_gate('identity_bytes_unique_index_access', 'one term_identity eq/ref access', $termAccess, $usesUniqueIdentity),
        wp_fts_wc_gate('identity_bytes_fixture_restored', [$termsBefore, 0], [$termsAfter, $cleanupRemaining], $termsAfter === $termsBefore && $cleanupRemaining === 0),
    ];

    return [
        'requested_term' => $requested,
        'unrelated_identities' => $fixtureCount,
        'inserted_identities' => $inserted,
        'baseline_signature' => $baselineSignature,
        'actual_signature' => $actualSignature,
        'plan_sql' => $planSql,
        'plan_explain' => $planExplain,
        'term_access' => $termAccess,
        'performance_schema_events' => $planEvents,
        'cleanup' => ['terms_before' => $termsBefore, 'terms_after' => $termsAfter, 'fixture_rows' => $cleanupRemaining],
        'gates' => $gates,
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_deleted_identity_cursor_proof(WP_FTS_Searcher $searcher): array
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $options = wp_fts_wc_search_ready_options([
        'query_lang' => 'en',
        'post_types' => ['post'],
        'post_statuses' => ['publish'],
        'limit' => 1,
        'mode' => 'OR',
        'prefix_matching' => false,
        'include_snippets' => false,
    ]);
    $firstPayload = wp_fts_wc_payload($searcher->search('commonalpha', $options));
    $cursor = isset($firstPayload['next_cursor']) && is_scalar($firstPayload['next_cursor'])
        ? (string) $firstPayload['next_cursor']
        : '';
    wp_fts_wc_assert($cursor !== '', 'The deleted-identity proof needs a real forward cursor.');

    $term = $wpdb->get_row($wpdb->prepare(
        "SELECT term_id,HEX(lang) lang_hex,kind,HEX(term) term_hex,doc_freq
FROM `{$terms}`
WHERE lang=%s AND kind=0 AND term=%s",
        'en',
        'commonalpha'
    ), ARRAY_A);
    wp_fts_wc_assert(is_array($term) && (int) ($term['term_id'] ?? 0) > 0, 'The deleted-identity proof could not snapshot its dictionary row.');
    $termId = (int) $term['term_id'];
    $postingCountBefore = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$postings}` WHERE term_id=%d", $termId),
        'requested-identity postings before cursor invalidation'
    );
    wp_fts_wc_assert($postingCountBefore > 1, 'The deleted-identity cursor fixture must have more than one posting.');
    $epochStateSql = $wpdb->prepare(
        "SELECT HEX(job_key) job_key_hex,kind,post_id,generation,state,available_at,attempts,claim_token,claimed_generation,claim_expires_at,cursor_post_id,scope_coverage,HEX(scope_incarnation) scope_incarnation_hex,scope_subject_type,scope_subject_id,payload,last_error_code,last_error_at
FROM `{$work}` WHERE job_key=%s AND kind='meta' AND state='meta'",
        WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY
    );
    $epochStateBefore = $wpdb->get_row($epochStateSql, ARRAY_A);
    $epochBefore = is_array($epochStateBefore) ? (int) ($epochStateBefore['generation'] ?? 0) : 0;
    wp_fts_wc_assert($epochBefore > 0, 'The deleted-identity proof requires the search epoch singleton.');

    $queries = [];
    $error = null;
    $termAfter = [];
    $epochStateAfter = [];
    $epochDuring = -1;
    $epochAfterRestore = -1;
    $postingCountAfter = -1;
    try {
        $mutation = wp_fts_wc_run_writer_fixture(
            'worst-case-delete-search-identity',
            static function () use ($wpdb, $terms, $termId): int {
                if ($wpdb->query('START TRANSACTION') === false) {
                    throw new RuntimeException('Could not start the deleted-identity fixture transaction.');
                }
                try {
                    $affected = $wpdb->query($wpdb->prepare("DELETE FROM `{$terms}` WHERE term_id=%d", $termId));
                    if ($affected !== 1) {
                        throw new RuntimeException('Could not delete exactly one requested dictionary identity.');
                    }
                    (new WP_FTS_Index_Queue($wpdb))->advance_search_epoch();
                    if ($wpdb->query('COMMIT') === false) {
                        throw new RuntimeException('Could not commit the deleted-identity fixture.');
                    }
                    return $affected;
                } catch (Throwable $failure) {
                    $wpdb->query('ROLLBACK');
                    throw $failure;
                }
            },
            ['record_health' => false, 'record_skip' => false]
        );
        wp_fts_wc_assert(!empty($mutation['acquired']) && (int) ($mutation['result'] ?? 0) === 1, 'The deleted-identity fixture did not acquire the shared writer lock.');
        $epochDuring = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT generation FROM `{$work}` WHERE job_key=%s AND kind='meta' AND state='meta'",
            WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY
        ));

        $filter = static function (string $sql) use (&$queries): string {
            $queries[] = $sql;
            return $sql;
        };
        add_filter('query', $filter, PHP_INT_MIN, 1);
        try {
            $searcher->search('commonalpha', $options + ['cursor' => $cursor]);
        } catch (Throwable $failure) {
            $error = $failure;
        } finally {
            remove_filter('query', $filter, PHP_INT_MIN);
        }
    } finally {
        $restoreNeeded = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$terms}` WHERE term_id=%d", $termId),
            'requested identity presence before fixture restoration'
        ) === 0;
        if ($restoreNeeded) {
            $restore = wp_fts_wc_run_writer_fixture(
                'worst-case-restore-search-identity',
                static function () use ($wpdb, $terms, $work, $term, $epochStateBefore): void {
                    if ($wpdb->query('START TRANSACTION') === false) {
                        throw new RuntimeException('Could not start the deleted-identity restore transaction.');
                    }
                    try {
                        $inserted = $wpdb->query($wpdb->prepare(
                            "INSERT INTO `{$terms}` (term_id,lang,kind,term,doc_freq)
VALUES (%d,UNHEX(%s),%d,UNHEX(%s),%d)",
                            (int) $term['term_id'],
                            (string) $term['lang_hex'],
                            (int) $term['kind'],
                            (string) $term['term_hex'],
                            (int) $term['doc_freq']
                        ));
                        if ($inserted !== 1) {
                            throw new RuntimeException('Could not restore the requested dictionary identity.');
                        }
                        $restoredEpoch = $wpdb->update(
                            $work,
                            [
                                'kind' => (string) $epochStateBefore['kind'],
                                'post_id' => (int) $epochStateBefore['post_id'],
                                'generation' => (int) $epochStateBefore['generation'],
                                'state' => (string) $epochStateBefore['state'],
                                'available_at' => (int) $epochStateBefore['available_at'],
                                'attempts' => (int) $epochStateBefore['attempts'],
                                'claim_token' => (string) $epochStateBefore['claim_token'],
                                'claimed_generation' => (int) $epochStateBefore['claimed_generation'],
                                'claim_expires_at' => (int) $epochStateBefore['claim_expires_at'],
                                'cursor_post_id' => (int) $epochStateBefore['cursor_post_id'],
                                'scope_subject_type' => (string) $epochStateBefore['scope_subject_type'],
                                'scope_subject_id' => (int) $epochStateBefore['scope_subject_id'],
                                'payload' => $epochStateBefore['payload'] === null ? null : (string) $epochStateBefore['payload'],
                                'last_error_code' => (string) $epochStateBefore['last_error_code'],
                                'last_error_at' => (int) $epochStateBefore['last_error_at'],
                            ],
                            ['job_key' => WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY],
                            ['%s', '%d', '%d', '%s', '%d', '%d', '%s', '%d', '%d', '%d', '%s', '%d', '%s', '%s', '%d'],
                            ['%s']
                        );
                        if ($restoredEpoch !== 1 && $restoredEpoch !== 0) {
                            throw new RuntimeException('Could not restore the search epoch singleton.');
                        }
                        if ($wpdb->query('COMMIT') === false) {
                            throw new RuntimeException('Could not commit the deleted-identity restore.');
                        }
                    } catch (Throwable $failure) {
                        $wpdb->query('ROLLBACK');
                        throw $failure;
                    }
                },
                ['record_health' => false, 'record_skip' => false]
            );
            wp_fts_wc_assert(!empty($restore['acquired']), 'The deleted-identity restore did not acquire the shared writer lock.');
        }

        $termAfter = $wpdb->get_row($wpdb->prepare(
            "SELECT term_id,HEX(lang) lang_hex,kind,HEX(term) term_hex,doc_freq
FROM `{$terms}` WHERE term_id=%d",
            $termId
        ), ARRAY_A) ?: [];
        $epochStateAfter = $wpdb->get_row($epochStateSql, ARRAY_A) ?: [];
        $epochAfterRestore = (int) ($epochStateAfter['generation'] ?? 0);
        $postingCountAfter = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$postings}` WHERE term_id=%d", $termId),
            'requested-identity postings after cursor invalidation'
        );
    }

    $planQueries = array_values(array_filter($queries, static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'plan'));
    $rankQueries = array_values(array_filter($queries, static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'rank'));
    $hydrateQueries = array_values(array_filter($queries, static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'hydrate'));
    $rejected = $error instanceof InvalidArgumentException && str_contains(strtolower($error->getMessage()), 'cursor');
    $stateRestored = $termAfter === $term
        && $epochStateAfter === $epochStateBefore
        && $epochAfterRestore === $epochBefore
        && $postingCountAfter === $postingCountBefore;
    $gates = [
        wp_fts_wc_gate('deleted_identity_cursor_rejected', 'InvalidArgumentException mentioning cursor', $error === null ? null : [get_class($error), $error->getMessage()], $rejected),
        wp_fts_wc_gate('deleted_identity_cursor_plan_statements', 1, count($planQueries), count($planQueries) === 1),
        wp_fts_wc_gate('deleted_identity_cursor_rank_statements', 0, count($rankQueries), count($rankQueries) === 0),
        wp_fts_wc_gate('deleted_identity_cursor_hydrate_statements', 0, count($hydrateQueries), count($hydrateQueries) === 0),
        wp_fts_wc_gate('deleted_identity_epoch_advanced', $epochBefore + 1, $epochDuring, $epochDuring === $epochBefore + 1),
        wp_fts_wc_gate('deleted_identity_state_restored', ['term' => $term, 'epoch' => $epochStateBefore, 'postings' => $postingCountBefore], ['term' => $termAfter, 'epoch' => $epochStateAfter, 'postings' => $postingCountAfter], $stateRestored),
    ];

    return [
        'cursor_sha256' => hash('sha256', $cursor),
        'term_before' => $term,
        'term_after_restore' => $termAfter,
        'epoch_before' => $epochBefore,
        'epoch_during_deleted_identity' => $epochDuring,
        'epoch_after_restore' => $epochAfterRestore,
        'epoch_state_before' => $epochStateBefore,
        'epoch_state_after_restore' => $epochStateAfter,
        'posting_count_before' => $postingCountBefore,
        'posting_count_after' => $postingCountAfter,
        'error' => $error === null ? null : ['class' => get_class($error), 'message' => $error->getMessage()],
        'plan_statements' => $planQueries,
        'rank_statements' => $rankQueries,
        'hydrate_statements' => $hydrateQueries,
        'gates' => $gates,
    ];
}

/** @return array<string,mixed> */
function wp_fts_wc_nontransactional_engine_proof(WP_FTS_Relational_Storage $storage): array
{
    global $wpdb;

    $workName = $wpdb->prefix . 'fts_work';
    $work = wp_fts_wc_identifier($workName);
    $backupName = $wpdb->prefix . 'wpfts_wc_engine_restore';
    $backup = wp_fts_wc_identifier($backupName);
    $workColumns = [
        'job_key', 'kind', 'post_id', 'generation', 'state', 'available_at',
        'attempts', 'claim_token', 'claimed_generation', 'claim_expires_at',
        'cursor_post_id', 'scope_coverage', 'scope_incarnation',
        'scope_subject_type', 'scope_subject_id', 'payload',
        'last_error_code', 'last_error_at',
    ];
    $columnSql = implode(',', array_map(static fn(string $column): string => "`{$column}`", $workColumns));
    $workStateSql = "SELECT HEX(job_key) job_key_hex,kind,post_id,generation,state,available_at,attempts,claim_token,claimed_generation,claim_expires_at,cursor_post_id,scope_coverage,HEX(scope_incarnation) scope_incarnation_hex,scope_subject_type,scope_subject_id,payload,last_error_code,last_error_at
FROM `{$work}` ORDER BY job_key";
    $stateBefore = $wpdb->get_results($workStateSql, ARRAY_A) ?: [];
    $stateHashBefore = wp_fts_wc_canonical_hash($stateBefore);
    $backupExists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($backupName)));
    wp_fts_wc_assert(!is_scalar($backupExists) || (string) $backupExists !== $backupName, 'The disposable database already contains the engine-restore table.');

    $engines = $wpdb->get_results('SHOW ENGINES', ARRAY_A) ?: [];
    $myisam = array_values(array_filter($engines, static fn(array $row): bool => strtolower((string) ($row['Engine'] ?? $row['engine'] ?? '')) === 'myisam'));
    $myisamSupport = strtoupper((string) ($myisam[0]['Support'] ?? $myisam[0]['support'] ?? ''));
    wp_fts_wc_assert(count($myisam) === 1 && in_array($myisamSupport, ['YES', 'DEFAULT'], true), 'The pinned database image does not provide the required MyISAM corruption fixture engine.');

    $beforeStatus = $wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s', $wpdb->esc_like($workName)), ARRAY_A);
    wp_fts_wc_assert(is_array($beforeStatus) && strtolower((string) ($beforeStatus['Engine'] ?? '')) === 'innodb', 'The work table must start the engine proof on InnoDB.');
    $backupCreated = false;
    $backupPopulated = false;
    $invalidVerification = [];
    $repairVerification = [];
    $repairEngine = '';
    $repairQueries = [];
    $dropCount = 0;
    $stateAfterRepair = [];
    $stateHashAfterRepair = '';
    $stateAfter = [];
    $stateHashAfter = '';
    $restoredEngine = '';
    try {
        if ($wpdb->query("CREATE TABLE `{$backup}` LIKE `{$work}`") === false) {
            throw new RuntimeException('Could not create the engine-restore table: ' . (string) $wpdb->last_error);
        }
        $backupCreated = true;
        $copied = $wpdb->query("INSERT INTO `{$backup}` ({$columnSql}) SELECT {$columnSql} FROM `{$work}`");
        if ($copied !== count($stateBefore)) {
            throw new RuntimeException('Could not snapshot the exact durable work state before engine repair.');
        }
        $backupPopulated = true;
        if ($wpdb->query("ALTER TABLE `{$work}` ENGINE=MyISAM") === false) {
            throw new RuntimeException('Could not convert the work table to MyISAM: ' . (string) $wpdb->last_error);
        }
        $invalidVerification = $storage->verify_schema();

        $repair = wp_fts_wc_run_writer_fixture(
            'worst-case-engine-repair',
            static fn(): array => wp_fts_wc_record_queries(static function () use ($storage): bool {
                $storage->create_tables();
                return true;
            }),
            ['record_health' => false, 'record_skip' => false]
        );
        wp_fts_wc_assert(!empty($repair['acquired']) && is_array($repair['result'] ?? null), 'Schema repair did not acquire the shared writer lock.');
        $repairRecord = $repair['result'];
        $repairQueries = is_array($repairRecord['queries'] ?? null) ? array_values($repairRecord['queries']) : [];
        $dropCount = count(array_filter($repairQueries, static function (string $sql) use ($work): bool {
            return strtoupper(trim($sql)) === strtoupper("DROP TABLE `{$work}`");
        }));
        $repairVerification = $storage->verify_schema();
        $repairedStatus = $wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s', $wpdb->esc_like($workName)), ARRAY_A);
        $repairEngine = is_array($repairedStatus) ? strtolower((string) ($repairedStatus['Engine'] ?? '')) : '';
        $stateAfterRepair = $wpdb->get_results($workStateSql, ARRAY_A) ?: [];
        $stateHashAfterRepair = wp_fts_wc_canonical_hash($stateAfterRepair);
    } finally {
        if ($backupPopulated) {
            $restore = wp_fts_wc_run_writer_fixture(
                'worst-case-engine-state-restore',
                static function () use ($wpdb, $storage, $workName, $work, $backup, $columnSql): void {
                    $exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($workName)));
                    if (!is_scalar($exists) || (string) $exists !== $workName) {
                        $storage->create_tables();
                    }
                    $status = $wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s', $wpdb->esc_like($workName)), ARRAY_A);
                    if (!is_array($status) || strtolower((string) ($status['Engine'] ?? '')) !== 'innodb') {
                        if ($wpdb->query("ALTER TABLE `{$work}` ENGINE=InnoDB") === false) {
                            throw new RuntimeException('Could not restore the work table to InnoDB.');
                        }
                    }
                    if ($wpdb->query('START TRANSACTION') === false) {
                        throw new RuntimeException('Could not start the engine-state restore transaction.');
                    }
                    try {
                        if ($wpdb->query("DELETE FROM `{$work}`") === false) {
                            throw new RuntimeException('Could not clear the repaired work table before state restoration.');
                        }
                        if ($wpdb->query("INSERT INTO `{$work}` ({$columnSql}) SELECT {$columnSql} FROM `{$backup}`") === false) {
                            throw new RuntimeException('Could not restore the durable work rows after engine repair.');
                        }
                        if ($wpdb->query('COMMIT') === false) {
                            throw new RuntimeException('Could not commit the engine-state restore transaction.');
                        }
                    } catch (Throwable $failure) {
                        $wpdb->query('ROLLBACK');
                        throw $failure;
                    }
                    if ($wpdb->query("DROP TABLE `{$backup}`") === false) {
                        throw new RuntimeException('Could not remove the engine-restore table.');
                    }
                },
                ['record_health' => false, 'record_skip' => false]
            );
            wp_fts_wc_assert(!empty($restore['acquired']), 'Engine fixture cleanup did not acquire the shared writer lock.');
        } elseif ($backupCreated && $wpdb->query("DROP TABLE `{$backup}`") === false) {
            throw new RuntimeException('Could not remove an incomplete engine-restore table.');
        }

        $stateAfter = $wpdb->get_results($workStateSql, ARRAY_A) ?: [];
        $stateHashAfter = wp_fts_wc_canonical_hash($stateAfter);
        $restoredStatus = $wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s', $wpdb->esc_like($workName)), ARRAY_A);
        $restoredEngine = is_array($restoredStatus) ? strtolower((string) ($restoredStatus['Engine'] ?? '')) : '';
        $backupAfter = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($backupName)));
        wp_fts_wc_assert(!is_scalar($backupAfter) || (string) $backupAfter !== $backupName, 'The engine-restore table remains after cleanup.');
    }

    $reportedEngines = is_array($invalidVerification['invalid_engines'] ?? null)
        ? array_values($invalidVerification['invalid_engines'])
        : [];
    $gates = [
        wp_fts_wc_gate('nontransactional_engine_rejected', false, $invalidVerification['valid'] ?? null, ($invalidVerification['valid'] ?? null) === false),
        wp_fts_wc_gate('nontransactional_engine_reported', ["{$workName}(myisam)"], $reportedEngines, $reportedEngines === ["{$workName}(myisam)"]),
        wp_fts_wc_gate('nontransactional_engine_repaired', ['valid' => true, 'engine' => 'innodb'], ['valid' => $repairVerification['valid'] ?? null, 'engine' => $repairEngine], ($repairVerification['valid'] ?? null) === true && $repairEngine === 'innodb'),
        wp_fts_wc_gate('nontransactional_engine_drop_count', 1, $dropCount, $dropCount === 1),
        wp_fts_wc_gate('nontransactional_engine_repair_does_not_claim_state_preservation', false, $stateAfterRepair === $stateBefore, $stateAfterRepair !== $stateBefore && $stateHashAfterRepair !== $stateHashBefore),
        wp_fts_wc_gate('nontransactional_engine_fixture_cleanup_restored', ['engine' => 'innodb', 'state_sha256' => $stateHashBefore], ['engine' => $restoredEngine, 'state_sha256' => $stateHashAfter], $restoredEngine === 'innodb' && $stateHashAfter === $stateHashBefore && $stateAfter === $stateBefore),
    ];

    return [
        'fixture_engine' => 'MyISAM',
        'fixture_engine_support' => $myisam[0],
        'table' => $workName,
        'schema_before_repair' => $invalidVerification,
        'schema_after_repair' => $repairVerification,
        'repair_engine' => $repairEngine,
        'repair_queries' => $repairQueries,
        'drop_count' => $dropCount,
        'state_before' => $stateBefore,
        'state_after_production_repair' => $stateAfterRepair,
        'state_sha256_after_production_repair' => $stateHashAfterRepair,
        'production_repair_preserved_exact_work_state' => false,
        'fixture_cleanup_state_after' => $stateAfter,
        'state_sha256_before' => $stateHashBefore,
        'fixture_cleanup_state_sha256' => $stateHashAfter,
        'fixture_cleanup_engine' => $restoredEngine,
        'gates' => $gates,
    ];
}

/** Prove the analyzer itself performs no database work. */
function wp_fts_wc_analysis_proof(): array
{
    $analyzer = new WP_FTS_Analyzer(WP_FTS_Plugin::runtime_analyzer_options());
    $query = 'Wrocław commonalpha Häusern 中文搜索';
    $recorded = wp_fts_wc_record_queries(static fn() => $analyzer->analyze_query_occurrences(
        $query,
        ['query_lang' => 'en']
    ));
    $occurrences = is_array($recorded['result']) ? $recorded['result'] : [];
    $queries = array_values($recorded['queries']);
    wp_fts_wc_assert(array_is_list($occurrences) && count($occurrences) <= 64, 'Query-analysis occurrence evidence exceeds its 64-row bound.');
    wp_fts_wc_assert(count($queries) <= 4, 'Query-analysis SQL evidence exceeds its four-statement diagnostic bound.');
    foreach ($queries as $sql) {
        wp_fts_wc_assert(strlen($sql) <= 32768, 'Query-analysis SQL evidence exceeds its 32 KiB statement bound.');
    }
    $observations = [
        'query' => $query,
        'query_sha256' => hash('sha256', $query),
        'occurrences' => $occurrences,
        'occurrences_sha256' => wp_fts_wc_canonical_hash($occurrences),
        'sql' => $queries,
        'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
    ];
    wp_fts_wc_assert_json_evidence_bytes($observations, 65536, 'Query-analysis observations');
    $gates = [
        wp_fts_wc_gate('query_analysis_sql_count', 0, count($queries), $queries === []),
        wp_fts_wc_gate('query_analysis_occurrences', '> 0', count($occurrences), $occurrences !== []),
    ];
    return [
        'schema' => 'relational-fts-analysis-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        ...$observations,
        'occurrence_count' => count($occurrences),
        'sql_count' => count($queries),
        'gates' => $gates,
    ];
}

/**
 * Exhaust up to 2,000 public posts immediately after the hidden corpus prefix
 * against a deliberately slow PHP scorer.
 * The oracle reads every matching posting in the slice and performs its own
 * visibility, score, and tie-break ordering; it does not reuse production
 * ranking SQL or a candidate cap. Traversing to the terminal page makes a
 * hidden late-result cap observable instead of validating only the first 100.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_oracle_proof(WP_FTS_Searcher $searcher, array $manifest): array
{
    global $wpdb;

    $profile = $manifest['profile'];
    $firstOrdinal = (int) $profile['hidden'] + 1;
    $lastOrdinal = min((int) $profile['documents'], $firstOrdinal + 1999);
    $firstId = (int) $manifest['first_post_id'] + $firstOrdinal - 1;
    $lastId = (int) $manifest['first_post_id'] + $lastOrdinal - 1;
    $dateBefore = gmdate('Y-m-d H:i:s', 1704067200 + $lastOrdinal);
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT po.post_id,po.impact,t.doc_freq,p.post_date_gmt
FROM `{$terms}` t
JOIN `{$postings}` po ON po.term_id=t.term_id
JOIN `{$documents}` d ON d.post_id=po.post_id
JOIN {$wpdb->posts} p ON p.ID=po.post_id
LEFT JOIN `{$work}` w ON w.kind='post' AND w.post_id=po.post_id
WHERE t.lang=%s AND t.kind=1 AND t.term=%s
	  AND po.post_id BETWEEN %d AND %d
	  AND p.post_type=%s AND p.post_status=%s AND p.post_password='' AND p.post_date_gmt<=%s AND w.job_key IS NULL",
        'en',
        'commonalpha',
        $firstId,
        $lastId,
        'post',
        'publish',
        $dateBefore
    ), ARRAY_A) ?: [];
    wp_fts_wc_assert($rows !== [], 'The independent oracle slice has no matching postings.');

    $oracle = [];
    foreach ($rows as $row) {
        $frequency = max(1, (int) $row['doc_freq']);
        $oracle[] = [
            'doc_id' => (int) $row['post_id'],
            'score' => max(1, (int) $row['impact']) * max(1, intdiv(1000000, $frequency)),
            'date' => (string) $row['post_date_gmt'],
        ];
    }
    usort($oracle, static function (array $left, array $right): int {
        return $right['score'] <=> $left['score']
            ?: strcmp($right['date'], $left['date'])
            ?: $right['doc_id'] <=> $left['doc_id'];
    });
    $actual = [];
    $cursor = null;
    $queryCounts = [];
    $expectedPages = (int) ceil(count($oracle) / 20);
    for ($page = 0; $page < $expectedPages; $page++) {
        $options = wp_fts_wc_search_ready_options([
            'query_lang' => 'en',
            'post_types' => ['post'],
            'post_statuses' => ['publish'],
            'date_before' => $dateBefore,
            'limit' => 20,
            'mode' => 'OR',
            'prefix_matching' => false,
        ]);
        if ($cursor !== null) {
            $options['cursor'] = $cursor;
        }
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search('commonalpha', $options));
        $payload = wp_fts_wc_payload($recorded['result']);
        $pageRows = wp_fts_wc_payload_results($payload);
        $actual = [...$actual, ...array_map(static fn(array $row): array => [
            'doc_id' => (int) $row['doc_id'],
            'score' => (int) round((float) ($row['score'] ?? 0)),
        ], $pageRows)];
        $queryCounts[] = count($recorded['queries']);
        $hasMore = !empty($payload['has_more']);
        $nextCursor = isset($payload['next_cursor']) && is_scalar($payload['next_cursor']) ? (string) $payload['next_cursor'] : '';
        if ($page < $expectedPages - 1) {
            wp_fts_wc_assert($hasMore && $nextCursor !== '', 'The complete oracle traversal ended before the terminal slice row.');
            $cursor = $nextCursor;
        } else {
            wp_fts_wc_assert(!$hasMore && $nextCursor === '', 'The complete oracle traversal exposed a cursor beyond the known slice membership.');
        }
    }
    $expectedComparable = array_map(static fn(array $row): array => ['doc_id' => $row['doc_id'], 'score' => $row['score']], $oracle);
    $expectedIds = array_column($expectedComparable, 'doc_id');
    $actualIds = array_column($actual, 'doc_id');
    $matches = $expectedComparable === $actual;

    return [
        'slice' => ['first_post_id' => $firstId, 'last_post_id' => $lastId, 'matching_postings' => count($rows)],
        'expected_ids' => $expectedIds,
        'actual_ids' => $actualIds,
        'pages' => $expectedPages,
        'expected_hash' => wp_fts_wc_canonical_hash($expectedComparable),
        'actual_hash' => wp_fts_wc_canonical_hash($actual),
        'max_query_count' => max($queryCounts ?: [PHP_INT_MAX]),
        'gates' => [
            wp_fts_wc_gate('oracle_complete_slice_membership_and_order', count($expectedIds), count($actualIds), $matches),
            wp_fts_wc_gate('oracle_unique_complete_slice', count($expectedIds), count(array_unique($actualIds)), count($actualIds) === count($expectedIds) && count(array_unique($actualIds)) === count($expectedIds)),
            wp_fts_wc_gate('oracle_terminal_page_reached', $expectedPages, (int) ceil(count($actualIds) / 20), count($actualIds) === count($expectedIds)),
            wp_fts_wc_gate('oracle_page_query_count', '<= 3', max($queryCounts ?: [PHP_INT_MAX]), max($queryCounts ?: [PHP_INT_MAX]) <= 3),
        ],
    ];
}

/**
 * Traverse enough broad-result pages to expose cursor duplication, omission,
 * deep-OFFSET regressions, or query-count growth.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_cursor_proof(WP_FTS_Searcher $searcher, array $manifest): array
{
    $profile = $manifest['profile'];
    $targetPages = $profile['name'] === '2k' ? 50 : 100;
    $definitions = wp_fts_wc_case_definitions($manifest);
    $definition = $definitions['common_or'];
    $baseOptions = wp_fts_wc_search_ready_options($definition['options']);
    $cursor = null;
    $ids = [];
    $cursorHashes = [];
    $pageObservations = [];
    $maxQueries = 0;
    $maxSql = 0;
    $totalSqlBytes = 0;
    $offsetStatements = 0;
    wp_fts_wc_assert($targetPages <= 100, 'Cursor evidence exceeds its 100-page bound.');
    for ($page = 0; $page < $targetPages; $page++) {
        $options = $baseOptions;
        if ($cursor !== null) {
            $options['cursor'] = $cursor;
        }
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $options));
        $payload = wp_fts_wc_payload($recorded['result']);
        $rows = wp_fts_wc_payload_results($payload);
        wp_fts_wc_assert(count($rows) === 20, "Cursor page {$page} did not contain exactly 20 results.");
        $pageIds = array_map('intval', array_column($rows, 'doc_id'));
        array_push($ids, ...$pageIds);
        $queries = array_values($recorded['queries']);
        wp_fts_wc_assert(count($queries) <= 16, "Cursor page {$page} exceeds its 16-statement evidence bound.");
        $maxQueries = max($maxQueries, count($queries));
        $pageOffsetStatements = 0;
        foreach ($queries as $sql) {
            $bytes = strlen($sql);
            wp_fts_wc_assert($bytes <= 1048576, "Cursor page {$page} contains SQL beyond its 1 MiB evidence bound.");
            $maxSql = max($maxSql, $bytes);
            $totalSqlBytes += $bytes;
            wp_fts_wc_assert($totalSqlBytes <= 16777216, 'Cursor SQL evidence exceeds its 16 MiB aggregate bound.');
            if (str_contains(strtoupper($sql), ' OFFSET ')) {
                $offsetStatements++;
                $pageOffsetStatements++;
            }
        }
        $cursor = isset($payload['next_cursor']) && is_scalar($payload['next_cursor']) ? (string) $payload['next_cursor'] : '';
        wp_fts_wc_assert($cursor !== '', "Cursor page {$page} did not provide another opaque cursor.");
        $cursorHash = hash('sha256', $cursor);
        $cursorHashes[] = $cursorHash;
        $pageObservations[] = [
            'page' => $page + 1,
            'result_ids' => $pageIds,
            'cursor_sha256' => $cursorHash,
            'query_count' => count($queries),
            'statement_shape' => wp_fts_wc_statement_shape(array_map(static fn(string $sql): array => ['sql' => $sql], $queries)),
            'statement_bytes' => array_map('strlen', $queries),
            'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
            'sql' => $queries,
            'offset_statement_count' => $pageOffsetStatements,
        ];
    }

    wp_fts_wc_assert(count($ids) <= 2000 && count($cursorHashes) <= 100 && count($pageObservations) <= 100, 'Cursor observations exceed their fixed vector bounds.');
    wp_fts_wc_assert_json_evidence_bytes($pageObservations, 33554432, 'Cursor page observations');

    $uniqueIds = count(array_unique($ids));
    $uniqueCursors = count(array_unique($cursorHashes));
    $prefix = wp_fts_wc_prefix_cursor_proof($searcher, $manifest);
    $security = wp_fts_wc_cursor_security_proof($searcher);
    return [
        'schema' => 'relational-fts-cursor-traversal-v1',
        'pages' => $targetPages,
        'rows' => count($ids),
        'unique_rows' => $uniqueIds,
        'unique_cursors' => $uniqueCursors,
        'result_ids' => $ids,
        'cursor_sha256' => $cursorHashes,
        'page_observations' => $pageObservations,
        'result_hash' => wp_fts_wc_canonical_hash($ids),
        'max_query_count' => $maxQueries,
        'max_sql_bytes' => $maxSql,
        'sql_total_bytes' => $totalSqlBytes,
        'offset_statements' => $offsetStatements,
        'prefix' => $prefix,
        'security' => $security,
        'gates' => [
            wp_fts_wc_gate('cursor_pages', $targetPages, $targetPages, true),
            wp_fts_wc_gate('cursor_unique_rows', count($ids), $uniqueIds, $uniqueIds === count($ids)),
            wp_fts_wc_gate('cursor_unique_tokens', $targetPages, $uniqueCursors, $uniqueCursors === $targetPages),
            wp_fts_wc_gate('cursor_query_count', '<= 3', $maxQueries, $maxQueries <= 3),
            wp_fts_wc_gate('cursor_sql_bytes', '<= 32768', $maxSql, $maxSql <= 32768),
            wp_fts_wc_gate('cursor_offset_statements', 0, $offsetStatements, $offsetStatements === 0),
            ...$prefix['gates'],
            ...$security['gates'],
        ],
    ];
}

/**
 * Prove exact prefix membership plus symmetric forward/reverse cursors.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_prefix_cursor_proof(WP_FTS_Searcher $searcher, array $manifest): array
{
    $definition = wp_fts_wc_case_definitions($manifest)['prefix_fanout'];
    $options = wp_fts_wc_search_ready_options($definition['options']);
    $first = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $options));
    $firstPayload = wp_fts_wc_payload($first['result']);
    $firstRows = wp_fts_wc_payload_results($firstPayload);
    $next = isset($firstPayload['next_cursor']) && is_scalar($firstPayload['next_cursor'])
        ? (string) $firstPayload['next_cursor']
        : '';
    wp_fts_wc_assert($next !== '', 'Prefix cursor proof did not receive a forward cursor.');

    $second = wp_fts_wc_record_queries(static fn() => $searcher->search(
        $definition['query'],
        $options + ['cursor' => $next, 'direction' => 'after']
    ));
    $secondPayload = wp_fts_wc_payload($second['result']);
    $secondRows = wp_fts_wc_payload_results($secondPayload);
    $previous = isset($secondPayload['previous_cursor']) && is_scalar($secondPayload['previous_cursor'])
        ? (string) $secondPayload['previous_cursor']
        : '';
    wp_fts_wc_assert($previous !== '', 'Prefix cursor proof did not receive a reverse cursor.');

    $reverse = wp_fts_wc_record_queries(static fn() => $searcher->search(
        $definition['query'],
        $options + ['cursor' => $previous, 'direction' => 'before']
    ));
    $reverseRows = wp_fts_wc_payload_results(wp_fts_wc_payload($reverse['result']));
    $firstIds = array_map('intval', array_column($firstRows, 'doc_id'));
    $secondIds = array_map('intval', array_column($secondRows, 'doc_id'));
    $reverseIds = array_map('intval', array_column($reverseRows, 'doc_id'));
    $allQueries = [...$first['queries'], ...$second['queries'], ...$reverse['queries']];
    $queryCounts = array_map(
        static fn(array $recorded): int => count($recorded['queries']),
        [$first, $second, $reverse]
    );
    $expectedNewestEnglish = (int) $manifest['last_post_id'] - 1;

    return [
        'first_ids' => $firstIds,
        'second_ids' => $secondIds,
        'reverse_ids' => $reverseIds,
        'expected_newest_completion_id' => $expectedNewestEnglish,
        'max_query_count' => max($queryCounts),
        'max_sql_bytes' => max(array_map('strlen', $allQueries) ?: [0]),
        'gates' => [
            wp_fts_wc_gate('prefix_cursor_surface_completion_membership', $expectedNewestEnglish, $firstIds[0] ?? null, ($firstIds[0] ?? null) === $expectedNewestEnglish),
            wp_fts_wc_gate('prefix_cursor_reverse_page_parity', $firstIds, $reverseIds, $firstIds === $reverseIds),
            wp_fts_wc_gate('prefix_cursor_forward_unique_rows', 40, count(array_unique([...$firstIds, ...$secondIds])), count($firstIds) === 20 && count($secondIds) === 20 && count(array_unique([...$firstIds, ...$secondIds])) === 40),
            wp_fts_wc_gate('prefix_cursor_total_query_count', '<= 3', max($queryCounts), max($queryCounts) <= 3),
        ],
    ];
}

/**
 * Traverse construction-known broad exact and prefix result sets through their
 * terminal pages. An independently populated relational oracle supplies 51-row
 * keyset windows while production supplies 50-row signed-cursor windows.
 * Neither side keeps full result rows in PHP or stops at a fixed page/sample
 * cap. The fixture covers the dirty-sized visible band plus 200 posts, bounding
 * terminal validation below a full-corpus traversal while separate warm cases
 * retain corpus-wide ranking pressure. The report retains a bounded JSONL
 * projection of each page's IDs and SQL measurements so aggregate hashes and
 * maxima can be recomputed from the final artifact.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_terminal_streaming_oracle(WP_FTS_Searcher $searcher, array $manifest): array
{
    global $wpdb;

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $workRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work before terminal streaming oracles');
    wp_fts_wc_assert($workRows === 0, 'Terminal streaming oracles require an empty work relation.');

    $oracleTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_wc_terminal_oracle');
    $wpdb->query("DROP TEMPORARY TABLE IF EXISTS `{$oracleTable}`");
    $created = $wpdb->query("CREATE TEMPORARY TABLE `{$oracleTable}` (
case_id VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
post_id BIGINT UNSIGNED NOT NULL,
score BIGINT SIGNED NOT NULL,
post_date_gmt DATETIME NOT NULL,
PRIMARY KEY (case_id,post_id),
KEY page_order (case_id,score,post_date_gmt,post_id)
) ENGINE=InnoDB");
    wp_fts_wc_assert($created !== false && trim((string) $wpdb->last_error) === '', 'Could not create the bounded terminal-oracle table.');

    try {
        wp_fts_wc_populate_terminal_oracle($oracleTable);
        $expectedRows = (int) $manifest['profile']['dirty'] + 200;
        $definitions = [
            'broad_exact' => [
                'query' => WP_FTS_WC_TERMINAL_QUERY_TERM,
                'options' => ['query_lang' => 'en', 'post_types' => ['post'], 'post_statuses' => ['publish'], 'limit' => 50, 'mode' => 'OR', 'prefix_matching' => false, 'include_snippets' => true, 'explain' => false],
            ],
            'broad_prefix' => [
                'query' => WP_FTS_WC_TERMINAL_QUERY_TERM,
                'options' => ['query_lang' => 'en', 'post_types' => ['post'], 'post_statuses' => ['publish'], 'limit' => 50, 'mode' => 'OR', 'prefix_matching' => true, 'prefix_min_length' => 4, 'include_snippets' => true, 'explain' => false],
            ],
        ];
        $cases = [];
        $gates = [wp_fts_wc_gate('terminal_oracle_initial_work_rows', 0, $workRows, $workRows === 0)];
        foreach ($definitions as $caseId => $definition) {
            $case = wp_fts_wc_traverse_terminal_oracle_case(
                $searcher,
                $oracleTable,
                $caseId,
                $definition,
                $expectedRows
            );
            $cases[$caseId] = $case;
            $minimumRows = in_array((string) $manifest['profile']['name'], ['50k', '100k'], true) ? 5000 : 40;
            array_push($gates,
                wp_fts_wc_gate("terminal_{$caseId}_full_membership_and_order", $case['expected_sha256'], $case['actual_sha256'], $case['completed'] && $case['expected_rows'] === $case['actual_rows'] && hash_equals($case['expected_sha256'], $case['actual_sha256'])),
                wp_fts_wc_gate("terminal_{$caseId}_terminal_page", $case['expected_pages'], $case['pages'], $case['completed'] && $case['pages'] === $case['expected_pages']),
                wp_fts_wc_gate("terminal_{$caseId}_uncapped_cardinality", "{$expectedRows} (> {$minimumRows})", $case['expected_rows'], $case['expected_rows'] === $expectedRows && $case['expected_rows'] > $minimumRows && $case['actual_rows'] === $expectedRows),
                wp_fts_wc_gate("terminal_{$caseId}_bounded_page_rows", '<= 50', $case['max_page_rows'], $case['max_page_rows'] <= 50),
                wp_fts_wc_gate("terminal_{$caseId}_hydrated_full_50_row_page", 50, $case['max_page_rows'], $case['max_page_rows'] === 50 && $case['statement_shapes_valid']),
                wp_fts_wc_gate("terminal_{$caseId}_query_count", 3, $case['max_query_count'], $case['statement_shapes_valid'] && $case['max_query_count'] === 3),
                wp_fts_wc_gate("terminal_{$caseId}_sql_bytes", '<= 32768', $case['max_sql_bytes'], $case['max_sql_bytes'] <= 32768),
                wp_fts_wc_gate("terminal_{$caseId}_offset_statements", 0, $case['offset_statements'], $case['offset_statements'] === 0),
                wp_fts_wc_gate("terminal_{$caseId}_bounded_php_memory", '<= 16777216', $case['max_memory_delta_bytes'], $case['max_memory_delta_bytes'] <= 16777216)
            );
        }

        return [
            'schema' => 'relational-fts-terminal-streaming-oracle-v1',
            'oracle_storage' => 'connection-local InnoDB temporary table',
            'page_size' => 50,
            'cases' => $cases,
            'gates' => $gates,
        ];
    } finally {
        $wpdb->query("DROP TEMPORARY TABLE IF EXISTS `{$oracleTable}`");
    }
}

/** Populate the independent SQL oracle used to verify complete cursor traversal. */
function wp_fts_wc_populate_terminal_oracle(string $oracleTable): void
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $exact = $wpdb->prepare(
        "INSERT INTO `{$oracleTable}` (case_id,post_id,score,post_date_gmt)
SELECT %s,po.post_id,MAX(po.impact * GREATEST(1,1000000 DIV GREATEST(1,t.doc_freq))),p.post_date_gmt
FROM `{$terms}` t
JOIN `{$postings}` po ON po.term_id=t.term_id
JOIN `{$documents}` d ON d.post_id=po.post_id
JOIN {$wpdb->posts} p ON p.ID=po.post_id
WHERE t.lang=%s AND t.kind=0 AND t.term=%s
  AND p.post_type='post' AND p.post_status='publish' AND p.post_password=''
GROUP BY po.post_id,p.post_date_gmt",
        'broad_exact',
        'en',
        WP_FTS_WC_TERMINAL_QUERY_TERM
    );
    $insertedExact = $wpdb->query($exact);
    wp_fts_wc_assert(is_int($insertedExact) && $insertedExact > 0 && trim((string) $wpdb->last_error) === '', 'Could not populate the broad exact terminal oracle.');

    $prefixLower = WP_FTS_WC_TERMINAL_QUERY_TERM;
    $prefixUpper = wp_fts_wc_binary_successor($prefixLower);
    wp_fts_wc_assert(is_string($prefixUpper), 'The terminal prefix oracle needs a finite binary successor.');
    $prefix = $wpdb->prepare(
        "INSERT INTO `{$oracleTable}` (case_id,post_id,score,post_date_gmt)
SELECT %s,raw.post_id,MAX(raw.group_score),p.post_date_gmt
FROM (
    SELECT epo.post_id,epo.impact * GREATEST(1,1000000 DIV GREATEST(1,et.doc_freq)) group_score
    FROM `{$terms}` et
    JOIN `{$postings}` epo ON epo.term_id=et.term_id
    WHERE et.lang=%s AND et.kind=0 AND et.term=%s
    UNION ALL
    SELECT ppo.post_id,CAST(ppo.impact * CAST(1000000 / CASE WHEN pt.doc_freq<1 THEN 1 ELSE pt.doc_freq END AS SIGNED) * 600 / 1000 AS SIGNED) group_score
    FROM `{$terms}` pt
    JOIN `{$postings}` ppo ON ppo.term_id=pt.term_id
    WHERE pt.lang=%s AND pt.kind=1 AND pt.term>=%s AND pt.term<%s
) raw
JOIN `{$documents}` d ON d.post_id=raw.post_id
JOIN {$wpdb->posts} p ON p.ID=raw.post_id
WHERE p.post_type='post' AND p.post_status='publish' AND p.post_password=''
GROUP BY raw.post_id,p.post_date_gmt",
        'broad_prefix',
        'en',
        WP_FTS_WC_TERMINAL_QUERY_TERM,
        'en',
        $prefixLower,
        $prefixUpper
    );
    $insertedPrefix = $wpdb->query($prefix);
    wp_fts_wc_assert(is_int($insertedPrefix) && $insertedPrefix > 0 && trim((string) $wpdb->last_error) === '', 'Could not populate the broad prefix terminal oracle.');
}

/**
 * @param array{query:string,options:array<string,mixed>} $definition
 * @return array<string,mixed>
 */
function wp_fts_wc_traverse_terminal_oracle_case(WP_FTS_Searcher $searcher, string $oracleTable, string $caseId, array $definition, int $maxEvidenceRows): array
{
    global $wpdb;

    wp_fts_wc_assert($maxEvidenceRows > 0 && $maxEvidenceRows <= 100000, "{$caseId} terminal evidence row bound is outside the supported corpus envelope.");
    $expectedTotal = wp_fts_wc_checked_count(
        $wpdb->prepare("SELECT COUNT(*) FROM `{$oracleTable}` WHERE case_id=%s", $caseId),
        "{$caseId} terminal-oracle rows"
    );
    wp_fts_wc_assert($expectedTotal > 0, "{$caseId} terminal oracle is empty.");
    wp_fts_wc_assert($expectedTotal <= $maxEvidenceRows, "{$caseId} terminal oracle exceeds its manifest-bound evidence envelope.");
    $expectedPages = (int) ceil($expectedTotal / 50);
    wp_fts_wc_assert($expectedPages <= 2000, "{$caseId} terminal oracle exceeds its 2,000-page evidence bound.");
    $expectedContext = hash_init('sha256');
    $actualContext = hash_init('sha256');
    $actualCursor = '';
    $expectedCursor = null;
    $actualRowsSeen = 0;
    $expectedRowsSeen = 0;
    $pages = 0;
    $maxQueries = 0;
    $maxSqlBytes = 0;
    $maxPageRows = 0;
    $offsetStatements = 0;
    $statementShapesValid = true;
    $completed = true;
    $firstMismatch = null;
    $pageObservationsJsonl = '';
    $memoryBaseline = memory_get_usage(true);
    $maxMemoryDelta = 0;
    $baseOptions = wp_fts_wc_search_ready_options($definition['options']);

    for ($page = 0; $page < $expectedPages; $page++) {
        if ($expectedCursor === null) {
            $expectedSql = $wpdb->prepare(
                "SELECT post_id,score,post_date_gmt FROM `{$oracleTable}` WHERE case_id=%s ORDER BY score DESC,post_date_gmt DESC,post_id DESC LIMIT 51",
                $caseId
            );
        } else {
            $expectedSql = $wpdb->prepare(
                "SELECT post_id,score,post_date_gmt FROM `{$oracleTable}` WHERE case_id=%s AND (score<%d OR (score=%d AND post_date_gmt<%s) OR (score=%d AND post_date_gmt=%s AND post_id<%d)) ORDER BY score DESC,post_date_gmt DESC,post_id DESC LIMIT 51",
                $caseId,
                $expectedCursor['score'],
                $expectedCursor['score'],
                $expectedCursor['date'],
                $expectedCursor['score'],
                $expectedCursor['date'],
                $expectedCursor['post_id']
            );
        }
        $expectedWindow = $wpdb->get_results($expectedSql, ARRAY_A);
        wp_fts_wc_assert(is_array($expectedWindow) && $expectedWindow !== [] && trim((string) $wpdb->last_error) === '', "Could not read {$caseId} terminal-oracle keyset page {$page}.");
        $expectedHasMore = count($expectedWindow) > 50;
        $expectedPage = array_slice($expectedWindow, 0, 50);
        $expectedIds = array_map(static fn(array $row): int => (int) $row['post_id'], $expectedPage);

        $options = $baseOptions;
        if ($actualCursor !== '') {
            $options['cursor'] = $actualCursor;
        }
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $options));
        $payload = wp_fts_wc_payload($recorded['result']);
        $actualPage = wp_fts_wc_payload_results($payload);
        $actualIds = array_map('intval', array_column($actualPage, 'doc_id'));
        $actualHasMore = !empty($payload['has_more']);
        $nextCursor = isset($payload['next_cursor']) && is_scalar($payload['next_cursor']) ? (string) $payload['next_cursor'] : '';
        $queries = array_values($recorded['queries']);
        wp_fts_wc_assert(count($queries) <= 16, "{$caseId} terminal page {$page} exceeds its 16-statement evidence bound.");
        $shape = wp_fts_wc_statement_shape(array_map(static fn(string $sql): array => ['sql' => $sql], $queries));
        $statementShapesValid = $statementShapesValid && $shape === ['plan' => 1, 'rank' => 1, 'hydrate' => 1];
        $maxQueries = max($maxQueries, count($queries));
        $maxPageRows = max($maxPageRows, count($actualIds), count($expectedIds));
        $pageOffsetStatements = 0;
        foreach ($queries as $sql) {
            $sqlBytes = strlen($sql);
            wp_fts_wc_assert($sqlBytes <= 1048576, "{$caseId} terminal page {$page} contains SQL beyond its 1 MiB evidence bound.");
            $maxSqlBytes = max($maxSqlBytes, $sqlBytes);
            if (str_contains(strtoupper($sql), ' OFFSET ')) {
                $offsetStatements++;
                $pageOffsetStatements++;
            }
        }
        foreach ($expectedIds as $id) {
            wp_fts_wc_signature_update($expectedContext, [$id]);
        }
        foreach ($actualIds as $id) {
            wp_fts_wc_signature_update($actualContext, [$id]);
        }
        $expectedRowsSeen += count($expectedIds);
        $actualRowsSeen += count($actualIds);
        $pages++;
        $pageObservation = [
            'page' => $page + 1,
            'expected_ids' => $expectedIds,
            'actual_ids' => $actualIds,
            'expected_has_more' => $expectedHasMore,
            'actual_has_more' => $actualHasMore,
            'next_cursor_present' => $nextCursor !== '',
            'cursor_sha256' => $nextCursor === '' ? null : hash('sha256', $nextCursor),
            'query_count' => count($queries),
            'statement_shape' => $shape,
            'statement_bytes' => array_map('strlen', $queries),
            'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
            'offset_statement_count' => $pageOffsetStatements,
        ];
        $pageObservationLine = json_encode($pageObservation, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR) . "\n";
        wp_fts_wc_assert(strlen($pageObservationLine) <= 65536, "{$caseId} terminal page {$page} observation exceeds 64 KiB.");
        $pageObservationsJsonl .= $pageObservationLine;
        wp_fts_wc_assert(strlen($pageObservationsJsonl) <= 16777216, "{$caseId} terminal page observations exceed 16 MiB.");
        $maxMemoryDelta = max($maxMemoryDelta, max(0, memory_get_usage(true) - $memoryBaseline));

        if ($actualIds !== $expectedIds || $actualHasMore !== $expectedHasMore || ($expectedHasMore && $nextCursor === '') || (!$expectedHasMore && $nextCursor !== '')) {
            $completed = false;
            $firstMismatch = [
                'page' => $page,
                'expected_ids' => $expectedIds,
                'actual_ids' => $actualIds,
                'expected_has_more' => $expectedHasMore,
                'actual_has_more' => $actualHasMore,
                'next_cursor_present' => $nextCursor !== '',
            ];
            break;
        }

        $lastExpected = $expectedPage[array_key_last($expectedPage)];
        $expectedCursor = [
            'score' => (int) $lastExpected['score'],
            'date' => (string) $lastExpected['post_date_gmt'],
            'post_id' => (int) $lastExpected['post_id'],
        ];
        $actualCursor = $nextCursor;
    }

    $expectedHash = hash_final($expectedContext);
    $actualHash = hash_final($actualContext);
    $completed = $completed
        && $pages === $expectedPages
        && $expectedRowsSeen === $expectedTotal
        && $actualRowsSeen === $expectedTotal
        && hash_equals($expectedHash, $actualHash);

    return [
        'expected_rows' => $expectedTotal,
        'actual_rows' => $actualRowsSeen,
        'expected_pages' => $expectedPages,
        'pages' => $pages,
        'expected_sha256' => $expectedHash,
        'actual_sha256' => $actualHash,
        'page_observations_format' => 'relational-fts-terminal-pages-jsonl-v1',
        'page_observations_bytes' => strlen($pageObservationsJsonl),
        'page_observations_sha256' => hash('sha256', $pageObservationsJsonl),
        'page_observations_jsonl' => $pageObservationsJsonl,
        'completed' => $completed,
        'first_mismatch' => $firstMismatch,
        'max_page_rows' => $maxPageRows,
        'max_query_count' => $maxQueries,
        'statement_shapes_valid' => $statementShapesValid,
        'max_sql_bytes' => $maxSqlBytes,
        'offset_statements' => $offsetStatements,
        'max_memory_delta_bytes' => $maxMemoryDelta,
    ];
}

/**
 * Bind cursors to the full query scope and freeze recency scoring to the
 * signed first-page epoch. Invalid tokens must fail before ranking SQL.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_cursor_security_proof(WP_FTS_Searcher $searcher): array
{
    $query = 'commonalpha commonbeta commongamma';
    $options = wp_fts_wc_search_ready_options([
        'query_lang' => 'en',
        'post_types' => ['post'],
        'post_statuses' => ['publish'],
        'limit' => 20,
        'mode' => 'OR',
        'prefix_matching' => false,
        'recency_boost_strength' => 1.25,
        'recency_boost_half_life_days' => 30,
    ]);
    $firstRuntimeBefore = gmdate('Y-m-d H:i:s');
    $first = wp_fts_wc_payload($searcher->search($query, $options));
    $firstRuntimeAfter = gmdate('Y-m-d H:i:s');
    $cursor = isset($first['next_cursor']) && is_scalar($first['next_cursor']) ? (string) $first['next_cursor'] : '';
    wp_fts_wc_assert($cursor !== '', 'Recency cursor proof did not receive a signed cursor.');
    $payloadNow = wp_fts_wc_cursor_payload_now($cursor);

    $originalClock = wp_fts_wc_payload($searcher->search($query, $options + ['cursor' => $cursor, 'direction' => 'after']));
    $clockDeadline = microtime(true) + 2.0;
    do {
        usleep(100000);
        $laterRuntimeNow = gmdate('Y-m-d H:i:s');
    } while ($laterRuntimeNow === $payloadNow && microtime(true) < $clockDeadline);
    wp_fts_wc_assert($laterRuntimeNow > $payloadNow, 'Recency cursor proof could not observe a later runtime clock second.');
    $laterClock = wp_fts_wc_payload($searcher->search($query, $options + ['cursor' => $cursor, 'direction' => 'after']));
    $originalRows = wp_fts_wc_payload_results($originalClock);
    $laterRows = wp_fts_wc_payload_results($laterClock);
    $laterCursor = isset($laterClock['next_cursor']) && is_scalar($laterClock['next_cursor']) ? (string) $laterClock['next_cursor'] : '';
    wp_fts_wc_assert($laterCursor !== '', 'Recency cursor proof did not receive a later-page cursor.');
    $laterCursorNow = wp_fts_wc_cursor_payload_now($laterCursor);

    // Alter a significant base64 sextet, not a trailing sextet whose only
    // changed bits could be discarded as padding by a permissive decoder.
    $tampered = ($cursor[0] === 'A' ? 'B' : 'A') . substr($cursor, 1);
    $rejections = [
        'tampered' => wp_fts_wc_cursor_rejection($searcher, $query, $options + ['cursor' => $tampered, 'direction' => 'after']),
        'query' => wp_fts_wc_cursor_rejection($searcher, 'commonbeta commonalpha', $options + ['cursor' => $cursor, 'direction' => 'after']),
        'mode' => wp_fts_wc_cursor_rejection($searcher, $query, array_replace($options, ['cursor' => $cursor, 'direction' => 'after', 'mode' => 'AND'])),
        'post_types' => wp_fts_wc_cursor_rejection($searcher, $query, array_replace($options, ['cursor' => $cursor, 'direction' => 'after', 'post_types' => ['post', 'page']])),
        'post_statuses' => wp_fts_wc_cursor_rejection($searcher, $query, array_replace($options, ['cursor' => $cursor, 'direction' => 'after', 'post_statuses' => ['publish', 'draft']])),
        'date' => wp_fts_wc_cursor_rejection($searcher, $query, $options + ['cursor' => $cursor, 'direction' => 'after', 'date_before' => '2024-01-01 12:00:00']),
        'prefix' => wp_fts_wc_cursor_rejection($searcher, $query, array_replace($options, ['cursor' => $cursor, 'direction' => 'after', 'prefix_matching' => true])),
    ];
    $allRejected = count(array_filter($rejections, static fn(array $result): bool => $result['rejected'])) === count($rejections);
    $rankStatements = array_sum(array_column($rejections, 'rank_statement_count'));

    return [
        'first_runtime_window_gmt' => [$firstRuntimeBefore, $firstRuntimeAfter],
        'cursor_now_gmt' => $payloadNow,
        'later_runtime_now_gmt' => $laterRuntimeNow,
        'later_cursor_now_gmt' => $laterCursorNow,
        'original_page_hash' => wp_fts_wc_result_hash($originalRows),
        'later_clock_page_hash' => wp_fts_wc_result_hash($laterRows),
        'rejections' => $rejections,
        'gates' => [
            wp_fts_wc_gate('cursor_signed_recency_epoch', [$firstRuntimeBefore, $firstRuntimeAfter], $payloadNow, $payloadNow >= $firstRuntimeBefore && $payloadNow <= $firstRuntimeAfter),
            wp_fts_wc_gate('cursor_recency_epoch_frozen', [$payloadNow, wp_fts_wc_result_hash($originalRows)], [$laterCursorNow, wp_fts_wc_result_hash($laterRows)], $laterCursorNow === $payloadNow && wp_fts_wc_result_hash($originalRows) === wp_fts_wc_result_hash($laterRows)),
            wp_fts_wc_gate('cursor_scope_replays_rejected', count($rejections), count(array_filter($rejections, static fn(array $result): bool => $result['rejected'])), $allRejected),
            wp_fts_wc_gate('cursor_invalid_replays_rank_statements', 0, $rankStatements, $rankStatements === 0),
        ],
    ];
}

/** @return array{rejected:bool,error_class:string,error_message:string,rank_statement_count:int,total_statement_count:int} */
function wp_fts_wc_cursor_rejection(WP_FTS_Searcher $searcher, string $query, array $options): array
{
    $errorClass = '';
    $errorMessage = '';
    $recorded = wp_fts_wc_record_queries(static function () use ($searcher, $query, $options, &$errorClass, &$errorMessage): void {
        try {
            $searcher->search($query, $options);
        } catch (InvalidArgumentException $error) {
            $errorClass = get_class($error);
            $errorMessage = $error->getMessage();
        }
    });
    $rankStatements = count(array_filter($recorded['queries'], static fn(string $sql): bool => str_contains(strtolower($sql), 'wp_fts:rank')));

    return [
        'rejected' => $errorClass !== '',
        'error_class' => $errorClass,
        'error_message' => $errorMessage,
        'rank_statement_count' => $rankStatements,
        'total_statement_count' => count($recorded['queries']),
    ];
}

/** Read the signed scoring epoch solely to construct scope-replay rejection cases. */
function wp_fts_wc_cursor_payload_now(string $cursor): string
{
    $padding = (4 - strlen($cursor) % 4) % 4;
    $decoded = base64_decode(strtr($cursor . str_repeat('=', $padding), '-_', '+/'), true);
    if (!is_string($decoded) || !str_contains($decoded, '.')) {
        throw new RuntimeException('Could not decode the signed cursor evidence payload.');
    }
    [$json] = explode('.', $decoded, 2);
    $payload = json_decode($json, true, 16, JSON_THROW_ON_ERROR);

    return is_array($payload) && is_string($payload['n'] ?? null) ? $payload['n'] : '';
}

/**
 * Prove foreground writes only enqueue bounded durable work and never analyze or
 * mutate the posting index inline.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_write_path_proof(array $manifest): array
{
    global $wpdb;

    WP_FTS_Plugin::flush_foreground_bulk_mutations();
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $workRowsBefore = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work before unchanged-requeue proof');
    wp_fts_wc_assert($workRowsBefore === 0, 'The unchanged-requeue proof requires an empty work queue.');
    $first = (int) $manifest['first_post_id'] + (int) $manifest['profile']['hidden'] + 250;
    $ids = range($first, min((int) $manifest['last_post_id'], $first + 99));
    wp_fts_wc_assert(count($ids) === 100, 'Write-path proof requires 100 public corpus posts.');
    $mutationPostId = (int) $manifest['last_post_id'] - (int) $manifest['profile']['rare'] - 250;
    wp_fts_wc_assert(!in_array($mutationPostId, $ids, true), 'Actual-save fixture overlaps the unchanged-requeue batch.');
    $mutationPost = get_post($mutationPostId);
    wp_fts_wc_assert(
        is_object($mutationPost)
            && (string) ($mutationPost->post_status ?? '') === 'publish'
            && (string) ($mutationPost->post_password ?? '') === '',
        'Actual-save proof requires a public, unpassworded canonical post.'
    );
    $originalExcerpt = (string) ($mutationPost->post_excerpt ?? '');
    $mutationToken = 'wpftsactualsave' . substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')), 0, 12);
    $indexerSignatures = wp_fts_wc_indexer_signature_evidence();
    $claimIndexOptions = wp_fts_wc_claim_index_options_preload_proof($ids[0]);
    $singlePostingKindsBefore = wp_fts_wc_document_posting_kind_counts($mutationPostId);
    $memoryBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $singleStarted = hrtime(true);
    $single = wp_fts_wc_record_queries(static fn() => wp_update_post([
        'ID' => $mutationPostId,
        'post_excerpt' => $originalExcerpt . ' ' . $mutationToken,
    ], true));
    $singleMs = wp_fts_wc_elapsed_ms($singleStarted);
    wp_fts_wc_assert(
        is_int($single['result']) && $single['result'] === $mutationPostId,
        'The real wp_update_post() mutation did not commit its canonical row.'
    );
    // The save, restoration, metadata mutations, and bulk invalidation model
    // separate foreground requests, so each shutdown handoff runs before its worker.
    WP_FTS_Plugin::flush_foreground_bulk_mutations();
    $singleFts = array_values(array_filter($single['queries'], 'wp_fts_wc_is_search_statement'));
    $singleBoundaries = array_values(array_filter(
        $singleFts,
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence')
            || str_contains($sql, 'wp_fts:mutation-promote')
    ));
    $singleSchema = array_values(array_filter($single['queries'], 'wp_fts_wc_is_fts_physical_schema_statement'));
    $singleRow = $wpdb->get_row($wpdb->prepare(
        "SELECT generation,state,claim_token,claimed_generation FROM `{$work}` WHERE kind='post' AND post_id=%d",
        $mutationPostId
    ), ARRAY_A);
    $singleWorkerRecorded = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::process_manual_index_batch([
        'source' => 'worst-case-actual-save',
        'batch_size' => 100,
        'time_budget' => 300.0,
    ]));
    $singleWorker = is_array($singleWorkerRecorded['result']) ? $singleWorkerRecorded['result'] : [];
    $singleWorkerStatements = $singleWorkerRecorded['queries'];
    $singleWorkerRoles = wp_fts_wc_worker_statement_roles($singleWorkerStatements);
    $singlePostingKindsAfter = wp_fts_wc_document_posting_kind_counts($mutationPostId);
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $singleLanguage = (string) $wpdb->get_var($wpdb->prepare(
        "SELECT primary_lang FROM `{$documents}` WHERE post_id=%d",
        $mutationPostId
    ));
    wp_fts_wc_assert($singleLanguage !== '', 'The actual-save worker did not publish a document language.');
    $singleSearch = WP_FTS_Plugin::search($mutationToken, [
        'lang' => $singleLanguage,
        'mode' => 'OR',
        'limit' => 20,
        'prefix_matching' => false,
    ]);
    $singleSearchIds = array_map('intval', array_column($singleSearch, 'doc_id'));

    $restore = wp_fts_wc_record_queries(static fn() => wp_update_post([
        'ID' => $mutationPostId,
        'post_excerpt' => $originalExcerpt,
    ], true));
    wp_fts_wc_assert(
        is_int($restore['result']) && $restore['result'] === $mutationPostId,
        'The real wp_update_post() cleanup did not restore its canonical row.'
    );
    WP_FTS_Plugin::flush_foreground_bulk_mutations();
    $restoreFts = array_values(array_filter($restore['queries'], 'wp_fts_wc_is_search_statement'));
    $restoreBoundaries = array_values(array_filter(
        $restoreFts,
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence')
            || str_contains($sql, 'wp_fts:mutation-promote')
    ));
    $restoreWorkerRecorded = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::process_manual_index_batch([
        'source' => 'worst-case-actual-save-restore',
        'batch_size' => 100,
        'time_budget' => 300.0,
    ]));
    $restoreWorker = is_array($restoreWorkerRecorded['result']) ? $restoreWorkerRecorded['result'] : [];
    $restoreWorkerStatements = $restoreWorkerRecorded['queries'];
    $restoreWorkerRoles = wp_fts_wc_worker_statement_roles($restoreWorkerStatements);
    $singlePostingKindsRestored = wp_fts_wc_document_posting_kind_counts($mutationPostId);
    $restoredPost = get_post($mutationPostId);
    $restoredSearch = WP_FTS_Plugin::search($mutationToken, [
        'lang' => 'en',
        'mode' => 'OR',
        'limit' => 20,
        'prefix_matching' => false,
    ]);
    $metadataEvidence = wp_fts_wc_real_metadata_mutation_proof($mutationPostId + 1);

    // The synthetic corpus is built in the exact `en` partition, while normal
    // WordPress writes resolve the site's `en-US` locale. Normalize this batch
    // through the production worker before proving that later requeues skip it.
    $queue = new WP_FTS_Index_Queue($wpdb);
    wp_fts_wc_assert($queue->enqueue_many($ids) === count($ids), 'Could not normalize the unchanged-requeue fixture.');
    $normalization = WP_FTS_Plugin::process_manual_index_batch([
        'source' => 'worst-case-unchanged-baseline',
        'batch_size' => 100,
        'time_budget' => 300.0,
    ]);
    wp_fts_wc_assert(
        is_array($normalization)
            && (int) ($normalization['attempted'] ?? -1) === count($ids)
            && (int) ($normalization['committed'] ?? -1) === count($ids)
            && wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work after unchanged-requeue normalization') === 0,
        'Could not publish the normalized unchanged-requeue fixture.'
    );
    $unchangedIndexBefore = wp_fts_wc_document_index_signatures($ids);

    $bulkStarted = hrtime(true);
    $queue = new WP_FTS_Index_Queue($wpdb);
    $bulk = wp_fts_wc_record_queries(static function () use ($queue, $ids): void {
        $queue->enqueue_many($ids);
    });
    WP_FTS_Plugin::flush_foreground_bulk_mutations();
    $bulkMs = wp_fts_wc_elapsed_ms($bulkStarted);
    $bulkFts = array_values(array_filter($bulk['queries'], 'wp_fts_wc_is_search_statement'));

    $repeatStarted = hrtime(true);
    $repeat = wp_fts_wc_record_queries(static function () use ($queue, $ids): void {
        for ($iteration = 0; $iteration < 1000; $iteration++) {
            $queue->enqueue_many([$ids[$iteration % 10]]);
        }
    });
    $repeatMs = wp_fts_wc_elapsed_ms($repeatStarted);
    $repeatDataStatements = array_values(array_filter($repeat['queries'], static function (string $sql): bool {
        $lower = strtolower($sql);
        return str_contains($lower, 'fts_terms') || str_contains($lower, 'fts_postings') || str_contains($lower, 'fts_documents');
    }));

    $workRowsQueued = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'coalesced work before unchanged-requeue worker');
    $unchangedWorker = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::process_manual_index_batch([
        'source' => 'worst-case-unchanged-requeues',
        'batch_size' => 100,
        'time_budget' => 300.0,
    ]));
    $unchangedSummary = is_array($unchangedWorker['result']) ? $unchangedWorker['result'] : [];
    $workRowsAfter = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work after unchanged-requeue proof');
    $unchangedStatements = $unchangedWorker['queries'];
    $unchangedRoles = wp_fts_wc_worker_statement_roles($unchangedStatements);
    $unchangedIndexDataWrites = array_values(array_filter($unchangedStatements, 'wp_fts_wc_is_index_data_mutation_statement'));
    $unchangedIndexAfter = wp_fts_wc_document_index_signatures($ids);

    $singleWorkOnly = count($singleFts) === 2
        && count($singleBoundaries) === 2
        && count(array_filter($singleBoundaries, static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence'))) === 1
        && count(array_filter($singleBoundaries, static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-promote'))) === 1
        && count(array_filter($singleFts, static fn(string $sql): bool => !str_contains(strtolower($sql), 'fts_work'))) === 0;
    $bulkWorkOnly = count($bulkFts) === 1 && str_contains(strtolower($bulkFts[0]), 'fts_work');
    return [
        'single_save' => [
            'api' => 'wp_update_post',
            'post_id' => $mutationPostId,
            'duration_ms' => $singleMs,
            'statement_count' => count($singleFts),
            'sql_bytes' => array_map('strlen', $singleFts),
            'sql' => $singleFts,
            'row_after_commit' => $singleRow,
            'worker_summary' => $singleWorker,
            'worker_statement_count' => count($singleWorkerStatements),
            'worker_statement_roles' => $singleWorkerRoles,
            'worker_max_statement_bytes' => max(array_map('strlen', $singleWorkerStatements) ?: [0]),
            'posting_kinds_before' => $singlePostingKindsBefore,
            'posting_kinds_after' => $singlePostingKindsAfter,
            'result_ids' => $singleSearchIds,
            'restore_statement_count' => count($restoreFts),
            'restore_sql_bytes' => array_map('strlen', $restoreFts),
            'restore_worker_summary' => $restoreWorker,
            'restore_worker_statement_count' => count($restoreWorkerStatements),
            'restore_worker_statement_roles' => $restoreWorkerRoles,
            'restore_worker_max_statement_bytes' => max(array_map('strlen', $restoreWorkerStatements) ?: [0]),
            'posting_kinds_restored' => $singlePostingKindsRestored,
            'memory_delta_bytes' => max(0, memory_get_usage(true) - $memoryBefore),
            'rss_delta_bytes' => max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore),
        ],
        'metadata_mutations' => $metadataEvidence,
        'claim_index_options_preload' => $claimIndexOptions,
        'bulk_100' => ['duration_ms' => $bulkMs, 'statement_count' => count($bulkFts), 'sql_bytes' => array_map('strlen', $bulkFts)],
        'unchanged_requeues_1000' => [
            'duration_ms' => $repeatMs,
            'foreground_statement_count' => count($repeat['queries']),
            'foreground_index_data_statement_count' => count($repeatDataStatements),
            'unique_work_rows' => $workRowsQueued,
            'worker_summary' => $unchangedSummary,
            'worker_statement_count' => count($unchangedStatements),
            'worker_statement_roles' => $unchangedRoles,
            'worker_max_statement_bytes' => max(array_map('strlen', $unchangedStatements) ?: [0]),
            'index_data_write_statement_count' => count($unchangedIndexDataWrites),
            'index_signatures_before' => $unchangedIndexBefore,
            'index_signatures_after' => $unchangedIndexAfter,
            'remaining_work_rows' => $workRowsAfter,
        ],
        'gates' => [
            wp_fts_wc_gate('actual_save_boundary_upsert_count', 2, count($singleFts), $singleWorkOnly),
            wp_fts_wc_gate('actual_save_fence_ready_after_commit', 'ready with cleared token', $singleRow, is_array($singleRow) && ($singleRow['state'] ?? null) === 'ready' && ($singleRow['claim_token'] ?? null) === '' && (int) ($singleRow['claimed_generation'] ?? -1) === 0),
            wp_fts_wc_gate('actual_save_duration_ms', '<= 500', $singleMs, $singleMs <= 500.0),
            wp_fts_wc_gate('actual_save_max_statement_bytes', '<= 1048576', max(array_map('strlen', $singleFts) ?: [PHP_INT_MAX]), $singleFts !== [] && max(array_map('strlen', $singleFts)) <= 1048576),
            wp_fts_wc_gate('actual_save_physical_schema_statements', 0, count($singleSchema), $singleSchema === []),
            wp_fts_wc_gate('actual_save_worker_attempted', 1, (int) ($singleWorker['attempted'] ?? -1), (int) ($singleWorker['attempted'] ?? -1) === 1),
            wp_fts_wc_gate('actual_save_worker_committed', 1, (int) ($singleWorker['committed'] ?? -1), (int) ($singleWorker['committed'] ?? -1) === 1),
            wp_fts_wc_gate('actual_save_worker_analyzed', 1, (int) ($singleWorker['analyzed'] ?? -1), (int) ($singleWorker['analyzed'] ?? -1) === 1),
            wp_fts_wc_gate('actual_save_worker_statement_count', '<= 20 all wpdb statements', count($singleWorkerStatements), $singleWorkerRoles['unknown'] === [] && count($singleWorkerStatements) <= 20),
            wp_fts_wc_gate('actual_save_worker_data_statement_count', '<= 15', count($singleWorkerRoles['data_roles']), $singleWorkerRoles['data_roles'] !== [] && count($singleWorkerRoles['data_roles']) <= 15),
            wp_fts_wc_gate('actual_save_worker_lease_controls', ['lease_acquire', 'lease_release'], $singleWorkerRoles['lease_control_roles'], $singleWorkerRoles['lease_control_roles'] === ['lease_acquire', 'lease_release']),
            wp_fts_wc_gate('actual_save_worker_transaction_controls', ['transaction_start', 'transaction_commit'], $singleWorkerRoles['transaction_roles'], $singleWorkerRoles['transaction_roles'] === ['transaction_start', 'transaction_commit'] && wp_fts_wc_worker_roles_are_ordered($singleWorkerRoles['roles'])),
            wp_fts_wc_gate('actual_save_worker_statement_bytes', '<= 4194304', max(array_map('strlen', $singleWorkerStatements) ?: [PHP_INT_MAX]), $singleWorkerStatements !== [] && max(array_map('strlen', $singleWorkerStatements)) <= 4194304),
            wp_fts_wc_gate('actual_save_surface_write_amplification_measured', 'one normalized-surface row per new distinct source surface inside the 8,192-row document envelope', ['before' => $singlePostingKindsBefore, 'after' => $singlePostingKindsAfter], $singlePostingKindsBefore['surface'] > 0 && $singlePostingKindsAfter['surface'] > $singlePostingKindsBefore['surface'] && $singlePostingKindsAfter['total'] > $singlePostingKindsBefore['total'] && $singlePostingKindsAfter['total'] <= WP_FTS_Relational_Storage::MAX_DOCUMENT_POSTINGS),
            wp_fts_wc_gate('actual_save_searchable_after_worker', [$mutationPostId], $singleSearchIds, $singleSearchIds === [$mutationPostId]),
            wp_fts_wc_gate('actual_save_restore_boundary_upsert_count', 2, count($restoreFts), count($restoreFts) === 2 && count($restoreBoundaries) === 2),
            wp_fts_wc_gate('actual_save_restore_worker_committed', 1, (int) ($restoreWorker['committed'] ?? -1), (int) ($restoreWorker['committed'] ?? -1) === 1),
            wp_fts_wc_gate('actual_save_restore_worker_statement_count', '<= 20 all wpdb statements', count($restoreWorkerStatements), $restoreWorkerRoles['unknown'] === [] && count($restoreWorkerStatements) <= 20),
            wp_fts_wc_gate('actual_save_restore_worker_data_statement_count', '<= 15', count($restoreWorkerRoles['data_roles']), $restoreWorkerRoles['data_roles'] !== [] && count($restoreWorkerRoles['data_roles']) <= 15),
            wp_fts_wc_gate('actual_save_restore_worker_lease_controls', ['lease_acquire', 'lease_release'], $restoreWorkerRoles['lease_control_roles'], $restoreWorkerRoles['lease_control_roles'] === ['lease_acquire', 'lease_release']),
            wp_fts_wc_gate('actual_save_restore_worker_transaction_controls', ['transaction_start', 'transaction_commit'], $restoreWorkerRoles['transaction_roles'], $restoreWorkerRoles['transaction_roles'] === ['transaction_start', 'transaction_commit'] && wp_fts_wc_worker_roles_are_ordered($restoreWorkerRoles['roles'])),
            wp_fts_wc_gate('actual_save_restore_worker_statement_bytes', '<= 4194304', max(array_map('strlen', $restoreWorkerStatements) ?: [PHP_INT_MAX]), $restoreWorkerStatements !== [] && max(array_map('strlen', $restoreWorkerStatements)) <= 4194304),
            wp_fts_wc_gate('actual_save_surface_rows_restored', $singlePostingKindsBefore, $singlePostingKindsRestored, $singlePostingKindsRestored === $singlePostingKindsBefore),
            wp_fts_wc_gate('actual_save_canonical_restore', $originalExcerpt, is_object($restoredPost) ? (string) ($restoredPost->post_excerpt ?? '') : null, is_object($restoredPost) && (string) ($restoredPost->post_excerpt ?? '') === $originalExcerpt),
            wp_fts_wc_gate('actual_save_index_restore', [], array_map('intval', array_column($restoredSearch, 'doc_id')), $restoredSearch === []),
            wp_fts_wc_gate('actual_save_php_delta', '<= 16777216', max(0, memory_get_usage(true) - $memoryBefore), max(0, memory_get_usage(true) - $memoryBefore) <= 16777216),
            wp_fts_wc_gate('actual_save_rss_delta', '<= 16777216', max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore), max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore) <= 16777216),
            wp_fts_wc_gate('bulk_100_work_upsert_count', 1, count($bulkFts), $bulkWorkOnly),
            wp_fts_wc_gate('bulk_100_duration_ms', '<= 500', $bulkMs, $bulkMs <= 500.0),
            wp_fts_wc_gate('unchanged_requeues_foreground_index_data_statements', 0, count($repeatDataStatements), $repeatDataStatements === []),
            wp_fts_wc_gate('unchanged_requeues_coalesced_work_rows', 100, $workRowsQueued, $workRowsQueued === 100),
            wp_fts_wc_gate('unchanged_requeues_worker_attempted', 100, (int) ($unchangedSummary['attempted'] ?? -1), (int) ($unchangedSummary['attempted'] ?? -1) === 100),
            wp_fts_wc_gate('unchanged_requeues_worker_not_reindexed', 0, (int) ($unchangedSummary['indexed'] ?? -1), (int) ($unchangedSummary['indexed'] ?? -1) === 0),
            wp_fts_wc_gate('unchanged_requeues_worker_acknowledged', ['committed' => 100, 'queue_processed' => 100], ['committed' => (int) ($unchangedSummary['committed'] ?? -1), 'queue_processed' => (int) ($unchangedSummary['queue_processed'] ?? -1)], (int) ($unchangedSummary['committed'] ?? -1) === 100 && (int) ($unchangedSummary['queue_processed'] ?? -1) === 100),
            wp_fts_wc_gate('unchanged_requeues_worker_unchanged', 100, (int) ($unchangedSummary['unchanged'] ?? -1), (int) ($unchangedSummary['unchanged'] ?? -1) === 100),
            wp_fts_wc_gate('unchanged_requeues_worker_analyzed', 0, (int) ($unchangedSummary['analyzed'] ?? -1), (int) ($unchangedSummary['analyzed'] ?? -1) === 0),
            wp_fts_wc_gate('unchanged_requeues_worker_adverse_outcomes', 0, (int) ($unchangedSummary['superseded'] ?? -1) + (int) ($unchangedSummary['deleted'] ?? -1) + (int) ($unchangedSummary['permanently_rejected'] ?? -1) + (int) ($unchangedSummary['retryable_failures'] ?? -1) + (int) ($unchangedSummary['deferred'] ?? -1) + (int) ($unchangedSummary['last_batch_failures'] ?? -1), (int) ($unchangedSummary['superseded'] ?? -1) === 0 && (int) ($unchangedSummary['deleted'] ?? -1) === 0 && (int) ($unchangedSummary['permanently_rejected'] ?? -1) === 0 && (int) ($unchangedSummary['retryable_failures'] ?? -1) === 0 && (int) ($unchangedSummary['deferred'] ?? -1) === 0 && (int) ($unchangedSummary['last_batch_failures'] ?? -1) === 0),
            wp_fts_wc_gate('current_profile_unchanged_hash_skips_rebuild', ['indexer' => 'wp-fts-indexer-v7', 'attempted' => 100, 'unchanged' => 100, 'analyzed' => 0], $indexerSignatures + ['attempted' => (int) ($unchangedSummary['attempted'] ?? -1), 'unchanged' => (int) ($unchangedSummary['unchanged'] ?? -1), 'analyzed' => (int) ($unchangedSummary['analyzed'] ?? -1)], $indexerSignatures === ['indexer' => 'wp-fts-indexer-v7'] && (int) ($unchangedSummary['attempted'] ?? -1) === 100 && (int) ($unchangedSummary['unchanged'] ?? -1) === 100 && (int) ($unchangedSummary['analyzed'] ?? -1) === 0),
            wp_fts_wc_gate('unchanged_requeues_content_hash_signature', $unchangedIndexBefore['content_hash_sha256'], $unchangedIndexAfter['content_hash_sha256'], $unchangedIndexBefore['document_rows'] === 100 && $unchangedIndexAfter['document_rows'] === 100 && $unchangedIndexBefore['content_hash_sha256'] === $unchangedIndexAfter['content_hash_sha256']),
            wp_fts_wc_gate('unchanged_requeues_surface_posting_signature', $unchangedIndexBefore['surface_posting_sha256'], $unchangedIndexAfter['surface_posting_sha256'], $unchangedIndexBefore['surface_posting_rows'] > 0 && $unchangedIndexBefore['surface_posting_rows'] === $unchangedIndexAfter['surface_posting_rows'] && $unchangedIndexBefore['surface_posting_sha256'] === $unchangedIndexAfter['surface_posting_sha256']),
            wp_fts_wc_gate('unchanged_requeues_index_data_writes', 0, count($unchangedIndexDataWrites), $unchangedIndexDataWrites === []),
            wp_fts_wc_gate('unchanged_requeues_worker_statement_count', '<= 20 all wpdb statements', count($unchangedStatements), $unchangedRoles['unknown'] === [] && count($unchangedStatements) <= 20),
            wp_fts_wc_gate('unchanged_requeues_worker_data_statement_count', '<= 15', count($unchangedRoles['data_roles']), $unchangedRoles['data_roles'] !== [] && count($unchangedRoles['data_roles']) <= 15),
            wp_fts_wc_gate('unchanged_requeues_worker_lease_controls', ['lease_acquire', 'lease_release'], $unchangedRoles['lease_control_roles'], $unchangedRoles['lease_control_roles'] === ['lease_acquire', 'lease_release']),
            wp_fts_wc_gate('unchanged_requeues_worker_transaction_controls', ['transaction_start', 'transaction_commit'], $unchangedRoles['transaction_roles'], $unchangedRoles['transaction_roles'] === ['transaction_start', 'transaction_commit'] && wp_fts_wc_worker_roles_are_ordered($unchangedRoles['roles'])),
            wp_fts_wc_gate('unchanged_requeues_worker_statement_bytes', '<= 4194304', max(array_map('strlen', $unchangedStatements) ?: [PHP_INT_MAX]), $unchangedStatements !== [] && max(array_map('strlen', $unchangedStatements)) <= 4194304),
            wp_fts_wc_gate('unchanged_requeues_worker_failures', 0, (int) ($unchangedSummary['last_batch_failures'] ?? -1), (int) ($unchangedSummary['last_batch_failures'] ?? -1) === 0),
            wp_fts_wc_gate('unchanged_requeues_work_drained', 0, $workRowsAfter, $workRowsAfter === 0),
            ...$claimIndexOptions['gates'],
            ...$metadataEvidence['gates'],
        ],
    ];
}

/**
 * Prove a custom-field selection carried only by one claimed generation is
 * part of the set-oriented preload. The selected key must travel through the
 * same fixed measurement/value statements as configured keys; reopening
 * postmeta after preload or silently dropping the claim option both fail.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_claim_index_options_preload_proof(int $postId): array
{
    global $wpdb;

    $post = get_post($postId);
    wp_fts_wc_assert(
        is_object($post)
            && (string) ($post->post_status ?? '') === 'publish'
            && (string) ($post->post_password ?? '') === '',
        'Per-claim index-options proof requires a public, unpassworded canonical post.'
    );
    $postmeta = wp_fts_wc_identifier((string) $wpdb->postmeta);
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $suffix = strtr(substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')), 0, 12), '0123456789', 'abcdefghij');
    $metaKey = '_wp_fts_claim_only_' . $suffix;
    $token = 'wpftsclaimoption' . $suffix;
    $originalRows = $wpdb->get_col($wpdb->prepare(
        "SELECT meta_value FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s ORDER BY meta_id",
        $postId,
        $metaKey
    )) ?: [];
    $replaceRows = static function (array $values) use ($wpdb, $postmeta, $postId, $metaKey): void {
        $deleted = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s",
            $postId,
            $metaKey
        ));
        wp_fts_wc_assert($deleted !== false, 'Could not reset the per-claim custom-field fixture.');
        foreach ($values as $value) {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO `{$postmeta}` (post_id,meta_key,meta_value) VALUES (%d,%s,%s)",
                $postId,
                $metaKey,
                (string) $value
            ));
            wp_fts_wc_assert($inserted === 1, 'Could not populate the per-claim custom-field fixture.');
        }
        if (function_exists('wp_cache_delete')) {
            wp_cache_delete($postId, 'post_meta');
        }
    };
    $queue = new WP_FTS_Index_Queue($wpdb);
    $storage = wp_fts_wc_storage_fixture(false);
    wp_fts_wc_assert(
        $storage instanceof WP_FTS_Set_Oriented_Search_Storage,
        'Per-claim index-options proof requires production set-oriented storage.'
    );
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $postingIdsForToken = static function () use ($wpdb, $terms, $postings, $token): array {
        return array_map('intval', $wpdb->get_col($wpdb->prepare(
            "SELECT p.post_id
FROM `{$terms}` t FORCE INDEX (term_identity)
INNER JOIN `{$postings}` p FORCE INDEX (PRIMARY) ON p.term_id=t.term_id
WHERE t.lang=%s AND t.kind=0 AND t.term=%s
ORDER BY p.post_id",
            'en',
            $token
        )) ?: []);
    };
    $payload = [
        'index_options' => [
            'document_lang' => 'en',
            'custom_field_keys' => [$metaKey],
        ],
    ];
    $restored = false;
    try {
        wp_fts_wc_assert(
            wp_fts_wc_checked_count(
                "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
                'work before per-claim index-options proof'
            ) === 0,
            'Per-claim index-options proof did not start from an empty direct-work frontier.'
        );
        wp_fts_wc_assert(
            wp_fts_wc_checked_count(
                $wpdb->prepare("SELECT COUNT(*) FROM `{$documents}` WHERE post_id=%d", $postId),
                'derived document before per-claim index-options proof'
            ) === 1,
            'Per-claim index-options proof requires one existing derived document, not the cheaper fresh-document path.'
        );
        $replaceRows([$token]);
        $queued = $queue->enqueue_many([$postId], null, $payload);
        $storedPayloadJson = $wpdb->get_var($wpdb->prepare(
            "SELECT payload FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $postId
        ));
        $storedPayload = is_string($storedPayloadJson)
            ? json_decode($storedPayloadJson, true, 16, JSON_THROW_ON_ERROR)
            : null;

        $memoryBefore = memory_get_usage(true);
        $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
        $started = hrtime(true);
        $recorded = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-claim-index-options',
            'batch_size' => 100,
            'time_budget' => 300.0,
        ]));
        $durationMs = wp_fts_wc_elapsed_ms($started);
        $memoryDelta = max(0, memory_get_usage(true) - $memoryBefore);
        $rssDelta = max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore);
        $summary = is_array($recorded['result']) ? $recorded['result'] : [];
        $statementRoles = wp_fts_wc_worker_statement_roles($recorded['queries']);
        $statements = $recorded['queries'];
        $measurementStatements = array_values(array_filter(
            $statements,
            static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_measurement')
        ));
        $valueStatements = array_values(array_filter(
            $statements,
            static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_values')
        ));
        $dependencyStatements = [...$measurementStatements, ...$valueStatements];
        $postmetaStatements = array_values(array_filter(
            $statements,
            static fn(string $sql): bool => str_contains(strtolower($sql), strtolower($postmeta))
        ));
        $selectedKeyStatements = array_values(array_filter(
            $dependencyStatements,
            static fn(string $sql): bool => str_contains($sql, $metaKey)
        ));
        $workerSqlHashes = [];
        foreach ($recorded['queries'] as $statementIndex => $sql) {
            $workerSqlHashes[] = [
                'bytes' => strlen($sql),
                'sha256' => hash('sha256', $sql),
                'role' => $statementRoles['roles'][$statementIndex] ?? 'unknown',
            ];
        }
        $postingIds = $postingIdsForToken();

        $replaceRows(array_map('strval', $originalRows));
        $restored = true;
        $restoreQueued = $queue->enqueue_many([$postId], null, $payload);
        $restoreRecorded = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-claim-index-options-restore',
            'batch_size' => 100,
            'time_budget' => 300.0,
        ]));
        $restoreSummary = is_array($restoreRecorded['result']) ? $restoreRecorded['result'] : [];
        $restoredPostingIds = $postingIdsForToken();
        $remainingWork = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d", $postId),
            'work after per-claim index-options restoration'
        );
        $restoredRows = array_map('strval', $wpdb->get_col($wpdb->prepare(
            "SELECT meta_value FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s ORDER BY meta_id",
            $postId,
            $metaKey
        )) ?: []);
    } finally {
        if (!$restored) {
            $replaceRows(array_map('strval', $originalRows));
        }
    }

    $fixedDependencyShape = count($measurementStatements) === 1
        && count($valueStatements) === 1
        && count($postmetaStatements) === 2
        && count($selectedKeyStatements) === 1
        && array_map('wp_fts_wc_canonical_hash', $postmetaStatements)
            === array_map('wp_fts_wc_canonical_hash', $dependencyStatements)
        && max(array_map('strlen', $dependencyStatements) ?: [PHP_INT_MAX]) <= 32768;
    $indexedExactly = $postingIds === [$postId]
        && (int) ($summary['attempted'] ?? -1) === 1
        && (int) ($summary['analyzed'] ?? -1) === 1
        && (int) ($summary['committed'] ?? -1) === 1;
    $expectedStatementRoles = [
        'lease_acquire',
        'claim_batch',
        'claim_source_snapshot',
        'dependency_measurement',
        'dependency_values',
        'replacement_frontier',
        'transaction_start',
        'dictionary_increment',
        'dictionary_decrement',
        'bounded_index_delete',
        'resolve_prepared_terms',
        'posting_replacement',
        'document_replacement',
        'atomic_worker_ack',
        'search_epoch_advance',
        'transaction_commit',
        'empty_term_cleanup',
        'lease_release',
    ];
    $boundedRoleContract = $statementRoles['unknown'] === []
        && $statementRoles['roles'] === $expectedStatementRoles
        && count($statementRoles['roles']) === 18
        && count($statementRoles['data_roles']) === 14
        && $statementRoles['lease_control_roles'] === ['lease_acquire', 'lease_release']
        && $statementRoles['transaction_roles'] === ['transaction_start', 'transaction_commit']
        && wp_fts_wc_worker_roles_are_ordered($statementRoles['roles']);
    $restorationExact = $restoreQueued === 1
        && (int) ($restoreSummary['committed'] ?? -1) === 1
        && $restoredPostingIds === []
        && $remainingWork === 0
        && $restoredRows === array_map('strval', $originalRows);

    return [
        'post_id' => $postId,
        'custom_field_key' => $metaKey,
        'search_token_sha256' => hash('sha256', $token),
        'queued' => $queued,
        'stored_payload' => $storedPayload,
        'worker_summary' => $summary,
        'worker_statement_count' => count($recorded['queries']),
        'worker_data_statement_count' => count($statementRoles['data_roles']),
        'worker_lease_control_statement_count' => count($statementRoles['lease_control_roles']),
        'worker_transaction_control_statement_count' => count($statementRoles['transaction_roles']),
        'worker_statement_roles' => $statementRoles['roles'],
        'worker_unclassified_statements' => $statementRoles['unknown'],
        'worker_statement_evidence' => $workerSqlHashes,
        'measurement_statement_count' => count($measurementStatements),
        'value_statement_count' => count($valueStatements),
        'postmeta_statement_count' => count($postmetaStatements),
        'selected_key_statement_count' => count($selectedKeyStatements),
        'max_dependency_statement_bytes' => max(array_map('strlen', $dependencyStatements) ?: [0]),
        'posting_ids' => $postingIds,
        'duration_ms' => $durationMs,
        'memory_delta_bytes' => $memoryDelta,
        'rss_delta_bytes' => $rssDelta,
        'restoration' => [
            'queued' => $restoreQueued,
            'summary' => $restoreSummary,
            'posting_ids' => $restoredPostingIds,
            'remaining_work' => $remainingWork,
            'meta_values' => $restoredRows,
        ],
        'gates' => [
            wp_fts_wc_gate(
                'claim_index_options_preload_contract',
                [1, $payload, 1, 1, 2, 1, $expectedStatementRoles, [$postId], true],
                [$queued, $storedPayload, count($measurementStatements), count($valueStatements), count($postmetaStatements), count($selectedKeyStatements), $statementRoles['roles'], $postingIds, $restorationExact],
                $queued === 1
                    && $storedPayload === $payload
                    && $fixedDependencyShape
                    && $boundedRoleContract
                    && $indexedExactly
                    && $restorationExact
            ),
            wp_fts_wc_gate('claim_index_options_payload_preserved', $payload, $storedPayload, $storedPayload === $payload),
            wp_fts_wc_gate('claim_index_options_fixed_dependency_statements', ['measurement' => 1, 'values' => 1, 'postmeta' => 2, 'selected_key' => 1], ['measurement' => count($measurementStatements), 'values' => count($valueStatements), 'postmeta' => count($postmetaStatements), 'selected_key' => count($selectedKeyStatements)], $fixedDependencyShape),
            wp_fts_wc_gate('claim_index_options_worker_statement_roles', $expectedStatementRoles, $statementRoles['roles'], $boundedRoleContract),
            wp_fts_wc_gate('claim_index_options_worker_total_statement_count', '<= 20', count($statementRoles['roles']), $statementRoles['unknown'] === [] && count($statementRoles['roles']) <= 20),
            wp_fts_wc_gate('claim_index_options_worker_data_statement_count', '<= 15', count($statementRoles['data_roles']), $statementRoles['data_roles'] !== [] && count($statementRoles['data_roles']) <= 15),
            wp_fts_wc_gate('claim_index_options_worker_lease_controls', ['lease_acquire', 'lease_release'], $statementRoles['lease_control_roles'], $statementRoles['lease_control_roles'] === ['lease_acquire', 'lease_release']),
            wp_fts_wc_gate('claim_index_options_worker_transaction_controls', ['transaction_start', 'transaction_commit'], $statementRoles['transaction_roles'], $statementRoles['transaction_roles'] === ['transaction_start', 'transaction_commit']),
            wp_fts_wc_gate('claim_index_options_worker_committed_and_indexed', ['attempted' => 1, 'analyzed' => 1, 'committed' => 1, 'ids' => [$postId]], ['attempted' => (int) ($summary['attempted'] ?? -1), 'analyzed' => (int) ($summary['analyzed'] ?? -1), 'committed' => (int) ($summary['committed'] ?? -1), 'ids' => $postingIds], $indexedExactly),
            wp_fts_wc_gate('claim_index_options_worker_duration_ms', '<= 5000', $durationMs, $durationMs <= 5000.0),
            wp_fts_wc_gate('claim_index_options_worker_memory_delta_bytes', '<= 16777216', $memoryDelta, $memoryDelta <= 16777216),
            wp_fts_wc_gate('claim_index_options_worker_rss_delta_bytes', '<= 16777216', $rssDelta, $rssDelta <= 16777216),
            wp_fts_wc_gate('claim_index_options_fixture_restored', true, $restorationExact, $restorationExact),
        ],
    ];
}

/** @param int[] $postIds @return array{document_rows:int,content_hash_sha256:string,surface_posting_rows:int,surface_posting_sha256:string} */
function wp_fts_wc_document_index_signatures(array $postIds): array
{
    global $wpdb;

    $postIds = array_values(array_unique(array_map('intval', $postIds)));
    sort($postIds, SORT_NUMERIC);
    wp_fts_wc_assert($postIds !== [], 'Index signature proof requires document ids.');
    $idSql = implode(',', $postIds);
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $documentRows = $wpdb->get_results(
        "SELECT post_id,HEX(content_hash) content_hash_hex
FROM `{$documents}`
WHERE post_id IN ({$idSql})
ORDER BY post_id",
        ARRAY_A
    );
    wp_fts_wc_assert(is_array($documentRows) && trim((string) $wpdb->last_error) === '', 'Could not sign unchanged document hashes.');
    $surfaceRows = $wpdb->get_results(
        "SELECT p.post_id,t.lang,t.term,p.impact
FROM `{$postings}` p FORCE INDEX (post_term)
INNER JOIN `{$terms}` t ON t.term_id=p.term_id AND t.kind=1
WHERE p.post_id IN ({$idSql})
ORDER BY p.post_id,t.lang,t.term",
        ARRAY_A
    );
    wp_fts_wc_assert(is_array($surfaceRows) && trim((string) $wpdb->last_error) === '', 'Could not sign unchanged normalized-surface postings.');

    return [
        'document_rows' => count($documentRows),
        'content_hash_sha256' => wp_fts_wc_canonical_hash($documentRows),
        'surface_posting_rows' => count($surfaceRows),
        'surface_posting_sha256' => wp_fts_wc_canonical_hash($surfaceRows),
    ];
}

/** True when a counted statement mutates terms, postings, or documents. */
function wp_fts_wc_is_index_data_mutation_statement(string $sql): bool
{
    $tokens = wp_fts_wc_sql_tokens($sql);
    $operation = null;
    foreach ($tokens as $token) {
        if (($token['type'] ?? null) === 'word') {
            $operation = (string) ($token['value'] ?? '');
            break;
        }
    }
    if (!in_array($operation, ['insert', 'replace', 'update', 'delete'], true)) {
        return false;
    }
    foreach ($tokens as $token) {
        if (
            in_array($token['type'] ?? '', ['word', 'identifier'], true)
            && in_array(wp_fts_wc_fts_table_kind((string) ($token['value'] ?? '')), ['terms', 'postings', 'documents'], true)
        ) {
            return true;
        }
    }
    return false;
}

/** @return array{lexical:int,surface:int,total:int} */
function wp_fts_wc_document_posting_kind_counts(int $postId): array
{
    global $wpdb;

    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT t.kind,COUNT(*) posting_rows
FROM `{$postings}` p FORCE INDEX (post_term)
JOIN `{$terms}` t ON t.term_id=p.term_id
WHERE p.post_id=%d AND t.kind IN (0,1)
GROUP BY t.kind
ORDER BY t.kind",
        $postId
    ), ARRAY_A) ?: [];
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', "Could not count posting kinds for document {$postId}.");
    $counts = [0 => 0, 1 => 0];
    foreach ($rows as $row) {
        $kind = (int) ($row['kind'] ?? -1);
        if (isset($counts[$kind])) {
            $counts[$kind] = max(0, (int) ($row['posting_rows'] ?? 0));
        }
    }
    return [
        'lexical' => $counts[0],
        'surface' => $counts[1],
        'total' => $counts[0] + $counts[1],
    ];
}

/**
 * Exercise actual WordPress metadata APIs, including the callback shapes that
 * tend to explode on commerce/plugin-heavy saves. A no-op dynamic index-options
 * filter deliberately makes an otherwise unrelated key conservatively
 * relevant; one post/request must still pay only one fence and one promotion.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_real_metadata_mutation_proof(int $postId): array
{
    global $wpdb;

    $post = get_post($postId);
    wp_fts_wc_assert(is_object($post) && (string) ($post->post_status ?? '') === 'publish', 'Metadata mutation proof requires a public post.');
    $postmeta = wp_fts_wc_identifier((string) $wpdb->postmeta);
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $metaKey = '_wp_fts_unrelated_mutation_probe';
    $originalRows = $wpdb->get_results($wpdb->prepare(
        "SELECT meta_value FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s ORDER BY meta_id",
        $postId,
        $metaKey
    ), ARRAY_A) ?: [];
    $replaceRows = static function (array $values) use ($wpdb, $postmeta, $postId, $metaKey): void {
        if ($wpdb->query($wpdb->prepare(
            "DELETE FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s",
            $postId,
            $metaKey
        )) === false) {
            throw new RuntimeException('Could not reset the real metadata mutation fixture.');
        }
        foreach (array_chunk($values, 500) as $chunk) {
            $rows = [];
            $args = [];
            foreach ($chunk as $value) {
                $rows[] = '(%d,%s,%s)';
                array_push($args, $postId, $metaKey, (string) $value);
            }
            if ($rows !== [] && $wpdb->query($wpdb->prepare(
                "INSERT INTO `{$postmeta}` (post_id,meta_key,meta_value) VALUES " . implode(',', $rows),
                ...$args
            )) !== count($rows)) {
                throw new RuntimeException('Could not populate every real metadata mutation fixture row.');
            }
        }
        if (function_exists('wp_cache_delete')) {
            wp_cache_delete($postId, 'post_meta');
        }
    };
    $boundaryStatements = static fn(array $queries): array => array_values(array_filter(
        $queries,
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence')
            || str_contains($sql, 'wp_fts:mutation-promote')
    ));
    $dynamicFilter = static fn(array $options): array => $options;
    add_filter(WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER, $dynamicFilter, 10, 2);
    $restored = false;
    $shortCircuit = null;
    try {
        $replaceRows(['stable']);
        wp_fts_wc_assert(
            wp_fts_wc_checked_count($wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d", $postId), 'metadata work before no-op APIs') === 0,
            'Metadata mutation proof did not start from an empty post work row.'
        );
        $shortCircuit = static fn(mixed $check): bool => true;
        $noOps = wp_fts_wc_record_queries(static function () use ($postId, $metaKey, $shortCircuit): array {
            $identical = update_post_meta($postId, $metaKey, 'stable');
            $unique = add_post_meta($postId, $metaKey, 'unique-rejected', true);
            $missing = delete_post_meta($postId, $metaKey, 'missing-value');
            add_filter('update_post_metadata', $shortCircuit, 10, 1);
            try {
                $shortCircuited = update_post_meta($postId, $metaKey, 'filter-owned');
            } finally {
                remove_filter('update_post_metadata', $shortCircuit, 10);
            }
            return [
                'identical_update' => $identical,
                'rejected_unique_add' => $unique,
                'missing_delete' => $missing,
                'filter_short_circuit' => $shortCircuited,
            ];
        });
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $noOpBoundaries = $boundaryStatements($noOps['queries']);
        $noOpFts = array_values(array_filter($noOps['queries'], 'wp_fts_wc_is_search_statement'));
        $workAfterNoOps = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d", $postId),
            'metadata work after no-op APIs'
        );

        $memoryBefore = memory_get_usage(true);
        $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
        $sequentialStarted = hrtime(true);
        $sequential = wp_fts_wc_record_queries(static function () use ($postId, $metaKey): void {
            for ($iteration = 1; $iteration <= 100; $iteration++) {
                update_post_meta($postId, $metaKey, $iteration % 2 === 0 ? 'stable' : 'changed');
            }
            WP_FTS_Plugin::flush_post_meta_mutations();
        });
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $sequentialMs = wp_fts_wc_elapsed_ms($sequentialStarted);
        $sequentialBoundaries = $boundaryStatements($sequential['queries']);
        $sequentialState = $wpdb->get_row($wpdb->prepare(
            "SELECT generation,state,claim_token,claimed_generation FROM `{$work}` WHERE kind='post' AND post_id=%d",
            $postId
        ), ARRAY_A);

        $replaceRows(array_fill(0, 1000, 'many-before'));
        $multiStarted = hrtime(true);
        $multi = wp_fts_wc_record_queries(static function () use ($postId, $metaKey): mixed {
            $result = update_post_meta($postId, $metaKey, 'many-after');
            WP_FTS_Plugin::flush_post_meta_mutations();
            return $result;
        });
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        $multiMs = wp_fts_wc_elapsed_ms($multiStarted);
        $multiBoundaries = $boundaryStatements($multi['queries']);
        $multiRowsAfter = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s AND meta_value=%s", $postId, $metaKey, 'many-after'),
            'metadata rows after multi-row API update'
        );

        $replaceRows(array_map(static fn(array $row): string => (string) ($row['meta_value'] ?? ''), $originalRows));
        $restored = true;
        $worker = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-real-metadata-mutations',
            'batch_size' => 1,
            'time_budget' => 300.0,
        ]);
        $remainingWork = wp_fts_wc_checked_count(
            $wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id=%d", $postId),
            'metadata work after reconciliation'
        );
        $restoredRows = $wpdb->get_col($wpdb->prepare(
            "SELECT meta_value FROM `{$postmeta}` WHERE post_id=%d AND meta_key=%s ORDER BY meta_id",
            $postId,
            $metaKey
        )) ?: [];
    } finally {
        if ($shortCircuit !== null) {
            remove_filter('update_post_metadata', $shortCircuit, 10);
        }
        remove_filter(WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER, $dynamicFilter, 10);
        if (!$restored) {
            $replaceRows(array_map(static fn(array $row): string => (string) ($row['meta_value'] ?? ''), $originalRows));
        }
    }

    $sequentialFts = array_values(array_filter($sequential['queries'], 'wp_fts_wc_is_search_statement'));
    $multiFts = array_values(array_filter($multi['queries'], 'wp_fts_wc_is_search_statement'));
    $originalValues = array_map(static fn(array $row): string => (string) ($row['meta_value'] ?? ''), $originalRows);
    $gates = [
        wp_fts_wc_gate('metadata_real_noop_results', [false, false, false, true], array_values($noOps['result']), array_values($noOps['result']) === [false, false, false, true]),
        wp_fts_wc_gate('metadata_real_noop_fts_statements', 0, count($noOpFts), $noOpFts === [] && $noOpBoundaries === [] && $workAfterNoOps === 0),
        wp_fts_wc_gate('metadata_real_100_sequential_boundary_statements', 2, count($sequentialFts), count($sequentialFts) === 2 && count($sequentialBoundaries) === 2),
        wp_fts_wc_gate('metadata_real_100_sequential_duration_ms', '<= 5000', $sequentialMs, $sequentialMs <= 5000.0),
        wp_fts_wc_gate('metadata_real_100_sequential_ready', 'ready with cleared token', $sequentialState, is_array($sequentialState) && ($sequentialState['state'] ?? null) === 'ready' && ($sequentialState['claim_token'] ?? null) === '' && (int) ($sequentialState['claimed_generation'] ?? -1) === 0),
        wp_fts_wc_gate('metadata_real_1000_row_boundary_statements', 2, count($multiFts), count($multiFts) === 2 && count($multiBoundaries) === 2),
        wp_fts_wc_gate('metadata_real_1000_rows_updated', 1000, $multiRowsAfter, $multiRowsAfter === 1000),
        wp_fts_wc_gate('metadata_real_1000_row_duration_ms', '<= 5000', $multiMs, $multiMs <= 5000.0),
        wp_fts_wc_gate('metadata_real_max_statement_bytes', '<= 1048576', max(array_map('strlen', [...$sequentialFts, ...$multiFts]) ?: [PHP_INT_MAX]), $sequentialFts !== [] && $multiFts !== [] && max(array_map('strlen', [...$sequentialFts, ...$multiFts])) <= 1048576),
        wp_fts_wc_gate('metadata_real_physical_schema_statements', 0, count(array_filter([...$noOps['queries'], ...$sequential['queries'], ...$multi['queries']], 'wp_fts_wc_is_physical_schema_statement')), count(array_filter([...$noOps['queries'], ...$sequential['queries'], ...$multi['queries']], 'wp_fts_wc_is_physical_schema_statement')) === 0),
        wp_fts_wc_gate('metadata_real_php_delta', '<= 16777216', max(0, memory_get_usage(true) - $memoryBefore), max(0, memory_get_usage(true) - $memoryBefore) <= 16777216),
        wp_fts_wc_gate('metadata_real_rss_delta', '<= 16777216', max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore), max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore) <= 16777216),
        wp_fts_wc_gate('metadata_real_worker_committed', 1, (int) ($worker['committed'] ?? -1), (int) ($worker['committed'] ?? -1) === 1),
        wp_fts_wc_gate('metadata_real_work_drained', 0, $remainingWork, $remainingWork === 0),
        wp_fts_wc_gate('metadata_real_fixture_restored', $originalValues, array_map('strval', $restoredRows), $originalValues === array_map('strval', $restoredRows)),
    ];
    return [
        'post_id' => $postId,
        'no_op_results' => $noOps['result'],
        'no_op_fts_statement_count' => count($noOpFts),
        'sequential_mutations' => [
            'calls' => 100,
            'duration_ms' => $sequentialMs,
            'fts_statement_count' => count($sequentialFts),
            'sql' => $sequentialFts,
            'state' => $sequentialState,
        ],
        'multi_row_update' => [
            'rows' => $multiRowsAfter,
            'duration_ms' => $multiMs,
            'fts_statement_count' => count($multiFts),
            'sql' => $multiFts,
        ],
        'worker_summary' => $worker,
        'gates' => $gates,
    ];
}

/**
 * Damage one physical table and contend the writer lease. Canonical WordPress
 * reads and saves must remain available, FTS must fail closed, and restoring
 * the physical table must restore the exact result page.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_missing_table_and_lock_proof(array $manifest): array
{
    global $wpdb;

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $pendingWork = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        'work before missing-table proof'
    );
    wp_fts_wc_assert(
        $pendingWork === 0,
        'Missing-table proof requires an empty relational work queue.'
    );

    $lock = [
        'token' => str_repeat('a', 24),
        'mode' => 'worst-case-contention',
        'started_at' => time(),
        'heartbeat_at' => time(),
        'expires_at' => time() + 300,
        'renewals' => 0,
    ];
    update_option(WP_FTS_Plugin::INDEX_LOCK_OPTION, $lock, false);
    try {
        $contended = WP_FTS_Plugin::process_manual_index_batch(['source' => 'worst-case-lock', 'batch_size' => 100, 'time_budget' => 1.0]);
    } finally {
        delete_option(WP_FTS_Plugin::INDEX_LOCK_OPTION);
    }
    $lockSkipped = !empty($contended['skipped_locked']);

    $termTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $backupTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms_missing_probe');
    $before = WP_FTS_Plugin::search('rareanchor', ['lang' => 'en', 'mode' => 'OR', 'limit' => 20]);
    wp_fts_wc_assert($before !== [], 'Missing-table proof needs a non-empty pre-fault result.');
    if ($wpdb->query("RENAME TABLE `{$termTable}` TO `{$backupTable}`") === false) {
        throw new RuntimeException('Could not install the missing-table fault: ' . (string) $wpdb->last_error);
    }

    $ftsFailedClosed = false;
    $ordinaryRead = false;
    $saveAvailable = false;
    $faultClass = '';
    $faultMessage = '';
    $recovery = [];
    $remainingRecoveryWork = -1;
    try {
        WP_FTS_Plugin::reset_request_caches();
        try {
            WP_FTS_Plugin::search('rareanchor', ['lang' => 'en', 'mode' => 'OR', 'limit' => 20]);
        } catch (Throwable $error) {
            $ftsFailedClosed = true;
            $faultClass = get_class($error);
            $faultMessage = $error->getMessage();
        }
        $post = get_post((int) $manifest['last_post_id']);
        $ordinaryRead = is_object($post) && (int) ($post->ID ?? 0) === (int) $manifest['last_post_id'];
        if (is_object($post)) {
            WP_FTS_Plugin::handle_post_save((int) $post->ID, $post);
            $saveAvailable = true;
        }
    } finally {
        if ($wpdb->query("RENAME TABLE `{$backupTable}` TO `{$termTable}`") === false) {
            throw new RuntimeException('Could not remove the missing-table fault: ' . (string) $wpdb->last_error);
        }
        // The failed foreground request ends before scheduled maintenance
        // verifies the restored schema. The canonical save then drains before
        // a second maintenance pass republishes the search capability.
        WP_FTS_Plugin::flush_foreground_bulk_mutations();
        WP_FTS_Plugin::reset_request_caches();
        WP_FTS_Plugin::run_scheduled_schema_repair();
        WP_FTS_Plugin::reset_request_caches();
        $recovery = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-missing-table-recovery',
            'batch_size' => 100,
            'time_budget' => 300.0,
        ]);
        WP_FTS_Plugin::reset_request_caches();
        WP_FTS_Plugin::run_scheduled_schema_repair();
        WP_FTS_Plugin::reset_request_caches();
        $remainingRecoveryWork = wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
            'work after missing-table recovery'
        );
    }
    $after = WP_FTS_Plugin::search('rareanchor', ['lang' => 'en', 'mode' => 'OR', 'limit' => 20]);
    $beforeHash = wp_fts_wc_result_hash($before);
    $afterHash = wp_fts_wc_result_hash($after);
    $restored = $beforeHash === $afterHash;
    wp_fts_wc_assert(count($before) <= 20 && count($after) <= 20, 'Availability-fault result evidence exceeds its 20-row page bound.');
    wp_fts_wc_assert(strlen($faultClass) <= 512 && strlen($faultMessage) <= 8192, 'Availability-fault exception evidence exceeds its diagnostic byte bound.');
    $observations = [
        'before_results' => $before,
        'after_results' => $after,
        'before_result_hash' => $beforeHash,
        'after_result_hash' => $afterHash,
        'fault_class' => $faultClass,
        'fault_message' => $faultMessage,
    ];
    wp_fts_wc_assert_json_evidence_bytes($observations, 4194304, 'Availability-fault observations');
    $gates = [
        wp_fts_wc_gate('maintenance_lock_contention', true, $lockSkipped, $lockSkipped),
        wp_fts_wc_gate('missing_table_fts_failed_closed', true, $ftsFailedClosed, $ftsFailedClosed),
        wp_fts_wc_gate('missing_table_ordinary_read_available', true, $ordinaryRead, $ordinaryRead),
        wp_fts_wc_gate('missing_table_save_available', true, $saveAvailable, $saveAvailable),
        wp_fts_wc_gate('missing_table_recovery_worker_committed', 1, (int) ($recovery['committed'] ?? -1), (int) ($recovery['committed'] ?? -1) === 1),
        wp_fts_wc_gate('missing_table_recovery_work_drained', 0, $remainingRecoveryWork, $remainingRecoveryWork === 0),
        wp_fts_wc_gate('missing_table_restore_parity', true, $restored, $restored),
    ];

    return [
        'schema' => 'relational-fts-availability-faults-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'writer_lock_skipped' => $lockSkipped,
        'fts_failed_closed' => $ftsFailedClosed,
        'ordinary_read_available' => $ordinaryRead,
        'save_available' => $saveAvailable,
        'recovery_worker_committed' => (int) ($recovery['committed'] ?? -1),
        'recovery_work_remaining' => $remainingRecoveryWork,
        ...$observations,
        'restored_result_hash' => $afterHash,
        'gates' => $gates,
    ];
}

/**
 * Drain the dirty-head fixture, freeze HTTP oracles, and assign hidden writers.
 *
 * Concurrent writers mutate only disjoint non-public posts. Public result sets
 * must therefore stay byte-for-byte stable while the same production queue and
 * relational writer remain busy; accepting any merely-visible page would let
 * duplication, omission, or ordering regressions pass unnoticed.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_concurrency_setup(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $acknowledged = 0;
    $indexed = 0;
    $scopeRowsScanned = 0;
    $drainBatches = [];
    $deadline = microtime(true) + 7200.0;
    $consecutiveNoProgress = 0;
    while (($remainingBefore = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'pre-concurrency durable work')) > 0) {
        wp_fts_wc_assert(microtime(true) < $deadline, 'Pre-concurrency dirty drain exceeded two hours.');
        $summary = WP_FTS_Plugin::process_manual_index_batch([
            'source' => 'worst-case-concurrency-setup',
            'batch_size' => 100,
            'time_budget' => 20.0,
        ]);
        $remainingAfter = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'pre-concurrency durable work after worker pass');
        $drainBatches[] = [
            'work_rows_before' => $remainingBefore,
            'work_rows_after' => $remainingAfter,
            'indexed' => (int) ($summary['indexed'] ?? 0),
            'committed' => (int) ($summary['committed'] ?? 0),
            'queue_processed' => (int) ($summary['queue_processed'] ?? 0),
            'backfill_scanned' => (int) ($summary['backfill_scanned'] ?? 0),
            'backfill_queued' => (int) ($summary['backfill_queued'] ?? 0),
            'scope_page_committed' => !empty($summary['scope_page_committed']),
            'scope_completed' => !empty($summary['scope_completed']),
            'wait_for_next_available' => !empty($summary['wait_for_next_available']),
            'next_available_at' => is_numeric($summary['next_available_at'] ?? null) ? (int) $summary['next_available_at'] : null,
            'skipped_locked' => !empty($summary['skipped_locked']),
            'stop_reason' => is_scalar($summary['stop_reason'] ?? null) ? (string) $summary['stop_reason'] : '',
        ];
        wp_fts_wc_assert((int) ($summary['last_batch_failures'] ?? 0) === 0, 'Pre-concurrency dirty drain recorded a worker failure.');
        wp_fts_wc_wait_after_worker_no_progress($summary, $deadline, 'Pre-concurrency dirty drain', $consecutiveNoProgress);
        $acknowledged += max(0, (int) ($summary['queue_processed'] ?? 0));
        $indexed += max(0, (int) ($summary['indexed'] ?? 0));
        $scopeRowsScanned += max(0, (int) ($summary['backfill_scanned'] ?? 0));
        WP_FTS_Plugin::reset_request_caches();
    }

    $hiddenIds = array_map('intval', $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts}
WHERE post_title LIKE %s AND post_status IN ('private','draft') AND post_password=''
ORDER BY ID ASC LIMIT 40",
        WP_FTS_WC_POST_TITLE_PREFIX . $wpdb->esc_like((string) $manifest['token']) . '%'
    )) ?: []);
    wp_fts_wc_assert(count($hiddenIds) === 40, 'Concurrency proof requires forty disjoint non-public writer posts.');
    $writerIds = [array_slice($hiddenIds, 0, 20), array_slice($hiddenIds, 20, 20)];

    $definitions = wp_fts_wc_case_definitions($manifest);
    $storage = wp_fts_wc_storage_fixture(false);
    wp_fts_wc_assert(interface_exists('WP_FTS_Set_Oriented_Search_Storage') && $storage instanceof WP_FTS_Set_Oriented_Search_Storage, 'Concurrency oracle requires the production set-oriented storage.');
    $oracleSearcher = new WP_FTS_Searcher($storage, new WP_FTS_Analyzer(WP_FTS_Plugin::runtime_analyzer_options()));
    $cases = [];
    foreach (array_values(array_unique(wp_fts_wc_concurrency_mix())) as $caseId) {
        WP_FTS_Plugin::reset_request_caches();
        $oracleOptions = wp_fts_wc_search_ready_options($definitions[$caseId]['options']);
        $oraclePayload = wp_fts_wc_payload($oracleSearcher->search($definitions[$caseId]['query'], $oracleOptions));
        $oracleRows = wp_fts_wc_payload_results($oraclePayload);
        $oracleIds = array_map('intval', array_column($oracleRows, 'doc_id'));
        $oracleHash = wp_fts_wc_result_hash($oracleRows);
        wp_fts_wc_assert($oracleRows !== [] && count($oracleIds) === count(array_unique($oracleIds)), "Independent concurrency oracle {$caseId} is empty or duplicated.");
        $http = wp_fts_wc_http_search($definitions[$caseId]);
        wp_fts_wc_assert($http['error'] === null && $http['rows'] !== [], "Concurrency baseline {$caseId} failed: " . (string) $http['error']);
        $httpIds = array_map('intval', array_column($http['rows'], 'doc_id'));
        $httpHash = wp_fts_wc_result_hash($http['rows']);
        wp_fts_wc_assert($httpIds === $oracleIds && hash_equals($oracleHash, $httpHash), "Concurrency HTTP baseline {$caseId} differs from the independent direct-core oracle.");
        $cases[$caseId] = [
            'count' => count($http['rows']),
            'ids' => $httpIds,
            'hash' => $httpHash,
            'request_url' => wp_fts_wc_http_search_url($definitions[$caseId]),
            'duration_ms' => $http['duration_ms'],
            'oracle' => [
                'source' => 'direct-set-oriented-searcher',
                'count' => count($oracleRows),
                'ids' => $oracleIds,
                'hash' => $oracleHash,
            ],
        ];
    }

    $evidence = [
        'schema' => 'relational-fts-concurrency-baseline-v5',
        'status' => 'PASS',
        'phase' => 'concurrency-setup',
        'concurrency_run_id' => bin2hex(random_bytes(16)),
        'reader_harness_sha256' => wp_fts_wc_required_env('WP_FTS_WC_CONCURRENT_READER_SHA256'),
        'acknowledged_generations' => $acknowledged,
        'indexed_documents' => $indexed,
        'scope_rows_scanned' => $scopeRowsScanned,
        'drain_batches' => $drainBatches,
        'remaining_work' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'post-concurrency-setup durable work'),
        'writer_post_ids' => $writerIds,
        'cases' => $cases,
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/concurrency-baseline.json', $evidence);

    return $evidence;
}

/** @return array<string,mixed> */
function wp_fts_wc_idle_http(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $definitions = wp_fts_wc_case_definitions($manifest);
    $mix = wp_fts_wc_concurrency_mix();
    $baseline = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/concurrency-baseline.json');
    $profileName = (string) ($manifest['profile']['name'] ?? '');
    $engine = strtolower(wp_fts_wc_required_env('WP_FTS_WC_ENGINE'));
    $engineFamily = match (true) {
        str_contains($engine, 'mariadb') => 'mariadb',
        str_contains($engine, 'mysql') => 'mysql',
        default => throw new RuntimeException("Unsupported worst-case database engine: {$engine}"),
    };
    $idleP95Limit = match ([$profileName, $engineFamily]) {
        ['50k', 'mysql'] => 1500.0,
        ['50k', 'mariadb'] => 5000.0,
        ['100k', 'mysql'] => 16000.0,
        ['100k', 'mariadb'] => 12000.0,
        default => 1000.0,
    };
    $iterations = WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT;
    $samples = [];
    $errors = [];
    for ($index = 0; $index < $iterations; $index++) {
        $caseId = $mix[$index % count($mix)];
        $result = wp_fts_wc_http_search($definitions[$caseId]);
        if ($result['error'] !== null) {
            $errors[] = ['case' => $caseId, 'message' => $result['error']];
            continue;
        }
        $hash = wp_fts_wc_result_hash($result['rows']);
        $ids = array_map('intval', array_column($result['rows'], 'doc_id'));
        $expected = $baseline['cases'][$caseId] ?? null;
        if (!is_array($expected) || $hash !== ($expected['hash'] ?? null) || $ids !== array_map('intval', $expected['ids'] ?? [])) {
            $errors[] = ['case' => $caseId, 'message' => 'REST result differs from the frozen construction-known concurrency baseline.'];
            continue;
        }
        $samples[] = ['case' => $caseId, 'duration_ms' => $result['duration_ms'], 'count' => count($result['rows']), 'hash' => $hash];
    }
    $latency = wp_fts_wc_distribution(array_map(static fn(array $sample): float => (float) $sample['duration_ms'], $samples));
    $result = [
        'schema' => 'relational-fts-idle-http-v3',
        'status' => 'FAIL',
        'phase' => 'idle-http',
        'transport' => 'http-rest',
        'requests' => $iterations,
        'samples' => $samples,
        'errors' => $errors,
        'latency_ms' => $latency,
        'p95_limit_ms' => $idleP95Limit,
        'gates' => [
            wp_fts_wc_gate('idle_http_request_count', WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT, $iterations, $iterations === WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT),
            wp_fts_wc_gate('idle_http_sample_count', WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT, count($samples), count($samples) === WP_FTS_WC_IDLE_HTTP_REQUEST_COUNT),
            wp_fts_wc_gate('idle_http_errors', 0, count($errors), $errors === []),
            wp_fts_wc_gate('idle_http_p95_ms', "<= {$idleP95Limit}", $latency['p95'], $latency['p95'] <= $idleP95Limit),
        ],
    ];
    $result['status'] = wp_fts_wc_gates_pass($result['gates']) ? 'PASS' : 'FAIL';
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/idle-http.json', $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Idle HTTP proof failed: ' . implode(', ', wp_fts_wc_gate_failures($result['gates'])));
    }
    return ['status' => 'PASS', 'phase' => 'idle-http', 'requests' => $iterations, 'errors' => count($errors)];
}

/** Build one deterministic relation whose payload is twice the buffer pool. */
function wp_fts_wc_cold_prepare(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();

    $table = wp_fts_wc_identifier($wpdb->prefix . 'fts_wc_cold_evict');
    $existing = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not inspect the cold-eviction relation.');
    wp_fts_wc_assert($existing === null, 'Cold-eviction preparation requires a fresh auxiliary relation.');
    wp_fts_wc_assert(WP_FTS_WC_COLD_EVICTION_BYTES % WP_FTS_WC_COLD_EVICTION_ROW_BYTES === 0, 'Cold-eviction constants do not form complete rows.');

    $created = $wpdb->query("CREATE TABLE `{$table}` (
id int unsigned NOT NULL,
payload mediumblob NOT NULL,
PRIMARY KEY (id)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=binary");
    wp_fts_wc_assert($created !== false && trim((string) $wpdb->last_error) === '', 'Could not create the cold-eviction relation: ' . trim((string) $wpdb->last_error));

    $rowCount = intdiv(WP_FTS_WC_COLD_EVICTION_BYTES, WP_FTS_WC_COLD_EVICTION_ROW_BYTES);
    $started = hrtime(true);
    for ($offset = 1; $offset <= $rowCount; $offset += 64) {
        $end = min($rowCount, $offset + 63);
        $rows = [];
        for ($id = $offset; $id <= $end; $id++) {
            $rows[] = "({$id},REPEAT(0x5A," . WP_FTS_WC_COLD_EVICTION_ROW_BYTES . '))';
        }
        $affected = $wpdb->query("INSERT INTO `{$table}` (id,payload) VALUES " . implode(',', $rows));
        wp_fts_wc_assert($affected === count($rows) && trim((string) $wpdb->last_error) === '', 'Could not populate the cold-eviction relation: ' . trim((string) $wpdb->last_error));
    }
    $buildMs = wp_fts_wc_elapsed_ms($started);
    $scan = wp_fts_wc_cold_eviction_scan($table);
    $bufferPoolBytes = 268435456;
    $gates = [
        wp_fts_wc_gate('cold_eviction_rows', $rowCount, $scan['row_count'], $scan['row_count'] === $rowCount),
        wp_fts_wc_gate('cold_eviction_logical_bytes', WP_FTS_WC_COLD_EVICTION_BYTES, $scan['bytes'], $scan['bytes'] === WP_FTS_WC_COLD_EVICTION_BYTES),
        wp_fts_wc_gate('cold_eviction_buffer_pool_ratio', '>= 2', $scan['bytes'] / $bufferPoolBytes, $scan['bytes'] >= 2 * $bufferPoolBytes),
        wp_fts_wc_gate('cold_eviction_payload_checksum_present', true, $scan['checksum'] !== '', $scan['checksum'] !== ''),
        wp_fts_wc_gate('cold_eviction_plan_reads_payload_relation', true, $scan['full_relation_scan'], $scan['full_relation_scan']),
    ];
    wp_fts_wc_assert_runtime();
    $evidence = [
        'schema' => 'relational-fts-cold-eviction-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'cold-prepare',
        'table' => $table,
        'row_bytes' => WP_FTS_WC_COLD_EVICTION_ROW_BYTES,
        'target_bytes' => WP_FTS_WC_COLD_EVICTION_BYTES,
        'build_ms' => $buildMs,
        'preparation_scan' => $scan,
        'gates' => $gates,
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/cold-eviction.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Cold-eviction preparation failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return $evidence;
}

/** @return array<string,mixed> */
function wp_fts_wc_cold_sample(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();
    $caseId = wp_fts_wc_required_env('WP_FTS_WC_CASE');
    $sample = wp_fts_wc_required_non_negative_int_env('WP_FTS_WC_SAMPLE');
    $manifest = wp_fts_wc_manifest();
    $processIdentity = wp_fts_wc_process_identity();
    $definitions = wp_fts_wc_case_definitions($manifest);
    if (!in_array($caseId, ['common_or', 'max_valid_or_prefix', 'rare_anchor_and', 'prefix_fanout'], true) || !isset($definitions[$caseId])) {
        throw new RuntimeException("Unsupported cold-sample case: {$caseId}");
    }
    $conditioning = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/cold-eviction.json');
    wp_fts_wc_require_evidence_gates(
        $conditioning,
        'cold-eviction preparation',
        ['cold_eviction_rows', 'cold_eviction_logical_bytes', 'cold_eviction_buffer_pool_ratio', 'cold_eviction_payload_checksum_present', 'cold_eviction_plan_reads_payload_relation'],
        'relational-fts-cold-eviction-v1'
    );
    $conditioningScan = wp_fts_wc_cold_eviction_scan(wp_fts_wc_identifier((string) ($conditioning['table'] ?? '')));
    $expectedScan = is_array($conditioning['preparation_scan'] ?? null) ? $conditioning['preparation_scan'] : [];
    $conditioningGates = [
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_eviction_rows", (int) ($expectedScan['row_count'] ?? -1), $conditioningScan['row_count'], $conditioningScan['row_count'] === (int) ($expectedScan['row_count'] ?? -1)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_eviction_bytes", WP_FTS_WC_COLD_EVICTION_BYTES, $conditioningScan['bytes'], $conditioningScan['bytes'] === WP_FTS_WC_COLD_EVICTION_BYTES),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_eviction_checksum", (string) ($expectedScan['checksum'] ?? ''), $conditioningScan['checksum'], $conditioningScan['checksum'] !== '' && $conditioningScan['checksum'] === (string) ($expectedScan['checksum'] ?? '')),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_eviction_plan", true, $conditioningScan['full_relation_scan'], $conditioningScan['full_relation_scan']),
    ];
    wp_fts_wc_assert(wp_fts_wc_gates_pass($conditioningGates), 'Cold sample was not conditioned by the complete twice-buffer-pool scan.');
    $storage = wp_fts_wc_storage_fixture(false);
    if (!interface_exists('WP_FTS_Set_Oriented_Search_Storage') || !($storage instanceof WP_FTS_Set_Oriented_Search_Storage)) {
        throw new RuntimeException('Cold sample requires the production set-oriented backend.');
    }
    $searcher = new WP_FTS_Searcher($storage, new WP_FTS_Analyzer(WP_FTS_Plugin::runtime_analyzer_options()));
    $definition = $definitions[$caseId];
    $searchOptions = wp_fts_wc_search_ready_options($definition['options']);
    $phpLifetimePeakBeforeReset = memory_get_peak_usage(true);
    wp_fts_wc_reset_php_peak_usage();
    $memoryBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $started = hrtime(true);
    $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $searchOptions));
    $duration = wp_fts_wc_elapsed_ms($started);
    $payload = wp_fts_wc_payload($recorded['result']);
    $queries = array_values($recorded['queries']);
    $rows = wp_fts_wc_payload_results($payload);
    $memoryAfter = memory_get_usage(true);
    $memoryPhasePeakAfter = memory_get_peak_usage(true);
    $memoryPeakBytes = max($phpLifetimePeakBeforeReset, $memoryPhasePeakAfter);
    $rssAfter = wp_fts_wc_rss_bytes('VmRSS');
    $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
    $memoryDelta = max(0, $memoryAfter - $memoryBefore);
    $memoryPeakDelta = max(0, $memoryPhasePeakAfter - $memoryBefore);
    $rssDelta = max(0, $rssAfter - $rssBefore);
    $rssPeakDelta = max(0, $rssPeakAfter - $rssBefore);
    // Keep report authentication outside the conditioned-search counters.
    $preliminary = wp_fts_wc_preliminary_report_binding();
    $sourceBinding = wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256']);
    $preliminaryReport = $preliminary[array_key_first($preliminary)] ?? null;
    $expected = is_array($preliminaryReport['cases'][$caseId] ?? null) ? $preliminaryReport['cases'][$caseId] : [];
    $statementShape = wp_fts_wc_statement_shape(array_map(static fn(string $sql): array => ['sql' => $sql], $queries));
    $actualIds = array_map('intval', array_column($rows, 'doc_id'));
    array_push(
        $conditioningGates,
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_source_binding", $sourceBinding, wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256']), $sourceBinding === wp_fts_wc_artifact_source_binding($manifest, $preliminary['sha256'])),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_validation_binding", $preliminary['sha256'], $sourceBinding['validation_evidence_sha256'], hash_equals($preliminary['sha256'], $sourceBinding['validation_evidence_sha256'])),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_case_definition", wp_fts_wc_canonical_hash(['query' => $expected['query'] ?? null, 'options' => $expected['options'] ?? null]), wp_fts_wc_canonical_hash($definition), wp_fts_wc_canonical_hash($definition) === wp_fts_wc_canonical_hash(['query' => $expected['query'] ?? null, 'options' => $expected['options'] ?? null])),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_result_parity", [$expected['result_ids'] ?? null, $expected['result_hash'] ?? null, $expected['result_score_signature'] ?? null], [$actualIds, wp_fts_wc_result_hash($rows), wp_fts_wc_ordered_score_signature($rows)], $actualIds === ($expected['result_ids'] ?? null) && wp_fts_wc_result_hash($rows) === ($expected['result_hash'] ?? null) && wp_fts_wc_ordered_score_signature($rows) === ($expected['result_score_signature'] ?? null)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_statement_shape", [$expected['max_total_query_count'] ?? null, $expected['statement_shape'] ?? null], [count($queries), $statementShape], count($queries) === ($expected['max_total_query_count'] ?? null) && $statementShape === ($expected['statement_shape'] ?? null)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_fresh_process_identity", 'positive pid/start ticks with a bound Linux boot identity', $processIdentity, wp_fts_wc_process_identity_valid($processIdentity)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_php_peak_attribution", 'resettable PHP phase peak after minus live usage before', [$memoryBefore, $memoryPhasePeakAfter, $memoryPeakDelta], $memoryBefore > 0 && $memoryPhasePeakAfter >= $memoryBefore && $memoryPeakDelta === max(0, $memoryPhasePeakAfter - $memoryBefore)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_php_delta", '<= 16777216 using live usage after minus before', [$memoryBefore, $memoryAfter, $memoryDelta], $memoryAfter > 0 && $memoryDelta === max(0, $memoryAfter - $memoryBefore) && $memoryDelta <= 16777216),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_php_peak_delta", '<= 16777216', $memoryPeakDelta, $memoryPeakDelta <= 16777216),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_php_peak", '0 < lifetime peak <= 134217728', $memoryPeakBytes, $memoryPeakBytes === max($phpLifetimePeakBeforeReset, $memoryPhasePeakAfter) && $memoryPeakBytes > 0 && $memoryPeakBytes <= 134217728),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_rss_peak_attribution", 'Linux VmHWM after minus VmRSS before', [$rssBefore, $rssPeakAfter, $rssPeakDelta], $rssBefore > 0 && $rssPeakAfter >= $rssBefore && $rssPeakDelta === max(0, $rssPeakAfter - $rssBefore)),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_rss_delta", '<= 16777216 using VmRSS after minus before', [$rssBefore, $rssAfter, $rssDelta], $rssAfter > 0 && $rssDelta === max(0, $rssAfter - $rssBefore) && $rssDelta <= 16777216),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_rss_peak_delta", '<= 16777216', $rssPeakDelta, $rssPeakDelta <= 16777216),
        wp_fts_wc_gate("cold_{$caseId}_{$sample}_rss_peak", '0 < VmHWM <= 134217728', $rssPeakAfter, $rssPeakAfter > 0 && $rssPeakAfter <= 134217728)
    );
    wp_fts_wc_assert(array_column($conditioningGates, 'id') === wp_fts_wc_cold_sample_gate_ids($caseId, $sample), "Cold {$caseId} sample {$sample} gate inventory drifted.");
    $case = [
        'schema' => 'relational-fts-cold-sample-v1',
        'status' => wp_fts_wc_gates_pass($conditioningGates) ? 'PASS' : 'FAIL',
        'phase' => 'cold-sample',
        ...$sourceBinding,
        'case' => $caseId,
        'sample' => $sample,
        'case_definition_sha256' => wp_fts_wc_canonical_hash($definition),
        'process_identity' => $processIdentity,
        'measurement_method' => 'fresh_process_conservative_peak_attribution',
        'php_peak_delta_authoritative' => true,
        'rss_peak_delta_authoritative' => true,
        'conditioning_scan' => $conditioningScan,
        'duration_ms' => $duration,
        'result_count' => count($rows),
        'result_ids' => $actualIds,
        'result_hash' => wp_fts_wc_result_hash($rows),
        'result_score_signature' => wp_fts_wc_ordered_score_signature($rows),
        'query_count' => count($queries),
        'statement_shape' => $statementShape,
        'max_sql_bytes' => max(array_map('strlen', $queries) ?: [0]),
        'memory_before_bytes' => $memoryBefore,
        'memory_after_bytes' => $memoryAfter,
        'memory_delta_bytes' => $memoryDelta,
        'php_lifetime_peak_before_reset_bytes' => $phpLifetimePeakBeforeReset,
        'php_phase_peak_after_reset_bytes' => $memoryPhasePeakAfter,
        'memory_peak_bytes' => $memoryPeakBytes,
        'memory_peak_delta_bytes' => $memoryPeakDelta,
        'rss_source' => 'linux_proc_status',
        'rss_before_bytes' => $rssBefore,
        'rss_after_bytes' => $rssAfter,
        'rss_delta_bytes' => $rssDelta,
        'rss_peak_bytes' => $rssPeakAfter,
        'rss_peak_delta_bytes' => $rssPeakDelta,
        'gates' => $conditioningGates,
    ];
    wp_fts_wc_assert_runtime();
    $case['evidence_sha256'] = wp_fts_wc_canonical_hash($case);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . "/cold-{$caseId}-{$sample}.json", $case);
    if ($case['status'] !== 'PASS') {
        throw new RuntimeException("Cold {$caseId} sample {$sample} failed: " . implode(', ', wp_fts_wc_gate_failures($conditioningGates)));
    }
    return ['status' => 'PASS', 'phase' => 'cold-sample', 'case' => $caseId, 'sample' => $sample, 'duration_ms' => $duration];
}

/** @return string[] */
function wp_fts_wc_cold_sample_gate_ids(string $caseId, int $sample): array
{
    return array_map(
        static fn(string $suffix): string => "cold_{$caseId}_{$sample}_{$suffix}",
        [
            'eviction_rows',
            'eviction_bytes',
            'eviction_checksum',
            'eviction_plan',
            'source_binding',
            'validation_binding',
            'case_definition',
            'result_parity',
            'statement_shape',
            'fresh_process_identity',
            'php_peak_attribution',
            'php_delta',
            'php_peak_delta',
            'php_peak',
            'rss_peak_attribution',
            'rss_delta',
            'rss_peak_delta',
            'rss_peak',
        ]
    );
}

/** Drop the auxiliary eviction relation before concurrent production work. */
function wp_fts_wc_cold_cleanup(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    $evidence = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/cold-eviction.json');
    $gates = wp_fts_wc_require_evidence_gates(
        $evidence,
        'cold-eviction preparation',
        ['cold_eviction_rows', 'cold_eviction_logical_bytes', 'cold_eviction_buffer_pool_ratio', 'cold_eviction_payload_checksum_present', 'cold_eviction_plan_reads_payload_relation'],
        'relational-fts-cold-eviction-v1'
    );
    $table = wp_fts_wc_identifier((string) ($evidence['table'] ?? ''));
    wp_fts_wc_assert($wpdb->query("DROP TABLE `{$table}`") !== false && trim((string) $wpdb->last_error) === '', 'Could not drop the cold-eviction relation.');
    $remaining = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not verify cold-eviction cleanup.');
    $gates[] = wp_fts_wc_gate('cold_eviction_relation_cleaned', null, $remaining, $remaining === null);
    $evidence['cleanup'] = ['table_exists' => $remaining !== null];
    $evidence['gates'] = $gates;
    $evidence['status'] = wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL';
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/cold-eviction.json', $evidence);
    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Cold-eviction cleanup failed.');
    }

    return ['status' => 'PASS', 'phase' => 'cold-cleanup'];
}

/** @return array{row_count:int,bytes:int,checksum:string,duration_ms:float,sql:string,explain:array<string,mixed>,table_access:array<int,array<string,mixed>>,full_relation_scan:bool} */
function wp_fts_wc_cold_eviction_scan(string $table): array
{
    global $wpdb;

    $sql = "SELECT /* wp_fts:cold_evict */ COUNT(*) row_count,
COALESCE(SUM(OCTET_LENGTH(payload)),0) bytes,
COALESCE(SUM(CRC32(payload)),0) checksum
FROM `{$table}`";
    $json = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
    wp_fts_wc_assert(is_string($json) && $json !== '' && trim((string) $wpdb->last_error) === '', 'Cold-eviction EXPLAIN returned no plan.');
    $explain = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($explain), 'Cold-eviction EXPLAIN JSON is malformed.');
    $access = [];
    wp_fts_wc_collect_database_table_access($explain, $access);
    $tableAccess = array_values(array_filter($access, static fn(array $row): bool => (string) ($row['table_name'] ?? '') === $table));
    $fullRelationScan = count(array_filter($tableAccess, static fn(array $row): bool => in_array(strtoupper((string) ($row['access_type'] ?? '')), ['ALL', 'INDEX'], true))) === 1;
    $started = hrtime(true);
    $row = $wpdb->get_row($sql, ARRAY_A);
    $durationMs = wp_fts_wc_elapsed_ms($started);
    wp_fts_wc_assert(is_array($row) && trim((string) $wpdb->last_error) === '', 'Cold-eviction scan failed: ' . trim((string) $wpdb->last_error));

    return [
        'row_count' => (int) ($row['row_count'] ?? -1),
        'bytes' => (int) ($row['bytes'] ?? -1),
        'checksum' => is_scalar($row['checksum'] ?? null) ? (string) $row['checksum'] : '',
        'duration_ms' => $durationMs,
        'sql' => $sql,
        'explain' => $explain,
        'table_access' => $tableAccess,
        'full_relation_scan' => $fullRelationScan,
    ];
}

/**
 * @param array{query:string,options:array<string,mixed>} $definition
 * @return array{duration_ms:float,rows:array<int,array<string,mixed>>,payload:array<string,mixed>,error:?string}
 */
function wp_fts_wc_http_search(array $definition): array
{
    $url = wp_fts_wc_http_search_url($definition);
    $started = hrtime(true);
    $response = wp_remote_get($url, ['timeout' => 15, 'redirection' => 0]);
    $duration = wp_fts_wc_elapsed_ms($started);
    if (is_wp_error($response)) {
        return ['duration_ms' => $duration, 'rows' => [], 'payload' => [], 'error' => $response->get_error_message()];
    }
    $status = (int) wp_remote_retrieve_response_code($response);
    $body = (string) wp_remote_retrieve_body($response);
    try {
        $payload = json_decode($body, true, 512, JSON_THROW_ON_ERROR);
    } catch (Throwable $error) {
        return ['duration_ms' => $duration, 'rows' => [], 'payload' => [], 'error' => "HTTP {$status} invalid JSON: " . $error->getMessage()];
    }
    if ($status !== 200 || !is_array($payload) || !is_array($payload['results'] ?? null)) {
        $message = is_array($payload) && is_scalar($payload['message'] ?? null) ? (string) $payload['message'] : substr($body, 0, 300);
        return ['duration_ms' => $duration, 'rows' => [], 'payload' => is_array($payload) ? $payload : [], 'error' => "HTTP {$status}: {$message}"];
    }
    $rows = wp_fts_wc_payload_results($payload);
    $ids = array_map('intval', array_column($rows, 'doc_id'));
    if (
        count($rows) > 20
        || count($ids) !== count(array_unique($ids))
        || array_key_exists('retrieval_mode', $payload)
        || array_key_exists('total_is_exact', $payload)
        || array_key_exists('results_may_be_incomplete', $payload)
    ) {
        return ['duration_ms' => $duration, 'rows' => [], 'payload' => $payload, 'error' => 'REST payload violated the bounded page or retired-field contract.'];
    }
    if ($ids !== [] && !wp_fts_wc_public_ids_currently_visible($ids)) {
        return ['duration_ms' => $duration, 'rows' => [], 'payload' => $payload, 'error' => 'REST payload contained hidden, password-protected, missing, or dirty rows.'];
    }
    return ['duration_ms' => $duration, 'rows' => $rows, 'payload' => $payload, 'error' => null];
}

/** @param array{query:string,options:array<string,mixed>} $definition */
function wp_fts_wc_http_search_url(array $definition): string
{
    $options = $definition['options'];

    $query = http_build_query([
        'q' => $definition['query'],
        'lang' => (string) ($options['query_lang'] ?? 'en'),
        'mode' => (string) ($options['mode'] ?? 'OR'),
        'limit' => (int) ($options['limit'] ?? 20),
        'prefix' => !empty($options['prefix_matching']) ? 1 : 0,
    ], '', '&', PHP_QUERY_RFC3986);

    return rest_url(WP_FTS_Plugin::REST_NAMESPACE . WP_FTS_Plugin::REST_SEARCH_ROUTE) . '?' . $query;
}

/** @param int[] $ids */
function wp_fts_wc_public_ids_currently_visible(array $ids): bool
{
    global $wpdb;

    $ids = array_values(array_unique(array_filter(array_map('intval', $ids), static fn(int $id): bool => $id > 0)));
    if ($ids === []) {
        return true;
    }
    $placeholders = implode(',', array_fill(0, count($ids), '%d'));
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $count = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->posts} p
LEFT JOIN `{$work}` w ON w.kind='post' AND w.post_id=p.ID
WHERE p.ID IN ({$placeholders}) AND p.post_type='post' AND p.post_status='publish' AND p.post_password='' AND w.job_key IS NULL",
        ...$ids
    ));
    return $count === count($ids);
}

/**
 * Reconcile pending dirty rows while readers execute. Two processes contend on
 * the production writer lease; skipped ownership is acceptable, lost work is not.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_concurrent_writer(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $worker = wp_fts_wc_required_non_negative_int_env('WP_FTS_WC_WORKER');
    $seconds = wp_fts_wc_required_positive_int_env('WP_FTS_WC_CONCURRENCY_SECONDS');
    $baseline = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/concurrency-baseline.json');
    $window = wp_fts_wc_concurrency_window('writer', $worker, $seconds, $baseline);
    $postIds = array_map('intval', $baseline['writer_post_ids'][$worker] ?? []);
    wp_fts_wc_assert(count($postIds) === 20, "Concurrent writer {$worker} has no disjoint hidden-post assignment.");
    $idSql = implode(',', array_fill(0, count($postIds), '%d'));
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $queue = new WP_FTS_Index_Queue($wpdb);
    $startedNs = hrtime(true);
    $deadlineNs = (int) $window['deadline_monotonic_ns'];
    $lastMutationDeadlineNs = $deadlineNs - 5000000000;
    $mutationIntervalNs = 15000000000;
    $nextMutationNs = $startedNs;
    $batches = [];
    $revision = 0;

    while (hrtime(true) < $deadlineNs) {
        $batchStarted = hrtime(true);
        $mutationAttempted = false;
        $queued = 0;
        try {
            if ($batchStarted >= $nextMutationNs && $batchStarted < $lastMutationDeadlineNs) {
                $assignedWork = wp_fts_wc_checked_count(
                    $wpdb->prepare(
                        "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id IN ({$idSql})",
                        ...$postIds
                    ),
                    "concurrent writer {$worker} assigned work"
                );
                if ($assignedWork === 0) {
                    $mutationAttempted = true;
                    $excerpt = "Hidden concurrent writer {$worker} revision " . ($revision % 2);
                    $updated = $wpdb->query($wpdb->prepare(
                        "UPDATE {$wpdb->posts} SET post_excerpt=%s,post_modified_gmt=UTC_TIMESTAMP() WHERE ID IN ({$idSql})",
                        $excerpt,
                        ...$postIds
                    ));
                    wp_fts_wc_assert(is_int($updated), "Concurrent writer {$worker} could not mutate its hidden posts.");
                    $queued = $queue->enqueue_many($postIds);
                    wp_fts_wc_assert($queued === count($postIds), "Concurrent writer {$worker} did not queue its complete mutation.");
                    $revision++;
                    $nextMutationNs = $batchStarted + $mutationIntervalNs;
                }
            }
            $summary = WP_FTS_Plugin::process_manual_index_batch([
                'source' => 'worst-case-concurrent-' . $worker,
                'batch_size' => 100,
                'time_budget' => 5.0,
            ]);
            $batches[] = [
                'duration_ms' => wp_fts_wc_elapsed_ms($batchStarted),
                'indexed' => (int) ($summary['indexed'] ?? 0),
                'skipped_locked' => !empty($summary['skipped_locked']),
                'failures' => (int) ($summary['last_batch_failures'] ?? 0),
                'deadlock_retry' => false,
                'queued' => $queued,
            ];
        } catch (Throwable $error) {
            $errorMessage = $error->getMessage();
            $databaseError = is_string($wpdb->last_error ?? null) ? (string) $wpdb->last_error : '';
            $deadlockRetry = str_contains($errorMessage, 'Deadlock found when trying to get lock')
                || ($errorMessage === 'Could not acquire the FTS index writer lease.'
                    && str_contains($databaseError, 'Deadlock found when trying to get lock'));
            if ($deadlockRetry && $mutationAttempted && $queued === 0) {
                // The canonical update may have committed before enqueueing
                // lost its transaction. Retry the same mutation immediately.
                $nextMutationNs = 0;
            }
            $batches[] = [
                'duration_ms' => wp_fts_wc_elapsed_ms($batchStarted),
                'indexed' => 0,
                'skipped_locked' => false,
                'failures' => $deadlockRetry ? 0 : 1,
                'deadlock_retry' => $deadlockRetry,
                'queued' => $queued,
                'error' => $errorMessage,
                'database_error' => $databaseError,
            ];
        }
        usleep(20000);
    }

    $finishedNs = hrtime(true);
    $finalExcerpt = (string) $wpdb->get_var($wpdb->prepare("SELECT post_excerpt FROM {$wpdb->posts} WHERE ID=%d", $postIds[0]));
    $failures = array_sum(array_column($batches, 'failures'));
    $deadlockRetries = count(array_filter($batches, static fn(array $batch): bool => !empty($batch['deadlock_retry'])));
    $mutations = count(array_filter($batches, static fn(array $batch): bool => (int) ($batch['queued'] ?? 0) === 20));
    $result = [
        'schema' => 'relational-fts-concurrent-writer-v3',
        'status' => $failures === 0 && $deadlockRetries <= 8 && $mutations > 0 ? 'PASS' : 'FAIL',
        'phase' => 'concurrent-writer',
        'worker' => $worker,
        'elapsed_seconds' => max(0.0, ($finishedNs - $startedNs) / 1000000000),
        'started_monotonic_ns' => $startedNs,
        'finished_monotonic_ns' => $finishedNs,
        'shared_window' => $window,
        'measured_overlap_seconds' => max(0.0, (min($finishedNs, $deadlineNs) - max($startedNs, (int) $window['start_monotonic_ns'])) / 1000000000),
        'batches' => $batches,
        'indexed' => array_sum(array_column($batches, 'indexed')),
        'lease_acquired_batches' => count(array_filter(
            $batches,
            static fn(array $batch): bool => empty($batch['skipped_locked'])
                && empty($batch['deadlock_retry'])
                && (int) ($batch['failures'] ?? 0) === 0
        )),
        'lease_skipped_batches' => count(array_filter($batches, static fn(array $batch): bool => !empty($batch['skipped_locked']))),
        'mutations' => $mutations,
        'deadlock_retries' => $deadlockRetries,
        'assigned_post_ids' => $postIds,
        'final_excerpt' => $finalExcerpt,
        'failures' => $failures,
        'rss_peak_bytes' => wp_fts_wc_rss_bytes('VmHWM'),
        'php_peak_bytes' => memory_get_peak_usage(true),
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . "/concurrent-writer-{$worker}.json", $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException(
            "Concurrent writer {$worker} recorded {$result['failures']} failed batches, "
                . "{$deadlockRetries} deadlock retries, and {$mutations} complete mutations."
        );
    }

    return ['status' => 'PASS', 'phase' => 'concurrent-writer', 'worker' => $worker, 'indexed' => $result['indexed'], 'deadlock_retries' => $deadlockRetries, 'failures' => 0];
}

/**
 * Publish readiness and join the coordinator-owned monotonic interval. Every
 * worker uses the same start/deadline pair, so independently long runtimes
 * cannot masquerade as an overlapping 8-reader/2-writer load.
 *
 * @param array<string,mixed> $baseline
 * @return array{schema:string,run_id:string,start_monotonic_ns:int,deadline_monotonic_ns:int,minimum_overlap_seconds:int,window_seconds:int}
 */
function wp_fts_wc_concurrency_window(string $role, int $worker, int $seconds, array $baseline): array
{
    $runId = is_string($baseline['concurrency_run_id'] ?? null) ? (string) $baseline['concurrency_run_id'] : '';
    wp_fts_wc_assert(strlen($runId) === 32 && wp_fts_wc_is_ascii_hex($runId), 'Concurrency baseline has no valid run identity.');
    wp_fts_wc_assert(in_array($role, ['reader', 'writer'], true), 'Concurrency worker role is invalid.');
    $readyPath = wp_fts_wc_evidence_dir() . "/concurrency-ready-{$role}-{$worker}.json";
    wp_fts_wc_write_json($readyPath, [
        'schema' => 'relational-fts-concurrency-ready-v1',
        'run_id' => $runId,
        'role' => $role,
        'worker' => $worker,
        'ready_monotonic_ns' => hrtime(true),
    ]);

    $coordinatorPath = wp_fts_wc_evidence_dir() . '/concurrency-window.json';
    $waitDeadline = hrtime(true) + 180000000000;
    while (!is_file($coordinatorPath)) {
        wp_fts_wc_assert(hrtime(true) < $waitDeadline, "Concurrent {$role} {$worker} waited more than 180 seconds for the shared start barrier.");
        usleep(20000);
        clearstatcache(true, $coordinatorPath);
    }
    $window = wp_fts_wc_read_json($coordinatorPath);
    wp_fts_wc_assert(
        ($window['schema'] ?? null) === 'relational-fts-concurrency-window-v1'
            && ($window['run_id'] ?? null) === $runId
            && ($window['minimum_overlap_seconds'] ?? null) === $seconds
            && is_int($window['start_monotonic_ns'] ?? null)
            && is_int($window['deadline_monotonic_ns'] ?? null)
            && (int) $window['deadline_monotonic_ns'] - (int) $window['start_monotonic_ns'] >= ($seconds * 1000000000),
        "Concurrent {$role} {$worker} received an invalid shared window."
    );
    while (hrtime(true) < (int) $window['start_monotonic_ns']) {
        usleep(1000);
    }

    /** @var array{schema:string,run_id:string,start_monotonic_ns:int,deadline_monotonic_ns:int,minimum_overlap_seconds:int,window_seconds:int} $window */
    return $window;
}

/** @return string[] */
function wp_fts_wc_concurrency_mix(): array
{
    return [
        'common_or', 'common_or', 'common_or', 'common_or', 'common_or',
        'common_or', 'common_or', 'common_or', 'common_or', 'common_or',
        'prefix_fanout', 'prefix_fanout', 'prefix_fanout',
        'rare_anchor_and', 'rare_anchor_and',
        'surface_rarest_exact_anchor_and', 'surface_rarest_exact_anchor_and',
        'common_or', 'prefix_fanout', 'max_valid_or_prefix',
    ];
}

/**
 * Invoke wp_update_term() against a term attached to the whole corpus. Its real
 * pre/post hooks must fence and promote one scope row without materializing
 * member IDs, and search must fail closed until workers finish that scope.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_scope_proof(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $sparseProviders = wp_fts_wc_sparse_provider_plan_proof($manifest);
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $denseRelationships = wp_fts_wc_dense_relationship_search_proof($manifest, $work);
    $targetedExpansion = wp_fts_wc_targeted_scope_expansion_proof();
    $postRowsBefore = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='post'", 'post work before taxonomy scope hook');
    $termBefore = get_term((int) $manifest['term_id'], 'category');
    wp_fts_wc_assert(is_object($termBefore), 'Taxonomy scope proof could not load its canonical term.');
    $updatedName = 'Relational scope ' . substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')), 0, 12);
    $memoryBefore = memory_get_usage(true);
    $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
    $started = hrtime(true);
    $recorded = wp_fts_wc_record_queries(static fn() => wp_update_term(
        (int) $manifest['term_id'],
        'category',
        ['name' => $updatedName]
    ));
    $duration = wp_fts_wc_elapsed_ms($started);
    wp_fts_wc_assert(
        is_array($recorded['result'])
            && (int) ($recorded['result']['term_id'] ?? 0) === (int) $manifest['term_id']
            && (int) ($recorded['result']['term_taxonomy_id'] ?? 0) === (int) $manifest['term_taxonomy_id'],
        'The real wp_update_term() call did not commit its canonical term.'
    );
    $ftsStatements = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_search_statement'));
    $boundaryStatements = array_values(array_filter(
        $ftsStatements,
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence')
            || str_contains($sql, 'wp_fts:mutation-promote')
    ));
    $schemaStatements = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_fts_physical_schema_statement'));
    $scopeRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope'", 'scope work after taxonomy hook');
    $postRowsAfter = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='post'", 'post work after taxonomy hook');
    $scopeState = $wpdb->get_row(
        "SELECT state,claim_token,claimed_generation,scope_subject_type,scope_subject_id FROM `{$work}` WHERE kind='scope' ORDER BY job_key LIMIT 1",
        ARRAY_A
    );
    $termAfter = get_term((int) $manifest['term_id'], 'category');
    $visibilityIndex = wp_fts_wc_visibility_index_probe($manifest, $work);
    $failedClosed = false;
    $scopeSearchIds = [];
    $scopeSearchOutcome = 'results';
    $scopeSearchQueries = [];
    $scopeSearchThreadId = (int) $wpdb->get_var(
        'SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()'
    );
    wp_fts_wc_assert($scopeSearchThreadId > 0, 'Could not map the taxonomy-scope search to Performance Schema.');
    $scopeSearchBeforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $scopeSearchThreadId
    ));
    $scopeSearchFilter = static function (string $sql) use (&$scopeSearchQueries): string {
        $scopeSearchQueries[] = $sql;
        return $sql;
    };
    WP_FTS_Plugin::reset_request_caches();
    $scopeSearchStarted = hrtime(true);
    add_filter('query', $scopeSearchFilter, PHP_INT_MIN, 1);
    try {
        $scopeSearchIds = array_map('intval', array_column(
            WP_FTS_Plugin::search('prefixprobe', [
                'lang' => 'en',
                'mode' => 'OR',
                'limit' => 20,
                'prefix_matching' => true,
                'prefix_min_length' => 4,
            ]),
            'doc_id'
        ));
        $failedClosed = $scopeSearchIds === [];
    } catch (Throwable $error) {
        $failedClosed = true;
        $scopeSearchOutcome = get_class($error);
    } finally {
        remove_filter('query', $scopeSearchFilter, PHP_INT_MIN);
    }
    $scopeSearchDuration = wp_fts_wc_elapsed_ms($scopeSearchStarted);
    $scopeSearchSql = array_values(array_filter(
        $scopeSearchQueries,
        static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) !== null
    ));
    $scopeSearchEvents = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $scopeSearchThreadId,
        $scopeSearchBeforeEvent
    ), ARRAY_A) ?: [];
    $scopeSearchEvents = array_values(array_filter(
        $scopeSearchEvents,
        static fn(array $event): bool => wp_fts_wc_search_statement_kind((string) ($event['SQL_TEXT'] ?? '')) !== null
    ));
    $scopeSearchPerformanceSql = array_map(
        static fn(array $event): string => (string) ($event['SQL_TEXT'] ?? ''),
        $scopeSearchEvents
    );
    $scopeSearchStatementMetrics = wp_fts_wc_search_statement_metrics($scopeSearchEvents);
    $scopeSearchStatementShape = [];
    foreach (['plan', 'rank', 'hydrate'] as $kind) {
        $scopeSearchStatementShape[$kind] = (int) ($scopeSearchStatementMetrics[$kind]['events'] ?? 0);
    }
    $scopeSearchRowsExamined = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['ROWS_EXAMINED'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchRowsSent = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['ROWS_SENT'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchDiskTempTables = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['CREATED_TMP_DISK_TABLES'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchSortMergePasses = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['SORT_MERGE_PASSES'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchNoIndexUsed = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['NO_INDEX_USED'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchNoGoodIndexUsed = array_sum(array_map(
        static fn(array $event): int => max(0, (int) ($event['NO_GOOD_INDEX_USED'] ?? 0)),
        $scopeSearchEvents
    ));
    $scopeSearchServerDuration = array_sum(array_map(
        static fn(array $event): float => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
        $scopeSearchEvents
    ));
    $scopeSearchPlans = [];
    $scopeSearchPlanFullScans = 0;
    $scopeSearchPlanMissingKeys = 0;
    $scopeSearchPlanCoverage = true;
    $scopeDefinition = [
        'query' => 'prefixprobe',
        'options' => [
            'query_lang' => 'en',
            'mode' => 'OR',
            'limit' => 20,
            'prefix_matching' => true,
            'prefix_min_length' => 4,
        ],
    ];
    foreach ($scopeSearchSql as $sql) {
        $kind = wp_fts_wc_search_statement_kind($sql);
        if ($kind === null) {
            continue;
        }
        $explainText = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
        $plan = is_string($explainText) && $explainText !== ''
            ? json_decode($explainText, true, 512, JSON_THROW_ON_ERROR)
            : null;
        $access = [];
        if (is_array($plan)) {
            wp_fts_wc_collect_database_table_access($plan, $access);
        }
        $relations = wp_fts_wc_sql_fts_relations($sql);
        $aliases = [];
        foreach ($relations as $relation) {
            $aliases[strtolower((string) $relation['alias'])] = (string) $relation['table'];
            $aliases[strtolower((string) $relation['relation'])] = (string) $relation['table'];
        }
        $ftsAccess = [];
        foreach ($access as $row) {
            $tableName = strtolower(trim((string) ($row['table_name'] ?? ''), "` \t\n\r\0\x0B"));
            $physical = $aliases[$tableName] ?? wp_fts_wc_fts_table_kind($tableName);
            if ($physical !== null) {
                $ftsAccess[] = $row + ['physical_table' => $physical];
            }
        }
        $declaredTables = array_values(array_unique(array_column($relations, 'table')));
        $observedTables = array_values(array_unique(array_column($ftsAccess, 'physical_table')));
        $expectedTables = wp_fts_wc_expected_statement_relations($kind, $scopeDefinition);
        sort($declaredTables, SORT_STRING);
        sort($observedTables, SORT_STRING);
        $fullScans = count(array_filter(
            $ftsAccess,
            static fn(array $row): bool => strtoupper((string) ($row['access_type'] ?? '')) === 'ALL'
        ));
        $missingKeys = count(array_filter(
            $ftsAccess,
            static fn(array $row): bool => trim((string) ($row['key'] ?? '')) === ''
        ));
        $scopeSearchPlanFullScans += $fullScans;
        $scopeSearchPlanMissingKeys += $missingKeys;
        $scopeSearchPlanCoverage = $scopeSearchPlanCoverage
            && is_array($plan)
            && $ftsAccess !== []
            && $declaredTables === $expectedTables
            && $observedTables === $expectedTables;
        $scopeSearchPlans[$kind] = [
            'sql_sha256' => hash('sha256', $sql),
            'plan' => $plan,
            'declared_tables' => $declaredTables,
            'observed_tables' => $observedTables,
            'expected_tables' => $expectedTables,
            'fts_table_access' => $ftsAccess,
            'full_scan_count' => $fullScans,
            'missing_key_count' => $missingKeys,
        ];
    }
    $scopeSearchRowsExaminedLimit = 256;
    $scopePrefixShapes = array_map('wp_fts_wc_surface_range_sql_shape', $scopeSearchSql);
    $scopePrefixEqualityCount = array_sum(array_column($scopePrefixShapes, 'term_equality_count'));
    $scopePrefixRangeCount = array_sum(array_column($scopePrefixShapes, 'term_range_count'));
    $scopePrefixKindCount = array_sum(array_column($scopePrefixShapes, 'kind_one_count'));
    $scopeDictionaryTermRangeCount = array_sum(array_map('wp_fts_wc_dictionary_term_range_count', $scopeSearchSql));
    $scopePlanTermAccess = array_values(array_filter(
        is_array($scopeSearchPlans['plan']['fts_table_access'] ?? null) ? $scopeSearchPlans['plan']['fts_table_access'] : [],
        static fn(array $access): bool => ($access['physical_table'] ?? null) === 'terms'
    ));
    $scopePlanUsesIdentityIndex = count($scopePlanTermAccess) === 1
        && count(array_filter(
            $scopePlanTermAccess,
            static fn(array $access): bool => (string) ($access['key'] ?? '') !== 'term_identity'
        )) === 0;
    $scopeSearchMaxStatementBytes = max(array_map('strlen', $scopeSearchSql) ?: [0]);
    $scopeSearchSqlHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $scopeSearchSql);
    $scopeSearchPerformanceSqlHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $scopeSearchPerformanceSql);
    $ordinaryPost = get_post((int) $manifest['last_post_id']);
    $ordinaryAvailable = is_object($ordinaryPost);
    $onlyBoundaryWork = count($ftsStatements) === 2
        && count($boundaryStatements) === 2
        && count(array_filter($boundaryStatements, static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-fence'))) === 1
        && count(array_filter($boundaryStatements, static fn(string $sql): bool => str_contains($sql, 'wp_fts:mutation-promote'))) === 1
        && count(array_filter($ftsStatements, static fn(string $sql): bool => !str_contains(strtolower($sql), 'fts_work'))) === 0;
    $gates = [
        wp_fts_wc_gate('taxonomy_scope_statement_count', 2, count($ftsStatements), $onlyBoundaryWork),
        wp_fts_wc_gate('taxonomy_scope_only_work_sql', true, $onlyBoundaryWork, $onlyBoundaryWork),
        wp_fts_wc_gate('taxonomy_scope_duration_ms', '<= 500', $duration, $duration <= 500.0),
        wp_fts_wc_gate('taxonomy_scope_php_delta', '<= 16777216', max(0, memory_get_usage(true) - $memoryBefore), max(0, memory_get_usage(true) - $memoryBefore) <= 16777216),
        wp_fts_wc_gate('taxonomy_scope_rss_delta', '<= 16777216', max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore), max(0, wp_fts_wc_rss_bytes('VmRSS') - $rssBefore) <= 16777216),
        wp_fts_wc_gate('taxonomy_scope_rows', 1, $scopeRows, $scopeRows === 1),
        wp_fts_wc_gate('taxonomy_scope_ready_after_commit', 'ready targeted scope', $scopeState, is_array($scopeState) && ($scopeState['state'] ?? null) === 'ready' && ($scopeState['claim_token'] ?? null) === '' && (int) ($scopeState['claimed_generation'] ?? -1) === 0 && ($scopeState['scope_subject_type'] ?? null) === 'term_taxonomy' && (int) ($scopeState['scope_subject_id'] ?? 0) === (int) $manifest['term_taxonomy_id']),
        wp_fts_wc_gate('taxonomy_scope_canonical_term_updated', $updatedName, is_object($termAfter) ? (string) ($termAfter->name ?? '') : null, is_object($termAfter) && (string) ($termAfter->name ?? '') === $updatedName),
        wp_fts_wc_gate('taxonomy_scope_physical_schema_statements', 0, count($schemaStatements), $schemaStatements === []),
        wp_fts_wc_gate('taxonomy_scope_foreground_post_fanout', 0, max(0, $postRowsAfter - $postRowsBefore), $postRowsAfter === $postRowsBefore),
        ...$sparseProviders['gates'],
        ...$denseRelationships['gates'],
        ...$visibilityIndex['gates'],
        wp_fts_wc_gate('taxonomy_scope_search_failed_closed', true, $failedClosed, $failedClosed),
        wp_fts_wc_gate('taxonomy_scope_search_outcome', WP_FTS_Search_Unavailable::class, [$scopeSearchOutcome, $scopeSearchIds], is_a($scopeSearchOutcome, WP_FTS_Search_Unavailable::class, true) && $scopeSearchIds === []),
        wp_fts_wc_gate('taxonomy_scope_search_statement_shape', ['plan' => 1, 'rank' => 0, 'hydrate' => 0], $scopeSearchStatementShape, $scopeSearchStatementShape === ['plan' => 1, 'rank' => 0, 'hydrate' => 0] && count($scopeSearchSql) === 1),
        wp_fts_wc_gate('taxonomy_scope_active_broad_prefix_plan_only', ['identity_equality' => 0, 'kind_one' => 1, 'pt_ranges' => 2, 'all_term_ranges' => 2, 'rank' => 0, 'hydrate' => 0], ['identity_equality' => $scopePrefixEqualityCount, 'kind_one' => $scopePrefixKindCount, 'pt_ranges' => $scopePrefixRangeCount, 'all_term_ranges' => $scopeDictionaryTermRangeCount, 'rank' => $scopeSearchStatementShape['rank'], 'hydrate' => $scopeSearchStatementShape['hydrate']], $scopePrefixEqualityCount === 0 && $scopePrefixKindCount === 1 && $scopePrefixRangeCount === 2 && $scopeDictionaryTermRangeCount === 2 && $scopeSearchStatementShape['rank'] === 0 && $scopeSearchStatementShape['hydrate'] === 0),
        wp_fts_wc_gate('taxonomy_scope_active_surface_range_gated', 'one gated surface SUM(doc_freq) aggregate', $scopePrefixShapes, count($scopePrefixShapes) === 1 && ($scopePrefixShapes[0]['surface_exists_count_count'] ?? 0) === 1 && ($scopePrefixShapes[0]['surface_identity_limit_one_count'] ?? 0) === 0 && ($scopePrefixShapes[0]['surface_doc_freq_sum_count'] ?? 0) === 1),
        wp_fts_wc_gate('taxonomy_scope_active_broad_prefix_plan_rows', 2, $scopeSearchRowsSent, $scopeSearchRowsSent === 2),
        wp_fts_wc_gate('taxonomy_scope_active_exact_identity_index', 'exact lookup uses term_identity while the gated range is optimized away', $scopePlanTermAccess, $scopePlanUsesIdentityIndex),
        wp_fts_wc_gate('taxonomy_scope_active_broad_prefix_statement_bytes', '<= 32768', $scopeSearchMaxStatementBytes, $scopeSearchMaxStatementBytes <= 32768),
        wp_fts_wc_gate('taxonomy_scope_search_duration_ms', '<= 2000', $scopeSearchDuration, $scopeSearchDuration <= 2000.0),
        wp_fts_wc_gate('taxonomy_scope_search_rows_examined', "<= {$scopeSearchRowsExaminedLimit}", $scopeSearchRowsExamined, $scopeSearchRowsExamined <= $scopeSearchRowsExaminedLimit),
        wp_fts_wc_gate('taxonomy_scope_search_rows_sent', '<= 13', $scopeSearchRowsSent, $scopeSearchRowsSent <= 13),
        wp_fts_wc_gate('taxonomy_scope_search_disk_temp_tables', 0, $scopeSearchDiskTempTables, $scopeSearchDiskTempTables === 0),
        wp_fts_wc_gate('taxonomy_scope_search_sort_merge_passes', 0, $scopeSearchSortMergePasses, $scopeSearchSortMergePasses === 0),
        wp_fts_wc_gate('taxonomy_scope_search_no_good_index_flag', 0, $scopeSearchNoGoodIndexUsed, $scopeSearchNoGoodIndexUsed === 0),
        wp_fts_wc_gate('taxonomy_scope_search_server_duration_ms', '<= 2000', $scopeSearchServerDuration, $scopeSearchServerDuration <= 2000.0),
        wp_fts_wc_gate('taxonomy_scope_search_server_attribution', $scopeSearchSqlHashes, $scopeSearchPerformanceSqlHashes, count($scopeSearchSqlHashes) === 1 && $scopeSearchSqlHashes === $scopeSearchPerformanceSqlHashes),
        wp_fts_wc_gate('taxonomy_scope_search_explain_statement_shape', ['plan'], array_keys($scopeSearchPlans), array_keys($scopeSearchPlans) === ['plan']),
        wp_fts_wc_gate('taxonomy_scope_search_explain_indexed', ['coverage' => true, 'full_scans' => 0, 'missing_keys' => 0], ['coverage' => $scopeSearchPlanCoverage, 'full_scans' => $scopeSearchPlanFullScans, 'missing_keys' => $scopeSearchPlanMissingKeys], $scopeSearchPlanCoverage && $scopeSearchPlanFullScans === 0 && $scopeSearchPlanMissingKeys === 0),
        ...$targetedExpansion['gates'],
        wp_fts_wc_gate('taxonomy_scope_ordinary_page_available', true, $ordinaryAvailable, $ordinaryAvailable),
    ];
    $result = [
        'schema' => 'relational-fts-scope-proof-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'phase' => 'scope-proof',
        'duration_ms' => $duration,
        'statement_count' => count($ftsStatements),
        'max_statement_bytes' => max(array_map('strlen', $ftsStatements) ?: [0]),
        'sql' => $ftsStatements,
        'canonical_term_before' => (string) ($termBefore->name ?? ''),
        'canonical_term_after' => is_object($termAfter) ? (string) ($termAfter->name ?? '') : null,
        'scope_state' => $scopeState,
        'scope_rows' => $scopeRows,
        'post_rows_before' => $postRowsBefore,
        'post_rows_after' => $postRowsAfter,
        'sparse_providers' => $sparseProviders,
        'dense_relationship_search' => $denseRelationships,
        'visibility_index' => $visibilityIndex,
        'search_failed_closed' => $failedClosed,
        'search_outcome' => $scopeSearchOutcome,
        'search_ids' => $scopeSearchIds,
        'search_instrumentation' => [
            'duration_ms' => $scopeSearchDuration,
            'statement_count' => count($scopeSearchSql),
            'max_statement_bytes' => $scopeSearchMaxStatementBytes,
            'statement_shape' => $scopeSearchStatementShape,
            'surface_range_sql_shape' => $scopePrefixShapes,
            'dictionary_term_range_count' => $scopeDictionaryTermRangeCount,
            'sql' => $scopeSearchSql,
            'sql_sha256' => $scopeSearchSqlHashes,
            'performance_schema_sql_sha256' => $scopeSearchPerformanceSqlHashes,
            'performance_schema_events' => $scopeSearchEvents,
            'statement_metrics' => $scopeSearchStatementMetrics,
            'rows_examined' => $scopeSearchRowsExamined,
            'rows_examined_limit' => $scopeSearchRowsExaminedLimit,
            'rows_sent' => $scopeSearchRowsSent,
            'created_tmp_disk_tables' => $scopeSearchDiskTempTables,
            'sort_merge_passes' => $scopeSearchSortMergePasses,
            'no_index_used' => $scopeSearchNoIndexUsed,
            'no_good_index_used' => $scopeSearchNoGoodIndexUsed,
            'server_duration_ms' => $scopeSearchServerDuration,
            'explain_by_statement' => $scopeSearchPlans,
            'explain_fts_full_scans' => $scopeSearchPlanFullScans,
            'explain_fts_missing_keys' => $scopeSearchPlanMissingKeys,
        ],
        'targeted_scope_expansion' => $targetedExpansion,
        'ordinary_page_available' => $ordinaryAvailable,
        'gates' => $gates,
    ];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/scope-proof.json', $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Taxonomy scope proof failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }
    return ['status' => 'PASS', 'phase' => 'scope-proof', 'gate_failures' => []];
}

/**
 * Run the production dependency reader with no language provider, Polylang,
 * WPML, and both providers against sparse requested rows plus 100,000 decoys.
 * Provider probes are extracted from the prepared production relation rather
 * than copied into the harness, so their plans and server counters cover the
 * SQL that a worker actually emits.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_sparse_provider_plan_proof(array $manifest): array
{
    global $wpdb;

    $relationships = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_provider_relationships');
    $termTaxonomy = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_provider_term_taxonomy');
    $terms = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_provider_terms');
    $requested = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_provider_requested');
    $sequence = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_provider_sequence');
    $translations = wp_fts_wc_identifier((string) $wpdb->prefix . 'icl_translations');
    $originalTables = [
        'term_relationships' => (string) $wpdb->term_relationships,
        'term_taxonomy' => (string) $wpdb->term_taxonomy,
        'terms' => (string) $wpdb->terms,
    ];
    $hadPolylangGlobal = array_key_exists('polylang', $GLOBALS);
    $originalPolylangGlobal = $GLOBALS['polylang'] ?? null;
    $hadSitepressGlobal = array_key_exists('sitepress', $GLOBALS);
    $originalSitepressGlobal = $GLOBALS['sitepress'] ?? null;
    $wpmlFilter = static fn(mixed $details): mixed => $details;
    $translationsCreated = false;
    $dropFixture = static function () use (
        $wpdb,
        $relationships,
        $termTaxonomy,
        $terms,
        $requested,
        $sequence,
        $translations,
        &$translationsCreated
    ): void {
        $tables = [$relationships, $termTaxonomy, $terms, $requested, $sequence];
        if ($translationsCreated) {
            $tables[] = $translations;
        }
        foreach ($tables as $table) {
            wp_fts_wc_assert(
                $wpdb->query("DROP TABLE IF EXISTS `{$table}`") !== false,
                "Could not drop sparse provider fixture table {$table}."
            );
        }
        $translationsCreated = false;
    };

    $dropFixture();
    $existingTranslations = wp_fts_wc_checked_count($wpdb->prepare(
        'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=%s',
        $translations
    ), 'preexisting WPML translations table');
    wp_fts_wc_assert($existingTranslations === 0, 'Sparse provider proof requires a disposable site without an existing WPML translations table.');
    $polylangAlreadyActive = function_exists('pll_get_post_language')
        && (defined('POLYLANG_VERSION') || function_exists('PLL') || isset($GLOBALS['polylang']));
    $wpmlAlreadyActive = has_filter('wpml_post_language_details')
        && (defined('ICL_SITEPRESS_VERSION') || isset($GLOBALS['sitepress']));
    wp_fts_wc_assert(!$polylangAlreadyActive && !$wpmlAlreadyActive, 'Sparse provider proof requires both language providers to be initially inactive.');

    $result = [];
    try {
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$sequence}` (
                n bigint(20) unsigned NOT NULL,
                PRIMARY KEY (n)
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the sparse provider sequence table.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$requested}` (
                ordinal int(10) unsigned NOT NULL,
                post_id bigint(20) unsigned NOT NULL,
                post_type varchar(20) NOT NULL,
                PRIMARY KEY (ordinal),
                UNIQUE KEY post_id (post_id)
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the sparse provider requested-post table.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$relationships}` (
                object_id bigint(20) unsigned NOT NULL,
                term_taxonomy_id bigint(20) unsigned NOT NULL,
                term_order int(11) NOT NULL DEFAULT 0,
                PRIMARY KEY (object_id,term_taxonomy_id),
                KEY term_taxonomy_id (term_taxonomy_id)
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the sparse Polylang relationship table.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$termTaxonomy}` (
                term_taxonomy_id bigint(20) unsigned NOT NULL,
                term_id bigint(20) unsigned NOT NULL,
                taxonomy varchar(32) NOT NULL,
                description longtext NOT NULL,
                PRIMARY KEY (term_taxonomy_id),
                KEY term_id_taxonomy (term_id,taxonomy)
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the sparse Polylang taxonomy table.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$terms}` (
                term_id bigint(20) unsigned NOT NULL,
                name varchar(200) NOT NULL,
                slug varchar(200) NOT NULL,
                PRIMARY KEY (term_id),
                KEY slug (slug(191))
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the sparse Polylang terms table.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$translations}` (
                translation_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
                element_type varchar(60) NOT NULL,
                element_id bigint(20) unsigned DEFAULT NULL,
                trid bigint(20) unsigned NOT NULL,
                language_code varchar(7) NOT NULL,
                source_language_code varchar(7) DEFAULT NULL,
                PRIMARY KEY (translation_id),
                UNIQUE KEY trid_lang (trid,language_code),
                UNIQUE KEY el_type_id (element_type,element_id),
                KEY trid (trid),
                KEY id_type_language (element_id,element_type,language_code)
            ) ENGINE=InnoDB"
        ) !== false, 'Could not create the canonical sparse WPML translations table.');
        $translationsCreated = true;

        wp_fts_wc_assert($wpdb->query("INSERT INTO `{$sequence}` (n) VALUES (1)") === 1, 'Could not seed the sparse provider sequence.');
        $sequenceRows = 1;
        while ($sequenceRows < 100000) {
            $copy = min($sequenceRows, 100000 - $sequenceRows);
            $inserted = $wpdb->query(
                "INSERT INTO `{$sequence}` (n)
SELECT n+{$sequenceRows} FROM `{$sequence}` ORDER BY n ASC LIMIT {$copy}"
            );
            wp_fts_wc_assert($inserted === $copy, 'Could not double the complete sparse provider sequence.');
            $sequenceRows += $copy;
        }

        $sourcePosts = $wpdb->get_results($wpdb->prepare(
            "SELECT ID,post_type FROM {$wpdb->posts}
WHERE ID BETWEEN %d AND %d
ORDER BY ID ASC
LIMIT 100",
            (int) $manifest['first_post_id'],
            (int) $manifest['last_post_id']
        ), ARRAY_A) ?: [];
        wp_fts_wc_assert(count($sourcePosts) === 100, 'Sparse provider proof requires exactly 100 real corpus posts.');
        $requestedValues = [];
        $requestedArgs = [];
        $basePosts = [];
        $metaKeysByPost = [];
        foreach ($sourcePosts as $index => $sourcePost) {
            $postId = (int) ($sourcePost['ID'] ?? 0);
            $postType = (string) ($sourcePost['post_type'] ?? '');
            wp_fts_wc_assert($postId > 0 && $postType !== '', 'Sparse provider source post is malformed.');
            $requestedValues[] = '(%d,%d,%s)';
            array_push($requestedArgs, $index + 1, $postId, $postType);
            $basePosts[$postId] = (object) [
                'ID' => $postId,
                'post_type' => $postType,
                'fts_integration_language' => '',
            ];
            $metaKeysByPost[$postId] = [WP_FTS_Plugin::LANGUAGE_META_KEY];
        }
        $insertedRequested = $wpdb->query($wpdb->prepare(
            "INSERT INTO `{$requested}` (ordinal,post_id,post_type) VALUES " . implode(',', $requestedValues),
            ...$requestedArgs
        ));
        wp_fts_wc_assert($insertedRequested === 100, 'Could not seed exactly 100 sparse provider requested posts.');

        $boundarySourcePosts = $wpdb->get_results($wpdb->prepare(
            "SELECT ID,post_type FROM {$wpdb->posts}
WHERE ID BETWEEN %d AND %d
ORDER BY ID ASC
LIMIT 5 OFFSET 100",
            (int) $manifest['first_post_id'],
            (int) $manifest['last_post_id']
        ), ARRAY_A) ?: [];
        wp_fts_wc_assert(count($boundarySourcePosts) === 5, 'Sparse Polylang frontier proof requires five additional real corpus posts.');
        $boundaryPosts = [];
        $boundaryMetaKeys = [];
        foreach ($boundarySourcePosts as $sourcePost) {
            $postId = (int) ($sourcePost['ID'] ?? 0);
            $postType = (string) ($sourcePost['post_type'] ?? '');
            wp_fts_wc_assert($postId > 0 && $postType !== '', 'Sparse Polylang frontier post is malformed.');
            $boundaryPosts[$postId] = (object) [
                'ID' => $postId,
                'post_type' => $postType,
                'fts_integration_language' => '',
            ];
            $boundaryMetaKeys[$postId] = [WP_FTS_Plugin::LANGUAGE_META_KEY];
        }
        $boundaryPostIds = array_keys($boundaryPosts);

        $termValues = [];
        $termArgs = [];
        $taxonomyValues = [];
        $taxonomyArgs = [];
        $languageDescription = serialize(['locale' => 'fr_FR']);
        for ($termId = 1; $termId <= 20; $termId++) {
            $isLanguage = $termId === 20;
            $termValues[] = '(%d,%s,%s)';
            array_push($termArgs, $termId, $isLanguage ? 'French' : "Provider category {$termId}", $isLanguage ? 'fr' : "provider-category-{$termId}");
            $taxonomyValues[] = '(%d,%d,%s,%s)';
            array_push($taxonomyArgs, $termId, $termId, $isLanguage ? 'language' : 'category', $isLanguage ? $languageDescription : '');
        }
        wp_fts_wc_assert($wpdb->query($wpdb->prepare(
            "INSERT INTO `{$terms}` (term_id,name,slug) VALUES " . implode(',', $termValues),
            ...$termArgs
        )) === 20, 'Could not seed the sparse Polylang terms.');
        wp_fts_wc_assert($wpdb->query($wpdb->prepare(
            "INSERT INTO `{$termTaxonomy}` (term_taxonomy_id,term_id,taxonomy,description) VALUES " . implode(',', $taxonomyValues),
            ...$taxonomyArgs
        )) === 20, 'Could not seed the sparse Polylang taxonomy rows.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$terms}` (term_id,name,slug)
SELECT 1000+sequence.n,CONCAT('Boundary category ',sequence.n),CONCAT('boundary-category-',sequence.n)
FROM `{$sequence}` sequence
WHERE sequence.n<=512"
        ) === 512, 'Could not seed 512 non-language Polylang frontier terms.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$termTaxonomy}` (term_taxonomy_id,term_id,taxonomy,description)
SELECT 1000+sequence.n,1000+sequence.n,'category',''
FROM `{$sequence}` sequence
WHERE sequence.n<=512"
        ) === 512, 'Could not seed 512 non-language Polylang frontier taxonomies.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order)
SELECT requested.post_id, sequence.n, 0
FROM `{$requested}` requested
CROSS JOIN `{$sequence}` sequence
WHERE sequence.n<=20"
        ) === 2000, 'Could not seed twenty dependencies for every requested provider post.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order)
SELECT 6000000000+sequence.n, 1+MOD(sequence.n,19), 0
FROM `{$sequence}` sequence"
        ) === 100000, 'Could not seed 100,000 unrelated Polylang relationship rows.');
        $frontierDriver = implode("\nUNION ALL\n", array_fill(0, 4, 'SELECT %d AS post_id'));
        $frontierSql = $wpdb->prepare(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order)
SELECT frontier_post.post_id,1000+sequence.n,0
FROM ({$frontierDriver}) frontier_post
CROSS JOIN `{$sequence}` sequence
WHERE sequence.n<=512",
            ...array_slice($boundaryPostIds, 0, 4)
        );
        wp_fts_wc_assert(is_string($frontierSql) && $frontierSql !== '', 'Could not prepare the 4-by-512 Polylang frontier fixture.');
        wp_fts_wc_assert($wpdb->query($frontierSql) === 2048, 'Could not seed the exact four-by-512 non-language Polylang frontier.');
        wp_fts_wc_assert($wpdb->query($wpdb->prepare(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order) VALUES (%d,1001,0)",
            $boundaryPostIds[4]
        )) === 1, 'Could not seed the explicit 2,049th Polylang frontier sentinel.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$translations}` (element_type,element_id,trid,language_code,source_language_code)
SELECT CONCAT('post_',requested.post_type), requested.post_id, 6100000000+requested.ordinal, 'en', NULL
FROM `{$requested}` requested"
        ) === 100, 'Could not seed 100 exact WPML translations.');
        wp_fts_wc_assert($wpdb->query(
            "INSERT INTO `{$translations}` (element_type,element_id,trid,language_code,source_language_code)
SELECT 'post_decoy', 6200000000+sequence.n, 6200000000+sequence.n, 'de', NULL
FROM `{$sequence}` sequence"
        ) === 100000, 'Could not seed 100,000 unrelated WPML translations.');
        wp_fts_wc_assert(
            $wpdb->query("ANALYZE TABLE `{$relationships}`,`{$termTaxonomy}`,`{$terms}`,`{$translations}`,`{$requested}`") !== false,
            'Could not analyze the sparse provider fixtures.'
        );

        $fixtureCounts = [
            'requested_posts' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$requested}`", 'sparse provider requested posts'),
            'requested_relationships' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$relationships}` relationship_row INNER JOIN `{$requested}` requested_post ON requested_post.post_id=relationship_row.object_id", 'sparse provider requested relationships'),
            'frontier_relationships' => wp_fts_wc_checked_count($wpdb->prepare(
                "SELECT COUNT(*) FROM `{$relationships}` WHERE object_id IN (" . implode(',', array_fill(0, count($boundaryPostIds), '%d')) . ')',
                ...$boundaryPostIds
            ), 'sparse Polylang frontier relationships'),
            'relationship_decoys' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$relationships}` WHERE object_id>=6000000000", 'sparse provider relationship decoys'),
            'requested_translations' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$translations}` WHERE element_type<>'post_decoy'", 'sparse provider requested translations'),
            'translation_decoys' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$translations}` WHERE element_type='post_decoy'", 'sparse provider translation decoys'),
        ];
        $wpdb->term_relationships = $relationships;
        $wpdb->term_taxonomy = $termTaxonomy;
        $wpdb->terms = $terms;

        $loadDependencies = Closure::bind(
            static fn(array $posts, array $metaKeysByPost): array => WP_FTS_Plugin::load_bounded_index_dependencies($posts, $metaKeysByPost),
            null,
            WP_FTS_Plugin::class
        );
        $buildRelation = Closure::bind(
            static fn(array $metaKeysByPost): array => WP_FTS_Plugin::index_dependency_bounded_relation($metaKeysByPost),
            null,
            WP_FTS_Plugin::class
        );
        wp_fts_wc_assert($loadDependencies instanceof Closure && $buildRelation instanceof Closure, 'Could not bind the production dependency reader for sparse provider proof.');

        $scenarios = [];
        $scenarios['none'] = wp_fts_wc_measure_sparse_provider_scenario(
            'none',
            [],
            [],
            '',
            $basePosts,
            $metaKeysByPost,
            $loadDependencies,
            $buildRelation
        );

        $GLOBALS['sitepress'] = (object) ['wp_fts_fixture' => true];
        add_filter('wpml_post_language_details', $wpmlFilter, PHP_INT_MAX, 1);
        $scenarios['wpml'] = wp_fts_wc_measure_sparse_provider_scenario(
            'wpml',
            ['wpml'],
            ['wpml' => 100],
            'en',
            $basePosts,
            $metaKeysByPost,
            $loadDependencies,
            $buildRelation
        );
        remove_filter('wpml_post_language_details', $wpmlFilter, PHP_INT_MAX);
        unset($GLOBALS['sitepress']);

        if (!function_exists('pll_get_post_language')) {
            /** Make Polylang detectable while forcing the bounded relation fallback. */
            function pll_get_post_language(mixed $postId = null, mixed $field = null): bool
            {
                return false;
            }
        }
        $GLOBALS['polylang'] = (object) ['wp_fts_fixture' => true];
        $scenarios['polylang'] = wp_fts_wc_measure_sparse_provider_scenario(
            'polylang',
            ['polylang'],
            ['polylang' => 2000],
            'fr-FR',
            $basePosts,
            $metaKeysByPost,
            $loadDependencies,
            $buildRelation
        );
        $polylangFrontier = wp_fts_wc_measure_sparse_provider_scenario(
            'polylang-frontier',
            ['polylang'],
            ['polylang' => 2049],
            '',
            $boundaryPosts,
            $boundaryMetaKeys,
            $loadDependencies,
            $buildRelation
        );

        $GLOBALS['sitepress'] = (object) ['wp_fts_fixture' => true];
        add_filter('wpml_post_language_details', $wpmlFilter, PHP_INT_MAX, 1);
        $scenarios['both'] = wp_fts_wc_measure_sparse_provider_scenario(
            'both',
            ['polylang', 'wpml'],
            ['polylang' => 2000, 'wpml' => 100],
            'fr-FR',
            $basePosts,
            $metaKeysByPost,
            $loadDependencies,
            $buildRelation
        );

        $expectedKinds = [
            'none' => ['term', 'meta'],
            'wpml' => ['term', 'meta', 'wpml'],
            'polylang' => ['term', 'polylang', 'meta'],
            'both' => ['term', 'polylang', 'meta', 'wpml'],
        ];
        $actualKinds = [];
        $languages = [];
        $measurementAttributed = true;
        $complete = true;
        $providerPlans = true;
        $wpmlRowsExamined = 0;
        $wpmlRowsSent = 0;
        $wpmlDuration = 0.0;
        $wpmlNoDiskTempOrSort = true;
        $polylangRowsExamined = 0;
        $polylangRowsSent = 0;
        $polylangDuration = 0.0;
        $polylangNoDiskTempOrSort = true;
        foreach ($scenarios as $scenarioId => $scenario) {
            $actualKinds[$scenarioId] = $scenario['source_kinds'] ?? null;
            $languages[$scenarioId] = $scenario['languages'] ?? null;
            $measurementAttributed = $measurementAttributed && ($scenario['measurement_attributed'] ?? false) === true;
            $complete = $complete
                && ($scenario['overflow'] ?? true) === false
                && ($scenario['incomplete_post_ids'] ?? null) === []
                && (int) ($scenario['measurement_rows'] ?? -1) === 100;
            $expectedProviders = $scenarioId === 'none'
                ? []
                : ($scenarioId === 'both' ? ['polylang', 'wpml'] : [$scenarioId]);
            $actualProviders = array_keys(is_array($scenario['provider_probes'] ?? null) ? $scenario['provider_probes'] : []);
            $providerPlans = $providerPlans && $actualProviders === $expectedProviders;
            foreach ($scenario['provider_probes'] ?? [] as $provider => $probe) {
                $providerPlans = $providerPlans && ($probe['plan_valid'] ?? false) === true;
                $noDiskTempOrSort = (int) ($probe['created_tmp_disk_tables'] ?? -1) === 0
                    && (int) ($probe['sort_merge_passes'] ?? -1) === 0
                    && ($probe['statement_attributed'] ?? false) === true;
                if ($provider === 'wpml') {
                    $wpmlRowsExamined = max($wpmlRowsExamined, (int) ($probe['rows_examined'] ?? PHP_INT_MAX));
                    $wpmlRowsSent = max($wpmlRowsSent, (int) ($probe['rows_sent'] ?? PHP_INT_MAX));
                    $wpmlDuration = max($wpmlDuration, (float) ($probe['duration_ms'] ?? PHP_INT_MAX), (float) ($probe['server_duration_ms'] ?? PHP_INT_MAX));
                    $wpmlNoDiskTempOrSort = $wpmlNoDiskTempOrSort && $noDiskTempOrSort;
                } elseif ($provider === 'polylang') {
                    $polylangRowsExamined = max($polylangRowsExamined, (int) ($probe['rows_examined'] ?? PHP_INT_MAX));
                    $polylangRowsSent = max($polylangRowsSent, (int) ($probe['rows_sent'] ?? PHP_INT_MAX));
                    $polylangDuration = max($polylangDuration, (float) ($probe['duration_ms'] ?? PHP_INT_MAX), (float) ($probe['server_duration_ms'] ?? PHP_INT_MAX));
                    $polylangNoDiskTempOrSort = $polylangNoDiskTempOrSort && $noDiskTempOrSort;
                }
            }
        }
        $frontierProbe = is_array($polylangFrontier['provider_probes']['polylang'] ?? null)
            ? $polylangFrontier['provider_probes']['polylang']
            : [];
        $frontierExpectedIncomplete = [(int) $boundaryPostIds[4]];
        $frontierComplete = ($polylangFrontier['source_kinds'] ?? null) === ['term', 'polylang', 'meta']
            && ($polylangFrontier['languages'] ?? null) === array_fill(0, 5, '')
            && ($polylangFrontier['overflow'] ?? false) === true
            && ($polylangFrontier['incomplete_post_ids'] ?? null) === $frontierExpectedIncomplete
            && (int) ($polylangFrontier['measurement_rows'] ?? -1) === 5
            && ($polylangFrontier['measurement_attributed'] ?? false) === true
            && ($frontierProbe['plan_valid'] ?? false) === true
            && (int) ($frontierProbe['result_rows'] ?? -1) === 2049
            && count($frontierProbe['result_post_ids'] ?? []) === 5;
        $frontierNoDiskTempOrSort = (int) ($frontierProbe['created_tmp_disk_tables'] ?? -1) === 0
            && (int) ($frontierProbe['sort_merge_passes'] ?? -1) === 0
            && ($frontierProbe['statement_attributed'] ?? false) === true;
        $polylangRowsExamined = max($polylangRowsExamined, (int) ($frontierProbe['rows_examined'] ?? PHP_INT_MAX));
        $polylangRowsSent = max($polylangRowsSent, (int) ($frontierProbe['rows_sent'] ?? PHP_INT_MAX));
        $polylangDuration = max($polylangDuration, (float) ($frontierProbe['duration_ms'] ?? PHP_INT_MAX), (float) ($frontierProbe['server_duration_ms'] ?? PHP_INT_MAX));
        $polylangNoDiskTempOrSort = $polylangNoDiskTempOrSort && $frontierNoDiskTempOrSort;

        $expectedLanguages = [
            'none' => array_fill(0, 100, ''),
            'wpml' => array_fill(0, 100, 'en'),
            'polylang' => array_fill(0, 100, 'fr-FR'),
            'both' => array_fill(0, 100, 'fr-FR'),
        ];
        $expectedFixtureCounts = [
            'requested_posts' => 100,
            'requested_relationships' => 2000,
            'frontier_relationships' => 2049,
            'relationship_decoys' => 100000,
            'requested_translations' => 100,
            'translation_decoys' => 100000,
        ];
        $gates = [
            wp_fts_wc_gate('provider_sparse_fixture_cardinality', $expectedFixtureCounts, $fixtureCounts, $fixtureCounts === $expectedFixtureCounts),
            wp_fts_wc_gate('provider_sparse_four_real_scenarios', $expectedKinds, $actualKinds, $actualKinds === $expectedKinds),
            wp_fts_wc_gate('provider_sparse_language_precedence', $expectedLanguages, $languages, $languages === $expectedLanguages),
            wp_fts_wc_gate('provider_sparse_measurement_attribution', true, $measurementAttributed, $measurementAttributed),
            wp_fts_wc_gate('provider_sparse_no_overflow_or_incomplete_posts', true, $complete, $complete),
            wp_fts_wc_gate('provider_sparse_production_plan_coverage', true, $providerPlans, $providerPlans),
            wp_fts_wc_gate('polylang_sparse_raw_frontier_cardinality', ['four_complete_posts' => 4, 'rows_per_complete_post' => 512, 'cursor_sentinel_rows' => 1, 'raw_rows' => 2049], ['post_ids' => $boundaryPostIds, 'fixture_rows' => $fixtureCounts['frontier_relationships'] ?? null, 'probe_rows' => $frontierProbe['result_rows'] ?? null], ($fixtureCounts['frontier_relationships'] ?? null) === 2049 && (int) ($frontierProbe['result_rows'] ?? -1) === 2049),
            wp_fts_wc_gate('polylang_sparse_raw_frontier_completion', ['complete' => array_slice($boundaryPostIds, 0, 4), 'incomplete' => $frontierExpectedIncomplete], ['overflow' => $polylangFrontier['overflow'] ?? null, 'incomplete' => $polylangFrontier['incomplete_post_ids'] ?? null], $frontierComplete),
            wp_fts_wc_gate('polylang_sparse_raw_frontier_primary_plan', true, $frontierProbe['provider_access'] ?? null, ($frontierProbe['plan_valid'] ?? false) === true),
            wp_fts_wc_gate('polylang_sparse_raw_frontier_server_attribution', true, $frontierProbe['statement_attributed'] ?? false, ($frontierProbe['statement_attributed'] ?? false) === true && ($polylangFrontier['measurement_attributed'] ?? false) === true),
            wp_fts_wc_gate('wpml_sparse_rows_examined', '<= 300 for 100 post PK rows, 100 translation point rows, and 100 bounded derived rows', $wpmlRowsExamined, $wpmlRowsExamined <= 300),
            wp_fts_wc_gate('wpml_sparse_rows_sent', 100, $wpmlRowsSent, $wpmlRowsSent === 100),
            wp_fts_wc_gate('wpml_sparse_no_disk_temp_or_sort', 0, $wpmlNoDiskTempOrSort ? 0 : 1, $wpmlNoDiskTempOrSort),
            wp_fts_wc_gate('wpml_sparse_duration_ms', '<= 2000', $wpmlDuration, $wpmlDuration <= 2000.0),
            wp_fts_wc_gate('polylang_sparse_rows_examined', '<= 8500 for the 2,049-row raw frontier, two indexed joins, and derived output', $polylangRowsExamined, $polylangRowsExamined <= 8500),
            wp_fts_wc_gate('polylang_sparse_rows_sent', 2049, $polylangRowsSent, $polylangRowsSent === 2049),
            wp_fts_wc_gate('polylang_sparse_no_disk_temp_or_sort', 0, $polylangNoDiskTempOrSort ? 0 : 1, $polylangNoDiskTempOrSort),
            wp_fts_wc_gate('polylang_sparse_duration_ms', '<= 2000', $polylangDuration, $polylangDuration <= 2000.0),
        ];
        $result = [
            'schema' => 'relational-fts-sparse-provider-plan-v1',
            'fixture_counts' => $fixtureCounts,
            'scenarios' => $scenarios,
            'polylang_raw_frontier' => $polylangFrontier,
            'gates' => $gates,
        ];
    } finally {
        remove_filter('wpml_post_language_details', $wpmlFilter, PHP_INT_MAX);
        if ($hadSitepressGlobal) {
            $GLOBALS['sitepress'] = $originalSitepressGlobal;
        } else {
            unset($GLOBALS['sitepress']);
        }
        if ($hadPolylangGlobal) {
            $GLOBALS['polylang'] = $originalPolylangGlobal;
        } else {
            unset($GLOBALS['polylang']);
        }
        foreach ($originalTables as $property => $table) {
            $wpdb->{$property} = $table;
        }
        $dropFixture();
    }

    $remainingTables = wp_fts_wc_checked_count($wpdb->prepare(
        'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN (%s,%s,%s,%s,%s,%s)',
        $relationships,
        $termTaxonomy,
        $terms,
        $requested,
        $sequence,
        $translations
    ), 'sparse provider fixture cleanup');
    $result['gates'][] = wp_fts_wc_gate('provider_sparse_fixture_cleanup', 0, $remainingTables, $remainingTables === 0);

    return $result;
}

/**
 * @param string[] $expectedProviders
 * @param array<string,int> $expectedProviderRows
 * @param array<int,object> $basePosts
 * @param array<int,string[]> $metaKeysByPost
 * @return array<string,mixed>
 */
function wp_fts_wc_measure_sparse_provider_scenario(
    string $scenarioId,
    array $expectedProviders,
    array $expectedProviderRows,
    string $expectedLanguage,
    array $basePosts,
    array $metaKeysByPost,
    Closure $loadDependencies,
    Closure $buildRelation
): array {
    global $wpdb;

    $posts = [];
    foreach ($basePosts as $postId => $post) {
        $posts[$postId] = clone $post;
        $posts[$postId]->fts_integration_language = '';
    }
    $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID()');
    wp_fts_wc_assert($threadId > 0, "Could not map sparse provider scenario {$scenarioId} to Performance Schema.");
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $threadId
    ));
    $recorded = wp_fts_wc_record_queries(static fn(): array => $loadDependencies($posts, $metaKeysByPost));
    $measurementSql = array_values(array_filter(
        $recorded['queries'],
        static fn(string $sql): bool => str_contains($sql, 'wp_fts:dependency_measurement')
    ));
    wp_fts_wc_assert(count($measurementSql) === 1, "Sparse provider scenario {$scenarioId} did not execute exactly one production dependency measurement.");
    $measurementEvents = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $measurementEvents = array_values(array_filter(
        $measurementEvents,
        static fn(array $event): bool => str_contains((string) ($event['SQL_TEXT'] ?? ''), 'wp_fts:dependency_measurement')
    ));
    $measurementAttributed = count($measurementEvents) === 1
        && (string) ($measurementEvents[0]['SQL_TEXT'] ?? '') === $measurementSql[0];

    [$relationSql, $relationArgs, $sourceKinds] = $buildRelation($metaKeysByPost);
    $preparedRelation = $wpdb->prepare($relationSql, ...$relationArgs);
    wp_fts_wc_assert(is_string($preparedRelation) && $preparedRelation !== '', "Could not prepare sparse provider relation {$scenarioId}.");
    $providerBranches = [];
    foreach (wp_fts_wc_dependency_relation_branches($preparedRelation) as $branch) {
        if (str_contains($branch, 'wp_fts:polylang-languages')) {
            $providerBranches['polylang'] = $branch;
        } elseif (str_contains($branch, 'wp_fts:wpml-languages')) {
            $providerBranches['wpml'] = $branch;
        }
    }
    wp_fts_wc_assert(array_keys($providerBranches) === $expectedProviders, "Sparse provider scenario {$scenarioId} emitted the wrong provider branches.");

    $fullPlanJson = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $measurementSql[0]);
    wp_fts_wc_assert(is_string($fullPlanJson) && $fullPlanJson !== '', "Sparse provider scenario {$scenarioId} returned no full JSON plan.");
    $fullPlan = json_decode($fullPlanJson, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($fullPlan), "Sparse provider scenario {$scenarioId} returned malformed full JSON plan.");
    $fullAccess = [];
    wp_fts_wc_collect_database_table_access($fullPlan, $fullAccess);

    $probes = [];
    foreach ($providerBranches as $provider => $branch) {
        $probes[$provider] = wp_fts_wc_measure_sparse_provider_branch(
            $scenarioId,
            $provider,
            $branch,
            (int) ($expectedProviderRows[$provider] ?? 0),
            count($posts)
        );
    }
    $dependencyResult = is_array($recorded['result'] ?? null) ? $recorded['result'] : [];
    $languages = array_values(array_map(
        static fn(object $post): string => (string) ($post->fts_integration_language ?? ''),
        $posts
    ));
    wp_fts_wc_assert($languages === array_fill(0, count($posts), $expectedLanguage), "Sparse provider scenario {$scenarioId} produced the wrong language precedence.");

    return [
        'source_kinds' => $sourceKinds,
        'languages' => $languages,
        'overflow' => $dependencyResult['overflow'] ?? null,
        'incomplete_post_ids' => array_values(array_map('intval', array_keys(is_array($dependencyResult['incomplete_post_ids'] ?? null) ? $dependencyResult['incomplete_post_ids'] : []))),
        'measurement_rows' => count(is_array($dependencyResult['measurements'] ?? null) ? $dependencyResult['measurements'] : []),
        'measurement_sql_sha256' => hash('sha256', $measurementSql[0]),
        'measurement_event' => $measurementEvents[0] ?? null,
        'measurement_attributed' => $measurementAttributed,
        'full_plan' => $fullPlan,
        'full_table_access' => $fullAccess,
        'provider_probes' => $probes,
    ];
}

/** @return string[] */
function wp_fts_wc_dependency_relation_branches(string $sql): array
{
    $branches = [];
    $lines = [];
    foreach (explode("\n", $sql) as $line) {
        // The production builder emits every top-level separator on its own
        // line. Scanning that generated record boundary avoids pretending a
        // regexp can parse nested derived-table SQL.
        if (trim($line) === 'UNION ALL') {
            $branch = trim(implode("\n", $lines));
            wp_fts_wc_assert($branch !== '', 'Production dependency relation contains an empty UNION branch.');
            $branches[] = $branch;
            $lines = [];
            continue;
        }
        $lines[] = $line;
    }
    $branch = trim(implode("\n", $lines));
    wp_fts_wc_assert($branch !== '', 'Production dependency relation ends with an empty UNION branch.');
    $branches[] = $branch;

    return $branches;
}

/** @return array<string,mixed> */
function wp_fts_wc_measure_sparse_provider_branch(
    string $scenarioId,
    string $provider,
    string $branch,
    int $expectedResultRows,
    int $expectedPostCount
): array
{
    global $wpdb;

    $tag = "wp_fts:provider-sparse-{$scenarioId}-{$provider}";
    $sql = "/* {$tag} */\n{$branch}";
    $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID()');
    wp_fts_wc_assert($threadId > 0, "Could not map sparse {$provider} probe to Performance Schema.");
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $threadId
    ));
    $started = hrtime(true);
    $rows = $wpdb->get_results($sql, ARRAY_A);
    $duration = wp_fts_wc_elapsed_ms($started);
    wp_fts_wc_assert(is_array($rows), "Sparse {$provider} production branch failed: " . trim((string) $wpdb->last_error));
    $events = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $events = array_values(array_filter(
        $events,
        static fn(array $event): bool => str_contains((string) ($event['SQL_TEXT'] ?? ''), $tag)
    ));
    $event = count($events) === 1 ? $events[0] : [];

    $planJson = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
    wp_fts_wc_assert(is_string($planJson) && $planJson !== '', "Sparse {$provider} branch returned no JSON plan.");
    $plan = json_decode($planJson, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($plan), "Sparse {$provider} branch returned malformed JSON plan.");
    $access = [];
    wp_fts_wc_collect_database_table_access($plan, $access);
    $providerAlias = $provider === 'wpml' ? 'wpml_translation' : 'raw_language_rel';
    $providerAccess = array_values(array_filter(
        $access,
        static fn(array $row): bool => strtolower((string) ($row['table_name'] ?? '')) === $providerAlias
    ));
    $expectedKey = $provider === 'wpml' ? 'el_type_id' : 'PRIMARY';
    $providerPlan = $providerAccess[0] ?? [];
    $statementAttributed = count($events) === 1 && (string) ($event['SQL_TEXT'] ?? '') === $sql;
    $directKeyedPlan = strcasecmp((string) ($providerPlan['key'] ?? ''), $expectedKey) === 0
        && strtoupper((string) ($providerPlan['access_type'] ?? '')) !== 'ALL'
        && is_int($providerPlan['rows'] ?? null)
        && (int) $providerPlan['rows'] <= ($provider === 'wpml' ? 100 : 2049);
    // MySQL reports this forced expression lookup as a table estimate plus a
    // per-outer-row range choice. Accept that exact shape only when the
    // attributed statement proves it touched the bounded runtime frontier.
    $mysqlRangeCheckedPlan = $provider === 'wpml'
        && wp_fts_wc_engine_family() === 'mysql'
        && strtoupper((string) ($providerPlan['access_type'] ?? '')) === 'ALL'
        && (string) ($providerPlan['key'] ?? '') === ''
        && ($providerPlan['possible_keys'] ?? null) === [$expectedKey]
        && trim((string) ($providerPlan['range_checked_for_each_record'] ?? '')) !== ''
        && $statementAttributed
        && (int) ($event['ROWS_EXAMINED'] ?? PHP_INT_MAX) <= 300
        && (int) ($event['ROWS_SENT'] ?? -1) === $expectedResultRows
        && (int) ($event['CREATED_TMP_DISK_TABLES'] ?? -1) === 0
        && (int) ($event['SORT_MERGE_PASSES'] ?? -1) === 0;
    $planValid = count($providerAccess) === 1 && ($directKeyedPlan || $mysqlRangeCheckedPlan);
    $postIds = array_values(array_unique(array_map(
        static fn(array $row): int => (int) ($row['post_id'] ?? 0),
        $rows
    )));
    sort($postIds, SORT_NUMERIC);

    return [
        'sql' => $sql,
        'sql_sha256' => hash('sha256', $sql),
        'result_rows' => count($rows),
        'result_post_ids' => $postIds,
        'duration_ms' => $duration,
        'server_duration_ms' => $event === [] ? (float) PHP_INT_MAX : max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
        'rows_examined' => $event === [] ? PHP_INT_MAX : max(0, (int) ($event['ROWS_EXAMINED'] ?? 0)),
        'rows_sent' => $event === [] ? PHP_INT_MAX : max(0, (int) ($event['ROWS_SENT'] ?? 0)),
        'created_tmp_disk_tables' => $event === [] ? -1 : (int) ($event['CREATED_TMP_DISK_TABLES'] ?? -1),
        'sort_merge_passes' => $event === [] ? -1 : (int) ($event['SORT_MERGE_PASSES'] ?? -1),
        'no_index_used' => $event === [] ? -1 : (int) ($event['NO_INDEX_USED'] ?? -1),
        'no_good_index_used' => $event === [] ? -1 : (int) ($event['NO_GOOD_INDEX_USED'] ?? -1),
        'statement_attributed' => $statementAttributed,
        'performance_schema_event' => $event,
        'plan' => $plan,
        'table_access' => $access,
        'provider_access' => $providerAccess,
        'plan_valid' => $planValid && count($rows) === $expectedResultRows && count($postIds) === $expectedPostCount,
    ];
}

/**
 * Prove that search cost is independent of taxonomy fanout after reconciliation
 * moved into the plan control boundary. The 51.2-million-row MyISAM fixture has
 * WordPress's canonical relationship columns and all three relevant indexes;
 * MyISAM is used only to make a zero-access negative proof practical. Its seed
 * time, bytes, and engine are not production performance claims. The populated
 * current-schema repair/concurrent-write proof separately exercises canonical InnoDB.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_dense_relationship_search_proof(array $manifest, string $work): array
{
    global $wpdb;

    $relationships = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_dense_relationships');
    $objects = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_dense_objects');
    $terms = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_dense_terms');
    $originalRelationships = (string) $wpdb->term_relationships;
    $expectedObjects = 100000;
    $relationshipsPerObject = 512;
    $expectedRelationships = $expectedObjects * $relationshipsPerObject;
    $objectBase = 7000000000;
    $activeScopeKey = 'wc-dense-active-targeted-scope';
    $raceScopeKey = 'wc-dense-race-targeted-scope';
    $remainingTables = PHP_INT_MAX;
    $dropFixture = static function () use ($wpdb, $relationships, $objects, $terms): void {
        foreach ([$relationships, $objects, $terms] as $table) {
            wp_fts_wc_assert(
                $wpdb->query("DROP TABLE IF EXISTS `{$table}`") !== false,
                "Could not drop dense relationship fixture table {$table}."
            );
        }
    };
    $deleteScope = static function (string $jobKey) use ($wpdb, $work): void {
        $deleted = $wpdb->query($wpdb->prepare("DELETE FROM `{$work}` WHERE job_key=%s", $jobKey));
        wp_fts_wc_assert(is_int($deleted), "Could not remove dense relationship scope {$jobKey}.");
    };
    $insertScopeSql = static function (string $jobKey, int $subjectId) use ($wpdb, $work): string {
        $sql = $wpdb->prepare(
            "INSERT INTO `{$work}`
 (job_key,kind,post_id,generation,state,available_at,scope_coverage,scope_subject_type,scope_subject_id)
VALUES (%s,'scope',0,1,'pending',1,'targeted','term_taxonomy',%d)",
            $jobKey,
            $subjectId
        );
        wp_fts_wc_assert(is_string($sql) && $sql !== '', "Could not prepare dense relationship scope {$jobKey}.");

        return $sql;
    };

    $dropFixture();
    $deleteScope($activeScopeKey);
    $deleteScope($raceScopeKey);
    $memoryBefore = memory_get_usage(true);
    $seedStarted = hrtime(true);
    $result = [];
    try {
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$objects}` (n int(10) unsigned NOT NULL, PRIMARY KEY (n)) ENGINE=MyISAM"
        ) !== false, 'Could not create the dense relationship object sequence.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$terms}` (n int(10) unsigned NOT NULL, PRIMARY KEY (n)) ENGINE=MyISAM"
        ) !== false, 'Could not create the dense relationship term sequence.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$relationships}` (
                object_id bigint(20) unsigned NOT NULL,
                term_taxonomy_id bigint(20) unsigned NOT NULL,
                term_order int(11) NOT NULL DEFAULT 0,
                PRIMARY KEY (object_id,term_taxonomy_id),
                KEY term_taxonomy_id (term_taxonomy_id),
                KEY wp_fts_term_object (term_taxonomy_id,object_id)
            ) ENGINE=MyISAM"
        ) !== false, 'Could not create the indexed dense relationship table.');
        wp_fts_wc_assert($wpdb->query("ALTER TABLE `{$relationships}` DISABLE KEYS") !== false, 'Could not defer dense relationship secondary-key construction.');

        wp_fts_wc_assert($wpdb->query("INSERT INTO `{$objects}` (n) VALUES (1)") === 1, 'Could not seed the dense object sequence.');
        $objectRows = 1;
        $objectSeedStatements = 1;
        while ($objectRows < $expectedObjects) {
            $copy = min($objectRows, $expectedObjects - $objectRows);
            $inserted = $wpdb->query(
                "INSERT INTO `{$objects}` (n) SELECT n+{$objectRows} FROM `{$objects}` ORDER BY n ASC LIMIT {$copy}"
            );
            wp_fts_wc_assert($inserted === $copy, 'Could not double the dense object sequence.');
            $objectRows += $copy;
            $objectSeedStatements++;
        }
        wp_fts_wc_assert($wpdb->query("INSERT INTO `{$terms}` (n) VALUES (1)") === 1, 'Could not seed the dense term sequence.');
        $termRows = 1;
        $termSeedStatements = 1;
        while ($termRows < $relationshipsPerObject) {
            $copy = min($termRows, $relationshipsPerObject - $termRows);
            $inserted = $wpdb->query(
                "INSERT INTO `{$terms}` (n) SELECT n+{$termRows} FROM `{$terms}` ORDER BY n ASC LIMIT {$copy}"
            );
            wp_fts_wc_assert($inserted === $copy, 'Could not double the dense term sequence.');
            $termRows += $copy;
            $termSeedStatements++;
        }
        $insertedRelationships = $wpdb->query(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order)
SELECT {$objectBase}+dense_object.n,dense_term.n,0
FROM `{$objects}` dense_object
STRAIGHT_JOIN `{$terms}` dense_term
ORDER BY dense_object.n ASC,dense_term.n ASC"
        );
        wp_fts_wc_assert($insertedRelationships === $expectedRelationships, 'Could not seed the complete 100,000-by-512 relationship fixture.');
        wp_fts_wc_assert($wpdb->query("ALTER TABLE `{$relationships}` ENABLE KEYS") !== false, 'Could not build the dense relationship secondary indexes.');
        wp_fts_wc_assert($wpdb->query("ANALYZE TABLE `{$relationships}`") !== false, 'Could not analyze the dense relationship fixture.');
        $seedDuration = wp_fts_wc_elapsed_ms($seedStarted);

        $fixtureCounts = [
            'objects' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$objects}`", 'dense relationship objects'),
            'terms_per_object' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$terms}`", 'dense relationship terms per object'),
            'relationships' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$relationships}`", 'dense relationship rows'),
            'first_object_rows' => wp_fts_wc_checked_count($wpdb->prepare("SELECT COUNT(*) FROM `{$relationships}` WHERE object_id=%d", $objectBase + 1), 'dense first object rows'),
            'last_object_rows' => wp_fts_wc_checked_count($wpdb->prepare("SELECT COUNT(*) FROM `{$relationships}` WHERE object_id=%d", $objectBase + $expectedObjects), 'dense last object rows'),
        ];
        $fixtureIndexes = [
            'PRIMARY' => wp_fts_wc_scope_index_columns($relationships, 'PRIMARY'),
            'term_taxonomy_id' => wp_fts_wc_scope_index_columns($relationships, 'term_taxonomy_id'),
            'wp_fts_term_object' => wp_fts_wc_scope_index_columns($relationships, 'wp_fts_term_object'),
        ];
        $fixtureStorage = array_change_key_case($wpdb->get_row($wpdb->prepare(
            'SELECT engine,data_length,index_length FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=%s',
            $relationships
        ), ARRAY_A) ?: [], CASE_LOWER);

        $wpdb->term_relationships = $relationships;
        WP_FTS_Plugin::reset_request_caches();
        $scopeRowsBefore = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind='scope'", 'scope rows before dense no-access search');
        wp_fts_wc_assert($scopeRowsBefore === 0, 'Dense no-access search requires an initially scope-free index.');

        $measureSearch = static function (string $caseId, ?Closure $beforeRank = null) use ($wpdb, $relationships): array {
            WP_FTS_Plugin::reset_request_caches();
            $queries = [];
            $injected = false;
            $filter = static function (string $sql) use (&$queries, &$injected, $beforeRank): string {
                $kind = wp_fts_wc_search_statement_kind($sql);
                if ($kind === null) {
                    return $sql;
                }
                if ($kind === 'rank' && !$injected && $beforeRank !== null) {
                    $beforeRank();
                    $injected = true;
                }
                $queries[] = $sql;

                return $sql;
            };
            $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID()');
            wp_fts_wc_assert($threadId > 0, "Could not map dense relationship search {$caseId} to Performance Schema.");
            $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
                'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
                $threadId
            ));
            $typedUnavailable = false;
            $outcome = 'results';
            $rows = [];
            $started = hrtime(true);
            add_filter('query', $filter, PHP_INT_MAX, 1);
            try {
                $rows = WP_FTS_Plugin::search('prefixprobe', ['lang' => 'en', 'mode' => 'OR', 'limit' => 20, 'prefix_matching' => true, 'prefix_min_length' => 4]);
            } catch (WP_FTS_Search_Unavailable $error) {
                $typedUnavailable = true;
                $outcome = get_class($error) . ': ' . $error->getMessage();
            } finally {
                remove_filter('query', $filter, PHP_INT_MAX);
            }
            $duration = wp_fts_wc_elapsed_ms($started);
            $events = $wpdb->get_results($wpdb->prepare(
                'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
                $threadId,
                $beforeEvent
            ), ARRAY_A) ?: [];
            $events = array_values(array_filter(
                $events,
                static fn(array $event): bool => wp_fts_wc_search_statement_kind((string) ($event['SQL_TEXT'] ?? '')) !== null
            ));
            $performanceSql = array_map(static fn(array $event): string => (string) ($event['SQL_TEXT'] ?? ''), $events);
            $shape = ['plan' => 0, 'rank' => 0, 'hydrate' => 0];
            $relationshipSqlReferences = 0;
            $relationshipPlanReferences = 0;
            $relationAllowlists = true;
            $plans = [];
            $definition = ['query' => 'prefixprobe', 'options' => ['query_lang' => 'en', 'mode' => 'OR', 'limit' => 20, 'prefix_matching' => true, 'prefix_min_length' => 4]];
            foreach ($queries as $sql) {
                $kind = wp_fts_wc_search_statement_kind($sql);
                if ($kind === null) {
                    continue;
                }
                $shape[$kind]++;
                if (str_contains($sql, $relationships) || str_contains(strtolower($sql), 'term_relationship')) {
                    $relationshipSqlReferences++;
                }
                $planJson = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
                $plan = is_string($planJson) && $planJson !== ''
                    ? json_decode($planJson, true, 512, JSON_THROW_ON_ERROR)
                    : null;
                $access = [];
                if (is_array($plan)) {
                    wp_fts_wc_collect_database_table_access($plan, $access);
                }
                foreach ($access as $accessRow) {
                    $tableName = strtolower((string) ($accessRow['table_name'] ?? ''));
                    if ($tableName === strtolower($relationships) || str_contains($tableName, 'relationship')) {
                        $relationshipPlanReferences++;
                    }
                }
                $declared = array_values(array_unique(array_column(wp_fts_wc_sql_fts_relations($sql), 'table')));
                sort($declared, SORT_STRING);
                $expected = wp_fts_wc_expected_statement_relations($kind, $definition);
                $relationAllowlists = $relationAllowlists && $declared === $expected;
                $plans[$kind] = [
                    'sql_sha256' => hash('sha256', $sql),
                    'declared_fts_relations' => $declared,
                    'expected_fts_relations' => $expected,
                    'plan' => $plan,
                    'table_access' => $access,
                ];
            }
            $resultIds = array_values(array_map('intval', array_column(is_array($rows) ? $rows : [], 'doc_id')));
            $serverDuration = array_sum(array_map(
                static fn(array $event): float => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
                $events
            ));
            $statementMetrics = wp_fts_wc_search_statement_metrics($events);

            return [
                'outcome' => $outcome,
                'typed_unavailable' => $typedUnavailable,
                'result_ids' => $resultIds,
                'duration_ms' => $duration,
                'server_duration_ms' => $serverDuration,
                'statement_shape' => $shape,
                'sql' => $queries,
                'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
                'performance_schema_sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $performanceSql),
                'performance_schema_events' => $events,
                'statement_metrics' => $statementMetrics,
                'surface_range_sql_shape' => array_map('wp_fts_wc_surface_range_sql_shape', $queries),
                'server_attributed' => $queries === $performanceSql,
                'relationship_sql_references' => $relationshipSqlReferences,
                'relationship_plan_references' => $relationshipPlanReferences,
                'relation_allowlists_valid' => $relationAllowlists,
                'plans' => $plans,
                'before_rank_injected' => $injected,
            ];
        };

        $noScope = $measureSearch('no-scope');

        $activeScopeSql = $insertScopeSql($activeScopeKey, 7100000001);
        wp_fts_wc_assert($wpdb->query($activeScopeSql) === 1, 'Could not seed the active targeted scope for dense relationship search.');
        $activeScope = $measureSearch('active-targeted-scope');
        $activeScopeRows = wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE job_key=%s AND kind='scope' AND scope_coverage='targeted'",
            $activeScopeKey
        ), 'dense active targeted scope');
        $deleteScope($activeScopeKey);

        $raceScopeSql = $insertScopeSql($raceScopeKey, 7100000002);
        $raceInsertAffected = 0;
        $readDatabaseHandle = Closure::bind(
            function (): mixed {
                return $this->dbh;
            },
            $wpdb,
            get_class($wpdb)
        );
        wp_fts_wc_assert($readDatabaseHandle instanceof Closure, 'Could not bind the real wpdb connection handle reader.');
        $databaseHandle = $readDatabaseHandle();
        wp_fts_wc_assert($databaseHandle instanceof mysqli, 'Dense plan/rank race requires the real mysqli connection.');
        $injectRaceScope = static function () use ($databaseHandle, $raceScopeSql, &$raceInsertAffected): void {
            $queryResult = mysqli_query($databaseHandle, $raceScopeSql);
            wp_fts_wc_assert($queryResult === true, 'Could not insert the targeted scope between plan and rank.');
            $raceInsertAffected = mysqli_affected_rows($databaseHandle);
            wp_fts_wc_assert($raceInsertAffected === 1, 'Plan/rank race did not insert exactly one targeted scope.');
        };
        $raceScope = $measureSearch('plan-rank-scope-race', $injectRaceScope);
        $raceScopeRows = wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE job_key=%s AND kind='scope' AND scope_coverage='targeted'",
            $raceScopeKey
        ), 'dense plan/rank race targeted scope');
        $deleteScope($raceScopeKey);

        $expectedCounts = [
            'objects' => $expectedObjects,
            'terms_per_object' => $relationshipsPerObject,
            'relationships' => $expectedRelationships,
            'first_object_rows' => $relationshipsPerObject,
            'last_object_rows' => $relationshipsPerObject,
        ];
        $expectedIndexes = [
            'PRIMARY' => ['object_id', 'term_taxonomy_id'],
            'term_taxonomy_id' => ['term_taxonomy_id'],
            'wp_fts_term_object' => ['term_taxonomy_id', 'object_id'],
        ];
        $fixtureIndexColumns = array_map(
            static fn(array $index): array => array_values(is_array($index['columns'] ?? null) ? $index['columns'] : []),
            $fixtureIndexes
        );
        $searchLatency = max(
            (float) ($noScope['duration_ms'] ?? PHP_INT_MAX),
            (float) ($noScope['server_duration_ms'] ?? PHP_INT_MAX),
            (float) ($activeScope['duration_ms'] ?? PHP_INT_MAX),
            (float) ($activeScope['server_duration_ms'] ?? PHP_INT_MAX),
            (float) ($raceScope['duration_ms'] ?? PHP_INT_MAX),
            (float) ($raceScope['server_duration_ms'] ?? PHP_INT_MAX)
        );
        $engineFamily = wp_fts_wc_engine_family();
        $prefixLatencyLimits = wp_fts_wc_case_latency_limits('prefix_fanout', $manifest['profile'], $engineFamily);
        $searchLatencyLimit = max(2000.0, $prefixLatencyLimits['p99']);
        $gates = [
            wp_fts_wc_gate('dense_relationship_fixture_cardinality', $expectedCounts, $fixtureCounts, $fixtureCounts === $expectedCounts),
            wp_fts_wc_gate('dense_relationship_fixture_index_shape', $expectedIndexes, $fixtureIndexColumns, $fixtureIndexColumns === $expectedIndexes),
            wp_fts_wc_gate('dense_relationship_fixture_engine', 'MYISAM negative-access fixture only', strtoupper((string) ($fixtureStorage['engine'] ?? '')), strtoupper((string) ($fixtureStorage['engine'] ?? '')) === 'MYISAM'),
            wp_fts_wc_gate('dense_relationship_fixture_server_side_seed', ['relationship_insert_statements' => 1, 'rows' => $expectedRelationships], ['relationship_insert_statements' => 1, 'rows' => $insertedRelationships, 'object_sequence_statements' => $objectSeedStatements, 'term_sequence_statements' => $termSeedStatements], $insertedRelationships === $expectedRelationships),
            wp_fts_wc_gate('dense_relationship_fixture_seed_duration_ms', '<= 900000', $seedDuration, $seedDuration <= 900000.0),
            wp_fts_wc_gate('dense_relationship_fixture_php_memory_delta', '<= 16777216', max(0, memory_get_usage(true) - $memoryBefore), max(0, memory_get_usage(true) - $memoryBefore) <= 16777216),
            wp_fts_wc_gate('dense_relationship_no_scope_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 0], $noScope['statement_shape'] ?? null, ($noScope['statement_shape'] ?? null) === ['plan' => 1, 'rank' => 1, 'hydrate' => 0]),
            wp_fts_wc_gate('dense_relationship_no_scope_result', 20, count($noScope['result_ids'] ?? []), ($noScope['typed_unavailable'] ?? true) === false && count($noScope['result_ids'] ?? []) === 20),
            wp_fts_wc_gate('dense_relationship_no_scope_zero_sql_or_plan_access', 0, [(int) ($noScope['relationship_sql_references'] ?? -1), (int) ($noScope['relationship_plan_references'] ?? -1)], (int) ($noScope['relationship_sql_references'] ?? -1) === 0 && (int) ($noScope['relationship_plan_references'] ?? -1) === 0),
            wp_fts_wc_gate('dense_relationship_no_scope_relation_allowlists', true, $noScope['relation_allowlists_valid'] ?? false, ($noScope['relation_allowlists_valid'] ?? false) === true),
            wp_fts_wc_gate('dense_relationship_no_scope_server_attribution', $noScope['sql_sha256'] ?? null, $noScope['performance_schema_sql_sha256'] ?? null, ($noScope['server_attributed'] ?? false) === true),
            wp_fts_wc_gate('dense_relationship_active_targeted_scope_fixture', 1, $activeScopeRows, $activeScopeRows === 1),
            wp_fts_wc_gate('dense_relationship_active_targeted_plan_only', ['plan' => 1, 'rank' => 0, 'hydrate' => 0], $activeScope['statement_shape'] ?? null, ($activeScope['statement_shape'] ?? null) === ['plan' => 1, 'rank' => 0, 'hydrate' => 0]),
            wp_fts_wc_gate('dense_relationship_active_targeted_typed_unavailable', true, $activeScope['outcome'] ?? null, ($activeScope['typed_unavailable'] ?? false) === true && ($activeScope['result_ids'] ?? null) === []),
            wp_fts_wc_gate('dense_relationship_active_targeted_zero_relationship_sql', 0, (int) ($activeScope['relationship_sql_references'] ?? -1), (int) ($activeScope['relationship_sql_references'] ?? -1) === 0),
            wp_fts_wc_gate('dense_relationship_active_targeted_server_attribution', $activeScope['sql_sha256'] ?? null, $activeScope['performance_schema_sql_sha256'] ?? null, ($activeScope['server_attributed'] ?? false) === true),
            wp_fts_wc_gate('dense_relationship_active_targeted_broad_prefix_rows_examined', '<= 256', $activeScope['statement_metrics']['plan']['rows_examined'] ?? null, (int) ($activeScope['statement_metrics']['plan']['rows_examined'] ?? PHP_INT_MAX) <= 256),
            wp_fts_wc_gate('dense_relationship_plan_rank_scope_race_fixture', ['inserted' => 1, 'rows' => 1], ['inserted' => $raceInsertAffected, 'rows' => $raceScopeRows], $raceInsertAffected === 1 && $raceScopeRows === 1 && ($raceScope['before_rank_injected'] ?? false) === true),
            wp_fts_wc_gate('dense_relationship_plan_rank_scope_race_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 0], $raceScope['statement_shape'] ?? null, ($raceScope['statement_shape'] ?? null) === ['plan' => 1, 'rank' => 1, 'hydrate' => 0]),
            wp_fts_wc_gate('dense_relationship_plan_rank_scope_race_typed_unavailable', true, $raceScope['outcome'] ?? null, ($raceScope['typed_unavailable'] ?? false) === true && ($raceScope['result_ids'] ?? null) === []),
            wp_fts_wc_gate('dense_relationship_plan_rank_scope_race_zero_relationship_sql', 0, (int) ($raceScope['relationship_sql_references'] ?? -1), (int) ($raceScope['relationship_sql_references'] ?? -1) === 0),
            wp_fts_wc_gate('dense_relationship_rank_control_revocation_returns_control_row', ['rows_examined' => '<= 256', 'rows_sent' => 1], $raceScope['statement_metrics']['rank'] ?? null, (int) ($raceScope['statement_metrics']['rank']['rows_examined'] ?? PHP_INT_MAX) <= 256 && (int) ($raceScope['statement_metrics']['rank']['rows_sent'] ?? PHP_INT_MAX) === 1),
            wp_fts_wc_gate('dense_relationship_plan_rank_scope_race_server_attribution', $raceScope['sql_sha256'] ?? null, $raceScope['performance_schema_sql_sha256'] ?? null, ($raceScope['server_attributed'] ?? false) === true),
            wp_fts_wc_gate('dense_relationship_search_duration_ms', "<= {$searchLatencyLimit}; two-second floor or {$engineFamily} prefix p99", $searchLatency, $searchLatency <= $searchLatencyLimit),
        ];
        $result = [
            'schema' => 'relational-fts-dense-relationship-zero-access-v1',
            'fixture' => [
                'engine_scope' => 'MyISAM canonical indexed shape used only for a zero-access negative proof; production DDL/concurrency is measured separately on InnoDB.',
                'counts' => $fixtureCounts,
                'indexes' => $fixtureIndexes,
                'storage' => $fixtureStorage,
                'seed_duration_ms' => $seedDuration,
                'relationship_insert_statements' => 1,
                'object_sequence_statements' => $objectSeedStatements,
                'term_sequence_statements' => $termSeedStatements,
            ],
            'no_scope' => $noScope,
            'active_targeted_scope' => $activeScope,
            'plan_rank_scope_race' => $raceScope,
            'gates' => $gates,
        ];
    } finally {
        $deleteScope($activeScopeKey);
        $deleteScope($raceScopeKey);
        $wpdb->term_relationships = $originalRelationships;
        WP_FTS_Plugin::reset_request_caches();
        $dropFixture();
        $remainingTables = wp_fts_wc_checked_count($wpdb->prepare(
            'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN (%s,%s,%s)',
            $relationships,
            $objects,
            $terms
        ), 'dense relationship fixture cleanup');
    }
    $result['gates'][] = wp_fts_wc_gate('dense_relationship_fixture_cleanup', 0, $remainingTables, $remainingTables === 0);

    return $result;
}

/**
 * Execute the exact production visibility fragment with a 100,000-row stale
 * post backlog and an active targeted taxonomy fence. The harness supplies
 * only a twenty-row candidate driver; every visibility join and predicate is
 * obtained through the production private method.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_visibility_index_probe(array $manifest, string $work): array
{
    global $wpdb;

    $backlogCount = 100000;
    $backlogStart = 3000000000;
    $backlogEnd = $backlogStart + $backlogCount - 1;
    $remainingBacklog = PHP_INT_MAX;
    $seedStatements = 0;
    $seedStarted = hrtime(true);
    $cleanup = static function () use ($wpdb, $work, $backlogStart, $backlogEnd): int {
        $deleted = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$work}` WHERE kind='post' AND post_id BETWEEN %d AND %d",
            $backlogStart,
            $backlogEnd
        ));
        wp_fts_wc_assert(is_int($deleted), 'Could not clean the visibility-index dirty backlog.');

        return wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id BETWEEN %d AND %d",
            $backlogStart,
            $backlogEnd
        ), 'visibility-index dirty backlog cleanup');
    };
    $cleanup();
    try {
        $batchSize = 5000;
        for ($offset = 0; $offset < $backlogCount; $offset += $batchSize) {
            $count = min($batchSize, $backlogCount - $offset);
            $values = [];
            $args = [];
            for ($row = 0; $row < $count; $row++) {
                $postId = $backlogStart + $offset + $row;
                $values[] = '(%s,\'post\',%d,1,\'pending\',1)';
                array_push($args, 'wc-visibility-dirty-' . $postId, $postId);
            }
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO `{$work}` (job_key,kind,post_id,generation,state,available_at) VALUES " . implode(',', $values),
                ...$args
            ));
            wp_fts_wc_assert($inserted === $count, 'Could not populate the complete visibility-index dirty backlog.');
            $seedStatements++;
        }
        $seedDuration = wp_fts_wc_elapsed_ms($seedStarted);
        $backlogRows = wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id BETWEEN %d AND %d",
            $backlogStart,
            $backlogEnd
        ), 'visibility-index dirty backlog');

        $storage = wp_fts_wc_storage_fixture(false);
        wp_fts_wc_assert($storage instanceof WP_FTS_Relational_Storage, 'Visibility-index proof requires the relational storage backend.');
        $readVisibility = Closure::bind(
            function (string $postIdExpression, string $suffix, array $options): array {
                return $this->visibility_sql($postIdExpression, $suffix, $options);
            },
            $storage,
            WP_FTS_Relational_Storage::class
        );
        wp_fts_wc_assert($readVisibility instanceof Closure, 'Could not bind the production visibility SQL builder.');
        $visibility = $readVisibility('candidate.ID', 'wc_visibility', [
            'post_statuses' => ['publish'],
            'post_types' => ['post'],
        ]);
        $candidateStart = max((int) $manifest['first_post_id'], (int) $manifest['last_post_id'] - 19);
        $candidateEnd = (int) $manifest['last_post_id'];
        $sql = "/* wp_fts:visibility-index-probe */
SELECT candidate.ID
FROM {$wpdb->posts} candidate
{$visibility['joins']}
WHERE candidate.ID BETWEEN %d AND %d
  AND {$visibility['where']}
LIMIT 20";
        $sql = $wpdb->prepare($sql, $candidateStart, $candidateEnd, ...$visibility['args']);
        wp_fts_wc_assert(is_string($sql) && $sql !== '', 'Could not prepare the production visibility-index probe.');

        $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID()');
        wp_fts_wc_assert($threadId > 0, 'Could not map the visibility-index probe to Performance Schema.');
        $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
            'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
            $threadId
        ));
        $started = hrtime(true);
        $rows = $wpdb->get_col($sql) ?: [];
        $duration = wp_fts_wc_elapsed_ms($started);
        wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Production visibility-index SQL was rejected by the database engine.');
        $events = $wpdb->get_results($wpdb->prepare(
            "SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d AND SQL_TEXT LIKE '%%wp_fts:visibility-index-probe%%' ORDER BY EVENT_ID",
            $threadId,
            $beforeEvent
        ), ARRAY_A) ?: [];
        $event = count($events) === 1 ? $events[0] : [];
        $explainText = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
        $explain = is_string($explainText) && $explainText !== ''
            ? json_decode($explainText, true, 512, JSON_THROW_ON_ERROR)
            : null;
        $tabular = $wpdb->get_results('EXPLAIN ' . $sql, ARRAY_A) ?: [];
        $access = [];
        if (is_array($explain)) {
            wp_fts_wc_collect_database_table_access($explain, $access);
        }
        $accessByAlias = [];
        foreach ($access as $row) {
            $alias = strtolower((string) ($row['table_name'] ?? ''));
            if (in_array($alias, ['d_wc_visibility', 'wp_wc_visibility', 'dirty_wc_visibility'], true)) {
                $accessByAlias[$alias][] = $row;
            }
        }
        $expectedKeys = [
            'd_wc_visibility' => 'document_presence',
            'wp_wc_visibility' => WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME,
            'dirty_wc_visibility' => 'dirty',
        ];
        $accessAliases = array_keys($accessByAlias);
        $expectedAliases = array_keys($expectedKeys);
        sort($accessAliases, SORT_STRING);
        sort($expectedAliases, SORT_STRING);
        $keyed = $accessAliases === $expectedAliases;
        $perCandidateRows = true;
        foreach ($expectedKeys as $alias => $key) {
            $aliasRows = $accessByAlias[$alias] ?? [];
            $keyed = $keyed
                && $aliasRows !== []
                && count(array_filter($aliasRows, static fn(array $row): bool => strcasecmp((string) ($row['key'] ?? ''), $key) !== 0 || strtoupper((string) ($row['access_type'] ?? '')) === 'ALL')) === 0;
            $perCandidateRows = $perCandidateRows
                && count(array_filter($aliasRows, static fn(array $row): bool => !is_int($row['rows'] ?? null) || (int) $row['rows'] > 20)) === 0;
        }
        $extra = strtolower(implode(' | ', array_map(static fn(array $row): string => (string) ($row['Extra'] ?? ''), $tabular)));
        $shape = str_contains($sql, ' d_wc_visibility FORCE INDEX (document_presence) ON ')
            && str_contains($sql, ' wp_wc_visibility FORCE INDEX (' . WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME . ') ON ')
            && str_contains($sql, 'LEFT JOIN ' . $work . ' dirty_wc_visibility FORCE INDEX (dirty)')
            && !str_contains($sql, (string) $wpdb->term_relationships)
            && !str_contains($sql, 'scope_rel_wc_visibility')
            && !str_contains($sql, 'term_scope_wc_visibility');
        $serverDuration = max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0);
        $expectedCandidateIds = range($candidateStart, $candidateEnd);
        $gates = [
            wp_fts_wc_gate('visibility_index_dirty_backlog_rows', $backlogCount, $backlogRows, $backlogRows === $backlogCount),
            wp_fts_wc_gate('visibility_index_production_sql_shape', ['document_presence', WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME, 'dirty', 'no relationship or scope anti-join'], hash('sha256', $sql), $shape),
            wp_fts_wc_gate('visibility_index_result_visible_without_scope_anti_join', $expectedCandidateIds, array_map('intval', $rows), array_map('intval', $rows) === $expectedCandidateIds),
            wp_fts_wc_gate('visibility_index_statement_count', 1, count($events), count($events) === 1),
            wp_fts_wc_gate('visibility_index_explain_keyed_per_candidate', $expectedKeys, $accessByAlias, $keyed && $perCandidateRows),
            wp_fts_wc_gate('visibility_index_explain_no_temp_filesort', 0, $extra, !str_contains($extra, 'temporary') && !str_contains($extra, 'filesort')),
            wp_fts_wc_gate('visibility_index_rows_examined', '<= 200', (int) ($event['ROWS_EXAMINED'] ?? PHP_INT_MAX), count($events) === 1 && (int) ($event['ROWS_EXAMINED'] ?? PHP_INT_MAX) <= 200),
            wp_fts_wc_gate('visibility_index_rows_sent', 20, (int) ($event['ROWS_SENT'] ?? -1), count($events) === 1 && (int) ($event['ROWS_SENT'] ?? -1) === 20),
            wp_fts_wc_gate('visibility_index_no_disk_or_index_flags', 0, [(int) ($event['CREATED_TMP_DISK_TABLES'] ?? -1), (int) ($event['SORT_MERGE_PASSES'] ?? -1), (int) ($event['NO_INDEX_USED'] ?? -1), (int) ($event['NO_GOOD_INDEX_USED'] ?? -1)], count($events) === 1 && (int) ($event['CREATED_TMP_DISK_TABLES'] ?? -1) === 0 && (int) ($event['SORT_MERGE_PASSES'] ?? -1) === 0 && (int) ($event['NO_INDEX_USED'] ?? -1) === 0 && (int) ($event['NO_GOOD_INDEX_USED'] ?? -1) === 0),
            wp_fts_wc_gate('visibility_index_duration_ms', '<= 500', [$duration, $serverDuration], count($events) === 1 && $duration <= 500.0 && $serverDuration <= 500.0),
        ];
        $result = [
            'schema' => 'relational-fts-visibility-index-v1',
            'fixture' => ['backlog_rows' => $backlogRows, 'seed_statements' => $seedStatements, 'seed_duration_ms' => $seedDuration],
            'sql' => $sql,
            'sql_sha256' => hash('sha256', $sql),
            'result_ids' => array_map('intval', $rows),
            'duration_ms' => $duration,
            'performance_schema_events' => $events,
            'explain' => ['json' => $explain, 'tabular' => $tabular, 'visibility_access' => $accessByAlias],
            'gates' => $gates,
        ];
    } finally {
        $remainingBacklog = $cleanup();
    }
    $result['gates'][] = wp_fts_wc_gate('visibility_index_fixture_cleanup', 0, $remainingBacklog, $remainingBacklog === 0);
    $result['fixture']['remaining_rows_after_cleanup'] = $remainingBacklog;
    $result['status'] = wp_fts_wc_gates_pass($result['gates']) ? 'PASS' : 'FAIL';
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Visibility-index proof failed: ' . implode(', ', wp_fts_wc_gate_failures($result['gates'])));
    }

    return $result;
}

/**
 * Exercise every production scope-page shape across a 100,000-row gap.
 *
 * Dedicated MyISAM tables make the single-column taxonomy secondary key genuinely
 * non-covering. Production must use its explicit term/object and
 * type/status/ID composites, so targeted work is proportional only to affected
 * membership and filtered work only to at most 32 selected lanes. Corpus work
 * alone advances through bounded raw post/document PRIMARY pages.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_targeted_scope_expansion_proof(): array
{
    global $wpdb;

    $posts = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_scope_posts');
    $relationships = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_scope_relationships');
    $documents = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_documents');
    $originalPosts = (string) ($wpdb->posts ?? ((string) $wpdb->prefix . 'posts'));
    $originalRelationships = (string) ($wpdb->term_relationships ?? ((string) $wpdb->prefix . 'term_relationships'));
    $gapCount = 100000;
    $sameTargetBacklogCount = 100000;
    $denseTargetCount = 100000;
    $pageLimit = 100;
    $targetTaxonomyId = 2000000001;
    $unrelatedTaxonomyId = 2000000000;
    $maxDocumentId = (int) $wpdb->get_var("SELECT COALESCE(MAX(post_id),0) FROM `{$documents}`");
    $cursor = max(1000000000, $maxDocumentId + $gapCount + 1);
    $targetPostId = $cursor + $gapCount + 1;
    $targetPostIds = range($targetPostId, $targetPostId + $denseTargetCount - 1);
    $denseFilteredStart = $targetPostId + $denseTargetCount + 1;
    $configuredTypes = Closure::bind(
        static fn(): array => WP_FTS_Plugin::configured_backfill_post_types(),
        null,
        WP_FTS_Plugin::class
    );
    wp_fts_wc_assert($configuredTypes instanceof Closure, 'Could not bind the configured scope post-type reader.');
    $eligibleTypes = $configuredTypes();
    wp_fts_wc_assert(is_array($eligibleTypes) && $eligibleTypes !== [], 'The scope proof requires one configured searchable post type.');
    $eligibleType = (string) reset($eligibleTypes);
    $realScopeIndexes = [
        'targeted' => wp_fts_wc_scope_index_columns($originalRelationships, WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME),
        'filtered' => wp_fts_wc_scope_index_columns($originalPosts, WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME),
        'visibility' => wp_fts_wc_scope_index_columns($originalPosts, WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME),
    ];
    $ownershipRows = wp_fts_wc_cold_option_rows([WP_FTS_Plugin::SCOPE_INDEX_OWNERSHIP_OPTION]);
    $ownershipKeys = get_option(WP_FTS_Plugin::SCOPE_INDEX_OWNERSHIP_OPTION, []);
    $ownershipKeys = is_array($ownershipKeys) ? array_values(array_filter($ownershipKeys, 'is_string')) : [];
    sort($ownershipKeys, SORT_STRING);
    $dropFixture = static function () use ($wpdb, $posts, $relationships): void {
        foreach ([$relationships, $posts] as $table) {
            wp_fts_wc_assert(
                $wpdb->query("DROP TABLE IF EXISTS `{$table}`") !== false,
                "Could not drop scope-expansion fixture table {$table}."
            );
        }
    };

    $dropFixture();
    $result = [];
    try {
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$posts}` (
                ID bigint(20) unsigned NOT NULL,
                post_status varchar(20) NOT NULL,
                post_type varchar(20) NOT NULL,
                post_password varchar(255) NOT NULL DEFAULT '',
                PRIMARY KEY (ID),
                KEY wp_fts_type_status_id (post_type,post_status,ID)
            ) ENGINE=MyISAM"
        ) !== false, 'Could not create the MyISAM scope posts fixture.');
        wp_fts_wc_assert($wpdb->query(
            "CREATE TABLE `{$relationships}` (
                object_id bigint(20) unsigned NOT NULL,
                term_taxonomy_id bigint(20) unsigned NOT NULL,
                term_order int(11) NOT NULL DEFAULT 0,
                PRIMARY KEY (object_id,term_taxonomy_id),
                KEY term_taxonomy_id (term_taxonomy_id),
                KEY wp_fts_term_object (term_taxonomy_id,object_id)
            ) ENGINE=MyISAM"
        ) !== false, 'Could not create the non-covering MyISAM relationship fixture.');

        $seedStarted = hrtime(true);
        $postSeedStatements = wp_fts_wc_seed_scope_posts(
            $posts,
            $cursor,
            $gapCount,
            $targetPostId,
            $eligibleType
        );
        $relationshipSeedStatements = wp_fts_wc_seed_scope_relationships(
            $relationships,
            $cursor,
            $gapCount,
            $targetPostId,
            $sameTargetBacklogCount,
            $denseTargetCount,
            $targetTaxonomyId,
            $unrelatedTaxonomyId
        );
        wp_fts_wc_assert($wpdb->query("ANALYZE TABLE `{$posts}`, `{$relationships}`") !== false, 'Could not analyze the scope-expansion fixture.');
        $seedDuration = wp_fts_wc_elapsed_ms($seedStarted);

        WP_FTS_Plugin::reset_request_caches();
        $takeoverBeforeRepair = wp_fts_wc_scope_takeover_signature(WP_FTS_Plugin::search_takeover_status(false));
        $indexRepair = wp_fts_wc_populated_scope_index_repair($takeoverBeforeRepair);

        $engines = $wpdb->get_results($wpdb->prepare(
            'SELECT table_name,engine FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN (%s,%s) ORDER BY table_name',
            $posts,
            $relationships
        ), ARRAY_A) ?: [];
        $engineMap = [];
        foreach ($engines as $row) {
            // MySQL returns information_schema column labels in uppercase even
            // when the SELECT spells them in lowercase; MariaDB preserves them.
            $row = array_change_key_case($row, CASE_LOWER);
            $engineMap[(string) ($row['table_name'] ?? '')] = strtoupper((string) ($row['engine'] ?? ''));
        }
        $fixtureIndexes = [
            'targeted' => wp_fts_wc_scope_index_columns($relationships, WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME),
            'filtered' => wp_fts_wc_scope_index_columns($posts, WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME),
            'single_column_taxonomy' => wp_fts_wc_scope_index_columns($relationships, 'term_taxonomy_id'),
        ];

        $fixtureCounts = [
            'posts' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$posts}`", 'scope-expansion raw posts'),
            'ineligible_posts' => wp_fts_wc_checked_count($wpdb->prepare(
                "SELECT COUNT(*) FROM `{$posts}` WHERE ID>%d AND ID<%d AND NOT (post_status='publish' AND post_type=%s)",
                $cursor,
                $targetPostId,
                $eligibleType
            ), 'scope-expansion ineligible post gap'),
            'same_target_backlog' => wp_fts_wc_checked_count($wpdb->prepare(
                "SELECT COUNT(*) FROM `{$relationships}` WHERE term_taxonomy_id=%d AND object_id<%d",
                $targetTaxonomyId,
                $cursor
            ), 'scope-expansion same-target backlog'),
            'unrelated_gap' => wp_fts_wc_checked_count($wpdb->prepare(
                "SELECT COUNT(*) FROM `{$relationships}` WHERE term_taxonomy_id=%d AND object_id>%d AND object_id<%d",
                $unrelatedTaxonomyId,
                $cursor,
                $targetPostId
            ), 'scope-expansion unrelated relationship gap'),
            'target_rows' => wp_fts_wc_checked_count($wpdb->prepare(
                "SELECT COUNT(*) FROM `{$relationships}` WHERE term_taxonomy_id=%d",
                $targetTaxonomyId
            ), 'scope-expansion complete target relationships'),
        ];

        $invokeProductionPage = Closure::bind(
            static fn(
                int $after,
                int $limit,
                string $coverage,
                string $subjectType,
                int $subjectId,
                array $payload
            ): array => WP_FTS_Plugin::scope_candidate_post_ids_after(
                $after,
                $limit,
                $coverage,
                $subjectType,
                $subjectId,
                $payload
            ),
            null,
            WP_FTS_Plugin::class
        );
        wp_fts_wc_assert($invokeProductionPage instanceof Closure, 'Could not bind the production scope-page workflow.');

        $wpdb->posts = $posts;
        $wpdb->term_relationships = $relationships;
        $targeted = wp_fts_wc_measure_scope_gap(
            'targeted_scope_expansion',
            'wp_fts:targeted-scope-page',
            static fn(int $after, int $limit): array => $invokeProductionPage(
                $after,
                $limit,
                WP_FTS_Index_Queue::SCOPE_COVERAGE_TARGETED,
                'term_taxonomy',
                $targetTaxonomyId,
                []
            ),
            $cursor,
            $targetPostIds,
            intdiv($denseTargetCount, $pageLimit) + 1,
            0,
            $denseTargetCount,
            null,
            $pageLimit,
            100,
            0,
            0,
            2048
        );
        $filtered = wp_fts_wc_measure_scope_gap(
            'filtered_scope_expansion',
            'wp_fts:filtered-scope-page',
            static fn(int $after, int $limit): array => $invokeProductionPage(
                $after,
                $limit,
                WP_FTS_Index_Queue::SCOPE_COVERAGE_FILTERED,
                '',
                0,
                ['post_status' => ['publish'], 'post_type' => [$eligibleType]]
            ),
            $cursor,
            [$targetPostId],
            2,
            0,
            1,
            null,
            $pageLimit,
            300,
            100,
            100,
            4096
        );
        $corpus = wp_fts_wc_measure_scope_gap(
            'corpus_scope_expansion',
            'wp_fts:corpus-scope-page',
            static fn(int $after, int $limit): array => $invokeProductionPage(
                $after,
                $limit,
                WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
                '',
                0,
                []
            ),
            $cursor,
            [$targetPostId],
            intdiv($gapCount, $pageLimit) + 2,
            intdiv($gapCount, $pageLimit),
            $gapCount + 1,
            $pageLimit,
            $pageLimit,
            // MariaDB counts both source keysets, both inner derived scans,
            // the grouped 200-row relation, and the final 100-row output.
            900,
            200,
            200,
            2048
        );

        $denseFiltered = wp_fts_wc_seed_filtered_scope_lanes($posts, $denseFilteredStart);
        wp_fts_wc_assert($wpdb->query("ANALYZE TABLE `{$posts}`") !== false, 'Could not analyze the dense filtered-scope lanes.');
        $filteredMax = wp_fts_wc_measure_scope_gap(
            'filtered_scope_max_lanes',
            'wp_fts:filtered-scope-page',
            static fn(int $after, int $limit): array => $invokeProductionPage(
                $after,
                $limit,
                WP_FTS_Index_Queue::SCOPE_COVERAGE_FILTERED,
                '',
                0,
                ['post_status' => $denseFiltered['post_statuses'], 'post_type' => $denseFiltered['post_types']]
            ),
            $denseFilteredStart - 1,
            $denseFiltered['post_ids'],
            33,
            0,
            3200,
            null,
            $pageLimit,
            // MariaDB counts all 3,200 lane rows in the source, UNION, and
            // grouping passes, then counts the final 100-row output.
            9700,
            3200,
            3200,
            32768
        );
        $overflowTypes = array_map(static fn(int $number): string => 'overflow_type_' . $number, range(1, 11));
        $overflowStatuses = array_map(static fn(int $number): string => 'overflow_status_' . $number, range(1, 3));
        $overflow = wp_fts_wc_record_queries(static function () use (
            $invokeProductionPage,
            $cursor,
            $pageLimit,
            $overflowTypes,
            $overflowStatuses
        ): array {
            try {
                $invokeProductionPage(
                    $cursor,
                    $pageLimit,
                    WP_FTS_Index_Queue::SCOPE_COVERAGE_FILTERED,
                    '',
                    0,
                    ['post_status' => $overflowStatuses, 'post_type' => $overflowTypes]
                );
            } catch (Throwable $error) {
                return ['class' => get_class($error), 'message' => $error->getMessage()];
            }

            return ['class' => null, 'message' => null];
        });
        $overflowResult = is_array($overflow['result']) ? $overflow['result'] : [];
        $overflowRejected = ($overflowResult['class'] ?? null) === RuntimeException::class
            && str_contains((string) ($overflowResult['message'] ?? ''), '32-lane query contract');

        $ownershipRow = $ownershipRows[WP_FTS_Plugin::SCOPE_INDEX_OWNERSHIP_OPTION] ?? null;
        $ownershipAutoload = is_array($ownershipRow) ? (string) ($ownershipRow['autoload'] ?? '') : '';
        $autoloadValues = function_exists('wp_autoload_values_to_autoload')
            ? array_map('strval', wp_autoload_values_to_autoload())
            : ['yes'];
        $gates = [
            wp_fts_wc_gate('scope_expansion_real_keyset_indexes', ['targeted' => ['term_taxonomy_id', 'object_id'], 'filtered' => ['post_type', 'post_status', 'ID'], 'visibility' => ['ID', 'post_type', 'post_status', 'post_password', 'post_date_gmt']], $realScopeIndexes, ($realScopeIndexes['targeted']['columns'] ?? null) === ['term_taxonomy_id', 'object_id'] && ($realScopeIndexes['targeted']['unique'] ?? null) === false && ($realScopeIndexes['filtered']['columns'] ?? null) === ['post_type', 'post_status', 'ID'] && ($realScopeIndexes['filtered']['unique'] ?? null) === false && ($realScopeIndexes['visibility']['columns'] ?? null) === ['ID', 'post_type', 'post_status', 'post_password', 'post_date_gmt'] && ($realScopeIndexes['visibility']['unique'] ?? null) === false),
            wp_fts_wc_gate('scope_expansion_index_ownership', ['keys' => ['filtered', 'targeted', 'visibility'], 'autoload' => 'nonautoload'], ['keys' => $ownershipKeys, 'autoload' => $ownershipAutoload], $ownershipKeys === ['filtered', 'targeted', 'visibility'] && $ownershipRow !== null && !in_array($ownershipAutoload, $autoloadValues, true)),
            wp_fts_wc_gate('scope_expansion_myisam_fixture_engine', ['MyISAM', 'MyISAM'], array_values($engineMap), count($engineMap) === 2 && count(array_filter($engineMap, static fn(string $engine): bool => $engine !== 'MYISAM')) === 0),
            wp_fts_wc_gate('scope_expansion_fixture_composite_indexes', ['targeted' => ['term_taxonomy_id', 'object_id'], 'filtered' => ['post_type', 'post_status', 'ID']], $fixtureIndexes, ($fixtureIndexes['targeted']['columns'] ?? null) === ['term_taxonomy_id', 'object_id'] && ($fixtureIndexes['targeted']['unique'] ?? null) === false && ($fixtureIndexes['filtered']['columns'] ?? null) === ['post_type', 'post_status', 'ID'] && ($fixtureIndexes['filtered']['unique'] ?? null) === false),
            wp_fts_wc_gate('scope_expansion_noncovering_decoy_index', ['term_taxonomy_id'], $fixtureIndexes['single_column_taxonomy'] ?? null, ($fixtureIndexes['single_column_taxonomy']['columns'] ?? null) === ['term_taxonomy_id']),
            wp_fts_wc_gate('scope_expansion_sparse_gap_rows', $gapCount + 1, [$fixtureCounts['posts'], $fixtureCounts['ineligible_posts']], $fixtureCounts['posts'] === $gapCount + 1 && $fixtureCounts['ineligible_posts'] === $gapCount),
            wp_fts_wc_gate('scope_expansion_unrelated_relationships', $gapCount, $fixtureCounts['unrelated_gap'], $fixtureCounts['unrelated_gap'] === $gapCount),
            wp_fts_wc_gate('scope_expansion_same_target_backlog', [$sameTargetBacklogCount, $denseTargetCount], [$fixtureCounts['same_target_backlog'], $fixtureCounts['target_rows']], $fixtureCounts['same_target_backlog'] === $sameTargetBacklogCount && $fixtureCounts['target_rows'] === $sameTargetBacklogCount + $denseTargetCount + 1),
            ...$indexRepair['gates'],
            ...$targeted['gates'],
            ...$filtered['gates'],
            ...$corpus['gates'],
            ...$filteredMax['gates'],
            wp_fts_wc_gate('filtered_scope_lane_overflow_rejected', '33 lanes rejected before SQL', $overflowResult, $overflowRejected),
            wp_fts_wc_gate('filtered_scope_lane_overflow_zero_sql', 0, count($overflow['queries']), $overflow['queries'] === []),
        ];
        $result = [
            'schema' => 'relational-fts-scope-expansion-v4',
            'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
            'fixture' => [
                'posts_table' => $posts,
                'relationships_table' => $relationships,
                'engines' => $engineMap,
                'real_scope_indexes' => $realScopeIndexes,
                'scope_index_ownership' => ['keys' => $ownershipKeys, 'autoload' => $ownershipAutoload],
                'fixture_indexes' => $fixtureIndexes,
                'counts' => $fixtureCounts,
                'cursor' => $cursor,
                'target_post_id' => $targetPostId,
                'page_limit' => $pageLimit,
                'gap_rows' => $gapCount,
                'dense_target_rows' => $denseTargetCount,
                'dense_filtered_rows' => count($denseFiltered['post_ids']),
                'eligible_post_type' => $eligibleType,
                'initial_seed_statements' => $postSeedStatements + $relationshipSeedStatements,
                'dense_filtered_seed_statements' => $denseFiltered['statements'],
                'initial_seed_duration_ms' => $seedDuration,
                'populated_scope_index_repair' => $indexRepair['evidence'],
            ],
            'targeted' => $targeted['evidence'],
            'filtered' => $filtered['evidence'],
            'corpus' => $corpus['evidence'],
            'filtered_max_lanes' => $filteredMax['evidence'],
            'filtered_lane_overflow' => ['result' => $overflowResult, 'query_count' => count($overflow['queries'])],
            'gates' => $gates,
        ];
    } finally {
        $wpdb->posts = $originalPosts;
        $wpdb->term_relationships = $originalRelationships;
        $dropFixture();
    }

    $remainingTables = wp_fts_wc_checked_count($wpdb->prepare(
        'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN (%s,%s)',
        $posts,
        $relationships
    ), 'scope-expansion fixture cleanup');
    $result['gates'][] = wp_fts_wc_gate('scope_expansion_fixture_cleanup', 0, $remainingTables, $remainingTables === 0);
    $result['fixture']['remaining_tables_after_cleanup'] = $remainingTables;
    $result['status'] = wp_fts_wc_gates_pass($result['gates']) ? 'PASS' : 'FAIL';
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/targeted-scope-expansion.json', $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Bounded scope-expansion proof failed: ' . implode(', ', wp_fts_wc_gate_failures($result['gates'])));
    }

    return $result;
}

/** Build the raw-post ID gap that exposes any offset or unindexed scope scan. */
function wp_fts_wc_seed_scope_posts(
    string $table,
    int $cursor,
    int $gapCount,
    int $targetPostId,
    string $eligibleType
): int {
    global $wpdb;

    $statements = 0;
    $batchSize = 5000;
    for ($offset = 0; $offset < $gapCount; $offset += $batchSize) {
        $count = min($batchSize, $gapCount - $offset);
        $values = [];
        $args = [];
        for ($row = 0; $row < $count; $row++) {
            $values[] = '(%d,%s,%s,%s)';
            array_push($args, $cursor + $offset + $row + 1, 'draft', 'wp_fts_wc_ineligible', '');
        }
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO `{$table}` (ID,post_status,post_type,post_password) VALUES " . implode(',', $values),
            ...$args
        ));
        wp_fts_wc_assert($inserted === $count, 'Could not seed the complete raw-post scope gap.');
        $statements++;
    }
    $inserted = $wpdb->query($wpdb->prepare(
        "INSERT INTO `{$table}` (ID,post_status,post_type,post_password) VALUES (%d,%s,%s,%s)",
        $targetPostId,
        'publish',
        $eligibleType,
        ''
    ));
    wp_fts_wc_assert($inserted === 1, 'Could not seed the eligible post after the raw scope gap.');

    return $statements + 1;
}

/** Build dense target and decoy relationship frontiers with bounded inserts. */
function wp_fts_wc_seed_scope_relationships(
    string $table,
    int $cursor,
    int $gapCount,
    int $targetPostId,
    int $sameTargetBacklogCount,
    int $denseTargetCount,
    int $targetTaxonomyId,
    int $unrelatedTaxonomyId
): int {
    global $wpdb;

    $statements = 0;
    $batchSize = 5000;
    foreach ([
        ['rows' => $sameTargetBacklogCount, 'object_start' => 1, 'taxonomy_id' => $targetTaxonomyId],
        ['rows' => $gapCount, 'object_start' => $cursor + 1, 'taxonomy_id' => $unrelatedTaxonomyId],
        ['rows' => $denseTargetCount, 'object_start' => $targetPostId, 'taxonomy_id' => $targetTaxonomyId],
    ] as $fixture) {
        for ($offset = 0; $offset < $fixture['rows']; $offset += $batchSize) {
            $count = min($batchSize, $fixture['rows'] - $offset);
            $values = [];
            $args = [];
            for ($row = 0; $row < $count; $row++) {
                $values[] = '(%d,%d,0)';
                $args[] = $fixture['object_start'] + $offset + $row;
                $args[] = $fixture['taxonomy_id'];
            }
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT INTO `{$table}` (object_id,term_taxonomy_id,term_order) VALUES " . implode(',', $values),
                ...$args
            ));
            wp_fts_wc_assert($inserted === $count, 'Could not seed the complete relationship scope backlog.');
            $statements++;
        }
    }
    $inserted = $wpdb->query($wpdb->prepare(
        "INSERT INTO `{$table}` (object_id,term_taxonomy_id,term_order) VALUES (%d,%d,0)",
        $cursor,
        $targetTaxonomyId
    ));
    wp_fts_wc_assert($inserted === 1, 'Could not seed the target relationship cursor sentinel.');

    return $statements + 1;
}

/** @return array{post_ids:int[],post_types:string[],post_statuses:string[],statements:int} */
function wp_fts_wc_seed_filtered_scope_lanes(string $table, int $firstPostId): array
{
    global $wpdb;

    $postTypes = [];
    for ($type = 1; $type <= 8; $type++) {
        $postTypes[] = 'wc_type_' . str_pad((string) $type, 2, '0', STR_PAD_LEFT);
    }
    $postStatuses = [];
    for ($status = 1; $status <= 4; $status++) {
        $postStatuses[] = 'wc_status_' . str_pad((string) $status, 2, '0', STR_PAD_LEFT);
    }
    $rows = [];
    $postIds = [];
    $nextPostId = $firstPostId;
    foreach ($postTypes as $postType) {
        foreach ($postStatuses as $postStatus) {
            for ($row = 0; $row < 100; $row++) {
                $rows[] = [$nextPostId, $postStatus, $postType, ''];
                $postIds[] = $nextPostId;
                $nextPostId++;
            }
        }
    }
    $statements = 0;
    foreach (array_chunk($rows, 500) as $batch) {
        $values = [];
        $args = [];
        foreach ($batch as $row) {
            $values[] = '(%d,%s,%s,%s)';
            array_push($args, ...$row);
        }
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT INTO `{$table}` (ID,post_status,post_type,post_password) VALUES " . implode(',', $values),
            ...$args
        ));
        wp_fts_wc_assert($inserted === count($batch), 'Could not seed all 32 filtered-scope lanes.');
        $statements++;
    }

    return [
        'post_ids' => $postIds,
        'post_types' => $postTypes,
        'post_statuses' => $postStatuses,
        'statements' => $statements,
    ];
}

/**
 * Repair missing current-schema scope indexes on populated InnoDB clones of
 * WordPress's canonical core tables. Redirecting the canonical wpdb properties
 * here exercises the production ownership, DDL, writer lease, and verification
 * path rather than a copied query.
 *
 * @param array<string,mixed> $takeoverBefore
 * @return array{evidence:array<string,mixed>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_populated_scope_index_repair(array $takeoverBefore): array
{
    global $wpdb;

    $posts = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_repair_posts');
    $relationships = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_repair_relationships');
    $sequence = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_wc_repair_sequence');
    $originalPosts = wp_fts_wc_identifier((string) ($wpdb->posts ?? ((string) $wpdb->prefix . 'posts')));
    $originalRelationships = wp_fts_wc_identifier((string) ($wpdb->term_relationships ?? ((string) $wpdb->prefix . 'term_relationships')));
    $schemaOption = WP_FTS_Plugin::SCHEMA_VERSION_OPTION;
    $ownershipOption = WP_FTS_Plugin::SCOPE_INDEX_OWNERSHIP_OPTION;
    $originalOwnership = get_option($ownershipOption, []);
    $readinessBefore = wp_fts_wc_scope_repair_readiness_options();
    $workBefore = wp_fts_wc_scope_repair_work_signature();
    $dropFixture = static function () use ($wpdb, $posts, $relationships, $sequence): void {
        foreach ([$relationships, $posts, $sequence] as $table) {
            wp_fts_wc_assert(
                $wpdb->query("DROP TABLE IF EXISTS `{$table}`") !== false,
                "Could not drop populated scope-index fixture table {$table}."
            );
        }
    };
    $result = null;

    $dropFixture();
    try {
        wp_fts_wc_assert(
            $wpdb->query("CREATE TABLE `{$posts}` LIKE `{$originalPosts}`") !== false,
            'Could not clone the canonical InnoDB posts table for populated repair DDL.'
        );
        wp_fts_wc_assert(
            $wpdb->query("CREATE TABLE `{$relationships}` LIKE `{$originalRelationships}`") !== false,
            'Could not clone the canonical InnoDB term-relationships table for populated repair DDL.'
        );
        wp_fts_wc_assert(
            $wpdb->query("DROP INDEX `" . WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME . "` ON `{$posts}`") !== false,
            'Could not stage the cloned posts table without its current scope index.'
        );
        wp_fts_wc_assert(
            $wpdb->query("DROP INDEX `" . WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME . "` ON `{$posts}`") !== false,
            'Could not stage the cloned posts table without its current visibility index.'
        );
        wp_fts_wc_assert(
            $wpdb->query("DROP INDEX `" . WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME . "` ON `{$relationships}`") !== false,
            'Could not stage the cloned relationships table without its current scope index.'
        );
        wp_fts_wc_assert(
            $wpdb->query("CREATE TABLE `{$sequence}` (n bigint unsigned NOT NULL, PRIMARY KEY (n)) ENGINE=InnoDB") !== false,
            'Could not create the populated scope-index sequence fixture.'
        );
        wp_fts_wc_assert($wpdb->query("INSERT INTO `{$sequence}` (n) VALUES (1)") === 1, 'Could not seed the scope-index sequence.');
        $sequenceRows = 1;
        $sequenceStatements = 1;
        while ($sequenceRows < 300001) {
            $copy = min($sequenceRows, 300001 - $sequenceRows);
            $inserted = $wpdb->query(
                "INSERT INTO `{$sequence}` (n) SELECT n+{$sequenceRows} FROM `{$sequence}` ORDER BY n ASC LIMIT {$copy}"
            );
            wp_fts_wc_assert($inserted === $copy, 'Could not double the complete scope-index sequence.');
            $sequenceRows += $copy;
            $sequenceStatements++;
        }
        $postColumns = 'ID,post_author,post_date,post_date_gmt,post_content,post_title,post_excerpt,post_status,comment_status,ping_status,post_password,post_name,to_ping,pinged,post_modified,post_modified_gmt,post_content_filtered,post_parent,guid,menu_order,post_type,post_mime_type,comment_count';
        $insertedPosts = $wpdb->query(
            "INSERT INTO `{$posts}` ({$postColumns})
SELECT n,1,'2020-01-01 00:00:00','2020-01-01 00:00:00','scope repair body',CONCAT('Scope repair ',n),'','publish','closed','closed','',CONCAT('scope-repair-',n),'','','2020-01-01 00:00:00','2020-01-01 00:00:00','',0,CONCAT('https://example.invalid/?p=',n),0,'post','',0
FROM `{$sequence}`
WHERE n<=100001"
        );
        wp_fts_wc_assert($insertedPosts === 100001, 'Could not populate the canonical posts DDL fixture.');
        $insertedRelationships = $wpdb->query(
            "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order)
SELECT FLOOR((n-1)/3)+1,MOD(n-1,1000)+1,0
FROM `{$sequence}`
WHERE n<=300001"
        );
        wp_fts_wc_assert($insertedRelationships === 300001, 'Could not populate the canonical relationships DDL fixture.');
        wp_fts_wc_assert($wpdb->query("ANALYZE TABLE `{$posts}`, `{$relationships}`") !== false, 'Could not analyze the populated canonical DDL fixtures.');

        $wpdb->posts = $posts;
        $wpdb->term_relationships = $relationships;
        $engines = $wpdb->get_results($wpdb->prepare(
            'SELECT TABLE_NAME,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN (%s,%s) ORDER BY TABLE_NAME',
            $posts,
            $relationships
        ), ARRAY_A) ?: [];
        $engineMap = [];
        foreach ($engines as $row) {
            $engineMap[(string) ($row['TABLE_NAME'] ?? '')] = strtoupper((string) ($row['ENGINE'] ?? ''));
        }
        $cardinality = [
            'posts' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$posts}`", 'populated scope-index repair posts'),
            'relationships' => wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$relationships}`", 'populated scope-index repair relationships'),
        ];
        $beforeIndexes = [
            'targeted' => wp_fts_wc_scope_index_columns($relationships, WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME),
            'filtered' => wp_fts_wc_scope_index_columns($posts, WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME),
            'visibility' => wp_fts_wc_scope_index_columns($posts, WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME),
        ];
        $beforeBytes = wp_fts_wc_scope_fixture_bytes($posts, $relationships);

        wp_fts_wc_assert(
            (int) get_option($schemaOption, 0) === WP_FTS_Plugin::SCHEMA_VERSION,
            'The populated scope-index repair requires the current schema version.'
        );
        wp_fts_wc_assert(
            update_option($ownershipOption, [], false) || get_option($ownershipOption, null) === [],
            'Could not clear scope-index ownership before the populated current-schema repair.'
        );
        WP_FTS_Plugin::reset_request_caches();
        $stagedSchema = (int) get_option($schemaOption, 0);
        $stagedOwnershipRows = wp_fts_wc_cold_option_rows([$ownershipOption]);

        $threadId = (int) $wpdb->get_var(
            'SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()'
        );
        wp_fts_wc_assert($threadId > 0, 'Could not map the populated scope-index repair to Performance Schema.');
        $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
            'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
            $threadId
        ));
        $expectedDdl = [
            "CREATE INDEX `" . WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME . "` ON `{$relationships}`(`term_taxonomy_id`,`object_id`)",
            "CREATE INDEX `" . WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME . "` ON `{$posts}`(`post_type`,`post_status`,`ID`)",
            "CREATE INDEX `" . WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME . "` ON `{$posts}`(`ID`,`post_type`,`post_status`,`post_password`,`post_date_gmt`)",
        ];
        $coordinationFilter = static function (string $sql) use ($expectedDdl, $posts, $relationships): string {
            $position = array_search($sql, $expectedDdl, true);
            if (!is_int($position)) {
                return $sql;
            }
            $ordinal = $position + 1;
            $directory = wp_fts_wc_evidence_dir();
            wp_fts_wc_write_json($directory . "/scope-ddl-start-{$ordinal}.json", [
                'schema' => 'relational-fts-scope-ddl-start-v1',
                'ordinal' => $ordinal,
                'sql_sha256' => hash('sha256', $sql),
                'tables' => ['posts' => $posts, 'relationships' => $relationships],
                'published_monotonic_ns' => hrtime(true),
            ]);
            foreach (['insert', 'update'] as $operation) {
                wp_fts_wc_wait_for_json_file(
                    $directory . "/scope-ddl-ready-{$ordinal}-{$operation}.json",
                    60.0,
                    "scope DDL {$ordinal} {$operation} writer readiness"
                );
            }
            wp_fts_wc_write_json($directory . "/scope-ddl-release-{$ordinal}.json", [
                'schema' => 'relational-fts-scope-ddl-release-v1',
                'ordinal' => $ordinal,
                'published_monotonic_ns' => hrtime(true),
            ]);

            return $sql;
        };
        $phpLifetimePeakBeforeReset = memory_get_peak_usage(true);
        wp_fts_wc_reset_php_peak_usage();
        gc_collect_cycles();
        $phpUsageBefore = memory_get_usage(true);
        $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
        $started = hrtime(true);
        add_filter('query', $coordinationFilter, PHP_INT_MIN, 1);
        try {
            $recorded = wp_fts_wc_record_queries(static function (): void {
                $result = WP_FTS_Plugin::repair_schema();
                wp_fts_wc_assert(empty($result['skipped_locked']), 'Current-schema repair unexpectedly lost its writer lease.');
            });
        } finally {
            remove_filter('query', $coordinationFilter, PHP_INT_MIN);
        }
        $wallDuration = wp_fts_wc_elapsed_ms($started);
        $phpPhasePeakAfter = memory_get_peak_usage(true);
        $phpPeakBytes = max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter);
        $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
        $phpPeakDelta = max(0, $phpPhasePeakAfter - $phpUsageBefore);
        $rssPeakDelta = max(0, $rssPeakAfter - $rssBefore);

        $queries = array_values($recorded['queries']);
        $physicalStatements = array_values(array_filter(
            $queries,
            static function (string $sql): bool {
                $firstToken = strtok(strtoupper(ltrim($sql)), " \t\r\n");

                return in_array($firstToken, ['CREATE', 'ALTER', 'DROP', 'RENAME', 'TRUNCATE'], true);
            }
        ));
        $ddl = array_values(array_filter(
            $queries,
            static fn(string $sql): bool => str_starts_with(strtoupper(ltrim($sql)), 'CREATE INDEX ')
        ));
        $ddlPositions = [];
        $ownershipMutationPositions = [];
        foreach ($queries as $position => $sql) {
            if (in_array($sql, $ddl, true)) {
                $ddlPositions[] = $position;
            }
            $normalized = strtoupper(ltrim($sql));
            $optionMutation = str_starts_with($normalized, 'INSERT ')
                || str_starts_with($normalized, 'UPDATE ')
                || str_starts_with($normalized, 'REPLACE ');
            if (!$optionMutation) {
                continue;
            }
            if (str_contains($sql, $ownershipOption)) {
                $ownershipMutationPositions[] = $position;
            }
        }

        $events = $wpdb->get_results($wpdb->prepare(
            'SELECT EVENT_ID,SQL_TEXT,TIMER_START,TIMER_END,TIMER_WAIT,LOCK_TIME,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
            $threadId,
            $beforeEvent
        ), ARRAY_A) ?: [];
        $ddlEvents = array_values(array_filter(
            $events,
            static fn(array $event): bool => in_array((string) ($event['SQL_TEXT'] ?? ''), $ddl, true)
        ));
        $queryHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $ddl);
        $eventHashes = array_map(
            static fn(array $event): string => hash('sha256', (string) ($event['SQL_TEXT'] ?? '')),
            $ddlEvents
        );
        $serverDurations = array_map(
            static fn(array $event): float => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
            $ddlEvents
        );
        $maxServerDuration = max($serverDurations ?: [PHP_INT_MAX]);
        $totalServerDuration = array_sum($serverDurations);
        $ddlEventsByHash = [];
        foreach ($ddlEvents as $event) {
            $ddlEventsByHash[hash('sha256', (string) ($event['SQL_TEXT'] ?? ''))] = $event;
        }

        $scopeWriterRecords = [];
        $writerValid = true;
        $writerOverlap = true;
        $writerClientDurations = [];
        $writerServerDurations = [];
        $writerLockDurations = [];
        $writerPids = [];
        foreach ([1, 2, 3] as $ordinal) {
            $ddlHash = hash('sha256', $expectedDdl[$ordinal - 1]);
            $ddlEvent = $ddlEventsByHash[$ddlHash] ?? [];
            foreach (['insert', 'update'] as $operation) {
                $path = wp_fts_wc_evidence_dir() . "/scope-ddl-writer-{$ordinal}-{$operation}.json";
                $writer = wp_fts_wc_wait_for_json_file($path, 60.0, "scope DDL {$ordinal} {$operation} writer result");
                $expectedWrite = wp_fts_wc_scope_ddl_writer_statement($ordinal, $operation, $posts, $relationships);
                $writeEvent = is_array($writer['performance_schema_event'] ?? null)
                    ? $writer['performance_schema_event']
                    : [];
                $overlap = $ddlEvent !== []
                    && $writeEvent !== []
                    && (int) ($ddlEvent['TIMER_START'] ?? PHP_INT_MAX) < (int) ($writeEvent['TIMER_END'] ?? 0)
                    && (int) ($writeEvent['TIMER_START'] ?? PHP_INT_MAX) < (int) ($ddlEvent['TIMER_END'] ?? 0);
                $valid = ($writer['schema'] ?? null) === 'relational-fts-scope-ddl-writer-v1'
                    && ($writer['status'] ?? null) === 'PASS'
                    && ($writer['ordinal'] ?? null) === $ordinal
                    && ($writer['operation'] ?? null) === $operation
                    && (int) ($writer['pid'] ?? 0) > 0
                    && ($writer['wordpress_bootstrapped'] ?? null) === false
                    && ($writer['sql_sha256'] ?? null) === hash('sha256', $expectedWrite)
                    && (int) ($writer['affected_rows'] ?? -1) === 1
                    && ($writer['performance_schema_sql_sha256'] ?? null) === hash('sha256', $expectedWrite);
                $writerValid = $writerValid && $valid;
                $writerOverlap = $writerOverlap && $overlap;
                $writerPids[] = (int) ($writer['pid'] ?? 0);
                $writerClientDurations[] = (float) ($writer['client_duration_ms'] ?? INF);
                $writerServerDurations[] = (float) ($writer['server_duration_ms'] ?? INF);
                $writerLockDurations[] = (float) ($writer['server_lock_ms'] ?? INF);
                $writer['overlapped_ddl'] = $overlap;
                $scopeWriterRecords[(string) $ordinal][$operation] = $writer;
            }
        }
        $maxWriterClientDuration = max($writerClientDurations ?: [INF]);
        $maxWriterServerDuration = max($writerServerDurations ?: [INF]);
        $maxWriterLockDuration = max($writerLockDurations ?: [INF]);
        $distinctWriterPids = array_values(array_unique($writerPids));

        $afterBytes = wp_fts_wc_scope_fixture_bytes($posts, $relationships);
        $afterIndexes = [
            'targeted' => wp_fts_wc_scope_index_columns($relationships, WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME),
            'filtered' => wp_fts_wc_scope_index_columns($posts, WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME),
            'visibility' => wp_fts_wc_scope_index_columns($posts, WP_FTS_Relational_Storage::VISIBILITY_INDEX_NAME),
        ];
        $indexBytesDelta = $afterBytes['index_bytes'] - $beforeBytes['index_bytes'];
        $readinessAfter = wp_fts_wc_scope_repair_readiness_options();
        $workAfter = wp_fts_wc_scope_repair_work_signature();
        WP_FTS_Plugin::reset_request_caches();
        $takeoverAfter = wp_fts_wc_scope_takeover_signature(WP_FTS_Plugin::search_takeover_status(false));
        $afterSchema = (int) get_option($schemaOption, 0);
        $afterOwnershipRows = wp_fts_wc_cold_option_rows([$ownershipOption]);
        $afterOwnership = get_option($ownershipOption, []);
        $afterOwnership = is_array($afterOwnership)
            ? array_values(array_filter($afterOwnership, 'is_string'))
            : [];
        sort($afterOwnership, SORT_STRING);
        $autoloadValues = function_exists('wp_autoload_values_to_autoload')
            ? array_map('strval', wp_autoload_values_to_autoload())
            : ['yes'];
        $ownershipRow = $afterOwnershipRows[$ownershipOption] ?? null;
        $ownershipAutoload = is_array($ownershipRow) ? (string) ($ownershipRow['autoload'] ?? '') : '';
        $stagedOwnershipRow = $stagedOwnershipRows[$ownershipOption] ?? null;
        $stagedOwnershipAutoload = is_array($stagedOwnershipRow)
            ? (string) ($stagedOwnershipRow['autoload'] ?? '')
            : '';
        $ownershipBeforeDdl = count($ddlPositions) === 3
            && $ownershipMutationPositions !== []
            && min($ownershipMutationPositions) < min($ddlPositions);
        $exactIndexes = ($afterIndexes['targeted']['columns'] ?? null) === ['term_taxonomy_id', 'object_id']
            && ($afterIndexes['targeted']['unique'] ?? null) === false
            && ($afterIndexes['filtered']['columns'] ?? null) === ['post_type', 'post_status', 'ID']
            && ($afterIndexes['filtered']['unique'] ?? null) === false
            && ($afterIndexes['visibility']['columns'] ?? null) === ['ID', 'post_type', 'post_status', 'post_password', 'post_date_gmt']
            && ($afterIndexes['visibility']['unique'] ?? null) === false;
        $exactEngines = count($engineMap) === 2
            && count(array_filter($engineMap, static fn(string $engine): bool => $engine !== 'INNODB')) === 0;

        $gates = [
            wp_fts_wc_gate('scope_index_repair_innodb_core_clones', ['InnoDB', 'InnoDB'], array_values($engineMap), $exactEngines),
            wp_fts_wc_gate('scope_index_repair_fixture_cardinality', ['posts' => 100001, 'relationships' => 300001], $cardinality, $cardinality === ['posts' => 100001, 'relationships' => 300001]),
            wp_fts_wc_gate('scope_index_repair_missing_indexes', ['schema' => WP_FTS_Plugin::SCHEMA_VERSION, 'targeted' => [], 'filtered' => [], 'visibility' => []], ['schema' => $stagedSchema, 'targeted' => $beforeIndexes['targeted']['columns'], 'filtered' => $beforeIndexes['filtered']['columns'], 'visibility' => $beforeIndexes['visibility']['columns']], $stagedSchema === WP_FTS_Plugin::SCHEMA_VERSION && $beforeIndexes['targeted']['columns'] === [] && $beforeIndexes['filtered']['columns'] === [] && $beforeIndexes['visibility']['columns'] === []),
            wp_fts_wc_gate('scope_index_repair_exact_ddl', $expectedDdl, $physicalStatements, $ddl === $expectedDdl && $physicalStatements === $expectedDdl),
            wp_fts_wc_gate('scope_index_repair_ownership_before_ddl', 'nonautoloaded [filtered,targeted,visibility] mutation before first CREATE', ['staged_autoload' => $stagedOwnershipAutoload, 'positions' => $ownershipMutationPositions, 'ddl_positions' => $ddlPositions, 'after' => $afterOwnership], $stagedOwnershipRow !== null && !in_array($stagedOwnershipAutoload, $autoloadValues, true) && $ownershipBeforeDdl && $afterOwnership === ['filtered', 'targeted', 'visibility']),
            wp_fts_wc_gate('scope_index_repair_schema_version_stable', WP_FTS_Plugin::SCHEMA_VERSION, $afterSchema, $afterSchema === WP_FTS_Plugin::SCHEMA_VERSION),
            wp_fts_wc_gate('scope_index_repair_performance_schema_attribution', $queryHashes, $eventHashes, count($ddlEvents) === 3 && $eventHashes === $queryHashes),
            wp_fts_wc_gate('scope_index_repair_wall_duration_ms', '<= 180000', $wallDuration, $wallDuration <= 180000.0),
            wp_fts_wc_gate('scope_index_repair_server_duration_ms', ['max_ms' => '<= 120000', 'total_ms' => '<= 180000'], ['max_ms' => $maxServerDuration, 'total_ms' => $totalServerDuration], count($ddlEvents) === 3 && $maxServerDuration <= 120000.0 && $totalServerDuration <= 180000.0),
            wp_fts_wc_gate('scope_index_repair_concurrent_writes', '6 exact successful canonical writes from 1 persistent lightweight process', $scopeWriterRecords, $writerValid && count($writerClientDurations) === 6 && count($distinctWriterPids) === 1),
            wp_fts_wc_gate('scope_index_repair_write_overlap', 'every INSERT/UPDATE server interval overlaps its CREATE INDEX', $scopeWriterRecords, $writerValid && $writerOverlap),
            wp_fts_wc_gate('scope_index_repair_write_duration_ms', ['client_max' => '<= 5000', 'server_max' => '<= 5000'], ['client_max' => $maxWriterClientDuration, 'server_max' => $maxWriterServerDuration, 'lock_max' => $maxWriterLockDuration], $writerValid && $maxWriterClientDuration <= 5000.0 && $maxWriterServerDuration <= 5000.0),
            wp_fts_wc_gate('scope_index_repair_storage_delta', '0 < index byte delta <= 134217728', ['before' => $beforeBytes, 'after' => $afterBytes, 'index_bytes_delta' => $indexBytesDelta], $indexBytesDelta > 0 && $indexBytesDelta <= 134217728),
            wp_fts_wc_gate('scope_index_repair_memory', ['php_peak_delta' => '<= 16777216', 'php_peak' => '0 < lifetime peak <= 134217728', 'rss_peak_delta' => '<= 16777216 using VmHWM-after minus VmRSS-before', 'rss_peak' => '0 < VmHWM <= 134217728'], ['php_peak_delta' => $phpPeakDelta, 'php_peak' => $phpPeakBytes, 'rss_peak_delta' => $rssPeakDelta, 'rss_peak' => $rssPeakAfter], $phpUsageBefore > 0 && $phpPeakDelta === max(0, $phpPhasePeakAfter - $phpUsageBefore) && $phpPeakDelta <= 16777216 && $phpPeakBytes === max($phpLifetimePeakBeforeReset, $phpPhasePeakAfter) && $phpPeakBytes > 0 && $phpPeakBytes <= 134217728 && $rssBefore > 0 && $rssPeakDelta === max(0, $rssPeakAfter - $rssBefore) && $rssPeakDelta <= 16777216 && $rssPeakAfter > 0 && $rssPeakAfter <= 134217728),
            wp_fts_wc_gate('scope_index_repair_query_count', '<= 64 total; exactly 3 DDL', ['total' => count($queries), 'ddl' => count($ddl)], count($queries) <= 64 && count($ddl) === 3),
            wp_fts_wc_gate('scope_index_repair_exact_definitions', ['targeted' => ['term_taxonomy_id', 'object_id'], 'filtered' => ['post_type', 'post_status', 'ID'], 'visibility' => ['ID', 'post_type', 'post_status', 'post_password', 'post_date_gmt']], $afterIndexes, $exactIndexes),
            wp_fts_wc_gate('scope_index_repair_readiness_preserved', ['options' => $readinessBefore, 'takeover' => $takeoverBefore], ['options' => $readinessAfter, 'takeover' => $takeoverAfter], $readinessAfter === $readinessBefore && $takeoverAfter === $takeoverBefore),
            wp_fts_wc_gate('scope_index_repair_work_preserved', $workBefore, $workAfter, $workAfter === $workBefore),
            wp_fts_wc_gate('scope_index_repair_ownership_nonautoloaded', 'nonautoloaded', $ownershipAutoload, $ownershipRow !== null && !in_array($ownershipAutoload, $autoloadValues, true)),
        ];
        $result = [
            'evidence' => [
                'schema' => 'relational-fts-populated-scope-index-repair-v1',
                'engines' => $engineMap,
                'cardinality' => $cardinality,
                'sequence_rows' => $sequenceRows,
                'sequence_seed_statements' => $sequenceStatements,
                'schema_version_before' => $stagedSchema,
                'schema_version_after' => $afterSchema,
                'wall_duration_ms' => $wallDuration,
                'server_duration_ms' => ['per_ddl' => $serverDurations, 'max' => $maxServerDuration, 'total' => $totalServerDuration],
                'concurrent_writes' => $scopeWriterRecords,
                'concurrent_write_duration_ms' => ['client_max' => $maxWriterClientDuration, 'server_max' => $maxWriterServerDuration, 'lock_max' => $maxWriterLockDuration],
                'query_count' => count($queries),
                'ddl_count' => count($ddl),
                'ddl' => $ddl,
                'ddl_sql_sha256' => $queryHashes,
                'performance_schema_sql_sha256' => $eventHashes,
                'performance_schema_events' => $ddlEvents,
                'concurrent_writer_pids' => $distinctWriterPids,
                'ownership_mutation_positions' => $ownershipMutationPositions,
                'ddl_positions' => $ddlPositions,
                                'scope_index_ownership' => ['keys' => $afterOwnership, 'autoload' => $ownershipAutoload],
                'indexes_before' => $beforeIndexes,
                'indexes_after' => $afterIndexes,
                'storage_before' => $beforeBytes,
                'storage_after' => $afterBytes,
                'index_bytes_delta' => $indexBytesDelta,
                'php_usage_before_bytes' => $phpUsageBefore,
                'php_lifetime_peak_before_reset_bytes' => $phpLifetimePeakBeforeReset,
                'php_phase_peak_after_reset_bytes' => $phpPhasePeakAfter,
                'php_peak_bytes' => $phpPeakBytes,
                'php_peak_delta_bytes' => $phpPeakDelta,
                'rss_before_bytes' => $rssBefore,
                'rss_peak_bytes' => $rssPeakAfter,
                'rss_peak_delta_bytes' => $rssPeakDelta,
                'rss_peak_delta_attribution' => 'conservative_vmhwm_after_minus_vmrss_before',
                'readiness_before' => $readinessBefore,
                'readiness_after' => $readinessAfter,
                'takeover_before' => $takeoverBefore,
                'takeover_after' => $takeoverAfter,
                'work_before' => $workBefore,
                'work_after' => $workAfter,
            ],
            'gates' => $gates,
        ];
    } finally {
        $wpdb->posts = $originalPosts;
        $wpdb->term_relationships = $originalRelationships;
        if (get_option($ownershipOption, []) !== $originalOwnership) {
            update_option($ownershipOption, $originalOwnership, false);
        }
        WP_FTS_Plugin::reset_request_caches();
        $dropFixture();
    }

    wp_fts_wc_assert(is_array($result), 'The populated current-schema scope-index repair did not produce a result.');
    if (!wp_fts_wc_gates_pass($result['gates'])) {
        throw new RuntimeException(
            'Populated current-schema scope-index repair failed: '
            . implode(', ', wp_fts_wc_gate_failures($result['gates']))
        );
    }

    return $result;
}

/**
 * Issue canonical core-table writes on a separate lightweight connection while
 * a populated current-schema CREATE INDEX is active. One PHP process covers
 * both operations and all three indexes without loading a second WordPress
 * runtime; Performance Schema timer intervals prove overlap.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_scope_ddl_writer(): array
{
    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert(!defined('ABSPATH') && !function_exists('get_option'), 'The lightweight scope DDL writer must run before WordPress bootstrap.');
    wp_fts_wc_assert(class_exists(mysqli::class), 'The lightweight scope DDL writer requires mysqli.');
    $databaseHost = wp_fts_wc_required_env('WORDPRESS_DB_HOST');
    $databasePort = 3306;
    $portSeparator = strrpos($databaseHost, ':');
    if ($portSeparator !== false) {
        $port = substr($databaseHost, $portSeparator + 1);
        wp_fts_wc_assert(
            $port !== ''
                && strspn($port, '0123456789') === strlen($port)
                && (int) $port > 0
                && (int) $port <= 65535,
            'The lightweight scope DDL writer received an invalid database port.'
        );
        $databasePort = (int) $port;
        $databaseHost = substr($databaseHost, 0, $portSeparator);
    }
    wp_fts_wc_assert($databaseHost !== '', 'The lightweight scope DDL writer received an empty database host.');
    mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
    $database = new mysqli(
        $databaseHost,
        wp_fts_wc_required_env('WORDPRESS_DB_USER'),
        wp_fts_wc_required_env('WORDPRESS_DB_PASSWORD'),
        wp_fts_wc_required_env('WORDPRESS_DB_NAME'),
        $databasePort
    );
    $database->set_charset('utf8mb4');
    $directory = wp_fts_wc_evidence_dir();
    $results = [];
    $totalDuration = 0.0;
    $tables = null;
    $pid = (int) getmypid();
    wp_fts_wc_assert($pid > 0, 'Could not identify the persistent scope DDL writer process.');
    $threadResult = $database->query(
        'SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()'
    );
    $threadRow = $threadResult->fetch_assoc();
    $threadResult->free();
    $threadId = is_array($threadRow) ? (int) ($threadRow['THREAD_ID'] ?? 0) : 0;
    wp_fts_wc_assert($threadId > 0, 'Could not map the scope DDL writer to Performance Schema.');
    foreach ([1, 2, 3] as $ordinal) {
        $start = wp_fts_wc_wait_for_json_file(
            $directory . "/scope-ddl-start-{$ordinal}.json",
            1200.0,
            "scope DDL {$ordinal} start"
        );
        wp_fts_wc_assert(
            ($start['schema'] ?? null) === 'relational-fts-scope-ddl-start-v1'
                && ($start['ordinal'] ?? null) === $ordinal,
            'Scope DDL writer received a malformed start capability.'
        );
        $startTables = is_array($start['tables'] ?? null) ? $start['tables'] : [];
        wp_fts_wc_assert(
            array_keys($startTables) === ['posts', 'relationships']
                && is_string($startTables['posts'])
                && is_string($startTables['relationships']),
            'Scope DDL writer start capability omitted its exact core-table names.'
        );
        $currentTables = [
            'posts' => wp_fts_wc_identifier((string) $startTables['posts']),
            'relationships' => wp_fts_wc_identifier((string) $startTables['relationships']),
        ];
        if ($tables === null) {
            $tables = $currentTables;
        }
        wp_fts_wc_assert($currentTables === $tables, 'Scope DDL writer core-table names changed between index builds.');
        foreach (['insert', 'update'] as $operation) {
            wp_fts_wc_write_json($directory . "/scope-ddl-ready-{$ordinal}-{$operation}.json", [
                'schema' => 'relational-fts-scope-ddl-ready-v1',
                'ordinal' => $ordinal,
                'operation' => $operation,
                'pid' => $pid,
                'published_monotonic_ns' => hrtime(true),
            ]);
        }
        $release = wp_fts_wc_wait_for_json_file(
            $directory . "/scope-ddl-release-{$ordinal}.json",
            120.0,
            "scope DDL {$ordinal} release"
        );
        wp_fts_wc_assert(
            ($release['schema'] ?? null) === 'relational-fts-scope-ddl-release-v1'
                && ($release['ordinal'] ?? null) === $ordinal,
            'Scope DDL writer received a malformed release capability.'
        );
        // Let the repair worker leave its query filter and enter mysqli_query() first.
        // Both writes still start while a 100k/300k InnoDB index build is active;
        // the server timer intervals below prove that rather than assuming it.
        usleep(2000);

        foreach (['insert', 'update'] as $operation) {
            $sql = wp_fts_wc_scope_ddl_writer_statement(
                $ordinal,
                $operation,
                $tables['posts'],
                $tables['relationships']
            );
            $beforeEventResult = $database->query(
                "SELECT COALESCE(MAX(EVENT_ID),0) AS event_id FROM performance_schema.events_statements_history_long WHERE THREAD_ID={$threadId}"
            );
            $beforeEventRow = $beforeEventResult->fetch_assoc();
            $beforeEventResult->free();
            $beforeEvent = is_array($beforeEventRow) ? (int) ($beforeEventRow['event_id'] ?? 0) : 0;
            $started = hrtime(true);
            $database->query($sql);
            $affected = $database->affected_rows;
            $clientDuration = wp_fts_wc_elapsed_ms($started);
            $eventResult = $database->query(
                "SELECT EVENT_ID,SQL_TEXT,TIMER_START,TIMER_END,TIMER_WAIT,LOCK_TIME,ROWS_EXAMINED,ROWS_AFFECTED FROM performance_schema.events_statements_history_long WHERE THREAD_ID={$threadId} AND EVENT_ID>{$beforeEvent} ORDER BY EVENT_ID"
            );
            $events = $eventResult->fetch_all(MYSQLI_ASSOC);
            $eventResult->free();
            $events = array_values(array_filter(
                $events,
                static fn(array $event): bool => (string) ($event['SQL_TEXT'] ?? '') === $sql
            ));
            $event = count($events) === 1 ? $events[0] : [];
            $serverDuration = $event === []
                ? INF
                : max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0);
            $serverLock = $event === []
                ? INF
                : max(0.0, (float) ($event['LOCK_TIME'] ?? 0) / 1000000000.0);
            $passed = $affected === 1 && count($events) === 1;
            $result = [
                'schema' => 'relational-fts-scope-ddl-writer-v1',
                'status' => $passed ? 'PASS' : 'FAIL',
                'phase' => 'scope-ddl-writer',
                'pid' => $pid,
                'wordpress_bootstrapped' => false,
                'ordinal' => $ordinal,
                'operation' => $operation,
                'affected_rows' => $affected,
                'client_duration_ms' => $clientDuration,
                'server_duration_ms' => $serverDuration,
                'server_lock_ms' => $serverLock,
                'sql_sha256' => hash('sha256', $sql),
                'performance_schema_sql_sha256' => $event === []
                    ? null
                    : hash('sha256', (string) ($event['SQL_TEXT'] ?? '')),
                'performance_schema_event' => $event,
            ];
            wp_fts_wc_write_json($directory . "/scope-ddl-writer-{$ordinal}-{$operation}.json", $result);
            if (!$passed) {
                throw new RuntimeException("Concurrent scope DDL {$operation} writer failed for index {$ordinal}.");
            }
            $results[(string) $ordinal][$operation] = $result;
            $totalDuration += $clientDuration;
        }
    }
    $database->close();

    return [
        'status' => 'PASS',
        'phase' => 'scope-ddl-writer',
        'pid' => $pid,
        'wordpress_bootstrapped' => false,
        'php_peak_bytes' => memory_get_peak_usage(true),
        'rss_peak_bytes' => wp_fts_wc_rss_bytes('VmHWM'),
        'ordinals' => $results,
        'duration_ms' => $totalDuration,
    ];
}

/** Select the deterministic concurrent DDL writer operation for one ordinal. */
function wp_fts_wc_scope_ddl_writer_statement(
    int $ordinal,
    string $operation,
    string $posts,
    string $relationships
): string {
    if ($ordinal === 1) {
        return $operation === 'insert'
            ? "INSERT INTO `{$relationships}` (object_id,term_taxonomy_id,term_order) VALUES (4000000001,4000000001,0)"
            : "UPDATE `{$relationships}` SET term_order=term_order+1 WHERE object_id=1 AND term_taxonomy_id=1";
    }
    if ($operation === 'update') {
        return "UPDATE `{$posts}` SET menu_order=menu_order+1 WHERE ID=1";
    }
    $postId = 4000000000 + $ordinal;
    $columns = 'ID,post_author,post_date,post_date_gmt,post_content,post_title,post_excerpt,post_status,comment_status,ping_status,post_password,post_name,to_ping,pinged,post_modified,post_modified_gmt,post_content_filtered,post_parent,guid,menu_order,post_type,post_mime_type,comment_count';

    return "INSERT INTO `{$posts}` ({$columns})
SELECT {$postId},post_author,post_date,post_date_gmt,post_content,'Concurrent scope repair insert',post_excerpt,post_status,comment_status,ping_status,post_password,'concurrent-scope-repair-insert-{$ordinal}',to_ping,pinged,post_modified,post_modified_gmt,post_content_filtered,post_parent,'https://example.invalid/?p={$postId}',menu_order,post_type,post_mime_type,comment_count
FROM `{$posts}` WHERE ID=1";
}

/** @return array<string,mixed> */
function wp_fts_wc_wait_for_json_file(string $path, float $timeoutSeconds, string $label): array
{
    $deadline = microtime(true) + $timeoutSeconds;
    while (!is_file($path)) {
        if (microtime(true) >= $deadline) {
            throw new RuntimeException("Timed out waiting for {$label}: {$path}");
        }
        usleep(1000);
    }

    return wp_fts_wc_read_json($path);
}

/** @return array<string,mixed> */
function wp_fts_wc_scope_takeover_signature(array $status): array
{
    $signature = [];
    foreach ([
        'ready',
        'reason',
        'ready_incarnation',
        'initial_index_status',
        'initial_index_started_at',
        'initial_index_completed_at',
        'schema_status',
        'physical_schema_usable',
    ] as $key) {
        $signature[$key] = $status[$key] ?? null;
    }

    return $signature;
}

/** @return array<string,mixed> */
function wp_fts_wc_scope_repair_readiness_options(): array
{
    return [
        'health' => get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null),
        'readiness_incarnation' => get_option(WP_FTS_Plugin::READINESS_INCARNATION_OPTION, null),
        'search_ready_incarnation' => get_option(WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION, null),
    ];
}

/** @return array{total:int,groups:array<int,array{kind:string,state:string,rows:int}>} */
function wp_fts_wc_scope_repair_work_signature(): array
{
    global $wpdb;

    $work = wp_fts_wc_identifier((string) $wpdb->prefix . 'fts_work');
    $rows = $wpdb->get_results(
        "SELECT kind,state,COUNT(*) AS row_count FROM `{$work}` GROUP BY kind,state ORDER BY kind,state",
        ARRAY_A
    );
    wp_fts_wc_assert(is_array($rows), 'Could not inspect durable work during the populated scope-index repair.');
    $groups = array_map(
        static fn(array $row): array => [
            'kind' => (string) ($row['kind'] ?? ''),
            'state' => (string) ($row['state'] ?? ''),
            'rows' => (int) ($row['row_count'] ?? 0),
        ],
        $rows
    );

    return [
        'total' => array_sum(array_column($groups, 'rows')),
        'groups' => $groups,
    ];
}

/**
 * @return array{tables:array<string,array{data_bytes:int,index_bytes:int,total_bytes:int}>,data_bytes:int,index_bytes:int,total_bytes:int}
 */
function wp_fts_wc_scope_fixture_bytes(string $posts, string $relationships): array
{
    global $wpdb;

    wp_fts_wc_assert(
        $wpdb->query("ANALYZE TABLE `{$posts}`, `{$relationships}`") !== false,
        'Could not analyze both populated scope-index tables for byte accounting.'
    );
    $rows = $wpdb->get_results($wpdb->prepare(
        'SELECT TABLE_NAME,DATA_LENGTH,INDEX_LENGTH FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN (%s,%s) ORDER BY TABLE_NAME',
        $posts,
        $relationships
    ), ARRAY_A) ?: [];
    $tables = [];
    $dataBytes = 0;
    $indexBytes = 0;
    foreach ($rows as $row) {
        $data = (int) ($row['DATA_LENGTH'] ?? 0);
        $index = (int) ($row['INDEX_LENGTH'] ?? 0);
        $tables[(string) ($row['TABLE_NAME'] ?? '')] = [
            'data_bytes' => $data,
            'index_bytes' => $index,
            'total_bytes' => $data + $index,
        ];
        $dataBytes += $data;
        $indexBytes += $index;
    }
    wp_fts_wc_assert(count($tables) === 2, 'Could not account for both populated scope-index tables.');

    return [
        'tables' => $tables,
        'data_bytes' => $dataBytes,
        'index_bytes' => $indexBytes,
        'total_bytes' => $dataBytes + $indexBytes,
    ];
}

/** @return array{name:string,columns:string[],unique:bool,rows:array<int,array<string,mixed>>} */
function wp_fts_wc_scope_index_columns(string $table, string $indexName): array
{
    global $wpdb;

    $table = wp_fts_wc_identifier($table);
    $rows = $wpdb->get_results("SHOW INDEX FROM `{$table}`", ARRAY_A) ?: [];
    $rows = array_values(array_filter(
        $rows,
        static fn(array $row): bool => strcasecmp((string) ($row['Key_name'] ?? ''), $indexName) === 0
    ));
    usort($rows, static fn(array $left, array $right): int => (int) ($left['Seq_in_index'] ?? 0) <=> (int) ($right['Seq_in_index'] ?? 0));

    return [
        'name' => $indexName,
        'columns' => array_map(static fn(array $row): string => (string) ($row['Column_name'] ?? ''), $rows),
        'unique' => $rows !== [] && count(array_filter($rows, static fn(array $row): bool => (int) ($row['Non_unique'] ?? 1) !== 1)) > 0,
        'rows' => $rows,
    ];
}

/**
 * @return array{evidence:array<string,mixed>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_measure_scope_gap(
    string $caseId,
    string $tag,
    callable $readPage,
    int $initialCursor,
    array $expectedMatched,
    int $expectedPages,
    int $expectedEmptyPrefixPages,
    int $expectedScanned,
    ?int $maxCursorAdvance,
    int $pageLimit,
    int $rowsExaminedLimit,
    int $derivedRowsLimit,
    int $sortRowsLimit,
    int $statementBytesLimit
): array {
    global $wpdb;

    $threadId = (int) $wpdb->get_var(
        'SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()'
    );
    wp_fts_wc_assert($threadId > 0, "Could not map {$caseId} to Performance Schema.");
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $threadId
    ));
    $expectedMatched = array_values(array_map('intval', $expectedMatched));
    $expectedFinalCursor = $expectedMatched === [] ? $initialCursor : max($expectedMatched);
    $cursor = $initialCursor;
    $matched = [];
    $clientDurations = [];
    $samples = [];
    $scannedTotal = 0;
    $progressionBounded = true;
    $emptyGapPages = 0;
    $sweepStarted = hrtime(true);
    $recorded = wp_fts_wc_record_queries(static function () use (
        $readPage,
        $pageLimit,
        $expectedPages,
        $expectedEmptyPrefixPages,
        $maxCursorAdvance,
        &$cursor,
        &$matched,
        &$clientDurations,
        &$samples,
        &$scannedTotal,
        &$progressionBounded,
        &$emptyGapPages
    ): array {
        $finalPage = [];
        for ($pageNumber = 1; $pageNumber <= $expectedPages; $pageNumber++) {
            $beforeCursor = $cursor;
            $started = hrtime(true);
            $page = $readPage($cursor, $pageLimit);
            $clientDurations[] = wp_fts_wc_elapsed_ms($started);
            wp_fts_wc_assert(is_array($page), 'The production scope-page workflow returned a malformed page.');
            $postIds = is_array($page['post_ids'] ?? null)
                ? array_values(array_map('intval', $page['post_ids']))
                : [];
            array_push($matched, ...$postIds);
            $scanned = max(0, (int) ($page['scanned_count'] ?? -1));
            $scannedTotal += $scanned;
            $nextCursor = (int) ($page['cursor_post_id'] ?? 0);
            $exhausted = ($page['exhausted'] ?? null) === true;
            $progressionBounded = $progressionBounded
                && $scanned <= $pageLimit
                && count($postIds) <= $pageLimit
                && ($exhausted
                    ? $scanned === 0 && $nextCursor === $beforeCursor
                    : $scanned > 0
                        && $nextCursor > $beforeCursor
                        && ($maxCursorAdvance === null || $nextCursor <= $beforeCursor + $maxCursorAdvance));
            if ($pageNumber <= $expectedEmptyPrefixPages && $postIds === []) {
                $emptyGapPages++;
            }
            if (in_array($pageNumber, [1, max(1, $expectedEmptyPrefixPages), max(1, $expectedPages - 1), $expectedPages], true)) {
                $samples[(string) $pageNumber] = $page;
            }
            $cursor = $nextCursor;
            $finalPage = $page;
            if ($exhausted) {
                break;
            }
        }

        return $finalPage;
    });
    $sweepDuration = wp_fts_wc_elapsed_ms($sweepStarted);
    $queries = array_values($recorded['queries']);
    $taggedQueries = array_values(array_filter(
        $queries,
        static fn(string $sql): bool => str_starts_with(ltrim($sql), "/* {$tag} */")
    ));
    $metadataQueries = array_values(array_filter(
        $queries,
        static fn(string $sql): bool => str_starts_with(strtoupper(ltrim($sql)), 'SHOW INDEX FROM ')
    ));
    $allEvents = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,SORT_ROWS,NO_INDEX_USED,NO_GOOD_INDEX_USED,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $events = array_values(array_filter(
        $allEvents,
        static fn(array $event): bool => str_starts_with(ltrim((string) ($event['SQL_TEXT'] ?? '')), "/* {$tag} */")
    ));
    $metadataEvents = array_values(array_filter(
        $allEvents,
        static fn(array $event): bool => str_starts_with(strtoupper(ltrim((string) ($event['SQL_TEXT'] ?? ''))), 'SHOW INDEX FROM ')
    ));
    $sql = $taggedQueries[0] ?? '';
    $explain = wp_fts_wc_scope_page_explain($sql, $caseId, $derivedRowsLimit);
    $eventHashes = array_map(static fn(array $event): string => hash('sha256', (string) ($event['SQL_TEXT'] ?? '')), $events);
    $queryHashes = array_map(static fn(string $query): string => hash('sha256', $query), $taggedQueries);
    $metadataEventHashes = array_map(static fn(array $event): string => hash('sha256', (string) ($event['SQL_TEXT'] ?? '')), $metadataEvents);
    $metadataQueryHashes = array_map(static fn(string $query): string => hash('sha256', $query), $metadataQueries);
    $selectorMeasurements = wp_fts_wc_scope_measurement_vectors($taggedQueries, $events, $clientDurations);
    $metadataMeasurements = wp_fts_wc_scope_measurement_vectors($metadataQueries, $metadataEvents, null);
    $maxRowsExamined = wp_fts_wc_scope_event_max($events, 'ROWS_EXAMINED');
    $maxRowsSent = wp_fts_wc_scope_event_max($events, 'ROWS_SENT');
    $diskTempTables = wp_fts_wc_scope_event_sum($events, 'CREATED_TMP_DISK_TABLES');
    $sortMergePasses = wp_fts_wc_scope_event_sum($events, 'SORT_MERGE_PASSES');
    $maxSortRows = wp_fts_wc_scope_event_max($events, 'SORT_ROWS');
    $noIndexUsed = wp_fts_wc_scope_event_sum($events, 'NO_INDEX_USED');
    $noGoodIndexUsed = wp_fts_wc_scope_event_sum($events, 'NO_GOOD_INDEX_USED');
    $serverDurations = array_map(
        static fn(array $event): float => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
        $events
    );
    $maxServerDuration = max($serverDurations ?: [INF]);
    $metadataServerDurations = array_map(
        static fn(array $event): float => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
        $metadataEvents
    );
    $maxMetadataServerDuration = max($metadataServerDurations ?: [0.0]);
    $maxMetadataRowsSent = $metadataEvents === [] ? 0 : wp_fts_wc_scope_event_max($metadataEvents, 'ROWS_SENT');
    $metadataDiskTempTables = $metadataEvents === [] ? 0 : wp_fts_wc_scope_event_sum($metadataEvents, 'CREATED_TMP_DISK_TABLES');
    $metadataSortMergePasses = $metadataEvents === [] ? 0 : wp_fts_wc_scope_event_sum($metadataEvents, 'SORT_MERGE_PASSES');
    $metadataNoGoodIndexUsed = $metadataEvents === [] ? 0 : wp_fts_wc_scope_event_sum($metadataEvents, 'NO_GOOD_INDEX_USED');
    $maxClientDuration = max($clientDurations ?: [INF]);
    $shapeValid = count(array_filter(
        $taggedQueries,
        static fn(string $query): bool => !wp_fts_wc_scope_sql_shape_valid($caseId, $query)
    )) === 0;
    $maxStatementBytes = max(array_map('strlen', $taggedQueries) ?: [PHP_INT_MAX]);
    $finalPage = is_array($recorded['result']) ? $recorded['result'] : [];
    $resultProgression = $progressionBounded
        && count($clientDurations) === $expectedPages
        && $emptyGapPages === $expectedEmptyPrefixPages
        && $scannedTotal === $expectedScanned
        && $matched === $expectedMatched
        && $cursor === $expectedFinalCursor
        && ($finalPage['exhausted'] ?? null) === true;
    $expectedMembership = wp_fts_wc_scope_id_signature($expectedMatched);
    $actualMembership = wp_fts_wc_scope_id_signature($matched);
    $indexFlagsAcceptable = count($events) === $expectedPages
        && $noGoodIndexUsed === 0
        && ($caseId !== 'targeted_scope_expansion' || $noIndexUsed === 0);
    $expectedMetadataQueries = $caseId === 'corpus_scope_expansion' ? 0 : $expectedPages;
    $queryBudgetValid = count($taggedQueries) === $expectedPages
        && count($metadataQueries) === $expectedMetadataQueries
        && count($queries) === $expectedPages + $expectedMetadataQueries;
    $metadataAttributionValid = count($metadataEvents) === $expectedMetadataQueries
        && $metadataEventHashes === $metadataQueryHashes
        && $maxMetadataRowsSent <= 3
        && $metadataDiskTempTables === 0
        && $metadataSortMergePasses === 0
        && $metadataNoGoodIndexUsed === 0
        && $maxMetadataServerDuration <= 250.0;
    $gates = [
        wp_fts_wc_gate("{$caseId}_result_progression", ['empty_prefix_pages' => $expectedEmptyPrefixPages, 'membership' => $expectedMembership, 'scanned' => $expectedScanned], ['empty_prefix_pages' => $emptyGapPages, 'membership' => $actualMembership, 'scanned' => $scannedTotal, 'final' => $finalPage], $resultProgression),
        wp_fts_wc_gate("{$caseId}_one_statement_per_page", ['selector' => $expectedPages, 'metadata' => $expectedMetadataQueries, 'total' => $expectedPages + $expectedMetadataQueries], ['selector' => count($taggedQueries), 'metadata' => count($metadataQueries), 'total' => count($queries)], $queryBudgetValid),
        wp_fts_wc_gate("{$caseId}_sql_shape", 'bounded production keyset shape', $sql !== '' ? hash('sha256', $sql) : null, $shapeValid),
        wp_fts_wc_gate("{$caseId}_statement_bytes", "<= {$statementBytesLimit}", $maxStatementBytes, $maxStatementBytes <= $statementBytesLimit),
        wp_fts_wc_gate("{$caseId}_client_page_duration_ms", '<= 250', $maxClientDuration, $maxClientDuration <= 250.0),
        wp_fts_wc_gate("{$caseId}_server_attribution", $queryHashes, $eventHashes, count($events) === $expectedPages && $eventHashes === $queryHashes),
        wp_fts_wc_gate("{$caseId}_metadata_server_attribution", ['sql_sha256' => $metadataQueryHashes, 'rows_sent_per_page' => '<= 3', 'server_ms' => '<= 250'], ['sql_sha256' => $metadataEventHashes, 'rows_sent_per_page' => $maxMetadataRowsSent, 'server_ms' => $maxMetadataServerDuration, 'disk_tmp' => $metadataDiskTempTables, 'merge_passes' => $metadataSortMergePasses, 'no_good_index_used' => $metadataNoGoodIndexUsed], $metadataAttributionValid),
        wp_fts_wc_gate("{$caseId}_rows_examined_per_page", "<= {$rowsExaminedLimit}", $maxRowsExamined, count($events) === $expectedPages && $maxRowsExamined <= $rowsExaminedLimit),
        wp_fts_wc_gate("{$caseId}_rows_sent_per_page", "<= {$pageLimit}", $maxRowsSent, count($events) === $expectedPages && $maxRowsSent <= $pageLimit),
        wp_fts_wc_gate("{$caseId}_no_disk_temp_or_merge", 0, ['disk_tmp' => $diskTempTables, 'merge_passes' => $sortMergePasses], count($events) === $expectedPages && $diskTempTables === 0 && $sortMergePasses === 0),
        wp_fts_wc_gate("{$caseId}_sort_rows_bounded", "<= {$sortRowsLimit}", $maxSortRows, count($events) === $expectedPages && $maxSortRows <= $sortRowsLimit),
        wp_fts_wc_gate("{$caseId}_no_bad_index_flags", ['no_good_index_used' => 0, 'target_no_index_used' => 0], ['no_index_used' => $noIndexUsed, 'no_good_index_used' => $noGoodIndexUsed], $indexFlagsAcceptable),
        wp_fts_wc_gate("{$caseId}_server_page_duration_ms", '<= 250', $maxServerDuration, count($events) === $expectedPages && $maxServerDuration <= 250.0),
        wp_fts_wc_gate("{$caseId}_explain_required_keys", $explain['expected_key'], $explain['physical_access'], $explain['required_keys']),
        wp_fts_wc_gate("{$caseId}_explain_bounded_derived", $derivedRowsLimit, $explain['derived_access'], $explain['derived_bounded']),
        wp_fts_wc_gate("{$caseId}_explain_no_unbounded_sort", $caseId === 'corpus_scope_expansion' ? 'runtime sort <= 200 rows' : 'no temporary/filesort', $explain['tabular_extra'], $explain['no_unbounded_sort'] && $maxSortRows <= $sortRowsLimit),
    ];

    return [
        'evidence' => [
            'schema' => 'relational-fts-scope-gap-sweep-v2',
            'case_id' => $caseId,
            'tag' => $tag,
            'expected_pages' => $expectedPages,
            'query_count' => count($queries),
            'selector_query_count' => count($taggedQueries),
            'metadata_query_count' => count($metadataQueries),
            'performance_schema_event_count' => count($events),
            'metadata_performance_schema_event_count' => count($metadataEvents),
            'sweep_duration_ms' => $sweepDuration,
            'max_client_page_duration_ms' => $maxClientDuration,
            'max_server_page_duration_ms' => $maxServerDuration,
            'max_statement_bytes' => $maxStatementBytes,
            'max_rows_examined_per_page' => $maxRowsExamined,
            'max_rows_sent_per_page' => $maxRowsSent,
            'max_sort_rows_per_page' => $maxSortRows,
            'created_tmp_disk_tables' => $diskTempTables,
            'sort_merge_passes' => $sortMergePasses,
            'no_index_used' => $noIndexUsed,
            'no_good_index_used' => $noGoodIndexUsed,
            'matched_post_ids' => $actualMembership,
            'scanned_rows' => $scannedTotal,
            'page_samples' => $samples,
            'representative_sql' => $sql,
            'representative_sql_sha256' => $sql !== '' ? hash('sha256', $sql) : null,
            'query_sql_sha256' => $queryHashes,
            'performance_schema_sql_sha256' => $eventHashes,
            'selector_measurements' => $selectorMeasurements,
            'metadata_query_sql_sha256' => $metadataQueryHashes,
            'metadata_performance_schema_sql_sha256' => $metadataEventHashes,
            'metadata_measurements' => $metadataMeasurements,
            'metadata_max_rows_sent_per_page' => $maxMetadataRowsSent,
            'metadata_max_server_page_duration_ms' => $maxMetadataServerDuration,
            'explain' => $explain,
        ],
        'gates' => $gates,
    ];
}

/**
 * Bind each captured statement to its ordered Performance Schema counters.
 *
 * @param string[] $queries
 * @param array<int,array<string,mixed>> $events
 * @param float[]|null $clientDurations
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_scope_measurement_vectors(array $queries, array $events, ?array $clientDurations): array
{
    $vectors = [];
    foreach (array_values($queries) as $index => $query) {
        $event = is_array($events[$index] ?? null) ? $events[$index] : [];
        $timerWait = max(0, (int) ($event['TIMER_WAIT'] ?? 0));
        $vector = [
            'sql_sha256' => hash('sha256', (string) $query),
            'event_id' => max(0, (int) ($event['EVENT_ID'] ?? 0)),
            'event_sql_sha256' => hash('sha256', (string) ($event['SQL_TEXT'] ?? '')),
            'statement_bytes' => strlen((string) $query),
        ];
        if ($clientDurations !== null) {
            $vector['client_duration_ms'] = is_numeric($clientDurations[$index] ?? null)
                ? (float) $clientDurations[$index]
                : null;
        }
        $vector += [
            'rows_examined' => max(0, (int) ($event['ROWS_EXAMINED'] ?? 0)),
            'rows_sent' => max(0, (int) ($event['ROWS_SENT'] ?? 0)),
            'created_tmp_disk_tables' => max(0, (int) ($event['CREATED_TMP_DISK_TABLES'] ?? 0)),
            'sort_merge_passes' => max(0, (int) ($event['SORT_MERGE_PASSES'] ?? 0)),
            'sort_rows' => max(0, (int) ($event['SORT_ROWS'] ?? 0)),
            'no_index_used' => max(0, (int) ($event['NO_INDEX_USED'] ?? 0)),
            'no_good_index_used' => max(0, (int) ($event['NO_GOOD_INDEX_USED'] ?? 0)),
            'timer_wait_picoseconds' => $timerWait,
            'server_duration_ms' => (float) $timerWait / 1000000000.0,
        ];
        $vectors[] = $vector;
    }

    return $vectors;
}

/** @return array<string,mixed> */
function wp_fts_wc_scope_page_explain(string $sql, string $caseId, int $derivedRowsLimit): array
{
    global $wpdb;

    wp_fts_wc_assert($sql !== '', "{$caseId} produced no SQL to explain.");
    $json = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
    wp_fts_wc_assert(is_string($json) && $json !== '', "{$caseId} EXPLAIN FORMAT=JSON returned no plan.");
    $plan = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($plan), "{$caseId} EXPLAIN JSON is malformed.");
    $access = [];
    wp_fts_wc_collect_database_table_access($plan, $access);
    $physicalAccess = array_values(array_filter(
        $access,
        static fn(array $row): bool => empty($row['materialized'])
            && !str_starts_with((string) ($row['table_name'] ?? ''), '<')
    ));
    $derivedAccess = array_values(array_filter(
        $access,
        static fn(array $row): bool => !empty($row['materialized'])
            || str_starts_with(strtolower((string) ($row['table_name'] ?? '')), '<derived')
    ));
    $expectedPhysical = match ($caseId) {
        'targeted_scope_expansion', 'filtered_scope_expansion' => 1,
        'filtered_scope_max_lanes' => 32,
        default => 2,
    };
    $expectedKey = match ($caseId) {
        'targeted_scope_expansion' => WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME,
        'filtered_scope_expansion', 'filtered_scope_max_lanes' => WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME,
        default => 'PRIMARY',
    };
    $requiredKeys = count($physicalAccess) === $expectedPhysical
        && count(array_filter($physicalAccess, static fn(array $row): bool => strcasecmp((string) ($row['key'] ?? ''), $expectedKey) !== 0 || strtoupper((string) ($row['access_type'] ?? '')) === 'ALL')) === 0;
    if ($derivedRowsLimit === 0) {
        $derivedBounded = $derivedAccess === [];
    } else {
        $derivedRows = array_map(static fn(array $row): int => is_int($row['rows'] ?? null) ? $row['rows'] : PHP_INT_MAX, $derivedAccess);
        $derivedBounded = $derivedAccess !== [] && max($derivedRows ?: [PHP_INT_MAX]) <= $derivedRowsLimit;
    }
    $tabular = $wpdb->get_results('EXPLAIN ' . $sql, ARRAY_A) ?: [];
    $extra = strtolower(implode('; ', array_map(static fn(array $row): string => (string) ($row['Extra'] ?? ''), $tabular)));
    $noUnboundedSort = $caseId === 'targeted_scope_expansion'
        ? !str_contains($extra, 'temporary') && !str_contains($extra, 'filesort')
        : $derivedBounded;

    return [
        'json' => $plan,
        'table_access' => $access,
        'physical_access' => $physicalAccess,
        'derived_access' => $derivedAccess,
        'tabular' => $tabular,
        'tabular_extra' => $extra,
        'expected_key' => $expectedKey,
        'required_keys' => $requiredKeys,
        'derived_bounded' => $derivedBounded,
        'no_unbounded_sort' => $noUnboundedSort,
    ];
}

/** Require each scope lane to retain its indexed keyset and bounded LIMIT shape. */
function wp_fts_wc_scope_sql_shape_valid(string $caseId, string $sql): bool
{
    if ($caseId === 'targeted_scope_expansion') {
        return str_contains($sql, ' scope_rel FORCE INDEX (`wp_fts_term_object`)')
            && str_contains($sql, 'WHERE scope_rel.term_taxonomy_id = ')
            && str_contains($sql, 'AND scope_rel.object_id > ')
            && str_contains($sql, 'ORDER BY scope_rel.object_id ASC')
            && substr_count($sql, 'LIMIT ') === 1
            && !str_contains($sql, 'FROM wp_fts_wc_scope_posts');
    }
    if (in_array($caseId, ['filtered_scope_expansion', 'filtered_scope_max_lanes'], true)) {
        $lanes = $caseId === 'filtered_scope_max_lanes' ? 32 : 1;

        return substr_count($sql, ' p FORCE INDEX (`wp_fts_type_status_id`)') === $lanes
            && substr_count($sql, 'WHERE p.post_type = ') === $lanes
            && substr_count($sql, 'AND p.post_status = ') === $lanes
            && substr_count($sql, 'AND p.ID > ') === $lanes
            && substr_count($sql, 'ORDER BY p.ID ASC') === $lanes
            && substr_count($sql, 'UNION ALL') === $lanes - 1
            && substr_count($sql, 'LIMIT ') === $lanes + 1
            && str_contains($sql, 'MAX(filtered_candidates.should_process)')
            && str_contains($sql, 'GROUP BY filtered_candidates.post_id')
            && str_contains($sql, 'ORDER BY filtered_candidates.post_id ASC');
    }

    return $caseId === 'corpus_scope_expansion'
        && str_contains($sql, '/* wp_fts:corpus-scope-page */')
        && str_contains($sql, 'UNION ALL')
        && str_contains($sql, ' raw_posts FORCE INDEX (PRIMARY)')
        && str_contains($sql, 'WHERE raw_posts.ID > ')
        && str_contains($sql, 'ORDER BY raw_posts.ID ASC')
        && str_contains($sql, ' raw_documents FORCE INDEX (PRIMARY)')
        && str_contains($sql, 'WHERE raw_documents.post_id > ')
        && str_contains($sql, 'ORDER BY raw_documents.post_id ASC')
        && str_contains($sql, 'GROUP BY candidates.post_id')
        && substr_count($sql, 'LIMIT ') === 3;
}

/** @param array<int,array<string,mixed>> $events */
function wp_fts_wc_scope_event_max(array $events, string $field): int
{
    return max(array_map(static fn(array $event): int => (int) ($event[$field] ?? PHP_INT_MAX), $events) ?: [PHP_INT_MAX]);
}

/** @param array<int,array<string,mixed>> $events */
function wp_fts_wc_scope_event_sum(array $events, string $field): int
{
    return array_sum(array_map(static fn(array $event): int => (int) ($event[$field] ?? PHP_INT_MAX), $events));
}

/** @param int[] $postIds @return array{count:int,first:?int,last:?int,sha256:string} */
function wp_fts_wc_scope_id_signature(array $postIds): array
{
    $context = hash_init('sha256');
    foreach ($postIds as $postId) {
        hash_update($context, (string) $postId . "\n");
    }

    return [
        'count' => count($postIds),
        'first' => $postIds[0] ?? null,
        'last' => $postIds === [] ? null : $postIds[array_key_last($postIds)],
        'sha256' => hash_final($context),
    ];
}

/**
 * Begin an uncommitted physical mutation and wait to be SIGKILLed by the
 * wrapper. Reaching the sleep is recorded before the parent kills this process.
 *
 * @return never
 */
function wp_fts_wc_transaction_crash(): never
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    if ($wpdb->query('START TRANSACTION') === false) {
        throw new RuntimeException('Could not start the crash-probe transaction.');
    }
    $statement = $wpdb->prepare(
        "INSERT INTO `{$terms}` (lang,kind,term,doc_freq) VALUES (%s,0,%s,0)",
        'en',
        'transactioncrashsentinel'
    );
    if ($wpdb->query($statement) !== 1) {
        throw new RuntimeException('Could not insert the uncommitted crash sentinel.');
    }
    $processIdentity = wp_fts_wc_process_identity();
    if (!wp_fts_wc_process_identity_valid($processIdentity)) {
        throw new RuntimeException('Could not bind the crash probe to its Linux process lifetime.');
    }
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/transaction-crash-ready.json', [
        'schema' => 'relational-fts-transaction-crash-ready-v1',
        'process_identity' => $processIdentity,
        'connection_id' => (int) $wpdb->get_var('SELECT CONNECTION_ID()'),
        'sentinel' => 'transactioncrashsentinel',
    ]);
    while (true) {
        sleep(60);
    }
}

/** @return array<string,mixed> */
function wp_fts_wc_verify_transaction_crash(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $readyPath = wp_fts_wc_evidence_dir() . '/transaction-crash-ready.json';
    $ready = wp_fts_wc_read_json($readyPath);
    $receipt = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/transaction-crash-kill-receipt.json');
    $readySha256 = hash_file('sha256', $readyPath);
    $receiptValid = is_string($readySha256)
        && wp_fts_wc_transaction_crash_receipt_is_exact($ready, $receipt, $readySha256);
    $terms = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $count = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$terms}` WHERE lang=%s AND kind=0 AND term=%s", 'en', 'transactioncrashsentinel'));
    $rows = WP_FTS_Plugin::search('rareanchor', ['lang' => 'en', 'mode' => 'OR', 'limit' => 20]);
    $gates = [
        wp_fts_wc_gate('killed_transaction_sigkill_receipt', ['signal' => 9, 'kill_exit_status' => 0, 'exit_status' => 137, 'ready_sha256' => 'exact', 'process_identity' => 'independently observed exact'], ['signal' => $receipt['signal'] ?? null, 'kill_exit_status' => $receipt['kill_exit_status'] ?? null, 'exit_status' => $receipt['exit_status'] ?? null, 'ready_sha256' => $receipt['ready_sha256'] ?? null, 'ready_process_identity' => $ready['process_identity'] ?? null, 'observed_process_identity' => $receipt['observed_process_identity'] ?? null], $receiptValid),
        wp_fts_wc_gate('killed_transaction_rolled_back', 0, $count, $count === 0),
        wp_fts_wc_gate('search_after_killed_transaction', '> 0', count($rows), $rows !== []),
    ];
    $result = ['schema' => 'relational-fts-transaction-crash-v3', 'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL', 'phase' => 'verify-transaction-crash', 'killed_process' => $ready, 'kill_receipt' => $receipt, 'sentinel_rows' => $count, 'search_rows' => count($rows), 'gates' => $gates];
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/transaction-crash.json', $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Killed-transaction recovery proof failed: ' . implode(', ', wp_fts_wc_gate_failures($gates)));
    }
    return ['status' => 'PASS', 'phase' => 'verify-transaction-crash'];
}

/** Prove the final artifact came from an observed SIGKILL of the ready child. */
function wp_fts_wc_transaction_crash_receipt_is_exact(array $ready, array $receipt, string $readySha256): bool
{
    $identity = is_array($ready['process_identity'] ?? null) ? $ready['process_identity'] : [];
    $observedIdentity = is_array($receipt['observed_process_identity'] ?? null)
        ? $receipt['observed_process_identity']
        : [];

    return array_keys($ready) === ['schema', 'process_identity', 'connection_id', 'sentinel']
        && ($ready['schema'] ?? null) === 'relational-fts-transaction-crash-ready-v1'
        && wp_fts_wc_process_identity_valid($identity)
        && is_int($ready['connection_id'] ?? null)
        && $ready['connection_id'] > 0
        && ($ready['sentinel'] ?? null) === 'transactioncrashsentinel'
        && array_keys($receipt) === ['schema', 'ready_sha256', 'child_pid', 'observed_process_identity', 'kill_exit_status', 'exit_status', 'signal']
        && ($receipt['schema'] ?? null) === 'relational-fts-transaction-crash-kill-receipt-v2'
        && wp_fts_wc_is_lowercase_sha256($readySha256)
        && ($receipt['ready_sha256'] ?? null) === $readySha256
        && ($receipt['child_pid'] ?? null) === ($identity['pid'] ?? null)
        && wp_fts_wc_process_identity_valid($observedIdentity)
        && $observedIdentity === $identity
        && ($receipt['kill_exit_status'] ?? null) === 0
        && ($receipt['exit_status'] ?? null) === 137
        && ($receipt['signal'] ?? null) === 9;
}

/** Reject failed or nonnumeric database counts instead of coercing them to zero. */
function wp_fts_wc_checked_count(string $statement, string $context): int
{
    global $wpdb;

    $value = $wpdb->get_var($statement);
    if (!is_numeric($value) || trim((string) $wpdb->last_error) !== '') {
        throw new RuntimeException("Could not count {$context}: " . trim((string) $wpdb->last_error));
    }
    return (int) $value;
}

/** Compute the exclusive binary prefix bound without enumerating completions. */
function wp_fts_wc_binary_successor(string $value): ?string
{
    for ($index = strlen($value) - 1; $index >= 0; $index--) {
        $byte = ord($value[$index]);
        if ($byte < 255) {
            return substr($value, 0, $index) . chr($byte + 1);
        }
    }
    return null;
}

/**
 * Drain remaining dirty work after the timed concurrency window and retain a
 * fully instrumented 100-document batch. This phase is outside search latency.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_drain(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_require_plugin();
    $manifest = wp_fts_wc_manifest();
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $started = hrtime(true);
    $batches = [];
    $queueClaimPlans = [];
    $batchMaximumFields = [
        'max_total_statement_count' => 'total_statement_count',
        'max_fts_data_statement_count' => 'fts_data_statement_count',
        'max_bounded_data_statement_count' => 'bounded_data_statement_count',
        'max_lease_control_statement_count' => 'lease_control_statement_count',
        'max_transaction_control_statement_count' => 'worker_transaction_control_statement_count',
        'max_scheduling_control_statement_count' => 'scheduling_control_statement_count',
        'max_physical_schema_statement_count' => 'physical_schema_statement_count',
        'max_scope_index_probe_statement_count' => 'scope_index_probe_statement_count',
        'max_unexpected_physical_schema_statement_count' => 'unexpected_physical_schema_statement_count',
        'max_statement_bytes' => 'max_statement_bytes',
        'max_batch_ms' => 'duration_ms',
    ];
    $initialDrainMaxima = array_fill_keys(array_keys($batchMaximumFields), 0);
    $initialDrainBatchCount = 0;
    $initialDrainIndexed = 0;
    $initialDrainMaxIndexed = 0;
    $initialDrainFullBatchCount = 0;
    $initialDrainFailures = 0;
    $initialDrainTotalStatementsBounded = true;
    $deadline = microtime(true) + 7200.0;
    $consecutiveNoProgress = 0;
    $remaining = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work rows before the instrumented drain');
    while ($remaining > 0) {
        if (microtime(true) >= $deadline) {
            throw new RuntimeException('Work drain exceeded the two-hour hard ceiling.');
        }
        $batch = wp_fts_wc_instrumented_worker_batch('worst-case-drain', $queueClaimPlans);
        $remainingAfter = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work rows after an instrumented drain pass');
        $batch['work_rows_before'] = $remaining;
        $batch['work_rows_after'] = $remainingAfter;
        $initialDrainBatchCount++;
        $initialDrainIndexed += (int) ($batch['indexed'] ?? 0);
        $initialDrainMaxIndexed = max($initialDrainMaxIndexed, (int) ($batch['indexed'] ?? 0));
        $initialDrainFullBatchCount += (int) ($batch['indexed'] ?? 0) === 100 ? 1 : 0;
        $initialDrainFailures += (int) ($batch['failures'] ?? 0);
        $initialDrainTotalStatementsBounded = $initialDrainTotalStatementsBounded
            && (int) ($batch['total_statement_count'] ?? PHP_INT_MAX) <= 20;
        foreach ($batchMaximumFields as $resultField => $batchField) {
            $initialDrainMaxima[$resultField] = max(
                $initialDrainMaxima[$resultField],
                $batch[$batchField] ?? 0
            );
        }
        wp_fts_wc_wait_after_worker_no_progress($batch, $deadline, 'Instrumented work drain', $consecutiveNoProgress);
        $remaining = $remainingAfter;
        // The taxonomy scope can take hundreds of bounded worker calls. Keep
        // its scalar totals, not every query hash and server event until exit.
        unset($batch);
        gc_collect_cycles();
        gc_mem_caches();
    }

    // A naturally full queue can still take the unchanged-hash fast path. Build
    // an explicit batch from the 100 smallest public corpus sources so this
    // isolates the document-count ceiling from the separate aggregate posting
    // and term ceilings, then prove all 100 are analyzed and rewritten.
    $fixtureIds = array_map('intval', $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts}
WHERE post_title LIKE %s AND post_type='post' AND post_status='publish' AND post_password=''
ORDER BY OCTET_LENGTH(post_content) ASC,ID ASC LIMIT 100",
        WP_FTS_WC_POST_TITLE_PREFIX . $wpdb->esc_like((string) $manifest['token']) . '%'
    )) ?: []);
    wp_fts_wc_assert(count($fixtureIds) === 100 && count(array_unique($fixtureIds)) === 100, 'Changed-worker proof requires 100 distinct public corpus posts.');
    $hashesBefore = wp_fts_wc_document_hashes($documents, $fixtureIds);
    wp_fts_wc_assert(count($hashesBefore) === 100, 'Changed-worker proof could not read all 100 pre-mutation hashes.');
    $idSql = implode(',', array_fill(0, count($fixtureIds), '%d'));
    $mutation = ' wcworkerchanged' . substr(hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')), 0, 12);
    $updated = $wpdb->query($wpdb->prepare(
        "UPDATE {$wpdb->posts} SET post_excerpt=CONCAT(post_excerpt,%s),post_modified_gmt=UTC_TIMESTAMP() WHERE ID IN ({$idSql})",
        $mutation,
        ...$fixtureIds
    ));
    wp_fts_wc_assert(is_int($updated) && $updated === 100, 'Changed-worker proof did not mutate exactly 100 canonical posts.');
    $queue = new WP_FTS_Index_Queue($wpdb);
    $enqueue = wp_fts_wc_record_queries(static fn() => $queue->enqueue_many($fixtureIds));
    $queued = (int) $enqueue['result'];
    $enqueueStatements = array_values(array_filter($enqueue['queries'], 'wp_fts_wc_is_search_statement'));
    $fixtureWorkRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'changed-worker fixture work');
    wp_fts_wc_assert($queued === 100 && $fixtureWorkRows === 100, 'Changed-worker fixture did not produce exactly 100 coalesced work rows.');

    $changedBatch = wp_fts_wc_instrumented_worker_batch('worst-case-changed-100', $queueClaimPlans);
    $changedBatch['fixture'] = 'smallest_public_sources';
    $batches[] = $changedBatch;
    $remainingAfterChanged = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'work rows after the changed-worker batch');
    wp_fts_wc_assert($remainingAfterChanged === 0, 'The scope-free changed-worker baseline must leave no post or scope work.');
    $hashesAfter = wp_fts_wc_document_hashes($documents, $fixtureIds);
    $changedHashes = 0;
    foreach ($fixtureIds as $postId) {
        if (isset($hashesBefore[$postId], $hashesAfter[$postId]) && !hash_equals($hashesBefore[$postId], $hashesAfter[$postId])) {
            $changedHashes++;
        }
    }
    $baselineRoles = is_array($changedBatch['statement_roles'] ?? null)
        ? array_values($changedBatch['statement_roles'])
        : [];
    $mixedActiveScope = wp_fts_wc_mixed_scope_changed_batch(
        'active-scope',
        $fixtureIds,
        false,
        $baselineRoles,
        $queueClaimPlans
    );
    array_push($batches, ...$mixedActiveScope['batches']);
    $mixedExhaustedCorpusScope = wp_fts_wc_mixed_scope_changed_batch(
        'exhausted-corpus-scope',
        $fixtureIds,
        true,
        $baselineRoles,
        $queueClaimPlans
    );
    array_push($batches, ...$mixedExhaustedCorpusScope['batches']);
    $composedMaximumWorker = wp_fts_wc_composed_maximum_worker_path($queueClaimPlans);
    array_push($batches, ...$composedMaximumWorker['batches']);
    $remaining = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        'work rows after both mixed scope/post batches'
    );
    $changedRoleContract = (int) ($changedBatch['total_statement_count'] ?? PHP_INT_MAX) <= 20
        && (int) ($changedBatch['bounded_data_statement_count'] ?? PHP_INT_MAX) <= 15
        && ($changedBatch['statement_roles_ordered'] ?? false) === true
        && (int) ($changedBatch['unclassified_statement_count'] ?? PHP_INT_MAX) === 0
        && array_values(array_filter(
            is_array($changedBatch['statement_roles'] ?? null) ? $changedBatch['statement_roles'] : [],
            static fn(string $role): bool => str_starts_with($role, 'lease_')
        )) === ['lease_acquire', 'lease_release']
        && array_values(array_filter(
            is_array($changedBatch['statement_roles'] ?? null) ? $changedBatch['statement_roles'] : [],
            static fn(string $role): bool => str_starts_with($role, 'transaction_')
        )) === ['transaction_start', 'transaction_commit'];
    $allBatchesHaveBoundedTotal = $initialDrainTotalStatementsBounded && count(array_filter(
        $batches,
        static fn(array $batch): bool => (int) ($batch['total_statement_count'] ?? PHP_INT_MAX) > 20
    )) === 0;

    $maxIndexed = max($initialDrainMaxIndexed, max(array_column($batches, 'indexed') ?: [0]));
    $fullBatchCount = $initialDrainFullBatchCount
        + count(array_filter($batches, static fn(array $batch): bool => (int) ($batch['indexed'] ?? 0) === 100));
    $failures = $initialDrainFailures + array_sum(array_column($batches, 'failures'));
    $batchMaxima = $initialDrainMaxima;
    foreach ($batchMaximumFields as $resultField => $batchField) {
        $batchMaxima[$resultField] = max(
            $batchMaxima[$resultField],
            max(array_column($batches, $batchField) ?: [0])
        );
    }
    $result = [
        'schema' => 'relational-fts-drain-v7',
        'status' => $batches !== []
            && $fullBatchCount > 0
            && $failures === 0
            && $remaining === 0
            && $allBatchesHaveBoundedTotal
            && $changedRoleContract
            && (int) ($changedBatch['attempted'] ?? -1) === 100
            && (int) ($changedBatch['indexed'] ?? -1) === 100
            && (int) ($changedBatch['analyzed'] ?? -1) === 100
            && (int) ($changedBatch['unchanged'] ?? -1) === 0
            && $changedHashes === 100
            && ($mixedActiveScope['status'] ?? null) === 'PASS'
            && ($mixedExhaustedCorpusScope['status'] ?? null) === 'PASS'
            && ($composedMaximumWorker['status'] ?? null) === 'PASS'
            ? 'PASS'
            : 'FAIL',
        'phase' => 'drain',
        'elapsed_ms' => wp_fts_wc_elapsed_ms($started),
        'batch_count' => $initialDrainBatchCount + count($batches),
        'batches' => $batches,
        'initial_drain' => [
            'batch_count' => $initialDrainBatchCount,
            'indexed' => $initialDrainIndexed,
            'max_indexed' => $initialDrainMaxIndexed,
            'full_100_document_batches' => $initialDrainFullBatchCount,
            'failures' => $initialDrainFailures,
            'maxima' => $initialDrainMaxima,
        ],
        'indexed' => $initialDrainIndexed + array_sum(array_column($batches, 'indexed')),
        'max_indexed' => $maxIndexed,
        'full_100_document_batches' => $fullBatchCount,
        'changed_100_document_batch' => [
            'post_ids' => $fixtureIds,
            'source_selection' => 'smallest_public_sources',
            'mutation_sha256' => hash('sha256', $mutation),
            'enqueue_statement_count' => count($enqueueStatements),
            'queued' => $queued,
            'work_rows_before_batch' => $fixtureWorkRows,
            'hashes_before_sha256' => wp_fts_wc_canonical_hash($hashesBefore),
            'hashes_after_sha256' => wp_fts_wc_canonical_hash($hashesAfter),
            'changed_hashes' => $changedHashes,
            'batch' => $changedBatch,
        ],
        'mixed_active_scope_continuous_arrival' => $mixedActiveScope,
        'mixed_exhausted_corpus_scope_continuous_arrival' => $mixedExhaustedCorpusScope,
        'composed_maximum_worker_path' => $composedMaximumWorker,
        'failures' => $failures,
        'remaining' => $remaining,
        'php_peak_bytes' => memory_get_peak_usage(true),
        'rss_peak_bytes' => wp_fts_wc_rss_bytes('VmHWM'),
        'queue_claim_explain' => $queueClaimPlans,
    ];
    $result = array_replace($result, $batchMaxima);
    wp_fts_wc_write_json(wp_fts_wc_evidence_dir() . '/drain.json', $result);
    if ($result['status'] !== 'PASS') {
        throw new RuntimeException('Final work-drain proof failed.');
    }

    return ['status' => 'PASS', 'phase' => 'drain', 'indexed' => $result['indexed'], 'batches' => count($batches)];
}

/**
 * Force both sides of the durable mixed scope/post alternation with a fresh
 * maximum changed-document arrival before the reserved scope turn.
 *
 * @param int[] $postIds
 * @param string[] $baselineRoles
 * @param array<string,array<string,mixed>> $queueClaimPlans
 * @return array<string,mixed>
 */
function wp_fts_wc_mixed_scope_changed_batch(
    string $caseId,
    array $postIds,
    bool $exhausted,
    array $baselineRoles,
    array &$queueClaimPlans
): array {
    global $wpdb;

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $profileHash = wp_fts_wc_current_index_profile_hash();
    $incarnation = get_option(WP_FTS_Plugin::READINESS_INCARNATION_OPTION, '');
    wp_fts_wc_assert(
        is_string($incarnation) && preg_match('/^[a-f0-9]{32}$/D', $incarnation) === 1,
        "Mixed {$caseId} proof requires the current readiness incarnation."
    );
    $healthOptionExists = (int) $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name=%s",
        WP_FTS_Plugin::INDEX_HEALTH_OPTION
    )) === 1;
    $healthBefore = get_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, null);
    wp_fts_wc_assert(
        is_array($healthBefore)
        && is_string($healthBefore['index_profile_hash'] ?? null)
        && hash_equals($profileHash, (string) $healthBefore['index_profile_hash']),
        "Mixed {$caseId} proof requires health bound to the current index profile."
    );

    $scopeKey = 'worst-case-mixed-' . $caseId . '-' . substr(
        hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . $caseId),
        0,
        20
    );
    $scopeJobKey = 'scope:' . hash('sha256', $scopeKey);
    $maximumSourceId = max(
        (int) $wpdb->get_var("SELECT COALESCE(MAX(ID),0) FROM {$wpdb->posts}"),
        (int) $wpdb->get_var("SELECT COALESCE(MAX(post_id),0) FROM `{$documents}`")
    );
    wp_fts_wc_assert($maximumSourceId > 0, "Mixed {$caseId} proof requires at least one corpus identity.");
    $initialCursor = $exhausted ? $maximumSourceId : max(0, $maximumSourceId - 1);
    $queue = new WP_FTS_Index_Queue($wpdb);
    $queue->enqueue_scope(
        $scopeKey,
        ['reason' => 'worst_case_mixed_' . str_replace('-', '_', $caseId), 'profile_hash' => $profileHash],
        null,
        WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
        '',
        0,
        $incarnation
    );
    $cursorSet = $wpdb->query($wpdb->prepare(
        "UPDATE `{$work}` SET cursor_post_id=%d,last_error_code='' WHERE job_key=%s AND kind='scope'",
        $initialCursor,
        $scopeJobKey
    ));
    wp_fts_wc_assert($cursorSet === 1, "Mixed {$caseId} proof could not condition the exact scope cursor.");
    if (function_exists('wp_next_scheduled') && function_exists('wp_schedule_single_event') && wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) === false) {
        wp_schedule_single_event(time() + 1, WP_FTS_Plugin::CRON_HOOK);
    }
    if (
        $exhausted
        && function_exists('wp_next_scheduled')
        && function_exists('wp_schedule_single_event')
        && wp_next_scheduled(WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK) === false
    ) {
        wp_schedule_single_event(time() + 1, WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK);
    }

    $firstArrival = wp_fts_wc_enqueue_changed_mixed_posts($caseId . '-documents', $postIds, $documents, $queue);
    $workRowsBeforeDocumentTurn = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        "mixed {$caseId} work before the document turn"
    );
    $scopeBeforeDocumentTurn = wp_fts_wc_scope_work_row($work, $scopeJobKey);
    $documentTurn = wp_fts_wc_instrumented_worker_batch(
        'wc-mixed-' . $caseId . '-document',
        $queueClaimPlans
    );
    $hashesAfterDocumentTurn = wp_fts_wc_document_hashes($documents, $postIds);
    $changedOnDocumentTurn = wp_fts_wc_count_changed_document_hashes(
        $firstArrival['hashes_before'],
        $hashesAfterDocumentTurn,
        $postIds
    );
    $scopeAfterDocumentTurn = wp_fts_wc_scope_work_row($work, $scopeJobKey);
    $postRowsAfterDocumentTurn = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind='post'",
        "mixed {$caseId} post work after the document turn"
    );

    $expectedDocumentRoles = $baselineRoles;
    $ackPosition = array_search('atomic_worker_ack', $expectedDocumentRoles, true);
    wp_fts_wc_assert(is_int($ackPosition), 'Scope-free baseline did not expose its atomic acknowledgement role.');
    array_splice($expectedDocumentRoles, $ackPosition, 0, ['scope_yield_to_posts']);
    $documentTurnPassed = $workRowsBeforeDocumentTurn === 101
        && (int) ($firstArrival['queued'] ?? -1) === 100
        && (int) ($documentTurn['total_statement_count'] ?? PHP_INT_MAX) <= 20
        && (int) ($documentTurn['bounded_data_statement_count'] ?? PHP_INT_MAX) <= 15
        && (int) ($documentTurn['attempted'] ?? -1) === 100
        && (int) ($documentTurn['indexed'] ?? -1) === 100
        && (int) ($documentTurn['analyzed'] ?? -1) === 100
        && (int) ($documentTurn['unchanged'] ?? -1) === 0
        && (int) ($documentTurn['deferred'] ?? -1) === 0
        && $changedOnDocumentTurn === 100
        && ($documentTurn['statement_roles'] ?? null) === $expectedDocumentRoles
        && ($documentTurn['statement_roles_ordered'] ?? false) === true
        && (int) ($documentTurn['unclassified_statement_count'] ?? -1) === 0
        && $postRowsAfterDocumentTurn === 0
        && is_array($scopeBeforeDocumentTurn)
        && is_array($scopeAfterDocumentTurn)
        && (int) ($scopeAfterDocumentTurn['cursor_post_id'] ?? -1) === $initialCursor
        && ($scopeAfterDocumentTurn['state'] ?? null) === 'ready'
        && ($scopeAfterDocumentTurn['last_error_code'] ?? null) === WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE;

    // This second generation is deliberately present before the marked scope
    // turn. A post-first implementation without a persisted turn bit would
    // process it and starve the cursor under an endless write stream.
    $continuousArrival = wp_fts_wc_enqueue_changed_mixed_posts($caseId . '-continuous', $postIds, $documents, $queue);
    $workRowsBeforeScopeTurn = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        "mixed {$caseId} work before the reserved scope turn"
    );
    $scopeBeforeScopeTurn = wp_fts_wc_scope_work_row($work, $scopeJobKey);

    if ($exhausted) {
        $completionFixture = $healthBefore;
        $completionFixture['reconciliation_scope_completed_at'] = '';
        $completionFixture['reconciliation_scope_completed_incarnation'] = '';
        $completionFixture['reconciliation_scope_completed_profile_hash'] = '';
        update_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, $completionFixture, false);
        wp_cache_delete(WP_FTS_Plugin::INDEX_HEALTH_OPTION, 'options');
        wp_cache_delete('alloptions', 'options');
        WP_FTS_Plugin::reset_request_caches();
        wp_load_alloptions();
    }

    try {
        $scopeTurn = wp_fts_wc_instrumented_worker_batch(
            'wc-mixed-' . $caseId . '-scope',
            $queueClaimPlans
        );
        $scopeAfterScopeTurn = wp_fts_wc_scope_work_row($work, $scopeJobKey);
    } finally {
        if ($exhausted) {
            wp_fts_wc_restore_option(WP_FTS_Plugin::INDEX_HEALTH_OPTION, $healthOptionExists, $healthBefore);
            wp_cache_delete(WP_FTS_Plugin::INDEX_HEALTH_OPTION, 'options');
            wp_cache_delete('alloptions', 'options');
            WP_FTS_Plugin::reset_request_caches();
            wp_load_alloptions();
        }
    }

    $postRowsAfterScopeTurn = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind='post'",
        "mixed {$caseId} post work after the reserved scope turn"
    );
    $scopeRoles = is_array($scopeTurn['statement_roles'] ?? null) ? $scopeTurn['statement_roles'] : [];
    $scopeProgressed = $exhausted
        ? $scopeAfterScopeTurn === null
            && ($scopeTurn['scope_completed'] ?? false) === true
            && ($scopeTurn['scope_completed_global'] ?? false) === true
            && (int) ($scopeTurn['backfill_scanned'] ?? -1) === 0
            && in_array('scope_acknowledgement', $scopeRoles, true)
        : is_array($scopeAfterScopeTurn)
            && (int) ($scopeAfterScopeTurn['cursor_post_id'] ?? 0) > $initialCursor
            && ($scopeAfterScopeTurn['last_error_code'] ?? null) === ''
            && ($scopeTurn['scope_completed'] ?? true) === false
            && (int) ($scopeTurn['backfill_scanned'] ?? -1) === 1
            && in_array('scope_page_advance', $scopeRoles, true);
    $scopeTurnPassed = $workRowsBeforeScopeTurn === 101
        && (int) ($continuousArrival['queued'] ?? -1) === 100
        && (int) ($scopeTurn['total_statement_count'] ?? PHP_INT_MAX) <= 20
        && (int) ($scopeTurn['bounded_data_statement_count'] ?? PHP_INT_MAX) <= 15
        && (int) ($scopeTurn['attempted'] ?? -1) === 0
        && (int) ($scopeTurn['indexed'] ?? -1) === 0
        && (int) ($scopeTurn['analyzed'] ?? -1) === 0
        && (int) ($scopeTurn['deferred'] ?? -1) === 100
        && $postRowsAfterScopeTurn >= 100
        && is_array($scopeBeforeScopeTurn)
        && ($scopeBeforeScopeTurn['last_error_code'] ?? null) === WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE
        && in_array('post_batch_release', $scopeRoles, true)
        && in_array('corpus_scope_page', $scopeRoles, true)
        && ($scopeTurn['statement_roles_ordered'] ?? false) === true
        && (int) ($scopeTurn['unclassified_statement_count'] ?? -1) === 0
        && $scopeProgressed;

    if (!$exhausted) {
        $deletedScope = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$work}` WHERE job_key=%s AND kind='scope'",
            $scopeJobKey
        ));
        wp_fts_wc_assert($deletedScope === 1, 'Active mixed-scope fixture cleanup did not remove its exact scope row.');
    }
    $cleanupBatches = [];
    $cleanupDeadline = microtime(true) + 300.0;
    while (wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", "mixed {$caseId} cleanup work") > 0) {
        if (microtime(true) >= $cleanupDeadline) {
            throw new RuntimeException("Mixed {$caseId} cleanup exceeded five minutes.");
        }
        $cleanupBatch = wp_fts_wc_instrumented_worker_batch(
            'wc-mixed-' . $caseId . '-cleanup',
            $queueClaimPlans
        );
        wp_fts_wc_assert(
            (int) ($cleanupBatch['total_statement_count'] ?? PHP_INT_MAX) <= 20,
            "Mixed {$caseId} cleanup exceeded the complete worker statement ceiling."
        );
        $cleanupBatches[] = $cleanupBatch;
    }
    $remaining = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
        "mixed {$caseId} remaining work"
    );
    $allBatches = [$documentTurn, $scopeTurn, ...$cleanupBatches];
    $status = $documentTurnPassed && $scopeTurnPassed && $remaining === 0 ? 'PASS' : 'FAIL';

    return [
        'status' => $status,
        'case' => $caseId,
        'scope_coverage' => WP_FTS_Index_Queue::SCOPE_COVERAGE_CORPUS,
        'scope_was_exhausted' => $exhausted,
        'scope_job_key_sha256' => hash('sha256', $scopeJobKey),
        'initial_cursor_post_id' => $initialCursor,
        'maximum_source_post_id' => $maximumSourceId,
        'work_rows_before_document_turn' => $workRowsBeforeDocumentTurn,
        'document_turn_changed_hashes' => $changedOnDocumentTurn,
        'document_turn_expected_roles' => $expectedDocumentRoles,
        'document_turn' => $documentTurn,
        'scope_before_document_turn' => $scopeBeforeDocumentTurn,
        'scope_after_document_turn' => $scopeAfterDocumentTurn,
        'post_rows_after_document_turn' => $postRowsAfterDocumentTurn,
        'continuous_arrival' => $continuousArrival,
        'work_rows_before_scope_turn' => $workRowsBeforeScopeTurn,
        'scope_before_scope_turn' => $scopeBeforeScopeTurn,
        'scope_turn' => $scopeTurn,
        'scope_after_scope_turn' => $scopeAfterScopeTurn,
        'post_rows_after_scope_turn' => $postRowsAfterScopeTurn,
        'document_turn_passed' => $documentTurnPassed,
        'scope_turn_passed' => $scopeTurnPassed,
        'cleanup_batches' => $cleanupBatches,
        'remaining' => $remaining,
        'batches' => $allBatches,
    ];
}

/**
 * @param int[] $postIds
 * @return array<string,mixed>
 */
function wp_fts_wc_enqueue_changed_mixed_posts(
    string $caseId,
    array $postIds,
    string $documents,
    WP_FTS_Index_Queue $queue
): array {
    global $wpdb;

    $hashesBefore = wp_fts_wc_document_hashes($documents, $postIds);
    wp_fts_wc_assert(count($hashesBefore) === 100, "Mixed {$caseId} arrival could not read all prior document hashes.");
    $placeholders = implode(',', array_fill(0, count($postIds), '%d'));
    $mutation = ' wcmixed' . substr(
        hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA') . '|' . $caseId),
        0,
        20
    );
    $updated = $wpdb->query($wpdb->prepare(
        "UPDATE {$wpdb->posts} SET post_excerpt=CONCAT(post_excerpt,%s),post_modified_gmt=UTC_TIMESTAMP() WHERE ID IN ({$placeholders})",
        $mutation,
        ...$postIds
    ));
    wp_fts_wc_assert($updated === 100, "Mixed {$caseId} arrival did not mutate exactly 100 posts.");
    $recorded = wp_fts_wc_record_queries(static fn(): int => $queue->enqueue_many($postIds));
    $enqueueStatements = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_search_statement'));

    return [
        'post_count' => count($postIds),
        'mutation_sha256' => hash('sha256', $mutation),
        'hashes_before' => $hashesBefore,
        'hashes_before_sha256' => wp_fts_wc_canonical_hash($hashesBefore),
        'queued' => (int) $recorded['result'],
        'enqueue_statement_count' => count($enqueueStatements),
    ];
}

/** @return array<string,mixed>|null */
function wp_fts_wc_scope_work_row(string $work, string $scopeJobKey): ?array
{
    global $wpdb;

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT generation,state,available_at,claim_token,claimed_generation,claim_expires_at,cursor_post_id,scope_coverage,scope_incarnation,payload,last_error_code FROM `{$work}` WHERE job_key=%s AND kind='scope'",
        $scopeJobKey
    ), ARRAY_A);
    if (!is_array($row)) {
        return null;
    }
    $payload = [];
    if (is_string($row['payload'] ?? null) && (string) $row['payload'] !== '') {
        $decoded = json_decode((string) $row['payload'], true, 32, JSON_THROW_ON_ERROR);
        $payload = is_array($decoded) ? $decoded : [];
    }

    return [
        'generation' => (int) ($row['generation'] ?? 0),
        'state' => (string) ($row['state'] ?? ''),
        'available_at' => (int) ($row['available_at'] ?? 0),
        'claim_token' => (string) ($row['claim_token'] ?? ''),
        'claimed_generation' => (int) ($row['claimed_generation'] ?? 0),
        'claim_expires_at' => (int) ($row['claim_expires_at'] ?? 0),
        'cursor_post_id' => (int) ($row['cursor_post_id'] ?? 0),
        'scope_coverage' => (string) ($row['scope_coverage'] ?? ''),
        'scope_incarnation' => (string) ($row['scope_incarnation'] ?? ''),
        'payload' => $payload,
        'last_error_code' => (string) ($row['last_error_code'] ?? ''),
    ];
}

/** @param array<int,string> $before @param array<int,string> $after @param int[] $postIds */
function wp_fts_wc_count_changed_document_hashes(array $before, array $after, array $postIds): int
{
    $changed = 0;
    foreach ($postIds as $postId) {
        if (isset($before[$postId], $after[$postId]) && !hash_equals($before[$postId], $after[$postId])) {
            $changed++;
        }
    }

    return $changed;
}

/**
 * Compose the independently legal worker maxima in real cron callbacks with
 * both no existing event and a later existing singleton. Every successor may
 * split work, but no phase may exceed either complete statement ceiling.
 *
 * @param array<string,array<string,mixed>> $queueClaimPlans
 * @return array<string,mixed>
 */
function wp_fts_wc_composed_maximum_worker_path(array &$queueClaimPlans): array
{
    global $wpdb;

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $postings = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    wp_fts_wc_assert(
        wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')", 'composed-worker initial work') === 0,
        'Composed-worker proof requires an empty post/scope work table.'
    );

    $postIds = [];
    $scopeJobKey = '';
    $cronBefore = function_exists('wp_next_scheduled') ? wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) : false;
    $cleanup = [];
    $cleaned = false;
    try {
        $oldContent = wp_fts_wc_maximum_identity_source('wcoldidentity');
        $newContent = wp_fts_wc_maximum_identity_source('wcnewidentity');
        $maximumPostId = wp_fts_wc_insert_composed_worker_post('maximum', $oldContent);
        $postIds[] = $maximumPostId;
        $nearLimitPostIds = [];
        for ($number = 1; $number <= 5; $number++) {
            $nearLimitPostIds[] = wp_fts_wc_insert_composed_worker_post(
                'near-limit-' . $number,
                wp_fts_wc_near_limit_comment_source($number)
            );
        }
        array_push($postIds, ...$nearLimitPostIds);
        $languageMetaInserted = $wpdb->insert($wpdb->postmeta, [
            'post_id' => $maximumPostId,
            'meta_key' => WP_FTS_Plugin::LANGUAGE_META_KEY,
            'meta_value' => 'en',
        ]);
        wp_fts_wc_assert($languageMetaInserted === 1, 'Composed-worker proof could not insert its selected dependency value.');

        $queue = new WP_FTS_Index_Queue($wpdb);
        wp_fts_wc_assert(
            $queue->enqueue_many([$maximumPostId], null, ['index_options' => ['document_lang' => 'en']]) === 1,
            'Composed-worker old-frontier setup did not enqueue its maximum document.'
        );
        $setupBatch = wp_fts_wc_instrumented_worker_batch(
            'worst-case-composed-maximum-old-frontier',
            $queueClaimPlans
        );
        $oldPostingCounts = wp_fts_wc_document_posting_kind_counts($maximumPostId);
        $oldHashes = wp_fts_wc_document_hashes($documents, [$maximumPostId]);
        $setupPassed = (int) ($setupBatch['indexed'] ?? -1) === 1
            && (int) ($setupBatch['analyzed'] ?? -1) === 1
            && (int) ($setupBatch['failures'] ?? -1) === 0
            && (int) ($setupBatch['total_statement_count'] ?? PHP_INT_MAX) <= 20
            && (int) ($setupBatch['bounded_data_statement_count'] ?? PHP_INT_MAX) <= 15
            && (int) ($setupBatch['unclassified_statement_count'] ?? -1) === 0
            && ($setupBatch['statement_roles_ordered'] ?? false) === true
            && $oldPostingCounts === ['lexical' => 4096, 'surface' => 4096, 'total' => 8192]
            && count($oldHashes) === 1;

        $mutated = $wpdb->update(
            $wpdb->posts,
            ['post_content' => $newContent, 'post_modified' => '2020-02-02 12:00:00', 'post_modified_gmt' => '2020-02-02 12:00:00'],
            ['ID' => $maximumPostId],
            ['%s', '%s', '%s'],
            ['%d']
        );
        wp_fts_wc_assert($mutated === 1, 'Composed-worker proof could not replace the maximum canonical source.');
        wp_fts_wc_assert(
            $queue->enqueue_many($postIds, null, ['index_options' => ['document_lang' => 'en']]) === 6,
            'Composed-worker proof did not enqueue all six direct generations.'
        );
        $scopeKey = 'worst-case-composed-worker-' . substr(
            hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')),
            0,
            20
        );
        $scopeJobKey = 'scope:' . hash('sha256', $scopeKey);
        $queue->enqueue_scope(
            $scopeKey,
            [
                'reason' => 'worst_case_composed_worker',
                'post_status' => ['publish'],
                'post_type' => ['post'],
                'remaining_limit' => 1,
            ],
            null,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_FILTERED
        );
        $recoveryConditioned = $wpdb->query($wpdb->prepare(
            "UPDATE `{$work}`
SET last_error_code='content_failure',last_error_at=%d
WHERE job_key=%s AND kind='post' AND post_id=%d AND state='ready'",
            time(),
            'post:' . $maximumPostId,
            $maximumPostId
        ));
        wp_fts_wc_assert($recoveryConditioned === 1, 'Composed-worker proof could not condition the successful failure-recovery path.');
        $workRowsBefore = wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
            'composed-worker mixed work rows'
        );
        $aggregateSourceBytes = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(SUM(OCTET_LENGTH(post_title)+OCTET_LENGTH(post_content)+OCTET_LENGTH(post_excerpt)),0) FROM {$wpdb->posts} WHERE ID IN (%d,%d,%d,%d,%d,%d)",
            ...$postIds
        ));
        $selectedDependencyRows = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE post_id IN (%d,%d,%d,%d,%d,%d) AND meta_key=%s",
            ...[...$postIds, WP_FTS_Plugin::LANGUAGE_META_KEY]
        ));

        // WordPress removes a due single event before invoking its callback.
        // An already-scheduled successor would hide the option write made by
        // the real cron/no-event path, so remove it outside measurement.
        if (function_exists('wp_clear_scheduled_hook')) {
            wp_clear_scheduled_hook(WP_FTS_Plugin::CRON_HOOK);
        }
        $noEventBefore = !function_exists('wp_next_scheduled')
            || wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) === false;
        $firstBatch = wp_fts_wc_instrumented_worker_batch(
            'worst-case-composed-cron-no-event',
            $queueClaimPlans,
            true,
            'without_preexisting_event',
            true
        );
        $successorScheduled = function_exists('wp_next_scheduled')
            && wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) !== false;
        $scopeAfterFirst = wp_fts_wc_scope_work_row($work, $scopeJobKey);

        $deletedScope = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$work}` WHERE job_key=%s AND kind='scope'",
            $scopeJobKey
        ));
        wp_fts_wc_assert($deletedScope === 1, 'Composed-worker cleanup did not remove the exact yielded scope.');
        $scopeJobKey = '';

        $pathBatches = [$firstBatch];
        $deadline = microtime(true) + 900.0;
        while (wp_fts_wc_checked_count(
            $wpdb->prepare(
                "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id IN (%d,%d,%d,%d,%d,%d)",
                ...$postIds
            ),
            'composed-worker remaining direct work'
        ) > 0) {
            if (microtime(true) >= $deadline || count($pathBatches) >= 20) {
                throw new RuntimeException('Composed-worker successors did not drain within the bounded lifecycle.');
            }
            $pathBatches[] = wp_fts_wc_instrumented_worker_batch(
                'worst-case-composed-successor',
                $queueClaimPlans
            );
        }

        $newPostingCounts = wp_fts_wc_document_posting_kind_counts($maximumPostId);
        $newHashes = wp_fts_wc_document_hashes($documents, [$maximumPostId]);

        // Scheduler state is independent of document shape. Re-run the same
        // maximum replacement, aggregate source overflow, failure recovery,
        // mixed scope collision, and deferred suffix with a later singleton
        // watchdog already present. Bringing it forward must replace that
        // event with one cron-option write, never clear+schedule it with two.
        $mutatedBack = $wpdb->update(
            $wpdb->posts,
            ['post_content' => $oldContent, 'post_modified' => '2020-03-03 12:00:00', 'post_modified_gmt' => '2020-03-03 12:00:00'],
            ['ID' => $maximumPostId],
            ['%s', '%s', '%s'],
            ['%d']
        );
        wp_fts_wc_assert($mutatedBack === 1, 'Composed-worker later-event proof could not replace the maximum source.');
        foreach ($nearLimitPostIds as $index => $postId) {
            $nearMutated = $wpdb->update(
                $wpdb->posts,
                ['post_content' => wp_fts_wc_near_limit_comment_source($index + 11)],
                ['ID' => $postId],
                ['%s'],
                ['%d']
            );
            wp_fts_wc_assert($nearMutated === 1, "Composed-worker later-event proof could not mutate near-limit post {$postId}.");
        }
        wp_fts_wc_assert(
            $queue->enqueue_many($postIds, null, ['index_options' => ['document_lang' => 'en']]) === 6,
            'Composed-worker later-event proof did not enqueue all six direct generations.'
        );
        $laterScopeKey = 'worst-case-composed-worker-later-' . substr(
            hash('sha256', wp_fts_wc_required_env('WP_FTS_SOURCE_SHA')),
            0,
            20
        );
        $scopeJobKey = 'scope:' . hash('sha256', $laterScopeKey);
        $queue->enqueue_scope(
            $laterScopeKey,
            [
                'reason' => 'worst_case_composed_worker_later_event',
                'post_status' => ['publish'],
                'post_type' => ['post'],
                'remaining_limit' => 1,
            ],
            null,
            WP_FTS_Index_Queue::SCOPE_COVERAGE_FILTERED
        );
        $laterRecoveryConditioned = $wpdb->query($wpdb->prepare(
            "UPDATE `{$work}`
SET last_error_code='content_failure',last_error_at=%d
WHERE job_key=%s AND kind='post' AND post_id=%d AND state='ready'",
            time(),
            'post:' . $maximumPostId,
            $maximumPostId
        ));
        wp_fts_wc_assert($laterRecoveryConditioned === 1, 'Composed-worker later-event proof could not condition failure recovery.');
        $laterWorkRowsBefore = wp_fts_wc_checked_count(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind IN ('post','scope')",
            'composed-worker later-event mixed work rows'
        );
        if (function_exists('wp_clear_scheduled_hook')) {
            wp_clear_scheduled_hook(WP_FTS_Plugin::CRON_HOOK);
        }
        $laterScheduledAt = time() + 300;
        $laterScheduled = function_exists('wp_schedule_single_event')
            && wp_schedule_single_event($laterScheduledAt, WP_FTS_Plugin::CRON_HOOK) === true;
        $laterEventBefore = function_exists('wp_next_scheduled')
            ? wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK)
            : false;
        wp_fts_wc_assert(
            $laterScheduled && is_int($laterEventBefore) && $laterEventBefore >= $laterScheduledAt,
            'Composed-worker later-event proof could not install its future singleton watchdog.'
        );
        $laterEventBatch = wp_fts_wc_instrumented_worker_batch(
            'wc-composed-cron-later-existing-event',
            $queueClaimPlans,
            true,
            'with_later_existing_event',
            true
        );
        $laterEventAfter = function_exists('wp_next_scheduled')
            ? wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK)
            : false;
        $laterScopeAfter = wp_fts_wc_scope_work_row($work, $scopeJobKey);
        $deletedLaterScope = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$work}` WHERE job_key=%s AND kind='scope'",
            $scopeJobKey
        ));
        wp_fts_wc_assert($deletedLaterScope === 1, 'Composed-worker later-event cleanup did not remove the yielded scope.');
        $scopeJobKey = '';
        $pathBatches[] = $laterEventBatch;
        while (wp_fts_wc_checked_count(
            $wpdb->prepare(
                "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id IN (%d,%d,%d,%d,%d,%d)",
                ...$postIds
            ),
            'composed-worker later-event remaining direct work'
        ) > 0) {
            if (microtime(true) >= $deadline || count($pathBatches) >= 30) {
                throw new RuntimeException('Composed-worker later-event successors did not drain within the bounded lifecycle.');
            }
            $pathBatches[] = wp_fts_wc_instrumented_worker_batch(
                'wc-composed-later-event-successor',
                $queueClaimPlans
            );
        }

        $laterEventPostingCounts = wp_fts_wc_document_posting_kind_counts($maximumPostId);
        $laterEventHashes = wp_fts_wc_document_hashes($documents, [$maximumPostId]);
        $fixtureDocumentRows = wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$documents}` WHERE post_id IN (%d,%d,%d,%d,%d,%d)",
            ...$postIds
        ), 'composed-worker final documents');
        $remaining = wp_fts_wc_checked_count($wpdb->prepare(
            "SELECT COUNT(*) FROM `{$work}` WHERE kind='post' AND post_id IN (%d,%d,%d,%d,%d,%d)",
            ...$postIds
        ), 'composed-worker final work');
        $pathRoles = [];
        foreach ($pathBatches as $batch) {
            array_push($pathRoles, ...(is_array($batch['statement_roles'] ?? null) ? $batch['statement_roles'] : []));
        }
        $replacementBatches = array_values(array_filter(
            $pathBatches,
            static fn(array $batch): bool => in_array(
                'document_replacement',
                is_array($batch['statement_roles'] ?? null) ? $batch['statement_roles'] : [],
                true
            )
        ));
        $replacementResolveCounts = array_map(
            static fn(array $batch): int => count(array_filter(
                is_array($batch['statement_roles'] ?? null) ? $batch['statement_roles'] : [],
                static fn(string $role): bool => $role === 'resolve_prepared_terms'
            )),
            $replacementBatches
        );
        $allBounded = count(array_filter(
            $pathBatches,
            static fn(array $batch): bool =>
                (int) ($batch['total_statement_count'] ?? PHP_INT_MAX) > 20
                || (int) ($batch['bounded_data_statement_count'] ?? PHP_INT_MAX) > 15
                || (int) ($batch['scheduling_control_statement_count'] ?? PHP_INT_MAX) > 1
                || (int) ($batch['unclassified_statement_count'] ?? PHP_INT_MAX) !== 0
                || ($batch['statement_roles_ordered'] ?? false) !== true
        )) === 0;
        $leaseProtocols = array_map(
            static fn(array $batch): array => array_values(array_filter(
                is_array($batch['statement_roles'] ?? null) ? $batch['statement_roles'] : [],
                static fn(string $role): bool => str_starts_with($role, 'lease_')
            )),
            $pathBatches
        );
        $transactionProtocols = array_map(
            static fn(array $batch): array => array_values(array_filter(
                is_array($batch['statement_roles'] ?? null) ? $batch['statement_roles'] : [],
                static fn(string $role): bool => str_starts_with($role, 'transaction_')
            )),
            $pathBatches
        );
        $protocolsBounded = count(array_filter(
            $leaseProtocols,
            static fn(array $roles): bool => $roles !== ['lease_acquire', 'lease_release']
        )) === 0 && count(array_filter(
            $transactionProtocols,
            static fn(array $roles): bool => !in_array($roles, [[], ['transaction_start', 'transaction_commit']], true)
        )) === 0;
        $requiredRoles = [
            'claim_batch',
            'claim_source_snapshot',
            'conditional_source_fallback',
            'dependency_measurement',
            'dependency_values',
            'replacement_frontier',
            'dictionary_increment',
            'dictionary_decrement',
            'bounded_index_delete',
            'resolve_prepared_terms',
            'posting_replacement',
            'document_replacement',
            'scope_yield_and_post_batch_release',
            'atomic_worker_ack',
            'search_epoch_advance',
            'cron_schedule_write',
        ];
        $missingRoles = array_values(array_filter(
            $requiredRoles,
            static fn(string $role): bool => !in_array($role, $pathRoles, true)
        ));
        $firstRoles = is_array($firstBatch['statement_roles'] ?? null) ? $firstBatch['statement_roles'] : [];
        $firstStatements = is_array($firstBatch['statements'] ?? null) ? $firstBatch['statements'] : [];
        $claimSnapshotStatements = [];
        $conditionalSourceStatements = [];
        foreach ($firstRoles as $index => $role) {
            if ($role === 'claim_source_snapshot' && isset($firstStatements[$index])) {
                $claimSnapshotStatements[] = (string) $firstStatements[$index];
            } elseif ($role === 'conditional_source_fallback' && isset($firstStatements[$index])) {
                $conditionalSourceStatements[] = (string) $firstStatements[$index];
            }
        }
        $claimSnapshotSql = strtolower($claimSnapshotStatements[0] ?? '');
        $conditionalSourceSql = strtolower($conditionalSourceStatements[0] ?? '');
        $boundedSourceFallback = count($claimSnapshotStatements) === 1
            && str_contains($claimSnapshotSql, 'source_snapshot_complete')
            && str_contains($claimSnapshotSql, 'source_post_content')
            && str_contains($claimSnapshotSql, 'source_batch')
            && str_contains($claimSnapshotSql, 'sum(')
            && count($conditionalSourceStatements) === 1
            && str_contains($conditionalSourceSql, 'source_budget')
            && str_contains($conditionalSourceSql, 'canonical_budget')
            && str_contains($conditionalSourceSql, 'fts_source_changed')
            && str_contains($conditionalSourceSql, 'fts_canonical_changed');
        $laterEventRoles = is_array($laterEventBatch['statement_roles'] ?? null)
            ? $laterEventBatch['statement_roles']
            : [];
        $laterEventStatements = is_array($laterEventBatch['statements'] ?? null)
            ? $laterEventBatch['statements']
            : [];
        $laterClaimSnapshotStatements = [];
        $laterConditionalSourceStatements = [];
        foreach ($laterEventRoles as $index => $role) {
            if ($role === 'claim_source_snapshot' && isset($laterEventStatements[$index])) {
                $laterClaimSnapshotStatements[] = (string) $laterEventStatements[$index];
            } elseif ($role === 'conditional_source_fallback' && isset($laterEventStatements[$index])) {
                $laterConditionalSourceStatements[] = (string) $laterEventStatements[$index];
            }
        }
        $laterClaimSnapshotSql = strtolower($laterClaimSnapshotStatements[0] ?? '');
        $laterConditionalSourceSql = strtolower($laterConditionalSourceStatements[0] ?? '');
        $laterBoundedSourceFallback = count($laterClaimSnapshotStatements) === 1
            && str_contains($laterClaimSnapshotSql, 'source_snapshot_complete')
            && str_contains($laterClaimSnapshotSql, 'source_post_content')
            && str_contains($laterClaimSnapshotSql, 'source_batch')
            && str_contains($laterClaimSnapshotSql, 'sum(')
            && count($laterConditionalSourceStatements) === 1
            && str_contains($laterConditionalSourceSql, 'source_budget')
            && str_contains($laterConditionalSourceSql, 'canonical_budget')
            && str_contains($laterConditionalSourceSql, 'fts_source_changed')
            && str_contains($laterConditionalSourceSql, 'fts_canonical_changed');
        $firstComposed = ($firstBatch['worker_mode'] ?? null) === 'cron_without_preexisting_event'
            && in_array('scope_yield_and_post_batch_release', $firstRoles, true)
            && $boundedSourceFallback
            && count(array_filter($firstRoles, static fn(string $role): bool => $role === 'cron_schedule_write')) === 1
            && (int) ($firstBatch['scheduling_control_statement_count'] ?? -1) === 1
            && (int) ($firstBatch['bounded_data_statement_count'] ?? -1) === 15
            && (int) ($firstBatch['total_statement_count'] ?? PHP_INT_MAX) <= 20
            && !empty($firstBatch['resolved_failure_records'])
            && !in_array('health_state_cas', $firstRoles, true);
        $laterEventComposed = ($laterEventBatch['worker_mode'] ?? null) === 'cron_with_later_existing_event'
            && $laterWorkRowsBefore === 7
            && in_array('scope_yield_and_post_batch_release', $laterEventRoles, true)
            && $laterBoundedSourceFallback
            && count(array_filter($laterEventRoles, static fn(string $role): bool => $role === 'cron_schedule_write')) === 1
            && (int) ($laterEventBatch['scheduling_control_statement_count'] ?? -1) === 1
            && (int) ($laterEventBatch['bounded_data_statement_count'] ?? -1) === 15
            && (int) ($laterEventBatch['total_statement_count'] ?? PHP_INT_MAX) <= 20
            && !empty($laterEventBatch['resolved_failure_records'])
            && !in_array('health_state_cas', $laterEventRoles, true)
            && is_array($laterScopeAfter)
            && ($laterScopeAfter['last_error_code'] ?? null) === WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE
            && is_int($laterEventBefore)
            && is_int($laterEventAfter)
            && $laterEventAfter < $laterEventBefore;
        $hashChanged = isset($oldHashes[$maximumPostId], $newHashes[$maximumPostId])
            && !hash_equals($oldHashes[$maximumPostId], $newHashes[$maximumPostId]);
        $laterEventHashChanged = isset($newHashes[$maximumPostId], $laterEventHashes[$maximumPostId])
            && !hash_equals($newHashes[$maximumPostId], $laterEventHashes[$maximumPostId]);
        $pathFailures = array_sum(array_column($pathBatches, 'failures'));

        $cleanup = wp_fts_wc_cleanup_dependency_lob_fixture($postIds, $documents, $postings, $work);
        $cleaned = true;
        $status = $setupPassed
            && $workRowsBefore === 7
            && $aggregateSourceBytes > WP_FTS_Index_Queue::MAX_SOURCE_SNAPSHOT_BYTES
            && $selectedDependencyRows === 1
            && $noEventBefore
            && $successorScheduled
            && is_array($scopeAfterFirst)
            && ($scopeAfterFirst['last_error_code'] ?? null) === WP_FTS_Index_Queue::SCOPE_EXPANSION_TURN_CODE
            && $firstComposed
            && $laterEventComposed
            && $allBounded
            && $protocolsBounded
            && $missingRoles === []
            && $replacementBatches !== []
            && max($replacementResolveCounts ?: [0]) === 1
            && $pathFailures === 0
            && $newPostingCounts === ['lexical' => 4096, 'surface' => 4096, 'total' => 8192]
            && $laterEventPostingCounts === ['lexical' => 4096, 'surface' => 4096, 'total' => 8192]
            && $hashChanged
            && $laterEventHashChanged
            && $fixtureDocumentRows === 6
            && $remaining === 0
            && count(array_filter($cleanup, static fn(int $count): bool => $count !== 0)) === 0
            ? 'PASS'
            : 'FAIL';

        unset($firstBatch['statements'], $laterEventBatch['statements']);
        foreach ($pathBatches as &$pathBatch) {
            unset($pathBatch['statements']);
        }
        unset($pathBatch);

        return [
            'status' => $status,
            'fixture' => [
                'post_count' => count($postIds),
                'maximum_post_id' => $maximumPostId,
                'near_limit_post_ids' => $nearLimitPostIds,
                'maximum_source_distinct_tokens' => WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_TERMS,
                'near_limit_source_bytes_each' => 1900000,
                'aggregate_source_bytes' => $aggregateSourceBytes,
                'source_snapshot_limit_bytes' => WP_FTS_Index_Queue::MAX_SOURCE_SNAPSHOT_BYTES,
                'selected_dependency_rows' => $selectedDependencyRows,
                'work_rows_before' => $workRowsBefore,
                'recovery_conditioned_rows' => $recoveryConditioned,
                'old_posting_counts' => $oldPostingCounts,
                'new_posting_counts' => $newPostingCounts,
                'later_event_posting_counts' => $laterEventPostingCounts,
                'old_hash_sha256' => wp_fts_wc_canonical_hash($oldHashes),
                'new_hash_sha256' => wp_fts_wc_canonical_hash($newHashes),
                'hash_changed' => $hashChanged,
                'later_event_hash_sha256' => wp_fts_wc_canonical_hash($laterEventHashes),
                'later_event_hash_changed' => $laterEventHashChanged,
                'later_event_work_rows_before' => $laterWorkRowsBefore,
                'later_event_recovery_conditioned_rows' => $laterRecoveryConditioned,
                'final_document_rows' => $fixtureDocumentRows,
            ],
            'cron' => [
                'event_absent_before_callback' => $noEventBefore,
                'successor_scheduled' => $successorScheduled,
                'later_event_scheduled' => $laterScheduled,
                'later_event_timestamp_before_callback' => $laterEventBefore,
                'later_event_timestamp_after_callback' => $laterEventAfter,
                'later_event_brought_forward' => is_int($laterEventBefore)
                    && is_int($laterEventAfter)
                    && $laterEventAfter < $laterEventBefore,
                'original_event_timestamp' => $cronBefore,
            ],
            'setup_batch' => $setupBatch,
            'first_composed_batch' => $firstBatch,
            'later_event_composed_batch' => $laterEventBatch,
            'path_batches' => $pathBatches,
            'max_total_statement_count' => max(array_column($pathBatches, 'total_statement_count') ?: [0]),
            'max_data_statement_count' => max(array_column($pathBatches, 'bounded_data_statement_count') ?: [0]),
            'max_scheduling_control_statement_count' => max(array_column($pathBatches, 'scheduling_control_statement_count') ?: [0]),
            'claim_source_snapshot' => [
                'statement_count' => count($claimSnapshotStatements),
                'statement_bytes' => $claimSnapshotStatements === [] ? 0 : strlen($claimSnapshotStatements[0]),
                'statement_sha256' => $claimSnapshotStatements === [] ? '' : hash('sha256', $claimSnapshotStatements[0]),
                'conditional_fallback_statement_count' => count($conditionalSourceStatements),
                'conditional_fallback_statement_bytes' => $conditionalSourceStatements === [] ? 0 : strlen($conditionalSourceStatements[0]),
                'conditional_fallback_statement_sha256' => $conditionalSourceStatements === [] ? '' : hash('sha256', $conditionalSourceStatements[0]),
                'bounded_two_statement_source_protocol' => $boundedSourceFallback,
                'later_event_statement_count' => count($laterClaimSnapshotStatements),
                'later_event_statement_bytes' => $laterClaimSnapshotStatements === [] ? 0 : strlen($laterClaimSnapshotStatements[0]),
                'later_event_statement_sha256' => $laterClaimSnapshotStatements === [] ? '' : hash('sha256', $laterClaimSnapshotStatements[0]),
                'later_event_conditional_fallback_statement_count' => count($laterConditionalSourceStatements),
                'later_event_conditional_fallback_statement_bytes' => $laterConditionalSourceStatements === [] ? 0 : strlen($laterConditionalSourceStatements[0]),
                'later_event_conditional_fallback_statement_sha256' => $laterConditionalSourceStatements === [] ? '' : hash('sha256', $laterConditionalSourceStatements[0]),
                'later_event_bounded_two_statement_source_protocol' => $laterBoundedSourceFallback,
            ],
            'required_roles' => $requiredRoles,
            'missing_roles' => $missingRoles,
            'replacement_resolve_counts' => $replacementResolveCounts,
            'lease_protocols' => $leaseProtocols,
            'transaction_protocols' => $transactionProtocols,
            'failures' => $pathFailures,
            'remaining' => $remaining,
            'cleanup' => $cleanup,
            'batches' => [$setupBatch, ...$pathBatches],
        ];
    } finally {
        if ($scopeJobKey !== '') {
            $wpdb->query($wpdb->prepare("DELETE FROM `{$work}` WHERE job_key=%s AND kind='scope'", $scopeJobKey));
        }
        if (!$cleaned && $postIds !== []) {
            wp_fts_wc_cleanup_dependency_lob_fixture($postIds, $documents, $postings, $work);
        }
        if (function_exists('wp_clear_scheduled_hook')) {
            wp_clear_scheduled_hook(WP_FTS_Plugin::CRON_HOOK);
        }
        if (
            is_int($cronBefore)
            && $cronBefore > 0
            && function_exists('wp_schedule_single_event')
        ) {
            wp_schedule_single_event(max(time() + 1, $cronBefore), WP_FTS_Plugin::CRON_HOOK);
        }
    }
}

/** Seed a post with only the controlled source field used by worker composition. */
function wp_fts_wc_insert_composed_worker_post(string $slug, string $content): int
{
    global $wpdb;

    $postId = wp_fts_wc_insert_dependency_lob_post('composed-' . $slug, $content);
    $updated = $wpdb->update(
        $wpdb->posts,
        ['post_title' => '', 'post_excerpt' => ''],
        ['ID' => $postId],
        ['%s', '%s'],
        ['%d']
    );
    wp_fts_wc_assert($updated !== false, "Could not normalize composed-worker post {$postId}.");

    return $postId;
}

/** Construct the exact maximum distinct-identity analyzer input. */
function wp_fts_wc_maximum_identity_source(string $prefix): string
{
    $tokens = [];
    for ($index = 0; $index < WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_TERMS; $index++) {
        $tokens[] = $prefix . str_pad((string) $index, 4, '0', STR_PAD_LEFT);
    }

    return '<p>' . implode(' ', $tokens) . '</p>';
}

/** Fill a near-limit source with invisible bytes while retaining one visible token. */
function wp_fts_wc_near_limit_comment_source(int $number): string
{
    $visible = '<p>wcnearvisible' . max(1, $number) . '</p>';
    $open = '<!--';
    $close = '-->';
    $bytes = 1900000;
    wp_fts_wc_assert(strlen($visible . $open . $close) < $bytes, 'Near-limit composed-worker source scaffold is invalid.');

    return $visible . $open . str_repeat('x', $bytes - strlen($visible . $open . $close)) . $close;
}

/** @param array<string,array<string,mixed>> $queueClaimPlans @return array<string,mixed> */
function wp_fts_wc_instrumented_worker_batch(
    string $source,
    array &$queueClaimPlans,
    bool $scheduled = false,
    string $scheduledEventState = 'without_preexisting_event',
    bool $retainStatements = false
): array
{
    global $wpdb;

    $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()');
    wp_fts_wc_assert($threadId > 0, 'Could not map the instrumented worker to Performance Schema.');
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d',
        $threadId
    ));
    $batchStarted = hrtime(true);
    $recorded = wp_fts_wc_record_queries($scheduled
        ? static fn() => WP_FTS_Plugin::process_scheduled_indexing()
        : static fn() => WP_FTS_Plugin::process_manual_index_batch([
            'source' => $source,
            'batch_size' => 100,
            'time_budget' => 300.0,
        ]));
    $batchDurationMs = wp_fts_wc_elapsed_ms($batchStarted);
    $summary = is_array($recorded['result']) ? $recorded['result'] : [];
    $queries = $recorded['queries'];
    $statementHashes = [];
    $statementBytes = [];
    foreach ($queries as $sql) {
        $statementHashes[] = hash('sha256', $sql);
        $statementBytes[] = strlen($sql);
    }
    $queryStartedMs = array_map('floatval', $recorded['query_started_ms']);
    $roles = wp_fts_wc_worker_statement_roles($queries);
    $ftsQueries = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_search_statement'));
    $schemaQueries = array_values(array_filter($queries, 'wp_fts_wc_is_physical_schema_statement'));
    $scopeIndexProbeCount = count(array_filter(
        $roles['roles'],
        static fn(string $role): bool => in_array($role, ['targeted_scope_index_probe', 'filtered_scope_index_probe'], true)
    ));
    foreach ($queries as $sql) {
        $claimKinds = wp_fts_wc_queue_claim_statement_kinds($sql);
        if ($claimKinds !== [] && array_diff($claimKinds, array_keys($queueClaimPlans)) !== []) {
            $plan = wp_fts_wc_explain_queue_claim($sql);
            foreach ($claimKinds as $claimKind) {
                $queueClaimPlans[$claimKind] ??= $plan;
            }
        }
    }
    $events = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID,SQL_TEXT,ROWS_EXAMINED,ROWS_SENT,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID>%d ORDER BY EVENT_ID',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $statementEvents = [];
    foreach ($events as $event) {
        $sql = (string) ($event['SQL_TEXT'] ?? '');
        if (
            $sql === ''
            || str_contains(strtolower($sql), 'performance_schema.')
        ) {
            continue;
        }
        $statementEvents[] = [
            'sql_sha256' => hash('sha256', $sql),
            'duration_ms' => max(0.0, (float) ($event['TIMER_WAIT'] ?? 0) / 1000000000.0),
            'rows_examined' => max(0, (int) ($event['ROWS_EXAMINED'] ?? 0)),
            'rows_sent' => max(0, (int) ($event['ROWS_SENT'] ?? 0)),
        ];
    }
    $databaseMs = array_sum(array_column($statementEvents, 'duration_ms'));

    $batch = [
        'statement_scope' => 'all_wpdb_including_transaction_control',
        'worker_mode' => $scheduled ? 'cron_' . $scheduledEventState : 'manual',
        'duration_ms' => $batchDurationMs,
        'attempted' => (int) ($summary['attempted'] ?? 0),
        'committed' => (int) ($summary['committed'] ?? 0),
        'queue_processed' => (int) ($summary['queue_processed'] ?? 0),
        'superseded' => (int) ($summary['superseded'] ?? 0),
        'indexed' => (int) ($summary['indexed'] ?? 0),
        'analyzed' => (int) ($summary['analyzed'] ?? 0),
        'unchanged' => (int) ($summary['unchanged'] ?? 0),
        'deleted' => (int) ($summary['deleted'] ?? 0),
        'permanently_rejected' => (int) ($summary['permanently_rejected'] ?? 0),
        'retryable_failures' => (int) ($summary['retryable_failures'] ?? 0),
        'deferred' => (int) ($summary['deferred'] ?? 0),
        'backfill_scanned' => (int) ($summary['backfill_scanned'] ?? 0),
        'backfill_queued' => (int) ($summary['backfill_queued'] ?? 0),
        'scope_page_committed' => !empty($summary['scope_page_committed']),
        'scope_completed' => !empty($summary['scope_completed']),
        'scope_completed_global' => !empty($summary['scope_completed_global']),
        'empty_terms_cleaned' => (int) ($summary['empty_terms_cleaned'] ?? 0),
        'wait_for_next_available' => !empty($summary['wait_for_next_available']),
        'next_available_at' => is_numeric($summary['next_available_at'] ?? null) ? (int) $summary['next_available_at'] : null,
        'has_more' => !empty($summary['has_more']),
        'stop_reason' => is_scalar($summary['stop_reason'] ?? null) ? (string) $summary['stop_reason'] : '',
        'total_statement_count' => count($queries),
        'fts_data_statement_count' => count($ftsQueries),
        'bounded_data_statement_count' => count($roles['data_roles']),
        'lease_control_statement_count' => count($roles['lease_control_roles']),
        'worker_transaction_control_statement_count' => count($roles['transaction_roles']),
        'scheduling_control_statement_count' => count($roles['scheduling_control_roles']),
        'unclassified_statement_count' => count($roles['unknown']),
        'statement_roles_ordered' => wp_fts_wc_worker_roles_are_ordered($roles['roles']),
        'statement_roles' => $roles['roles'],
        'unclassified_statements' => $roles['unknown'],
        'physical_schema_statement_count' => count($schemaQueries),
        'scope_index_probe_statement_count' => $scopeIndexProbeCount,
        'unexpected_physical_schema_statement_count' => max(0, count($schemaQueries) - $scopeIndexProbeCount),
        'transaction_control_statement_count' => count($roles['transaction_roles']),
        'statement_started_ms' => $queryStartedMs,
        'performance_schema_statement_count' => count($statementEvents),
        'performance_schema_statements' => $statementEvents,
        'database_statement_ms' => $databaseMs,
        'non_database_ms' => max(0.0, $batchDurationMs - $databaseMs),
        'max_statement_bytes' => $statementBytes === [] ? 0 : max($statementBytes),
        'statement_sha256' => $statementHashes,
        'statement_bytes' => $statementBytes,
        'failures' => (int) ($summary['last_batch_failures'] ?? 0),
        'error_class' => is_scalar($summary['error_class'] ?? null) ? (string) $summary['error_class'] : '',
        'error_message' => is_scalar($summary['error_message'] ?? null) ? (string) $summary['error_message'] : '',
        'lock_before' => is_array($summary['lock_before'] ?? null) ? $summary['lock_before'] : [],
        'resolved_failure_records' => !empty($summary['resolved_failure_records']),
        'skipped_locked' => !empty($summary['skipped_locked']),
    ];
    if ($retainStatements) {
        $batch['statements'] = $queries;
    }

    return $batch;
}

/** A worker pass advances either an acknowledged generation or one scope page. */
function wp_fts_wc_worker_made_progress(array $summary): bool
{
    foreach (['queue_processed', 'committed', 'backfill_queued', 'empty_terms_cleaned'] as $field) {
        if (max(0, (int) ($summary[$field] ?? 0)) > 0) {
            return true;
        }
    }

    return !empty($summary['scope_page_committed']) || !empty($summary['scope_completed']);
}

/** Sleep to the worker's durable retry time, or reject an unexplained stall. */
function wp_fts_wc_wait_after_worker_no_progress(
    array $summary,
    float $deadline,
    string $context,
    int &$consecutiveNoProgress
): void {
    if (wp_fts_wc_worker_made_progress($summary)) {
        $consecutiveNoProgress = 0;
        return;
    }

    $consecutiveNoProgress++;
    if ($consecutiveNoProgress > 3) {
        throw new RuntimeException("{$context} exceeded three consecutive bounded no-progress worker passes.");
    }
    if (max((int) ($summary['last_batch_failures'] ?? 0), (int) ($summary['failures'] ?? 0)) > 0
        || !empty($summary['error_class'])
        || !empty($summary['error_message'])
    ) {
        throw new RuntimeException("{$context} stopped on a worker failure instead of making durable progress.");
    }

    $delaySeconds = null;
    if (!empty($summary['wait_for_next_available'])) {
        $nextAvailableAt = $summary['next_available_at'] ?? null;
        if (!is_numeric($nextAvailableAt)) {
            throw new RuntimeException("{$context} requested a future retry without an exact availability time.");
        }
        $delaySeconds = max(1, (int) $nextAvailableAt - time() + 1);
    } elseif (!empty($summary['skipped_locked'])) {
        $expiresIn = $summary['lock_before']['expires_in_seconds'] ?? null;
        $delaySeconds = is_numeric($expiresIn) ? max(1, (int) $expiresIn + 1) : 1;
    } elseif (in_array((string) ($summary['stop_reason'] ?? ''), ['stale_writer_lease_recovered', 'profile_reconciliation_restarted'], true)) {
        $delaySeconds = 1;
    }
    if ($delaySeconds === null) {
        throw new RuntimeException("{$context} left work pending without progress or a bounded retry reason.");
    }

    $remainingSeconds = $deadline - microtime(true);
    if ($remainingSeconds <= 0.0) {
        throw new RuntimeException("{$context} reached its deadline before the next bounded retry.");
    }
    sleep(min($delaySeconds, max(1, (int) ceil($remainingSeconds))));
}

/** @param int[] $postIds @return array<int,string> */
function wp_fts_wc_document_hashes(string $documents, array $postIds): array
{
    global $wpdb;

    $postIds = array_values(array_unique(array_filter(array_map('intval', $postIds), static fn(int $postId): bool => $postId > 0)));
    if ($postIds === []) {
        return [];
    }
    $placeholders = implode(',', array_fill(0, count($postIds), '%d'));
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT post_id,content_hash FROM `{$documents}` WHERE post_id IN ({$placeholders}) ORDER BY post_id ASC",
        ...$postIds
    ), ARRAY_A) ?: [];
    $hashes = [];
    foreach ($rows as $row) {
        $postId = (int) ($row['post_id'] ?? 0);
        $hash = is_scalar($row['content_hash'] ?? null) ? (string) $row['content_hash'] : '';
        if ($postId > 0 && $hash !== '') {
            $hashes[$postId] = $hash;
        }
    }
    ksort($hashes, SORT_NUMERIC);

    return $hashes;
}

/** @return string[] */
function wp_fts_wc_queue_claim_statement_kinds(string $sql): array
{
    if (!str_contains(strtolower($sql), 'wp_fts:claim-batch')) {
        return [];
    }

    $kinds = [];
    $window = [];
    foreach (wp_fts_wc_sql_token_stream($sql, true) as $token) {
        $window[] = $token;
        if (count($window) > 3) {
            array_shift($window);
        }
        if (
            count($window) === 3
            && in_array($window[0]['type'] ?? null, ['word', 'identifier'], true)
            && ($window[0]['value'] ?? null) === 'kind'
            && ($window[1]['type'] ?? null) === 'symbol'
            && ($window[1]['value'] ?? null) === '='
            && ($window[2]['type'] ?? null) === 'string'
            && in_array($window[2]['value'] ?? null, ['scope', 'post'], true)
        ) {
            $kinds[(string) $window[2]['value']] = true;
        }
    }

    return array_keys($kinds);
}

/** @return array{sql:string,plan:array<string,mixed>,work_table_access:array<int,array<string,mixed>>,uses_full_scan:bool,uses_index:bool} */
function wp_fts_wc_explain_queue_claim(string $sql): array
{
    global $wpdb;

    $json = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
    wp_fts_wc_assert(is_string($json) && $json !== '', 'Queue claim EXPLAIN FORMAT=JSON returned no plan.');
    $plan = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(is_array($plan), 'Queue claim EXPLAIN JSON is not an object.');
    $access = [];
    wp_fts_wc_collect_work_table_access($plan, $access);
    wp_fts_wc_assert($access !== [], 'Queue claim EXPLAIN did not expose the production work table.');
    $usesFullScan = count(array_filter($access, static fn(array $row): bool => strtoupper((string) ($row['access_type'] ?? '')) === 'ALL')) > 0;
    $usesIndex = count(array_filter($access, static fn(array $row): bool => is_string($row['key'] ?? null) && (string) $row['key'] !== '')) > 0;

    return [
        'sql' => $sql,
        'plan' => $plan,
        'work_table_access' => $access,
        'uses_full_scan' => $usesFullScan,
        'uses_index' => $usesIndex,
    ];
}

/**
 * @param array<string|int,mixed> $node
 * @param array<int,array<string,mixed>> $access
 */
function wp_fts_wc_collect_work_table_access(array $node, array &$access): void
{
    $tableAccess = [];
    wp_fts_wc_collect_database_table_access($node, $tableAccess);
    foreach ($tableAccess as $row) {
        // MySQL may name a bounded derived container chosen_fts_work; only its
        // non-materialized leaves represent physical queue-table access.
        if (!empty($row['materialized']) || !str_ends_with(strtolower((string) ($row['table_name'] ?? '')), 'fts_work')) {
            continue;
        }
        $access[] = [
            'table_name' => (string) $row['table_name'],
            'access_type' => (string) $row['access_type'],
            'possible_keys' => $row['possible_keys'],
            'key' => (string) $row['key'],
            'rows' => $row['rows'],
        ];
    }
}

/**
 * Merge independently written concurrency evidence and make the final process
 * exit non-zero when any gate failed.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_finalize(): array
{
    global $wpdb;

    wp_fts_wc_assert_disposable_guard();
    wp_fts_wc_assert_runtime();
    wp_fts_wc_assert_source_binding();
    wp_fts_wc_require_plugin();
    $evidence = wp_fts_wc_read_json(wp_fts_wc_evidence_path());
    if (($evidence['schema'] ?? null) !== WP_FTS_WC_EVIDENCE_SCHEMA) {
        throw new RuntimeException('Validation evidence is missing or has the wrong schema.');
    }
    if (($evidence['completed'] ?? null) !== false) {
        throw new RuntimeException('Finalization requires the incomplete validation artifact, not a stale completed report.');
    }
    $recordedPreliminaryHash = $evidence['evidence_sha256'] ?? null;
    $preliminaryHashInput = $evidence;
    unset($preliminaryHashInput['evidence_sha256']);
    $calculatedPreliminaryHash = wp_fts_wc_canonical_hash($preliminaryHashInput);
    if (
        !wp_fts_wc_is_lowercase_sha256($recordedPreliminaryHash)
        || !hash_equals($calculatedPreliminaryHash, (string) $recordedPreliminaryHash)
    ) {
        throw new RuntimeException('Validation evidence self-hash is missing or invalid.');
    }
    if (!wp_fts_wc_validation_inventory_matches($evidence)) {
        throw new RuntimeException('Validation evidence does not match the canonical gate/case/section inventory.');
    }
    $validationInventory = is_array($evidence['validation_inventory'] ?? null) ? $evidence['validation_inventory'] : [];
    wp_fts_wc_require_evidence_gates(
        $evidence,
        'validation',
        is_array($validationInventory['gate_ids'] ?? null) ? array_values($validationInventory['gate_ids']) : [],
        WP_FTS_WC_EVIDENCE_SCHEMA
    );
    $externalEvidence = wp_fts_wc_final_external_evidence($evidence);
    $authoritativeSearchMemory = wp_fts_wc_collect_authoritative_search_memory($evidence);

    $concurrencySeconds = wp_fts_wc_required_positive_int_env('WP_FTS_WC_CONCURRENCY_SECONDS');
    $concurrencyProfile = wp_fts_wc_required_env('WP_FTS_WC_PROFILE');
    $concurrencyEngine = strtolower(wp_fts_wc_required_env('WP_FTS_WC_ENGINE'));
    $concurrencyEngineFamily = match (true) {
        str_contains($concurrencyEngine, 'mariadb') => 'mariadb',
        str_contains($concurrencyEngine, 'mysql') => 'mysql',
        default => throw new RuntimeException("Unsupported worst-case database engine: {$concurrencyEngine}"),
    };
    [$concurrentP95Limit, $concurrentP99Limit] = match ([$concurrencyProfile, $concurrencyEngineFamily]) {
        ['50k', 'mysql'] => [10000.0, 15000.0],
        ['50k', 'mariadb'] => [25000.0, 35000.0],
        ['100k', 'mysql'] => [40000.0, 60000.0],
        ['100k', 'mariadb'] => [90000.0, 120000.0],
        default => [1000.0, 1500.0],
    };
    $baseline = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/concurrency-baseline.json');
    $readerHarnessHash = wp_fts_wc_required_env('WP_FTS_WC_CONCURRENT_READER_SHA256');
    $expectedCaseIds = array_values(array_unique(wp_fts_wc_concurrency_mix()));
    $actualCaseIds = is_array($baseline['cases'] ?? null) ? array_keys($baseline['cases']) : [];
    sort($expectedCaseIds, SORT_STRING);
    sort($actualCaseIds, SORT_STRING);
    $baselineCasesValid = $actualCaseIds === $expectedCaseIds;
    foreach (is_array($baseline['cases'] ?? null) ? $baseline['cases'] : [] as $caseId => $case) {
        $ids = is_array($case['ids'] ?? null) ? $case['ids'] : [];
        $hash = is_string($case['hash'] ?? null) ? (string) $case['hash'] : '';
        $requestUrl = is_string($case['request_url'] ?? null) ? (string) $case['request_url'] : '';
        $requestUrlParts = parse_url($requestUrl);
        $oracle = is_array($case['oracle'] ?? null) ? $case['oracle'] : [];
        $baselineCasesValid = $baselineCasesValid
            && in_array($caseId, $expectedCaseIds, true)
            && is_int($case['count'] ?? null)
            && (int) $case['count'] > 0
            && count($ids) === (int) $case['count']
            && count(array_filter($ids, 'is_int')) === count($ids)
            && count(array_unique($ids)) === count($ids)
            && strlen($hash) === 64
            && wp_fts_wc_is_ascii_hex($hash)
            && is_array($requestUrlParts)
            && ($requestUrlParts['scheme'] ?? null) === 'http'
            && ($requestUrlParts['host'] ?? null) === 'wordpress'
            && !isset($requestUrlParts['user'])
            && !isset($requestUrlParts['pass'])
            && (!isset($requestUrlParts['port']) || $requestUrlParts['port'] === 80)
            && ($oracle['source'] ?? null) === 'direct-set-oriented-searcher'
            && ($oracle['count'] ?? null) === ($case['count'] ?? null)
            && ($oracle['ids'] ?? null) === $ids
            && ($oracle['hash'] ?? null) === $hash;
    }
    $writerAssignments = is_array($baseline['writer_post_ids'] ?? null) ? $baseline['writer_post_ids'] : [];
    $flatWriterIds = [];
    $writerAssignmentsValid = count($writerAssignments) === 2;
    foreach ($writerAssignments as $assignment) {
        $writerAssignmentsValid = $writerAssignmentsValid
            && is_array($assignment)
            && count($assignment) === 20
            && count(array_filter($assignment, 'is_int')) === 20
            && count(array_unique($assignment)) === 20;
        if (is_array($assignment)) {
            array_push($flatWriterIds, ...$assignment);
        }
    }
    $writerAssignmentsValid = $writerAssignmentsValid
        && count($flatWriterIds) === 40
        && count(array_unique($flatWriterIds)) === 40
        && count(array_filter($flatWriterIds, static fn(mixed $id): bool => is_int($id) && $id > 0)) === 40;
    $concurrentGates = [
        wp_fts_wc_gate(
            'concurrency_baseline_artifact',
            'complete PASS concurrency baseline',
            [$baseline['schema'] ?? null, $baseline['status'] ?? null, $baseline['phase'] ?? null],
            ($baseline['schema'] ?? null) === 'relational-fts-concurrency-baseline-v5'
                && ($baseline['status'] ?? null) === 'PASS'
                && ($baseline['phase'] ?? null) === 'concurrency-setup'
                && is_string($baseline['concurrency_run_id'] ?? null)
                && strlen((string) $baseline['concurrency_run_id']) === 32
                && wp_fts_wc_is_ascii_hex((string) $baseline['concurrency_run_id'])
                && ($baseline['reader_harness_sha256'] ?? null) === $readerHarnessHash
                && wp_fts_wc_is_lowercase_sha256($readerHarnessHash)
        ),
        wp_fts_wc_gate('concurrency_baseline_work_drained', 0, $baseline['remaining_work'] ?? null, ($baseline['remaining_work'] ?? null) === 0),
        wp_fts_wc_gate('concurrency_baseline_case_oracles', $expectedCaseIds, $actualCaseIds, $baselineCasesValid),
        wp_fts_wc_gate('concurrency_writer_assignments', 'two disjoint 20-post sets', $writerAssignments, $writerAssignmentsValid),
    ];

    $durations = [];
    $errors = [];
    $readerRequests = 0;
    $readerHttpAttempts = 0;
    $readerUnavailableRetries = 0;
    $readerPeaks = [];
    $readerEvidence = [];
    $concurrencyStarts = [];
    $concurrencyFinishes = [];
    $sharedWindowIdentity = null;
    for ($worker = 0; $worker < 8; $worker++) {
        $path = wp_fts_wc_evidence_dir() . "/concurrent-reader-{$worker}.json";
        $reader = wp_fts_wc_read_json($path);
        $readerEvidence[$worker] = $reader;
        $samples = is_array($reader['samples'] ?? null) ? array_values($reader['samples']) : [];
        $readerErrors = is_array($reader['errors'] ?? null) ? array_values($reader['errors']) : [];
        $requests = (int) ($reader['requests'] ?? -1);
        $httpAttempts = (int) ($reader['http_attempts'] ?? -1);
        $unavailableRetries = (int) ($reader['unavailable_retries'] ?? -1);
        $readerRequests += max(0, $requests);
        $readerHttpAttempts += max(0, $httpAttempts);
        $readerUnavailableRetries += max(0, $unavailableRetries);
        $readerPeaks[] = (int) ($reader['rss_peak_bytes'] ?? 0);
        $samplesValid = count($samples) + count($readerErrors) === $requests;
        $sampleHttpAttempts = 0;
        $sampleUnavailableRetries = 0;
        foreach ($samples as $sample) {
            if (is_array($sample) && is_numeric($sample['duration_ms'] ?? null)) {
                $durations[] = (float) $sample['duration_ms'];
            }
            $caseId = is_array($sample) && is_string($sample['case'] ?? null) ? (string) $sample['case'] : '';
            $sampleAttempts = is_array($sample) ? ($sample['attempts'] ?? null) : null;
            $sampleRetries = is_array($sample) ? ($sample['unavailable_retries'] ?? null) : null;
            $sampleHttpAttempts += is_int($sampleAttempts) ? $sampleAttempts : 0;
            $sampleUnavailableRetries += is_int($sampleRetries) ? $sampleRetries : 0;
            $samplesValid = $samplesValid
                && is_array($sample)
                && in_array($caseId, $expectedCaseIds, true)
                && is_numeric($sample['duration_ms'] ?? null)
                && (float) $sample['duration_ms'] >= 0.0
                && is_int($sample['count'] ?? null)
                && (int) $sample['count'] > 0
                && is_string($sample['hash'] ?? null)
                && ($sample['hash'] ?? null) === ($baseline['cases'][$caseId]['hash'] ?? null)
                && is_int($sampleAttempts)
                && $sampleAttempts >= 1
                && $sampleAttempts <= 4
                && is_int($sampleRetries)
                && $sampleRetries >= 0
                && $sampleRetries <= 3
                && $sampleAttempts === $sampleRetries + 1;
        }
        foreach ($readerErrors as $error) {
            $errors[] = $error;
        }
        $readerWindow = is_array($reader['shared_window'] ?? null) ? $reader['shared_window'] : [];
        $windowIdentity = [
            $readerWindow['run_id'] ?? null,
            $readerWindow['start_monotonic_ns'] ?? null,
            $readerWindow['deadline_monotonic_ns'] ?? null,
            $readerWindow['minimum_overlap_seconds'] ?? null,
        ];
        $sharedWindowIdentity ??= $windowIdentity;
        $startNs = (int) ($reader['started_monotonic_ns'] ?? 0);
        $finishNs = (int) ($reader['finished_monotonic_ns'] ?? 0);
        $concurrencyStarts[] = $startNs;
        $concurrencyFinishes[] = $finishNs;
        $readerShape = ($reader['schema'] ?? null) === 'relational-fts-concurrent-reader-v3'
            && ($reader['status'] ?? null) === 'PASS'
            && ($reader['phase'] ?? null) === 'concurrent-reader'
            && ($reader['worker'] ?? null) === $worker
            && ($reader['harness_sha256'] ?? null) === $readerHarnessHash
            && is_int($reader['requests'] ?? null)
            && $requests > 0
            && is_int($reader['http_attempts'] ?? null)
            && $httpAttempts === $sampleHttpAttempts
            && is_int($reader['unavailable_retries'] ?? null)
            && $unavailableRetries === $sampleUnavailableRetries
            && $httpAttempts === $requests + $unavailableRetries
            && is_array($reader['samples'] ?? null)
            && is_array($reader['errors'] ?? null)
            && $samplesValid
            && $windowIdentity === $sharedWindowIdentity
            && $startNs >= (int) ($readerWindow['start_monotonic_ns'] ?? PHP_INT_MAX)
            && $finishNs >= $startNs
            && is_numeric($reader['measured_overlap_seconds'] ?? null)
            && (float) $reader['measured_overlap_seconds'] >= $concurrencySeconds;
        $concurrentGates[] = wp_fts_wc_gate("concurrent_reader_{$worker}_artifact", 'complete PASS reader artifact', [$reader['schema'] ?? null, $reader['status'] ?? null, $reader['phase'] ?? null, $reader['worker'] ?? null, $requests], $readerShape);
        $concurrentGates[] = wp_fts_wc_gate("concurrent_reader_{$worker}_overlap_seconds", ">= {$concurrencySeconds}", $reader['measured_overlap_seconds'] ?? null, is_numeric($reader['measured_overlap_seconds'] ?? null) && (float) $reader['measured_overlap_seconds'] >= $concurrencySeconds);
    }

    $writerIndexed = 0;
    $writerFailures = 0;
    $writerDeadlockRetries = 0;
    $writerMutations = 0;
    $writerPeaks = [];
    $writerEvidence = [];
    $writerCount = 2;
    $writerDeadlockRetryLimitPerWriter = 8;
    for ($worker = 0; $worker < $writerCount; $worker++) {
        $writer = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . "/concurrent-writer-{$worker}.json");
        $writerEvidence[$worker] = $writer;
        $rawBatches = is_array($writer['batches'] ?? null) ? array_values($writer['batches']) : [];
        $batches = array_values(array_filter($rawBatches, 'is_array'));
        $batchIndexed = array_sum(array_map(static fn(array $batch): int => (int) ($batch['indexed'] ?? 0), $batches));
        $batchFailures = array_sum(array_map(static fn(array $batch): int => (int) ($batch['failures'] ?? 0), $batches));
        $batchDeadlockRetries = count(array_filter($batches, static fn(array $batch): bool => !empty($batch['deadlock_retry'])));
        $batchMutations = count(array_filter($batches, static fn(array $batch): bool => (int) ($batch['queued'] ?? 0) === 20));
        $writerIndexed += (int) ($writer['indexed'] ?? 0);
        $writerFailures += (int) ($writer['failures'] ?? 0);
        $writerDeadlockRetries += (int) ($writer['deadlock_retries'] ?? 0);
        $writerMutations += (int) ($writer['mutations'] ?? 0);
        $writerPeaks[] = (int) ($writer['rss_peak_bytes'] ?? 0);
        $batchesValid = $rawBatches !== [] && count($rawBatches) === count($batches);
        foreach ($batches as $batch) {
            $batchError = is_string($batch['error'] ?? null) ? (string) $batch['error'] : '';
            $batchDatabaseError = is_string($batch['database_error'] ?? null) ? (string) $batch['database_error'] : '';
            $recordedDeadlockRetry = $batch['deadlock_retry'] ?? null;
            $recognizedDeadlockRetry = str_contains($batchError, 'Deadlock found when trying to get lock')
                || ($batchError === 'Could not acquire the FTS index writer lease.'
                    && str_contains($batchDatabaseError, 'Deadlock found when trying to get lock'));
            $batchesValid = $batchesValid
                && is_numeric($batch['duration_ms'] ?? null)
                && (float) $batch['duration_ms'] >= 0.0
                && is_int($batch['indexed'] ?? null)
                && (int) $batch['indexed'] >= 0
                && is_int($batch['failures'] ?? null)
                && (int) $batch['failures'] >= 0
                && is_bool($recordedDeadlockRetry)
                && $recordedDeadlockRetry === $recognizedDeadlockRetry
                && is_int($batch['queued'] ?? null)
                && in_array($batch['queued'], [0, 20], true);
        }
        $writerWindow = is_array($writer['shared_window'] ?? null) ? $writer['shared_window'] : [];
        $windowIdentity = [
            $writerWindow['run_id'] ?? null,
            $writerWindow['start_monotonic_ns'] ?? null,
            $writerWindow['deadline_monotonic_ns'] ?? null,
            $writerWindow['minimum_overlap_seconds'] ?? null,
        ];
        $sharedWindowIdentity ??= $windowIdentity;
        $startNs = (int) ($writer['started_monotonic_ns'] ?? 0);
        $finishNs = (int) ($writer['finished_monotonic_ns'] ?? 0);
        $concurrencyStarts[] = $startNs;
        $concurrencyFinishes[] = $finishNs;
        $assignedIds = is_array($writer['assigned_post_ids'] ?? null) ? array_values(array_map('intval', $writer['assigned_post_ids'])) : [];
        $finalExcerpt = is_string($writer['final_excerpt'] ?? null) ? (string) $writer['final_excerpt'] : '';
        $parityRows = [];
        if (count($assignedIds) === 20) {
            $placeholders = implode(',', array_fill(0, count($assignedIds), '%d'));
            $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
            $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
            $parityRows = $wpdb->get_results($wpdb->prepare(
                "SELECT p.ID FROM {$wpdb->posts} p JOIN `{$documents}` d ON d.post_id=p.ID LEFT JOIN `{$work}` w ON w.kind='post' AND w.post_id=p.ID WHERE p.ID IN ({$placeholders}) AND p.post_excerpt=%s AND d.indexed_at>=UNIX_TIMESTAMP(p.post_modified_gmt) AND w.job_key IS NULL",
                ...[...$assignedIds, $finalExcerpt]
            ), ARRAY_A) ?: [];
        }
        $writerShape = ($writer['schema'] ?? null) === 'relational-fts-concurrent-writer-v3'
            && ($writer['status'] ?? null) === 'PASS'
            && ($writer['phase'] ?? null) === 'concurrent-writer'
            && ($writer['worker'] ?? null) === $worker
            && $batchesValid
            && ($writer['indexed'] ?? null) === $batchIndexed
            && ($writer['failures'] ?? null) === $batchFailures
            && ($writer['deadlock_retries'] ?? null) === $batchDeadlockRetries
            && $batchDeadlockRetries <= $writerDeadlockRetryLimitPerWriter
            && ($writer['mutations'] ?? null) === $batchMutations
            && $batchMutations > 0
            && $windowIdentity === $sharedWindowIdentity
            && $startNs >= (int) ($writerWindow['start_monotonic_ns'] ?? PHP_INT_MAX)
            && $finishNs >= $startNs
            && is_numeric($writer['measured_overlap_seconds'] ?? null)
            && (float) $writer['measured_overlap_seconds'] >= $concurrencySeconds;
        $concurrentGates[] = wp_fts_wc_gate("concurrent_writer_{$worker}_artifact", 'complete PASS writer artifact', [$writer['schema'] ?? null, $writer['status'] ?? null, $writer['phase'] ?? null, $writer['worker'] ?? null, count($rawBatches)], $writerShape);
        $concurrentGates[] = wp_fts_wc_gate("concurrent_writer_{$worker}_overlap_seconds", ">= {$concurrencySeconds}", $writer['measured_overlap_seconds'] ?? null, is_numeric($writer['measured_overlap_seconds'] ?? null) && (float) $writer['measured_overlap_seconds'] >= $concurrencySeconds);
        $concurrentGates[] = wp_fts_wc_gate("concurrent_writer_{$worker}_independent_progress", ['indexed' => '> 0', 'lease_acquired_batches' => '> 0'], ['indexed' => $writer['indexed'] ?? null, 'lease_acquired_batches' => $writer['lease_acquired_batches'] ?? null], (int) ($writer['indexed'] ?? 0) > 0 && (int) ($writer['lease_acquired_batches'] ?? 0) > 0);
        $concurrentGates[] = wp_fts_wc_gate("concurrent_writer_{$worker}_final_index_parity", 20, count($parityRows), count($parityRows) === 20);
    }

    $latency = wp_fts_wc_distribution($durations);
    $measuredIntersectionSeconds = $concurrencyStarts !== [] && $concurrencyFinishes !== []
        ? max(0.0, (min($concurrencyFinishes) - max($concurrencyStarts)) / 1000000000)
        : 0.0;
    $idle = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/idle-http.json');
    $idleLatency = is_array($idle['latency_ms'] ?? null) ? $idle['latency_ms'] : [];
    $idleP95 = (float) ($idleLatency['p95'] ?? INF);
    $degradation = $idleP95 > 0.0 && is_finite($idleP95) ? $latency['p95'] / $idleP95 : INF;
    $writerDeadlockRetryLimit = $writerCount * $writerDeadlockRetryLimitPerWriter;
    $concurrency = [
        'transport' => 'http-rest',
        'duration_seconds' => $concurrencySeconds,
        'readers' => 8,
        'writers' => $writerCount,
        'requests' => $readerRequests,
        'http_attempts' => $readerHttpAttempts,
        'unavailable_retries' => $readerUnavailableRetries,
        'errors' => $errors,
        'latency_ms' => $latency,
        'writer_indexed' => $writerIndexed,
        'writer_failures' => $writerFailures,
        'writer_deadlock_retries' => $writerDeadlockRetries,
        'writer_mutations' => $writerMutations,
        'reader_rss_peak_bytes' => max($readerPeaks ?: [0]),
        'writer_rss_peak_bytes' => max($writerPeaks ?: [0]),
        'idle_http_p95_ms' => $idleP95,
        'p95_degradation_ratio' => $degradation,
        'shared_window_identity' => $sharedWindowIdentity,
        'measured_all_worker_intersection_seconds' => $measuredIntersectionSeconds,
        'baseline' => $baseline,
        'reader_artifacts' => $readerEvidence,
        'writer_artifacts' => $writerEvidence,
    ];

    array_push(
        $concurrentGates,
        wp_fts_wc_gate('concurrent_requests', '> 0', $readerRequests, $readerRequests > 0),
        wp_fts_wc_gate('concurrent_http_attempts', 'requests plus bounded publication retries', $readerHttpAttempts, $readerHttpAttempts === $readerRequests + $readerUnavailableRetries),
        wp_fts_wc_gate('concurrent_unavailable_retries', "<= {$readerRequests}", $readerUnavailableRetries, $readerUnavailableRetries <= $readerRequests),
        wp_fts_wc_gate('concurrent_errors', 0, count($errors), $errors === []),
        wp_fts_wc_gate(
            'concurrent_writer_failures',
            ['terminal' => 0, 'deadlock_retries' => "<= {$writerDeadlockRetryLimit}"],
            ['terminal' => $writerFailures, 'deadlock_retries' => $writerDeadlockRetries],
            $writerFailures === 0 && $writerDeadlockRetries <= $writerDeadlockRetryLimit
        ),
        wp_fts_wc_gate('concurrent_writer_progress', '> 0', $writerIndexed, $writerIndexed > 0),
        wp_fts_wc_gate('concurrent_shared_window_identity', 'one exact run/start/deadline/minimum tuple', $sharedWindowIdentity, is_array($sharedWindowIdentity) && ($sharedWindowIdentity[0] ?? null) === ($baseline['concurrency_run_id'] ?? null)),
        wp_fts_wc_gate('concurrent_all_worker_intersection_seconds', ">= {$concurrencySeconds}", $measuredIntersectionSeconds, $measuredIntersectionSeconds >= $concurrencySeconds),
        wp_fts_wc_gate('concurrent_p95_ms', "<= {$concurrentP95Limit}", $latency['p95'], $latency['p95'] <= $concurrentP95Limit),
