        wp_fts_wc_gate('old_posting_frontier_remaining_terms', 0, $frontierEventual['remaining_terms'] ?? null, ($frontierEventual['remaining_terms'] ?? null) === 0),
        wp_fts_wc_gate('old_posting_frontier_preserved_decoy_postings', 100000, $frontierEventual['preserved_decoy_postings'] ?? null, ($frontierEventual['preserved_decoy_postings'] ?? null) === 100000),
        wp_fts_wc_gate('old_posting_frontier_preserved_decoy_terms', 1, $frontierEventual['preserved_decoy_terms'] ?? null, ($frontierEventual['preserved_decoy_terms'] ?? null) === 1),
        wp_fts_wc_gate('old_posting_frontier_bad_doc_freqs', 0, $frontierEventual['bad_document_frequencies'] ?? null, ($frontierEventual['bad_document_frequencies'] ?? null) === 0),
        wp_fts_wc_gate(
            'old_posting_frontier_covering_index',
            ['range', 'post_term', true],
            [$frontierPlanAccess['access_type'] ?? null, $frontierPlanAccess['key'] ?? null, $frontierPlanAccess['using_index'] ?? null],
            ($frontierPlanAccess['access_type'] ?? null) === 'range'
                && ($frontierPlanAccess['key'] ?? null) === 'post_term'
                && ($frontierPlanAccess['using_index'] ?? null) === true
        ),
        wp_fts_wc_gate('old_posting_frontier_inner_plan', ['filesort' => false, 'temporary_table' => false], ['filesort' => $frontierPlan['inner_uses_filesort'] ?? null, 'temporary_table' => $frontierPlan['inner_uses_temporary_table'] ?? null], ($frontierPlan['inner_uses_filesort'] ?? null) === false && ($frontierPlan['inner_uses_temporary_table'] ?? null) === false),
        wp_fts_wc_gate(
            'old_posting_frontier_plan_hash',
            'raw JSON and inner block bound to lowercase sha256',
            [$frontierPlan['sha256'] ?? null, $frontierPlan['inner_query_block_sha256'] ?? null],
            wp_fts_wc_is_lowercase_sha256($frontierPlan['sha256'] ?? null)
                && wp_fts_wc_is_lowercase_sha256($frontierPlan['inner_query_block_sha256'] ?? null)
                && is_string($frontierPlan['raw_json'] ?? null)
                && hash_equals(hash('sha256', (string) $frontierPlan['raw_json']), (string) ($frontierPlan['sha256'] ?? ''))
        ),
        wp_fts_wc_gate(
            'old_posting_frontier_cleanup',
            [4, 4, [], [], true],
            [$frontierCleanup['requested_tables'] ?? null, $frontierCleanup['drop_statements'] ?? null, $frontierCleanup['drop_failures'] ?? null, $frontierCleanup['remaining_tables'] ?? null, $frontierCleanup['verified_absent'] ?? null],
            ($frontierCleanup['requested_tables'] ?? null) === 4
                && ($frontierCleanup['drop_statements'] ?? null) === 4
                && ($frontierCleanup['drop_failures'] ?? null) === []
                && ($frontierCleanup['remaining_tables'] ?? null) === []
                && ($frontierCleanup['verified_absent'] ?? null) === true
        ),
        wp_fts_wc_gate(
            'old_posting_reset_populated_fixture',
            [157344, 57345, 28673, 28672, 7, 2, 1],
            [$frontierResetFixture['postings'] ?? null, $frontierResetFixture['terms'] ?? null, $frontierResetFixture['lexical_terms'] ?? null, $frontierResetFixture['surface_terms'] ?? null, $frontierResetFixture['documents'] ?? null, $frontierResetFixture['work_rows'] ?? null, $frontierResetFixture['non_epoch_work_rows'] ?? null],
            ($frontierResetFixture['postings'] ?? null) === 157344
                && ($frontierResetFixture['terms'] ?? null) === 57345
                && ($frontierResetFixture['lexical_terms'] ?? null) === 28673
                && ($frontierResetFixture['surface_terms'] ?? null) === 28672
                && ($frontierResetFixture['documents'] ?? null) === 7
                && ($frontierResetFixture['work_rows'] ?? null) === 2
                && ($frontierResetFixture['non_epoch_work_rows'] ?? null) === 1
                && is_int($frontierResetFixture['search_epoch'] ?? null)
                && $frontierResetFixture['search_epoch'] > 0
                && wp_fts_wc_is_search_epoch_incarnation($frontierResetFixture['search_epoch_incarnation'] ?? null)
        ),
        wp_fts_wc_gate(
            'old_posting_reset_summary',
            'atomic swap and epoch + 1',
            $frontierResetSummary,
            ($frontierResetSummary['reset_strategy'] ?? null) === 'mysql_atomic_table_swap'
                && ($frontierResetSummary['search_epoch'] ?? null) === ($frontierResetFixture['search_epoch'] ?? -1) + 1
        ),
        wp_fts_wc_gate('old_posting_reset_storage_statements', 'nine exact source-asserted storage statements with hashes; no DELETE/COUNT', count($frontierResetStatements), $frontierResetStatementsValid && ($frontierReset['statement_count'] ?? null) === 9 && ($frontierReset['statement_methods'] ?? null) === $expectedResetMethods && ($frontierReset['exact_sql_shape'] ?? null) === true && ($frontierReset['contains_delete_or_count'] ?? null) === false && ($frontierReset['max_statement_bytes'] ?? PHP_INT_MAX) <= 4096),
        wp_fts_wc_gate('old_posting_reset_guard_calls', 3, $frontierReset['guard_calls'] ?? null, ($frontierReset['guard_calls'] ?? null) === 3),
        wp_fts_wc_gate('old_posting_reset_latency', '<= 5000 ms', $frontierReset['elapsed_ms'] ?? null, is_numeric($frontierReset['elapsed_ms'] ?? null) && (float) $frontierReset['elapsed_ms'] >= 0.0 && (float) $frontierReset['elapsed_ms'] <= 5000.0),
        wp_fts_wc_gate('old_posting_reset_php_allocation', '<= 16777216', $frontierReset['php_allocation_delta_bytes'] ?? null, is_int($frontierReset['php_allocation_delta_bytes'] ?? null) && $frontierReset['php_allocation_delta_bytes'] <= 16777216),
        wp_fts_wc_gate('old_posting_reset_php_peak', '<= 134217728', $frontierReset['php_peak_bytes'] ?? null, is_int($frontierReset['php_peak_bytes'] ?? null) && $frontierReset['php_peak_bytes'] <= 134217728),
        wp_fts_wc_gate('old_posting_reset_linux_vmhwm', '<= 134217728', $frontierReset['linux_vmhwm_bytes'] ?? null, is_int($frontierReset['linux_vmhwm_bytes'] ?? null) && $frontierReset['linux_vmhwm_bytes'] > 0 && $frontierReset['linux_vmhwm_bytes'] <= 134217728),
        wp_fts_wc_gate('old_posting_reset_schema_verification', 'exact valid current schema', $frontierResetSchema, ($frontierReset['schema_version'] ?? null) === WP_FTS_Plugin::SCHEMA_VERSION && $frontierResetSchemaValid),
        wp_fts_wc_gate('old_posting_reset_physical_schema', 'exact columns/indexes and InnoDB on four canonical tables', $frontierResetPhysical['exact_current_contract'] ?? null, $frontierResetPhysicalValid),
        wp_fts_wc_gate(
            'old_posting_reset_published_state',
            'empty terms/postings/documents, singleton advanced epoch, no staging/retired tables',
            $frontierResetPostState,
            ($frontierResetPostState['postings'] ?? null) === 0
                && ($frontierResetPostState['terms'] ?? null) === 0
                && ($frontierResetPostState['documents'] ?? null) === 0
                && ($frontierResetPostState['work_rows'] ?? null) === 1
                && ($frontierResetPostState['only_canonical_tables'] ?? null) === true
                && $frontierResetTables === $expectedResetTables
                && ($frontierResetWorkRow['job_key'] ?? null) === 'meta:search-epoch'
                && ($frontierResetWorkRow['kind'] ?? null) === 'meta'
                && (int) ($frontierResetWorkRow['post_id'] ?? -1) === 0
                && (int) ($frontierResetWorkRow['generation'] ?? -1) === ($frontierResetSummary['search_epoch'] ?? -2)
                && ($frontierResetWorkRow['state'] ?? null) === 'meta'
                && wp_fts_wc_is_search_epoch_incarnation($frontierResetWorkRow['payload'] ?? null)
                && !hash_equals(
                    (string) ($frontierResetFixture['search_epoch_incarnation'] ?? ''),
                    (string) ($frontierResetWorkRow['payload'] ?? '')
                )
        ),
        wp_fts_wc_gate('old_posting_frontier_php_peak', '<= 134217728', (int) ($oldPostingFrontier['php_peak_bytes'] ?? PHP_INT_MAX), (int) ($oldPostingFrontier['php_peak_bytes'] ?? PHP_INT_MAX) <= 134217728)
    );
    $evidence['concurrency'] = $concurrency;
    $evidence['idle_http'] = $idle;
    $evidence['cold_cache'] = $cold;
    $evidence['drain'] = $drain;
    $evidence['scope_work'] = $scope;
    $evidence['killed_transaction'] = $transactionCrash;
    $evidence['wp_cli_cursor'] = $wpcliCursor;
    $evidence['writer_aggregate'] = $writerAggregate;
    $evidence['old_posting_frontier'] = $oldPostingFrontier;
    $evidence['max_valid_setup'] = $maxValidSetup;
    $evidence['max_valid_frontend'] = $maxValidSearch;
    $evidence['authoritative_search_memory'] = $authoritativeSearchMemory;
    $evidence['mutation_fence_concurrency'] = $externalEvidence['mutation'];
    $evidence['resource_limits'] = $externalEvidence['resources'];
    $evidence['isolated_boundaries'] = $externalEvidence['isolated_boundaries'];
    $evidence['installed_tree_binding'] = $externalEvidence['installed_tree'];
    $evidence['external_artifact_sha256'] = $externalEvidence['artifact_sha256'];
    $evidence['gates'] = array_merge(
        is_array($evidence['gates'] ?? null) ? $evidence['gates'] : [],
        $authoritativeSearchMemory['gates'],
        $concurrentGates,
        $drainGates,
        $externalEvidence['gates']
    );
    $workTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $evidence['final_work_rows'] = wp_fts_wc_checked_count(
        "SELECT COUNT(*) FROM `{$workTable}` WHERE kind IN ('post','scope')",
        'final pending durable work'
    );
    $evidence['gates'][] = wp_fts_wc_gate('final_work_rows', 0, $evidence['final_work_rows'], $evidence['final_work_rows'] === 0);
    $evidence['search_epoch_rows'] = wp_fts_wc_checked_count(
        $wpdb->prepare(
            "SELECT COUNT(*) FROM `{$workTable}` WHERE job_key=%s AND kind='meta' AND state='meta'",
            WP_FTS_Index_Queue::SEARCH_EPOCH_JOB_KEY
        ),
        'final search epoch singleton'
    );
    $evidence['gates'][] = wp_fts_wc_gate('search_epoch_rows', 1, $evidence['search_epoch_rows'], $evidence['search_epoch_rows'] === 1);
    $gateIds = array_map(static fn(array $gate): string => (string) ($gate['id'] ?? ''), $evidence['gates']);
    if (in_array('evidence_gate_ids_unique', $gateIds, true)) {
        throw new RuntimeException('The reserved final evidence uniqueness gate ID appeared before finalization.');
    }
    $uniqueGateIds = count(array_unique($gateIds));
    $evidence['gates'][] = wp_fts_wc_gate('evidence_gate_ids_unique', count($gateIds) + 1, $uniqueGateIds + 1, $uniqueGateIds === count($gateIds) && !in_array('', $gateIds, true));
    $finalGateIds = array_map(static fn(array $gate): string => (string) ($gate['id'] ?? ''), $evidence['gates']);
    if (!wp_fts_wc_gate_inventory_fingerprint_matches($finalGateIds, 'final')) {
        throw new RuntimeException(
            'Final gate IDs differ from the exact source-reviewed inventory: count='
                . count($finalGateIds)
                . ' sha256='
                . wp_fts_wc_canonical_hash($finalGateIds)
        );
    }
    if (!wp_fts_wc_authoritative_search_memory_inventory_matches($evidence['authoritative_search_memory'])) {
        throw new RuntimeException('Final authoritative search-memory evidence was mutated or shrunk before publication.');
    }
    $evidence['status'] = wp_fts_wc_gates_pass($evidence['gates']) ? 'PASS' : 'FAIL';
    $evidence['completed'] = true;
    unset($evidence['evidence_sha256']);
    $evidence['evidence_sha256'] = wp_fts_wc_canonical_hash($evidence);
    wp_fts_wc_write_json(wp_fts_wc_evidence_path(), $evidence);

    if ($evidence['status'] !== 'PASS') {
        throw new RuntimeException('Worst-case evidence has failed gates: ' . implode(', ', wp_fts_wc_gate_failures($evidence['gates'])));
    }

    return ['status' => 'PASS', 'phase' => 'finalize', 'evidence_path' => wp_fts_wc_evidence_path(), 'evidence_sha256' => $evidence['evidence_sha256']];
}

/**
 * Recompute the complete near-limit front-end artifact from retained rows.
 *
 * @param array<string,mixed> $artifact
 * @param array<string,mixed> $setup
 * @param array<string,string> $expectedBinding
 */
function wp_fts_wc_max_valid_frontend_artifact_is_exact(array $artifact, array $setup, array $expectedBinding): bool
{
    $expectedKeys = [
        'schema', 'status', 'phase',
        'source_sha', 'zip_sha256', 'harness_sha256', 'lane_id', 'engine', 'profile', 'manifest_sha256', 'validation_evidence_sha256',
        'process_identity', 'measurement_method', 'content_bytes', 'content_sha256', 'pages', 'actual_ids',
        'php_usage_before_bytes', 'php_lifetime_peak_before_reset_bytes', 'php_phase_peak_after_reset_bytes', 'php_peak_bytes', 'memory_peak_delta_bytes',
        'rss_before_bytes', 'rss_source', 'rss_delta_bytes', 'rss_peak_bytes', 'rss_peak_delta_bytes',
        'php_peak_delta_authoritative', 'rss_peak_delta_authoritative', 'gates', 'evidence_sha256',
    ];
    $pages = is_array($artifact['pages'] ?? null) ? array_values($artifact['pages']) : [];
    $actualIds = is_array($artifact['actual_ids'] ?? null) ? array_values($artifact['actual_ids']) : [];
    $setupIds = is_array($setup['post_ids'] ?? null) ? array_values($setup['post_ids']) : [];
    $expectedIds = array_reverse($setupIds);
    $pageIds = [];
    $pageMemoryPeaks = [];
    $pageRssDeltas = [];
    $pageRssAfter = [];
    $pagesValid = count($pages) === 10;
    foreach ($pages as $index => $page) {
        if (!is_array($page)) {
            $pagesValid = false;
            continue;
        }
        $ids = is_array($page['ids'] ?? null) ? array_values($page['ids']) : [];
        $results = is_array($page['results'] ?? null) ? array_values($page['results']) : [];
        $resultIds = [];
        $resultsValid = count($results) === 2;
        foreach ($results as $result) {
            $valid = is_array($result)
                && array_keys($result) === ['post_id', 'content_bytes', 'content_sha256']
                && is_int($result['post_id'] ?? null)
                && $result['post_id'] > 0
                && ($result['content_bytes'] ?? null) === 1900000
                && ($result['content_sha256'] ?? null) === wp_fts_wc_max_valid_content_sha256();
            $resultsValid = $resultsValid && $valid;
            if ($valid) {
                $resultIds[] = $result['post_id'];
            }
        }
        $memoryBefore = $page['memory_before_bytes'] ?? null;
        $memoryPeak = $page['memory_phase_peak_bytes'] ?? null;
        $memoryDelta = $page['memory_peak_delta_bytes'] ?? null;
        $rssBefore = $page['rss_before_bytes'] ?? null;
        $rssAfter = $page['rss_after_bytes'] ?? null;
        $rssDelta = $page['rss_delta_bytes'] ?? null;
        $pageValid = array_keys($page) === [
            'page', 'ids', 'results', 'query_count', 'shape',
            'memory_before_bytes', 'memory_peak_delta_bytes', 'memory_phase_peak_bytes',
            'rss_before_bytes', 'rss_after_bytes', 'rss_delta_bytes', 'has_more',
        ]
            && ($page['page'] ?? null) === $index + 1
            && count($ids) === 2
            && count(array_filter($ids, static fn(mixed $id): bool => is_int($id) && $id > 0)) === 2
            && $resultsValid
            && $resultIds === $ids
            && ($page['query_count'] ?? null) === 3
            && ($page['shape'] ?? null) === ['plan' => 1, 'rank' => 1, 'hydrate' => 1]
            && is_int($memoryBefore) && $memoryBefore > 0
            && is_int($memoryPeak) && $memoryPeak >= $memoryBefore
            && is_int($memoryDelta) && $memoryDelta === $memoryPeak - $memoryBefore && $memoryDelta <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES
            && is_int($rssBefore) && $rssBefore > 0
            && is_int($rssAfter) && $rssAfter > 0
            && is_int($rssDelta) && $rssDelta === max(0, $rssAfter - $rssBefore) && $rssDelta <= WP_FTS_WC_MAX_VALID_SEARCH_DELTA_BYTES
            && ($page['has_more'] ?? null) === ($index < 9);
        $pagesValid = $pagesValid && $pageValid;
        if ($pageValid) {
            array_push($pageIds, ...$ids);
            $pageMemoryPeaks[] = $memoryPeak;
            $pageRssDeltas[] = $rssDelta;
            $pageRssAfter[] = $rssAfter;
        }
    }

    return array_keys($artifact) === $expectedKeys
        && ($artifact['schema'] ?? null) === 'relational-fts-max-valid-search-v2'
        && ($artifact['status'] ?? null) === 'PASS'
        && ($artifact['phase'] ?? null) === 'max-valid-search'
        && array_intersect_key($artifact, $expectedBinding) === $expectedBinding
        && wp_fts_wc_process_identity_valid(is_array($artifact['process_identity'] ?? null) ? $artifact['process_identity'] : [])
        && ($artifact['measurement_method'] ?? null) === 'fresh_process_conservative_peak_attribution'
        && ($artifact['content_bytes'] ?? null) === 1900000
        && ($artifact['content_sha256'] ?? null) === wp_fts_wc_max_valid_content_sha256()
        && count($setupIds) === 20
        && count(array_filter($setupIds, static fn(mixed $id): bool => is_int($id) && $id > 0)) === 20
        && count(array_unique($setupIds)) === 20
        && $pagesValid
        && $pageIds === $expectedIds
        && $actualIds === $pageIds
        && count(array_unique($actualIds)) === 20
        && ($artifact['php_phase_peak_after_reset_bytes'] ?? null) === max($pageMemoryPeaks ?: [PHP_INT_MAX])
        && ($artifact['rss_delta_bytes'] ?? null) === max($pageRssDeltas ?: [PHP_INT_MAX])
        && is_int($artifact['rss_peak_bytes'] ?? null)
        && $artifact['rss_peak_bytes'] >= max($pageRssAfter ?: [PHP_INT_MAX])
        && ($artifact['rss_source'] ?? null) === 'linux_proc_status'
        && ($artifact['php_peak_delta_authoritative'] ?? null) === true
        && ($artifact['rss_peak_delta_authoritative'] ?? null) === true
        && is_array($artifact['gates'] ?? null)
        && wp_fts_wc_is_lowercase_sha256($artifact['evidence_sha256'] ?? null);
}

/**
 * Re-read and structurally verify the three source-bound artifacts produced
 * outside the main phase process. The final report retains both their complete
 * payloads and hashes so a plausible summary cannot replace the measured SQL,
 * cgroup, or exact-boundary evidence.
 *
 * @param array<string,mixed> $validationEvidence
 * @return array{resources:array<string,mixed>,mutation:array<string,mixed>,isolated_boundaries:array<string,mixed>,installed_tree:array<string,mixed>,artifact_sha256:array<string,string>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_final_external_evidence(array $validationEvidence): array
{
    $directory = wp_fts_wc_evidence_dir();
    $paths = [
        'resources' => $directory . '/resources.json',
        'mutation' => $directory . '/mutation-fence-concurrency.json',
        'isolated_boundaries' => $directory . '/relational-fts-isolated-boundaries.json',
        'installed_post_install' => $directory . '/installed-tree-post-install.json',
        'installed_pre_finalize' => $directory . '/installed-tree-pre-finalize.json',
    ];
    $resources = wp_fts_wc_read_json($paths['resources']);
    $mutation = wp_fts_wc_read_json($paths['mutation']);
    $isolated = wp_fts_wc_read_json($paths['isolated_boundaries']);
    $installedPostInstall = wp_fts_wc_read_json($paths['installed_post_install']);
    $installedPreFinalize = wp_fts_wc_read_json($paths['installed_pre_finalize']);
    $artifactHashes = [];
    foreach ($paths as $name => $path) {
        $hash = hash_file('sha256', $path);
        if (!is_string($hash)) {
            throw new RuntimeException("Could not hash required {$name} evidence: {$path}");
        }
        $artifactHashes[$name] = $hash;
    }

    $gates = wp_fts_wc_resource_artifact_gates($resources, $validationEvidence);
    array_push($gates, ...wp_fts_wc_installed_tree_artifact_gates($installedPostInstall, $installedPreFinalize, $resources, $validationEvidence));
    array_push($gates, ...wp_fts_wc_mutation_artifact_gates($mutation, $resources, $validationEvidence));
    $preliminaryMutation = is_array($validationEvidence['mutation_fence_concurrency'] ?? null)
        ? $validationEvidence['mutation_fence_concurrency']
        : [];
    $preliminaryMutationHash = wp_fts_wc_canonical_hash($preliminaryMutation);
    $finalMutationHash = wp_fts_wc_canonical_hash($mutation);
    $gates[] = wp_fts_wc_gate(
        'mutation_artifact_preliminary_identity',
        $preliminaryMutationHash,
        $finalMutationHash,
        $preliminaryMutation !== [] && hash_equals($preliminaryMutationHash, $finalMutationHash)
    );

    $isolatedGateIds = [
        'cjk_accepted_input_exactly_4095_bytes',
        'cjk_4095_production_analyzer_indexer_accepted',
        'cjk_4095_distinct_terms_bounded',
        'cjk_4095_occurrences_bounded',
        'cjk_4095_writer_replaced_document',
        'cjk_4095_writer_terms_and_postings',
        'cjk_4095_writer_statement_count',
        'cjk_4095_writer_sql_bytes',
        'cjk_rejected_input_is_above_4096_bytes',
        'cjk_above_4k_rejects_as_lexical_run_bytes',
        'cjk_above_4k_sql_before_rejection',
        'cjk_fixture_cleanup_completed',
        'cjk_fixture_cleanup_rows',
        'html_nested_fixture_within_source_limit',
        'html_nested_100000_rejects_as_element_depth',
        'html_nested_100000_sql_before_rejection',
        'html_nested_100000_duration_ms',
        'html_nested_100000_php_allocation_delta',
        'html_nested_100000_vmhwm_within_128_mib',
        'html_nested_100000_vmrss_within_128_mib',
        'html_language_fixture_within_source_limit',
        'html_language_1800000_rejects_as_attribute_bytes',
        'html_language_1800000_sql_before_rejection',
        'html_language_1800000_duration_ms',
        'html_language_1800000_php_allocation_delta',
        'html_language_1800000_vmhwm_within_128_mib',
        'html_language_1800000_vmrss_within_128_mib',
        'infinite_tokenizer_rejected_by_occurrence_limit',
        'infinite_tokenizer_call_count',
        'infinite_tokenizer_consumed_occurrences',
        'infinite_tokenizer_storage_sql',
        'logical_groups_12_accepted',
        'logical_groups_12_statement_count',
        'logical_groups_13_rejected',
        'logical_groups_13_sql_before_rejection',
        'query_alternatives_12_accepted',
        'query_alternatives_12_statement_count',
        'query_alternatives_13_rejected',
        'query_alternatives_13_sql_before_rejection',
        'document_4096_distinct_terms_accepted',
        'document_4096_prepared_term_count',
        'document_4096_writer_term_count',
        'document_4096_writer_posting_count',
        'document_4096_writer_statement_count',
        'document_4096_writer_max_sql_bytes',
        'document_4097_distinct_terms_rejected',
        'document_4097_sql_before_rejection',
        'document_fixture_cleanup_completed',
        'document_fixture_cleanup_rows',
        'enqueue_many_1000_return_count',
        'enqueue_many_1000_statement_count',
        'enqueue_many_1000_statement_shape',
        'enqueue_many_1000_statement_bytes',
        'enqueue_many_1001_rejected',
        'enqueue_many_1001_sql_before_rejection',
        'queue_fixture_cleanup_completed',
        'queue_fixture_cleanup_rows',
        'all_reject_paths_actual_wpdb_statement_count',
        'php_memory_limit_exactly_128_mib',
        'php_peak_memory_within_128_mib',
        'proc_vmhwm_within_128_mib',
        'proc_vmrss_within_128_mib',
    ];
    $isolatedGates = wp_fts_wc_require_evidence_gates(
        $isolated,
        'isolated exact-boundary proof',
        $isolatedGateIds,
        'relational-fts-isolated-boundaries-v1'
    );
    $actualIsolatedGateIds = array_map(
        static fn(array $gate): string => (string) ($gate['id'] ?? ''),
        $isolatedGates
    );
    $isolatedBinding = is_array($isolated['binding'] ?? null) ? $isolated['binding'] : [];
    $expectedIsolatedBinding = [
        'source_sha' => $validationEvidence['source_sha'] ?? null,
        'source_dirty' => $validationEvidence['source_dirty'] ?? null,
        'zip_sha256' => $validationEvidence['zip_sha256'] ?? null,
        'harness_sha256' => $resources['isolated_boundaries_sha256'] ?? null,
        'profile' => $validationEvidence['manifest']['profile']['name'] ?? null,
        'engine' => $validationEvidence['engine'] ?? null,
    ];
    $hashInput = $isolated;
    $recordedIsolatedHash = $hashInput['evidence_sha256'] ?? null;
    $hashInput['evidence_sha256'] = null;
    $calculatedIsolatedHash = wp_fts_wc_isolated_canonical_hash($hashInput);
    $isolatedLog = $directory . '/relational-fts-isolated-boundaries.log';
    $isolatedLogHash = is_file($isolatedLog) ? hash_file('sha256', $isolatedLog) : false;
    array_push(
        $gates,
        wp_fts_wc_gate('isolated_boundary_exact_gate_set', $isolatedGateIds, $actualIsolatedGateIds, $actualIsolatedGateIds === $isolatedGateIds),
        wp_fts_wc_gate('isolated_boundary_source_binding', $expectedIsolatedBinding, $isolatedBinding, $isolatedBinding === $expectedIsolatedBinding),
        wp_fts_wc_gate(
            'isolated_boundary_evidence_hash',
            $calculatedIsolatedHash,
            $recordedIsolatedHash,
            wp_fts_wc_is_lowercase_sha256($recordedIsolatedHash) && hash_equals($calculatedIsolatedHash, (string) $recordedIsolatedHash)
        ),
        wp_fts_wc_gate(
            'isolated_boundary_stdout_artifact_identity',
            $artifactHashes['isolated_boundaries'],
            $isolatedLogHash,
            is_string($isolatedLogHash) && hash_equals($artifactHashes['isolated_boundaries'], $isolatedLogHash)
        ),
        wp_fts_wc_gate('isolated_boundary_error', null, $isolated['error'] ?? null, ($isolated['error'] ?? null) === null)
    );
    array_push($gates, ...$isolatedGates);

    return [
        'resources' => $resources,
        'mutation' => $mutation,
        'isolated_boundaries' => $isolated,
        'installed_tree' => ['post_install' => $installedPostInstall, 'pre_finalize' => $installedPreFinalize],
        'artifact_sha256' => $artifactHashes,
        'gates' => $gates,
    ];
}

/**
 * @param array<string,mixed> $postInstall
 * @param array<string,mixed> $preFinalize
 * @param array<string,mixed> $resources
 * @param array<string,mixed> $validationEvidence
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_installed_tree_artifact_gates(array $postInstall, array $preFinalize, array $resources, array $validationEvidence): array
{
    $package = is_array($resources['package_reproducibility'] ?? null) ? $resources['package_reproducibility'] : [];
    $zipEntries = is_array($package['primary']['manifest']['entries'] ?? null)
        ? array_values($package['primary']['manifest']['entries'])
        : [];
    $packageTree = [];
    foreach ($zipEntries as $entry) {
        if (!is_array($entry) || !is_string($entry['name'] ?? null) || !str_starts_with((string) $entry['name'], 'indexer/')) {
            continue;
        }
        $packageTree[] = [
            'path' => substr((string) $entry['name'], strlen('indexer/')),
            'bytes' => (int) ($entry['bytes'] ?? -1),
            'sha256' => (string) ($entry['content_sha256'] ?? ''),
        ];
    }
    usort($packageTree, static fn(array $left, array $right): int => strcmp($left['path'], $right['path']));
    $packageTreeHash = hash('sha256', json_encode($packageTree, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR));
    $gates = [];
    foreach (['post-install' => $postInstall, 'pre-finalize' => $preFinalize] as $checkpoint => $artifact) {
        $artifactGates = wp_fts_wc_require_evidence_gates(
            $artifact,
            "installed tree {$checkpoint}",
            ['installed_tree_exact_names', 'installed_tree_exact_content', 'installed_tree_no_symlinks', 'installed_tree_zip_digest'],
            'relational-fts-installed-tree-v1'
        );
        $expectedManifest = is_array($artifact['expected_manifest'] ?? null) ? array_values($artifact['expected_manifest']) : [];
        $actualManifest = is_array($artifact['actual_manifest'] ?? null) ? array_values($artifact['actual_manifest']) : [];
        foreach ($artifactGates as $artifactGate) {
            $artifactGate['id'] = 'installed_tree_' . str_replace('-', '_', $checkpoint) . '_' . $artifactGate['id'];
            $gates[] = $artifactGate;
        }
        $gates[] = wp_fts_wc_gate(
            'installed_tree_' . str_replace('-', '_', $checkpoint) . '_binding',
            [$checkpoint, $validationEvidence['source_sha'] ?? null, $validationEvidence['zip_sha256'] ?? null, $packageTreeHash],
            [$artifact['checkpoint'] ?? null, $artifact['source_sha'] ?? null, $artifact['zip_sha256'] ?? null, $artifact['expected_manifest_sha256'] ?? null],
            ($artifact['checkpoint'] ?? null) === $checkpoint
                && ($artifact['source_sha'] ?? null) === ($validationEvidence['source_sha'] ?? null)
                && ($artifact['zip_sha256'] ?? null) === ($validationEvidence['zip_sha256'] ?? null)
                && $expectedManifest === $packageTree
                && $actualManifest === $packageTree
                && ($artifact['expected_manifest_sha256'] ?? null) === $packageTreeHash
                && ($artifact['actual_manifest_sha256'] ?? null) === $packageTreeHash
        );
    }
    $gates[] = wp_fts_wc_gate(
        'installed_tree_checkpoints_identical',
        $postInstall['actual_manifest_sha256'] ?? null,
        $preFinalize['actual_manifest_sha256'] ?? null,
        is_string($postInstall['actual_manifest_sha256'] ?? null)
            && ($postInstall['actual_manifest_sha256'] ?? null) === ($preFinalize['actual_manifest_sha256'] ?? null)
            && ($postInstall['actual_manifest'] ?? null) === ($preFinalize['actual_manifest'] ?? null)
    );

    return $gates;
}

/**
 * @param array<string,mixed> $resources
 * @param array<string,mixed> $validationEvidence
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_resource_artifact_gates(array $resources, array $validationEvidence): array
{
    $engine = (string) ($validationEvidence['engine'] ?? '');
    $expectedDatabaseImage = match ($engine) {
        'mariadb-10.11' => 'mariadb@sha256:5a5c675881ef3fd1c1da9b0a3bfd6ee82edbe39cd9e32e06be18034c37235e0e',
        'mysql-8.0' => 'mysql@sha256:7dcddc01f13bab2f15cde676d44d01f61fc9f99fe7785e86196dfc07d358ae2b',
        default => throw new RuntimeException("Unsupported resource engine: {$engine}"),
    };
    $expectedImages = [
        'database' => $expectedDatabaseImage,
        'wordpress' => 'wordpress@sha256:bfc320ed4f02dd3939186b8020de64203a48a939d6dedcf44cb92cf2368923f5',
        'wpcli' => 'wordpress@sha256:7f492e43c962ee85b1a9d5f88a97111559d92c2fb785f5d20650670bfaaa1763',
    ];
    $expectedMemory = [
        'database' => 1073741824,
        'wordpress' => 536870912,
        'wpcli' => 536870912,
    ];
    $profile = is_array($validationEvidence['manifest']['profile'] ?? null)
        ? $validationEvidence['manifest']['profile']
        : [];
    $verification = is_array($resources['verification'] ?? null) ? $resources['verification'] : [];
    $packageReproducibility = is_array($resources['package_reproducibility'] ?? null)
        ? $resources['package_reproducibility']
        : [];
    $ioProfile = is_array($resources['io_profile'] ?? null) ? $resources['io_profile'] : [];
    $hostEnvironment = is_array($resources['host_environment'] ?? null) ? $resources['host_environment'] : [];
    $databaseEvidence = is_array($resources['database'] ?? null) ? $resources['database'] : [];
    $databaseMemory = is_array($databaseEvidence['memory'] ?? null) ? $databaseEvidence['memory'] : [];
    $preCorpusMemory = is_array($databaseMemory['pre_corpus'] ?? null) ? $databaseMemory['pre_corpus'] : [];
    $finalMemory = is_array($databaseMemory['final_checkpoint'] ?? null) ? $databaseMemory['final_checkpoint'] : [];
    $memoryCheckpoints = is_array($databaseMemory['checkpoints'] ?? null) ? array_values($databaseMemory['checkpoints']) : [];
    $expectedMemoryCheckpointLabels = ['pre-corpus', 'post-frontier', 'post-reindex'];
    foreach (['common_or', 'max_valid_or_prefix', 'rare_anchor_and', 'prefix_fanout'] as $caseId) {
        for ($sample = 0; $sample < WP_FTS_WC_COLD_SAMPLE_COUNT; $sample++) {
            $expectedMemoryCheckpointLabels[] = "pre-cold-restart-{$caseId}-{$sample}";
        }
    }
    $expectedMemoryCheckpointLabels[] = 'pre-scope-restart';
    $expectedMemoryCheckpointLabels[] = 'final-workload';
    $actualMemoryCheckpointLabels = array_map(
        static fn(mixed $checkpoint): mixed => is_array($checkpoint) ? ($checkpoint['checkpoint'] ?? null) : null,
        $memoryCheckpoints
    );
    $wholeRunPeak = $databaseMemory['whole_run_peak_bytes'] ?? null;
    $wholeRunHeadroom = $databaseMemory['whole_run_headroom_bytes'] ?? null;
    $wordpressEvidence = is_array($resources['wordpress'] ?? null) ? $resources['wordpress'] : [];
    $wordpressMemory = is_array($wordpressEvidence['memory'] ?? null) ? $wordpressEvidence['memory'] : [];
    $wordpressMemoryCheckpoints = is_array($wordpressMemory['checkpoints'] ?? null) ? array_values($wordpressMemory['checkpoints']) : [];
    $wordpressFinalMemory = is_array($wordpressMemory['final_checkpoint'] ?? null) ? $wordpressMemory['final_checkpoint'] : [];
    $expectedWordpressMemoryCheckpointLabels = ['pre-corpus', 'final-workload'];
    $actualWordpressMemoryCheckpointLabels = array_map(
        static fn(mixed $checkpoint): mixed => is_array($checkpoint) ? ($checkpoint['checkpoint'] ?? null) : null,
        $wordpressMemoryCheckpoints
    );
    $wordpressWholeRunPeak = $wordpressMemory['whole_run_peak_bytes'] ?? null;
    $wordpressWholeRunHeadroom = $wordpressMemory['whole_run_headroom_bytes'] ?? null;
    $acceptanceLane = ($validationEvidence['acceptance_lane'] ?? null) === true;
    $hostEnvironmentRecorded = is_string($hostEnvironment['runner_os'] ?? null)
        && (string) $hostEnvironment['runner_os'] !== ''
        && is_string($hostEnvironment['runner_arch'] ?? null)
        && (string) $hostEnvironment['runner_arch'] !== ''
        && is_string($hostEnvironment['image_os'] ?? null)
        && (string) $hostEnvironment['image_os'] !== ''
        && is_string($hostEnvironment['image_version'] ?? null)
        && (string) $hostEnvironment['image_version'] !== '';
    $acceptanceHostRecorded = !$acceptanceLane || (
        ($hostEnvironment['runner_os'] ?? null) === 'Linux'
        && ($hostEnvironment['runner_arch'] ?? null) === 'X64'
        && ($hostEnvironment['image_os'] ?? null) !== 'unknown'
        && ($hostEnvironment['image_version'] ?? null) !== 'unknown'
    );
    $gates = [
        wp_fts_wc_gate(
            'resource_artifact_contract',
            ['relational-fts-resources-v2', 'PASS', 'relational-fts-resource-verification-v1', $acceptanceLane, []],
            [$resources['schema'] ?? null, $resources['status'] ?? null, $verification['schema'] ?? null, $verification['acceptance_lane'] ?? null, $verification['gate_failures'] ?? null],
            ($resources['schema'] ?? null) === 'relational-fts-resources-v2'
                && ($resources['status'] ?? null) === 'PASS'
                && ($verification['schema'] ?? null) === 'relational-fts-resource-verification-v1'
                && ($verification['acceptance_lane'] ?? null) === $acceptanceLane
                && ($verification['gate_failures'] ?? null) === []
        ),
        wp_fts_wc_gate(
            'resource_artifact_full_binding',
            [$profile['name'] ?? null, $profile['documents'] ?? null, $engine, wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256')],
            [$resources['profile'] ?? null, $resources['documents'] ?? null, $resources['engine'] ?? null, $resources['harness_sha256'] ?? null],
            ($resources['profile'] ?? null) === ($profile['name'] ?? null)
                && ($resources['documents'] ?? null) === ($profile['documents'] ?? null)
                && ($resources['engine'] ?? null) === $engine
                && ($resources['harness_sha256'] ?? null) === wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256')
                && wp_fts_wc_is_lowercase_sha256($resources['harness_sha256'] ?? null)
                && wp_fts_wc_is_lowercase_sha256($resources['mutation_proof_sha256'] ?? null)
                && wp_fts_wc_is_lowercase_sha256($resources['isolated_boundaries_sha256'] ?? null)
        ),
        wp_fts_wc_gate(
            'resource_package_reproducibility',
            'two byte- and manifest-identical source-bound release builds',
            $packageReproducibility,
            wp_fts_wc_package_reproducibility_is_exact($packageReproducibility, $validationEvidence)
        ),
        wp_fts_wc_gate(
            'resource_latency_scope',
            ['host-provided-unthrottled', 'this recorded CI/Docker runner only'],
            [$ioProfile['mode'] ?? null, $ioProfile['latency_scope'] ?? null],
            ($ioProfile['mode'] ?? null) === 'host-provided-unthrottled'
                && ($ioProfile['latency_scope'] ?? null) === 'this recorded CI/Docker runner only'
                && ($ioProfile['portable_gates'] ?? null) === ['statement_count', 'statement_bytes', 'rows_examined', 'rows_sent', 'memory']
        ),
        wp_fts_wc_gate(
            'resource_host_environment',
            $acceptanceLane ? ['Linux', 'X64', 'recorded runner image'] : 'recorded local or CI host',
            $hostEnvironment,
            $hostEnvironmentRecorded && $acceptanceHostRecorded
        ),
        wp_fts_wc_gate(
            'resource_database_memory_checkpoint_contract',
            'restart-safe cgroup v1/v2 peak and OOM checkpoints',
            $databaseMemory,
            wp_fts_wc_database_memory_evidence_is_exact($databaseMemory, $databaseEvidence)
        ),
        wp_fts_wc_gate(
            'resource_database_memory_checkpoint_inventory',
            $expectedMemoryCheckpointLabels,
            $actualMemoryCheckpointLabels,
            ($databaseMemory['expected_checkpoint_labels'] ?? null) === $expectedMemoryCheckpointLabels
                && $actualMemoryCheckpointLabels === $expectedMemoryCheckpointLabels
        ),
        wp_fts_wc_gate(
            'resource_database_pre_corpus_peak',
            ['peak_bytes' => '<= 805306368', 'headroom_bytes' => '>= 268435456'],
            ['peak_bytes' => $preCorpusMemory['peak_bytes'] ?? null, 'headroom_bytes' => is_int($preCorpusMemory['peak_bytes'] ?? null) ? 1073741824 - $preCorpusMemory['peak_bytes'] : null],
            is_int($preCorpusMemory['peak_bytes'] ?? null)
                && $preCorpusMemory['peak_bytes'] > 0
                && $preCorpusMemory['peak_bytes'] <= 805306368
                && 1073741824 - $preCorpusMemory['peak_bytes'] >= 268435456
        ),
        wp_fts_wc_gate(
            'resource_database_whole_run_peak_recorded',
            'actual restart-safe peak and signed headroom under the hard 1 GiB cgroup',
            ['peak_bytes' => $wholeRunPeak, 'headroom_bytes' => $wholeRunHeadroom, 'final_checkpoint' => $finalMemory],
            is_int($wholeRunPeak)
                && $wholeRunPeak > 0
                && is_int($wholeRunHeadroom)
                && $wholeRunHeadroom === 1073741824 - $wholeRunPeak
                && is_int($finalMemory['peak_bytes'] ?? null)
                && $finalMemory['peak_bytes'] <= $wholeRunPeak
        ),
        wp_fts_wc_gate(
            'resource_database_zero_oom',
            ['oom_events' => 0, 'oom_kill_events' => 0],
            ['oom_events' => $databaseMemory['oom_events'] ?? null, 'oom_kill_events' => $databaseMemory['oom_kill_events'] ?? null],
            ($databaseMemory['oom_events'] ?? null) === 0
                && ($databaseMemory['oom_kill_events'] ?? null) === 0
                && count(array_filter($memoryCheckpoints, static fn(mixed $checkpoint): bool => !is_array($checkpoint) || ($checkpoint['oom_events'] ?? null) !== 0 || ($checkpoint['oom_kill_events'] ?? null) !== 0)) === 0
        ),
        wp_fts_wc_gate(
            'resource_wordpress_cgroup_memory_complete',
            ['contract' => 'persistent-container cgroup v1/v2 memory evidence', 'checkpoints' => $expectedWordpressMemoryCheckpointLabels],
            ['memory' => $wordpressMemory, 'checkpoints' => $actualWordpressMemoryCheckpointLabels],
            wp_fts_wc_wordpress_memory_evidence_is_exact($wordpressMemory, $wordpressEvidence)
                && $actualWordpressMemoryCheckpointLabels === $expectedWordpressMemoryCheckpointLabels
        ),
        wp_fts_wc_gate(
            'resource_wordpress_cgroup_peak',
            'actual whole-run peak within the hard 512 MiB cgroup plus exact remaining headroom',
            ['peak_bytes' => $wordpressWholeRunPeak, 'headroom_bytes' => $wordpressWholeRunHeadroom, 'final_checkpoint' => $wordpressFinalMemory],
            is_int($wordpressWholeRunPeak)
                && $wordpressWholeRunPeak > 0
                && $wordpressWholeRunPeak <= 536870912
                && is_int($wordpressWholeRunHeadroom)
                && $wordpressWholeRunHeadroom === 536870912 - $wordpressWholeRunPeak
                && ($wordpressFinalMemory['peak_bytes'] ?? null) === $wordpressWholeRunPeak
        ),
        wp_fts_wc_gate(
            'resource_wordpress_cgroup_no_oom',
            ['limit_events' => 0, 'oom_events' => 0, 'oom_kill_events' => 0],
            ['limit_events' => $wordpressMemory['max_limit_events'] ?? null, 'oom_events' => $wordpressMemory['oom_events'] ?? null, 'oom_kill_events' => $wordpressMemory['oom_kill_events'] ?? null],
            ($wordpressMemory['max_limit_events'] ?? null) === 0
                && ($wordpressMemory['oom_events'] ?? null) === 0
                && ($wordpressMemory['oom_kill_events'] ?? null) === 0
                && count(array_filter($wordpressMemoryCheckpoints, static fn(mixed $checkpoint): bool => !is_array($checkpoint) || ($checkpoint['limit_events'] ?? null) !== 0 || ($checkpoint['oom_events'] ?? null) !== 0 || ($checkpoint['oom_kill_events'] ?? null) !== 0)) === 0
        ),
    ];
    foreach ($expectedImages as $role => $expectedReference) {
        $roleEvidence = is_array($resources[$role] ?? null) ? $resources[$role] : [];
        $image = is_array($roleEvidence['image'] ?? null) ? $roleEvidence['image'] : [];
        $cgroup = is_array($roleEvidence['effective_cgroup'] ?? null) ? $roleEvidence['effective_cgroup'] : [];
        $gates[] = wp_fts_wc_gate(
            "resource_{$role}_pinned_image",
            $acceptanceLane ? $expectedReference : 'recorded non-acceptance image override',
            $image,
            wp_fts_wc_resource_image_is_exact($image, $expectedReference, $acceptanceLane)
        );
        $gates[] = wp_fts_wc_gate(
            "resource_{$role}_effective_cgroup",
            ['cpus' => 1, 'memory_bytes' => $expectedMemory[$role], 'swap_bytes' => 0],
            $cgroup,
            wp_fts_wc_resource_cgroup_is_exact($cgroup, $expectedMemory[$role])
        );
    }

    $expectedGateIds = [
        'resource_artifact_contract',
        'resource_artifact_full_binding',
        'resource_package_reproducibility',
        'resource_latency_scope',
        'resource_host_environment',
        'resource_database_memory_checkpoint_contract',
        'resource_database_memory_checkpoint_inventory',
        'resource_database_pre_corpus_peak',
        'resource_database_whole_run_peak_recorded',
        'resource_database_zero_oom',
        'resource_wordpress_cgroup_memory_complete',
        'resource_wordpress_cgroup_peak',
        'resource_wordpress_cgroup_no_oom',
        'resource_database_pinned_image',
        'resource_database_effective_cgroup',
        'resource_wordpress_pinned_image',
        'resource_wordpress_effective_cgroup',
        'resource_wpcli_pinned_image',
        'resource_wpcli_effective_cgroup',
        'resource_gate_inventory',
    ];
    $actualGateIds = array_map(static fn(array $gate): string => (string) ($gate['id'] ?? ''), $gates);
    $actualGateIds[] = 'resource_gate_inventory';
    $gates[] = wp_fts_wc_gate(
        'resource_gate_inventory',
        $expectedGateIds,
        $actualGateIds,
        $actualGateIds === $expectedGateIds
    );

    return $gates;
}

/** Prove that planned database restarts could not erase peak or OOM evidence. */
function wp_fts_wc_database_memory_evidence_is_exact(array $memory, array $databaseEvidence): bool
{
    $checkpoints = is_array($memory['checkpoints'] ?? null) ? array_values($memory['checkpoints']) : [];
    $expectedLabels = ['pre-corpus', 'post-frontier', 'post-reindex'];
    foreach (['common_or', 'max_valid_or_prefix', 'rare_anchor_and', 'prefix_fanout'] as $caseId) {
        for ($sample = 0; $sample < WP_FTS_WC_COLD_SAMPLE_COUNT; $sample++) {
            $expectedLabels[] = "pre-cold-restart-{$caseId}-{$sample}";
        }
    }
    $expectedLabels[] = 'pre-scope-restart';
    $expectedLabels[] = 'final-workload';
    if (
        ($memory['schema'] ?? null) !== 'relational-fts-database-cgroup-memory-v2'
        || ($memory['limit_bytes'] ?? null) !== 1073741824
        || ($memory['pre_corpus_peak_limit_bytes'] ?? null) !== 805306368
        || ($memory['complete'] ?? null) !== true
        || ($memory['checkpoint_count'] ?? null) !== count($checkpoints)
        || ($memory['expected_checkpoint_labels'] ?? null) !== $expectedLabels
        || count($checkpoints) !== count($expectedLabels)
        || ($memory['counter_aggregation'] ?? null) !== 'maximum across restart-delimited cumulative counters'
    ) {
        return false;
    }

    $effectiveCgroup = is_array($databaseEvidence['effective_cgroup'] ?? null)
        ? $databaseEvidence['effective_cgroup']
        : [];
    $expectedVersion = $effectiveCgroup['version'] ?? null;
    $labels = [];
    $actualLabels = [];
    $peaks = [];
    $limitEvents = [];
    $oomEvents = [];
    $oomKills = [];
    $unsigned = static fn(mixed $value): ?int => is_string($value)
        && $value !== ''
        && strspn($value, '0123456789') === strlen($value)
            ? (int) $value
            : null;
    foreach ($checkpoints as $checkpoint) {
        if (!is_array($checkpoint)) {
            return false;
        }
        $version = $checkpoint['cgroup_version'] ?? null;
        $expectedSources = $version === 'v2'
            ? ['usage' => 'memory.current', 'peak' => 'memory.peak', 'limit_events' => 'memory.events:max', 'oom_events' => 'memory.events:oom', 'oom_kill_events' => 'memory.events:oom_kill']
            : ['usage' => 'memory.usage_in_bytes', 'peak' => 'memory.max_usage_in_bytes', 'limit_events' => 'memory.failcnt', 'oom_events' => 'memory.failcnt (conservative)', 'oom_kill_events' => 'memory.oom_control:oom_kill'];
        $label = $checkpoint['checkpoint'] ?? null;
        $raw = $checkpoint['raw'] ?? null;
        $rawParts = is_string($raw) ? explode("\t", $raw) : [];
        $rawMatchesStructured = count($rawParts) === 6
            && ($rawParts[0] ?? null) === $version
            && $unsigned($rawParts[1] ?? null) === ($checkpoint['usage_bytes'] ?? null)
            && $unsigned($rawParts[2] ?? null) === ($checkpoint['peak_bytes'] ?? null)
            && $unsigned($rawParts[3] ?? null) === ($checkpoint['limit_events'] ?? null)
            && $unsigned($rawParts[4] ?? null) === ($checkpoint['oom_events'] ?? null)
            && $unsigned($rawParts[5] ?? null) === ($checkpoint['oom_kill_events'] ?? null)
            && is_string($checkpoint['raw_sha256'] ?? null)
            && hash_equals(hash('sha256', $raw), $checkpoint['raw_sha256']);
        if (
            !is_string($label)
            || $label === ''
            || isset($labels[$label])
            || !in_array($version, ['v1', 'v2'], true)
            || $version !== $expectedVersion
            || ($checkpoint['sources'] ?? null) !== $expectedSources
            || !is_int($checkpoint['usage_bytes'] ?? null)
            || $checkpoint['usage_bytes'] < 0
            || !is_int($checkpoint['peak_bytes'] ?? null)
            || $checkpoint['peak_bytes'] < 1
            || $checkpoint['peak_bytes'] < $checkpoint['usage_bytes']
            || !is_int($checkpoint['limit_events'] ?? null)
            || $checkpoint['limit_events'] < 0
            || !is_int($checkpoint['oom_events'] ?? null)
            || $checkpoint['oom_events'] < 0
            || !is_int($checkpoint['oom_kill_events'] ?? null)
            || $checkpoint['oom_kill_events'] < 0
            || !$rawMatchesStructured
            || !wp_fts_wc_is_lowercase_sha256($checkpoint['raw_sha256'] ?? null)
        ) {
            return false;
        }
        $labels[$label] = true;
        $actualLabels[] = $label;
        $peaks[] = $checkpoint['peak_bytes'];
        $limitEvents[] = $checkpoint['limit_events'];
        $oomEvents[] = $checkpoint['oom_events'];
        $oomKills[] = $checkpoint['oom_kill_events'];
    }

    $first = $checkpoints[0];
    $final = $checkpoints[array_key_last($checkpoints)];
    $wholeRunPeak = max($peaks);

    return $actualLabels === $expectedLabels
        && ($first['checkpoint'] ?? null) === 'pre-corpus'
        && ($final['checkpoint'] ?? null) === 'final-workload'
        && ($memory['pre_corpus'] ?? null) === $first
        && ($memory['final_checkpoint'] ?? null) === $final
        && ($memory['whole_run_peak_bytes'] ?? null) === $wholeRunPeak
        && ($memory['whole_run_headroom_bytes'] ?? null) === 1073741824 - $wholeRunPeak
        && ($memory['max_limit_events'] ?? null) === max($limitEvents)
        && ($memory['oom_events'] ?? null) === max($oomEvents)
        && ($memory['oom_kill_events'] ?? null) === max($oomKills);
}

/** Prove that the unrestarted WordPress container stayed within its cgroup for the entire run. */
function wp_fts_wc_wordpress_memory_evidence_is_exact(array $memory, array $wordpressEvidence): bool
{
    $checkpoints = is_array($memory['checkpoints'] ?? null) ? array_values($memory['checkpoints']) : [];
    $expectedLabels = ['pre-corpus', 'final-workload'];
    if (
        ($memory['schema'] ?? null) !== 'relational-fts-wordpress-cgroup-memory-v3'
        || ($memory['limit_bytes'] ?? null) !== 536870912
        || ($memory['complete'] ?? null) !== true
        || ($memory['checkpoint_count'] ?? null) !== count($checkpoints)
        || ($memory['expected_checkpoint_labels'] ?? null) !== $expectedLabels
        || count($checkpoints) !== count($expectedLabels)
        || ($memory['counter_aggregation'] ?? null) !== 'maximum across cumulative checkpoints in one unrestarted container'
    ) {
        return false;
    }

    $effectiveCgroup = is_array($wordpressEvidence['effective_cgroup'] ?? null)
        ? $wordpressEvidence['effective_cgroup']
        : [];
    $expectedVersion = $effectiveCgroup['version'] ?? null;
    $containerId = $wordpressEvidence['container_id'] ?? null;
    if (!is_string($containerId) || preg_match('/\A[0-9a-f]{64}\z/D', $containerId) !== 1) {
        return false;
    }
    $containerLifecycle = is_array($wordpressEvidence['container_lifecycle'] ?? null)
        ? $wordpressEvidence['container_lifecycle']
        : [];
    if (
        array_keys($containerLifecycle) !== ['started_at', 'host_pid', 'restart_count']
        || !is_string($containerLifecycle['started_at'] ?? null)
        || $containerLifecycle['started_at'] === ''
        || !is_int($containerLifecycle['host_pid'] ?? null)
        || $containerLifecycle['host_pid'] < 1
        || !is_int($containerLifecycle['restart_count'] ?? null)
        || $containerLifecycle['restart_count'] < 0
    ) {
        return false;
    }
    $seenLabels = [];
    $actualLabels = [];
    $peaks = [];
    $limitEvents = [];
    $oomEvents = [];
    $oomKills = [];
    $unsigned = static fn(mixed $value): ?int => is_string($value)
        && $value !== ''
        && strspn($value, '0123456789') === strlen($value)
            ? (int) $value
            : null;
    foreach ($checkpoints as $checkpoint) {
        if (!is_array($checkpoint)) {
            return false;
        }
        $version = $checkpoint['cgroup_version'] ?? null;
        $expectedSources = $version === 'v2'
            ? ['usage' => 'memory.current', 'peak' => 'memory.peak', 'limit_events' => 'memory.events:max', 'oom_events' => 'memory.events:oom', 'oom_kill_events' => 'memory.events:oom_kill']
            : ['usage' => 'memory.usage_in_bytes', 'peak' => 'memory.max_usage_in_bytes', 'limit_events' => 'memory.failcnt', 'oom_events' => 'memory.failcnt (conservative)', 'oom_kill_events' => 'memory.oom_control:oom_kill'];
        $label = $checkpoint['checkpoint'] ?? null;
        $raw = $checkpoint['raw'] ?? null;
        $rawParts = is_string($raw) ? explode("\t", $raw) : [];
        $rawMatchesStructured = count($rawParts) === 10
            && ($rawParts[0] ?? null) === $version
            && $unsigned($rawParts[1] ?? null) === ($checkpoint['usage_bytes'] ?? null)
            && $unsigned($rawParts[2] ?? null) === ($checkpoint['peak_bytes'] ?? null)
            && $unsigned($rawParts[3] ?? null) === ($checkpoint['limit_events'] ?? null)
            && $unsigned($rawParts[4] ?? null) === ($checkpoint['oom_events'] ?? null)
            && $unsigned($rawParts[5] ?? null) === ($checkpoint['oom_kill_events'] ?? null)
            && ($rawParts[6] ?? null) === ($checkpoint['container_id'] ?? null)
            && ($rawParts[7] ?? null) === ($checkpoint['container_started_at'] ?? null)
            && $unsigned($rawParts[8] ?? null) === ($checkpoint['container_host_pid'] ?? null)
            && $unsigned($rawParts[9] ?? null) === ($checkpoint['container_restart_count'] ?? null)
            && is_string($checkpoint['raw_sha256'] ?? null)
            && hash_equals(hash('sha256', $raw), $checkpoint['raw_sha256']);
        if (
            !is_string($label)
            || $label === ''
            || isset($seenLabels[$label])
            || !in_array($version, ['v1', 'v2'], true)
            || $version !== $expectedVersion
            || ($checkpoint['sources'] ?? null) !== $expectedSources
            || !is_int($checkpoint['usage_bytes'] ?? null)
            || $checkpoint['usage_bytes'] < 0
            || !is_int($checkpoint['peak_bytes'] ?? null)
            || $checkpoint['peak_bytes'] < 1
            || $checkpoint['peak_bytes'] < $checkpoint['usage_bytes']
            || $checkpoint['peak_bytes'] > 536870912
            || !is_int($checkpoint['limit_events'] ?? null)
            || $checkpoint['limit_events'] < 0
            || !is_int($checkpoint['oom_events'] ?? null)
            || $checkpoint['oom_events'] < 0
            || !is_int($checkpoint['oom_kill_events'] ?? null)
            || $checkpoint['oom_kill_events'] < 0
            || !$rawMatchesStructured
            || !wp_fts_wc_is_lowercase_sha256($checkpoint['raw_sha256'] ?? null)
            || ($checkpoint['container_id'] ?? null) !== $containerId
            || ($checkpoint['container_started_at'] ?? null) !== $containerLifecycle['started_at']
            || ($checkpoint['container_host_pid'] ?? null) !== $containerLifecycle['host_pid']
            || ($checkpoint['container_restart_count'] ?? null) !== $containerLifecycle['restart_count']
        ) {
            return false;
        }
        $seenLabels[$label] = true;
        $actualLabels[] = $label;
        $peaks[] = $checkpoint['peak_bytes'];
        $limitEvents[] = $checkpoint['limit_events'];
        $oomEvents[] = $checkpoint['oom_events'];
        $oomKills[] = $checkpoint['oom_kill_events'];
    }

    $first = $checkpoints[0];
    $final = $checkpoints[array_key_last($checkpoints)];
    $wholeRunPeak = max($peaks);

    return $actualLabels === $expectedLabels
        && ($memory['pre_corpus'] ?? null) === $first
        && ($memory['final_checkpoint'] ?? null) === $final
        && ($memory['whole_run_peak_bytes'] ?? null) === $wholeRunPeak
        && ($final['peak_bytes'] ?? null) === $wholeRunPeak
        && ($final['peak_bytes'] ?? 0) >= ($first['peak_bytes'] ?? PHP_INT_MAX)
        && ($memory['whole_run_headroom_bytes'] ?? null) === 536870912 - $wholeRunPeak
        && ($memory['max_limit_events'] ?? null) === max($limitEvents)
        && ($memory['oom_events'] ?? null) === max($oomEvents)
        && ($memory['oom_kill_events'] ?? null) === max($oomKills)
        && max($limitEvents) === 0
        && max($oomEvents) === 0
        && max($oomKills) === 0;
}

/**
 * @param array<string,mixed> $package
 * @param array<string,mixed> $validationEvidence
 */
function wp_fts_wc_package_reproducibility_is_exact(array $package, array $validationEvidence): bool
{
    $primary = is_array($package['primary'] ?? null) ? $package['primary'] : [];
    $secondary = is_array($package['secondary'] ?? null) ? $package['secondary'] : [];
    $primaryManifest = is_array($primary['manifest'] ?? null) ? $primary['manifest'] : [];
    $secondaryManifest = is_array($secondary['manifest'] ?? null) ? $secondary['manifest'] : [];
    $toolchain = is_array($package['toolchain'] ?? null) ? $package['toolchain'] : [];
    $isolation = is_array($package['build_isolation'] ?? null) ? $package['build_isolation'] : [];
    $gates = is_array($package['gates'] ?? null) ? array_values($package['gates']) : [];
    $expectedGateIds = [
        'independent_build_zip_bytes_identical',
        'independent_build_entry_manifests_identical',
        'independent_build_entries_ordered_unique',
        'independent_build_reports_match_archives',
        'package_toolchain_recorded',
        'package_builds_use_fresh_composer_state',
    ];
    $actualGateIds = [];
    $gateById = [];
    foreach ($gates as $gate) {
        if (
            !is_array($gate)
            || !is_string($gate['id'] ?? null)
            || !array_key_exists('expected', $gate)
            || !array_key_exists('actual', $gate)
            || ($gate['passed'] ?? null) !== true
        ) {
            return false;
        }
        $actualGateIds[] = $gate['id'];
        $gateById[$gate['id']] = $gate;
    }

    $primaryEntries = is_array($primaryManifest['entries'] ?? null) ? array_values($primaryManifest['entries']) : [];
    $entryNames = [];
    foreach ($primaryEntries as $entry) {
        if (
            !is_array($entry)
            || !is_string($entry['name'] ?? null)
            || ($entry['name'] ?? '') === ''
            || str_ends_with((string) $entry['name'], '/')
            || !is_int($entry['bytes'] ?? null)
            || (int) $entry['bytes'] < 0
            || !wp_fts_wc_is_lowercase_sha256($entry['content_sha256'] ?? null)
            || !is_string($entry['crc32'] ?? null)
            || !wp_fts_wc_is_ascii_digits((string) $entry['crc32'])
            || !is_int($entry['compressed_bytes'] ?? null)
            || (int) $entry['compressed_bytes'] < 0
            || !is_int($entry['compression_method'] ?? null)
            || (int) $entry['compression_method'] < 0
            || ($entry['mtime'] ?? null) !== 946684800
            || ($entry['opsys'] ?? null) !== ZipArchive::OPSYS_UNIX
            || !is_int($entry['external_attributes'] ?? null)
            || (((int) $entry['external_attributes'] >> 16) & 0xffff) !== (str_ends_with((string) $entry['name'], '.sh') ? 0100755 : 0100644)
        ) {
            return false;
        }
        $pathParts = explode('/', (string) $entry['name']);
        if (
            !str_starts_with((string) $entry['name'], 'indexer/')
            || str_contains((string) $entry['name'], '\\')
            || in_array('.', $pathParts, true)
            || in_array('..', $pathParts, true)
        ) {
            return false;
        }
        $entryNames[] = $entry['name'];
    }
    $sortedNames = $entryNames;
    sort($sortedNames, SORT_STRING);
    $primaryManifestHash = wp_fts_wc_canonical_hash($primaryManifest);
    $secondaryManifestHash = wp_fts_wc_canonical_hash($secondaryManifest);
    $hashInput = $package;
    $recordedEvidenceHash = $hashInput['evidence_sha256'] ?? null;
    unset($hashInput['evidence_sha256']);
    $composerState = is_array($gateById['package_builds_use_fresh_composer_state']['actual'] ?? null)
        ? $gateById['package_builds_use_fresh_composer_state']['actual']
        : [];
    $primaryHome = $composerState['primary_home'] ?? null;
    $secondaryHome = $composerState['secondary_home'] ?? null;
    $primaryCache = $composerState['primary_cache'] ?? null;
    $secondaryCache = $composerState['secondary_cache'] ?? null;
    $composerStateValid = is_string($primaryHome)
        && is_string($secondaryHome)
        && is_string($primaryCache)
        && is_string($secondaryCache)
        && str_ends_with($primaryHome, '/composer-home')
        && str_ends_with($secondaryHome, '/composer-home')
        && str_ends_with($primaryCache, '/composer-cache')
        && str_ends_with($secondaryCache, '/composer-cache')
        && dirname($primaryHome) === dirname($primaryCache)
        && dirname($secondaryHome) === dirname($secondaryCache)
        && dirname($primaryHome) !== dirname($secondaryHome)
        && ($composerState['plugins'] ?? null) === [false, false]
        && ($composerState['scripts'] ?? null) === [false, false];
    $phpVersionParts = is_string($toolchain['php_version'] ?? null)
        ? explode('.', (string) $toolchain['php_version'])
        : [];
    $phpVersionIsStable84 = count($phpVersionParts) === 3
        && $phpVersionParts[0] === '8'
        && $phpVersionParts[1] === '4'
        && wp_fts_wc_is_ascii_digits($phpVersionParts[2]);
    $toolchainValid = ($toolchain['php_sapi'] ?? null) === 'cli'
        && is_string($toolchain['php_version'] ?? null)
        && (string) $toolchain['php_version'] !== ''
        && is_string($toolchain['zip_extension_version'] ?? null)
        && (string) $toolchain['zip_extension_version'] !== ''
        && is_string($toolchain['libzip_version'] ?? null)
        && (string) $toolchain['libzip_version'] !== ''
        && is_string($toolchain['zlib_version'] ?? null)
        && (string) $toolchain['zlib_version'] !== ''
        && is_string($toolchain['composer_version'] ?? null)
        && (string) $toolchain['composer_version'] !== ''
        && wp_fts_wc_is_lowercase_sha256($toolchain['php_binary_sha256'] ?? null)
        && wp_fts_wc_is_lowercase_sha256($toolchain['composer_binary_sha256'] ?? null)
        && (
            ($validationEvidence['acceptance_lane'] ?? null) !== true
            || (
                $phpVersionIsStable84
                && str_starts_with((string) $toolchain['composer_version'], 'Composer version 2.9.8 ')
            )
        );
    $gateSemanticsValid = ($gateById['independent_build_zip_bytes_identical']['expected'] ?? null) === ($primary['zip_sha256'] ?? null)
        && ($gateById['independent_build_zip_bytes_identical']['actual'] ?? null) === ($secondary['zip_sha256'] ?? null)
        && ($gateById['independent_build_entry_manifests_identical']['expected'] ?? null) === $primaryManifestHash
        && ($gateById['independent_build_entry_manifests_identical']['actual'] ?? null) === $secondaryManifestHash
        && ($gateById['independent_build_entries_ordered_unique']['expected'] ?? null) === true
        && ($gateById['independent_build_entries_ordered_unique']['actual'] ?? null) === [true, true]
        && ($gateById['independent_build_reports_match_archives']['expected'] ?? null) === [
            $primary['zip_sha256'] ?? null,
            $secondary['zip_sha256'] ?? null,
        ]
        && ($gateById['independent_build_reports_match_archives']['actual'] ?? null) === [
            $primary['zip_sha256'] ?? null,
            $secondary['zip_sha256'] ?? null,
        ]
        && ($gateById['package_toolchain_recorded']['expected'] ?? null) === 'complete version and binary identities'
        && ($gateById['package_toolchain_recorded']['actual'] ?? null) === $toolchain
        && ($gateById['package_builds_use_fresh_composer_state']['expected'] ?? null) === 'independent homes and caches; plugins/scripts disabled'
        && $composerStateValid;

    return ($package['schema'] ?? null) === 'relational-fts-package-reproducibility-v1'
        && ($package['status'] ?? null) === 'PASS'
        && ($package['source_sha'] ?? null) === ($validationEvidence['source_sha'] ?? null)
        && ($primary['zip_sha256'] ?? null) === ($validationEvidence['zip_sha256'] ?? null)
        && ($secondary['zip_sha256'] ?? null) === ($primary['zip_sha256'] ?? null)
        && wp_fts_wc_is_lowercase_sha256($primary['zip_sha256'] ?? null)
        && ($primary['entry_manifest_sha256'] ?? null) === $primaryManifestHash
        && ($secondary['entry_manifest_sha256'] ?? null) === $secondaryManifestHash
        && hash_equals($primaryManifestHash, $secondaryManifestHash)
        && $primaryManifest === $secondaryManifest
        && ($primaryManifest['entry_count'] ?? null) === count($primaryEntries)
        && count($primaryEntries) > 0
        && ($primaryManifest['ordered_unique_names'] ?? null) === true
        && $entryNames === $sortedNames
        && count(array_unique($entryNames)) === count($entryNames)
        && $actualGateIds === $expectedGateIds
        && count(array_unique($actualGateIds)) === count($actualGateIds)
        && $gateSemanticsValid
        && $isolation === [
            'build_directories' => 'independent',
            'composer_homes' => 'fresh-per-build',
            'composer_caches' => 'fresh-per-build',
            'composer_plugins' => 'disabled',
            'composer_scripts' => 'disabled',
        ]
        && $toolchainValid
        && wp_fts_wc_is_lowercase_sha256($recordedEvidenceHash)
        && hash_equals(wp_fts_wc_canonical_hash($hashInput), (string) $recordedEvidenceHash);
}

/** @param array<string,mixed> $image */
function wp_fts_wc_resource_image_is_exact(
    array $image,
    string $expectedReference,
    bool $requireAcceptanceDigest
): bool
{
    $separator = strpos($expectedReference, '@');
    $expectedDigest = $separator === false ? '' : substr($expectedReference, $separator + 1);
    $manifestDigests = is_array($image['actual_manifest_digests'] ?? null)
        ? array_values($image['actual_manifest_digests'])
        : [];
    $repoDigests = is_array($image['actual_repo_digests'] ?? null)
        ? array_values($image['actual_repo_digests'])
        : [];
    $manifestDigestsValid = count(array_filter(
        $manifestDigests,
        static fn(mixed $digest): bool => wp_fts_wc_is_lowercase_sha256($digest, 'sha256:')
    )) === count($manifestDigests);
    $repoDigestsValid = count(array_filter($repoDigests, static function (mixed $digest): bool {
        if (!is_string($digest)) {
            return false;
        }
        $separator = strrpos($digest, '@');

        return $separator !== false
            && wp_fts_wc_is_lowercase_sha256(substr($digest, $separator + 1), 'sha256:');
    })) === count($repoDigests);
    $selectedReference = $image['selected_reference'] ?? null;
    $matchesExpected = is_string($selectedReference)
        && $selectedReference === $expectedReference
        && in_array($expectedDigest, $manifestDigests, true);

    return ($image['expected_reference'] ?? null) === $expectedReference
        && is_string($selectedReference)
        && $selectedReference !== ''
        && ($image['expected_manifest_digest'] ?? null) === $expectedDigest
        && wp_fts_wc_is_lowercase_sha256($expectedDigest, 'sha256:')
        && $manifestDigestsValid
        && $repoDigestsValid
        && wp_fts_wc_is_lowercase_sha256($image['actual_image_id'] ?? null, 'sha256:')
        && wp_fts_wc_is_lowercase_sha256($image['running_container_image_id'] ?? null, 'sha256:')
        && ($image['running_container_image_id'] ?? null) === ($image['actual_image_id'] ?? null)
        && ($image['container_matches_inspected_image'] ?? null) === true
        && ($image['matches_expected'] ?? null) === $matchesExpected
        && (!$requireAcceptanceDigest || $matchesExpected);
}

/** @param array<string,mixed> $cgroup */
function wp_fts_wc_resource_cgroup_is_exact(array $cgroup, int $expectedMemoryBytes): bool
{
    $cpu = is_array($cgroup['cpu'] ?? null) ? $cgroup['cpu'] : [];
    $memory = is_array($cgroup['memory'] ?? null) ? $cgroup['memory'] : [];
    $swap = is_array($cgroup['swap'] ?? null) ? $cgroup['swap'] : [];
    $quota = $cpu['quota_us'] ?? null;
    $period = $cpu['period_us'] ?? null;
    $effective = $cpu['effective_cpus'] ?? null;
    $raw = $cgroup['raw'] ?? null;
    $rawParts = is_string($raw) ? explode("\t", $raw) : [];
    $unsigned = static fn(mixed $value): ?int => is_string($value)
        && $value !== ''
        && strspn($value, '0123456789') === strlen($value)
            ? (int) $value
            : null;
    $rawVersion = $rawParts[0] ?? null;
    $rawQuota = $unsigned($rawParts[1] ?? null);
    $rawPeriod = $unsigned($rawParts[2] ?? null);
    $rawMemory = $unsigned($rawParts[3] ?? null);
    $rawSwap = $unsigned($rawParts[4] ?? null);
    $rawEffectiveSwap = $rawVersion === 'v1' && $rawSwap !== null && $rawMemory !== null
        ? $rawSwap - $rawMemory
        : $rawSwap;
    $rawCpuMatches = $rawQuota !== null && $rawQuota > 0 && $rawPeriod !== null && $rawQuota === $rawPeriod;
    $rawMemoryMatches = $rawMemory === $expectedMemoryBytes;
    $rawSwapMatches = $rawEffectiveSwap === 0;
    $rawMatchesStructured = count($rawParts) === 5
        && in_array($rawVersion, ['v1', 'v2'], true)
        && $rawQuota !== null
        && $rawPeriod !== null
        && $rawPeriod > 0
        && $rawMemory !== null
        && $rawSwap !== null
        && ($cgroup['version'] ?? null) === $rawVersion
        && $quota === $rawQuota
        && $period === $rawPeriod
        && is_numeric($effective)
        && (float) $effective === (float) ($rawQuota / $rawPeriod)
        && ($cpu['matches_expected'] ?? null) === $rawCpuMatches
        && ($memory['max_bytes'] ?? null) === $rawMemory
        && ($memory['matches_expected'] ?? null) === $rawMemoryMatches
        && ($swap['raw_max_bytes'] ?? null) === $rawSwap
        && ($swap['effective_max_bytes'] ?? null) === $rawEffectiveSwap
        && ($swap['matches_expected'] ?? null) === $rawSwapMatches
        && is_string($cgroup['raw_sha256'] ?? null)
        && hash_equals(hash('sha256', $raw), $cgroup['raw_sha256'])
        && ($cgroup['matches_expected'] ?? null) === ($rawCpuMatches && $rawMemoryMatches && $rawSwapMatches);

    return $rawMatchesStructured
        && in_array($cgroup['version'] ?? null, ['v1', 'v2'], true)
        && is_int($quota)
        && $quota > 0
        && is_int($period)
        && $period > 0
        && $quota === $period
        && is_numeric($effective)
        && (float) $effective === 1.0
        && ($cpu['matches_expected'] ?? null) === true
        && ($memory['max_bytes'] ?? null) === $expectedMemoryBytes
        && ($memory['matches_expected'] ?? null) === true
        && ($swap['effective_max_bytes'] ?? null) === 0
        && ($swap['matches_expected'] ?? null) === true
        && wp_fts_wc_is_lowercase_sha256($cgroup['raw_sha256'] ?? null)
        && ($cgroup['matches_expected'] ?? null) === true;
}

/** The mutation artifact is invalid if any cross-process proof field is absent. */
function wp_fts_wc_mutation_cross_process_guard_valid(array $mutation): bool
{
    $proof = is_array($mutation['cross_process_foreground_guard'] ?? null)
        ? $mutation['cross_process_foreground_guard']
        : [];
    $expectedKeys = [
        'schema', 'status', 'parent_pid', 'holder_pid', 'holder_runtime_pid', 'process_is_independent',
        'holder_queue_path', 'holder_queue_sha256', 'parent_queue_sha256', 'holder_proof_sha256',
        'holder_lock_path', 'parent_lock_path', 'holder_lock_device', 'parent_lock_device',
        'holder_lock_inode', 'parent_lock_inode', 'same_lock_file', 'parent_static_guard_count',
        'seeded_post_ids', 'seeded_states', 'optimizer_noise_rows', 'optimizer_noise_due_at',
        'busy_probe_state', 'busy_claimed_post_ids', 'busy_protected_states',
        'busy_claim_guarded_predicate_count', 'busy_claim_fenced_predicate_count', 'busy_claim',
        'busy_schedule_probe_state', 'busy_next_available', 'busy_watchdog_min', 'busy_watchdog_max',
        'busy_schedule_guarded_predicate_count', 'busy_schedule_fenced_predicate_count', 'busy_schedule',
        'holder_alive_after_busy_queries', 'kill_signal_requested', 'kill_observed',
        'kill_observed_signal', 'process_reaped', 'free_probe_state', 'free_claimed_post_ids',
        'free_claim_guarded_predicate_count', 'free_claim_fenced_predicate_count', 'free_claim',
        'fenced_state_after_free_claim', 'free_schedule_probe_state', 'free_next_available',
        'free_schedule_guarded_predicate_count', 'free_schedule_fenced_predicate_count', 'free_schedule',
        'promoted_fenced_claimed_post_ids', 'promoted_fenced_claim',
    ];
    if (array_keys($proof) !== $expectedKeys) {
        return false;
    }
    $seededStates = [
        ['post_id' => 45, 'generation' => 1, 'state' => 'guarded', 'claimed_generation' => 1, 'token_class' => 'guard'],
        ['post_id' => 46, 'generation' => 1, 'state' => 'fenced', 'claimed_generation' => 1, 'token_class' => 'unmarked'],
        ['post_id' => 47, 'generation' => 1, 'state' => 'ready', 'claimed_generation' => 0, 'token_class' => 'empty'],
    ];
    $protectedStates = array_slice($seededStates, 0, 2);
    $fencedState = [$seededStates[1]];
    $busyMin = $proof['busy_watchdog_min'];
    $busyMax = $proof['busy_watchdog_max'];
    $busyNext = $proof['busy_next_available'];
    $noiseDue = $proof['optimizer_noise_due_at'];

    return ($proof['schema'] ?? null) === 'relational-fts-cross-process-owner-guard-v1'
        && ($proof['status'] ?? null) === 'PASS'
        && is_int($proof['parent_pid'])
        && $proof['parent_pid'] > 0
        && is_int($proof['holder_pid'])
        && $proof['holder_pid'] > 0
        && $proof['holder_pid'] !== $proof['parent_pid']
        && $proof['holder_runtime_pid'] === $proof['holder_pid']
        && $proof['process_is_independent'] === true
        && is_string($proof['holder_queue_path'])
        && $proof['holder_queue_path'] !== ''
        && wp_fts_wc_is_lowercase_sha256($proof['holder_queue_sha256'])
        && $proof['parent_queue_sha256'] === $proof['holder_queue_sha256']
        && wp_fts_wc_is_lowercase_sha256($proof['holder_proof_sha256'])
        && ($mutation['proof_sha256'] ?? null) === $proof['holder_proof_sha256']
        && is_string($proof['holder_lock_path'])
        && $proof['holder_lock_path'] !== ''
        && $proof['parent_lock_path'] === $proof['holder_lock_path']
        && is_int($proof['holder_lock_device'])
        && $proof['holder_lock_device'] >= 0
        && $proof['parent_lock_device'] === $proof['holder_lock_device']
        && is_int($proof['holder_lock_inode'])
        && $proof['holder_lock_inode'] > 0
        && $proof['parent_lock_inode'] === $proof['holder_lock_inode']
        && $proof['same_lock_file'] === true
        && $proof['parent_static_guard_count'] === 0
        && $proof['seeded_post_ids'] === [45, 46, 47]
        && $proof['seeded_states'] === $seededStates
        && $proof['optimizer_noise_rows'] === 512
        && is_int($noiseDue)
        && $noiseDue > 0
        && $proof['busy_probe_state'] === 'busy'
        && $proof['busy_claimed_post_ids'] === [47]
        && $proof['busy_protected_states'] === $protectedStates
        && $proof['busy_claim_guarded_predicate_count'] === 0
        && $proof['busy_claim_fenced_predicate_count'] === 0
        && wp_fts_wc_mutation_guard_operation_valid(
            $proof['busy_claim'],
            2,
            400,
            ['ready', 'recoverable', 'PRIMARY', 'claim_token'],
            ['query', 'get_results'],
            'wp_fts:fences-require-free-guard'
        )
        && $proof['busy_schedule_probe_state'] === 'busy'
        && is_int($busyMin)
        && is_int($busyMax)
        && is_int($busyNext)
        && $busyMin <= $busyNext
        && $busyNext <= $busyMax
        && $noiseDue > $busyMax
        && $proof['busy_schedule_guarded_predicate_count'] === 2
        && $proof['busy_schedule_fenced_predicate_count'] === 2
        && wp_fts_wc_mutation_guard_operation_valid(
            $proof['busy_schedule'],
            1,
            12,
            ['ready', 'recoverable'],
            ['get_var'],
            'wp_fts:nonfree-fence-watchdog'
        )
        && $proof['holder_alive_after_busy_queries'] === true
        && $proof['kill_signal_requested'] === 9
        && $proof['kill_observed'] === true
        && $proof['kill_observed_signal'] === 9
        && $proof['process_reaped'] === true
        && $proof['free_probe_state'] === 'free'
        && $proof['free_claimed_post_ids'] === [45]
        && $proof['free_claim_guarded_predicate_count'] === 3
        && $proof['free_claim_fenced_predicate_count'] === 0
        && wp_fts_wc_mutation_guard_operation_valid(
            $proof['free_claim'],
            2,
            500,
            ['ready', 'recoverable', 'PRIMARY', 'claim_token'],
            ['query', 'get_results'],
            'wp_fts:only-guarded-fence-recovery'
        )
        && $proof['fenced_state_after_free_claim'] === $fencedState
        && $proof['free_schedule_probe_state'] === 'free'
        && $proof['free_next_available'] === $noiseDue
        && $proof['free_schedule_guarded_predicate_count'] === 2
        && $proof['free_schedule_fenced_predicate_count'] === 0
        && wp_fts_wc_mutation_guard_operation_valid(
            $proof['free_schedule'],
            1,
            10,
            ['ready', 'recoverable'],
            ['get_var'],
            'wp_fts:only-guarded-fence-recovery'
        )
        && $proof['promoted_fenced_claimed_post_ids'] === [46]
        && wp_fts_wc_mutation_guard_operation_valid(
            $proof['promoted_fenced_claim'],
            2,
            500,
            ['ready', 'recoverable', 'PRIMARY', 'claim_token'],
            ['query', 'get_results'],
            'wp_fts:only-guarded-fence-recovery'
        );
}

/** Verify one exact measured statement set and every recorded tabular plan row. */
function wp_fts_wc_mutation_guard_operation_valid(
    mixed $value,
    int $statementCount,
    int $candidateRowUpperBound,
    array $requiredPlanKeys,
    array $expectedMethods,
    string $requiredMarker
): bool {
    if (!is_array($value) || array_keys($value) !== [
        'statement_count', 'candidate_row_upper_bound', 'base_table', 'required_plan_keys',
        'observed_plan_keys', 'base_full_scan_count', 'statement_shape_sha256', 'statements',
    ]) {
        return false;
    }
    $baseTable = $value['base_table'];
    $statements = $value['statements'];
    if (
        $value['statement_count'] !== $statementCount
        || $value['candidate_row_upper_bound'] !== $candidateRowUpperBound
        || !is_string($baseTable)
        || $baseTable === ''
        || $value['required_plan_keys'] !== $requiredPlanKeys
        || $value['base_full_scan_count'] !== 0
        || !wp_fts_wc_is_lowercase_sha256($value['statement_shape_sha256'])
        || !is_array($statements)
        || count($statements) !== $statementCount
    ) {
        return false;
    }
    $observedPlanKeys = [];
    $shape = [];
    $redactedSql = '';
    foreach ($statements as $index => $statement) {
        if (!is_array($statement) || array_keys($statement) !== [
            'method', 'elapsed_ms', 'affected_rows', 'sql_bytes', 'sql_sha256', 'redacted_sql',
            'redacted_sql_bytes', 'redacted_sql_truncated', 'plan_row_count', 'plan_keys',
            'plan_max_estimated_rows', 'base_full_scan_count', 'plan',
        ]) {
            return false;
        }
        $plan = $statement['plan'];
        if (
            ($statement['method'] ?? null) !== ($expectedMethods[$index] ?? null)
            || (!is_int($statement['elapsed_ms']) && !is_float($statement['elapsed_ms']))
            || $statement['elapsed_ms'] < 0
            || !is_int($statement['affected_rows'])
            || !is_int($statement['sql_bytes'])
            || $statement['sql_bytes'] <= 0
            || !wp_fts_wc_is_lowercase_sha256($statement['sql_sha256'])
            || !is_string($statement['redacted_sql'])
            || $statement['redacted_sql'] === ''
            || !is_int($statement['redacted_sql_bytes'])
            || $statement['redacted_sql_bytes'] !== strlen($statement['redacted_sql'])
            || $statement['redacted_sql_bytes'] > 2048
            || !is_bool($statement['redacted_sql_truncated'])
            || ($statement['redacted_sql_truncated'] && $statement['redacted_sql_bytes'] !== 2048)
            || !is_array($plan)
            || $plan === []
            || $statement['plan_row_count'] !== count($plan)
            || !is_array($statement['plan_keys'])
            || !is_int($statement['plan_max_estimated_rows'])
            || $statement['plan_max_estimated_rows'] < 0
            || $statement['base_full_scan_count'] !== 0
        ) {
            return false;
        }
        $statementPlanKeys = [];
        $maxEstimatedRows = 0;
        $baseFullScans = 0;
        foreach ($plan as $planRow) {
            if (!is_array($planRow) || array_keys($planRow) !== [
                'select_type', 'table', 'access_type', 'possible_keys', 'key', 'key_len',
                'ref', 'rows', 'filtered', 'extra',
            ]) {
                return false;
            }
            $key = $planRow['key'];
            $optimizedEmptyArm = $planRow['table'] === ''
                && $planRow['access_type'] === ''
                && $planRow['rows'] === 0
                && str_contains(strtolower((string) $planRow['extra']), 'no matching row in const table');
            if (
                !is_string($planRow['select_type'])
                || $planRow['select_type'] === ''
                || !is_string($planRow['table'])
                || (!$optimizedEmptyArm && $planRow['table'] === '')
                || !is_string($planRow['access_type'])
                || (!$optimizedEmptyArm && $planRow['access_type'] === '')
                || (!is_null($planRow['possible_keys']) && !is_string($planRow['possible_keys']))
                || (!is_null($key) && !is_string($key))
                || (!is_null($planRow['key_len']) && !is_string($planRow['key_len']))
                || (!is_null($planRow['ref']) && !is_string($planRow['ref']))
                || !is_int($planRow['rows'])
                || $planRow['rows'] < 0
                || (!is_null($planRow['filtered']) && !is_int($planRow['filtered']) && !is_float($planRow['filtered']))
                || !is_string($planRow['extra'])
            ) {
                return false;
            }
            if (is_string($key) && $key !== '') {
                $statementPlanKeys[] = $key;
                $observedPlanKeys[] = $key;
            }
            if (
                $planRow['access_type'] === 'ALL'
                && ($planRow['table'] === $baseTable || $planRow['table'] === 'claim_target')
            ) {
                $baseFullScans++;
            }
            $maxEstimatedRows = max($maxEstimatedRows, $planRow['rows']);
        }
        $statementPlanKeys = array_values(array_unique($statementPlanKeys));
        if (
            $statement['plan_keys'] !== $statementPlanKeys
            || $statement['plan_max_estimated_rows'] !== $maxEstimatedRows
            || $baseFullScans !== 0
        ) {
            return false;
        }
        $shape[] = [
            'method' => $statement['method'],
            'sql_sha256' => $statement['sql_sha256'],
            'sql_bytes' => $statement['sql_bytes'],
            'plan_row_count' => $statement['plan_row_count'],
        ];
        $redactedSql .= "\n" . $statement['redacted_sql'];
    }
    $observedPlanKeys = array_values(array_unique($observedPlanKeys));
    foreach ($requiredPlanKeys as $requiredPlanKey) {
        if (!in_array($requiredPlanKey, $observedPlanKeys, true)) {
            return false;
        }
    }

    return $value['observed_plan_keys'] === $observedPlanKeys
        && hash_equals(
            $value['statement_shape_sha256'],
            hash('sha256', json_encode($shape, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR))
        )
        && str_contains($redactedSql, $requiredMarker);
}

/**
 * @param array<string,mixed> $mutation
 * @param array<string,mixed> $resources
 * @param array<string,mixed> $validationEvidence
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_mutation_artifact_gates(array $mutation, array $resources, array $validationEvidence): array
{
    $expectedBoundaryIds = [
        'a_fence_generation_1',
        'b_fence_generation_2',
        'a_stale_promote',
        'c_fence_generation_3',
        'b_stale_promote',
        'c_owned_promote',
        'crash_fence',
    ];
    $expectedCounts = array_fill_keys($expectedBoundaryIds, 1);
    $expectedFenceCounts = [
        'a_fence_generation_1' => 1,
        'b_fence_generation_2' => 1,
        'c_fence_generation_3' => 1,
        'crash_fence' => 1,
    ];
    $expectedPromotionCounts = [
        'a_stale_promote' => 1,
        'b_stale_promote' => 1,
        'c_owned_promote' => 1,
    ];
    $boundaries = is_array($mutation['boundary_statement_evidence'] ?? null)
        ? array_values($mutation['boundary_statement_evidence'])
        : [];
    $actualBoundaryIds = [];
    $actualBoundaryCounts = [];
    $invalidBoundaries = [];
    $forbiddenTokens = [
        str_repeat('a', 32),
        str_repeat('b', 32),
        str_repeat('c', 32),
        str_repeat('d', 32),
        str_repeat('e', 32),
    ];
    foreach ($boundaries as $index => $boundary) {
        if (!is_array($boundary)) {
            $invalidBoundaries[] = "{$index}:not-an-object";
            continue;
        }
        $boundaryId = is_string($boundary['boundary_id'] ?? null) ? (string) $boundary['boundary_id'] : '';
        $actualBoundaryIds[] = $boundaryId;
        $statements = is_array($boundary['statements'] ?? null) ? array_values($boundary['statements']) : [];
        $statementCount = $boundary['statement_count'] ?? null;
        $actualBoundaryCounts[$boundaryId] = $statementCount;
        $valid = $boundaryId !== ''
            && is_string($boundary['operation'] ?? null)
            && (string) $boundary['operation'] !== ''
            && is_string($boundary['outcome'] ?? null)
            && (string) $boundary['outcome'] !== ''
            && is_int($statementCount)
            && $statementCount === count($statements)
            && ($expectedCounts[$boundaryId] ?? null) === $statementCount;
        foreach ($statements as $statement) {
            if (!is_array($statement)) {
                $valid = false;
                continue;
            }
            $redacted = $statement['redacted_sql'] ?? null;
            $redactedBytes = $statement['redacted_sql_bytes'] ?? null;
            $containsToken = false;
            if (is_string($redacted)) {
                foreach ($forbiddenTokens as $token) {
                    $containsToken = $containsToken || str_contains($redacted, $token);
                }
            }
            $valid = $valid
                && in_array($statement['method'] ?? null, ['query', 'get_var', 'get_results'], true)
                && is_int($statement['sql_bytes'] ?? null)
                && (int) $statement['sql_bytes'] > 0
                && wp_fts_wc_is_lowercase_sha256($statement['sql_sha256'] ?? null)
                && is_string($redacted)
                && $redacted !== ''
                && is_int($redactedBytes)
                && $redactedBytes === strlen((string) $redacted)
                && $redactedBytes <= 2048
                && is_bool($statement['redacted_sql_truncated'] ?? null)
                && !$containsToken;
        }
        if (!$valid) {
            $invalidBoundaries[] = $boundaryId !== '' ? $boundaryId : "{$index}:missing-id";
        }
    }

    return [
        wp_fts_wc_gate(
            'mutation_statement_evidence_contract',
            ['relational-fts-mutation-generation-cas-v4', 'PASS', 'relational-fts-mutation-statements-v1', 2048, 7],
            [$mutation['schema'] ?? null, $mutation['status'] ?? null, $mutation['statement_evidence_schema'] ?? null, $mutation['statement_evidence_max_redacted_sql_bytes'] ?? null, $mutation['measured_boundary_count'] ?? null],
            ($mutation['schema'] ?? null) === 'relational-fts-mutation-generation-cas-v4'
                && ($mutation['status'] ?? null) === 'PASS'
                && ($mutation['statement_evidence_schema'] ?? null) === 'relational-fts-mutation-statements-v1'
                && ($mutation['statement_evidence_max_redacted_sql_bytes'] ?? null) === 2048
                && ($mutation['measured_boundary_count'] ?? null) === 7
                && count($boundaries) === 7
        ),
        wp_fts_wc_gate(
            'mutation_statement_evidence_binding',
            [$validationEvidence['engine'] ?? null, $validationEvidence['source_sha'] ?? null, $resources['mutation_proof_sha256'] ?? null],
            [$mutation['engine'] ?? null, $mutation['source_sha'] ?? null, $mutation['proof_sha256'] ?? null],
            ($mutation['engine'] ?? null) === ($validationEvidence['engine'] ?? null)
                && ($mutation['source_sha'] ?? null) === ($validationEvidence['source_sha'] ?? null)
                && wp_fts_wc_is_lowercase_sha256($resources['mutation_proof_sha256'] ?? null)
                && ($mutation['proof_sha256'] ?? null) === ($resources['mutation_proof_sha256'] ?? null)
        ),
        wp_fts_wc_gate('mutation_fence_boundary_statement_counts', $expectedFenceCounts, $mutation['fence_boundary_statement_counts'] ?? null, ($mutation['fence_boundary_statement_counts'] ?? null) === $expectedFenceCounts),
        wp_fts_wc_gate('mutation_promotion_boundary_statement_counts', $expectedPromotionCounts, $mutation['promotion_boundary_statement_counts'] ?? null, ($mutation['promotion_boundary_statement_counts'] ?? null) === $expectedPromotionCounts),
        wp_fts_wc_gate('mutation_boundary_statement_order', $expectedBoundaryIds, $actualBoundaryIds, $actualBoundaryIds === $expectedBoundaryIds),
        wp_fts_wc_gate('mutation_boundary_statement_counts', $expectedCounts, $actualBoundaryCounts, $actualBoundaryCounts === $expectedCounts),
        wp_fts_wc_gate('mutation_boundary_statement_payloads', [], $invalidBoundaries, $invalidBoundaries === []),
        wp_fts_wc_gate(
            'mutation_artifact_production_worker_sql_evidence_contract',
            ['relational-fts-mutation-worker-sql-v1', '<=32 statements', '<=1 MiB/statement', '<=4 MiB total', 'self-hash'],
            $mutation['production_worker_cas']['sql_evidence'] ?? null,
            wp_fts_wc_mutation_worker_sql_evidence_valid(
                is_array($mutation['production_worker_cas'] ?? null) ? $mutation['production_worker_cas'] : []
            )
        ),
        wp_fts_wc_gate(
            'mutation_artifact_cross_process_guard_contract',
            'independent source-bound holder, exact busy/free statements and EXPLAIN rows, fenced debt never auto-recovered',
            $mutation['cross_process_foreground_guard'] ?? null,
            wp_fts_wc_mutation_cross_process_guard_valid($mutation)
        ),
        wp_fts_wc_gate(
            'mutation_artifact_handoff_contract',
            [2, 3, 0, true],
            [
                $mutation['exact_handoff_statements'] ?? null,
                $mutation['max_owned_scope_corpus_handoff_statements'] ?? null,
                $mutation['handoff_tombstones_after_20_exact_requests'] ?? null,
                $mutation['ready_targeted_scope_preserved'] ?? null,
            ],
            ($mutation['exact_handoff_statements'] ?? null) === 2
                && ($mutation['max_owned_scope_corpus_handoff_statements'] ?? null) === 3
                && ($mutation['handoff_tombstones_after_20_exact_requests'] ?? null) === 0
                && ($mutation['ready_targeted_scope_preserved'] ?? null) === true
        ),
        wp_fts_wc_gate(
            'mutation_artifact_owned_scope_delete_contract',
            'one bounded primary-key/token CAS delete; stale ownership preserves the successor',
            [
                'owned' => $mutation['owned_scope_delete_proof'] ?? null,
                'stale' => $mutation['stale_owned_scope_cas_proof'] ?? null,
            ],
            wp_fts_wc_mutation_owned_scope_delete_proofs_valid($mutation)
        ),
        wp_fts_wc_gate(
            'mutation_artifact_corpus_publication_contract',
            'both max-shape handoffs publish one canonical corpus generation and delete their exact request sentinel',
            $mutation['corpus_handoff_publication_proofs'] ?? null,
            wp_fts_wc_mutation_corpus_publication_proofs_valid($mutation)
        ),
    ];
}

/** Validate the complete bounded production-worker SQL evidence envelope. */
function wp_fts_wc_mutation_worker_sql_evidence_valid(array $worker): bool
{
    $evidence = is_array($worker['sql_evidence'] ?? null) ? $worker['sql_evidence'] : [];
    if (
        array_keys($evidence) !== [
            'schema',
            'statement_count',
            'total_bytes',
            'max_statement_bytes',
            'statements',
            'evidence_sha256',
        ]
        || ($evidence['schema'] ?? null) !== 'relational-fts-mutation-worker-sql-v1'
        || !is_int($evidence['statement_count'] ?? null)
        || $evidence['statement_count'] < 1
        || $evidence['statement_count'] > 32
        || ($worker['captured_worker_statement_count'] ?? null) !== $evidence['statement_count']
        || !is_int($evidence['total_bytes'] ?? null)
        || $evidence['total_bytes'] < 1
        || $evidence['total_bytes'] > 4194304
        || !is_int($evidence['max_statement_bytes'] ?? null)
        || $evidence['max_statement_bytes'] < 1
        || $evidence['max_statement_bytes'] > 1048576
        || !is_array($evidence['statements'] ?? null)
        || !array_is_list($evidence['statements'])
        || count($evidence['statements']) !== $evidence['statement_count']
        || !wp_fts_wc_is_lowercase_sha256($evidence['evidence_sha256'] ?? null)
    ) {
        return false;
    }

    $totalBytes = 0;
    $maxStatementBytes = 0;
    $ackMatches = 0;
    foreach ($evidence['statements'] as $index => $statement) {
        if (
            !is_array($statement)
            || array_keys($statement) !== ['index', 'sql', 'bytes', 'sha256']
            || ($statement['index'] ?? null) !== $index
            || !is_string($statement['sql'] ?? null)
            || $statement['sql'] === ''
            || !is_int($statement['bytes'] ?? null)
            || $statement['bytes'] !== strlen($statement['sql'])
            || $statement['bytes'] < 1
            || $statement['bytes'] > 1048576
            || !wp_fts_wc_is_lowercase_sha256($statement['sha256'] ?? null)
            || !hash_equals($statement['sha256'], hash('sha256', $statement['sql']))
        ) {
            return false;
        }
        $totalBytes += $statement['bytes'];
        $maxStatementBytes = max($maxStatementBytes, $statement['bytes']);
        if (
            ($worker['atomic_ack_sql_bytes'] ?? null) === $statement['bytes']
            && is_string($worker['atomic_ack_sql_sha256'] ?? null)
            && hash_equals($worker['atomic_ack_sql_sha256'], $statement['sha256'])
        ) {
            $ackMatches++;
        }
    }
    if (
        $totalBytes !== $evidence['total_bytes']
        || $maxStatementBytes !== $evidence['max_statement_bytes']
        || ($worker['atomic_ack_statement_count'] ?? null) !== 1
        || $ackMatches !== 1
    ) {
        return false;
    }

    $recordedHash = $evidence['evidence_sha256'];
    unset($evidence['evidence_sha256']);

    return hash_equals($recordedHash, wp_fts_wc_canonical_hash($evidence));
}

/** @param array<string,mixed> $mutation */
function wp_fts_wc_mutation_owned_scope_delete_proofs_valid(array $mutation): bool
{
    $owned = is_array($mutation['owned_scope_delete_proof'] ?? null)
        ? $mutation['owned_scope_delete_proof']
        : [];
    $stale = is_array($mutation['stale_owned_scope_cas_proof'] ?? null)
        ? $mutation['stale_owned_scope_cas_proof']
        : [];

    return ($mutation['max_owned_scope_corpus_handoff_statements'] ?? null) === 3
        && ($owned['statement_count'] ?? null) === 1
        && ($owned['affected_rows'] ?? null) === 1
        && ($owned['residue_rows'] ?? null) === 0
        && is_int($owned['sql_bytes'] ?? null)
        && $owned['sql_bytes'] > 0
        && $owned['sql_bytes'] < 512
        && (is_int($owned['elapsed_ms'] ?? null) || is_float($owned['elapsed_ms'] ?? null))
        && $owned['elapsed_ms'] >= 0.0
        && wp_fts_wc_is_lowercase_sha256($owned['sql_sha256'] ?? null)
        && is_string($owned['plan_key'] ?? null)
        && strcasecmp($owned['plan_key'], 'PRIMARY') === 0
        && is_int($owned['plan_rows'] ?? null)
        && $owned['plan_rows'] >= 0
        && $owned['plan_rows'] <= 1
        && ($owned['uses_temporary'] ?? null) === false
        && ($owned['uses_filesort'] ?? null) === false
        && ($stale['handoff_statement_count'] ?? null) === 3
        && ($stale['delete_statement_count'] ?? null) === 1
        && ($stale['delete_affected_rows'] ?? null) === 0
        && is_int($stale['delete_sql_bytes'] ?? null)
        && $stale['delete_sql_bytes'] > 0
        && $stale['delete_sql_bytes'] < 512
        && (is_int($stale['delete_elapsed_ms'] ?? null) || is_float($stale['delete_elapsed_ms'] ?? null))
        && $stale['delete_elapsed_ms'] >= 0.0
        && ($stale['surviving_rows'] ?? null) === 1
        && ($stale['surviving_generation'] ?? null) === 2
        && ($stale['newer_payload_preserved'] ?? null) === true;
}

/** @param array<string,mixed> $mutation */
function wp_fts_wc_mutation_corpus_publication_proofs_valid(array $mutation): bool
{
    $proofs = is_array($mutation['corpus_handoff_publication_proofs'] ?? null)
        ? $mutation['corpus_handoff_publication_proofs']
        : [];
    if (array_keys($proofs) !== ['stale_owned_token', 'exact_owned_token']) {
        return false;
    }
    $expected = [
        'stale_owned_token' => ['generation' => 1, 'reason' => 'stale-token-global'],
        'exact_owned_token' => ['generation' => 2, 'reason' => 'global'],
    ];
    foreach ($expected as $id => $contract) {
        $proof = is_array($proofs[$id] ?? null) ? $proofs[$id] : [];
        $sentinelElapsed = $proof['sentinel_delete_elapsed_ms'] ?? null;
        if (
            ($proof['statement_count'] ?? null) !== 3
            || ($proof['canonical_upsert_statement_count'] ?? null) !== 1
            || !is_int($proof['canonical_upsert_sql_bytes'] ?? null)
            || $proof['canonical_upsert_sql_bytes'] <= 0
            || $proof['canonical_upsert_sql_bytes'] >= 1048576
            || !wp_fts_wc_is_lowercase_sha256($proof['canonical_upsert_sql_sha256'] ?? null)
            || ($proof['sentinel_delete_statement_count'] ?? null) !== 1
            || ($proof['sentinel_delete_affected_rows'] ?? null) !== 1
            || ($proof['sentinel_delete_residue_rows'] ?? null) !== 0
            || !is_int($proof['sentinel_delete_sql_bytes'] ?? null)
            || $proof['sentinel_delete_sql_bytes'] <= 0
            || $proof['sentinel_delete_sql_bytes'] >= 512
            || !wp_fts_wc_is_lowercase_sha256($proof['sentinel_delete_sql_sha256'] ?? null)
            || (!is_int($sentinelElapsed) && !is_float($sentinelElapsed))
            || $sentinelElapsed < 0
            || !is_string($proof['sentinel_delete_plan_key'] ?? null)
            || strcasecmp($proof['sentinel_delete_plan_key'], 'PRIMARY') !== 0
            || !is_int($proof['sentinel_delete_plan_rows'] ?? null)
            || $proof['sentinel_delete_plan_rows'] < 0
            || $proof['sentinel_delete_plan_rows'] > 1
            || ($proof['sentinel_delete_uses_temporary'] ?? null) !== false
            || ($proof['sentinel_delete_uses_filesort'] ?? null) !== false
            || ($proof['canonical_rows'] ?? null) !== 1
            || ($proof['canonical_generation'] ?? null) !== $contract['generation']
            || ($proof['canonical_state'] ?? null) !== 'ready'
            || ($proof['canonical_claim_token_empty'] ?? null) !== true
            || ($proof['canonical_scope_coverage'] ?? null) !== 'corpus'
            || ($proof['canonical_scope_incarnation'] ?? null) !== '0123456789abcdef0123456789abcdef'
            || ($proof['canonical_payload_reason'] ?? null) !== $contract['reason']
        ) {
            return false;
        }
    }

    return true;
}

/** Accepts only a nonempty sequence of ASCII decimal digits. */
function wp_fts_wc_is_ascii_digits(mixed $value): bool
{
    return is_string($value)
        && $value !== ''
        && strspn($value, '0123456789') === strlen($value);
}

/** Accepts only a nonempty sequence of ASCII hexadecimal digits. */
function wp_fts_wc_is_ascii_hex(mixed $value): bool
{
    return is_string($value)
        && $value !== ''
        && strspn($value, '0123456789abcdefABCDEF') === strlen($value);
}

/** Accept only the fixed-width lowercase search-generation identity. */
function wp_fts_wc_is_search_epoch_incarnation(mixed $value): bool
{
    return is_string($value) && preg_match('/^[a-f0-9]{32}$/D', $value) === 1;
}

/** Validate a prefixed lowercase SHA-256 without normalizing malformed evidence. */
function wp_fts_wc_is_lowercase_sha256(mixed $value, string $prefix = ''): bool
{
    if (!is_string($value) || !str_starts_with($value, $prefix)) {
        return false;
    }
    $digest = substr($value, strlen($prefix));

    return strlen($digest) === 64 && $digest === strtolower($digest) && wp_fts_wc_is_ascii_hex($digest);
}

/** Recompute nested proof hashes independently of the outer evidence helper. */
function wp_fts_wc_isolated_canonical_hash(mixed $value): string
{
    return hash('sha256', json_encode(
        wp_fts_wc_canonicalize($value),
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE | JSON_THROW_ON_ERROR
    ));
}

/**
 * Re-read every required fresh-process search artifact and reject any missing,
 * extra, rebound, rehashed, or process-reused case before final evidence merge.
 *
 * @param array<string,mixed> $validationEvidence
 * @return array<string,mixed>
 */
function wp_fts_wc_collect_authoritative_search_memory(array $validationEvidence): array
{
    $caseIds = wp_fts_wc_authoritative_search_memory_case_ids();
    $expectedFiles = array_map(static fn(string $caseId): string => "search-memory-{$caseId}.json", $caseIds);
    $directoryEntries = scandir(wp_fts_wc_evidence_dir());
    if (!is_array($directoryEntries)) {
        throw new RuntimeException('Could not enumerate authoritative search-memory artifacts.');
    }
    $actualFiles = [];
    foreach ($directoryEntries as $entry) {
        if (str_starts_with($entry, 'search-memory-') && str_ends_with($entry, '.json')) {
            $actualFiles[] = $entry;
        }
    }
    sort($expectedFiles, SORT_STRING);
    sort($actualFiles, SORT_STRING);
    $manifest = wp_fts_wc_manifest();
    $validationHash = (string) ($validationEvidence['evidence_sha256'] ?? '');
    $expectedBinding = wp_fts_wc_artifact_source_binding($manifest, $validationHash);
    $cases = [];
    $artifactHashes = [];
    $processIdentities = [];
    $selfHashesValid = true;
    $sourceBindingsValid = true;
    $measurementsValid = true;
    $caseGates = [];
    foreach ($caseIds as $caseId) {
        $filename = "search-memory-{$caseId}.json";
        $path = wp_fts_wc_evidence_dir() . '/' . $filename;
        $artifact = wp_fts_wc_read_json($path);
        $recordedHash = $artifact['evidence_sha256'] ?? null;
        $hashInput = $artifact;
        unset($hashInput['evidence_sha256']);
        $selfHashesValid = $selfHashesValid
            && wp_fts_wc_is_lowercase_sha256($recordedHash)
            && hash_equals(wp_fts_wc_canonical_hash($hashInput), (string) $recordedHash);
        $rawHash = hash_file('sha256', $path);
        if (!is_string($rawHash)) {
            throw new RuntimeException("Could not hash authoritative search-memory artifact: {$filename}");
        }
        $artifactHashes[$filename] = $rawHash;
        $expected = is_array($validationEvidence['cases'][$caseId] ?? null) ? $validationEvidence['cases'][$caseId] : [];
        $definition = wp_fts_wc_case_definitions($manifest)[$caseId] ?? null;
        $identity = is_array($artifact['process_identity'] ?? null) ? $artifact['process_identity'] : [];
        $identityHash = is_string($identity['sha256'] ?? null) ? (string) $identity['sha256'] : '';
        $processIdentities[$caseId] = $identityHash;
        $sourceBindingsValid = $sourceBindingsValid
            && array_intersect_key($artifact, $expectedBinding) === $expectedBinding
            && ($artifact['case'] ?? null) === $caseId
            && ($artifact['phase'] ?? null) === 'search-memory-sample'
            && ($artifact['schema'] ?? null) === 'relational-fts-search-memory-sample-v1'
            && ($artifact['case_definition_sha256'] ?? null) === wp_fts_wc_canonical_hash($definition)
            && wp_fts_wc_process_identity_valid($identity);
        $measurementsValid = $measurementsValid
            && ($artifact['measurement_method'] ?? null) === 'fresh_process_conservative_peak_attribution'
            && ($artifact['php_peak_delta_authoritative'] ?? null) === true
            && ($artifact['rss_peak_delta_authoritative'] ?? null) === true
            && ($artifact['rss_source'] ?? null) === 'linux_proc_status'
            && is_int($artifact['php_usage_before_bytes'] ?? null)
            && is_int($artifact['php_lifetime_peak_before_reset_bytes'] ?? null)
            && is_int($artifact['php_phase_peak_after_reset_bytes'] ?? null)
            && is_int($artifact['php_peak_bytes'] ?? null)
            && is_int($artifact['php_peak_delta_bytes'] ?? null)
            && $artifact['php_usage_before_bytes'] > 0
            && $artifact['php_phase_peak_after_reset_bytes'] >= $artifact['php_usage_before_bytes']
            && $artifact['php_peak_delta_bytes'] === max(0, $artifact['php_phase_peak_after_reset_bytes'] - $artifact['php_usage_before_bytes'])
            && $artifact['php_peak_delta_bytes'] <= 16777216
            && $artifact['php_peak_bytes'] === max($artifact['php_lifetime_peak_before_reset_bytes'], $artifact['php_phase_peak_after_reset_bytes'])
            && $artifact['php_peak_bytes'] > 0
            && $artifact['php_peak_bytes'] <= 134217728
            && is_int($artifact['php_usage_after_bytes'] ?? null)
            && is_int($artifact['php_delta_bytes'] ?? null)
            && $artifact['php_usage_after_bytes'] > 0
            && $artifact['php_delta_bytes'] === max(0, $artifact['php_usage_after_bytes'] - $artifact['php_usage_before_bytes'])
            && $artifact['php_delta_bytes'] <= 16777216
            && is_int($artifact['rss_before_bytes'] ?? null)
            && is_int($artifact['rss_after_bytes'] ?? null)
            && is_int($artifact['rss_peak_bytes'] ?? null)
            && is_int($artifact['rss_peak_delta_bytes'] ?? null)
            && $artifact['rss_before_bytes'] > 0
            && $artifact['rss_after_bytes'] > 0
            && $artifact['rss_peak_bytes'] >= $artifact['rss_before_bytes']
            && $artifact['rss_peak_delta_bytes'] === max(0, $artifact['rss_peak_bytes'] - $artifact['rss_before_bytes'])
            && $artifact['rss_peak_delta_bytes'] <= 16777216
            && $artifact['rss_peak_bytes'] > 0
            && $artifact['rss_peak_bytes'] <= 134217728
            && is_int($artifact['rss_delta_bytes'] ?? null)
            && $artifact['rss_delta_bytes'] === max(0, $artifact['rss_after_bytes'] - $artifact['rss_before_bytes'])
            && $artifact['rss_delta_bytes'] <= 16777216
            && ($artifact['result_ids'] ?? null) === ($expected['result_ids'] ?? null)
            && ($artifact['result_hash'] ?? null) === ($expected['result_hash'] ?? null)
            && ($artifact['result_score_signature'] ?? null) === ($expected['result_score_signature'] ?? null)
            && ($artifact['query_count'] ?? null) === ($expected['max_total_query_count'] ?? null)
            && ($artifact['statement_shape'] ?? null) === ($expected['statement_shape'] ?? null);
        array_push($caseGates, ...wp_fts_wc_require_evidence_gates(
            $artifact,
            "authoritative search-memory {$caseId}",
            wp_fts_wc_authoritative_search_memory_gate_ids($caseId),
            'relational-fts-search-memory-sample-v1'
        ));
        $cases[$caseId] = $artifact;
    }
    ksort($artifactHashes, SORT_STRING);
    $uniqueProcesses = array_values(array_unique(array_values($processIdentities)));
    $gates = [
        wp_fts_wc_gate('authoritative_search_memory_artifact_inventory', $expectedFiles, $actualFiles, $actualFiles === $expectedFiles),
        wp_fts_wc_gate('authoritative_search_memory_case_inventory', $caseIds, array_keys($cases), array_keys($cases) === $caseIds),
        wp_fts_wc_gate('authoritative_search_memory_distinct_fresh_processes', count($caseIds), count($uniqueProcesses), !in_array('', $uniqueProcesses, true) && count($uniqueProcesses) === count($caseIds)),
        wp_fts_wc_gate('authoritative_search_memory_artifact_self_hashes', count($caseIds), count($artifactHashes), $selfHashesValid && count($artifactHashes) === count($caseIds)),
        wp_fts_wc_gate('authoritative_search_memory_source_bindings', $expectedBinding, array_map(static fn(array $artifact): array => array_intersect_key($artifact, $expectedBinding), $cases), $sourceBindingsValid),
        wp_fts_wc_gate('authoritative_search_memory_measurement_inventory', 'all thirteen fresh-process formulas, absolute peaks, result hashes, and SQL shapes', count($cases), $measurementsValid && count($cases) === count($caseIds)),
        ...$caseGates,
    ];
    $result = [
        'schema' => 'relational-fts-authoritative-search-memory-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'case_ids' => $caseIds,
        'artifact_files' => $actualFiles,
        'artifact_sha256' => $artifactHashes,
        'process_identities' => $processIdentities,
        'cases' => $cases,
        'gates' => $gates,
    ];
    $result['evidence_sha256'] = wp_fts_wc_canonical_hash($result);
    if (!wp_fts_wc_authoritative_search_memory_inventory_matches($result)) {
        throw new RuntimeException('Authoritative search-memory evidence does not match its exact case/artifact/gate inventory.');
    }

    return $result;
}

/** Reject self-rehashed aggregate evidence after any required memory proof shrinks. */
function wp_fts_wc_authoritative_search_memory_inventory_matches(array $evidence): bool
{
    $caseIds = wp_fts_wc_authoritative_search_memory_case_ids();
    $expectedFiles = array_map(static fn(string $caseId): string => "search-memory-{$caseId}.json", $caseIds);
    sort($expectedFiles, SORT_STRING);
    $expectedGateIds = [
        'authoritative_search_memory_artifact_inventory',
        'authoritative_search_memory_case_inventory',
        'authoritative_search_memory_distinct_fresh_processes',
        'authoritative_search_memory_artifact_self_hashes',
        'authoritative_search_memory_source_bindings',
        'authoritative_search_memory_measurement_inventory',
    ];
    foreach ($caseIds as $caseId) {
        array_push($expectedGateIds, ...wp_fts_wc_authoritative_search_memory_gate_ids($caseId));
    }
    $gates = is_array($evidence['gates'] ?? null) ? array_values($evidence['gates']) : [];
    $gateIds = array_map(static fn(mixed $gate): string => is_array($gate) && is_string($gate['id'] ?? null) ? $gate['id'] : '', $gates);
    $hashInput = $evidence;
    $recordedHash = $hashInput['evidence_sha256'] ?? null;
    unset($hashInput['evidence_sha256']);

    return array_keys($evidence) === ['schema', 'status', 'case_ids', 'artifact_files', 'artifact_sha256', 'process_identities', 'cases', 'gates', 'evidence_sha256']
        && ($evidence['schema'] ?? null) === 'relational-fts-authoritative-search-memory-v1'
        && ($evidence['status'] ?? null) === 'PASS'
        && ($evidence['case_ids'] ?? null) === $caseIds
        && ($evidence['artifact_files'] ?? null) === $expectedFiles
        && array_keys(is_array($evidence['artifact_sha256'] ?? null) ? $evidence['artifact_sha256'] : []) === $expectedFiles
        && array_keys(is_array($evidence['process_identities'] ?? null) ? $evidence['process_identities'] : []) === $caseIds
        && count(array_unique(array_values($evidence['process_identities']))) === count($caseIds)
        && !in_array('', $evidence['process_identities'], true)
        && array_keys(is_array($evidence['cases'] ?? null) ? $evidence['cases'] : []) === $caseIds
        && $gateIds === $expectedGateIds
        && count(array_unique($gateIds)) === count($gateIds)
        && wp_fts_wc_gates_pass($gates)
        && wp_fts_wc_is_lowercase_sha256($recordedHash)
        && hash_equals(wp_fts_wc_canonical_hash($hashInput), (string) $recordedHash);
}

/**
 * @param array<string,mixed> $evidence
 * @return array{conditioning:array<string,mixed>,samples:array<string,array<int,array<string,mixed>>>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_collect_cold_evidence(array $evidence): array
{
    $count = WP_FTS_WC_COLD_SAMPLE_COUNT;
    $limits = ['common_or' => 2000.0, 'max_valid_or_prefix' => 4000.0, 'rare_anchor_and' => 500.0, 'prefix_fanout' => 2000.0];
    $samples = [];
    $processIdentities = [];
    $artifactSelfHashesValid = true;
    $sourceBindingsValid = true;
    $manifest = wp_fts_wc_manifest();
    $expectedBinding = wp_fts_wc_artifact_source_binding($manifest, (string) ($evidence['evidence_sha256'] ?? ''));
    $definitions = wp_fts_wc_case_definitions($manifest);
    $expectedSampleFiles = [];
    foreach (array_keys($limits) as $caseId) {
        for ($sample = 0; $sample < $count; $sample++) {
            $expectedSampleFiles[] = "cold-{$caseId}-{$sample}.json";
        }
    }
    $actualSampleFiles = [];
    $directoryEntries = scandir(wp_fts_wc_evidence_dir());
    if (!is_array($directoryEntries)) {
        throw new RuntimeException('Could not enumerate cold-sample artifacts.');
    }
    foreach ($directoryEntries as $entry) {
        if (str_starts_with($entry, 'cold-') && str_ends_with($entry, '.json') && $entry !== 'cold-eviction.json' && $entry !== 'cold-ready-request.json') {
            $actualSampleFiles[] = $entry;
        }
    }
    sort($expectedSampleFiles, SORT_STRING);
    sort($actualSampleFiles, SORT_STRING);
    $conditioning = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . '/cold-eviction.json');
    $gates = wp_fts_wc_require_evidence_gates(
        $conditioning,
        'cold-eviction lifecycle',
        ['cold_eviction_rows', 'cold_eviction_logical_bytes', 'cold_eviction_buffer_pool_ratio', 'cold_eviction_payload_checksum_present', 'cold_eviction_plan_reads_payload_relation', 'cold_eviction_relation_cleaned'],
        'relational-fts-cold-eviction-v1'
    );
    foreach ($limits as $caseId => $limit) {
        for ($sample = 0; $sample < $count; $sample++) {
            $row = wp_fts_wc_read_json(wp_fts_wc_evidence_dir() . "/cold-{$caseId}-{$sample}.json");
            $recordedHash = $row['evidence_sha256'] ?? null;
            $hashInput = $row;
            unset($hashInput['evidence_sha256']);
            $artifactSelfHashesValid = $artifactSelfHashesValid
                && wp_fts_wc_is_lowercase_sha256($recordedHash)
                && hash_equals(wp_fts_wc_canonical_hash($hashInput), (string) $recordedHash);
            $identity = is_array($row['process_identity'] ?? null) ? $row['process_identity'] : [];
            $processIdentities[] = is_string($identity['sha256'] ?? null) ? (string) $identity['sha256'] : '';
            $expectedCase = is_array($evidence['cases'][$caseId] ?? null) ? $evidence['cases'][$caseId] : [];
            if ($sample === 0) {
                $warmP99 = $expectedCase['latency_ms']['p99'] ?? null;
                if (!is_numeric($warmP99) || !is_finite((float) $warmP99) || (float) $warmP99 <= 0.0) {
                    throw new RuntimeException("Cold samples have no warm p99 reference for {$caseId}.");
                }
                $limit = max($limit, ceil((float) $warmP99 * 2.75));
            }
            $definition = is_array($definitions[$caseId] ?? null) ? $definitions[$caseId] : [];
            $sourceBindingsValid = $sourceBindingsValid
                && array_intersect_key($row, $expectedBinding) === $expectedBinding
                && ($row['case'] ?? null) === $caseId
                && ($row['sample'] ?? null) === $sample
                && ($row['case_definition_sha256'] ?? null) === wp_fts_wc_canonical_hash($definition)
                && ($row['result_ids'] ?? null) === ($expectedCase['result_ids'] ?? null)
                && ($row['result_hash'] ?? null) === ($expectedCase['result_hash'] ?? null)
                && ($row['result_score_signature'] ?? null) === ($expectedCase['result_score_signature'] ?? null)
                && ($row['query_count'] ?? null) === ($expectedCase['max_total_query_count'] ?? null)
                && ($row['statement_shape'] ?? null) === ($expectedCase['statement_shape'] ?? null)
                && ($row['measurement_method'] ?? null) === 'fresh_process_conservative_peak_attribution'
                && ($row['php_peak_delta_authoritative'] ?? null) === true
                && ($row['rss_peak_delta_authoritative'] ?? null) === true
                && ($row['rss_source'] ?? null) === 'linux_proc_status'
                && is_int($row['memory_before_bytes'] ?? null)
                && is_int($row['memory_after_bytes'] ?? null)
                && is_int($row['memory_delta_bytes'] ?? null)
                && is_int($row['php_lifetime_peak_before_reset_bytes'] ?? null)
                && is_int($row['php_phase_peak_after_reset_bytes'] ?? null)
                && is_int($row['memory_peak_bytes'] ?? null)
                && is_int($row['memory_peak_delta_bytes'] ?? null)
                && $row['memory_before_bytes'] > 0
                && $row['memory_after_bytes'] > 0
                && $row['memory_delta_bytes'] === max(0, $row['memory_after_bytes'] - $row['memory_before_bytes'])
                && $row['memory_delta_bytes'] <= 16777216
                && $row['php_phase_peak_after_reset_bytes'] >= $row['memory_before_bytes']
                && $row['memory_peak_delta_bytes'] === max(0, $row['php_phase_peak_after_reset_bytes'] - $row['memory_before_bytes'])
                && $row['memory_peak_delta_bytes'] <= 16777216
                && $row['memory_peak_bytes'] === max($row['php_lifetime_peak_before_reset_bytes'], $row['php_phase_peak_after_reset_bytes'])
                && $row['memory_peak_bytes'] > 0
                && $row['memory_peak_bytes'] <= 134217728
                && is_int($row['rss_before_bytes'] ?? null)
                && is_int($row['rss_after_bytes'] ?? null)
                && is_int($row['rss_delta_bytes'] ?? null)
                && is_int($row['rss_peak_bytes'] ?? null)
                && is_int($row['rss_peak_delta_bytes'] ?? null)
                && $row['rss_before_bytes'] > 0
                && $row['rss_after_bytes'] > 0
                && $row['rss_delta_bytes'] === max(0, $row['rss_after_bytes'] - $row['rss_before_bytes'])
                && $row['rss_delta_bytes'] <= 16777216
                && $row['rss_peak_bytes'] >= $row['rss_before_bytes']
                && $row['rss_peak_delta_bytes'] === max(0, $row['rss_peak_bytes'] - $row['rss_before_bytes'])
                && $row['rss_peak_delta_bytes'] <= 16777216
                && $row['rss_peak_bytes'] > 0
                && $row['rss_peak_bytes'] <= 134217728
                && wp_fts_wc_process_identity_valid($identity);
            array_push($gates, ...wp_fts_wc_require_evidence_gates(
                $row,
                "cold {$caseId} sample {$sample}",
                wp_fts_wc_cold_sample_gate_ids($caseId, $sample),
                'relational-fts-cold-sample-v1'
            ));
            $samples[$caseId][] = $row;
        }
        $durations = array_map(static fn(array $row): float => (float) ($row['duration_ms'] ?? INF), $samples[$caseId]);
        $queryCounts = array_map(static fn(array $row): int => (int) ($row['query_count'] ?? PHP_INT_MAX), $samples[$caseId]);
        $sqlBytes = array_map(static fn(array $row): int => (int) ($row['max_sql_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $memory = array_map(static fn(array $row): int => (int) ($row['memory_delta_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $memoryPeak = array_map(static fn(array $row): int => (int) ($row['memory_peak_delta_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $memoryAbsolutePeak = array_map(static fn(array $row): int => (int) ($row['memory_peak_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $rss = array_map(static fn(array $row): int => (int) ($row['rss_delta_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $rssPeak = array_map(static fn(array $row): int => (int) ($row['rss_peak_delta_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $rssAbsolutePeak = array_map(static fn(array $row): int => (int) ($row['rss_peak_bytes'] ?? PHP_INT_MAX), $samples[$caseId]);
        $hashes = array_values(array_unique(array_map(static fn(array $row): string => (string) ($row['result_hash'] ?? ''), $samples[$caseId])));
        $hotHash = (string) ($evidence['cases'][$caseId]['result_hash'] ?? '');
        $maxDuration = max($durations ?: [INF]);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_sample_count", $count, count($samples[$caseId]), count($samples[$caseId]) === $count);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_max_ms", "<= {$limit}", $maxDuration, $maxDuration <= $limit);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_query_count", '<= 3', max($queryCounts ?: [PHP_INT_MAX]), max($queryCounts ?: [PHP_INT_MAX]) <= 3);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_sql_bytes", '<= 32768', max($sqlBytes ?: [PHP_INT_MAX]), max($sqlBytes ?: [PHP_INT_MAX]) <= 32768);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_memory_delta", '<= 16777216', max($memory ?: [PHP_INT_MAX]), max($memory ?: [PHP_INT_MAX]) <= 16777216);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_memory_peak_delta", '<= 16777216', max($memoryPeak ?: [PHP_INT_MAX]), max($memoryPeak ?: [PHP_INT_MAX]) <= 16777216);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_php_peak", '0 < peak <= 134217728', max($memoryAbsolutePeak ?: [PHP_INT_MAX]), min($memoryAbsolutePeak ?: [0]) > 0 && max($memoryAbsolutePeak ?: [PHP_INT_MAX]) <= 134217728);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_rss_delta", '<= 16777216', max($rss ?: [PHP_INT_MAX]), max($rss ?: [PHP_INT_MAX]) <= 16777216);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_rss_peak_delta", '<= 16777216', max($rssPeak ?: [PHP_INT_MAX]), max($rssPeak ?: [PHP_INT_MAX]) <= 16777216);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_rss_peak", '0 < VmHWM <= 134217728', max($rssAbsolutePeak ?: [PHP_INT_MAX]), min($rssAbsolutePeak ?: [0]) > 0 && max($rssAbsolutePeak ?: [PHP_INT_MAX]) <= 134217728);
        $gates[] = wp_fts_wc_gate("cold_{$caseId}_result_parity", $hotHash, $hashes, $hotHash !== '' && $hashes === [$hotHash]);
    }
    $uniqueProcessIdentities = array_values(array_unique($processIdentities));
    $gates[] = wp_fts_wc_gate('cold_all_sample_artifact_inventory', $expectedSampleFiles, $actualSampleFiles, $actualSampleFiles === $expectedSampleFiles);
    $gates[] = wp_fts_wc_gate('cold_all_sample_artifact_self_hashes', 40, count($processIdentities), $artifactSelfHashesValid && count($processIdentities) === 40);
    $gates[] = wp_fts_wc_gate('cold_all_sample_source_bindings', $expectedBinding, $sourceBindingsValid, $sourceBindingsValid);
    $gates[] = wp_fts_wc_gate('cold_all_sample_distinct_fresh_processes', 40, count($uniqueProcessIdentities), !in_array('', $uniqueProcessIdentities, true) && count($uniqueProcessIdentities) === 40);

    return ['conditioning' => $conditioning, 'samples' => $samples, 'artifact_files' => $actualSampleFiles, 'process_identities' => $processIdentities, 'gates' => $gates];
}

/** wpdb decorator that records the exact statements executed by storage. */
final class WP_FTS_WC_Recording_WPDB
{
    public string $prefix;
    public string $posts;
    public string $term_relationships;
    public string $last_error = '';
    /** @var string[] */
    public array $queries = [];
    /** @var array<int,array{sql:string,result:int|bool}> */
    public array $queryEvents = [];

    /** Mirror the real connection while retaining exact executed statements. */
    public function __construct(private object $delegate)
    {
        $this->prefix = (string) ($delegate->prefix ?? '');
        $this->posts = (string) ($delegate->posts ?? ($this->prefix . 'posts'));
        $this->term_relationships = (string) ($delegate->term_relationships ?? ($this->prefix . 'term_relationships'));
    }

    /** Delegate interpolation without recording a template that never executed. */
    public function prepare(string $query, mixed ...$args): mixed
    {
        $statement = $this->delegate->prepare($query, ...$args);
        $this->sync_error();

        return $statement;
    }

    /** Record statement order and affected-row results around the real query. */
    public function query(mixed $query): int|bool
    {
        $sql = (string) $query;
        $this->queries[] = $sql;
        $result = $this->delegate->query($query);
        $this->queryEvents[] = ['sql' => $sql, 'result' => $result];
        $this->sync_error();

        return $result;
    }

    /** @return object[]|array<int,array<string,mixed>> */
    public function get_results(mixed $query): array
    {
        $this->queries[] = (string) $query;
        $result = $this->delegate->get_results($query);
        $this->sync_error();

        return is_array($result) ? $result : [];
    }

    /** Record single-row reads used by the storage protocol. */
    public function get_row(mixed $query): mixed
    {
        $this->queries[] = (string) $query;
        $result = $this->delegate->get_row($query);
        $this->sync_error();

        return $result;
    }

    /** @return array<int,mixed> */
    public function get_col(mixed $query): array
    {
        $this->queries[] = (string) $query;
        $result = $this->delegate->get_col($query);
        $this->sync_error();

        return is_array($result) ? $result : [];
    }

    /** Preserve wpdb's placeholder-unescape behavior for delegated storage calls. */
    public function remove_placeholder_escape(string $query): string
    {
        $result = $this->delegate->remove_placeholder_escape($query);

        return is_string($result) ? $result : $query;
    }

    /** Keep the decorator's error channel identical to the real connection. */
    private function sync_error(): void
    {
        $this->last_error = isset($this->delegate->last_error) ? (string) $this->delegate->last_error : '';
    }
}

/** Bootstrap only the disposable WordPress tree supplied by the wrapper. */
function wp_fts_wc_bootstrap_wordpress(): void
{
    if (defined('ABSPATH') && function_exists('get_option')) {
        return;
    }

    $wpPath = getenv('WP_FTS_WP_PATH');
    if (!is_string($wpPath) || trim($wpPath) === '') {
        throw new RuntimeException('WP_FTS_WP_PATH is required; use the disposable Docker wrapper.');
    }
    $wpLoad = rtrim($wpPath, '/\\') . '/wp-load.php';
    if (!is_file($wpLoad)) {
        throw new RuntimeException("WordPress bootstrap was not found at {$wpLoad}.");
    }
    require $wpLoad;
    if (!function_exists('get_option')) {
        throw new RuntimeException('WordPress did not bootstrap correctly.');
    }
}

/** Fail closed unless both the explicit guard and on-disk marker are present. */
function wp_fts_wc_assert_disposable_guard(): void
{
    if (wp_fts_wc_required_env('WP_FTS_WC_ALLOW_DISPOSABLE') !== '1') {
        throw new RuntimeException('The destructive disposable-database guard is absent.');
    }
    $marker = rtrim(wp_fts_wc_required_env('WP_FTS_WP_PATH'), '/\\') . '/.wp-fts-relational-worst-case';
    if (!is_file($marker)) {
        throw new RuntimeException("Disposable marker is absent: {$marker}");
    }
}

/** Bind evidence to the exact low-resource database and PHP runtime contract. */
function wp_fts_wc_assert_runtime(): void
{
    global $wpdb;

    if (!isset($wpdb) || !is_object($wpdb)) {
        throw new RuntimeException('WordPress loaded without $wpdb.');
    }
    $row = $wpdb->get_row('SELECT VERSION() AS version, @@version_comment AS comment, @@innodb_buffer_pool_size AS buffer_pool, @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, @@max_connections AS max_connections, @@innodb_flush_log_at_trx_commit AS flush_mode, @@performance_schema_max_sql_text_length AS performance_schema_sql_bytes, @@performance_schema_events_statements_history_long_size AS performance_schema_history_long_events, @@performance_schema_events_statements_history_size AS performance_schema_thread_history_events, @@performance_schema_digests_size AS performance_schema_digests, @@performance_schema_max_thread_instances AS performance_schema_thread_capacity, @@performance_schema_accounts_size AS performance_schema_accounts, @@performance_schema_hosts_size AS performance_schema_hosts, @@performance_schema_users_size AS performance_schema_users, @@performance_schema_session_connect_attrs_size AS performance_schema_session_connect_attrs, @@performance_schema_events_stages_history_long_size AS performance_schema_stages_history_long, @@performance_schema_events_stages_history_size AS performance_schema_stages_history, @@performance_schema_events_transactions_history_long_size AS performance_schema_transactions_history_long, @@performance_schema_events_transactions_history_size AS performance_schema_transactions_history, @@performance_schema_events_waits_history_long_size AS performance_schema_waits_history_long, @@performance_schema_events_waits_history_size AS performance_schema_waits_history');
    if (!is_object($row)) {
        throw new RuntimeException('Could not read the MySQL/MariaDB runtime: ' . (string) $wpdb->last_error);
    }
    $identity = strtolower((string) $row->version . ' ' . (string) $row->comment);
    if (!str_contains($identity, 'mysql') && !str_contains($identity, 'mariadb')) {
        throw new RuntimeException('The proof requires MySQL or MariaDB.');
    }
    $engine = wp_fts_wc_required_env('WP_FTS_WC_ENGINE');
    $version = strtolower((string) $row->version);
    if ($engine === 'mariadb-10.11') {
        wp_fts_wc_assert(
            str_contains($identity, 'mariadb')
                && version_compare($version, '10.11', '>=')
                && version_compare($version, '10.12', '<'),
            'The mariadb-10.11 lane must run MariaDB 10.11.x.'
        );
    } elseif ($engine === 'mysql-8.0') {
        wp_fts_wc_assert(
            !str_contains($identity, 'mariadb')
                && str_contains($identity, 'mysql')
                && version_compare($version, '8.0', '>=')
                && version_compare($version, '8.1', '<'),
            'The mysql-8.0 lane must run MySQL 8.0.x.'
        );
    } else {
        throw new RuntimeException("Unsupported declared database engine: {$engine}");
    }
    wp_fts_wc_assert((int) $row->buffer_pool === 268435456, 'InnoDB buffer pool must be exactly 256 MiB.');
    wp_fts_wc_assert((int) $row->tmp_table_size === 33554432, 'tmp_table_size must be exactly 32 MiB.');
    wp_fts_wc_assert((int) $row->max_heap_table_size === 33554432, 'max_heap_table_size must be exactly 32 MiB.');
    wp_fts_wc_assert((int) $row->max_connections === 24, 'max_connections must be exactly 24.');
    wp_fts_wc_assert((int) $row->flush_mode === 1, 'innodb_flush_log_at_trx_commit must remain 1.');
    wp_fts_wc_assert(
        (int) $row->performance_schema_sql_bytes === WP_FTS_WC_PERFORMANCE_SCHEMA_SQL_TEXT_BYTES,
        'Performance Schema must retain exactly 32,768 SQL bytes for complete bounded-statement attribution.'
    );
    wp_fts_wc_assert(
        (int) $row->performance_schema_history_long_events === WP_FTS_WC_PERFORMANCE_SCHEMA_HISTORY_LONG_EVENTS,
        'Performance Schema must retain exactly 2,048 global statement events.'
    );
    wp_fts_wc_assert(
        (int) $row->performance_schema_thread_history_events === WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_HISTORY_EVENTS,
        'Performance Schema must not reserve unused per-thread statement history.'
    );
    wp_fts_wc_assert(
        (int) $row->performance_schema_digests === WP_FTS_WC_PERFORMANCE_SCHEMA_DIGESTS,
        'Performance Schema must not reserve unused statement digest summaries.'
    );
    wp_fts_wc_assert(
        (int) $row->performance_schema_thread_capacity === WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES,
        'Performance Schema must reserve exactly 128 instrumented thread instances.'
    );
    wp_fts_wc_assert(
        wp_fts_wc_unused_performance_schema_capacities($row) === WP_FTS_WC_UNUSED_PERFORMANCE_SCHEMA_CAPACITIES,
        'Performance Schema must not reserve histories or identity summaries that the proof never reads.'
    );
    wp_fts_wc_assert(
        function_exists('wp_convert_hr_to_bytes') && wp_convert_hr_to_bytes((string) ini_get('memory_limit')) === 134217728,
        'PHP memory_limit must be exactly 128 MiB.'
    );

    $performanceSchema = (int) $wpdb->get_var("SELECT COUNT(*) FROM information_schema.ENGINES WHERE ENGINE = 'PERFORMANCE_SCHEMA' AND SUPPORT IN ('YES','DEFAULT')");
    wp_fts_wc_assert($performanceSchema === 1, 'Performance Schema must be enabled; rows-examined evidence cannot be skipped.');

    $consumerState = wp_fts_wc_performance_schema_consumer_state();
    wp_fts_wc_assert(
        $consumerState === [
            'events_statements_current' => 'YES',
            'events_statements_history' => 'NO',
            'events_statements_history_long' => 'YES',
        ],
        'Performance Schema statement consumers do not match the exact bounded attribution state.'
    );

    $instrumentedThreads = $wpdb->get_var('SELECT COUNT(*) FROM performance_schema.threads');
    wp_fts_wc_assert(
        is_numeric($instrumentedThreads) && (int) $instrumentedThreads < WP_FTS_WC_PERFORMANCE_SCHEMA_THREAD_INSTANCES,
        'Performance Schema has no instrumented-thread headroom.'
    );
    $lostThreads = $wpdb->get_row("SHOW GLOBAL STATUS LIKE 'Performance_schema_thread_instances_lost'");
    wp_fts_wc_assert(
        is_object($lostThreads)
            && strcasecmp((string) ($lostThreads->Variable_name ?? ''), 'Performance_schema_thread_instances_lost') === 0
            && is_numeric($lostThreads->Value ?? null)
            && (int) $lostThreads->Value === 0,
        'Performance Schema lost an instrumented thread; statement attribution is incomplete.'
    );
}

/** @return array<string,int> */
function wp_fts_wc_unused_performance_schema_capacities(object $row): array
{
    return [
        'accounts' => (int) ($row->performance_schema_accounts ?? -1),
        'hosts' => (int) ($row->performance_schema_hosts ?? -1),
        'users' => (int) ($row->performance_schema_users ?? -1),
        'session_connect_attrs' => (int) ($row->performance_schema_session_connect_attrs ?? -1),
        'stages_history_long' => (int) ($row->performance_schema_stages_history_long ?? -1),
        'stages_history' => (int) ($row->performance_schema_stages_history ?? -1),
        'transactions_history_long' => (int) ($row->performance_schema_transactions_history_long ?? -1),
        'transactions_history' => (int) ($row->performance_schema_transactions_history ?? -1),
        'waits_history_long' => (int) ($row->performance_schema_waits_history_long ?? -1),
        'waits_history' => (int) ($row->performance_schema_waits_history ?? -1),
    ];
}

/** @return array<string,string> */
function wp_fts_wc_performance_schema_consumer_state(): array
{
    global $wpdb;

    $rows = $wpdb->get_results("SELECT NAME, ENABLED FROM performance_schema.setup_consumers WHERE NAME IN ('events_statements_current','events_statements_history','events_statements_history_long') ORDER BY NAME ASC", ARRAY_A);
    wp_fts_wc_assert(
        trim((string) $wpdb->last_error) === '' && is_array($rows),
        'Could not read the Performance Schema statement-consumer state.'
    );

    $state = [];
    foreach ($rows as $row) {
        if (isset($row['NAME'], $row['ENABLED']) && is_string($row['NAME']) && is_string($row['ENABLED'])) {
            $state[$row['NAME']] = $row['ENABLED'];
        }
    }

    return $state;
}

/** Reject evidence not bound to the mounted harness, ZIP, source, and lane. */
function wp_fts_wc_assert_source_binding(): void
{
    $sha = wp_fts_wc_required_env('WP_FTS_SOURCE_SHA');
    $zipHash = wp_fts_wc_required_env('WP_FTS_ZIP_SHA256');
    $harnessHash = wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256');
    wp_fts_wc_assert(strlen($sha) === 40 && wp_fts_wc_is_ascii_hex($sha), 'WP_FTS_SOURCE_SHA must be a full Git SHA.');
    wp_fts_wc_assert(strlen($zipHash) === 64 && wp_fts_wc_is_ascii_hex($zipHash), 'WP_FTS_ZIP_SHA256 must be a SHA-256 digest.');
    wp_fts_wc_assert(strlen($harnessHash) === 64 && wp_fts_wc_is_ascii_hex($harnessHash), 'WP_FTS_HARNESS_SHA256 must be a SHA-256 digest.');
    wp_fts_wc_assert(hash_equals($harnessHash, hash_file('sha256', __FILE__)), 'Mounted acceptance harness does not match its source-ref digest.');
    $profile = wp_fts_wc_required_env('WP_FTS_WC_PROFILE');
    $engine = wp_fts_wc_required_env('WP_FTS_WC_ENGINE');
    $laneId = wp_fts_wc_required_env('WP_FTS_WC_LANE_ID');
    $expectedLaneId = wp_fts_wc_expected_lane_id($profile, $engine);
    if (getenv('WP_FTS_WC_ALLOW_DIRTY') !== '1') {
        wp_fts_wc_assert($expectedLaneId !== null && hash_equals($expectedLaneId, $laneId), 'Clean evidence must use one exact supported profile/engine lane identity.');
    } else {
        wp_fts_wc_assert($laneId === 'diagnostic-' . $engine . '-' . $profile || $laneId === $expectedLaneId, 'Diagnostic evidence has an invalid stable lane identity.');
    }
    if (wp_fts_wc_required_env('WP_FTS_SOURCE_DIRTY') === '1' && getenv('WP_FTS_WC_ALLOW_DIRTY') !== '1') {
        throw new RuntimeException('Acceptance evidence cannot be created from a dirty source tree.');
    }
}

/** Map only the four supported clean profile/engine combinations to lane IDs. */
function wp_fts_wc_expected_lane_id(string $profile, string $engine): ?string
{
    return match ($profile . '/' . $engine) {
        '50k/mariadb-10.11' => 'mariadb1011-50k',
        '50k/mysql-8.0' => 'mysql80-50k',
        '100k/mariadb-10.11' => 'mariadb1011-100k',
        '100k/mysql-8.0' => 'mysql80-100k',
        default => null,
    };
}

/** Require the installed release ZIP to have bootstrapped its production classes. */
function wp_fts_wc_require_plugin(): void
{
    if (!class_exists('WP_FTS_Plugin') || !class_exists('WP_FTS_Index_Queue')) {
        throw new RuntimeException('The installed release ZIP did not bootstrap the Language FTS plugin.');
    }
}

/**
 * @return array{name:string,documents:int,hidden:int,dirty:int,password:int,rare:int,prefix_terms:int,iterations:int,warmup:int}
 */
function wp_fts_wc_profile(): array
{
    $name = wp_fts_wc_required_env('WP_FTS_WC_PROFILE');

    return match ($name) {
        '2k' => ['name' => '2k', 'documents' => 2000, 'hidden' => 100, 'dirty' => 400, 'password' => 20, 'rare' => 16, 'prefix_terms' => 400, 'iterations' => WP_FTS_WC_WARM_SAMPLE_COUNT, 'warmup' => WP_FTS_WC_WARMUP_COUNT],
        '50k' => ['name' => '50k', 'documents' => 50000, 'hidden' => 2500, 'dirty' => 10000, 'password' => 500, 'rare' => 32, 'prefix_terms' => 10000, 'iterations' => WP_FTS_WC_WARM_SAMPLE_COUNT, 'warmup' => WP_FTS_WC_WARMUP_COUNT],
        '100k' => ['name' => '100k', 'documents' => 100000, 'hidden' => 5000, 'dirty' => 20000, 'password' => 1000, 'rare' => 64, 'prefix_terms' => 20000, 'iterations' => WP_FTS_WC_WARM_SAMPLE_COUNT, 'warmup' => WP_FTS_WC_WARMUP_COUNT],
        default => throw new RuntimeException("Unsupported corpus profile: {$name}"),
    };
}

/**
 * @param array{name:string,documents:int,hidden:int,dirty:int,password:int,rare:int,prefix_terms:int,iterations:int,warmup:int} $profile
 * @return array{date:string,content:string,title:string,excerpt:string,status:string,password:string,slug:string,guid:string}
 */
function wp_fts_wc_document(int $ordinal, array $profile, string $token): array
{
    $documents = $profile['documents'];
    $hiddenLimit = $profile['hidden'];
    $dirtyLimit = $hiddenLimit + $profile['dirty'];
    $password = '';
    $status = 'publish';
    if ($ordinal <= $hiddenLimit) {
        if ($ordinal <= $profile['password']) {
            $password = 'wpfts-worst-case-password';
        } else {
            $status = $ordinal % 5 === 0 ? 'draft' : 'private';
        }
    }

    $rare = $ordinal > $documents - $profile['rare'];
    $common = ['commonalpha'];
    if ($ordinal <= (int) floor($documents * 0.95) || $rare) {
        $common[] = 'commonbeta';
    }
    if ($ordinal <= (int) floor($documents * 0.85) || $rare) {
        $common[] = 'commongamma';
    }

    // Twelve exact, corpus-wide keys plus the final normalized-surface range
    // form the largest valid relational OR plan. Keeping them in every
    // document makes the boundary workload construction-known instead of
    // extrapolated from a much smaller three-term query.
    for ($maxCommon = 1; $maxCommon <= 11; $maxCommon++) {
        $common[] = 'maxcommon' . str_pad((string) $maxCommon, 2, '0', STR_PAD_LEFT);
    }
    $common[] = 'prefixprobe';
    if ($ordinal <= WP_FTS_WC_DENSE_PREFIX_DOCUMENTS) {
        // Three fixed completions make the broad prefix range cost more than
        // one maximum-size candidate envelope even in the 2k lane. Larger
        // lanes retain the same fixed perturbation rather than scaling the
        // per-document fixture or its storage amplification with corpus size.
        array_push($common, ...WP_FTS_WC_DENSE_PREFIX_COMPLETIONS);
    }

    $prefixOrdinal = ($ordinal - 1) % $profile['prefix_terms'];
    $prefixToken = 'prefixprobe' . wp_fts_wc_alpha_id($prefixOrdinal);
    $tokens = array_merge($common, [$prefixToken]);
    if ($rare) {
        $tokens[] = 'rareanchor';
    }
    if ($ordinal === $documents - $profile['rare'] - 8) {
        // One exact candidate against the complete prefix range exercises the
        // candidate-first driver even in the 2k lane. The fixed consonant
        // suffix keeps these identities distinct after stemming, so the
        // candidate carries at least 8,000 physical postings. SQL shape and
        // row gates prove the range is not scanned before this bounded set.
        $tokens[] = 'candidateanchor';
        for ($candidateTerm = 0; $candidateTerm < WP_FTS_WC_DENSE_CANDIDATE_TERMS; $candidateTerm++) {
            $tokens[] = 'candidatefill' . wp_fts_wc_alpha_id($candidateTerm) . 'qx';
        }
    }
    if ($ordinal === $documents - $profile['rare'] - 9) {
        // One surface completion against the corpus-wide commonalpha exact
        // group proves AND can select a prefix anchor instead of scanning the
        // common posting list merely because the prefix is final.
        $tokens[] = 'selectiveprefixcompletion';
    }
    if ($ordinal <= $hiddenLimit) {
        for ($i = 0; $i < 24; $i++) {
            $tokens[] = 'visibilityprobe';
        }
    } elseif ($ordinal <= $dirtyLimit) {
        for ($i = 0; $i < 16; $i++) {
            $tokens[] = 'visibilityprobe';
        }
    } elseif ($ordinal <= $dirtyLimit + 200) {
        $tokens[] = 'visibilityprobe';
    }
    if ($ordinal === $documents - 1) {
        // Keep the beyond-sample completion dominant in the explicit English
        // segment even when the WordPress title inherits an en-US locale.
        array_push($tokens, ...array_fill(0, 24, $prefixToken));
    }
    $adversarialTokens = $tokens;

    $length = wp_fts_wc_target_tokens($ordinal);
    $filler = ['editorial', 'harbor', 'atlas', 'wordpress', 'performance', 'content', 'search', 'reader', 'article', 'archive', 'author', 'topic'];
    for ($index = count($tokens); $index < $length; $index++) {
        $tokens[] = $filler[($ordinal + $index) % count($filler)];
    }

    $language = match ($ordinal % 100) {
        0, 1, 2, 3, 4 => 'pl',
        5, 6, 7 => 'de',
        8, 9 => 'zh',
        10, 11 => 'ar',
        12, 13 => 'und',
        default => 'en',
    };
    $special = match ($language) {
        'pl' => ' Wrocław Łódź kotami zamkami ',
        'de' => ' Führung Straße Häusern ',
        'zh' => ' 中文搜索内容 ',
        'ar' => ' البحث والمحتوى ',
        'und' => ' Beyoncé résumé café ',
        default => ' canonical searchable material ',
    };
    $adversarialBody = implode(' ', $adversarialTokens);
    $languageBody = implode(' ', array_slice($tokens, count($adversarialTokens))) . $special;
    $content = '<article><p lang="en">'
        . htmlspecialchars($adversarialBody, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')
        . '</p><p lang="' . $language . '">'
        . htmlspecialchars($languageBody, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')
        . '</p></article>';

    $titleSuffix = '';
    if ($ordinal === $documents - $profile['rare'] - 7) {
        // These four rows exercise a real two-lemma Polish surface as one
        // logical source group. Their known match sets distinguish OR from AND,
        // while the impact/date ordering and explain shape make accidental
        // group splitting visible.
        $content .= '<p lang="pl">chrząstek wpftsambanchor</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 6) {
        $content .= '<p lang="pl">chrząstka</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 5) {
        $content .= '<p lang="pl">wpftsambanchor</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 4) {
        $content .= '<p lang="pl">chrząstki wpftsambanchor</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 3) {
        $titleSuffix = ' fieldprobe actual title hit';
        $content .= '<p>fieldprobe</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 2) {
        $titleSuffix = ' unrelated unrelated unrelated unrelated unrelated';
        $content .= '<p>fieldprobe</p>';
    } elseif ($ordinal === $documents - $profile['rare'] - 1) {
        $content .= '<p>fieldprobe</p>';
    }
    if ($ordinal === $documents - 1) {
        // This completion is deliberately beyond the former lexical expansion
        // cap and receives a title impact that makes omission visible on page 1.
        $titleSuffix .= ' ' . $prefixToken . ' exact surface range sentinel';
    }

    $date = gmdate('Y-m-d H:i:s', 1704067200 + $ordinal);
    $slug = $token . '-' . str_pad((string) $ordinal, 6, '0', STR_PAD_LEFT);

    return [
        'date' => $date,
        'content' => $content,
        'title' => WP_FTS_WC_POST_TITLE_PREFIX . $token . ' ' . $ordinal . $titleSuffix,
        'excerpt' => "Deterministic relational search excerpt {$ordinal} {$common[0]}",
        'status' => $status,
        'password' => $password,
        'slug' => $slug,
        'guid' => 'https://example.test/?p=' . $slug,
    ];
}

/** Produce the deterministic skewed document-size distribution for the corpus. */
function wp_fts_wc_target_tokens(int $ordinal): int
{
    $bucket = $ordinal % 100;
    if ($bucket === 0) {
        return 5000 + ($ordinal % 201);
    }
    if ($bucket <= 7) {
        return 600 + ($ordinal % 901);
    }
    if ($bucket <= 27) {
        return 221 + ($ordinal % 380);
    }

    return 80 + ($ordinal % 141);
}

/** Encode fixture identities alphabetically so tokenizers cannot split digits. */
function wp_fts_wc_alpha_id(int $value): string
{
    $letters = '';
    for ($index = 0; $index < 4; $index++) {
        $letters = chr(97 + ($value % 26)) . $letters;
        $value = intdiv($value, 26);
    }

    return $letters;
}

/** Install the exact public adapters, scope, prefix, and dependency settings under proof. */
function wp_fts_wc_enable_search_settings(): void
{
    $settings = get_option(WP_FTS_Plugin::SETTINGS_OPTION, []);
    $settings = is_array($settings) ? $settings : [];
    $settings['rest_api_enabled'] = true;
    $settings['rest_prefix_matching'] = true;
    $settings['prefix_matching'] = true;
    $settings['prefix_min_length'] = 4;
    $settings['replace_frontend_search'] = true;
    $settings['replace_admin_post_search'] = true;
    $settings['result_limit'] = 20;
    $settings['index_post_types'] = WP_FTS_WC_INDEX_POST_TYPES;
    update_option(WP_FTS_Plugin::SETTINGS_OPTION, $settings, false);
    update_option(WP_FTS_PostContentExtractor::CUSTOM_FIELDS_OPTION, ['selected_signal'], false);
}

/**
 * Enumerate and activate every distributable lemma manifest in the
 * installed release artifact. Duplicate language/kind identities fail rather
 * than being silently discarded, because the runtime can activate exactly one
 * lemmatizer per language. Stable manifest digests bind this proof to the ZIP.
 *
 * @return array{expected:array<int,array<string,string>>,active:array<int,array<string,string>>,expected_sha256:string,active_sha256:string,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_enable_all_runtime_lemma_packs(): array
{
    $root = rtrim((string) WP_PLUGIN_DIR, '/\\') . '/indexer/resources/analyzer-packs';
    if (!is_dir($root)) {
        throw new RuntimeException('The installed artifact has no analyzer-pack directory.');
    }

    $expected = [];
    $pathsByIdentity = [];
    $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS));
    foreach ($iterator as $file) {
        if (!$file->isFile() || $file->getFilename() !== 'manifest.json') {
            continue;
        }
        $path = $file->getPathname();
        $manifest = wp_fts_wc_read_json($path);
        $language = isset($manifest['language']) && is_scalar($manifest['language']) ? strtolower(trim((string) $manifest['language'])) : '';
        $capabilities = is_array($manifest['capabilities'] ?? null) ? array_map('strval', $manifest['capabilities']) : [];
        $runtimeFormat = is_scalar($manifest['runtime']['format'] ?? null) ? strtolower((string) $manifest['runtime']['format']) : '';
        $manifestKind = is_scalar($manifest['kind'] ?? null) ? strtolower((string) $manifest['kind']) : '';
        $isLemma = in_array('dictionary-lemmatizer', $capabilities, true)
            || str_contains($runtimeFormat, 'lemma')
            || str_contains($manifestKind, 'lemma');
        if (!$isLemma) {
            continue;
        }
        $packId = is_scalar($manifest['pack_id'] ?? null) ? trim((string) $manifest['pack_id']) : '';
        $digest = hash_file('sha256', $path);
        wp_fts_wc_assert($language !== '' && $packId !== '' && is_string($digest), 'A distributable lemma manifest lacks a stable language, pack ID, or digest.');
        $identityKey = $language . '|lemmatizer';
        wp_fts_wc_assert(!isset($pathsByIdentity[$identityKey]), "Installed ZIP contains multiple distributable lemmatizers for {$language}; exact activation is impossible.");
        $relative = str_replace(rtrim((string) WP_PLUGIN_DIR, '/\\') . '/indexer/', '', $path);
        $identity = [
            'language' => $language,
            'kind' => 'lemmatizer',
            'pack_id' => $packId,
            'manifest' => $relative,
            'manifest_sha256' => $digest,
            'runtime_format' => $runtimeFormat,
        ];
        $expected[] = $identity;
        $pathsByIdentity[$identityKey] = $path;
    }
    usort($expected, static fn(array $left, array $right): int => strcmp($left['language'] . '|' . $left['kind'] . '|' . $left['manifest_sha256'], $right['language'] . '|' . $right['kind'] . '|' . $right['manifest_sha256']));
    wp_fts_wc_assert($expected !== [], 'The installed artifact has no distributable lemma packs.');

    foreach ($expected as $identity) {
        WP_FTS_Plugin::set_runtime_lemma_pack_option($identity['language'], $pathsByIdentity[$identity['language'] . '|lemmatizer']);
    }
    WP_FTS_Plugin::reset_request_caches();
    $statuses = WP_FTS_Plugin::runtime_analyzer_pack_statuses();
    $runtimeOptions = WP_FTS_Plugin::runtime_analyzer_options();
    $activeOptions = is_array($runtimeOptions['lemma_packs_by_lang'] ?? null)
        ? $runtimeOptions['lemma_packs_by_lang']
        : [];
    $active = [];
    $runtimeStatusesValid = true;
    foreach ($statuses as $status) {
        if (($status['kind'] ?? null) !== 'lemmatizer' || ($status['status'] ?? null) !== 'active') {
            continue;
        }
        $language = strtolower((string) ($status['language'] ?? ''));
        $activePath = WP_FTS_LanguageLemmaPack::manifest_path_from_option($activeOptions[$language] ?? null);
        $activeManifest = is_string($activePath) && is_file($activePath) ? wp_fts_wc_read_json($activePath) : [];
        $activeDigest = is_string($activePath) && is_file($activePath) ? hash_file('sha256', $activePath) : false;
        $runtimeStatusesValid = $runtimeStatusesValid
            && is_scalar($activeManifest['pack_id'] ?? null)
            && (string) $activeManifest['pack_id'] === (string) ($status['pack_id'] ?? '');
        $active[] = [
            'language' => $language,
            'kind' => 'lemmatizer',
            'pack_id' => is_scalar($activeManifest['pack_id'] ?? null) ? (string) $activeManifest['pack_id'] : (string) ($status['pack_id'] ?? ''),
            'manifest' => is_string($activePath) ? str_replace(rtrim((string) WP_PLUGIN_DIR, '/\\') . '/indexer/', '', $activePath) : '',
            'manifest_sha256' => is_string($activeDigest) ? $activeDigest : '',
            'runtime_format' => is_scalar($activeManifest['runtime']['format'] ?? null) ? strtolower((string) $activeManifest['runtime']['format']) : '',
        ];
    }
    usort($active, static fn(array $left, array $right): int => strcmp($left['language'] . '|' . $left['kind'] . '|' . $left['manifest_sha256'], $right['language'] . '|' . $right['kind'] . '|' . $right['manifest_sha256']));
    $expectedHash = wp_fts_wc_canonical_hash($expected);
    $activeHash = wp_fts_wc_canonical_hash($active);
    $gates = [
        wp_fts_wc_gate('all_distributable_pack_cardinality_active', count($expected), count($active), count($active) === count($expected)),
        wp_fts_wc_gate('all_distributable_pack_identities_active', $expected, $active, $active === $expected),
        wp_fts_wc_gate('all_distributable_pack_manifest_digest_set_active', $expectedHash, $activeHash, hash_equals($expectedHash, $activeHash)),
        wp_fts_wc_gate('all_distributable_pack_runtime_statuses_active', true, $runtimeStatusesValid, $runtimeStatusesValid),
    ];
    wp_fts_wc_assert(wp_fts_wc_gates_pass($gates), 'The active runtime pack set differs from the installed distributable non-fixture lemma set.');

    return [
        'expected' => $expected,
        'active' => $active,
        'expected_sha256' => $expectedHash,
        'active_sha256' => $activeHash,
        'gates' => $gates,
    ];
}

/** @return array{tables:array{terms:string,postings:string,documents:string,work:string},physical:array<string,mixed>,verification:array<string,mixed>} */
function wp_fts_wc_assert_relational_schema(): array
{
    global $wpdb;

    $tables = [
        'terms' => $wpdb->prefix . 'fts_terms',
        'postings' => $wpdb->prefix . 'fts_postings',
        'documents' => $wpdb->prefix . 'fts_documents',
        'work' => $wpdb->prefix . 'fts_work',
    ];
    $actual = array_map('strval', $wpdb->get_col($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($wpdb->prefix . 'fts_') . '%')) ?: []);
    sort($actual, SORT_STRING);
    $expected = array_values($tables);
    sort($expected, SORT_STRING);
    if ($actual !== $expected) {
        throw new RuntimeException('Fresh relational schema must contain exactly four FTS tables. Expected ' . json_encode($expected) . ', got ' . json_encode($actual));
    }

    $requiredColumns = [
        'terms' => ['term_id', 'lang', 'kind', 'term', 'doc_freq'],
        'postings' => ['term_id', 'post_id', 'impact'],
        'documents' => ['post_id', 'primary_lang', 'content_hash', 'snippet_text', 'indexed_at'],
        'work' => [
            'job_key', 'kind', 'post_id', 'generation', 'state', 'available_at',
            'attempts', 'claim_token', 'claimed_generation', 'claim_expires_at',
            'cursor_post_id', 'scope_coverage', 'scope_incarnation',
            'scope_subject_type', 'scope_subject_id', 'payload',
            'last_error_code', 'last_error_at',
        ],
    ];
    $requiredIndexes = [
        'terms' => [
            'PRIMARY' => ['columns' => ['term_id'], 'unique' => true],
            'empty_terms' => ['columns' => ['doc_freq'], 'unique' => false],
            'term_identity' => ['columns' => ['lang', 'kind', 'term'], 'unique' => true],
        ],
        'postings' => [
            'PRIMARY' => ['columns' => ['term_id', 'post_id'], 'unique' => true],
            'post_term' => ['columns' => ['post_id', 'term_id'], 'unique' => false],
        ],
        'documents' => [
            'PRIMARY' => ['columns' => ['post_id'], 'unique' => true],
            'document_presence' => ['columns' => ['post_id', 'indexed_at'], 'unique' => false],
        ],
        'work' => [
            'PRIMARY' => ['columns' => ['job_key'], 'unique' => true],
            'claim_token' => ['columns' => ['claim_token', 'post_id'], 'unique' => false],
            'dirty' => ['columns' => ['post_id', 'kind'], 'unique' => false],
            'kind_job' => ['columns' => ['kind', 'job_key'], 'unique' => false],
            'ready' => ['columns' => ['kind', 'state', 'available_at', 'post_id', 'job_key'], 'unique' => false],
            'recoverable' => ['columns' => ['kind', 'state', 'claim_expires_at', 'available_at', 'post_id', 'job_key'], 'unique' => false],
            'scope_subject' => ['columns' => ['kind', 'scope_coverage', 'scope_subject_type', 'scope_subject_id'], 'unique' => false],
        ],
    ];
    $requiredDefinitions = [
        'terms' => [
            'term_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => null, 'extra' => 'auto_increment'],
            'lang' => ['type' => 'varbinary(32)', 'nullable' => false, 'default' => null, 'extra' => ''],
            'kind' => ['type' => 'tinyint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'term' => ['type' => 'varbinary(255)', 'nullable' => false, 'default' => null, 'extra' => ''],
            'doc_freq' => ['type' => 'int unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
        ],
        'postings' => [
            'term_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => null, 'extra' => ''],
            'post_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => null, 'extra' => ''],
            'impact' => ['type' => 'smallint unsigned', 'nullable' => false, 'default' => null, 'extra' => ''],
        ],
        'documents' => [
            'post_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => null, 'extra' => ''],
            'primary_lang' => ['type' => 'varbinary(32)', 'nullable' => false, 'default' => 'und', 'extra' => ''],
            'content_hash' => ['type' => 'varbinary(40)', 'nullable' => false, 'default' => null, 'extra' => ''],
            'snippet_text' => ['type' => 'mediumtext', 'nullable' => false, 'default' => null, 'extra' => ''],
            'indexed_at' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
        ],
        'work' => [
            'job_key' => ['type' => 'varbinary(191)', 'nullable' => false, 'default' => null, 'extra' => ''],
            'kind' => ['type' => 'varchar(16)', 'nullable' => false, 'default' => null, 'extra' => ''],
            'post_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'generation' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '1', 'extra' => ''],
            'state' => ['type' => 'varchar(12)', 'nullable' => false, 'default' => 'pending', 'extra' => ''],
            'available_at' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'attempts' => ['type' => 'int unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'claim_token' => ['type' => 'varchar(64)', 'nullable' => false, 'default' => '', 'extra' => ''],
            'claimed_generation' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'claim_expires_at' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'cursor_post_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'scope_coverage' => ['type' => 'varchar(12)', 'nullable' => false, 'default' => '', 'extra' => ''],
            'scope_incarnation' => ['type' => 'varbinary(32)', 'nullable' => false, 'default' => '', 'extra' => ''],
            'scope_subject_type' => ['type' => 'varchar(24)', 'nullable' => false, 'default' => '', 'extra' => ''],
            'scope_subject_id' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
            'payload' => ['type' => 'longtext', 'nullable' => true, 'default' => null, 'extra' => ''],
            'last_error_code' => ['type' => 'varchar(64)', 'nullable' => false, 'default' => '', 'extra' => ''],
            'last_error_at' => ['type' => 'bigint unsigned', 'nullable' => false, 'default' => '0', 'extra' => ''],
        ],
    ];
    $physical = [];
    foreach ($tables as $key => $table) {
        $identifier = wp_fts_wc_identifier($table);
        $status = $wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s', $table));
        $engine = is_object($status) ? strtolower((string) ($status->Engine ?? '')) : '';
        wp_fts_wc_assert($engine === 'innodb', "{$table} must use InnoDB.");
        $columns = [];
        $definitions = [];
        foreach ($wpdb->get_results("SHOW COLUMNS FROM `{$identifier}`") ?: [] as $column) {
            $name = (string) $column->Field;
            $type = wp_fts_wc_normalize_mysql_column_type((string) ($column->Type ?? ''));
            $default = ($column->Default ?? null) === null ? null : (string) $column->Default;
            $hexDefault = is_string($default) && str_starts_with(strtolower($default), '0x')
                ? substr($default, 2)
                : '';
            if (str_starts_with($type, 'varbinary(') && $hexDefault !== '' && strlen($hexDefault) % 2 === 0 && wp_fts_wc_is_ascii_hex($hexDefault)) {
                $decodedDefault = hex2bin($hexDefault);
                if (is_string($decodedDefault)) {
                    $default = $decodedDefault;
                }
            }
            $columns[] = $name;
            $definitions[$name] = [
                'type' => $type,
                'nullable' => strtoupper((string) ($column->Null ?? '')) === 'YES',
                'default' => $default,
                'extra' => strtolower(trim((string) ($column->Extra ?? ''))),
            ];
        }
        foreach ($requiredColumns[$key] as $column) {
            wp_fts_wc_assert(in_array($column, $columns, true), "{$table}.{$column} is required.");
        }
        wp_fts_wc_assert(
            $columns === $requiredColumns[$key],
            "{$table} columns do not exactly match the production schema contract."
        );
        wp_fts_wc_assert(
            $definitions === $requiredDefinitions[$key],
            "{$table} column definitions do not exactly match the production schema contract."
        );
        $indexes = wp_fts_wc_table_indexes($table);
        wp_fts_wc_assert(
            $indexes === $requiredIndexes[$key],
            "{$table} indexes do not exactly match the production schema contract."
        );
        $physical[$key] = ['table' => $table, 'engine' => $engine, 'columns' => $definitions, 'indexes' => $indexes];
    }

    $termIndexes = wp_fts_wc_table_indexes($tables['terms']);
    $postingIndexes = wp_fts_wc_table_indexes($tables['postings']);
    wp_fts_wc_assert(wp_fts_wc_index_has_columns($termIndexes, ['lang', 'kind', 'term'], true), 'fts_terms needs a unique (lang,kind,term) identity/range path.');
    wp_fts_wc_assert(wp_fts_wc_index_has_columns($postingIndexes, ['term_id', 'post_id'], true), 'fts_postings needs a unique term-first primary/index path.');
    wp_fts_wc_assert(wp_fts_wc_index_has_columns($postingIndexes, ['post_id', 'term_id']), 'fts_postings needs a post-first candidate-probe path.');

    $storage = wp_fts_wc_storage_fixture(false);
    wp_fts_wc_assert(method_exists($storage, 'verify_schema'), 'Relational storage must expose physical schema verification.');
    $verification = $storage->verify_schema();
    wp_fts_wc_assert(is_array($verification) && !empty($verification['valid']), 'Production physical schema verification rejected the exact acceptance schema.');

    return ['tables' => $tables, 'physical' => $physical, 'verification' => $verification];
}

/** Remove display-width/version noise before comparing physical column contracts. */
function wp_fts_wc_normalize_mysql_column_type(string $type): string
{
    $parts = array_values(array_filter(explode(' ', str_replace(["\t", "\n", "\r"], ' ', strtolower(trim($type)))), static fn(string $part): bool => $part !== ''));
    if ($parts === []) {
        return '';
    }
    foreach (['tinyint', 'smallint', 'mediumint', 'int', 'bigint'] as $integerType) {
        $prefix = $integerType . '(';
        if (!str_starts_with($parts[0], $prefix) || !str_ends_with($parts[0], ')')) {
            continue;
        }
        $displayWidth = substr($parts[0], strlen($prefix), -1);
        if ($displayWidth !== '' && wp_fts_wc_is_ascii_digits($displayWidth)) {
            $parts[0] = $integerType;
        }
        break;
    }

    return implode(' ', $parts);
}

/**
 * @return array<string,array{columns:string[],unique:bool}>
 */
function wp_fts_wc_table_indexes(string $table): array
{
    global $wpdb;

    $indexes = [];
    foreach ($wpdb->get_results('SHOW INDEX FROM `' . wp_fts_wc_identifier($table) . '`') ?: [] as $row) {
        $name = (string) $row->Key_name;
        $sequence = (int) $row->Seq_in_index;
        $indexes[$name]['columns'][$sequence] = (string) $row->Column_name;
        $indexes[$name]['unique'] = (int) ($row->Non_unique ?? 1) === 0;
    }
    foreach ($indexes as &$index) {
        ksort($index['columns'], SORT_NUMERIC);
        $index['columns'] = array_values($index['columns']);
    }
    unset($index);
    ksort($indexes, SORT_STRING);

    return $indexes;
}

/**
 * @param array<string,array{columns:string[],unique:bool}> $indexes
 * @param string[] $required
 */
function wp_fts_wc_index_has_columns(array $indexes, array $required, bool $mustBeUnique = false): bool
{
    foreach ($indexes as $index) {
        if (
            (!$mustBeUnique || !empty($index['unique']))
            && array_slice($index['columns'], 0, count($required)) === $required
        ) {
            return true;
        }
    }

    return false;
}

/**
 * @return array<string,mixed>
 */
function wp_fts_wc_runtime_evidence(): array
{
    global $wpdb;

    $row = $wpdb->get_row('SELECT VERSION() AS version, @@version_comment AS comment, @@innodb_buffer_pool_size AS buffer_pool, @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, @@max_connections AS max_connections, @@innodb_flush_log_at_trx_commit AS flush_mode, @@performance_schema_max_sql_text_length AS performance_schema_sql_bytes, @@performance_schema_events_statements_history_long_size AS performance_schema_history_long_events, @@performance_schema_events_statements_history_size AS performance_schema_thread_history_events, @@performance_schema_digests_size AS performance_schema_digests, @@performance_schema_max_thread_instances AS performance_schema_thread_capacity, @@performance_schema_accounts_size AS performance_schema_accounts, @@performance_schema_hosts_size AS performance_schema_hosts, @@performance_schema_users_size AS performance_schema_users, @@performance_schema_session_connect_attrs_size AS performance_schema_session_connect_attrs, @@performance_schema_events_stages_history_long_size AS performance_schema_stages_history_long, @@performance_schema_events_stages_history_size AS performance_schema_stages_history, @@performance_schema_events_transactions_history_long_size AS performance_schema_transactions_history_long, @@performance_schema_events_transactions_history_size AS performance_schema_transactions_history, @@performance_schema_events_waits_history_long_size AS performance_schema_waits_history_long, @@performance_schema_events_waits_history_size AS performance_schema_waits_history');
    $consumerState = wp_fts_wc_performance_schema_consumer_state();
    $instrumentedThreads = $wpdb->get_var('SELECT COUNT(*) FROM performance_schema.threads');
    $lostThreads = $wpdb->get_row("SHOW GLOBAL STATUS LIKE 'Performance_schema_thread_instances_lost'");

    return [
        'version' => (string) ($row->version ?? ''),
        'comment' => (string) ($row->comment ?? ''),
        'innodb_buffer_pool_size' => (int) ($row->buffer_pool ?? 0),
        'tmp_table_size' => (int) ($row->tmp_table_size ?? 0),
        'max_heap_table_size' => (int) ($row->max_heap_table_size ?? 0),
        'max_connections' => (int) ($row->max_connections ?? 0),
        'innodb_flush_log_at_trx_commit' => (int) ($row->flush_mode ?? 0),
        'performance_schema_max_sql_text_length' => (int) ($row->performance_schema_sql_bytes ?? 0),
        'performance_schema_events_statements_history_long_size' => (int) ($row->performance_schema_history_long_events ?? 0),
        'performance_schema_events_statements_history_size' => (int) ($row->performance_schema_thread_history_events ?? 0),
        'performance_schema_digests_size' => (int) ($row->performance_schema_digests ?? -1),
        'performance_schema_max_thread_instances' => (int) ($row->performance_schema_thread_capacity ?? 0),
        'performance_schema_unused_capacities' => wp_fts_wc_unused_performance_schema_capacities($row),
        'performance_schema_statement_consumers' => $consumerState,
        'performance_schema_instrumented_threads' => is_numeric($instrumentedThreads) ? (int) $instrumentedThreads : null,
        'performance_schema_thread_instances_lost' => is_object($lostThreads) && is_numeric($lostThreads->Value ?? null)
            ? (int) $lostThreads->Value
            : null,
        'php_version' => PHP_VERSION,
        'php_memory_limit' => ini_get('memory_limit'),
    ];
}

/**
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_failure_recovery_proof(array $manifest): array
{
    global $wpdb;

    $profile = $manifest['profile'];
    $offset = min($profile['documents'] - 101, $profile['hidden'] + $profile['dirty'] + 300);
    $ids = array_map('intval', $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts} WHERE post_title LIKE %s ORDER BY ID ASC LIMIT 100 OFFSET %d",
        WP_FTS_WC_POST_TITLE_PREFIX . $wpdb->esc_like((string) $manifest['token']) . '%',
        $offset
    )) ?: []);
    wp_fts_wc_assert(count($ids) === 100, 'Poison proof requires exactly 100 corpus posts.');
    $poisonId = $ids[0];
    $queue = new WP_FTS_Index_Queue($wpdb);
    wp_fts_wc_assert(method_exists($queue, 'enqueue_many'), 'Set-oriented queue must expose enqueue_many(); per-post setup is not accepted.');
    $fenceId = (int) $manifest['first_post_id'] + (int) $profile['hidden'] + (int) $profile['dirty'] + 150;
    wp_fts_wc_assert(!in_array($fenceId, $ids, true), 'Generation-fence fixture overlaps the poison batch.');
    $generationFence = wp_fts_wc_generation_fence_proof($queue, $fenceId);

    $recorded = wp_fts_wc_record_queries(static fn() => $queue->enqueue_many($ids));
    $enqueueCount = is_numeric($recorded['result']) ? (int) $recorded['result'] : count($ids);
    $enqueueSql = array_values($recorded['queries']);
    wp_fts_wc_assert($enqueueCount === count($ids), 'enqueue_many() did not report every unique post.');
    wp_fts_wc_assert(count($enqueueSql) === 1, 'enqueue_many() must use exactly one data statement.');
    wp_fts_wc_assert(strlen($enqueueSql[0]) <= 1048576, 'Poison-proof enqueue SQL exceeds its 1 MiB evidence bound.');

    $poisonOptionCalls = 0;
    $filter = static function (array $options, object $post) use ($poisonId, &$poisonOptionCalls): array {
        if ((int) ($post->ID ?? 0) === $poisonId) {
            $poisonOptionCalls++;
            // The first call belongs to shared dependency preloading. Fail the
            // later per-document preparation so only this generation backs off.
            if ($poisonOptionCalls > 1) {
                throw new RuntimeException('intentional-relational-worst-case-poison');
            }
        }
        return $options;
    };
    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    add_filter(WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER, $filter, 10, 2);
    $batchErrors = [];
    $batchErrorCount = 0;
    $processedByAttempt = [];
    $processed = 0;
    try {
        // One failure-only phase plus at most one advancing pass per healthy
        // post keeps this proof valid when the source-byte frontier splits the
        // 100 claimed generations into several smaller bounded batches.
        for ($attempt = 0; $attempt <= count($ids); $attempt++) {
            try {
                $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
                $processedThisAttempt = (int) ($summary['queue_processed'] ?? 0);
                $processed += $processedThisAttempt;
                $processedByAttempt[] = $processedThisAttempt;
            } catch (Throwable $error) {
                $batchErrorCount++;
                if (count($batchErrors) < 3) {
                    $batchErrors[] = $error->getMessage();
                }
                $processedByAttempt[] = 0;
            }
            $laterOutstanding = wp_fts_wc_checked_count(
                "SELECT COUNT(*) FROM `{$work}` WHERE post_id BETWEEN " . (int) min($ids) . ' AND ' . (int) max($ids) . ' AND post_id <> ' . (int) $poisonId,
                'unrelated work during poison recovery'
            );
            if ($laterOutstanding === 0) {
                break;
            }
        }
    } finally {
        remove_filter(WP_FTS_Plugin::POST_INDEX_OPTIONS_FILTER, $filter, 10);
    }

    $remainingIds = array_map('intval', $wpdb->get_col(
        "SELECT post_id FROM `{$work}` WHERE post_id BETWEEN " . (int) min($ids) . ' AND ' . (int) max($ids) . ' ORDER BY post_id ASC'
    ) ?: []);
    $laterRemaining = array_values(array_diff($remainingIds, [$poisonId]));
    $workStateRow = $wpdb->get_row(
        "SELECT job_key,kind,post_id,generation,state,available_at,attempts,claimed_generation,claim_expires_at,last_error_code,last_error_at FROM `{$work}` WHERE post_id = " . (int) $poisonId,
        ARRAY_A
    );
    wp_fts_wc_assert(is_array($workStateRow), 'Poison work has no durable row evidence.');
    $workState = [
        'job_key' => (string) ($workStateRow['job_key'] ?? ''),
        'kind' => (string) ($workStateRow['kind'] ?? ''),
        'post_id' => (int) ($workStateRow['post_id'] ?? 0),
        'generation' => (int) ($workStateRow['generation'] ?? 0),
        'state' => (string) ($workStateRow['state'] ?? ''),
        'available_at' => (int) ($workStateRow['available_at'] ?? 0),
        'attempts' => (int) ($workStateRow['attempts'] ?? 0),
        'claimed_generation' => (int) ($workStateRow['claimed_generation'] ?? 0),
        'claim_expires_at' => (int) ($workStateRow['claim_expires_at'] ?? 0),
        'last_error_code' => (string) ($workStateRow['last_error_code'] ?? ''),
        'last_error_at' => (int) ($workStateRow['last_error_at'] ?? 0),
    ];
    $state = $workState['state'];
    $scheduled = function_exists('wp_next_scheduled') ? wp_next_scheduled(WP_FTS_Plugin::CRON_HOOK) : false;

    wp_fts_wc_assert(
        $laterRemaining === [],
        'A poison item left ' . count($laterRemaining) . ' unrelated queue rows after ' . count($processedByAttempt) . ' bounded worker attempts.'
    );
    wp_fts_wc_assert(in_array($poisonId, $remainingIds, true), 'Poison debt lost its last durable work row.');
    wp_fts_wc_assert($state !== '', 'Poison work has no durable state.');
    wp_fts_wc_assert($scheduled !== false, 'Pending poison debt has no future watchdog/cron event.');

    $laterSearchId = 0;
    foreach (array_slice($ids, 1) as $candidateId) {
        $ordinal = $candidateId - (int) $manifest['first_post_id'] + 1;
        if ($ordinal % 100 >= 14) {
            $laterSearchId = $candidateId;
            break;
        }
    }
    wp_fts_wc_assert($laterSearchId > 0, 'Poison proof could not select a later English search sentinel.');
    $laterOrdinal = $laterSearchId - (int) $manifest['first_post_id'] + 1;
    $laterTerm = 'prefixprobe' . wp_fts_wc_alpha_id(($laterOrdinal - 1) % (int) $profile['prefix_terms']);
    $laterRows = WP_FTS_Plugin::search($laterTerm, [
        'lang' => 'en',
        'mode' => 'OR',
        'limit' => 20,
        'prefix_matching' => false,
    ]);
    $laterSearchable = in_array($laterSearchId, array_map('intval', array_column($laterRows, 'doc_id')), true);
    wp_fts_wc_assert($laterSearchable, 'A later acknowledged post was not searchable while poison debt remained durable.');

    $queue->retry_many([$poisonId], time());
    $recovered = 0;
    for ($attempt = 0; $attempt < 3; $attempt++) {
        $summary = WP_FTS_Plugin::process_manual_index_batch(['batch_size' => 100]);
        $recovered += (int) ($summary['queue_processed'] ?? 0);
        $stillPresent = (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$work}` WHERE post_id = " . (int) $poisonId);
        if ($stillPresent === 0) {
            break;
        }
    }
    $poisonRemaining = (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$work}` WHERE post_id = " . (int) $poisonId);
    wp_fts_wc_assert($poisonRemaining === 0, 'Removing the poison fault did not reconcile and acknowledge the desired generation.');

    wp_fts_wc_assert(count($ids) === 100 && count($remainingIds) <= 100 && count($laterRemaining) <= 99, 'Failure-recovery post-ID evidence exceeds its fixed vector bounds.');
    wp_fts_wc_assert(count($processedByAttempt) <= 101, 'Failure-recovery processing exceeded its 101-attempt bound.');
    wp_fts_wc_assert(count($batchErrors) <= 3, 'Failure-recovery error diagnostics exceed their three-message bound.');
    foreach ($batchErrors as $errorMessage) {
        wp_fts_wc_assert(is_string($errorMessage) && strlen($errorMessage) <= 8192, 'Failure-recovery error evidence exceeds its 8 KiB message bound.');
    }
    $observations = [
        'enqueued_post_ids' => $ids,
        'enqueued_post_ids_sha256' => wp_fts_wc_canonical_hash($ids),
        'enqueue_sql' => $enqueueSql,
        'enqueue_sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $enqueueSql),
        'enqueue_statement_byte_counts' => array_map('strlen', $enqueueSql),
        'remaining_post_ids_before_recovery' => $remainingIds,
        'later_remaining_post_ids_before_recovery' => $laterRemaining,
        'poison_work_row_before_recovery' => $workState,
        'poison_remaining_after_recovery' => $poisonRemaining,
        'processed_by_attempt' => $processedByAttempt,
        'batch_error_count' => $batchErrorCount,
    ];
    wp_fts_wc_assert_json_evidence_bytes($observations, 4194304, 'Failure-recovery observations');
    $gates = [
        wp_fts_wc_gate('poison_later_posts_searchable', true, $laterSearchable, $laterSearchable),
        wp_fts_wc_gate('poison_debt_durable_before_recovery', true, in_array($poisonId, $remainingIds, true), in_array($poisonId, $remainingIds, true)),
        wp_fts_wc_gate('poison_recovered_desired_generation', 0, $poisonRemaining, $poisonRemaining === 0),
        ...$generationFence['gates'],
    ];

    return [
        'schema' => 'relational-fts-failure-recovery-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'passed' => $laterRemaining === [] && $poisonRemaining === 0,
        'poison_post_id' => $poisonId,
        ...$observations,
        'enqueue_statement_count' => count($enqueueSql),
        'enqueue_statement_bytes' => max(array_map('strlen', $enqueueSql)),
        'processed_before_recovery' => $processed,
        'batch_errors' => $batchErrors,
        'durable_state_before_recovery' => $state,
        'cron_timestamp_before_recovery' => (int) $scheduled,
        'later_search_post_id' => $laterSearchId,
        'later_searchable_before_recovery' => $laterSearchable,
        'generation_fence' => $generationFence,
        'recovered' => $recovered,
        'gates' => $gates,
    ];
}

/**
 * Advance a post while its old generation is leased and prove every stale
 * completion path remains fenced from the new immediately claimable work.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_generation_fence_proof(WP_FTS_Index_Queue $queue, int $postId): array
{
    global $wpdb;

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $now = time();
    $queue->enqueue_many([$postId], $now);
    $old = $queue->claim_batch(1, $now, 60)[0] ?? null;
    wp_fts_wc_assert(is_array($old) && (int) ($old['post_id'] ?? 0) === $postId, 'Could not claim the old generation fence fixture.');
    $queue->enqueue_many([$postId], $now + 1);
    $ready = $wpdb->get_row($wpdb->prepare(
        "SELECT generation,state,claim_token,claimed_generation,available_at FROM `{$work}` WHERE post_id=%d",
        $postId
    ), ARRAY_A);
    wp_fts_wc_assert(is_array($ready), 'Advanced generation fence row disappeared.');

    $oldAcknowledge = $queue->acknowledge_many([$old])['acknowledged'] === 1;
    $oldFail = $queue->fail_many([$old], $now + 1);
    $oldRelease = $queue->release_many([$old], $now + 1);
    $afterReadyStale = $wpdb->get_row($wpdb->prepare(
        "SELECT generation,state,claim_token,claimed_generation,available_at FROM `{$work}` WHERE post_id=%d",
        $postId
    ), ARRAY_A);
    $new = $queue->claim_batch(1, $now + 1, 60)[0] ?? null;
    wp_fts_wc_assert(is_array($new) && (int) ($new['generation'] ?? 0) === 2, 'Advanced generation was not immediately claimable.');
    $newToken = (string) ($new['token'] ?? '');

    $leasedOldAcknowledge = $queue->acknowledge_many([$old])['acknowledged'] === 1;
    $leasedOldFail = $queue->fail_many([$old], $now + 1);
    $leasedOldRelease = $queue->release_many([$old], $now + 1);
    $afterLeasedStale = $wpdb->get_row($wpdb->prepare(
        "SELECT generation,state,claim_token,claimed_generation,available_at FROM `{$work}` WHERE post_id=%d",
        $postId
    ), ARRAY_A);
    $newAcknowledged = $queue->acknowledge_many([$new])['acknowledged'] === 1;
    $remaining = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$work}` WHERE post_id=%d", $postId));

    $readyPreserved = is_array($afterReadyStale)
        && (int) $afterReadyStale['generation'] === 2
        && (string) $afterReadyStale['state'] === 'ready'
        && (string) $afterReadyStale['claim_token'] === '';
    $leasePreserved = is_array($afterLeasedStale)
        && (int) $afterLeasedStale['generation'] === 2
        && (string) $afterLeasedStale['state'] === 'leased'
        && hash_equals($newToken, (string) $afterLeasedStale['claim_token'])
        && (int) $afterLeasedStale['claimed_generation'] === 2;
    $staleResults = [$oldAcknowledge, $oldFail, $oldRelease, $leasedOldAcknowledge, $leasedOldFail, $leasedOldRelease];
    $staleNoops = $staleResults === [false, 0, 0, false, 0, 0];

    return [
        'post_id' => $postId,
        'old_generation' => (int) ($old['generation'] ?? 0),
        'new_generation' => (int) ($new['generation'] ?? 0),
        'ready_after_advance' => $ready,
        'ready_after_stale_completions' => $afterReadyStale,
        'leased_after_stale_completions' => $afterLeasedStale,
        'stale_completion_results' => $staleResults,
        'new_acknowledged' => $newAcknowledged,
        'remaining' => $remaining,
        'gates' => [
            wp_fts_wc_gate('generation_fence_advanced_ready', true, $readyPreserved, $readyPreserved),
            wp_fts_wc_gate('generation_fence_stale_completions_noop', [false, 0, 0, false, 0, 0], $staleResults, $staleNoops),
            wp_fts_wc_gate('generation_fence_new_lease_preserved', true, $leasePreserved, $leasePreserved),
            wp_fts_wc_gate('generation_fence_new_generation_acknowledged', 0, $remaining, $newAcknowledged && $remaining === 0),
        ],
    ];
}

/**
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_enqueue_dirty_head(array $manifest): array
{
    global $wpdb;

    $profile = $manifest['profile'];
    $ids = array_map('intval', $wpdb->get_col($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts} WHERE post_title LIKE %s ORDER BY ID ASC LIMIT %d OFFSET %d",
        WP_FTS_WC_POST_TITLE_PREFIX . $wpdb->esc_like((string) $manifest['token']) . '%',
        (int) $profile['dirty'],
        (int) $profile['hidden']
    )) ?: []);
    wp_fts_wc_assert(count($ids) === (int) $profile['dirty'], 'Dirty-head fixture count is wrong.');

    $queue = new WP_FTS_Index_Queue($wpdb);
    wp_fts_wc_assert(method_exists($queue, 'enqueue_many'), 'Dirty-head proof requires set-oriented enqueue_many() calls.');
    $chunks = array_chunk($ids, WP_FTS_Index_Queue::MAX_ENQUEUE_POSTS);
    $recorded = wp_fts_wc_record_queries(static function () use ($queue, $chunks): void {
        foreach ($chunks as $chunk) {
            $queue->enqueue_many($chunk);
        }
    });
    $queries = array_values($recorded['queries']);
    wp_fts_wc_assert(
        count($queries) === count($chunks),
        'Dirty-head enqueue must use exactly one bounded multi-row UPSERT per chunk.'
    );
    wp_fts_wc_assert(count($ids) <= 20000 && count($chunks) <= 20, 'Dirty-head evidence exceeds the largest supported corpus vector.');
    $statementByteCounts = array_map('strlen', $queries);
    wp_fts_wc_assert(
        max($statementByteCounts) <= 1048576,
        'Dirty-head enqueue statements must remain within the one-megabyte queue contract.'
    );
    $totalStatementBytes = array_sum($statementByteCounts);
    wp_fts_wc_assert($totalStatementBytes <= 20971520, 'Dirty-head SQL evidence exceeds its 20 MiB aggregate bound.');
    $observations = [
        'post_ids' => $ids,
        'post_ids_sha256' => wp_fts_wc_canonical_hash($ids),
        'statement_post_counts' => array_map('count', $chunks),
        'statement_byte_counts' => $statementByteCounts,
        'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
        'sql' => $queries,
    ];
    wp_fts_wc_assert_json_evidence_bytes($observations, 33554432, 'Dirty-head observations');

    $work = wp_fts_wc_identifier($wpdb->prefix . 'fts_work');
    $actual = (int) $wpdb->get_var("SELECT COUNT(*) FROM `{$work}` WHERE post_id BETWEEN " . min($ids) . ' AND ' . max($ids));
    wp_fts_wc_assert($actual === count($ids), 'Dirty-head work rows were not durably persisted.');

    return [
        'schema' => 'relational-fts-dirty-head-v1',
        'status' => 'PASS',
        ...$observations,
        'post_count' => count($ids),
        'first_post_id' => min($ids),
        'last_post_id' => max($ids),
        'statement_count' => count($queries),
        'statement_bytes' => max($statementByteCounts),
        'statement_total_bytes' => $totalStatementBytes,
    ];
}

/**
 * Prove that the timed English plans really have their construction-known DFs.
 *
 * The corpus also contains multilingual paragraphs. These assertions prevent a
 * language-tag change from silently shrinking the advertised common-term and
 * maximum-plan workloads while leaving their latency gates deceptively green.
 *
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_adversarial_frequency_proof(array $manifest): array
{
    global $wpdb;

    $profile = $manifest['profile'];
    $documents = (int) $profile['documents'];
    $password = (int) $profile['password'];
    $rare = (int) $profile['rare'];
    $eligible = $documents - $password;
    $densePrefixDocuments = min($documents, WP_FTS_WC_DENSE_PREFIX_DOCUMENTS);
    $densePrefixEligible = $densePrefixDocuments - min($password, $densePrefixDocuments);
    $densePrefixPostings = $densePrefixEligible * count(WP_FTS_WC_DENSE_PREFIX_COMPLETIONS);
    $expected = [
        'candidateanchor' => 1,
        'commonalpha' => $eligible,
        'commonbeta' => (int) floor($documents * 0.95) - $password + $rare,
        'commongamma' => (int) floor($documents * 0.85) - $password + $rare,
        'prefixprobe' => $eligible,
        'rareanchor' => $rare,
    ];
    for ($term = 1; $term <= 11; $term++) {
        $expected['maxcommon' . str_pad((string) $term, 2, '0', STR_PAD_LEFT)] = $eligible;
    }
    ksort($expected, SORT_STRING);

    $termsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $placeholders = implode(',', array_fill(0, count($expected), '%s'));
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT term,doc_freq FROM `{$termsTable}` WHERE lang=%s AND kind=0 AND term IN ({$placeholders})",
        'en',
        ...array_keys($expected)
    ), ARRAY_A) ?: [];
    $actual = [];
    foreach ($rows as $row) {
        $actual[(string) $row['term']] = (int) $row['doc_freq'];
    }
    ksort($actual, SORT_STRING);

    $prefixLower = 'prefixprobe';
    $prefixUpper = wp_fts_wc_binary_successor($prefixLower);
    wp_fts_wc_assert(is_string($prefixUpper), 'The adversarial prefix needs a finite binary successor.');
    $lexicalPrefixVocabulary = $wpdb->get_row($wpdb->prepare(
        "SELECT COUNT(*) term_count,COALESCE(SUM(doc_freq),0) posting_count FROM `{$termsTable}` WHERE lang=%s AND kind=0 AND term>=%s AND term<%s",
        'en',
        $prefixLower,
        $prefixUpper
    ), ARRAY_A);
    $lexicalPrefixVocabulary = is_array($lexicalPrefixVocabulary) ? [
        'term_count' => (int) ($lexicalPrefixVocabulary['term_count'] ?? -1),
        'posting_count' => (int) ($lexicalPrefixVocabulary['posting_count'] ?? -1),
    ] : ['term_count' => -1, 'posting_count' => -1];
    $expectedLexicalPrefixVocabulary = [
        'term_count' => (int) $profile['prefix_terms'] + 1 + count(WP_FTS_WC_DENSE_PREFIX_COMPLETIONS),
        'posting_count' => $eligible * 2 + $densePrefixPostings,
    ];
    $postingsTable = wp_fts_wc_identifier($wpdb->prefix . 'fts_postings');
    $surfaceRange = $wpdb->get_row($wpdb->prepare(
        "SELECT COUNT(*) term_count,
       COALESCE(SUM(surface.doc_freq),0) dictionary_posting_count,
       COALESCE(SUM(surface.posting_rows),0) physical_posting_count,
       COALESCE(SUM(surface.doc_freq<>surface.posting_rows),0) doc_freq_mismatches,
       COALESCE(SUM(surface.posting_rows<>surface.distinct_post_rows),0) duplicate_posting_mismatches
FROM (
SELECT t.term_id,t.doc_freq,COUNT(p.post_id) posting_rows,COUNT(DISTINCT p.post_id) distinct_post_rows
FROM `{$termsTable}` t
LEFT JOIN `{$postingsTable}` p FORCE INDEX (PRIMARY) ON p.term_id=t.term_id
WHERE t.lang=%s AND t.kind=1 AND t.term>=%s AND t.term<%s
GROUP BY t.term_id,t.doc_freq
) surface",
        'en',
        $prefixLower,
        $prefixUpper
    ), ARRAY_A);
    $surfaceRange = is_array($surfaceRange) ? array_map('intval', $surfaceRange) : [];
    $expectedSurfaceRange = [
        'term_count' => (int) $profile['prefix_terms'] + 1 + count(WP_FTS_WC_DENSE_PREFIX_COMPLETIONS),
        'dictionary_posting_count' => $eligible * 2 + $densePrefixPostings,
        'physical_posting_count' => $eligible * 2 + $densePrefixPostings,
        'doc_freq_mismatches' => 0,
        'duplicate_posting_mismatches' => 0,
    ];

    return [
        'exact' => $actual,
        'expected' => $expected,
        'lexical_prefix_vocabulary' => $lexicalPrefixVocabulary,
        'surface_range' => $surfaceRange,
        'gates' => [
            wp_fts_wc_gate('adversarial_exact_document_frequencies', $expected, $actual, $actual === $expected),
            wp_fts_wc_gate('adversarial_prefix_lexical_vocabulary_terms', $expectedLexicalPrefixVocabulary['term_count'], $lexicalPrefixVocabulary['term_count'], $lexicalPrefixVocabulary['term_count'] === $expectedLexicalPrefixVocabulary['term_count']),
            wp_fts_wc_gate('adversarial_prefix_lexical_vocabulary_postings', $expectedLexicalPrefixVocabulary['posting_count'], $lexicalPrefixVocabulary['posting_count'], $lexicalPrefixVocabulary['posting_count'] === $expectedLexicalPrefixVocabulary['posting_count']),
            wp_fts_wc_gate('surface_range_dictionary_terms', $expectedSurfaceRange['term_count'], $surfaceRange['term_count'] ?? null, $surfaceRange === $expectedSurfaceRange),
            wp_fts_wc_gate('surface_range_posting_rows', $expectedSurfaceRange['physical_posting_count'], $surfaceRange['physical_posting_count'] ?? null, $surfaceRange === $expectedSurfaceRange),
            wp_fts_wc_gate('surface_range_doc_freq_parity', 0, $surfaceRange['doc_freq_mismatches'] ?? null, $surfaceRange === $expectedSurfaceRange),
            wp_fts_wc_gate('surface_range_20000_completion_vocabulary', [(int) $profile['prefix_terms'], (int) $profile['prefix_terms'] + 1 + count(WP_FTS_WC_DENSE_PREFIX_COMPLETIONS)], [(int) $profile['prefix_terms'], $surfaceRange['term_count'] ?? null], $surfaceRange === $expectedSurfaceRange),
        ],
    ];
}

/**
 * Record the storage and rebuild cost of normalized source surfaces.
 *
 * These are measurements, not estimates from vocabulary size. Physical posting
 * rows are counted by kind and cross-checked against dictionary `doc_freq`.
 * The per-document limits are the same hard writer envelope enforced before a
 * transaction, so a future surface scheme cannot silently multiply the index
 * beyond the accepted low-end-host bound.
 *
 * @param array<string,mixed> $manifest
 * @param array<string,mixed> $counts
 * @return array<string,mixed>
 */
function wp_fts_wc_surface_storage_proof(array $manifest, array $counts): array
{
    global $wpdb;

    $documents = wp_fts_wc_identifier($wpdb->prefix . 'fts_documents');
    $documentRows = wp_fts_wc_checked_count("SELECT COUNT(*) FROM `{$documents}`", 'surface storage documents');
    $lexicalPostings = max(0, (int) ($counts['lexical']['posting_rows'] ?? -1));
    $surfacePostings = max(0, (int) ($counts['surface']['posting_rows'] ?? -1));
    $lexicalTerms = max(0, (int) ($counts['lexical']['term_rows'] ?? -1));
    $surfaceTerms = max(0, (int) ($counts['surface']['term_rows'] ?? -1));
    $totalPostings = max(0, (int) ($counts['total_posting_rows'] ?? -1));
    $surfacePerDocument = $documentRows > 0 ? $surfacePostings / $documentRows : INF;
    $totalPerDocument = $documentRows > 0 ? $totalPostings / $documentRows : INF;
    $postingAmplification = $lexicalPostings > 0 ? $totalPostings / $lexicalPostings : INF;
    $termAmplification = $lexicalTerms > 0 ? ($lexicalTerms + $surfaceTerms) / $lexicalTerms : INF;
    $physicalByKind = is_array($counts['physical_by_kind'] ?? null) ? $counts['physical_by_kind'] : [];
    $docFreqByKind = is_array($counts['doc_freq_by_kind'] ?? null) ? $counts['doc_freq_by_kind'] : [];
    $expectedDocuments = (int) ($manifest['profile']['documents'] ?? 0)
        - (int) ($manifest['profile']['password'] ?? 0);
    $maxSurfaceRows = $documentRows * WP_FTS_Analysis_Limits::MAX_DOCUMENT_DISTINCT_SURFACES;
    $maxTotalRows = $documentRows * WP_FTS_Relational_Storage::MAX_DOCUMENT_POSTINGS;

    $gates = [
        wp_fts_wc_gate('surface_storage_document_cardinality', $expectedDocuments, $documentRows, $expectedDocuments > 0 && $documentRows === $expectedDocuments),
        wp_fts_wc_gate('surface_storage_physical_doc_freq_parity', $physicalByKind, $docFreqByKind, $physicalByKind === [0 => $lexicalPostings, 1 => $surfacePostings] && $physicalByKind === $docFreqByKind),
        wp_fts_wc_gate('surface_storage_lexical_rows_present', '> 0', [$lexicalTerms, $lexicalPostings], $lexicalTerms > 0 && $lexicalPostings > 0),
        wp_fts_wc_gate('surface_storage_surface_rows_present', '> 0', [$surfaceTerms, $surfacePostings], $surfaceTerms > 0 && $surfacePostings >= $documentRows),
        wp_fts_wc_gate('surface_storage_total_row_accounting', $lexicalPostings + $surfacePostings, $totalPostings, $totalPostings === $lexicalPostings + $surfacePostings),
        wp_fts_wc_gate('surface_storage_per_document_surface_bound', "<= {$maxSurfaceRows}", $surfacePostings, $surfacePostings <= $maxSurfaceRows),
        wp_fts_wc_gate('surface_storage_per_document_total_bound', "<= {$maxTotalRows}", $totalPostings, $totalPostings <= $maxTotalRows),
        wp_fts_wc_gate('surface_storage_amplification_measured', 'finite positive ratios', [$surfacePerDocument, $totalPerDocument, $postingAmplification, $termAmplification], is_finite($surfacePerDocument) && is_finite($totalPerDocument) && is_finite($postingAmplification) && is_finite($termAmplification) && $surfacePerDocument > 0.0 && $totalPerDocument > 0.0 && $postingAmplification >= 1.0 && $termAmplification >= 1.0),
    ];

    return [
        'schema' => 'relational-fts-surface-storage-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'documents' => $documentRows,
        'counts' => $counts,
        'amplification' => [
            'surface_postings_per_document' => $surfacePerDocument,
            'total_postings_per_document' => $totalPerDocument,
            'total_to_lexical_posting_ratio' => $postingAmplification,
            'total_to_lexical_term_ratio' => $termAmplification,
        ],
        'hard_row_envelope' => [
            'surface_postings' => $maxSurfaceRows,
            'total_postings' => $maxTotalRows,
        ],
        'gates' => $gates,
    ];
}

/**
 * @param array<string,mixed> $manifest
 * @return array<string,array{query:string,options:array<string,mixed>}>
 */
function wp_fts_wc_case_definitions(array $manifest): array
{
    $common = ['query_lang' => 'en', 'post_types' => ['post'], 'post_statuses' => ['publish'], 'limit' => 20, 'include_snippets' => true, 'explain' => true];

    return [
        'common_or' => ['query' => 'commonalpha commonbeta commongamma', 'options' => $common + ['mode' => 'OR', 'prefix_matching' => false]],
        'max_valid_or_prefix' => [
            'query' => implode(' ', [...array_map(
                static fn(int $term): string => 'maxcommon' . str_pad((string) $term, 2, '0', STR_PAD_LEFT),
                range(1, 11)
            ), 'prefixprobe']),
            'options' => $common + ['mode' => 'OR', 'prefix_matching' => true, 'prefix_min_length' => 4],
        ],
        // Put the rare group last so a planner that blindly anchors the first
        // source occurrence cannot satisfy the worst-case proof.
        'rare_anchor_and' => ['query' => 'commonalpha commonbeta rareanchor', 'options' => $common + ['mode' => 'AND', 'prefix_matching' => false]],
        'prefix_fanout' => ['query' => 'prefixprobe', 'options' => $common + ['mode' => 'OR', 'prefix_matching' => true, 'prefix_min_length' => 4]],
        // The prefix must remain final, while the rare exact group is still
        // deliberately not first.
        'surface_rarest_exact_anchor_and' => ['query' => 'commonalpha rareanchor prefixprobe', 'options' => $common + ['mode' => 'AND', 'prefix_matching' => true, 'prefix_min_length' => 4]],
        // One exact candidate with 8,000+ postings against a still broader
        // prefixprobe surface range proves the rank arm classifies the bounded
        // candidate envelope instead of scanning every matching prefix row.
        'surface_dense_candidate_prefix_and' => ['query' => 'candidateanchor prefixprobe', 'options' => $common + ['mode' => 'AND', 'prefix_matching' => true, 'prefix_min_length' => 4]],
        'selective_prefix_anchor_and' => ['query' => 'commonalpha selectiveprefix', 'options' => $common + ['mode' => 'AND', 'prefix_matching' => true, 'prefix_min_length' => 4]],
        'hidden_dirty_head' => ['query' => 'visibilityprobe', 'options' => $common + ['mode' => 'OR', 'prefix_matching' => false]],
        'impossible_and' => ['query' => 'absentmandatoryprobe prefixprobe', 'options' => $common + ['mode' => 'AND', 'prefix_matching' => true, 'prefix_min_length' => 4]],
        'all_packs' => ['query' => 'commonalpha', 'options' => $common + ['mode' => 'OR', 'prefix_matching' => false]],
        'ambiguous_morphology_or' => ['query' => 'chrząstki wpftsambanchor', 'options' => array_replace($common, ['query_lang' => 'pl', 'mode' => 'OR', 'prefix_matching' => false])],
        'ambiguous_morphology_and' => ['query' => 'chrząstki wpftsambanchor', 'options' => array_replace($common, ['query_lang' => 'pl', 'mode' => 'AND', 'prefix_matching' => false])],
        'field_impact' => ['query' => 'fieldprobe', 'options' => array_replace($common, ['query_lang' => 'en-US', 'mode' => 'OR', 'prefix_matching' => false])],
    ];
}

/** @param array<string,mixed> $options @return array<string,mixed> */
function wp_fts_wc_search_ready_options(array $options): array
{
    $status = WP_FTS_Plugin::search_takeover_status(false);
    $incarnation = $status['ready_incarnation'] ?? null;
    $profileHash = $status['ready_profile_hash'] ?? null;
    wp_fts_wc_assert(
        !empty($status['ready'])
        && is_string($incarnation)
        && strlen($incarnation) === 32
        && wp_fts_wc_is_ascii_hex($incarnation)
        && is_string($profileHash)
        && strlen($profileHash) === 40
        && wp_fts_wc_is_ascii_hex($profileHash),
        'Direct production search requires the published readiness capability.'
    );

    return array_replace($options, [
        '_search_ready_incarnation' => $incarnation,
        '_search_ready_profile_hash' => $profileHash,
    ]);
}

/**
 * @param array{query:string,options:array<string,mixed>} $definition
 * @return array<string,mixed>
 */
function wp_fts_wc_measure_case(WP_FTS_Searcher $searcher, string $caseId, array $definition): array
{
    $searchDefinition = $definition;
    $searchDefinition['options'] = wp_fts_wc_search_ready_options($definition['options']);
    for ($index = 0; $index < WP_FTS_WC_WARMUP_COUNT; $index++) {
        $searcher->search($searchDefinition['query'], $searchDefinition['options']);
    }

    $durations = [];
    $queryCounts = [];
    $ftsQueryCounts = [];
    $sqlBytes = [];
    $memoryDeltas = [];
    $memoryPeakDeltas = [];
    $rssDeltas = [];
    $diagnosticRssPeakIncrements = [];
    $rssPeaks = [];
    $payload = [];
    $sampleResults = [];
    $capturedSql = [];
    for ($index = 0; $index < WP_FTS_WC_WARM_SAMPLE_COUNT; $index++) {
        wp_fts_wc_reset_php_peak_usage();
        gc_collect_cycles();
        $memoryBefore = memory_get_usage(true);
        $rssBefore = wp_fts_wc_rss_bytes('VmRSS');
        $rssPeakBefore = wp_fts_wc_rss_bytes('VmHWM');
        $started = hrtime(true);
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($searchDefinition['query'], $searchDefinition['options']));
        $duration = wp_fts_wc_elapsed_ms($started);
        $memoryAfter = memory_get_usage(true);
        $memoryPeakAfter = memory_get_peak_usage(true);
        $rssAfter = wp_fts_wc_rss_bytes('VmRSS');
        $rssPeakAfter = wp_fts_wc_rss_bytes('VmHWM');
        $payload = wp_fts_wc_payload($recorded['result']);
        $sampleRows = wp_fts_wc_payload_results($payload);
        $sampleIds = array_map('intval', array_column($sampleRows, 'doc_id'));
        $sampleResults[] = [
            'iteration' => $index,
            'result_count' => count($sampleRows),
            'result_ids' => $sampleIds,
            'result_hash' => wp_fts_wc_result_hash($sampleRows),
            'payload_sha256' => wp_fts_wc_canonical_hash($payload),
            'has_more' => (bool) ($payload['has_more'] ?? false),
            'next_cursor' => isset($payload['next_cursor']) && is_scalar($payload['next_cursor']) ? (string) $payload['next_cursor'] : '',
            'contract_valid' => count($sampleRows) <= (int) ($definition['options']['limit'] ?? 20)
                && count($sampleIds) === count(array_unique($sampleIds))
                && !array_key_exists('retrieval_mode', $payload)
                && !array_key_exists('total_is_exact', $payload)
                && !array_key_exists('results_may_be_incomplete', $payload),
        ];
        $queries = array_values($recorded['queries']);
        $ftsQueries = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_search_statement'));
        $sampleIndex = array_key_last($sampleResults);
        $sampleResults[$sampleIndex]['query_count'] = count($queries);
        $sampleResults[$sampleIndex]['fts_query_count'] = count($ftsQueries);
        $sampleResults[$sampleIndex]['max_sql_bytes'] = $queries === [] ? 0 : max(array_map('strlen', $queries));
        $sampleResults[$sampleIndex]['statement_shape'] = wp_fts_wc_statement_shape(array_map(
            static fn(string $sql): array => ['sql' => $sql],
            $queries
        ));

        $durations[] = $duration;
        $queryCounts[] = count($queries);
        $ftsQueryCounts[] = count($ftsQueries);
        $sqlBytes[] = $queries === [] ? 0 : max(array_map('strlen', $queries));
        $memoryDeltas[] = max(0, $memoryAfter - $memoryBefore);
        $memoryPeakDeltas[] = max(0, $memoryPeakAfter - $memoryBefore);
        $rssDeltas[] = max(0, $rssAfter - $rssBefore);
        // VmHWM cannot be reset in this 200-sample process. This increment is
        // retained only as a cumulative warm-loop diagnostic; the dedicated
        // fresh child for this case supplies the authoritative peak delta.
        $diagnosticRssPeakIncrements[] = max(0, $rssPeakAfter - max($rssBefore, $rssPeakBefore));
        $rssPeaks[] = $rssPeakAfter;
        if ($capturedSql === []) {
            $capturedSql = $queries;
        }
    }

    $instrumentation = wp_fts_wc_instrument_case($searcher, $searchDefinition, $capturedSql);
    $rows = wp_fts_wc_payload_results($payload);
    $statementShape = wp_fts_wc_statement_shape(array_map(
        static fn(string $sql): array => ['sql' => $sql],
        $capturedSql
    ));

    return [
        'query' => $definition['query'],
        'options' => $definition['options'],
        'warmup_count' => WP_FTS_WC_WARMUP_COUNT,
        'sample_count' => count($durations),
        'samples' => $durations,
        'sample_results' => $sampleResults,
        'latency_ms' => wp_fts_wc_distribution($durations),
        'max_query_count' => max($queryCounts ?: [0]),
        'max_total_query_count' => max($queryCounts ?: [0]),
        'max_fts_query_count' => max($ftsQueryCounts ?: [0]),
        'max_sql_bytes' => max($sqlBytes ?: [0]),
        'max_memory_delta_bytes' => max($memoryDeltas ?: [0]),
        'max_memory_peak_delta_bytes' => max($memoryPeakDeltas ?: [0]),
        'max_rss_delta_bytes' => max($rssDeltas ?: [0]),
        'max_diagnostic_rss_peak_increment_bytes' => max($diagnosticRssPeakIncrements ?: [0]),
        'rss_peak_bytes' => max($rssPeaks ?: [0]),
        'php_peak_bytes' => memory_get_peak_usage(true),
        'memory_attribution' => [
            'process_scope' => 'reused_warm_process_diagnostic',
            'rss_peak_delta_authoritative' => false,
            'authoritative_artifact' => "search-memory-{$caseId}.json",
        ],
        'result_count' => count($rows),
        'result_ids' => array_map('intval', array_column($rows, 'doc_id')),
        'result_hash' => wp_fts_wc_result_hash($rows),
        'result_score_signature' => wp_fts_wc_ordered_score_signature($rows),
        'payload_sha256' => wp_fts_wc_canonical_hash($payload),
        'has_more' => (bool) ($payload['has_more'] ?? false),
        'next_cursor' => isset($payload['next_cursor']) && is_scalar($payload['next_cursor']) ? (string) $payload['next_cursor'] : '',
        'statement_shape' => $statementShape,
        'explain' => is_array($payload['explain'] ?? null) ? $payload['explain'] : [],
        'captured_sql' => $capturedSql,
        'instrumentation' => $instrumentation,
    ];
}

/**
 * @param array{query:string,options:array<string,mixed>} $definition
 * @param string[] $capturedSql
 * @return array<string,mixed>
 */
function wp_fts_wc_instrument_case(WP_FTS_Searcher $searcher, array $definition, array $capturedSql): array
{
    global $wpdb;

    $threadId = (int) $wpdb->get_var('SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID = CONNECTION_ID()');
    wp_fts_wc_assert($threadId > 0, 'Could not map the WordPress DB connection to Performance Schema.');
    $beforeEvent = (int) $wpdb->get_var($wpdb->prepare('SELECT COALESCE(MAX(EVENT_ID),0) FROM performance_schema.events_statements_history_long WHERE THREAD_ID = %d', $threadId));
    $beforeHandlers = wp_fts_wc_handler_status();
    $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($definition['query'], $definition['options']));
    $afterHandlers = wp_fts_wc_handler_status();
    $events = $wpdb->get_results($wpdb->prepare(
        'SELECT EVENT_ID, SQL_TEXT, ROWS_EXAMINED, ROWS_SENT, CREATED_TMP_DISK_TABLES, SORT_MERGE_PASSES, NO_INDEX_USED, NO_GOOD_INDEX_USED, LOCK_TIME, TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID = %d AND EVENT_ID > %d ORDER BY EVENT_ID ASC',
        $threadId,
        $beforeEvent
    ), ARRAY_A) ?: [];
    $events = array_values(array_filter($events, static function (array $event): bool {
        $sql = strtoupper(ltrim((string) ($event['SQL_TEXT'] ?? '')));
        return !str_contains($sql, 'PERFORMANCE_SCHEMA.') && !str_starts_with($sql, 'SHOW SESSION STATUS');
    }));
    wp_fts_wc_assert($events !== [], 'Performance Schema did not retain the measured search statements.');
    $instrumentedSql = array_values($recorded['queries']);
    $instrumentedPayload = wp_fts_wc_payload($recorded['result']);
    $instrumentedRows = wp_fts_wc_payload_results($instrumentedPayload);
    $performanceSql = array_map(static fn(array $event): string => (string) ($event['SQL_TEXT'] ?? ''), $events);
    $capturedSqlHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $capturedSql);
    $instrumentedSqlHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $instrumentedSql);
    $performanceSqlHashes = array_map(static fn(string $sql): string => hash('sha256', $sql), $performanceSql);
    $statementMetrics = wp_fts_wc_search_statement_metrics($events);

    $rankSql = '';
    $explainByStatement = [];
    foreach ($instrumentedSql as $sql) {
        $kind = wp_fts_wc_search_statement_kind($sql);
        if ($kind === null) {
            continue;
        }
        $explainText = $wpdb->get_var('EXPLAIN FORMAT=JSON ' . $sql);
        wp_fts_wc_assert(is_string($explainText) && $explainText !== '', "EXPLAIN FORMAT=JSON returned no {$kind} plan.");
        $statementExplain = json_decode($explainText, true, 512, JSON_THROW_ON_ERROR);
        wp_fts_wc_assert(is_array($statementExplain), "EXPLAIN FORMAT=JSON returned malformed {$kind} JSON.");
        $access = [];
        wp_fts_wc_collect_database_table_access($statementExplain, $access);
        $relations = wp_fts_wc_sql_fts_relations($sql);
        $aliases = [];
        foreach ($relations as $relation) {
            $aliases[strtolower((string) $relation['alias'])] = (string) $relation['table'];
            $aliases[strtolower((string) $relation['relation'])] = (string) $relation['table'];
        }
        $ftsAccess = [];
        foreach ($access as $row) {
            $tableName = strtolower(trim((string) ($row['table_name'] ?? ''), "` \t\n\r\0\x0B"));
            $physical = $aliases[$tableName] ?? wp_fts_wc_fts_table_kind($tableName);
            if ($physical === null) {
                continue;
            }
            $ftsAccess[] = $row + ['physical_table' => $physical];
        }
        $expectedTables = array_values(array_unique(array_column($relations, 'table')));
        $observedTables = array_values(array_unique(array_column($ftsAccess, 'physical_table')));
        sort($expectedTables, SORT_STRING);
        sort($observedTables, SORT_STRING);
        $relationAllowlist = wp_fts_wc_expected_statement_relations($kind, $definition);
        $explainByStatement[$kind] = [
            'sql_sha256' => hash('sha256', $sql),
            'plan' => $statementExplain,
            'fts_relations' => $relations,
            'fts_table_access' => $ftsAccess,
            'declared_tables' => $expectedTables,
            'expected_tables' => $relationAllowlist,
            'observed_tables' => $observedTables,
            'full_scan_count' => count(array_filter($ftsAccess, static fn(array $row): bool => strtoupper((string) ($row['access_type'] ?? '')) === 'ALL')),
            'missing_key_count' => count(array_filter($ftsAccess, static fn(array $row): bool => trim((string) ($row['key'] ?? '')) === '')),
        ];
        if ($kind === 'rank') {
            $rankSql = $sql;
        }
    }
    $explain = null;
    $analyze = null;
    if ($rankSql !== '') {
        $explain = $explainByStatement['rank']['plan'] ?? null;
        if (str_contains(strtolower(wp_fts_wc_required_env('WP_FTS_WC_ENGINE')), 'mariadb')) {
            $analyzeText = $wpdb->get_var('ANALYZE FORMAT=JSON ' . $rankSql);
            wp_fts_wc_assert(is_string($analyzeText) && $analyzeText !== '', 'ANALYZE FORMAT=JSON returned no rank metrics.');
            $analyze = json_decode($analyzeText, true, 512, JSON_THROW_ON_ERROR);
        }
    }

    $handlerDelta = [];
    foreach ($afterHandlers as $name => $value) {
        $handlerDelta[$name] = max(0, $value - ($beforeHandlers[$name] ?? 0));
    }
    // Handler_read_* counts storage-engine operations, not logical rows. One
    // examined row can require a key lookup, a range step, and a derived-table
    // read, so retain that workload signal without relabeling it as rows.
    $handlerReadOperations = array_sum($handlerDelta);
    $eventRows = array_sum(array_map(static fn(array $event): int => (int) ($event['ROWS_EXAMINED'] ?? 0), $events));

    return [
        'handler_read_delta' => $handlerDelta,
        'handler_read_operations' => $handlerReadOperations,
        'performance_schema_events' => $events,
        'statement_metrics' => $statementMetrics,
        'performance_schema_rows_examined' => $eventRows,
        'rows_sent' => array_sum(array_map(static fn(array $event): int => (int) ($event['ROWS_SENT'] ?? 0), $events)),
        'created_tmp_disk_tables' => array_sum(array_map(static fn(array $event): int => (int) ($event['CREATED_TMP_DISK_TABLES'] ?? 0), $events)),
        'sort_merge_passes' => array_sum(array_map(static fn(array $event): int => (int) ($event['SORT_MERGE_PASSES'] ?? 0), $events)),
        'no_index_used' => array_sum(array_map(static fn(array $event): int => (int) ($event['NO_INDEX_USED'] ?? 0), $events)),
        'no_good_index_used' => array_sum(array_map(static fn(array $event): int => (int) ($event['NO_GOOD_INDEX_USED'] ?? 0), $events)),
        'captured_sql' => $instrumentedSql,
        'instrumented_result' => [
            'ids' => array_map('intval', array_column($instrumentedRows, 'doc_id')),
            'result_hash' => wp_fts_wc_result_hash($instrumentedRows),
            'score_signature' => wp_fts_wc_ordered_score_signature($instrumentedRows),
            'payload_sha256' => wp_fts_wc_canonical_hash($instrumentedPayload),
            'has_more' => (bool) ($instrumentedPayload['has_more'] ?? false),
            'next_cursor' => isset($instrumentedPayload['next_cursor']) && is_scalar($instrumentedPayload['next_cursor']) ? (string) $instrumentedPayload['next_cursor'] : '',
            'previous_cursor' => isset($instrumentedPayload['previous_cursor']) && is_scalar($instrumentedPayload['previous_cursor']) ? (string) $instrumentedPayload['previous_cursor'] : '',
        ],
        'sql_attribution' => [
            'statement_scope' => 'all_recorded_wpdb_including_transaction_control',
            'captured_statement_count' => count($capturedSql),
            'instrumented_statement_count' => count($instrumentedSql),
            'performance_schema_statement_count' => count($performanceSql),
            'captured_sql_sha256' => $capturedSqlHashes,
            'instrumented_wpdb_sql_sha256' => $instrumentedSqlHashes,
            'performance_schema_sql_sha256' => $performanceSqlHashes,
            'ordered_exact_match' => $capturedSqlHashes === $instrumentedSqlHashes && $instrumentedSqlHashes === $performanceSqlHashes,
            'performance_schema_sql_text_bytes' => array_map('strlen', $performanceSql),
        ],
        'explain_by_statement' => $explainByStatement,
        'explain' => $explain,
        'analyze' => $analyze,
    ];
}

/**
 * Independent production contract for the three hot statements. The planner
 * may only cost the dictionary; exact ranking reads postings plus visibility,
 * prefix ranking additionally reads one exact kind=1 dictionary identity, and
 * hydration may only revisit the two visibility relations for the bounded page.
 *
 * @param array{query:string,options:array<string,mixed>} $definition
 * @return string[]
 */
function wp_fts_wc_expected_statement_relations(string $kind, array $definition): array
{
    if ($kind === 'plan') {
        return ['terms', 'work'];
    }
    if ($kind === 'hydrate') {
        return ['documents', 'work'];
    }
    if ($kind !== 'rank') {
        return [];
    }

    $relations = ['documents', 'postings', 'work'];
    if (!empty($definition['options']['prefix_matching'])) {
        $relations[] = 'terms';
    }
    sort($relations, SORT_STRING);

    return $relations;
}

/** @return array{plan:array<string,int>,rank:array<string,int>,hydrate:array<string,int>} */
function wp_fts_wc_search_statement_metrics(array $events): array
{
    $empty = [
        'events' => 0,
        'rows_examined' => 0,
        'rows_sent' => 0,
        'created_tmp_disk_tables' => 0,
        'sort_merge_passes' => 0,
        'no_index_used' => 0,
        'no_good_index_used' => 0,
    ];
    $metrics = ['plan' => $empty, 'rank' => $empty, 'hydrate' => $empty];
    foreach ($events as $event) {
        if (!is_array($event)) {
            continue;
        }
        $kind = wp_fts_wc_search_statement_kind((string) ($event['SQL_TEXT'] ?? ''));
        if ($kind === null) {
            continue;
        }
        $metrics[$kind]['events']++;
        foreach (['ROWS_EXAMINED' => 'rows_examined', 'ROWS_SENT' => 'rows_sent', 'CREATED_TMP_DISK_TABLES' => 'created_tmp_disk_tables', 'SORT_MERGE_PASSES' => 'sort_merge_passes', 'NO_INDEX_USED' => 'no_index_used', 'NO_GOOD_INDEX_USED' => 'no_good_index_used'] as $source => $destination) {
            $metrics[$kind][$destination] += (int) ($event[$source] ?? 0);
        }
    }

    return $metrics;
}

/** Classify only the three explicitly marked production search statements. */
function wp_fts_wc_search_statement_kind(string $sql): ?string
{
    $sql = strtolower($sql);
    foreach (['plan', 'rank', 'hydrate'] as $kind) {
        if (str_contains($sql, "wp_fts:{$kind}")) {
            return $kind;
        }
    }

    return null;
}

/**
 * Tokenize the narrow SQL surface emitted by production search. Comments are
 * skipped, quoted identifiers are retained, and quoted values are skipped
 * unless a physical-schema classifier explicitly requests their decoded
 * tokens. This avoids substring/regexp parsing of nested SQL while preventing
 * an ordinary DML value from masquerading as table ownership.
 *
 * @return array<int,array{type:string,value:string}>
 */
function wp_fts_wc_sql_tokens(string $sql): array
{
    return iterator_to_array(wp_fts_wc_sql_token_stream($sql), false);
}

/**
 * Describe the normalized-surface range emitted by production search SQL.
 *
 * String literals are intentionally absent from the token stream. The proof
 * cares about operator, range, and join shape rather than rendered values:
 * every range has one lower and one upper bound, every prefix plan returns one
 * aggregate cost row, and AND ranking starts from the cheapest logical group
 * without constructing candidate-by-completion products.
 *
 * @return array<string,int>
 */
function wp_fts_wc_surface_range_sql_shape(string $sql): array
{
    $values = array_map(
        static fn(array $token): string => (string) ($token['value'] ?? ''),
        wp_fts_wc_sql_tokens($sql)
    );
    $countSequence = static function (array $needle) use ($values): int {
        $matches = 0;
        $needleCount = count($needle);
        $limit = count($values) - $needleCount;
        for ($offset = 0; $offset <= $limit; $offset++) {
            if (array_slice($values, $offset, $needleCount) === $needle) {
                $matches++;
            }
        }
        return $matches;
    };
    // The token stream emits the leading inequality operator separately from
    // an optional equals token, so each range predicate is counted once.
    $termLowerBounds = $countSequence(['pt', '.', 'term', '>']);
    $termUpperBounds = $countSequence(['pt', '.', 'term', '<']);

    return [
        'term_equality_count' => $countSequence(['pt', '.', 'term', '=']),
        'term_lower_bound_count' => $termLowerBounds,
        'term_upper_bound_count' => $termUpperBounds,
        'term_range_count' => $termLowerBounds + $termUpperBounds,
        'lang_equality_count' => $countSequence(['pt', '.', 'lang', '=']),
        'kind_one_count' => $countSequence(['pt', '.', 'kind', '=', '1']),
        'surface_doc_freq_sum_count' => $countSequence(['sum', '(', 'surface_identity', '.', 'doc_freq', ')']),
        'surface_exists_count_count' => $countSequence(['case', 'when', 'count', '(', '*', ')', '>']),
        'limit_one_count' => $countSequence(['limit', '1']),
        'surface_identity_limit_one_count' => $countSequence(['limit', '1', ')', 'surface_identity']),
        'term_identity_hint_count' => $countSequence(['pt', 'force', 'index', '(', 'term_identity', ')']),
        'exact_probe_posting_hint_count' => $countSequence(['po', 'force', 'index', '(', 'post_term', ')']),
        'classifier_posting_hint_count' => $countSequence(['ppo', 'force', 'index', '(', 'post_term', ')']),
        'prefix_posting_primary_hint_count' => $countSequence(['ppo', 'force', 'index', '(', 'primary', ')']),
        'selected_prefix_posting_primary_hint_count' => $countSequence(['prefix_posting', 'force', 'index', '(', 'primary', ')']),
        'classifier_term_primary_hint_count' => $countSequence(['pt', 'force', 'index', '(', 'primary', ')']),
        'exact_probe_join_count' => $countSequence([
            'po', '.', 'post_id', '=', 'c', '.', 'post_id', 'and',
            'po', '.', 'term_id', '=', 'q', '.', 'term_id',
        ]),
        'classifier_posting_join_count' => $countSequence([
            'ppo', '.', 'post_id', '=', 'c', '.', 'post_id',
        ]),
        'classifier_term_join_count' => $countSequence([
            'pt', '.', 'term_id', '=', 'ppo', '.', 'term_id',
        ]),
        'classifier_query_join_count' => $countSequence([
            'q', '.', 'term_id', '=', 'ppo', '.', 'term_id',
        ]),
        'selected_prefix_posting_join_count' => $countSequence([
            'prefix_posting', '.', 'term_id', '=', 'prefix_term', '.', 'term_id',
        ]),
        'prefix_posting_join_count' => $countSequence([
            'ppo', '.', 'term_id', '=', 'pt', '.', 'term_id',
        ]),
        'prefix_candidate_join_count' => $countSequence([
            'prefix_candidate', '.', 'post_id', '=', 'ppo', '.', 'post_id',
        ]),
    ];
}

/** Count dictionary-term inequalities through every concrete terms alias. */
function wp_fts_wc_dictionary_term_range_count(string $sql): int
{
    $termAliases = [];
    foreach (wp_fts_wc_sql_fts_relations($sql) as $relation) {
        if (($relation['table'] ?? null) !== 'terms') {
            continue;
        }
        $termAliases[strtolower((string) ($relation['alias'] ?? ''))] = true;
        $termAliases[strtolower((string) ($relation['relation'] ?? ''))] = true;
    }
    unset($termAliases['']);

    $tokens = wp_fts_wc_sql_tokens($sql);
    $ranges = 0;
    foreach ($tokens as $offset => $token) {
        if (!isset($termAliases[(string) ($token['value'] ?? '')])) {
            continue;
        }
        if (
            ($tokens[$offset + 1]['value'] ?? null) === '.'
            && ($tokens[$offset + 2]['value'] ?? null) === 'term'
            && in_array($tokens[$offset + 3]['value'] ?? null, ['<', '>'], true)
        ) {
            $ranges++;
        }
    }
    return $ranges;
}

/**
 * Describe the flat numeric VALUES relation in one real posting INSERT.
 *
 * A flat row constructor keeps parser depth constant. Rebuilding the same
 * input as thousands of SELECT/UNION arms would reintroduce the thread-stack
 * failure this proof is intended to catch.
 *
 * @return array{tuple_count:int,minimum_columns:int,maximum_columns:int,maximum_parenthesis_depth:int,select_count:int,union_count:int,from_count:int,valid_flat_values:bool}
 */
function wp_fts_wc_posting_values_shape(string $sql): array
{
    $depth = 0;
    $maximumDepth = 0;
    $keywordCounts = ['select' => 0, 'union' => 0, 'from' => 0];
    $seenValues = false;
    $expectTuple = false;
    $expectValue = false;
    $expectSeparator = false;
    $afterTuple = false;
    $balanced = true;
    $valid = true;
    $columns = 0;
    $tupleCount = 0;
    $minimumColumns = PHP_INT_MAX;
    $maximumColumns = 0;
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        $value = (string) ($token['value'] ?? '');
        if ($value === '(') {
            $depth++;
            $maximumDepth = max($maximumDepth, $depth);
        } elseif ($value === ')') {
            $depth--;
            $balanced = $balanced && $depth >= 0;
        } elseif (array_key_exists($value, $keywordCounts)) {
            $keywordCounts[$value]++;
        }

        if (!$seenValues) {
            if ($value === 'values') {
                $seenValues = true;
                $expectTuple = true;
            }
            continue;
        }
        if ($expectTuple) {
            $valid = $valid && $value === '(';
            $expectTuple = false;
            $expectValue = true;
            $columns = 0;
            continue;
        }
        if ($expectValue) {
            $valid = $valid
                && ($token['type'] ?? '') === 'word'
                && wp_fts_wc_is_ascii_digits($value);
            $columns++;
            $expectValue = false;
            $expectSeparator = true;
            continue;
        }
        if ($expectSeparator) {
            if ($value === ',') {
                $expectSeparator = false;
                $expectValue = true;
                continue;
            }
            $valid = $valid && $value === ')';
            $expectSeparator = false;
            $afterTuple = true;
            $tupleCount++;
            $minimumColumns = min($minimumColumns, $columns);
            $maximumColumns = max($maximumColumns, $columns);
            continue;
        }
        if ($afterTuple && $value === ',') {
            $afterTuple = false;
            $expectTuple = true;
            continue;
        }
        $valid = false;
    }
    $valid = $valid
        && $seenValues
        && $afterTuple
        && !$expectTuple
        && !$expectValue
        && !$expectSeparator
        && $balanced
        && $depth === 0
        && $tupleCount > 0
        && $keywordCounts['select'] === 0
        && $keywordCounts['union'] === 0
        && $keywordCounts['from'] === 0;

    return [
        'tuple_count' => $tupleCount,
        'minimum_columns' => $tupleCount === 0 ? 0 : $minimumColumns,
        'maximum_columns' => $maximumColumns,
        'maximum_parenthesis_depth' => $maximumDepth,
        'select_count' => $keywordCounts['select'],
        'union_count' => $keywordCounts['union'],
        'from_count' => $keywordCounts['from'],
        'valid_flat_values' => $valid,
    ];
}

/** @return Generator<int,array{type:string,value:string}> */
function wp_fts_wc_sql_token_stream(string $sql, bool $includeQuotedValues = false): Generator
{
    $length = strlen($sql);
    for ($index = 0; $index < $length;) {
        $character = $sql[$index];
        if (ord($character) <= 32) {
            $index++;
            continue;
        }
        if ($character === '/' && $index + 1 < $length && $sql[$index + 1] === '*') {
            $end = strpos($sql, '*/', $index + 2);
            $index = $end === false ? $length : $end + 2;
            continue;
        }
        if ($character === '#') {
            $end = strpos($sql, "\n", $index + 1);
            $index = $end === false ? $length : $end + 1;
            continue;
        }
        if (
            $character === '-'
            && $index + 2 < $length
            && $sql[$index + 1] === '-'
            && ord($sql[$index + 2]) <= 32
        ) {
            $end = strpos($sql, "\n", $index + 3);
            $index = $end === false ? $length : $end + 1;
            continue;
        }
        if ($character === "'" || $character === '"') {
            $quote = $character;
            $value = '';
            $index++;
            while ($index < $length) {
                if ($sql[$index] === '\\') {
                    if ($index + 1 < $length) {
                        $value .= $sql[$index + 1];
                    }
                    $index = min($length, $index + 2);
                    continue;
                }
                if ($sql[$index] !== $quote) {
                    $value .= $sql[$index++];
                    continue;
                }
                if ($index + 1 < $length && $sql[$index + 1] === $quote) {
                    $value .= $quote;
                    $index += 2;
                    continue;
                }
                $index++;
                break;
            }
            if ($includeQuotedValues) {
                yield ['type' => 'string', 'value' => strtolower($value)];
            }
            continue;
        }
        if ($character === '`') {
            $index++;
            $identifier = '';
            while ($index < $length) {
                if ($sql[$index] !== '`') {
                    $identifier .= $sql[$index++];
                    continue;
                }
                if ($index + 1 < $length && $sql[$index + 1] === '`') {
                    $identifier .= '`';
                    $index += 2;
                    continue;
                }
                $index++;
                break;
            }
            if ($identifier !== '') {
                yield ['type' => 'identifier', 'value' => strtolower($identifier)];
            }
            continue;
        }
        $byte = ord($character);
        if (($byte >= 48 && $byte <= 57) || ($byte >= 65 && $byte <= 90) || ($byte >= 97 && $byte <= 122) || $character === '_' || $character === '$') {
            $start = $index++;
            while ($index < $length) {
                $next = ord($sql[$index]);
                if (!(($next >= 48 && $next <= 57) || ($next >= 65 && $next <= 90) || ($next >= 97 && $next <= 122) || $sql[$index] === '_' || $sql[$index] === '$')) {
                    break;
                }
                $index++;
            }
            yield ['type' => 'word', 'value' => strtolower(substr($sql, $start, $index - $start))];
            continue;
        }
        yield ['type' => 'symbol', 'value' => $character];
        $index++;
    }
}

/** @return array<int,array{table:string,relation:string,alias:string}> */
function wp_fts_wc_sql_fts_relations(string $sql): array
{
    $tokens = wp_fts_wc_sql_tokens($sql);
    $relations = [];
    $keywords = array_fill_keys([
        'where', 'on', 'force', 'use', 'ignore', 'index', 'inner', 'left', 'right',
        'cross', 'join', 'order', 'group', 'having', 'limit', 'union', 'straight_join',
    ], true);
    $count = count($tokens);
    for ($index = 0; $index < $count; $index++) {
        if (
            ($tokens[$index]['type'] ?? '') !== 'word'
            || !in_array($tokens[$index]['value'], ['from', 'join', 'straight_join'], true)
        ) {
            continue;
        }
        $cursor = $index + 1;
        if (($tokens[$cursor]['value'] ?? null) === '(' || !in_array($tokens[$cursor]['type'] ?? '', ['word', 'identifier'], true)) {
            continue;
        }
        $relation = (string) $tokens[$cursor]['value'];
        $cursor++;
        while (($tokens[$cursor]['value'] ?? null) === '.' && in_array($tokens[$cursor + 1]['type'] ?? '', ['word', 'identifier'], true)) {
            $relation = (string) $tokens[$cursor + 1]['value'];
            $cursor += 2;
        }
        $table = wp_fts_wc_fts_table_kind($relation);
        if ($table === null) {
            continue;
        }
        $alias = $relation;
        if (($tokens[$cursor]['value'] ?? null) === 'as' && in_array($tokens[$cursor + 1]['type'] ?? '', ['word', 'identifier'], true)) {
            $alias = (string) $tokens[$cursor + 1]['value'];
        } elseif (
            in_array($tokens[$cursor]['type'] ?? '', ['word', 'identifier'], true)
            && !isset($keywords[$tokens[$cursor]['value']])
        ) {
            $alias = (string) $tokens[$cursor]['value'];
        }
        $relations[] = ['table' => $table, 'relation' => $relation, 'alias' => $alias];
    }

    return $relations;
}

/** Map prefixed physical table identifiers to the four relational roles. */
function wp_fts_wc_fts_table_kind(string $table): ?string
{
    $table = strtolower(trim($table, "` \t\n\r\0\x0B"));
    foreach (['terms', 'postings', 'documents', 'work'] as $kind) {
        if ($table === "fts_{$kind}" || str_ends_with($table, "_fts_{$kind}")) {
            return $kind;
        }
    }

    return null;
}

/** Count parsed candidate-ID IN lists that would reveal page-sized SQL fanout. */
function wp_fts_wc_candidate_id_list_count(string $sql): int
{
    $tokens = wp_fts_wc_sql_tokens($sql);
    $matches = 0;
    foreach ($tokens as $index => $token) {
        if (
            ($token['value'] ?? null) === 'post_id'
            && ($tokens[$index + 1]['value'] ?? null) === 'in'
            && ($tokens[$index + 2]['value'] ?? null) === '('
        ) {
            $matches++;
        }
    }

    return $matches;
}

/**
 * @return array<string,int>
 */
function wp_fts_wc_handler_status(): array
{
    global $wpdb;

    $wanted = ['Handler_read_first', 'Handler_read_key', 'Handler_read_last', 'Handler_read_next', 'Handler_read_prev', 'Handler_read_rnd', 'Handler_read_rnd_next'];
    $result = array_fill_keys($wanted, 0);
    foreach ($wpdb->get_results("SHOW SESSION STATUS WHERE Variable_name LIKE 'Handler_read%'") ?: [] as $row) {
        $name = (string) $row->Variable_name;
        if (array_key_exists($name, $result)) {
            $result[$name] = (int) $row->Value;
        }
    }

    return $result;
}

/**
 * @param array<string,mixed> $case
 * @param array{query:string,options:array<string,mixed>} $definition
 * @param array<string,mixed> $manifest
 */
function wp_fts_wc_assert_case_correctness(string $caseId, array $case, array $definition, array $manifest): void
{
    global $wpdb;

    $ids = array_values(array_unique(array_map('intval', $case['result_ids'] ?? [])));
    wp_fts_wc_assert(count($ids) === (int) ($case['result_count'] ?? -1), "{$caseId} returned duplicate or invalid document IDs.");
    $expectedShape = $caseId === 'impossible_and'
        ? ['plan' => 1, 'rank' => 0, 'hydrate' => 0]
        : ['plan' => 1, 'rank' => 1, 'hydrate' => 1];
    wp_fts_wc_assert(($case['statement_shape'] ?? null) === $expectedShape, "{$caseId} did not execute the exact bounded plan/rank/hydrate statement shape.");
    if ($caseId === 'impossible_and') {
        wp_fts_wc_assert($ids === [], 'Impossible mandatory group must return no rows.');
        return;
    }

    $minimumRows = match ($caseId) {
        'rare_anchor_and', 'surface_rarest_exact_anchor_and' => min(20, max(1, (int) $manifest['profile']['rare'] - 1)),
        'surface_dense_candidate_prefix_and', 'selective_prefix_anchor_and' => 1,
        'field_impact' => 3,
        'ambiguous_morphology_or' => 4,
        'ambiguous_morphology_and' => 2,
        default => 20,
    };
    wp_fts_wc_assert(count($ids) >= $minimumRows, "{$caseId} did not fill the expected page.");
    wp_fts_wc_assert(count($ids) <= 21, "{$caseId} returned more than LIMIT+1 rows.");
    $placeholders = implode(',', array_fill(0, count($ids), '%d'));
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT p.ID,p.post_status,p.post_password,w.post_id AS dirty_id
FROM {$wpdb->posts} p
LEFT JOIN `" . wp_fts_wc_identifier($wpdb->prefix . 'fts_work') . "` w ON w.post_id = p.ID
WHERE p.ID IN ({$placeholders})",
        ...$ids
    ), ARRAY_A) ?: [];
    wp_fts_wc_assert(count($rows) === count($ids), "{$caseId} returned missing canonical posts.");
    foreach ($rows as $row) {
        wp_fts_wc_assert((string) $row['post_status'] === 'publish', "{$caseId} returned a non-published post.");
        wp_fts_wc_assert((string) $row['post_password'] === '', "{$caseId} returned a password-protected post.");
        wp_fts_wc_assert($row['dirty_id'] === null, "{$caseId} returned a dirty post.");
    }

    if (in_array($caseId, ['rare_anchor_and', 'surface_rarest_exact_anchor_and'], true)) {
        $minimum = (int) $manifest['last_post_id'] - (int) $manifest['profile']['rare'] + 1;
        foreach ($ids as $id) {
            wp_fts_wc_assert($id >= $minimum, 'Rare-anchor AND returned a document outside the construction-known rare set.');
        }
    }
    if ($caseId === 'surface_dense_candidate_prefix_and') {
        $expectedCandidate = (int) $manifest['last_post_id'] - (int) $manifest['profile']['rare'] - 8;
        wp_fts_wc_assert($ids === [$expectedCandidate], 'Dense-candidate prefix AND did not return its one construction-known document.');
    }
    if ($caseId === 'selective_prefix_anchor_and') {
        $expectedCandidate = (int) $manifest['last_post_id'] - (int) $manifest['profile']['rare'] - 9;
        wp_fts_wc_assert($ids === [$expectedCandidate], 'Selective-prefix AND did not return its one construction-known document.');
    }
    if ($caseId === 'prefix_fanout') {
        // The newest English document deliberately owns a completion far past
        // the former expansion cap. Its normalized-surface posting must rank it
        // first without expanding completions into query text.
        $expectedNewestEnglish = (int) $manifest['last_post_id'] - 1;
        wp_fts_wc_assert(($ids[0] ?? 0) === $expectedNewestEnglish, 'Surface range omitted the construction-known completion beyond the fixed comparison sample.');
    }
    if ($caseId === 'hidden_dirty_head') {
        $firstClean = (int) $manifest['first_post_id'] + (int) $manifest['profile']['hidden'] + (int) $manifest['profile']['dirty'];
        foreach ($ids as $id) {
            wp_fts_wc_assert($id >= $firstClean, 'Hidden/dirty high-impact rows consumed the public page.');
        }
    }
    if ($caseId === 'field_impact') {
        $lastId = (int) $manifest['last_post_id'];
        $rare = (int) $manifest['profile']['rare'];
        $expected = [$lastId - $rare - 3, $lastId - $rare - 1, $lastId - $rare - 2];
        wp_fts_wc_assert($ids === $expected, 'Field impact did not rank the title-plus-body hit first or preserve the date tie-break for identical body hits.');
    }
    if (in_array($caseId, ['ambiguous_morphology_or', 'ambiguous_morphology_and'], true)) {
        $lastId = (int) $manifest['last_post_id'];
        $rare = (int) $manifest['profile']['rare'];
        $expected = $caseId === 'ambiguous_morphology_or'
            ? [$lastId - $rare - 7, $lastId - $rare - 4, $lastId - $rare - 6, $lastId - $rare - 5]
            : [$lastId - $rare - 7, $lastId - $rare - 4];
        wp_fts_wc_assert($ids === $expected, "{$caseId} did not preserve construction-known ambiguous morphology membership and order.");
        $explain = is_array($case['explain'] ?? null) ? $case['explain'] : [];
        wp_fts_wc_assert((int) ($explain['logical_group_count'] ?? 0) === 2, "{$caseId} split one ambiguous source occurrence into multiple logical groups.");
        wp_fts_wc_assert((int) ($explain['resolved_alternatives'] ?? 0) === 3, "{$caseId} did not resolve the two morphology alternatives plus the exact anchor.");
    }

    if (in_array($caseId, ['common_or', 'max_valid_or_prefix', 'prefix_fanout', 'all_packs'], true)) {
        wp_fts_wc_assert(!empty($case['has_more']), "{$caseId} did not expose has_more for a broad result.");
        wp_fts_wc_assert((string) ($case['next_cursor'] ?? '') !== '', "{$caseId} did not expose a search-after cursor.");
    }
}

/**
 * @param array<string,mixed> $case
 * @param array<string,mixed> $profile
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_case_gates(string $caseId, array $case, array $profile): array
{
    $engineFamily = wp_fts_wc_engine_family();
    $profileName = (string) $profile['name'];
    $latencyLimits = wp_fts_wc_case_latency_limits($caseId, $profile, $engineFamily);
    $limit = $latencyLimits['p95'];
    $p99Limit = $latencyLimits['p99'];
    $instrumentation = is_array($case['instrumentation'] ?? null) ? $case['instrumentation'] : [];
    $rowLimits = [
        'common_or' => $profile['name'] === '100k' ? 520000 : ($profile['name'] === '50k' ? 260000 : 50000),
        'max_valid_or_prefix' => $profile['name'] === '100k' ? 2500000 : ($profile['name'] === '50k' ? 1400000 : 225000),
        'rare_anchor_and' => 8192,
        'prefix_fanout' => $profile['name'] === '100k' ? 350000 : ($profile['name'] === '50k' ? 175000 : 70000),
        'surface_rarest_exact_anchor_and' => $profile['name'] === '100k' ? 350000 : ($profile['name'] === '50k' ? 175000 : 30000),
        'surface_dense_candidate_prefix_and' => 65536,
        'selective_prefix_anchor_and' => 2048,
        'hidden_dirty_head' => $profile['name'] === '2k' ? 10000 : ($profile['documents'] * 2),
        'impossible_and' => 128,
        'all_packs' => $profile['name'] === '2k' ? 26000 : ($profile['documents'] * 2),
    ];
    $rowsLimit = $rowLimits[$caseId] ?? ($profile['documents'] * 2);
    $handlerOperationLimits = $profile['name'] === '2k'
        ? $rowLimits
        : [
            'common_or' => $profile['documents'] * 14,
            'max_valid_or_prefix' => $profile['documents'] * 44,
            'prefix_fanout' => $profile['documents'] * 15,
            'surface_rarest_exact_anchor_and' => $profile['documents'] * 6,
            'hidden_dirty_head' => $profile['documents'] * 5,
            'all_packs' => $profile['documents'] * 12,
        ];
    $handlerOperationsLimit = $handlerOperationLimits[$caseId] ?? $rowsLimit;
    // MariaDB's statement counter includes derived-table iteration that MySQL
    // does not charge to ROWS_EXAMINED for the same SQL shape. Retain both raw
    // counters, but cap MariaDB's statement total with the storage-operation
    // envelope rather than presenting unlike engine accounting as one limit.
    $serverRowsLimit = $engineFamily === 'mariadb'
        ? $handlerOperationsLimit
        : $rowsLimit;
    $queriesExpected = $caseId === 'impossible_and' ? 1 : 3;
    $expectedShape = $caseId === 'impossible_and'
        ? ['plan' => 1, 'rank' => 0, 'hydrate' => 0]
        : ['plan' => 1, 'rank' => 1, 'hydrate' => 1];
    $capturedSql = is_array($case['captured_sql'] ?? null) ? array_map('strval', $case['captured_sql']) : [];
    $rankSqlStatements = array_values(array_filter(
        $capturedSql,
        static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'rank'
    ));
    $rankSql = count($rankSqlStatements) === 1 ? $rankSqlStatements[0] : '';
    $planSqlStatements = array_values(array_filter(
        $capturedSql,
        static fn(string $sql): bool => wp_fts_wc_search_statement_kind($sql) === 'plan'
    ));
    $planSql = count($planSqlStatements) === 1 ? $planSqlStatements[0] : '';
    $planSurfaceShape = $planSql === '' ? [] : wp_fts_wc_surface_range_sql_shape($planSql);
    $schemaStatements = count(array_filter($capturedSql, static function (string $sql): bool {
        $normalized = strtoupper(ltrim($sql));
        return str_starts_with($normalized, 'SHOW ')
            || str_starts_with($normalized, 'DESCRIBE ')
            || str_contains($normalized, 'INFORMATION_SCHEMA.');
    }));
    $candidateLists = array_sum(array_map('wp_fts_wc_candidate_id_list_count', $capturedSql));
    $rankPostingRelations = 0;
    foreach ($capturedSql as $sql) {
        if (wp_fts_wc_search_statement_kind($sql) !== 'rank') {
            continue;
        }
        $rankPostingRelations += count(array_filter(
            wp_fts_wc_sql_fts_relations($sql),
            static fn(array $relation): bool => ($relation['table'] ?? null) === 'postings'
        ));
    }
    $expectedPostingRelations = match ($caseId) {
        'common_or', 'max_valid_or_prefix', 'prefix_fanout', 'hidden_dirty_head', 'all_packs', 'ambiguous_morphology_or', 'field_impact' => 1,
        'rare_anchor_and', 'ambiguous_morphology_and', 'selective_prefix_anchor_and' => 2,
        'surface_rarest_exact_anchor_and', 'surface_dense_candidate_prefix_and' => 4,
        'impossible_and' => 0,
        default => null,
    };
    $prefixSqlShapes = array_map('wp_fts_wc_surface_range_sql_shape', $capturedSql);
    $surfaceLowerPredicates = array_sum(array_column($prefixSqlShapes, 'term_lower_bound_count'));
    $surfaceUpperPredicates = array_sum(array_column($prefixSqlShapes, 'term_upper_bound_count'));
    $surfaceKindPredicates = array_sum(array_column($prefixSqlShapes, 'kind_one_count'));
    $dictionaryTermRanges = array_sum(array_map('wp_fts_wc_dictionary_term_range_count', $capturedSql));
    $explain = is_array($case['explain'] ?? null) ? $case['explain'] : [];
    $statementMetrics = is_array($instrumentation['statement_metrics'] ?? null) ? $instrumentation['statement_metrics'] : [];
    $eventShape = [];
    foreach (array_keys($expectedShape) as $kind) {
        $eventShape[$kind] = (int) ($statementMetrics[$kind]['events'] ?? -1);
    }
    $explainByStatement = is_array($instrumentation['explain_by_statement'] ?? null) ? $instrumentation['explain_by_statement'] : [];
    $expectedExplainKinds = array_keys(array_filter($expectedShape, static fn(int $count): bool => $count > 0));
    $actualExplainKinds = array_keys($explainByStatement);
    sort($expectedExplainKinds, SORT_STRING);
    sort($actualExplainKinds, SORT_STRING);
    $explainCoverage = true;
    $explainFullScans = 0;
    $explainMissingKeys = 0;
    $expectedRelationSets = [];
    $declaredRelationSets = [];
    $observedRelationSets = [];
    $caseDefinition = [
        'query' => (string) ($case['query'] ?? ''),
        'options' => is_array($case['options'] ?? null) ? $case['options'] : [],
    ];
    foreach ($explainByStatement as $statementKind => $statementExplain) {
        if (!is_array($statementExplain)) {
            $explainCoverage = false;
            continue;
        }
        $statementKind = is_string($statementKind) ? $statementKind : '';
        $expectedRelationSets[$statementKind] = wp_fts_wc_expected_statement_relations($statementKind, $caseDefinition);
        $declaredRelationSets[$statementKind] = $statementExplain['declared_tables'] ?? null;
        $observedRelationSets[$statementKind] = $statementExplain['observed_tables'] ?? null;
        $explainCoverage = $explainCoverage
            && ($statementExplain['expected_tables'] ?? null) === $expectedRelationSets[$statementKind]
            && ($statementExplain['declared_tables'] ?? null) === $expectedRelationSets[$statementKind]
            && ($statementExplain['observed_tables'] ?? null) === $expectedRelationSets[$statementKind]
            && is_array($statementExplain['fts_table_access'] ?? null)
            && $statementExplain['fts_table_access'] !== [];
        $explainFullScans += (int) ($statementExplain['full_scan_count'] ?? 1);
        $explainMissingKeys += (int) ($statementExplain['missing_key_count'] ?? 1);
    }
    $planRowsSent = (int) ($statementMetrics['plan']['rows_sent'] ?? PHP_INT_MAX);
    $rankRowsSent = (int) ($statementMetrics['rank']['rows_sent'] ?? PHP_INT_MAX);
    $hydrateRowsSent = (int) ($statementMetrics['hydrate']['rows_sent'] ?? PHP_INT_MAX);
    $sampleResults = is_array($case['sample_results'] ?? null) ? array_values($case['sample_results']) : [];
