            'exact_probe' => 1,
            'selected_prefix_posting' => 1,
            'selected_prefix_posting_primary' => 1,
            'exact_anchor_materialization' => 0,
        ];
        $actualJoinShape = [
            'exact_probe' => $rankShape['exact_probe_join_count'] ?? 0,
            'selected_prefix_posting' => $rankShape['selected_prefix_posting_join_count'] ?? 0,
            'selected_prefix_posting_primary' => $rankShape['selected_prefix_posting_primary_hint_count'] ?? 0,
            'exact_anchor_materialization' => substr_count(strtolower($rankSql), 'select distinct ap.post_id'),
        ];
        $rankRowsExamined = (int) ($statementMetrics['rank']['rows_examined'] ?? PHP_INT_MAX);
        $gates[] = wp_fts_wc_gate(
            'selective_prefix_anchor_and_join_shape',
            $expectedJoinShape,
            $actualJoinShape,
            $actualJoinShape === $expectedJoinShape && ($rankShape['exact_probe_posting_hint_count'] ?? 0) === 1
        );
        $gates[] = wp_fts_wc_gate(
            'selective_prefix_anchor_and_explain_bounded',
            'pt term_identity -> prefix_posting PRIMARY anchor; exact po post_term probes',
            ['exact_probe' => $exactProbeAccess, 'prefix_terms' => $prefixTermAccess, 'prefix_postings' => $prefixPostingAccess],
            $prefixLedAccess
        );
        $gates[] = wp_fts_wc_gate(
            'selective_prefix_anchor_and_rank_rows_examined',
            "<= {$rowsLimit}; one selective prefix posting plus bounded exact probes",
            $rankRowsExamined,
            $rankRowsExamined <= $rowsLimit
        );
        $gates[] = wp_fts_wc_gate(
            'selective_prefix_anchor_and_common_exact_not_materialized',
            0,
            $actualJoinShape['exact_anchor_materialization'],
            $actualJoinShape['exact_anchor_materialization'] === 0
        );
    }
    if (in_array($caseId, ['common_or', 'max_valid_or_prefix', 'prefix_fanout', 'hidden_dirty_head', 'all_packs', 'ambiguous_morphology_or', 'field_impact'], true)) {
        $documentVisibilityJoin = ' d_f FORCE INDEX (document_presence) ON ';
        $postVisibilityJoin = ' wp_f FORCE INDEX (wp_fts_visibility) ON ';
        $documentVisibilityCount = substr_count($rankSql, $documentVisibilityJoin);
        $postVisibilityCount = substr_count($rankSql, $postVisibilityJoin);
        $innerExactVisibilityCount = substr_count($rankSql, 'd_exact_match');
        $innerPrefixVisibilityCount = substr_count($rankSql, 'd_prefix_match');
        $rankedPosition = strpos($rankSql, ') ranked');
        $dirtyVisibilityPosition = strpos($rankSql, ' dirty_f FORCE INDEX (dirty) ON ');
        $documentVisibilityPosition = strpos($rankSql, $documentVisibilityJoin);
        $postVisibilityPosition = strpos($rankSql, $postVisibilityJoin);
        $orderPosition = strpos($rankSql, 'ORDER BY scored.score');
        $visibilityOrderValid = $rankedPosition !== false
            && $dirtyVisibilityPosition !== false
            && $documentVisibilityPosition !== false
            && $postVisibilityPosition !== false
            && $orderPosition !== false
            && $rankedPosition < $dirtyVisibilityPosition
            && $dirtyVisibilityPosition < $postVisibilityPosition
            && $postVisibilityPosition < $documentVisibilityPosition
            && $documentVisibilityPosition < $orderPosition;
        $gates[] = wp_fts_wc_gate(
            "{$caseId}_broad_outer_visibility_shape",
            ['d_f' => 1, 'wp_f' => 1, 'd_exact_match' => 0, 'd_prefix_match' => 0],
            ['d_f' => $documentVisibilityCount, 'wp_f' => $postVisibilityCount, 'd_exact_match' => $innerExactVisibilityCount, 'd_prefix_match' => $innerPrefixVisibilityCount],
            $documentVisibilityCount === 1
                && $postVisibilityCount === 1
                && $innerExactVisibilityCount === 0
                && $innerPrefixVisibilityCount === 0
        );
        $gates[] = wp_fts_wc_gate("{$caseId}_broad_visibility_order", 'group postings < dirty generation < covering visibility < ORDER/LIMIT', $visibilityOrderValid, $visibilityOrderValid);
    }
    return $gates;
}

/**
 * @param array<string,mixed> $profile
 * @return array{p95:float,p99:float}
 */
function wp_fts_wc_case_latency_limits(string $caseId, array $profile, string $engineFamily): array
{
    $profileName = (string) $profile['name'];
    $p95Limits = $profileName === '100k'
        ? ['common_or' => 500.0, 'max_valid_or_prefix' => 2000.0, 'rare_anchor_and' => 150.0, 'prefix_fanout' => 500.0, 'surface_rarest_exact_anchor_and' => 500.0, 'surface_dense_candidate_prefix_and' => 500.0, 'selective_prefix_anchor_and' => 150.0, 'impossible_and' => 50.0, 'all_packs' => 500.0]
        : ['common_or' => 300.0, 'max_valid_or_prefix' => 1000.0, 'rare_anchor_and' => 100.0, 'prefix_fanout' => 300.0, 'surface_rarest_exact_anchor_and' => 300.0, 'surface_dense_candidate_prefix_and' => 300.0, 'selective_prefix_anchor_and' => 100.0, 'impossible_and' => 50.0, 'all_packs' => 500.0];
    $p99Limits = $profileName === '100k'
        ? ['common_or' => 750.0, 'max_valid_or_prefix' => 3000.0, 'rare_anchor_and' => 250.0, 'prefix_fanout' => 750.0, 'surface_rarest_exact_anchor_and' => 750.0, 'surface_dense_candidate_prefix_and' => 750.0, 'selective_prefix_anchor_and' => 250.0, 'impossible_and' => 100.0, 'all_packs' => 750.0]
        : ['common_or' => 500.0, 'max_valid_or_prefix' => 1500.0, 'rare_anchor_and' => 200.0, 'prefix_fanout' => 500.0, 'surface_rarest_exact_anchor_and' => 500.0, 'surface_dense_candidate_prefix_and' => 500.0, 'selective_prefix_anchor_and' => 200.0, 'impossible_and' => 100.0, 'all_packs' => 750.0];
    if ($profileName === '50k') {
        [$p95Overrides, $p99Overrides] = $engineFamily === 'mariadb'
            ? [
                ['common_or' => 4000.0, 'max_valid_or_prefix' => 5000.0, 'prefix_fanout' => 4000.0, 'all_packs' => 3500.0],
                ['common_or' => 6000.0, 'max_valid_or_prefix' => 6000.0, 'prefix_fanout' => 6000.0, 'all_packs' => 4000.0],
            ]
            : [
                ['common_or' => 500.0, 'prefix_fanout' => 600.0],
                ['common_or' => 550.0, 'prefix_fanout' => 650.0],
            ];
        $p95Limits = array_replace($p95Limits, $p95Overrides);
        $p99Limits = array_replace($p99Limits, $p99Overrides);
    } elseif ($profileName === '100k') {
        [$p95Overrides, $p99Overrides] = $engineFamily === 'mariadb'
            ? [
                ['common_or' => 6500.0, 'max_valid_or_prefix' => 8500.0, 'prefix_fanout' => 7000.0, 'all_packs' => 6500.0],
                ['common_or' => 7000.0, 'max_valid_or_prefix' => 9000.0, 'prefix_fanout' => 7500.0, 'all_packs' => 7000.0],
            ]
            : [
                ['common_or' => 5000.0, 'max_valid_or_prefix' => 12000.0, 'prefix_fanout' => 5500.0, 'all_packs' => 5000.0],
                ['common_or' => 6500.0, 'max_valid_or_prefix' => 14000.0, 'prefix_fanout' => 6500.0, 'all_packs' => 6500.0],
            ];
        $p95Limits = array_replace($p95Limits, $p95Overrides);
        $p99Limits = array_replace($p99Limits, $p99Overrides);
    }

    return [
        'p95' => (float) ($p95Limits[$caseId] ?? 500.0),
        'p99' => (float) ($p99Limits[$caseId] ?? 750.0),
    ];
}

function wp_fts_wc_engine_family(): string
{
    $engine = strtolower(wp_fts_wc_required_env('WP_FTS_WC_ENGINE'));

    return match (true) {
        str_contains($engine, 'mariadb') => 'mariadb',
        str_contains($engine, 'mysql') => 'mysql',
        default => throw new RuntimeException("Unsupported worst-case database engine: {$engine}"),
    };
}

/**
 * Run the same production search with exactly one and with every distributable
 * lemma pack active. This proves the statement-count invariant on both sides;
 * a single all-pack run cannot establish that pack cardinality is irrelevant.
 *
 * @param array{query:string,options:array<string,mixed>} $definition
 * @param array<string,mixed> $oracleCase
 * @param array<string,mixed> $manifest
 * @return array<string,mixed>
 */
function wp_fts_wc_pack_cardinality_statement_proof(array $definition, array $oracleCase, array $manifest): array
{
    $searchDefinition = $definition;
    $searchDefinition['options'] = wp_fts_wc_search_ready_options($definition['options']);
    $activePacks = is_array($manifest['active_packs'] ?? null) ? array_values($manifest['active_packs']) : [];
    wp_fts_wc_assert(count($activePacks) > 1, 'Pack-cardinality proof requires more than one distributable active pack.');
    $selected = $activePacks[0];
    foreach ($activePacks as $pack) {
        if (($pack['language'] ?? null) === 'en') {
            $selected = $pack;
            break;
        }
    }
    $language = is_string($selected['language'] ?? null) ? (string) $selected['language'] : '';
    $relativeManifest = is_string($selected['manifest'] ?? null) ? (string) $selected['manifest'] : '';
    $manifestPath = rtrim((string) WP_PLUGIN_DIR, '/\\') . '/indexer/' . ltrim($relativeManifest, '/\\');
    wp_fts_wc_assert($language !== '' && is_file($manifestPath), 'One-pack proof could not resolve its source-bound manifest.');

    $stored = get_option(WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION, []);
    $allPackAnalyzerOptions = WP_FTS_Plugin::runtime_analyzer_options();
    $onePackAnalyzerOptions = $allPackAnalyzerOptions;
    $onePackAnalyzerOptions['lemma_packs_by_lang'] = [$language => $manifestPath];

    // Keep the installed index publication intact. Mutating the stored analyzer
    // option would correctly revoke search readiness and enqueue reconciliation,
    // while this proof only compares two isolated query analyzers.
    $measure = static function (array $searchDefinition, array $analyzerOptions, array $packs): array {
        $storage = wp_fts_wc_storage_fixture(false);
        wp_fts_wc_assert(interface_exists('WP_FTS_Set_Oriented_Search_Storage') && $storage instanceof WP_FTS_Set_Oriented_Search_Storage, 'Pack-cardinality proof requires set-oriented storage.');
        $searcher = new WP_FTS_Searcher($storage, new WP_FTS_Analyzer($analyzerOptions));
        $recorded = wp_fts_wc_record_queries(static fn() => $searcher->search($searchDefinition['query'], $searchDefinition['options']));
        $payload = wp_fts_wc_payload($recorded['result']);
        $rows = wp_fts_wc_payload_results($payload);
        $queries = array_values($recorded['queries']);
        wp_fts_wc_assert(count($packs) <= 64, 'Pack-cardinality active-pack record exceeds its 64-pack bound.');
        wp_fts_wc_assert(count($queries) <= 16, 'Pack-cardinality SQL evidence exceeds its 16-statement diagnostic bound.');
        $statementBytes = array_map('strlen', $queries);
        foreach ($statementBytes as $bytes) {
            wp_fts_wc_assert($bytes <= 1048576, 'Pack-cardinality SQL evidence exceeds its 1 MiB statement bound.');
        }
        wp_fts_wc_assert(array_sum($statementBytes) <= 4194304, 'Pack-cardinality SQL evidence exceeds its 4 MiB aggregate bound.');
        wp_fts_wc_assert(count($rows) <= 20, 'Pack-cardinality result evidence exceeds its 20-row page bound.');

        $measurement = [
            'active_pack_count' => count($packs),
            'active_pack_ids' => array_values(array_map(static fn(array $pack): string => (string) ($pack['pack_id'] ?? ''), $packs)),
            'query_count' => count($queries),
            'statement_shape' => wp_fts_wc_statement_shape(array_map(static fn(string $sql): array => ['sql' => $sql], $queries)),
            'statement_bytes' => $statementBytes,
            'max_sql_bytes' => $statementBytes === [] ? 0 : max($statementBytes),
            'sql_total_bytes' => array_sum($statementBytes),
            'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $queries),
            'sql' => $queries,
            'result_ids' => array_map('intval', array_column($rows, 'doc_id')),
            'result_score_signature' => wp_fts_wc_ordered_score_signature($rows),
        ];
        wp_fts_wc_assert_json_evidence_bytes($measurement, 8388608, 'Pack-cardinality measurement');

        return $measurement;
    };

    $onePack = $measure($searchDefinition, $onePackAnalyzerOptions, [$selected]);
    $allPacks = $measure($searchDefinition, $allPackAnalyzerOptions, $activePacks);
    $expectedShape = ['plan' => 1, 'rank' => 1, 'hydrate' => 1];
    $gates = [
        wp_fts_wc_gate('one_pack_runtime_cardinality', 1, $onePack['active_pack_count'], $onePack['active_pack_count'] === 1),
        wp_fts_wc_gate('all_pack_runtime_cardinality', count($activePacks), $allPacks['active_pack_count'], $allPacks['active_pack_count'] === count($activePacks)),
        wp_fts_wc_gate('one_pack_statement_count', 3, $onePack['query_count'], $onePack['query_count'] === 3 && $onePack['statement_shape'] === $expectedShape),
        wp_fts_wc_gate('all_pack_statement_count', 3, $allPacks['query_count'], $allPacks['query_count'] === 3 && $allPacks['statement_shape'] === $expectedShape),
        wp_fts_wc_gate('pack_cardinality_statement_count_equal', $onePack['query_count'], $allPacks['query_count'], $onePack['query_count'] === $allPacks['query_count']),
        wp_fts_wc_gate('one_pack_independent_oracle_order', $oracleCase['result_ids'] ?? null, $onePack['result_ids'], ($oracleCase['result_ids'] ?? null) === $onePack['result_ids']),
        wp_fts_wc_gate('one_pack_independent_oracle_scores', $oracleCase['result_score_signature'] ?? null, $onePack['result_score_signature'], ($oracleCase['result_score_signature'] ?? null) === $onePack['result_score_signature']),
        wp_fts_wc_gate('all_pack_independent_oracle_order', $oracleCase['result_ids'] ?? null, $allPacks['result_ids'], ($oracleCase['result_ids'] ?? null) === $allPacks['result_ids']),
        wp_fts_wc_gate('all_pack_independent_oracle_scores', $oracleCase['result_score_signature'] ?? null, $allPacks['result_score_signature'], ($oracleCase['result_score_signature'] ?? null) === $allPacks['result_score_signature']),
        wp_fts_wc_gate('pack_cardinality_option_unchanged', $stored, get_option(WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION, []), get_option(WP_FTS_Plugin::ANALYZER_OPTIONS_OPTION, []) === $stored),
    ];

    return [
        'schema' => 'relational-fts-pack-cardinality-v1',
        'status' => wp_fts_wc_gates_pass($gates) ? 'PASS' : 'FAIL',
        'one_pack' => $onePack,
        'all_packs' => $allPacks,
        'gates' => $gates,
    ];
}

/**
 * Exercise the stable WordPress PHP adapter and ensure it does not reintroduce
 * query fanout or reorder the storage-owned page.
 *
 * @param array<string,array{query:string,options:array<string,mixed>}> $definitions
 * @param array<string,mixed> $manifest
 * @return array{cases:array<string,mixed>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_public_adapter_proof(array $definitions, array $manifest, array $oracleCases): array
{
    // The component names its analyzer language `query_lang` and asks for plan
    // details. The stable WordPress API exposes `lang` and rejects `explain`.
    foreach ($definitions as &$definition) {
        $definition['options']['lang'] = $definition['options']['query_lang'];
        unset($definition['options']['query_lang']);
        unset($definition['options']['explain']);
    }
    unset($definition);

    $cases = [];
    $gates = [];
    foreach (['common_or', 'max_valid_or_prefix', 'rare_anchor_and', 'prefix_fanout', 'hidden_dirty_head'] as $caseId) {
        $definition = $definitions[$caseId];
        $started = hrtime(true);
        $recorded = wp_fts_wc_record_queries(static fn() => WP_FTS_Plugin::search($definition['query'], $definition['options']));
        $rows = is_array($recorded['result']) ? $recorded['result'] : [];
        $queries = array_values($recorded['queries']);
        $ftsQueries = array_values(array_filter($recorded['queries'], 'wp_fts_wc_is_search_statement'));
        wp_fts_wc_assert($rows !== [], "Public PHP adapter returned no rows for {$caseId}.");
        $case = [
            'duration_ms' => wp_fts_wc_elapsed_ms($started),
            'result_count' => count($rows),
            'result_ids' => array_map('intval', array_column($rows, 'doc_id')),
            'result_score_signature' => wp_fts_wc_ordered_score_signature($rows),
            'oracle_source' => 'direct-set-oriented-searcher',
            'query_count' => count($queries),
            'fts_query_count' => count($ftsQueries),
            'max_sql_bytes' => $queries === [] ? 0 : max(array_map('strlen', $queries)),
            'sql' => $queries,
        ];
        $cases[$caseId] = $case;
        $gates[] = wp_fts_wc_gate("public_{$caseId}_query_count", '<= 3', $case['query_count'], $case['query_count'] <= 3);
        $gates[] = wp_fts_wc_gate("public_{$caseId}_sql_bytes", '<= 32768', $case['max_sql_bytes'], $case['max_sql_bytes'] <= 32768);
        $gates[] = wp_fts_wc_gate("public_{$caseId}_page_rows", '<= 20', $case['result_count'], $case['result_count'] <= 20);
        $gates[] = wp_fts_wc_gate("public_{$caseId}_oracle_order", $oracleCases[$caseId]['result_ids'] ?? null, $case['result_ids'], ($oracleCases[$caseId]['result_ids'] ?? null) === $case['result_ids']);
        $gates[] = wp_fts_wc_gate("public_{$caseId}_oracle_scores", $oracleCases[$caseId]['result_score_signature'] ?? null, $case['result_score_signature'], ($oracleCases[$caseId]['result_score_signature'] ?? null) === $case['result_score_signature']);
    }

    $frontend = wp_fts_wc_frontend_cache_priming_proof(
        $definitions['common_or'],
        $manifest,
        is_array($oracleCases['common_or'] ?? null) ? $oracleCases['common_or'] : []
    );
    $cases['frontend'] = $frontend['cases'];
    array_push($gates, ...$frontend['gates']);

    return ['cases' => $cases, 'gates' => $gates];
}

/**
 * Prove a cold `posts_pre_query` page pays at most two batched WordPress cache
 * queries and ordinary result-loop metadata/taxonomy access pays none. Running
 * the same proof at 1, 20, and the maximum 50 rows catches hidden per-result
 * fanout that a single small page cannot expose.
 *
 * @param array{query:string,options:array<string,mixed>} $definition
 * @param array<string,mixed> $manifest
 * @param array<string,mixed> $oracleCase
 * @return array{cases:array<string,mixed>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_frontend_cache_priming_proof(array $definition, array $manifest, array $oracleCase): array
{
    global $wpdb;

    $termId = max(0, (int) ($manifest['term_id'] ?? 0));
    wp_fts_wc_assert($termId > 0, 'Frontend cache proof requires the construction-known category term.');

    $cases = [];
    $gates = [];
    $cachePrimeCounts = [];
    $authorPrimeCounts = [];
    $coreContract = wp_fts_wc_wp_query_cache_lifecycle_contract();
    $forceFrontend = static fn(mixed $enabled, mixed ...$unused): bool => true;
    add_filter(WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER, $forceFrontend, PHP_INT_MAX, 2);
    try {
        foreach ([1, 20, 50] as $pageSize) {
            $expectedRows = WP_FTS_Plugin::search(
                $definition['query'],
                array_replace($definition['options'], ['limit' => $pageSize])
            );
            $expectedIds = array_map('intval', array_column($expectedRows, 'doc_id'));
            wp_fts_wc_assert(count($expectedIds) === $pageSize, "Frontend cache proof requires a full {$pageSize}-row page.");
            wp_fts_wc_cold_result_caches($expectedIds, [1]);

            $preLoop = wp_fts_wc_record_query_ownership(
                static fn(): WP_Query => wp_fts_wc_run_frontend_wp_query($pageSize, true, true)
            );
            $wpQuery = $preLoop['result'];
            $posts = $wpQuery instanceof WP_Query && is_array($wpQuery->posts) ? $wpQuery->posts : [];
            $resultIds = array_map(static fn(object $post): int => (int) ($post->ID ?? 0), $posts);
            $shape = wp_fts_wc_frontend_cache_query_shape($preLoop['queries'], $preLoop['owners']);
            $previousPost = $GLOBALS['post'] ?? null;
            try {
                $firstLoop = wp_fts_wc_record_queries(static function () use ($wpQuery, $termId): array {
                    if (!$wpQuery instanceof WP_Query || !$wpQuery->have_posts()) {
                        return ['post_cache_hits' => 0, 'metadata_reads' => 0, 'category_hits' => 0, 'author_hits' => 0];
                    }
                    $wpQuery->the_post();
                    return wp_fts_wc_template_result_access($wpQuery->post, $termId);
                });
                $remainingLoop = wp_fts_wc_record_queries(static function () use ($wpQuery, $termId): array {
                    $postCacheHits = 0;
                    $metadataReads = 0;
                    $categoryHits = 0;
                    $authorHits = 0;
                    while ($wpQuery instanceof WP_Query && $wpQuery->have_posts()) {
                        $wpQuery->the_post();
                        $access = wp_fts_wc_template_result_access($wpQuery->post, $termId);
                        $postCacheHits += $access['post_cache_hits'];
                        $metadataReads += $access['metadata_reads'];
                        $categoryHits += $access['category_hits'];
                        $authorHits += $access['author_hits'];
                    }

                    return [
                        'post_cache_hits' => $postCacheHits,
                        'metadata_reads' => $metadataReads,
                        'category_hits' => $categoryHits,
                        'author_hits' => $authorHits,
                    ];
                });
            } finally {
                $GLOBALS['post'] = $previousPost;
            }
            $firstLoopEvidence = is_array($firstLoop['result']) ? $firstLoop['result'] : [];
            $remainingLoopEvidence = is_array($remainingLoop['result']) ? $remainingLoop['result'] : [];
            $loopEvidence = [];
            foreach (['post_cache_hits', 'metadata_reads', 'category_hits', 'author_hits'] as $key) {
                $loopEvidence[$key] = (int) ($firstLoopEvidence[$key] ?? 0) + (int) ($remainingLoopEvidence[$key] ?? 0);
            }
            $authorShape = wp_fts_wc_author_cache_query_shape($firstLoop['queries']);
            $caseId = "k{$pageSize}";
            $cachePrimeCounts[] = $shape['cache_prime'];
            $authorPrimeCounts[] = array_sum($authorShape);
            $cases[$caseId] = [
                'page_size' => $pageSize,
                'result_ids' => $resultIds,
                'expected_ids_sha256' => wp_fts_wc_canonical_hash($expectedIds),
                'pre_loop_statement_count' => count($preLoop['queries']),
                'statement_shape' => $shape,
                'first_loop_statement_count' => count($firstLoop['queries']),
                'first_loop_statement_shape' => $authorShape,
                'remaining_loop_statement_count' => count($remainingLoop['queries']),
                'loop_evidence' => $loopEvidence,
                'pre_loop_statement_owners' => $preLoop['owners'],
                'pre_loop_sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $preLoop['queries']),
            ];

            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_page_rows", $pageSize, count($posts), count($posts) === $pageSize);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_result_order", $expectedIds, $resultIds, $resultIds === $expectedIds);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_plugin_statement_shape", ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0], $shape['plugin'], $shape['plugin'] === ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0]);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_canonical_post_read_statements", 0, $shape['canonical_post_reads'], $shape['canonical_post_reads'] === 0);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_cache_prime_statement_count", '<= 2', $shape['cache_prime'], $shape['cache_prime'] <= 2);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_cache_prime_statement_shape", ['postmeta' => 1, 'term_relationships' => 1, 'other' => 0], $shape['core'], $shape['core'] === ['postmeta' => 1, 'term_relationships' => 1, 'other' => 0]);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_pre_loop_statement_ceiling", '<= 5', count($preLoop['queries']), count($preLoop['queries']) <= 5);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_first_loop_author_statement_count", '<= 2', count($firstLoop['queries']), count($firstLoop['queries']) <= 2);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_first_loop_author_statement_shape", ['users' => 1, 'usermeta' => 1, 'other' => 0], $authorShape, $authorShape === ['users' => 1, 'usermeta' => 1, 'other' => 0]);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_total_through_first_loop_ceiling", '<= 7', count($preLoop['queries']) + count($firstLoop['queries']), count($preLoop['queries']) + count($firstLoop['queries']) <= 7);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_remaining_result_loop_statements", 0, count($remainingLoop['queries']), $remainingLoop['queries'] === []);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_canonical_post_cache_hits", $pageSize, (int) ($loopEvidence['post_cache_hits'] ?? -1), (int) ($loopEvidence['post_cache_hits'] ?? -1) === $pageSize);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_metadata_reads", $pageSize, (int) ($loopEvidence['metadata_reads'] ?? -1), (int) ($loopEvidence['metadata_reads'] ?? -1) === $pageSize);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_category_hits", $pageSize, (int) ($loopEvidence['category_hits'] ?? -1), (int) ($loopEvidence['category_hits'] ?? -1) === $pageSize);
            $gates[] = wp_fts_wc_gate("frontend_cache_{$caseId}_author_hits", $pageSize, (int) ($loopEvidence['author_hits'] ?? -1), (int) ($loopEvidence['author_hits'] ?? -1) === $pageSize);
        }

        $stockExpectedRows = WP_FTS_Plugin::search(
            $definition['query'],
            array_replace($definition['options'], ['limit' => 20])
        );
        $stockExpectedIds = array_map('intval', array_column($stockExpectedRows, 'doc_id'));
        wp_fts_wc_assert(count($stockExpectedIds) === 20, 'Stock unscoped frontend proof requires a full 20-row page.');
        $stockUnscoped = wp_fts_wc_record_query_ownership(
            static fn(): WP_Query => wp_fts_wc_run_stock_unscoped_frontend_wp_query(20)
        );
        $stockQuery = $stockUnscoped['result'];
        $stockPosts = $stockQuery instanceof WP_Query && is_array($stockQuery->posts) ? $stockQuery->posts : [];
        $stockIds = array_map(static fn(object $post): int => (int) ($post->ID ?? 0), $stockPosts);
        $stockShape = wp_fts_wc_frontend_cache_query_shape($stockUnscoped['queries'], $stockUnscoped['owners']);
        $stockCoreLikeQueries = [];
        foreach ($stockUnscoped['queries'] as $index => $sql) {
            if (($stockUnscoped['owners'][$index] ?? null) !== 'core') {
                continue;
            }
            $lower = strtolower($sql);
            if (str_contains($lower, strtolower((string) $wpdb->posts)) && str_contains($lower, ' like ')) {
                $stockCoreLikeQueries[] = $sql;
            }
        }
        $stockOriginal = $stockQuery instanceof WP_Query && is_array($stockQuery->query)
            ? $stockQuery->query
            : [];
        $stockCandidate = $stockQuery instanceof WP_Query
            ? $stockQuery->get('wp_fts_search_candidate', null)
            : null;
        $stockUnavailable = $stockQuery instanceof WP_Query
            ? $stockQuery->get('wp_fts_search_unavailable', null)
            : null;
        $cases['stock_unscoped'] = [
            'original_has_post_type' => array_key_exists('post_type', $stockOriginal),
            'original_has_post_status' => array_key_exists('post_status', $stockOriginal),
            'fts_candidate' => $stockCandidate,
            'fts_unavailable' => $stockUnavailable,
            'result_ids' => $stockIds,
            'plugin_statement_count' => array_sum($stockShape['plugin']),
            'statement_shape' => $stockShape,
            'core_posts_like_statement_count' => count($stockCoreLikeQueries),
            'sql_sha256' => array_map(static fn(string $sql): string => hash('sha256', $sql), $stockUnscoped['queries']),
        ];
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_original_scope_omitted', ['post_type' => false, 'post_status' => false], ['post_type' => array_key_exists('post_type', $stockOriginal), 'post_status' => array_key_exists('post_status', $stockOriginal)], !array_key_exists('post_type', $stockOriginal) && !array_key_exists('post_status', $stockOriginal));
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_fts_candidate', true, $stockCandidate, $stockCandidate === true);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_available', null, $stockUnavailable, $stockUnavailable === null);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_result_order', $stockExpectedIds, $stockIds, $stockIds === $stockExpectedIds);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_plugin_statement_ceiling', '<= 3', array_sum($stockShape['plugin']), array_sum($stockShape['plugin']) <= 3);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_plugin_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0], $stockShape['plugin'], $stockShape['plugin'] === ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0]);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_zero_core_statements', 0, array_sum($stockShape['core']), array_sum($stockShape['core']) === 0);
        $gates[] = wp_fts_wc_gate('frontend_stock_unscoped_zero_core_posts_like', 0, count($stockCoreLikeQueries), $stockCoreLikeQueries === []);

        $flaglessExpectedRows = WP_FTS_Plugin::search(
            $definition['query'],
            array_replace($definition['options'], ['limit' => 20])
        );
        $flaglessExpectedIds = array_map('intval', array_column($flaglessExpectedRows, 'doc_id'));
        wp_fts_wc_assert(count($flaglessExpectedIds) === 20, 'Frontend flag-disabled cache proof requires a full 20-row page.');
        wp_fts_wc_cold_result_caches($flaglessExpectedIds, []);
        $flagless = wp_fts_wc_record_query_ownership(
            static fn(): WP_Query => wp_fts_wc_run_frontend_wp_query(20, false, false)
        );
        $flaglessQuery = $flagless['result'];
        $flaglessPosts = $flaglessQuery instanceof WP_Query && is_array($flaglessQuery->posts) ? $flaglessQuery->posts : [];
        $flaglessIds = array_map(static fn(object $post): int => (int) ($post->ID ?? 0), $flaglessPosts);
        $flaglessShape = wp_fts_wc_frontend_cache_query_shape($flagless['queries'], $flagless['owners']);
        $flaglessReads = wp_fts_wc_record_queries(static function () use ($flaglessPosts): int {
            $cacheHits = 0;
            foreach ($flaglessPosts as $post) {
                $postId = (int) ($post->ID ?? 0);
                $cached = get_post($postId);
                if (is_object($cached) && (int) ($cached->ID ?? 0) === $postId) {
                    $cacheHits++;
                }
            }
            return $cacheHits;
        });
        $cases['flags_false'] = [
            'result_ids' => $flaglessIds,
            'pre_loop_statement_count' => count($flagless['queries']),
            'statement_shape' => $flaglessShape,
            'post_cache_read_statement_count' => count($flaglessReads['queries']),
            'post_cache_hits' => (int) $flaglessReads['result'],
        ];

        $cacheDisabledExpectedRows = WP_FTS_Plugin::search(
            $definition['query'],
            array_replace($definition['options'], ['limit' => 50])
        );
        $cacheDisabledExpectedIds = array_map('intval', array_column($cacheDisabledExpectedRows, 'doc_id'));
        wp_fts_wc_assert(count($cacheDisabledExpectedIds) === 50, 'Cache-disabled frontend proof requires a full 50-row page.');
        wp_fts_wc_cold_result_caches($cacheDisabledExpectedIds, [1]);
        $cacheDisabled = wp_fts_wc_record_query_ownership(
            static fn(): WP_Query => wp_fts_wc_run_frontend_wp_query(50, true, true, false)
        );
        $cacheDisabledQuery = $cacheDisabled['result'];
        $cacheDisabledPosts = $cacheDisabledQuery instanceof WP_Query && is_array($cacheDisabledQuery->posts)
            ? $cacheDisabledQuery->posts
            : [];
        $cacheDisabledIds = array_map(static fn(object $post): int => (int) ($post->ID ?? 0), $cacheDisabledPosts);
        $cacheDisabledShape = wp_fts_wc_frontend_cache_query_shape($cacheDisabled['queries'], $cacheDisabled['owners']);
        $cacheDisabledPostCacheMisses = count(array_filter(
            $cacheDisabledPosts,
            static fn(object $post): bool => wp_cache_get((int) ($post->ID ?? 0), 'posts') === false
        ));
        $cacheDisabledRawPosts = count(array_filter(
            $cacheDisabledPosts,
            static fn(object $post): bool => ($post->filter ?? null) === 'raw'
        ));
        $cacheDisabledNormalization = wp_fts_wc_record_queries(static function () use ($cacheDisabledPosts): int {
            $normalized = 0;
            foreach ($cacheDisabledPosts as $post) {
                $canonical = get_post($post);
                if (is_object($canonical) && (int) ($canonical->ID ?? 0) === (int) ($post->ID ?? 0)) {
                    $normalized++;
                }
            }

            return $normalized;
        });
        $cases['cache_results_false'] = [
            'result_ids' => $cacheDisabledIds,
            'pre_loop_statement_count' => count($cacheDisabled['queries']),
            'statement_shape' => $cacheDisabledShape,
            'post_cache_misses' => $cacheDisabledPostCacheMisses,
            'raw_post_count' => $cacheDisabledRawPosts,
            'normalization_count' => (int) $cacheDisabledNormalization['result'],
            'normalization_statement_count' => count($cacheDisabledNormalization['queries']),
        ];
    } finally {
        remove_filter(WP_FTS_Plugin::FRONTEND_SEARCH_REPLACEMENT_FILTER, $forceFrontend, PHP_INT_MAX);
    }

    $gates[] = wp_fts_wc_gate('frontend_cache_prime_queries_independent_of_k', [2, 2, 2], $cachePrimeCounts, $cachePrimeCounts === [2, 2, 2]);
    $gates[] = wp_fts_wc_gate('frontend_author_prime_queries_independent_of_k', [2, 2, 2], $authorPrimeCounts, $authorPrimeCounts === [2, 2, 2]);
    $gates[] = wp_fts_wc_gate('frontend_wp_query_supported_version', '>= 6.5', $coreContract['wordpress_version'], $coreContract['supported_version']);
    $gates[] = wp_fts_wc_gate('frontend_wp_query_cache_lifecycle_contract', true, $coreContract, $coreContract['cache_lifecycle_valid']);
    $gates[] = wp_fts_wc_gate('frontend_cache_flags_false_result_order', $flaglessExpectedIds, $flaglessIds, $flaglessIds === $flaglessExpectedIds);
    $gates[] = wp_fts_wc_gate('frontend_cache_flags_false_plugin_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0], $flaglessShape['plugin'], $flaglessShape['plugin'] === ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0]);
    $gates[] = wp_fts_wc_gate('frontend_cache_flags_false_zero_prime_statements', 0, $flaglessShape['cache_prime'], $flaglessShape['cache_prime'] === 0 && $flaglessShape['core'] === ['postmeta' => 0, 'term_relationships' => 0, 'other' => 0]);
    $gates[] = wp_fts_wc_gate('frontend_cache_flags_false_canonical_post_cache_hits', 20, (int) $flaglessReads['result'], (int) $flaglessReads['result'] === 20);
    $gates[] = wp_fts_wc_gate('frontend_cache_flags_false_post_cache_read_statements', 0, count($flaglessReads['queries']), $flaglessReads['queries'] === []);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_result_order', $cacheDisabledExpectedIds, $cacheDisabledIds, $cacheDisabledIds === $cacheDisabledExpectedIds);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_plugin_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0], $cacheDisabledShape['plugin'], $cacheDisabledShape['plugin'] === ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0]);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_zero_core_statements', 0, array_sum($cacheDisabledShape['core']), $cacheDisabledShape['core'] === ['postmeta' => 0, 'term_relationships' => 0, 'other' => 0]);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_zero_canonical_post_reads', 0, $cacheDisabledShape['canonical_post_reads'], $cacheDisabledShape['canonical_post_reads'] === 0);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_post_cache_untouched', 50, $cacheDisabledPostCacheMisses, $cacheDisabledPostCacheMisses === 50);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_raw_post_objects', 50, $cacheDisabledRawPosts, $cacheDisabledRawPosts === 50);
    $gates[] = wp_fts_wc_gate('frontend_cache_results_false_normalization_reads', 0, count($cacheDisabledNormalization['queries']), $cacheDisabledNormalization['queries'] === [] && (int) $cacheDisabledNormalization['result'] === 50);
    $gates[] = wp_fts_wc_gate('frontend_total_query_count', '<= 5', $cases['k20']['pre_loop_statement_count'] ?? PHP_INT_MAX, (int) ($cases['k20']['pre_loop_statement_count'] ?? PHP_INT_MAX) <= 5);
    $gates[] = wp_fts_wc_gate('frontend_fts_query_count', 3, array_sum($cases['k20']['statement_shape']['plugin'] ?? []), array_sum($cases['k20']['statement_shape']['plugin'] ?? []) === 3);
    $gates[] = wp_fts_wc_gate('frontend_statement_shape', ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0], $cases['k20']['statement_shape']['plugin'] ?? null, ($cases['k20']['statement_shape']['plugin'] ?? null) === ['plan' => 1, 'rank' => 1, 'hydrate' => 1, 'other' => 0]);
    $gates[] = wp_fts_wc_gate('frontend_page_rows', 20, count($cases['k20']['result_ids'] ?? []), count($cases['k20']['result_ids'] ?? []) === 20);
    $gates[] = wp_fts_wc_gate('frontend_schema_statements', 0, $cases['k20']['statement_shape']['schema'] ?? -1, ($cases['k20']['statement_shape']['schema'] ?? -1) === 0);
    $gates[] = wp_fts_wc_gate('frontend_oracle_order', $oracleCase['result_ids'] ?? null, $cases['k20']['result_ids'] ?? null, ($oracleCase['result_ids'] ?? null) === ($cases['k20']['result_ids'] ?? null));

    $cases['wp_query_core_contract'] = $coreContract;

    return ['cases' => $cases, 'gates' => $gates];
}

/**
 * Bind the measured behavior to the WordPress 6.5+ control flow: a non-null
 * `posts_pre_query` result bypasses only the default SELECT, while cache priming
 * remains in `get_posts()` and author priming remains in `the_post()`.
 *
 * @return array{wordpress_version:string,supported_version:bool,posts_pre_query_token:int,post_normalization_token:int,post_cache_prime_token:int,author_cache_prime_token:int,get_posts_sha256:string,the_post_sha256:string,cache_lifecycle_valid:bool}
 */
function wp_fts_wc_wp_query_cache_lifecycle_contract(): array
{
    $methodTokens = static function (string $method): array {
        $reflection = new ReflectionMethod(WP_Query::class, $method);
        $file = $reflection->getFileName();
        if (!is_string($file) || $file === '') {
            return ['source' => '', 'tokens' => []];
        }
        $lines = file($file);
        if (!is_array($lines)) {
            return ['source' => '', 'tokens' => []];
        }
        $source = implode('', array_slice(
            $lines,
            $reflection->getStartLine() - 1,
            $reflection->getEndLine() - $reflection->getStartLine() + 1
        ));
        $values = [];
        foreach (token_get_all("<?php\n" . $source) as $token) {
            if (!is_array($token)) {
                continue;
            }
            if ($token[0] === T_STRING) {
                $values[] = $token[1];
            } elseif ($token[0] === T_CONSTANT_ENCAPSED_STRING) {
                $values[] = trim($token[1], "'\"");
            }
        }
        return ['source' => $source, 'tokens' => $values];
    };

    $getPosts = $methodTokens('get_posts');
    $thePost = $methodTokens('the_post');
    $postsPreQuery = array_search('posts_pre_query', $getPosts['tokens'], true);
    $postCachePrime = array_search('update_post_caches', $getPosts['tokens'], true);
    $authorCachePrime = array_search('update_post_author_caches', $thePost['tokens'], true);
    $postNormalization = false;
    if (is_int($postsPreQuery) && is_int($postCachePrime)) {
        foreach ($getPosts['tokens'] as $index => $token) {
            if ($index > $postsPreQuery && $index < $postCachePrime && $token === 'get_post') {
                $postNormalization = $index;
            }
        }
    }
    $version = (string) get_bloginfo('version');
    $supported = version_compare($version, '6.5', '>=');
    $valid = $supported
        && is_int($postsPreQuery)
        && is_int($postNormalization)
        && is_int($postCachePrime)
        && $postsPreQuery < $postNormalization
        && $postNormalization < $postCachePrime
        && is_int($authorCachePrime);

    return [
        'wordpress_version' => $version,
        'supported_version' => $supported,
        'posts_pre_query_token' => is_int($postsPreQuery) ? $postsPreQuery : -1,
        'post_normalization_token' => is_int($postNormalization) ? $postNormalization : -1,
        'post_cache_prime_token' => is_int($postCachePrime) ? $postCachePrime : -1,
        'author_cache_prime_token' => is_int($authorCachePrime) ? $authorCachePrime : -1,
        'get_posts_sha256' => hash('sha256', $getPosts['source']),
        'the_post_sha256' => hash('sha256', $thePost['source']),
        'cache_lifecycle_valid' => $valid,
    ];
}

/**
 * Attribute SQL while the complete query runs so WordPress's cache primes
 * cannot be mistaken for plugin-owned search statements.
 *
 * @return array{result:mixed,queries:string[],owners:string[]}
 */
function wp_fts_wc_record_query_ownership(callable $callback): array
{
    $queries = [];
    $owners = [];
    $filter = static function (string $sql) use (&$queries, &$owners): string {
        $owner = 'core';
        foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 64) as $frame) {
            if (($frame['class'] ?? null) === WP_FTS_Plugin::class) {
                $owner = 'plugin';
                break;
            }
        }
        $queries[] = $sql;
        $owners[] = $owner;
        return $sql;
    };
    add_filter('query', $filter, PHP_INT_MIN, 1);
    try {
        $result = $callback();
    } finally {
        remove_filter('query', $filter, PHP_INT_MIN);
    }

    return ['result' => $result, 'queries' => $queries, 'owners' => $owners];
}

/**
 * Run the complete core query lifecycle so cache priming happens after the
 * plugin's `posts_pre_query` callback, exactly where WordPress owns it.
 *
 * @return WP_Query The completed query is retained for the real template loop.
 */
function wp_fts_wc_run_frontend_wp_query(int $pageSize, bool $updateTermCache, bool $updateMetaCache, bool $cacheResults = true): WP_Query
{
    global $wp_query, $wp_the_query;

    $previousQuery = $wp_query ?? null;
    $previousMainQuery = $wp_the_query ?? null;
    $query = new WP_Query();
    $wp_query = $query;
    $wp_the_query = $query;
    try {
        $query->query([
            's' => 'commonalpha commonbeta commongamma',
            'wp_fts_lang' => 'en',
            'posts_per_page' => $pageSize,
            'post_type' => 'post',
            'post_status' => 'publish',
            'paged' => 1,
            'suppress_filters' => false,
            'cache_results' => $cacheResults,
            'update_post_term_cache' => $updateTermCache,
            'update_post_meta_cache' => $updateMetaCache,
            'ignore_sticky_posts' => true,
        ]);
        return $query;
    } finally {
        $wp_query = $previousQuery;
        $wp_the_query = $previousMainQuery;
    }
}

/** Run a stock `/?s=...` main query with no explicit type or status scope. */
function wp_fts_wc_run_stock_unscoped_frontend_wp_query(int $pageSize): WP_Query
{
    global $wp_query, $wp_the_query;

    $previousQuery = $wp_query ?? null;
    $previousMainQuery = $wp_the_query ?? null;
    $query = new WP_Query();
    $wp_query = $query;
    $wp_the_query = $query;
    try {
        $query->query([
            's' => 'commonalpha commonbeta commongamma',
            'wp_fts_lang' => 'en',
            'posts_per_page' => $pageSize,
            'paged' => 1,
            'suppress_filters' => false,
            'cache_results' => false,
            'update_post_term_cache' => false,
            'update_post_meta_cache' => false,
            'ignore_sticky_posts' => true,
        ]);
        return $query;
    } finally {
        $wp_query = $previousQuery;
        $wp_the_query = $previousMainQuery;
    }
}

/** Evict every post and author cache whose absence can turn one result into SQL. */
function wp_fts_wc_cold_result_caches(array $postIds, array $authorIds): void
{
    $taxonomies = get_object_taxonomies('post');
    foreach ($postIds as $postId) {
        $postId = (int) $postId;
        clean_post_cache($postId);
        wp_cache_delete($postId, 'posts');
        wp_cache_delete($postId, 'post_meta');
        foreach ($taxonomies as $taxonomy) {
            wp_cache_delete($postId, "{$taxonomy}_relationships");
        }
    }
    foreach ($authorIds as $authorId) {
        $authorId = (int) $authorId;
        clean_user_cache($authorId);
        wp_cache_delete($authorId, 'users');
        wp_cache_delete($authorId, 'user_meta');
    }
}

/**
 * Exercise the post, metadata, taxonomy, and author reads used by ordinary
 * templates after core has performed its bounded cache primes.
 *
 * @return array{post_cache_hits:int,metadata_reads:int,category_hits:int,author_hits:int}
 */
function wp_fts_wc_template_result_access(object $post, int $termId): array
{
    $postId = (int) ($post->ID ?? 0);
    $authorId = (int) ($post->post_author ?? 0);
    $cached = wp_cache_get($postId, 'posts');
    $terms = get_the_terms($postId, 'category');
    $termIds = is_array($terms)
        ? array_map(static fn(object $term): int => (int) ($term->term_id ?? 0), $terms)
        : [];
    $author = get_userdata($authorId);

    return [
        'post_cache_hits' => is_object($cached) && (int) ($cached->ID ?? 0) === $postId ? 1 : 0,
        'metadata_reads' => is_array(get_post_meta($postId)) ? 1 : 0,
        'category_hits' => in_array($termId, $termIds, true) ? 1 : 0,
        'author_hits' => is_object($author) && (int) ($author->ID ?? 0) === $authorId ? 1 : 0,
    ];
}

/** Classify the two set-oriented user-cache queries at the first loop entry. */
function wp_fts_wc_author_cache_query_shape(array $queries): array
{
    global $wpdb;

    $shape = ['users' => 0, 'usermeta' => 0, 'other' => 0];
    foreach ($queries as $sql) {
        if (str_contains($sql, (string) $wpdb->usermeta)) {
            $shape['usermeta']++;
        } elseif (str_contains($sql, (string) $wpdb->users)) {
            $shape['users']++;
        } else {
            $shape['other']++;
        }
    }

    return $shape;
}

/**
 * Separate the three plugin statements from WordPress's two bounded cache
 * primes so an unrelated query cannot hide inside a relaxed total ceiling.
 *
 * @param string[] $queries
 * @param string[] $owners
 * @return array{plugin:array{plan:int,rank:int,hydrate:int,other:int},core:array{postmeta:int,term_relationships:int,other:int},cache_prime:int,canonical_post_reads:int,schema:int}
 */
function wp_fts_wc_frontend_cache_query_shape(array $queries, array $owners): array
{
    global $wpdb;

    $plugin = ['plan' => 0, 'rank' => 0, 'hydrate' => 0, 'other' => 0];
    $core = ['postmeta' => 0, 'term_relationships' => 0, 'other' => 0];
    $canonicalPostReads = 0;
    $schema = 0;
    foreach (array_values($queries) as $index => $sql) {
        if (($owners[$index] ?? null) === 'plugin') {
            $kind = 'other';
            foreach (['plan', 'rank', 'hydrate'] as $candidate) {
                if (str_contains($sql, "wp_fts:{$candidate}")) {
                    $kind = $candidate;
                    break;
                }
            }
            $plugin[$kind]++;
            continue;
        }

        $upper = strtoupper(ltrim($sql));
        if (str_starts_with($upper, 'SHOW ') || str_starts_with($upper, 'DESCRIBE ') || str_contains($upper, 'INFORMATION_SCHEMA.')) {
            $schema++;
        }
        if (str_contains($sql, (string) $wpdb->posts)) {
            $canonicalPostReads++;
        }
        if (str_contains($sql, (string) $wpdb->postmeta)) {
            $core['postmeta']++;
        } elseif (str_contains($sql, (string) $wpdb->term_relationships)) {
            $core['term_relationships']++;
        } else {
            $core['other']++;
        }
    }

    return [
        'plugin' => $plugin,
        'core' => $core,
        'cache_prime' => array_sum($core),
        'canonical_post_reads' => $canonicalPostReads,
        'schema' => $schema,
    ];
}

/**
 * Run real loopback requests through every WordPress web adapter and attribute
 * the completed SQL from the Apache connection through Performance Schema.
 * Direct method calls cannot prove routing, authentication, or that core LIKE
 * search did not run after the plugin returned.
 *
 * @param array<string,mixed> $manifest
 * @return array{cases:array<string,mixed>,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_actual_http_adapter_proof(array $manifest, array $oracleCase): array
{
    $attributionPlugin = wp_fts_wc_install_request_attribution_mu_plugin();
    register_shutdown_function(static function () use ($attributionPlugin): void {
        @unlink($attributionPlugin);
    });
    $definitions = wp_fts_wc_case_definitions($manifest);
    $definition = $definitions['common_or'];
    $query = (string) $definition['query'];
    $options = $definition['options'];
    $expectedIds = is_array($oracleCase['result_ids'] ?? null) ? array_values(array_map('intval', $oracleCase['result_ids'])) : [];
    $expectedScores = is_array($oracleCase['result_score_signature'] ?? null) ? array_values($oracleCase['result_score_signature']) : [];
    wp_fts_wc_assert(count($expectedIds) === 20, 'Actual adapter proof requires a full construction-known result page.');
    $authHeaders = wp_fts_wc_admin_auth_headers();
    $frontendHeaders = ['X-WP-FTS-WC-Main-Query-Probe' => '1'];
    $requests = [];
    $requests['rest'] = wp_fts_wc_measure_http_adapter(
        rest_url(WP_FTS_Plugin::REST_NAMESPACE . WP_FTS_Plugin::REST_SEARCH_ROUTE) . '?' . http_build_query([
            'q' => $query,
            'lang' => 'en',
            'mode' => 'OR',
            'limit' => 20,
        ], '', '&', PHP_QUERY_RFC3986),
        []
    );
    $restPayload = json_decode($requests['rest']['body'], true);
    $restRows = is_array($restPayload) && is_array($restPayload['results'] ?? null) ? $restPayload['results'] : [];
    $requests['rest']['result_ids'] = array_map('intval', array_column($restRows, 'doc_id'));
    $requests['rest']['result_score_signature'] = wp_fts_wc_ordered_score_signature($restRows);

    $requests['frontend'] = wp_fts_wc_measure_http_adapter(
        home_url('/?' . http_build_query([
            's' => $query,
            'post_type' => 'post',
            'wp_fts_lang' => 'en',
        ], '', '&', PHP_QUERY_RFC3986)),
        $frontendHeaders
    );
    $requests['frontend']['main_query_probe'] = wp_fts_wc_main_query_probe($requests['frontend']['body']);
    $requests['frontend']['result_ids'] = $requests['frontend']['main_query_probe']['result_ids'];

    $requests['frontend_stock_unscoped'] = wp_fts_wc_measure_http_adapter(
        home_url('/?' . http_build_query(['s' => $query, 'wp_fts_lang' => 'en'], '', '&', PHP_QUERY_RFC3986)),
        $frontendHeaders
    );
    $requests['frontend_stock_unscoped']['main_query_probe'] = wp_fts_wc_main_query_probe($requests['frontend_stock_unscoped']['body']);
    $requests['frontend_stock_unscoped']['result_ids'] = $requests['frontend_stock_unscoped']['main_query_probe']['result_ids'];

    $requests['admin_posts'] = wp_fts_wc_measure_http_adapter(
        admin_url('edit.php?' . http_build_query([
            's' => $query,
            'post_type' => 'post',
            'wp_fts_lang' => 'en',
        ], '', '&', PHP_QUERY_RFC3986)),
        $authHeaders
    );
    $requests['admin_posts']['result_ids'] = wp_fts_wc_html_post_ids($requests['admin_posts']['body']);

    $sandboxUrl = admin_url('options-general.php?' . http_build_query([
        'page' => WP_FTS_Plugin::ADMIN_PAGE_SLUG,
        'tab' => 'sandbox',
        'wp_fts_sandbox_query' => $query,
        'wp_fts_sandbox_lang' => 'en',
        'wp_fts_sandbox_search' => '1',
        'wp_fts_sandbox_mode' => 'OR',
        'wp_fts_sandbox_limit' => '20',
        'wp_fts_sandbox_prefix_matching' => '1',
        'wp_fts_sandbox_post_type' => ['post'],
        'wp_fts_sandbox_post_status' => ['publish'],
    ], '', '&', PHP_QUERY_RFC3986));
    $requests['sandbox'] = wp_fts_wc_measure_http_adapter($sandboxUrl, $authHeaders);
    $sandboxTransport = wp_fts_wc_sandbox_transport($requests['sandbox']['body']);
    $requests['sandbox']['result_ids'] = $sandboxTransport['post_ids'];

    $sandboxDetailsBody = [
        'action' => 'wp_fts_sandbox_result_details',
        'wp_fts_sandbox_details_nonce' => $sandboxTransport['nonce'],
        'wp_fts_sandbox_post_ids' => implode(',', $sandboxTransport['post_ids']),
        'wp_fts_sandbox_query' => $query,
        'wp_fts_sandbox_lang' => 'en',
        'wp_fts_sandbox_mode' => 'OR',
        'wp_fts_sandbox_limit' => '20',
        'wp_fts_sandbox_snippet_length' => '180',
        'wp_fts_sandbox_highlight' => '1',
        'wp_fts_sandbox_prefix_matching' => '1',
        'wp_fts_sandbox_post_type' => ['post'],
        'wp_fts_sandbox_post_status' => ['publish'],
    ];
    $requests['sandbox_ajax'] = wp_fts_wc_measure_http_adapter(
        admin_url('admin-ajax.php'),
        $authHeaders,
        $sandboxDetailsBody
    );
    $ajaxPayload = json_decode($requests['sandbox_ajax']['body'], true);
    $ajaxRows = is_array($ajaxPayload) && is_array($ajaxPayload['data']['rows'] ?? null)
        ? $ajaxPayload['data']['rows']
        : [];
    $requests['sandbox_ajax']['result_ids'] = array_map('intval', array_keys($ajaxRows));

    $missingTable = [
        'rest' => wp_fts_wc_measure_missing_table_http(
            rest_url(WP_FTS_Plugin::REST_NAMESPACE . WP_FTS_Plugin::REST_SEARCH_ROUTE) . '?' . http_build_query([
                'q' => $query,
                'lang' => 'en',
                'mode' => 'OR',
                'limit' => 20,
            ], '', '&', PHP_QUERY_RFC3986),
            []
        ),
        'frontend' => wp_fts_wc_measure_missing_table_http(
            home_url('/?' . http_build_query([
                's' => $query,
                'post_type' => 'post',
                'wp_fts_lang' => 'en',
            ], '', '&', PHP_QUERY_RFC3986)),
            $frontendHeaders
        ),
        'admin_posts' => wp_fts_wc_measure_missing_table_http(
            admin_url('edit.php?' . http_build_query([
                's' => $query,
                'post_type' => 'post',
                'wp_fts_lang' => 'en',
            ], '', '&', PHP_QUERY_RFC3986)),
            $authHeaders
        ),
        'sandbox' => wp_fts_wc_measure_missing_table_http($sandboxUrl, $authHeaders),
        'sandbox_ajax' => wp_fts_wc_measure_missing_table_http(
            admin_url('admin-ajax.php'),
            $authHeaders,
            $sandboxDetailsBody
        ),
    ];
    $missingTable['frontend']['main_query_probe'] = wp_fts_wc_main_query_probe($missingTable['frontend']['body']);
    $stageFailureUrl = rest_url(WP_FTS_Plugin::REST_NAMESPACE . WP_FTS_Plugin::REST_SEARCH_ROUTE) . '?' . http_build_query([
        'q' => $query,
        'lang' => 'en',
        'mode' => 'OR',
        'limit' => 20,
    ], '', '&', PHP_QUERY_RFC3986);
    $stageFailures = [];
    foreach (array_keys(WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS) as $failureStage) {
        $failureUrl = $failureStage === 'hydrate' ? admin_url('admin-ajax.php') : $stageFailureUrl;
        $failureHeaders = $failureStage === 'hydrate' ? $authHeaders : [];
        $failureBody = $failureStage === 'hydrate' ? $sandboxDetailsBody : null;
        $stageFailures[$failureStage] = wp_fts_wc_measure_stage_failure_http(
            $failureStage,
            $failureUrl,
            $failureHeaders,
            $failureBody
        );
    }

    $gates = [];
    foreach ($requests as $caseId => &$case) {
        $ids = array_values(array_filter(
            array_map('intval', is_array($case['result_ids'] ?? null) ? $case['result_ids'] : []),
            static fn(int $id): bool => $id > 0
        ));
        $expectedCaseIds = in_array($caseId, ['frontend', 'frontend_stock_unscoped'], true)
            ? array_slice($expectedIds, 0, 10)
            : $expectedIds;
        $expectedCount = count($expectedCaseIds);
        $expectedShape = $caseId === 'rest'
            ? ['plan' => 1, 'rank' => 1, 'hydrate' => 0]
            : ['plan' => 1, 'rank' => 1, 'hydrate' => 1];
        $expectedStatementCount = array_sum($expectedShape);
        $attribution = is_array($case['attribution'] ?? null) ? $case['attribution'] : [];
        $searchEvents = is_array($attribution['search_events'] ?? null)
            ? array_values($attribution['search_events'])
            : [];
        $pluginTableEvents = is_array($attribution['plugin_table_events'] ?? null)
            ? array_values($attribution['plugin_table_events'])
            : [];
        $optionEvents = is_array($attribution['plugin_option_sitemeta_events'] ?? null)
            ? array_values($attribution['plugin_option_sitemeta_events'])
            : [];
        $firstSearchEventId = $searchEvents === []
            ? PHP_INT_MAX
            : min(array_map(static fn(array $event): int => (int) ($event['event_id'] ?? PHP_INT_MAX), $searchEvents));
        $standaloneSearchOptionEvents = array_values(array_filter(
            $optionEvents,
            static fn(array $event): bool => (int) ($event['event_id'] ?? -1) >= $firstSearchEventId
                && !wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))
        ));
        $shape = wp_fts_wc_statement_shape($case['events']);
        $case['result_ids'] = $ids;
        $case['oracle_source'] = 'direct-set-oriented-searcher';
        $case['oracle_result_ids_sha256'] = wp_fts_wc_canonical_hash($expectedCaseIds);
        $case['statement_shape'] = $shape;
        $case['query_count'] = array_sum($shape);
        $case['rows_examined'] = array_sum(array_map(static fn(array $event): int => (int) ($event['rows_examined'] ?? 0), $case['events']));
        $case['body_sha256'] = hash('sha256', $case['body']);
        unset($case['body']);

        $gates[] = wp_fts_wc_gate("actual_{$caseId}_http_status", 200, $case['status'], $case['status'] === 200);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_result_count", $expectedCount, count($ids), count($ids) === $expectedCount);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_result_unique_count", $expectedCount, count(array_unique($ids)), count($ids) === $expectedCount && count(array_unique($ids)) === $expectedCount);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_result_order", $expectedCaseIds, $ids, $ids === $expectedCaseIds);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_query_count", $expectedStatementCount, $case['query_count'], $case['query_count'] === $expectedStatementCount);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_statement_shape", $expectedShape, $shape, $shape === $expectedShape);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_connection_attribution", ['relational-fts-http-attribution-v1', $case['request_id'] ?? null, 1], [$attribution['schema'] ?? null, $attribution['request_id'] ?? null, $attribution['terminal_event_count'] ?? null], ($attribution['schema'] ?? null) === 'relational-fts-http-attribution-v1' && ($attribution['request_id'] ?? null) === ($case['request_id'] ?? null) && (int) ($attribution['thread_id'] ?? 0) > 0 && ($attribution['terminal_event_count'] ?? null) === 1 && (int) ($attribution['end_event_id'] ?? 0) >= (int) ($attribution['start_event_id'] ?? PHP_INT_MAX));
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_all_table_sql_attributed", 0, count(is_array($attribution['unattributed_connection_events'] ?? null) ? $attribution['unattributed_connection_events'] : []), ($attribution['unattributed_connection_events'] ?? null) === []);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_exact_plugin_table_statement_set", $expectedStatementCount, count($pluginTableEvents), count($pluginTableEvents) === $expectedStatementCount && ($attribution['non_search_plugin_table_events'] ?? null) === []);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_exact_plugin_statement_set", $expectedStatementCount, count($searchEvents), count($searchEvents) === $expectedStatementCount);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_no_plugin_option_or_sitemeta_sql", 0, count($standaloneSearchOptionEvents), $standaloneSearchOptionEvents === []);
        $gates[] = wp_fts_wc_gate("actual_{$caseId}_core_like_queries", 0, count(is_array($case['core_like_events'] ?? null) ? $case['core_like_events'] : []), ($case['core_like_events'] ?? null) === []);
    }
    unset($case);
    $gates[] = wp_fts_wc_gate('actual_rest_oracle_scores', $expectedScores, $requests['rest']['result_score_signature'] ?? null, ($requests['rest']['result_score_signature'] ?? null) === $expectedScores);

    $expectedFaultStatus = ['rest' => 503, 'frontend' => 200, 'admin_posts' => 200, 'sandbox' => 200, 'sandbox_ajax' => 500];
    $preFaultOptionHashes = [];
    foreach ($missingTable as $caseId => &$case) {
        $measurements = wp_fts_wc_search_failure_attribution($case);
        $attribution = $measurements['attribution'];
        $pluginSearchEvents = $measurements['search_events'];
        $pluginControlEvents = $measurements['control_events'];
        $pluginOptionEvents = $measurements['option_events'];
        $failureEvents = $measurements['failure_events'];
        $pluginTableEvents = $measurements['plugin_table_events'];
        $nonSearchPluginTableEvents = $measurements['non_search_plugin_table_events'];
        $requiredOptionMutationCounts = $measurements['required_option_mutations'];
        $shape = wp_fts_wc_statement_shape($pluginSearchEvents);
        $pluginSearchShape = wp_fts_wc_statement_shape($pluginSearchEvents);
        $faultIsolation = is_array($case['fault_isolation'] ?? null) ? $case['fault_isolation'] : [];
        $body = $case['body'];
        $failedClosed = match ($caseId) {
            'rest' => $case['status'] === 503,
            'frontend' => ($case['main_query_probe']['result_ids'] ?? null) === []
                && ($case['main_query_probe']['search_unavailable'] ?? null) === 'runtime_failure',
            'admin_posts' => wp_fts_wc_html_post_ids($body) === [],
            'sandbox' => str_contains($body, 'Could not run the sandbox search'),
            'sandbox_ajax' => ($decoded = json_decode($body, true)) && ($decoded['success'] ?? true) === false,
            default => false,
        };
        $case['statement_shape'] = $shape;
        $case['query_count'] = array_sum($shape);
        $case['plugin_statement_count'] = count($failureEvents);
        $case['plugin_control_statement_count'] = count($pluginControlEvents);
        $case['plugin_option_sitemeta_statement_count'] = count($pluginOptionEvents);
        $case['body_sha256'] = hash('sha256', $body);
        unset($case['body']);
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_http_status", $expectedFaultStatus[$caseId], $case['status'], $case['status'] === $expectedFaultStatus[$caseId]);
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_fails_closed", true, $failedClosed, $failedClosed);
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_core_like_queries", 0, count($case['core_like_events']), $case['core_like_events'] === []);
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_failed_plan_statement_shape", ['plan' => 1, 'rank' => 0, 'hydrate' => 0], $shape, $shape === ['plan' => 1, 'rank' => 0, 'hydrate' => 0]);
        $gates[] = wp_fts_wc_gate(
            "missing_table_{$caseId}_failed_plan_plugin_attribution",
            ['shape' => ['plan' => 1, 'rank' => 0, 'hydrate' => 0], 'plugin_table_events' => 1, 'non_search_plugin_table_events' => 0],
            ['shape' => $pluginSearchShape, 'plugin_table_events' => count($pluginTableEvents), 'non_search_plugin_table_events' => count($nonSearchPluginTableEvents)],
            $pluginSearchShape === ['plan' => 1, 'rank' => 0, 'hydrate' => 0]
                && count($pluginSearchEvents) === 1
                && count($pluginTableEvents) === 1
                && $nonSearchPluginTableEvents === []
        );
        $gates[] = wp_fts_wc_gate(
            "missing_table_{$caseId}_failure_control_statement_set",
            '2..4 option/sitemeta statements, exactly one readiness revocation and one Health latch mutation, and no other plugin control SQL',
            [
                'plugin_control' => count($pluginControlEvents),
                'option_sitemeta' => count($pluginOptionEvents),
                'required_option_mutations' => $requiredOptionMutationCounts,
            ],
            count($pluginControlEvents) >= WP_FTS_WC_FAILED_SEARCH_MIN_CONTROL_STATEMENTS
                && count($pluginControlEvents) <= WP_FTS_WC_FAILED_SEARCH_MAX_CONTROL_STATEMENTS
                && count($pluginOptionEvents) === count($pluginControlEvents)
                && $requiredOptionMutationCounts === ['search_ready' => 1, 'health' => 1]
        );
        $gates[] = wp_fts_wc_gate(
            "missing_table_{$caseId}_total_plugin_statement_ceiling",
            '<= 5 (one failed plan plus at most four failure-latching controls)',
            count($failureEvents),
            count($failureEvents) >= 1 + WP_FTS_WC_FAILED_SEARCH_MIN_CONTROL_STATEMENTS
                && count($failureEvents) <= WP_FTS_WC_FAILED_SEARCH_MAX_PLUGIN_STATEMENTS
                && count($failureEvents) === 1 + count($pluginControlEvents)
        );
        $beforeOptionHashes = is_array($faultIsolation['before_option_sha256'] ?? null)
            ? $faultIsolation['before_option_sha256']
            : [];
        $afterOptionHashes = is_array($faultIsolation['after_option_sha256'] ?? null)
            ? $faultIsolation['after_option_sha256']
            : [];
        $preFaultOptionHashes[$caseId] = $beforeOptionHashes;
        $postFaultOptionHashes = is_array($faultIsolation['post_fault_option_sha256'] ?? null)
            ? $faultIsolation['post_fault_option_sha256']
            : [];
        $gates[] = wp_fts_wc_gate(
            "missing_table_{$caseId}_post_fault_state_latched",
            [
                'search_ready_revoked' => true,
                'health_unhealthy' => true,
                'search_runtime_failure_latched' => true,
                'schema_repair_scheduled' => true,
                'three hashed post-fault option snapshots',
            ],
            [
                'post_fault_search_ready_revoked' => $faultIsolation['post_fault_search_ready_revoked'] ?? null,
                'post_fault_health_unhealthy' => $faultIsolation['post_fault_health_unhealthy'] ?? null,
                'post_fault_health_latched' => $faultIsolation['post_fault_health_latched'] ?? null,
                'pre_fault_repair_scheduled' => $faultIsolation['pre_fault_repair_scheduled'] ?? null,
                'post_fault_repair_scheduled' => $faultIsolation['post_fault_repair_scheduled'] ?? null,
                'post_fault_option_sha256' => $postFaultOptionHashes,
            ],
            ($faultIsolation['schema'] ?? null) === 'relational-fts-missing-table-isolation-v1'
                && ($faultIsolation['post_fault_search_ready_revoked'] ?? null) === true
                && ($faultIsolation['post_fault_health_unhealthy'] ?? null) === true
                && ($faultIsolation['post_fault_health_latched'] ?? null) === true
                && is_bool($faultIsolation['pre_fault_repair_scheduled'] ?? null)
                && ($faultIsolation['post_fault_repair_scheduled'] ?? null) === true
                && array_keys($postFaultOptionHashes) === ['cron', 'health', 'search_ready']
                && count(array_filter(
                    $postFaultOptionHashes,
                    static fn(mixed $hash): bool => is_string($hash)
                        && strlen($hash) === 64
                        && strspn($hash, '0123456789abcdef') === 64
                )) === 3
        );
        $gates[] = wp_fts_wc_gate(
            "missing_table_{$caseId}_isolated_state_restored",
            ['pre_fault_search_ready' => true, 'restored' => true, 'three exact option snapshots'],
            $faultIsolation,
            ($faultIsolation['schema'] ?? null) === 'relational-fts-missing-table-isolation-v1'
                && ($faultIsolation['pre_fault_search_ready'] ?? null) === true
                && ($faultIsolation['restored'] ?? null) === true
                && $beforeOptionHashes === $afterOptionHashes
                && array_keys($beforeOptionHashes) === ['cron', 'health', 'search_ready']
                && count(array_filter(
                    $beforeOptionHashes,
                    static fn(mixed $hash): bool => is_string($hash)
                        && strlen($hash) === 64
                        && strspn($hash, '0123456789abcdef') === 64
                )) === 3
        );
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_connection_attribution", ['relational-fts-http-attribution-v1', $case['request_id'] ?? null, 1], [$attribution['schema'] ?? null, $attribution['request_id'] ?? null, $attribution['terminal_event_count'] ?? null], ($attribution['schema'] ?? null) === 'relational-fts-http-attribution-v1' && ($attribution['request_id'] ?? null) === ($case['request_id'] ?? null) && (int) ($attribution['thread_id'] ?? 0) > 0 && ($attribution['terminal_event_count'] ?? null) === 1);
        $gates[] = wp_fts_wc_gate("missing_table_{$caseId}_all_table_sql_attributed", 0, count(is_array($attribution['unattributed_connection_events'] ?? null) ? $attribution['unattributed_connection_events'] : []), ($attribution['unattributed_connection_events'] ?? null) === []);
    }
    unset($case);
    $preFaultStateSignatures = array_values(array_unique(array_map(
        'wp_fts_wc_canonical_hash',
        $preFaultOptionHashes
    )));
    $gates[] = wp_fts_wc_gate(
        'missing_table_all_adapters_same_pre_fault_state',
        'one exact capability, Health, and cron snapshot across all five adapters',
        $preFaultOptionHashes,
        array_keys($preFaultOptionHashes) === ['rest', 'frontend', 'admin_posts', 'sandbox', 'sandbox_ajax']
            && count($preFaultStateSignatures) === 1
    );

    $stagePreFaultOptionHashes = [];
    $orderedStages = ['plan', 'rank', 'hydrate'];
    foreach ($stageFailures as $failureStage => &$case) {
        $measurements = wp_fts_wc_search_failure_attribution($case);
        $attribution = $measurements['attribution'];
        $pluginEvents = $measurements['plugin_events'];
        $pluginSearchEvents = $measurements['search_events'];
        $pluginControlEvents = $measurements['control_events'];
        $pluginOptionEvents = $measurements['option_events'];
        $failureEvents = $measurements['failure_events'];
        $pluginTableEvents = $measurements['plugin_table_events'];
        $nonSearchPluginTableEvents = $measurements['non_search_plugin_table_events'];
        $requiredOptionMutationCounts = $measurements['required_option_mutations'];
        $actualOrderedStages = $measurements['ordered_search_stages'];
        $expectedOrderedStages = array_slice($orderedStages, 0, array_search($failureStage, $orderedStages, true) + 1);
        $expectedShape = [
            'plan' => 1,
            'rank' => in_array('rank', $expectedOrderedStages, true) ? 1 : 0,
            'hydrate' => in_array('hydrate', $expectedOrderedStages, true) ? 1 : 0,
        ];
        $shape = wp_fts_wc_statement_shape($pluginSearchEvents);
        $injectedEvents = array_values(array_filter(
            $pluginSearchEvents,
            static fn(array $event): bool => str_contains(
                (string) ($event['sql'] ?? ''),
                "wp_fts_wc_injected_failure:{$failureStage}"
            )
        ));
        $databaseErrorEvents = array_values(array_filter(
            $pluginEvents,
            static fn(array $event): bool => (int) ($event['mysql_errno'] ?? 0) !== 0
        ));
        $injectedEvent = count($injectedEvents) === 1 ? $injectedEvents[0] : [];
        $faultIsolation = is_array($case['fault_isolation'] ?? null) ? $case['fault_isolation'] : [];
        $body = (string) ($case['body'] ?? '');
        $payload = json_decode($body, true);
        $expectedStatus = $failureStage === 'hydrate' ? 500 : 503;
        $failedClosed = $failureStage === 'hydrate'
            ? (int) ($case['status'] ?? 0) === 500
                && is_array($payload)
                && ($payload['success'] ?? true) === false
            : (int) ($case['status'] ?? 0) === 503
                && is_array($payload)
                && ($payload['code'] ?? null) === 'wp_fts_search_unavailable';
        $beforeOptionHashes = is_array($faultIsolation['before_option_sha256'] ?? null)
            ? $faultIsolation['before_option_sha256']
            : [];
        $afterOptionHashes = is_array($faultIsolation['after_option_sha256'] ?? null)
            ? $faultIsolation['after_option_sha256']
            : [];
        $postFaultOptionHashes = is_array($faultIsolation['post_fault_option_sha256'] ?? null)
            ? $faultIsolation['post_fault_option_sha256']
            : [];
        $stagePreFaultOptionHashes[$failureStage] = $beforeOptionHashes;
        $case['ordered_search_stages'] = $actualOrderedStages;
        $case['statement_shape'] = $shape;
        $case['plugin_statement_count'] = count($failureEvents);
        $case['plugin_control_statement_count'] = count($pluginControlEvents);
        $case['plugin_option_sitemeta_statement_count'] = count($pluginOptionEvents);
        $case['body_sha256'] = hash('sha256', $body);
        unset($case['body']);

        $gates[] = wp_fts_wc_gate("stage_failure_{$failureStage}_http_status", $expectedStatus, $case['status'] ?? null, (int) ($case['status'] ?? 0) === $expectedStatus);
        $gates[] = wp_fts_wc_gate("stage_failure_{$failureStage}_fails_closed", true, $failedClosed, $failedClosed);
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_ordered_search_shape",
            ['ordered' => $expectedOrderedStages, 'shape' => $expectedShape],
            ['ordered' => $actualOrderedStages, 'shape' => $shape],
            $actualOrderedStages === $expectedOrderedStages && $shape === $expectedShape
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_one_shot_real_database_failure",
            ['injections' => 1, 'database_errors' => 1, 'failed_stage' => $failureStage, 'mysql_errno' => 1146, 'sqlstate' => '42S02'],
            [
                'injections' => count($injectedEvents),
                'database_errors' => count($databaseErrorEvents),
                'failed_stage' => wp_fts_wc_search_statement_kind((string) ($injectedEvent['sql'] ?? '')),
                'mysql_errno' => (int) ($injectedEvent['mysql_errno'] ?? 0),
                'sqlstate' => (string) ($injectedEvent['returned_sqlstate'] ?? ''),
                'message_text' => (string) ($injectedEvent['message_text'] ?? ''),
            ],
            count($injectedEvents) === 1
                && count($databaseErrorEvents) === 1
                && (int) ($injectedEvent['event_id'] ?? 0) === (int) ($databaseErrorEvents[0]['event_id'] ?? -1)
                && wp_fts_wc_search_statement_kind((string) ($injectedEvent['sql'] ?? '')) === $failureStage
                && str_contains((string) ($injectedEvent['sql'] ?? ''), "fts_wc_failed_{$failureStage}_")
                && (int) ($injectedEvent['mysql_errno'] ?? 0) === 1146
                && (string) ($injectedEvent['returned_sqlstate'] ?? '') === '42S02'
                && trim((string) ($injectedEvent['message_text'] ?? '')) !== ''
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_no_later_search_or_core_like",
            ['ordered_search' => $expectedOrderedStages, 'plugin_table_events' => count($expectedOrderedStages), 'non_search_plugin_table_events' => 0, 'core_like' => 0],
            ['ordered_search' => $actualOrderedStages, 'plugin_table_events' => count($pluginTableEvents), 'non_search_plugin_table_events' => count($nonSearchPluginTableEvents), 'core_like' => count($case['core_like_events'] ?? [])],
            $actualOrderedStages === $expectedOrderedStages
                && count($pluginTableEvents) === count($expectedOrderedStages)
                && $nonSearchPluginTableEvents === []
                && ($case['core_like_events'] ?? null) === []
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_failure_control_statement_set",
            '2..4 option/sitemeta statements, exactly one readiness revocation and one Health latch mutation, and no other plugin control SQL',
            [
                'plugin_control' => count($pluginControlEvents),
                'option_sitemeta' => count($pluginOptionEvents),
                'required_option_mutations' => $requiredOptionMutationCounts,
            ],
            count($pluginControlEvents) >= WP_FTS_WC_FAILED_SEARCH_MIN_CONTROL_STATEMENTS
                && count($pluginControlEvents) <= WP_FTS_WC_FAILED_SEARCH_MAX_CONTROL_STATEMENTS
                && count($pluginOptionEvents) === count($pluginControlEvents)
                && $requiredOptionMutationCounts === ['search_ready' => 1, 'health' => 1]
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_total_plugin_statement_ceiling",
            '<= ' . WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS[$failureStage],
            count($failureEvents),
            count($failureEvents) >= count($expectedOrderedStages) + WP_FTS_WC_FAILED_SEARCH_MIN_CONTROL_STATEMENTS
                && count($failureEvents) <= WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS[$failureStage]
                && count($failureEvents) === count($pluginSearchEvents) + count($pluginControlEvents)
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_post_fault_state_latched",
            ['search_ready_revoked' => true, 'health_unhealthy' => true, 'search_runtime_failure_latched' => true, 'schema_repair_scheduled' => true],
            $faultIsolation,
            ($faultIsolation['schema'] ?? null) === 'relational-fts-stage-failure-isolation-v1'
                && ($faultIsolation['failure_stage'] ?? null) === $failureStage
                && ($faultIsolation['post_fault_search_ready_revoked'] ?? null) === true
                && ($faultIsolation['post_fault_health_unhealthy'] ?? null) === true
                && ($faultIsolation['post_fault_health_latched'] ?? null) === true
                && is_bool($faultIsolation['pre_fault_repair_scheduled'] ?? null)
                && ($faultIsolation['post_fault_repair_scheduled'] ?? null) === true
                && array_keys($postFaultOptionHashes) === ['cron', 'health', 'search_ready']
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_isolated_state_restored",
            ['pre_fault_search_ready' => true, 'restored' => true, 'three exact option snapshots'],
            $faultIsolation,
            ($faultIsolation['pre_fault_search_ready'] ?? null) === true
                && ($faultIsolation['restored'] ?? null) === true
                && $beforeOptionHashes === $afterOptionHashes
                && array_keys($beforeOptionHashes) === ['cron', 'health', 'search_ready']
                && count(array_filter(
                    $beforeOptionHashes,
                    static fn(mixed $hash): bool => is_string($hash)
                        && strlen($hash) === 64
                        && strspn($hash, '0123456789abcdef') === 64
                )) === 3
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_connection_attribution",
            ['relational-fts-http-attribution-v1', $case['request_id'] ?? null, 1],
            [$attribution['schema'] ?? null, $attribution['request_id'] ?? null, $attribution['terminal_event_count'] ?? null],
            ($attribution['schema'] ?? null) === 'relational-fts-http-attribution-v1'
                && ($attribution['request_id'] ?? null) === ($case['request_id'] ?? null)
                && (int) ($attribution['thread_id'] ?? 0) > 0
                && ($attribution['terminal_event_count'] ?? null) === 1
        );
        $gates[] = wp_fts_wc_gate(
            "stage_failure_{$failureStage}_all_table_sql_attributed",
            0,
            count(is_array($attribution['unattributed_connection_events'] ?? null) ? $attribution['unattributed_connection_events'] : []),
            ($attribution['unattributed_connection_events'] ?? null) === []
        );
    }
    unset($case);
    $stagePreFaultStateSignatures = array_values(array_unique(array_map(
        'wp_fts_wc_canonical_hash',
        $stagePreFaultOptionHashes
    )));
    $gates[] = wp_fts_wc_gate(
        'stage_failure_all_stages_same_pre_fault_state',
        'one exact capability, Health, and cron snapshot across plan/rank/hydrate',
        $stagePreFaultOptionHashes,
        array_keys($stagePreFaultOptionHashes) === $orderedStages
            && count($stagePreFaultStateSignatures) === 1
    );

    $result = [
        'oracle' => [
            'source' => 'direct-set-oriented-searcher',
            'result_ids' => $expectedIds,
            'result_score_signature' => $expectedScores,
            'result_ids_sha256' => wp_fts_wc_canonical_hash($expectedIds),
            'result_scores_sha256' => wp_fts_wc_canonical_hash($expectedScores),
        ],
        'cases' => $requests,
        'missing_table' => $missingTable,
        'stage_failures' => $stageFailures,
        'gates' => $gates,
    ];
    wp_fts_wc_assert(@unlink($attributionPlugin), 'Could not remove the temporary HTTP attribution MU plugin.');

    return $result;
}

/** @return array<string,mixed> */
function wp_fts_wc_search_failure_attribution(array $case): array
{
    $attribution = is_array($case['attribution'] ?? null) ? $case['attribution'] : [];
    $pluginEvents = is_array($attribution['plugin_attributed_events'] ?? null)
        ? array_values($attribution['plugin_attributed_events'])
        : [];
    $searchEvents = array_values(array_filter(
        $pluginEvents,
        static fn(array $event): bool => wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))
    ));
    $failedEvents = array_values(array_filter(
        $pluginEvents,
        static fn(array $event): bool => (int) ($event['mysql_errno'] ?? 0) !== 0
    ));
    $failedEventId = $failedEvents === []
        ? PHP_INT_MAX
        : min(array_map(static fn(array $event): int => (int) ($event['event_id'] ?? PHP_INT_MAX), $failedEvents));
    $controlEvents = array_values(array_filter(
        $pluginEvents,
        static fn(array $event): bool => (int) ($event['event_id'] ?? -1) > $failedEventId
            && !wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))
    ));
    $attributedOptionEvents = is_array($attribution['plugin_option_sitemeta_events'] ?? null)
        ? array_values($attribution['plugin_option_sitemeta_events'])
        : [];
    $optionEvents = array_values(array_filter(
        $attributedOptionEvents,
        static fn(array $event): bool => (int) ($event['event_id'] ?? -1) > $failedEventId
            && !wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))
    ));
    $failureEvents = [...$searchEvents, ...$controlEvents];
    usort(
        $failureEvents,
        static fn(array $left, array $right): int => (int) ($left['event_id'] ?? 0) <=> (int) ($right['event_id'] ?? 0)
    );
    $requiredOptionMutations = ['search_ready' => 0, 'health' => 0];
    foreach ($controlEvents as $event) {
        $sql = (string) ($event['sql'] ?? '');
        $normalizedSql = strtoupper(ltrim($sql));
        $isMutation = str_starts_with($normalizedSql, 'UPDATE ')
            || str_starts_with($normalizedSql, 'INSERT ')
            || str_starts_with($normalizedSql, 'REPLACE ')
            || str_starts_with($normalizedSql, 'DELETE ');
        if (!$isMutation) {
            continue;
        }
        if (str_contains($sql, WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION)) {
            $requiredOptionMutations['search_ready']++;
        }
        if (str_contains($sql, WP_FTS_Plugin::INDEX_HEALTH_OPTION)) {
            $requiredOptionMutations['health']++;
        }
    }

    return [
        'attribution' => $attribution,
        'plugin_events' => $pluginEvents,
        'search_events' => $searchEvents,
        'control_events' => $controlEvents,
        'option_events' => $optionEvents,
        'failure_events' => $failureEvents,
        'plugin_table_events' => is_array($attribution['plugin_table_events'] ?? null)
            ? array_values($attribution['plugin_table_events'])
            : [],
        'non_search_plugin_table_events' => is_array($attribution['non_search_plugin_table_events'] ?? null)
            ? array_values($attribution['non_search_plugin_table_events'])
            : [],
        'required_option_mutations' => $requiredOptionMutations,
        'ordered_search_stages' => array_map(
            static fn(array $event): ?string => wp_fts_wc_search_statement_kind((string) ($event['sql'] ?? '')),
            $searchEvents
        ),
    ];
}

/**
 * Install a disposable request tagger outside the tested plugin tree. It tags
 * every wpdb statement and emits a shutdown marker, allowing Performance
 * Schema evidence to select one exact Apache connection and event interval.
 */
function wp_fts_wc_install_request_attribution_mu_plugin(): string
{
    $directory = rtrim((string) WPMU_PLUGIN_DIR, '/\\');
    if (!is_dir($directory) && !mkdir($directory, 0755, true) && !is_dir($directory)) {
        throw new RuntimeException('Could not create the disposable MU-plugin directory for HTTP attribution.');
    }
    $path = $directory . '/wp-fts-wc-request-attribution.php';
    wp_fts_wc_assert(!is_file($path), 'HTTP attribution MU plugin already exists; the disposable runtime is not fresh.');
    $source = <<<'PHP'
<?php
add_filter('query', static function (string $sql): string {
    global $wpdb;
    static $injectedFailure = false;

    $id = isset($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']))
        : '';
    if (strlen($id) !== 32 || strspn($id, '0123456789abcdef') !== 32) {
        return $sql;
    }
    $pluginQuery = false;
    foreach (debug_backtrace(DEBUG_BACKTRACE_IGNORE_ARGS, 32) as $frame) {
        $class = isset($frame['class']) && is_string($frame['class']) ? $frame['class'] : '';
        $file = isset($frame['file']) && is_string($frame['file']) ? str_replace('\\', '/', $frame['file']) : '';
        if (str_starts_with($class, 'WP_FTS_') || str_contains($file, '/wp-content/plugins/indexer/')) {
            $pluginQuery = true;
            break;
        }
    }
    $failureStage = isset($_SERVER['HTTP_X_WP_FTS_WC_FAILURE_STAGE']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_FAILURE_STAGE'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_FAILURE_STAGE']))
        : '';
    if (
        !$injectedFailure
        && $pluginQuery
        && in_array($failureStage, ['plan', 'rank', 'hydrate'], true)
        && str_contains($sql, 'wp_fts:' . $failureStage)
        && isset($wpdb)
        && is_object($wpdb)
    ) {
        $sourceTable = match ($failureStage) {
            'plan' => $wpdb->prefix . 'fts_terms',
            'rank' => $wpdb->prefix . 'fts_postings',
            'hydrate' => $wpdb->prefix . 'fts_documents',
        };
        $sourceOffset = strpos($sql, $sourceTable);
        if ($sourceOffset !== false) {
            $missingTable = $wpdb->prefix . 'fts_wc_failed_' . $failureStage . '_' . substr($id, 0, 8);
            $sql = '/* wp_fts_wc_injected_failure:' . $failureStage . ' */ '
                . substr_replace($sql, $missingTable, $sourceOffset, strlen($sourceTable));
            $injectedFailure = true;
        }
    }
    return rtrim($sql)
        . ($pluginQuery ? ' /* wp_fts_wc_plugin_query */' : '')
        . ' /* wp_fts_wc_request:' . $id . ' */';
}, PHP_INT_MAX);
add_filter('wp_fts_debug_enabled', static function (mixed $enabled): mixed {
    $id = isset($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']))
        : '';

    return strlen($id) === 32 && strspn($id, '0123456789abcdef') === 32 ? true : $enabled;
}, PHP_INT_MAX, 1);
add_action('wp_footer', static function (): void {
    $enabled = isset($_SERVER['HTTP_X_WP_FTS_WC_MAIN_QUERY_PROBE'])
        && $_SERVER['HTTP_X_WP_FTS_WC_MAIN_QUERY_PROBE'] === '1';
    if (!$enabled) {
        return;
    }
    global $wp_query;
    if (!is_object($wp_query)) {
        return;
    }
    $ids = [];
    foreach (is_array($wp_query->posts ?? null) ? $wp_query->posts : [] as $post) {
        $postId = is_object($post) ? (int) ($post->ID ?? 0) : (int) $post;
        if ($postId > 0) {
            $ids[] = $postId;
        }
    }
    $unavailable = method_exists($wp_query, 'get')
        ? (string) $wp_query->get('wp_fts_search_unavailable', '')
        : '';
    echo '<span hidden data-wp-fts-wc-main-query-probe="v1" data-result-ids="'
        . esc_attr(implode(',', $ids))
        . '" data-search-unavailable="'
        . esc_attr($unavailable)
        . '"></span>';
}, PHP_INT_MAX);
$GLOBALS['wp_fts_wc_request_end_callback'] = static function (): void {
    global $wpdb;
    $id = isset($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']))
        : '';
    if (strlen($id) === 32 && strspn($id, '0123456789abcdef') === 32 && isset($wpdb) && is_object($wpdb)) {
        $wpdb->query('SELECT /* wp_fts_wc_request_end:' . $id . ' */ 1');
    }
};
add_action('shutdown', $GLOBALS['wp_fts_wc_request_end_callback'], PHP_INT_MAX);
add_action('init', static function (): void {
    $callback = $GLOBALS['wp_fts_wc_request_end_callback'] ?? null;
    if (!is_callable($callback)) {
        return;
    }
    // The production plugin also owns PHP_INT_MAX shutdown work. Re-register
    // after ordinary plugins load so this marker closes the complete request.
    remove_action('shutdown', $callback, PHP_INT_MAX);
    add_action('shutdown', $callback, PHP_INT_MAX);
}, PHP_INT_MAX - 1);
add_action('init', static function (): void {
    $case = isset($_SERVER['HTTP_X_WP_FTS_WC_COLD_CASE']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_COLD_CASE'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_COLD_CASE']))
        : '';
    if (!in_array($case, ['ready', 'impossible', 'nonhydrate', 'hydrated'], true)) {
        return;
    }
    $requestId = isset($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']) && is_string($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID'])
        ? strtolower(trim($_SERVER['HTTP_X_WP_FTS_WC_REQUEST_ID']))
        : '';
    $payload = [
        'case' => $case,
        'request_id' => $requestId,
        'method' => isset($_SERVER['REQUEST_METHOD']) && is_string($_SERVER['REQUEST_METHOD']) ? $_SERVER['REQUEST_METHOD'] : '',
        'sapi' => PHP_SAPI,
        'php_pid' => getmypid(),
        'external_object_cache' => function_exists('wp_using_ext_object_cache')
            ? (bool) wp_using_ext_object_cache()
            : is_file(WP_CONTENT_DIR . '/object-cache.php'),
        'schema_version' => (int) get_option(WP_FTS_Plugin::SCHEMA_VERSION_OPTION, 0),
        'ready' => false,
        'result_count' => 0,
        'result_ids' => [],
        'all_results_have_snippets' => false,
    ];
    $status = 200;
    try {
        $readiness = WP_FTS_Plugin::search_takeover_status(false);
        $payload['ready'] = ($readiness['ready'] ?? null) === true;
        if (!in_array($case, ['ready'], true)) {
            $query = $case === 'impossible'
                ? 'wpftscoldmissingzzqvbxn commonalpha'
                : 'commonalpha';
            $page = WP_FTS_Plugin::search_page($query, [
                'mode' => $case === 'impossible' ? 'AND' : 'OR',
                'limit' => 20,
                'lang' => 'en',
                'prefix_matching' => false,
                'include_metadata' => $case === 'hydrated',
                'include_snippets' => $case === 'hydrated',
            ]);
            $rows = is_array($page['results'] ?? null) ? array_values($page['results']) : [];
            $payload['result_count'] = count($rows);
            $payload['result_ids'] = array_map('intval', array_column($rows, 'doc_id'));
            $payload['all_results_have_snippets'] = $rows !== [] && count(array_filter(
                $rows,
                static fn(array $row): bool => !is_string($row['snippet'] ?? null)
            )) === 0;
        }
    } catch (Throwable $error) {
        $status = 500;
        $payload['error'] = ['class' => get_class($error), 'message' => $error->getMessage()];
    }
    status_header($status);
    nocache_headers();
    header('Content-Type: application/json; charset=utf-8');
    echo wp_json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    exit;
}, PHP_INT_MAX);
PHP;
    $written = file_put_contents($path, $source . "\n", LOCK_EX);
    wp_fts_wc_assert($written === strlen($source) + 1 && hash_equals(hash('sha256', $source . "\n"), (string) hash_file('sha256', $path)), 'Could not install an exact HTTP attribution MU plugin.');

    return $path;
}

/**
 * @param array<string,string> $headers
 * @param array<string,mixed>|null $body
 * @return array{status:int,duration_ms:float,body:string,events:array<int,array<string,mixed>>,core_like_events:array<int,array<string,mixed>>}
 */
function wp_fts_wc_measure_http_adapter(string $url, array $headers, ?array $body = null): array
{
    $requestId = bin2hex(random_bytes(16));
    $headers['X-WP-FTS-WC-Request-ID'] = $requestId;
    $started = hrtime(true);
    $response = wp_remote_request($url, [
        'method' => $body === null ? 'GET' : 'POST',
        'headers' => $headers,
        'body' => $body ?? [],
        'timeout' => 30,
        'redirection' => 0,
    ]);
    $duration = wp_fts_wc_elapsed_ms($started);
    if (is_wp_error($response)) {
        throw new RuntimeException('Actual adapter HTTP request failed: ' . $response->get_error_message());
    }

    $attribution = wp_fts_wc_performance_schema_request_events($requestId, true);

    return [
        'status' => (int) wp_remote_retrieve_response_code($response),
        'duration_ms' => $duration,
        'body' => (string) wp_remote_retrieve_body($response),
        'request_id' => $requestId,
        'attribution' => $attribution,
        'events' => $attribution['search_events'],
        'core_like_events' => $attribution['core_like_events'],
    ];
}

/**
 * Remove the dictionary for one isolated adapter request. The shared failure
 * harness restores the table and exact option state before the next request.
 *
 * @param array<string,string> $headers
 * @param array<string,mixed>|null $body
 * @return array<string,mixed>
 */
function wp_fts_wc_measure_missing_table_http(string $url, array $headers, ?array $body = null): array
{
    return wp_fts_wc_measure_isolated_search_failure_http('missing_table', $url, $headers, $body);
}

/** @return array<string,mixed> */
function wp_fts_wc_measure_stage_failure_http(
    string $failureStage,
    string $url,
    array $headers,
    ?array $body = null
): array {
    wp_fts_wc_assert(
        array_key_exists($failureStage, WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS),
        'HTTP search-failure injection requires plan, rank, or hydrate.'
    );

    return wp_fts_wc_measure_isolated_search_failure_http($failureStage, $url, $headers, $body);
}

/**
 * Run one real HTTP failure, capture its production latch, then restore the
 * exact capability, Health, and cron rows solely to isolate the next proof.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_measure_isolated_search_failure_http(
    string $fault,
    string $url,
    array $headers,
    ?array $body = null
): array
{
    global $wpdb;

    $missingTableFault = $fault === 'missing_table';
    wp_fts_wc_assert(
        $missingTableFault || array_key_exists($fault, WP_FTS_WC_FAILED_SEARCH_STAGE_CEILINGS),
        'Unknown isolated HTTP search fault.'
    );
    $table = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms');
    $missing = wp_fts_wc_identifier($wpdb->prefix . 'fts_terms_wc_missing');
    $optionNames = [
        'cron' => 'cron',
        'health' => WP_FTS_Plugin::INDEX_HEALTH_OPTION,
        'search_ready' => WP_FTS_Plugin::SEARCH_READY_INCARNATION_OPTION,
    ];
    $optionSnapshots = [];
    foreach ($optionNames as $key => $optionName) {
        $optionSnapshots[$key] = wp_fts_wc_raw_option_snapshot($optionName);
    }
    $searchReady = $optionSnapshots['search_ready']['exists']
        ? maybe_unserialize($optionSnapshots['search_ready']['option_value'])
        : null;
    $readyProfileHash = is_array($searchReady) && is_string($searchReady['profile_hash'] ?? null)
        ? $searchReady['profile_hash']
        : '';
    $preFaultSearchReady = is_array($searchReady)
        && preg_match('/^[a-f0-9]{32}$/D', (string) ($searchReady['incarnation'] ?? '')) === 1
        && strlen($readyProfileHash) === 40
        && $readyProfileHash === strtolower($readyProfileHash)
        && wp_fts_wc_is_ascii_hex($readyProfileHash);
    wp_fts_wc_assert($preFaultSearchReady, 'Isolated HTTP failure proof did not begin with a published search-ready capability.');

    if ($missingTableFault) {
        $wpdb->query("DROP TABLE IF EXISTS `{$missing}`");
        if ($wpdb->query("RENAME TABLE `{$table}` TO `{$missing}`") === false) {
            throw new RuntimeException('Could not install the actual-adapter missing-table fault.');
        }
    } else {
        $headers['X-WP-FTS-WC-Failure-Stage'] = $fault;
    }
    $response = null;
    $postFaultOptionSnapshots = [];
    $restoredOptionSnapshots = [];
    try {
        $response = wp_fts_wc_measure_http_adapter($url, $headers, $body);
        // Capture the production-visible failure latch before the harness puts
        // the table and options back. Hashes leave the evidence without raw
        // option values while the booleans prove the required semantics.
        foreach ($optionNames as $key => $optionName) {
            $postFaultOptionSnapshots[$key] = wp_fts_wc_raw_option_snapshot($optionName);
        }
    } finally {
        if ($missingTableFault && $wpdb->query("RENAME TABLE `{$missing}` TO `{$table}`") === false) {
            throw new RuntimeException('Could not restore the actual-adapter missing table.');
        }
        foreach ($optionNames as $key => $optionName) {
            wp_fts_wc_restore_raw_option_snapshot($optionName, $optionSnapshots[$key]);
        }
        // Re-read the complete set only after every restoration write. This
        // catches a later write or hook disturbing an option restored earlier.
        foreach ($optionNames as $key => $optionName) {
            $restoredOptionSnapshots[$key] = wp_fts_wc_raw_option_snapshot($optionName);
        }
    }

    wp_fts_wc_assert(is_array($response), 'Isolated HTTP failure request did not return measurable evidence.');
    $restored = $restoredOptionSnapshots === $optionSnapshots;
    wp_fts_wc_assert($restored, 'Isolated HTTP failure proof did not restore all exact pre-fault option states.');
    $postFaultSearchReady = maybe_unserialize($postFaultOptionSnapshots['search_ready']['option_value']);
    $postFaultHealth = maybe_unserialize($postFaultOptionSnapshots['health']['option_value']);
    $response['fault_isolation'] = [
        'schema' => $missingTableFault
            ? 'relational-fts-missing-table-isolation-v1'
            : 'relational-fts-stage-failure-isolation-v1',
        'failure_stage' => $missingTableFault ? 'plan' : $fault,
        'fault_source' => $missingTableFault ? 'renamed_dictionary' : 'one_shot_missing_relation',
        'pre_fault_search_ready' => $preFaultSearchReady,
        'post_fault_search_ready_revoked' => $postFaultOptionSnapshots['search_ready']['exists']
            && $postFaultSearchReady === '',
        'post_fault_health_unhealthy' => $postFaultOptionSnapshots['health']['exists']
            && is_array($postFaultHealth)
            && ($postFaultHealth['status'] ?? null) === 'unhealthy',
        'post_fault_health_latched' => $postFaultOptionSnapshots['health']['exists']
            && is_array($postFaultHealth)
            && ($postFaultHealth['search_runtime_failure_latched'] ?? null) === true,
        'pre_fault_repair_scheduled' => wp_fts_wc_raw_cron_snapshot_has_schema_repair($optionSnapshots['cron']),
        'post_fault_repair_scheduled' => wp_fts_wc_raw_cron_snapshot_has_schema_repair($postFaultOptionSnapshots['cron']),
        'restored' => $restored,
        'before_option_sha256' => array_map('wp_fts_wc_raw_option_snapshot_hash', $optionSnapshots),
        'post_fault_option_sha256' => array_map('wp_fts_wc_raw_option_snapshot_hash', $postFaultOptionSnapshots),
        'after_option_sha256' => array_map('wp_fts_wc_raw_option_snapshot_hash', $restoredOptionSnapshots),
    ];

    return $response;
}

/** @return array{exists:bool,option_value:string,autoload:string} */
function wp_fts_wc_raw_option_snapshot(string $optionName): array
{
    global $wpdb;

    $options = wp_fts_wc_identifier((string) $wpdb->options);
    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT option_value,autoload FROM `{$options}` WHERE option_name=%s",
        $optionName
    ), ARRAY_A);
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', "Could not snapshot the {$optionName} option for missing-table isolation.");
    if (!is_array($row)) {
        return ['exists' => false, 'option_value' => '', 'autoload' => ''];
    }

    return [
        'exists' => true,
        'option_value' => (string) ($row['option_value'] ?? ''),
        'autoload' => (string) ($row['autoload'] ?? ''),
    ];
}

/** @param array{exists:bool,option_value:string,autoload:string} $snapshot */
function wp_fts_wc_restore_raw_option_snapshot(string $optionName, array $snapshot): void
{
    global $wpdb;

    $options = wp_fts_wc_identifier((string) $wpdb->options);
    if ($snapshot['exists']) {
        $result = $wpdb->query($wpdb->prepare(
            "INSERT INTO `{$options}` (option_name,option_value,autoload) VALUES (%s,%s,%s) ON DUPLICATE KEY UPDATE option_value=VALUES(option_value),autoload=VALUES(autoload)",
            $optionName,
            $snapshot['option_value'],
            $snapshot['autoload']
        ));
    } else {
        $result = $wpdb->query($wpdb->prepare(
            "DELETE FROM `{$options}` WHERE option_name=%s",
            $optionName
        ));
    }
    wp_fts_wc_assert($result !== false && trim((string) $wpdb->last_error) === '', "Could not restore the {$optionName} option after missing-table isolation.");
    wp_cache_delete($optionName, 'options');
    wp_cache_delete('alloptions', 'options');
    wp_cache_delete('notoptions', 'options');
    wp_fts_wc_assert(
        wp_fts_wc_raw_option_snapshot($optionName) === $snapshot,
        "The {$optionName} option did not return to its exact pre-fault state."
    );
}

/** @param array{exists:bool,option_value:string,autoload:string} $snapshot */
function wp_fts_wc_raw_option_snapshot_hash(array $snapshot): string
{
    $autoload = $snapshot['autoload'];
    $value = $snapshot['option_value'];

    return hash(
        'sha256',
        ($snapshot['exists'] ? '1' : '0')
            . ':' . strlen($autoload) . ':' . $autoload
            . ':' . strlen($value) . ':' . $value
    );
}

/** @param array{exists:bool,option_value:string,autoload:string} $snapshot */
function wp_fts_wc_raw_cron_snapshot_has_schema_repair(array $snapshot): bool
{
    if (!$snapshot['exists']) {
        return false;
    }
    $cron = maybe_unserialize($snapshot['option_value']);
    if (!is_array($cron)) {
        return false;
    }
    foreach ($cron as $timestamp => $hooks) {
        if ($timestamp === 'version' || !is_numeric($timestamp) || (int) $timestamp <= 0 || !is_array($hooks)) {
            continue;
        }
        $events = $hooks[WP_FTS_Plugin::SCHEMA_REPAIR_CRON_HOOK] ?? null;
        if (!is_array($events)) {
            continue;
        }
        foreach ($events as $event) {
            if (
                is_array($event)
                && ($event['schedule'] ?? null) === false
                && ($event['args'] ?? null) === []
            ) {
                return true;
            }
        }
    }

    return false;
}

/** @return array<string,string> */
function wp_fts_wc_admin_auth_headers(): array
{
    $previousUser = get_current_user_id();
    $admin = get_user_by('login', 'admin');
    if (!is_object($admin) || (int) ($admin->ID ?? 0) <= 0) {
        throw new RuntimeException('Actual adapter proof could not resolve the disposable admin user.');
    }
    $adminId = (int) $admin->ID;
    wp_set_current_user($adminId);
    $expiration = time() + 3600;
    $auth = wp_generate_auth_cookie($adminId, $expiration, 'auth');
    $loggedIn = wp_generate_auth_cookie($adminId, $expiration, 'logged_in');
    wp_set_current_user($previousUser);

    return [
        'Cookie' => AUTH_COOKIE . '=' . $auth . '; ' . LOGGED_IN_COOKIE . '=' . $loggedIn,
        'User-Agent' => 'wp-fts-relational-worst-case-proof',
    ];
}

/** @return int[] */
function wp_fts_wc_html_post_ids(string $html): array
{
    $processor = new WP_HTML_Tag_Processor($html);
    $ids = [];
    while ($processor->next_tag()) {
        $candidates = [];
        foreach (['id', 'class'] as $attribute) {
            $value = $processor->get_attribute($attribute);
            if (!is_string($value)) {
                continue;
            }
            array_push($candidates, ...preg_split('/\s+/', trim($value)) ?: []);
        }
        foreach ($candidates as $candidate) {
            if (!str_starts_with($candidate, 'post-')) {
                continue;
            }
            $postId = substr($candidate, 5);
            if ($postId !== '' && wp_fts_wc_is_ascii_digits($postId)) {
                $ids[(int) $postId] = true;
            }
        }
    }

    return array_slice(array_keys($ids), 0, 20);
}

/** @return array{schema:string,result_ids:int[],search_unavailable:string} */
function wp_fts_wc_main_query_probe(string $html): array
{
    $processor = new WP_HTML_Tag_Processor($html);
    $probes = [];
    while ($processor->next_tag()) {
        if ($processor->get_attribute('data-wp-fts-wc-main-query-probe') !== 'v1') {
            continue;
        }
        $ids = [];
        $encodedIds = $processor->get_attribute('data-result-ids');
        foreach (is_string($encodedIds) && $encodedIds !== '' ? explode(',', $encodedIds) : [] as $encodedId) {
            if (!wp_fts_wc_is_ascii_digits($encodedId) || (int) $encodedId <= 0) {
                throw new RuntimeException('Actual front-end main-query probe contained a malformed post ID.');
            }
            $ids[] = (int) $encodedId;
        }
        $unavailable = $processor->get_attribute('data-search-unavailable');
        $probes[] = [
            'schema' => 'relational-fts-main-query-probe-v1',
            'result_ids' => $ids,
            'search_unavailable' => is_string($unavailable) ? $unavailable : '',
        ];
    }
    if (count($probes) !== 1) {
        throw new RuntimeException('Actual front-end response did not contain exactly one main-query probe.');
    }

    return $probes[0];
}

/** @return array{nonce:string,post_ids:int[]} */
function wp_fts_wc_sandbox_transport(string $html): array
{
    $processor = new WP_HTML_Tag_Processor($html);
    $nonce = '';
    $ids = [];
    while ($processor->next_tag()) {
        $candidateNonce = $processor->get_attribute('data-nonce');
        if ($nonce === '' && is_string($candidateNonce)) {
            $nonce = $candidateNonce;
        }
        $candidateId = $processor->get_attribute('data-post-id');
        if (is_string($candidateId) && wp_fts_wc_is_ascii_digits($candidateId) && (int) $candidateId > 0) {
            $ids[(int) $candidateId] = true;
        }
    }
    if ($nonce === '' || $ids === []) {
        throw new RuntimeException('Actual Sandbox response omitted its nonce or result rows.');
    }

    return ['nonce' => $nonce, 'post_ids' => array_slice(array_keys($ids), 0, 20)];
}

/**
 * Resolve one request tag to one connection, then retain every statement from
 * its first tagged event (or the connection's first retained event) through
 * the tagged shutdown marker. Search counts are derived from that closed
 * interval, never from global/tag-only traffic.
 *
 * @return array<string,mixed>
 */
function wp_fts_wc_performance_schema_request_events(string $requestId, bool $fromConnectionStart = false): array
{
    global $wpdb;

    wp_fts_wc_assert(strlen($requestId) === 32 && wp_fts_wc_is_ascii_hex($requestId), 'HTTP attribution request identity is malformed.');
    $tagPattern = '%wp\_fts\_wc\_request:' . $wpdb->esc_like($requestId) . '%';
    $tagged = $wpdb->get_results($wpdb->prepare(
        "SELECT THREAD_ID,EVENT_ID,SQL_TEXT FROM performance_schema.events_statements_history_long WHERE SQL_TEXT LIKE %s ORDER BY THREAD_ID,EVENT_ID",
        $tagPattern
    ), ARRAY_A) ?: [];
    $threadIds = array_values(array_unique(array_map(static fn(array $row): int => (int) ($row['THREAD_ID'] ?? 0), $tagged)));
    $threadIds = array_values(array_filter($threadIds, static fn(int $threadId): bool => $threadId > 0));
    wp_fts_wc_assert(count($threadIds) === 1, 'HTTP request correlation did not resolve to exactly one database thread.');
    $threadId = $threadIds[0];
    $taggedStartEvent = min(array_map(static fn(array $row): int => (int) ($row['EVENT_ID'] ?? PHP_INT_MAX), $tagged));
    $endEvents = array_values(array_filter($tagged, static fn(array $row): bool => str_contains((string) ($row['SQL_TEXT'] ?? ''), "wp_fts_wc_request_end:{$requestId}")));
    wp_fts_wc_assert(count($endEvents) === 1, 'HTTP request correlation has no unique shutdown event.');
    $endEvent = (int) ($endEvents[0]['EVENT_ID'] ?? 0);
    $firstConnectionEvent = (int) $wpdb->get_var($wpdb->prepare(
        'SELECT MIN(EVENT_ID) FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID<=%d',
        $threadId,
        $endEvent
    ));
    wp_fts_wc_assert(trim((string) $wpdb->last_error) === '', 'Could not resolve the first retained HTTP connection event.');
    $startEvent = $fromConnectionStart ? $firstConnectionEvent : $taggedStartEvent;
    wp_fts_wc_assert($firstConnectionEvent > 0 && $taggedStartEvent >= $firstConnectionEvent && $startEvent > 0 && $endEvent >= $startEvent, 'HTTP request correlation interval is invalid.');
    if ($fromConnectionStart) {
        wp_fts_wc_assert($firstConnectionEvent === 1, 'HTTP connection-start attribution lost its first Performance Schema event.');
    }

    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT THREAD_ID,EVENT_ID,SQL_TEXT,MYSQL_ERRNO,RETURNED_SQLSTATE,MESSAGE_TEXT,ROWS_EXAMINED,ROWS_SENT,CREATED_TMP_DISK_TABLES,SORT_MERGE_PASSES,NO_INDEX_USED,NO_GOOD_INDEX_USED,LOCK_TIME,TIMER_WAIT FROM performance_schema.events_statements_history_long WHERE THREAD_ID=%d AND EVENT_ID BETWEEN %d AND %d ORDER BY EVENT_ID ASC",
        $threadId,
        $startEvent,
        $endEvent
    ), ARRAY_A) ?: [];
    wp_fts_wc_assert(
        count($rows) <= intdiv(WP_FTS_WC_PERFORMANCE_SCHEMA_HISTORY_LONG_EVENTS, 2),
        'HTTP request attribution consumed more than half of the fixed Performance Schema history ring.'
    );
    $events = array_map(static fn(array $row): array => [
        'thread_id' => (int) ($row['THREAD_ID'] ?? 0),
        'event_id' => (int) ($row['EVENT_ID'] ?? 0),
        'sql' => (string) ($row['SQL_TEXT'] ?? ''),
        'sql_sha256' => hash('sha256', (string) ($row['SQL_TEXT'] ?? '')),
        'sql_bytes' => strlen((string) ($row['SQL_TEXT'] ?? '')),
        'mysql_errno' => (int) ($row['MYSQL_ERRNO'] ?? 0),
        'returned_sqlstate' => (string) ($row['RETURNED_SQLSTATE'] ?? ''),
        'message_text' => (string) ($row['MESSAGE_TEXT'] ?? ''),
        'rows_examined' => (int) ($row['ROWS_EXAMINED'] ?? 0),
        'rows_sent' => (int) ($row['ROWS_SENT'] ?? 0),
        'tmp_disk_tables' => (int) ($row['CREATED_TMP_DISK_TABLES'] ?? 0),
        'sort_merge_passes' => (int) ($row['SORT_MERGE_PASSES'] ?? 0),
        'no_index_used' => (int) ($row['NO_INDEX_USED'] ?? 0),
        'no_good_index_used' => (int) ($row['NO_GOOD_INDEX_USED'] ?? 0),
        'lock_time' => (int) ($row['LOCK_TIME'] ?? 0),
        'timer_wait' => (int) ($row['TIMER_WAIT'] ?? 0),
    ], $rows);
    $requestTag = "wp_fts_wc_request:{$requestId}";
    $unattributedConnectionEvents = array_values(array_filter(
        $events,
        static fn(array $event): bool => (int) ($event['event_id'] ?? 0) >= $taggedStartEvent
            && !str_contains((string) ($event['sql'] ?? ''), $requestTag)
    ));
    $untaggedConnectionPrefixEvents = array_values(array_filter(
        $events,
        static fn(array $event): bool => (int) ($event['event_id'] ?? PHP_INT_MAX) < $taggedStartEvent
    ));
    $tableTouching = array_values(array_filter($events, static function (array $event) use ($wpdb): bool {
        $sql = (string) ($event['sql'] ?? '');
        return wp_fts_wc_sql_references_owned_fts_table($sql, (string) $wpdb->prefix)
            || wp_fts_wc_sql_references_physical_table($sql, (string) $wpdb->posts);
    }));
    $unattributedTableTouching = array_values(array_filter(
        $tableTouching,
        static fn(array $event): bool => !str_contains((string) ($event['sql'] ?? ''), $requestTag)
    ));
    $searchEvents = array_values(array_filter($tableTouching, static fn(array $event): bool => wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))));
    $pluginTableEvents = array_values(array_filter($tableTouching, static function (array $event) use ($wpdb): bool {
        return wp_fts_wc_sql_references_owned_fts_table((string) ($event['sql'] ?? ''), (string) $wpdb->prefix);
    }));
    $pluginAttributedEvents = array_values(array_filter($events, static fn(array $event): bool => str_contains(
        (string) ($event['sql'] ?? ''),
        'wp_fts_wc_plugin_query'
    )));
    $pluginOptionSitemetaEvents = array_values(array_filter($pluginAttributedEvents, static function (array $event) use ($wpdb): bool {
        $sql = (string) ($event['sql'] ?? '');
        return wp_fts_wc_sql_references_physical_table($sql, (string) $wpdb->options)
            || wp_fts_wc_sql_references_physical_table($sql, (string) $wpdb->sitemeta);
    }));
    $nonSearchPluginTableEvents = array_values(array_filter($pluginTableEvents, static fn(array $event): bool => !wp_fts_wc_is_search_statement((string) ($event['sql'] ?? ''))));
    $coreLikeEvents = array_values(array_filter($tableTouching, static function (array $event) use ($wpdb): bool {
        $sql = (string) ($event['sql'] ?? '');
        return wp_fts_wc_sql_references_physical_table($sql, (string) $wpdb->posts)
            && wp_fts_wc_sql_contains_executable_word($sql, 'like')
            && !wp_fts_wc_sql_references_owned_fts_table($sql, (string) $wpdb->prefix);
    }));

    return [
        'schema' => 'relational-fts-http-attribution-v1',
        'request_id' => $requestId,
        'thread_id' => $threadId,
        'start_event_id' => $startEvent,
        'first_connection_event_id' => $firstConnectionEvent,
        'tagged_start_event_id' => $taggedStartEvent,
        'end_event_id' => $endEvent,
        'terminal_event_count' => count($endEvents),
        'history_long_capacity' => WP_FTS_WC_PERFORMANCE_SCHEMA_HISTORY_LONG_EVENTS,
        'history_long_event_count' => count($rows),
        'history_long_headroom' => WP_FTS_WC_PERFORMANCE_SCHEMA_HISTORY_LONG_EVENTS - count($rows),
        'all_connection_events' => $events,
        'untagged_connection_prefix_events' => $untaggedConnectionPrefixEvents,
        'unattributed_connection_events' => $unattributedConnectionEvents,
        'table_touching_events' => $tableTouching,
        'unattributed_table_touching_events' => $unattributedTableTouching,
        'search_events' => $searchEvents,
        'plugin_table_events' => $pluginTableEvents,
        'plugin_attributed_events' => $pluginAttributedEvents,
        'plugin_option_sitemeta_events' => $pluginOptionSitemetaEvents,
        'non_search_plugin_table_events' => $nonSearchPluginTableEvents,
        'core_like_events' => $coreLikeEvents,
        'ordered_sql_sha256' => array_column($events, 'sql_sha256'),
    ];
}

/** Match one decoded identifier token; comments and quoted values are absent. */
function wp_fts_wc_sql_references_physical_table(string $sql, string $table): bool
{
    $table = strtolower(trim($table, "` \t\n\r\0\x0B"));
    if ($table === '') {
        return false;
    }
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if (in_array($token['type'] ?? null, ['word', 'identifier'], true) && ($token['value'] ?? null) === $table) {
            return true;
        }
    }

    return false;
}

/** Recognize only current-site production tables and bounded fault descendants. */
function wp_fts_wc_sql_references_owned_fts_table(string $sql, string $tablePrefix): bool
{
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if (
            in_array($token['type'] ?? null, ['word', 'identifier'], true)
            && wp_fts_wc_is_owned_fts_table_identifier((string) ($token['value'] ?? ''), $tablePrefix)
        ) {
            return true;
        }
    }

    return false;
}

/** Parse the deliberately narrow physical table-name grammar without regexp. */
function wp_fts_wc_is_owned_fts_table_identifier(string $identifier, string $tablePrefix): bool
{
    $identifier = strtolower(trim($identifier, "` \t\n\r\0\x0B"));
    $tablePrefix = strtolower($tablePrefix);
    if (in_array($identifier, [
        $tablePrefix . 'fts_terms',
        $tablePrefix . 'fts_postings',
        $tablePrefix . 'fts_documents',
        $tablePrefix . 'fts_work',
        $tablePrefix . 'fts_terms_wc_missing',
    ], true)) {
        return true;
    }

    $failurePrefix = $tablePrefix . 'fts_wc_failed_';
    if (!str_starts_with($identifier, $failurePrefix)) {
        return false;
    }
    $suffix = substr($identifier, strlen($failurePrefix));
    foreach (['plan', 'rank', 'hydrate'] as $stage) {
        $stagePrefix = $stage . '_';
        if (!str_starts_with($suffix, $stagePrefix)) {
            continue;
        }
        $nonce = substr($suffix, strlen($stagePrefix));
        return strlen($nonce) === 8 && strspn($nonce, '0123456789abcdef') === 8;
    }

    return false;
}

/** Match a real executable keyword rather than text inside a value/comment. */
function wp_fts_wc_sql_contains_executable_word(string $sql, string $word): bool
{
    $word = strtolower($word);
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if (($token['type'] ?? null) === 'word' && ($token['value'] ?? null) === $word) {
            return true;
        }
    }

    return false;
}

/**
 * @param array<int,array<string,mixed>> $events
 * @return array{plan:int,rank:int,hydrate:int}
 */
function wp_fts_wc_statement_shape(array $events): array
{
    $shape = ['plan' => 0, 'rank' => 0, 'hydrate' => 0];
    foreach ($events as $event) {
        $sql = is_scalar($event['sql'] ?? null) ? (string) $event['sql'] : '';
        foreach (array_keys($shape) as $kind) {
            if (str_contains($sql, "wp_fts:{$kind}")) {
                $shape[$kind]++;
            }
        }
    }

    return $shape;
}

/**
 * @return array{error_class:string,error_message:string,query_count:int,gates:array<int,array<string,mixed>>}
 */
function wp_fts_wc_explosive_input_proof(): array
{
    $words = [];
    for ($index = 0; $index < 1024; $index++) {
        $words[] = 'adversarialprobe' . wp_fts_wc_alpha_id($index);
    }
    $errorClass = '';
    $errorMessage = '';
    $recorded = wp_fts_wc_record_queries(static function () use ($words, &$errorClass, &$errorMessage): array {
        try {
            return WP_FTS_Plugin::search(implode(' ', $words), ['lang' => 'en', 'mode' => 'OR', 'prefix_matching' => true, 'limit' => 20]);
        } catch (Throwable $error) {
            $errorClass = get_class($error);
            $errorMessage = $error->getMessage();
            return [];
        }
    });
    $queries = array_values($recorded['queries']);
    $ftsQueries = array_values(array_filter($queries, 'wp_fts_wc_is_search_statement'));
    $typed = $errorClass !== '' && (str_contains($errorClass, 'Budget') || str_contains(strtolower($errorMessage), 'complex'));

    return [
        'error_class' => $errorClass,
        'error_message' => $errorMessage,
        'query_count' => count($queries),
        'gates' => [
            wp_fts_wc_gate('explosive_input_typed_rejection', true, $typed, $typed),
            wp_fts_wc_gate('explosive_input_total_queries', 0, count($queries), $queries === []),
            wp_fts_wc_gate('explosive_input_fts_queries', 0, count($ftsQueries), $ftsQueries === []),
        ],
    ];
}

/**
 * @return array<string,mixed>
 */
function wp_fts_wc_payload(mixed $value): array
{
    if (!is_array($value) || !array_key_exists('results', $value) || !is_array($value['results'])) {
        throw new RuntimeException('Set-oriented search did not return its canonical page payload.');
    }

    return $value;
}

/**
 * @param array<string,mixed> $payload
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_payload_results(array $payload): array
{
    $rows = [];
    foreach ($payload['results'] ?? [] as $row) {
        if (!is_array($row) || !is_numeric($row['doc_id'] ?? null)) {
            throw new RuntimeException('Search payload contains a malformed result row.');
        }
        $rows[] = $row;
    }

    return $rows;
}

/**
 * @return array{result:mixed,queries:string[],query_started_ms:float[]}
 */
function wp_fts_wc_record_queries(callable $callback): array
{
    $queries = [];
    $queryStartedMs = [];
    $started = hrtime(true);
    $filter = static function (string $sql) use (&$queries, &$queryStartedMs, $started): string {
        $queries[] = $sql;
        $queryStartedMs[] = wp_fts_wc_elapsed_ms($started);
        return $sql;
    };
    add_filter('query', $filter, PHP_INT_MIN, 1);
    try {
        $result = $callback();
    } finally {
        remove_filter('query', $filter, PHP_INT_MIN);
    }

    return ['result' => $result, 'queries' => $queries, 'query_started_ms' => $queryStartedMs];
}

/** Identify every statement touching the current relational search tables. */
function wp_fts_wc_is_search_statement(string $sql): bool
{
    global $wpdb;

    if (isset($wpdb) && is_object($wpdb) && wp_fts_wc_sql_references_owned_fts_table($sql, (string) ($wpdb->prefix ?? ''))) {
        return true;
    }
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if (
            in_array($token['type'] ?? null, ['word', 'identifier'], true)
            && wp_fts_wc_fts_table_kind((string) ($token['value'] ?? '')) !== null
        ) {
            return true;
        }
    }

    return false;
}

/**
 * Classify the deliberately small production-worker SQL protocol by its
 * semantic role. An added query is not allowed to disappear into a relaxed
 * count: an unrecognized statement fails both the focused one-row proof and
 * the instrumented 100-row drain.
 *
 * @param string[] $statements
 * @return array{
 *   roles:string[],
 *   data_roles:string[],
 *   lease_control_roles:string[],
 *   transaction_roles:string[],
 *   scheduling_control_roles:string[],
 *   unknown:array<int,array{index:int,bytes:int,sha256:string}>
 * }
 */
function wp_fts_wc_worker_statement_roles(array $statements): array
{
    $dataRoles = [];
    $leaseControlRoles = [];
    $transactionRoles = [];
    $schedulingControlRoles = [];
    $roles = [];
    $unknown = [];
    foreach (array_values($statements) as $index => $sql) {
        $role = wp_fts_wc_worker_statement_role((string) $sql);
        $roles[] = $role;
        if ($role === 'unknown') {
            $unknown[] = [
                'index' => $index,
                'bytes' => strlen((string) $sql),
                'sha256' => hash('sha256', (string) $sql),
            ];
        } elseif (str_starts_with($role, 'lease_')) {
            $leaseControlRoles[] = $role;
        } elseif (str_starts_with($role, 'transaction_')) {
            $transactionRoles[] = $role;
        } elseif (
            str_starts_with($role, 'cron_schedule_')
            || $role === 'option_cache_reload'
        ) {
            // WordPress's cron option writes and the cache reload coupled to
            // that outer control plane are counted in the complete callback
            // total, but they are not source/queue/index data statements.
            // Keeping the category explicit prevents either number from
            // making the other look cheaper.
            $schedulingControlRoles[] = $role;
        } else {
            $dataRoles[] = $role;
        }
    }

    return [
        'roles' => $roles,
        'data_roles' => $dataRoles,
        'lease_control_roles' => $leaseControlRoles,
        'transaction_roles' => $transactionRoles,
        'scheduling_control_roles' => $schedulingControlRoles,
        'unknown' => $unknown,
    ];
}

/** Assign one exact semantic role to a production-worker statement. */
function wp_fts_wc_worker_statement_role(string $sql): string
{
    global $wpdb;

    $trimmed = trim($sql);
    $normalized = strtoupper(rtrim($trimmed, "; \t\n\r\0\x0B"));
    if (in_array($normalized, ['START TRANSACTION', 'BEGIN'], true)) {
        return 'transaction_start';
    }
    if ($normalized === 'COMMIT') {
        return 'transaction_commit';
    }
    if ($normalized === 'ROLLBACK') {
        return 'transaction_rollback';
    }

    $tagRoles = [
        'wp_fts:claim-batch' => 'claim_batch',
        'wp_fts:yield-scope-release-posts' => 'scope_yield_and_post_batch_release',
        'wp_fts:scope-yield-to-posts' => 'scope_yield_to_posts',
        'wp_fts:release-batch' => 'post_batch_release',
        'wp_fts:fail-batch' => 'post_batch_failure',
        'wp_fts:corpus-scope-page' => 'corpus_scope_page',
        'wp_fts:filtered-scope-page' => 'filtered_scope_page',
        'wp_fts:targeted-scope-page' => 'targeted_scope_page',
        'wp_fts:dependency_measurement' => 'dependency_measurement',
        'wp_fts:dependency_values' => 'dependency_values',
        'wp_fts:replacement-frontier' => 'replacement_frontier',
        'wp_fts:dictionary-increment' => 'dictionary_increment',
        'wp_fts:dictionary-decrement' => 'dictionary_decrement',
        'wp_fts:bounded-index-delete' => 'bounded_index_delete',
        'wp_fts:resolve-prepared-terms' => 'resolve_prepared_terms',
        'wp_fts:posting-replacement' => 'posting_replacement',
        'wp_fts:search-epoch-advance' => 'search_epoch_advance',
        'wp_fts:atomic-worker-ack' => 'atomic_worker_ack',
        'wp_fts:cleanup-empty-terms' => 'empty_term_cleanup',
    ];
    foreach ($tagRoles as $tag => $role) {
        if (str_contains($sql, $tag)) {
            return $role;
        }
    }
    $scopeIndexProbeRole = wp_fts_wc_scope_index_probe_role($sql);
    if ($scopeIndexProbeRole !== null) {
        return $scopeIndexProbeRole;
    }

    $lower = strtolower($trimmed);
    if (str_contains($lower, 'wp_fts_indexing_lock')) {
        if (str_starts_with($normalized, 'INSERT IGNORE INTO ')) {
            return 'lease_acquire';
        }
        if (str_starts_with($normalized, 'UPDATE ')) {
            return 'lease_heartbeat';
        }
        if (str_starts_with($normalized, 'DELETE FROM ')) {
            return 'lease_release';
        }
    }
    if (
        str_starts_with($normalized, 'SELECT ')
        && str_contains($lower, 'source_existing_hash')
        && str_contains($lower, 'source_snapshot_complete')
    ) {
        return 'claim_source_snapshot';
    }
    if (
        str_starts_with($normalized, 'SELECT ')
        && str_contains($lower, 'fts_source_changed')
        && str_contains($lower, 'fts_canonical_changed')
        && str_contains($lower, 'source_budget')
        && str_contains($lower, 'canonical_budget')
    ) {
        return 'conditional_source_fallback';
    }
    if (
        str_starts_with($normalized, 'UPDATE ')
        && str_contains($lower, 'fts_work')
        && str_contains($lower, 'set cursor_post_id =')
        && str_contains($lower, "last_error_code = ''")
    ) {
        return 'scope_page_advance';
    }
    if (
        str_starts_with($normalized, 'INSERT INTO ')
        && str_contains($lower, 'fts_work')
        && str_contains($lower, "'meta:search-epoch'")
        && str_contains($lower, 'generation = generation + 1')
    ) {
        return 'search_epoch_advance';
    }
    if (
        str_starts_with($normalized, 'INSERT INTO ')
        && str_contains($lower, 'fts_work')
        && str_contains($lower, "'post'")
        && str_contains($lower, 'on duplicate key update')
    ) {
        return 'scope_page_enqueue';
    }
    if (
        str_starts_with($normalized, 'DELETE FROM ')
        && str_contains($lower, 'fts_work')
        && str_contains($lower, 'claimed_generation')
        && str_contains($lower, "job_key = 'scope:")
    ) {
        return 'scope_acknowledgement';
    }
    if (
        str_starts_with($normalized, 'UPDATE ')
        && wp_fts_wc_sql_references_named_option(
            $sql,
            (string) $wpdb->options,
            WP_FTS_Plugin::INDEX_HEALTH_OPTION
        )
    ) {
        return 'health_state_cas';
    }
    if (
        str_starts_with($normalized, 'SELECT ')
        && wp_fts_wc_sql_references_named_option(
            $sql,
            (string) $wpdb->options,
            WP_FTS_Plugin::INDEX_HEALTH_OPTION
        )
    ) {
        return 'health_state_read';
    }
    if (
        str_starts_with($normalized, 'SELECT ')
        && str_contains($lower, 'options')
        && str_contains($lower, 'option_name')
        && str_contains($lower, 'autoload')
    ) {
        return 'option_cache_reload';
    }
    if (wp_fts_wc_sql_references_named_option($sql, (string) $wpdb->options, 'cron')) {
        return str_starts_with($normalized, 'SELECT ')
            ? 'cron_schedule_probe'
            : 'cron_schedule_write';
    }
    if (str_starts_with($normalized, 'INSERT INTO ') && str_contains($lower, 'fts_documents')) {
        return 'document_replacement';
    }

    return 'unknown';
}

/** Identify the exact metadata read that authenticates one forced scope index. */
function wp_fts_wc_scope_index_probe_role(string $sql): ?string
{
    $values = [];
    foreach (wp_fts_wc_sql_token_stream($sql, true) as $token) {
        $values[] = (string) ($token['value'] ?? '');
    }
    $prefix = ['show', 'index', 'from'];
    $suffix = ['where', 'key_name', '='];
    if (array_slice($values, 0, 3) !== $prefix || array_slice($values, 4, 3) !== $suffix || count($values) !== 8) {
        return null;
    }

    global $wpdb;

    $contracts = [
        'targeted_scope_index_probe' => [
            ...$prefix,
            strtolower((string) $wpdb->term_relationships),
            ...$suffix,
            strtolower(WP_FTS_Relational_Storage::TARGETED_SCOPE_INDEX_NAME),
        ],
        'filtered_scope_index_probe' => [
            ...$prefix,
            strtolower((string) $wpdb->posts),
            ...$suffix,
            strtolower(WP_FTS_Relational_Storage::FILTERED_SCOPE_INDEX_NAME),
        ],
    ];
    foreach ($contracts as $role => $expected) {
        if ($values === $expected) {
            return $role;
        }
    }

    return null;
}

/** Match one exact option table and name through decoded SQL tokens. */
function wp_fts_wc_sql_references_named_option(string $sql, string $table, string $optionName): bool
{
    if (!wp_fts_wc_sql_references_physical_table($sql, $table)) {
        return false;
    }

    $optionName = strtolower($optionName);
    $window = [];
    foreach (wp_fts_wc_sql_token_stream($sql, true) as $token) {
        $window[] = $token;
        if (count($window) > 3) {
            array_shift($window);
        }
        if (
            count($window) === 3
            && in_array($window[0]['type'] ?? null, ['word', 'identifier'], true)
            && ($window[0]['value'] ?? null) === 'option_name'
            && ($window[1]['type'] ?? null) === 'symbol'
            && ($window[1]['value'] ?? null) === '='
            && ($window[2]['type'] ?? null) === 'string'
            && ($window[2]['value'] ?? null) === $optionName
        ) {
            return true;
        }
    }

    return false;
}

/** @param string[] $roles */
function wp_fts_wc_worker_roles_are_ordered(array $roles): bool
{
    $stages = [
        'lease_acquire' => 0,
        'claim_batch' => 1,
        'claim_source_snapshot' => 2,
        'post_batch_release' => 3,
        'targeted_scope_index_probe' => 4,
        'filtered_scope_index_probe' => 4,
        'corpus_scope_page' => 4,
        'filtered_scope_page' => 4,
        'targeted_scope_page' => 4,
        'conditional_source_fallback' => 4,
        'dependency_measurement' => 5,
        'dependency_values' => 6,
        'replacement_frontier' => 7,
        'post_batch_failure' => 7,
        'lease_heartbeat' => 7,
        'health_state_read' => 8,
        'health_state_cas' => 8,
        'transaction_start' => 8,
        'scope_page_advance' => 9,
        'dictionary_increment' => 9,
        'scope_page_enqueue' => 10,
        'dictionary_decrement' => 10,
        'bounded_index_delete' => 11,
        'resolve_prepared_terms' => 12,
        'posting_replacement' => 13,
        'document_replacement' => 14,
        'scope_acknowledgement' => 15,
        'atomic_worker_ack' => 15,
        'search_epoch_advance' => 16,
        'transaction_commit' => 17,
        'empty_term_cleanup' => 18,
        'lease_release' => 19,
        'option_cache_reload' => 18,
        'cron_schedule_probe' => 18,
        'cron_schedule_write' => 18,
    ];
    $previous = -1;
    $leaseReleased = false;
    foreach ($roles as $role) {
        // Corpus completion publishes diagnostics and consults its already
        // scheduled watchdog only after releasing the writer lease. Those
        // outer option operations cannot reorder the completed data protocol.
        if ($leaseReleased && in_array($role, ['health_state_cas', 'option_cache_reload', 'cron_schedule_probe', 'cron_schedule_write'], true)) {
            continue;
        }
        if (in_array($role, [
            'post_batch_release',
            'scope_yield_to_posts',
            'scope_yield_and_post_batch_release',
            'health_state_cas',
        ], true)) {
            // Set releases appear before reserved scope work, after a
            // failure-only settlement, or inside a writer transaction for a
            // deferred suffix. The two scope-yield shapes publish after
            // document replacement, and diagnostics can follow a completed
            // transaction. None may move the surrounding protocol backward.
            $stage = max($role === 'health_state_cas' ? 8 : 3, $previous);
        } else {
            $stage = $stages[$role] ?? null;
        }
        if (!is_int($stage) || $stage < $previous) {
            return false;
        }
        $previous = $stage;
        if ($role === 'lease_release') {
            $leaseReleased = true;
        }
    }

    return true;
}

/** Detect schema discovery or mutation that must stay outside hot paths. */
function wp_fts_wc_is_physical_schema_statement(string $sql): bool
{
    $firstExecutableWord = null;
    $window = [];
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if ($firstExecutableWord === null && in_array($token['type'] ?? null, ['word', 'identifier'], true)) {
            $firstExecutableWord = (string) ($token['value'] ?? '');
            if (in_array($firstExecutableWord, ['show', 'describe', 'create', 'alter', 'drop', 'rename', 'truncate'], true)) {
                return true;
            }
        }
        $window[] = $token;
        if (count($window) > 3) {
            array_shift($window);
        }
        if (
            count($window) === 3
            && ($window[0]['value'] ?? null) === 'information_schema'
            && ($window[1]['value'] ?? null) === '.'
            && in_array($window[2]['type'] ?? null, ['word', 'identifier'], true)
        ) {
            return true;
        }
    }

    return false;
}

/** Distinguish plugin-owned metadata work from WordPress core write diagnostics. */
function wp_fts_wc_is_fts_physical_schema_statement(string $sql): bool
{
    return wp_fts_wc_is_physical_schema_statement($sql)
        && wp_fts_wc_sql_touches_owned_fts_table($sql, true);
}

/** Identify one plugin-owned INSERT/UPDATE/DELETE/REPLACE without parsing values. */
function wp_fts_wc_is_fts_data_mutation_statement(string $sql): bool
{
    if (!wp_fts_wc_sql_touches_owned_fts_table($sql)) {
        return false;
    }
    foreach (wp_fts_wc_sql_token_stream($sql) as $token) {
        if (($token['type'] ?? null) !== 'word') {
            continue;
        }

        return in_array($token['value'] ?? null, ['insert', 'update', 'delete', 'replace'], true);
    }

    return false;
}

/** Match an exact site-owned FTS identifier, optionally including schema values. */
function wp_fts_wc_sql_touches_owned_fts_table(string $sql, bool $includeQuotedValues = false): bool
{
    global $wpdb;

    $ownedPrefix = strtolower((string) ($wpdb->prefix ?? '') . 'fts_');
    $ownedTokenTypes = $includeQuotedValues ? ['word', 'identifier', 'string'] : ['word', 'identifier'];
    foreach (wp_fts_wc_sql_token_stream($sql, $includeQuotedValues) as $token) {
        if (!in_array($token['type'] ?? null, $ownedTokenTypes, true)) {
            continue;
        }
        if (str_starts_with((string) ($token['value'] ?? ''), $ownedPrefix)) {
            return true;
        }
    }

    return false;
}

/**
 * @param array<int,mixed> $rows
 */
function wp_fts_wc_result_hash(array $rows): string
{
    $signature = [];
    foreach ($rows as $row) {
        if (!is_array($row)) {
            continue;
        }
        $signature[] = [
            'doc_id' => (int) ($row['doc_id'] ?? 0),
            'score' => round((float) ($row['score'] ?? 0.0), 8),
        ];
    }

    return hash('sha256', json_encode($signature, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR));
}

/**
 * Preserve database order while making numeric scores stable across JSON and
 * PHP/MySQL driver representations. Eight fractional digits retain the exact
 * current ranking without float noise.
 *
 * @param array<int,mixed> $rows
 * @return array<int,array{doc_id:int,score:string}>
 */
function wp_fts_wc_ordered_score_signature(array $rows): array
{
    $signature = [];
    foreach ($rows as $row) {
        if (!is_array($row) || !is_numeric($row['doc_id'] ?? null) || !is_numeric($row['score'] ?? null)) {
            throw new RuntimeException('Current ranking returned a malformed result row.');
        }
        $score = (float) $row['score'];
        if (!is_finite($score)) {
            throw new RuntimeException('Current ranking returned a non-finite score.');
        }
        $signature[] = [
            'doc_id' => (int) $row['doc_id'],
            'score' => number_format($score, 8, '.', ''),
        ];
    }
    return $signature;
}

/**
 * @param array{terms:string,postings:string,documents:string,work:string} $tables
 * @return array{tables:array<string,array{data_bytes:int,index_bytes:int,total_bytes:int}>,data_bytes:int,index_bytes:int,total_bytes:int}
 */
function wp_fts_wc_storage_bytes(array $tables): array
{
    global $wpdb;

    foreach ($tables as $table) {
        $wpdb->query('ANALYZE TABLE `' . wp_fts_wc_identifier($table) . '`');
    }
    $placeholders = implode(',', array_fill(0, count($tables), '%s'));
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT TABLE_NAME,DATA_LENGTH,INDEX_LENGTH FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ({$placeholders})",
        ...array_values($tables)
    ), ARRAY_A) ?: [];
    $details = [];
    $dataBytes = 0;
    $indexBytes = 0;
    foreach ($rows as $row) {
        $data = (int) $row['DATA_LENGTH'];
        $index = (int) $row['INDEX_LENGTH'];
        $details[(string) $row['TABLE_NAME']] = ['data_bytes' => $data, 'index_bytes' => $index, 'total_bytes' => $data + $index];
        $dataBytes += $data;
        $indexBytes += $index;
    }
    wp_fts_wc_assert(count($details) === count($tables), 'Could not measure every FTS table in information_schema.');

    return ['tables' => $details, 'data_bytes' => $dataBytes, 'index_bytes' => $indexBytes, 'total_bytes' => $dataBytes + $indexBytes];
}

/**
 * @param float[] $samples
 * @return array{count:int,min:float,p50:float,p95:float,p99:float,max:float,mean:float}
 */
function wp_fts_wc_distribution(array $samples): array
{
    if ($samples === []) {
        return ['count' => 0, 'min' => INF, 'p50' => INF, 'p95' => INF, 'p99' => INF, 'max' => INF, 'mean' => INF];
    }
    sort($samples, SORT_NUMERIC);

    return [
        'count' => count($samples),
        'min' => (float) $samples[0],
        'p50' => wp_fts_wc_nearest_rank($samples, 0.50),
        'p95' => wp_fts_wc_nearest_rank($samples, 0.95),
        'p99' => wp_fts_wc_nearest_rank($samples, 0.99),
        'max' => (float) $samples[array_key_last($samples)],
        'mean' => array_sum($samples) / count($samples),
    ];
}

/**
 * @param float[] $sorted
 */
function wp_fts_wc_nearest_rank(array $sorted, float $quantile): float
{
    $rank = max(1, (int) ceil($quantile * count($sorted)));
    return (float) $sorted[$rank - 1];
}

/**
 * @return array{id:string,expected:mixed,actual:mixed,passed:bool}
 */
function wp_fts_wc_gate(string $id, mixed $expected, mixed $actual, bool $passed): array
{
    return ['id' => $id, 'expected' => $expected, 'actual' => $actual, 'passed' => $passed];
}

/**
 * @param array<int,array<string,mixed>> $gates
 */
function wp_fts_wc_gates_pass(array $gates): bool
{
    return $gates !== [] && count(array_filter($gates, static fn(array $gate): bool => empty($gate['passed']))) === 0;
}

/**
 * @param array<int,array<string,mixed>> $gates
 * @return string[]
 */
function wp_fts_wc_gate_failures(array $gates): array
{
    $failures = [];
    foreach ($gates as $gate) {
        if (empty($gate['passed'])) {
            $failures[] = (string) ($gate['id'] ?? 'unnamed');
        }
    }

    return $failures;
}

/** @return string[] */
function wp_fts_wc_validation_section_ids(): array
{
    return [
        'runtime',
        'runtime_profile_parity',
        'mutation_fence_concurrency',
        'actual_wpcli_adapter',
        'cold_ready_requests',
        'resource_limits',
        'manifest',
        'tables',
        'physical_schema',
        'storage',
        'indexing',
        'dirty_head',
        'adversarial_frequencies',
        'surface_storage',
        'identity_epoch_engine',
        'analysis',
        'oracle',
        'cursor_traversal',
        'terminal_streaming_oracle',
        'write_paths',
        'availability_faults',
        'failure_recovery',
        'cases',
        'pack_cardinality',
        'public_adapters',
        'actual_http_adapters',
        'adapter_oracle',
        'explosive_input',
        'dependency_lob',
    ];
}

/**
 * Authenticate the preliminary report shape before any later phase data is
 * merged. The inventory is part of the source-bound self-hashed artifact; a
 * removed case, section, or gate without the matching inventory entry fails.
 *
 * @param array<string,mixed> $evidence
 */
function wp_fts_wc_validation_inventory_matches(array $evidence): bool
{
    $expectedTopLevelKeys = [
        'schema', 'status', 'source_sha', 'zip_sha256', 'source_dirty', 'acceptance_lane', 'lane_id', 'completed', 'engine',
        ...wp_fts_wc_validation_section_ids(),
        'validation_inventory', 'gates', 'concurrency', 'evidence_sha256',
    ];
    if (array_keys($evidence) !== $expectedTopLevelKeys) {
        return false;
    }
    $inventory = is_array($evidence['validation_inventory'] ?? null) ? $evidence['validation_inventory'] : [];
    $gates = is_array($evidence['gates'] ?? null) ? array_values($evidence['gates']) : [];
    $gateIds = array_map(static fn(mixed $gate): string => is_array($gate) && is_string($gate['id'] ?? null) ? (string) $gate['id'] : '', $gates);
    $expectedCaseIds = [
        'common_or',
        'max_valid_or_prefix',
        'rare_anchor_and',
        'prefix_fanout',
        'surface_rarest_exact_anchor_and',
        'surface_dense_candidate_prefix_and',
        'selective_prefix_anchor_and',
        'hidden_dirty_head',
        'impossible_and',
        'all_packs',
        'ambiguous_morphology_or',
        'ambiguous_morphology_and',
        'field_impact',
    ];
    $criticalGateIds = [
        'runtime_performance_schema_integrity',
        'mutation_fence_real_database_artifact',
        'mutation_fence_real_database_cross_process_guard',
        'mutation_fence_real_database_owned_scope_delete',
        'mutation_fence_real_database_corpus_publication',
