            'diagnostic_rss_peak_increment',
            'rss_peak',
            'rows_examined',
        ] as $suffix) {
            $criticalGateIds[] = "{$caseId}_{$suffix}";
        }
    }

    return ($inventory['schema'] ?? null) === 'relational-fts-validation-inventory-v1'
        && ($inventory['section_ids'] ?? null) === wp_fts_wc_validation_section_ids()
        && ($inventory['case_ids'] ?? null) === $expectedCaseIds
        && ($inventory['gate_ids'] ?? null) === $gateIds
        && ($inventory['gate_count'] ?? null) === count($gateIds)
        && ($inventory['gate_ids_sha256'] ?? null) === wp_fts_wc_canonical_hash($gateIds)
        && $gateIds !== []
        && !in_array('', $gateIds, true)
        && !in_array('evidence_gate_ids_unique', $gateIds, true)
        && count(array_unique($gateIds)) === count($gateIds)
        && array_diff($criticalGateIds, $gateIds) === []
        && wp_fts_wc_gate_inventory_fingerprint_matches($gateIds, 'preliminary')
        && array_keys(is_array($evidence['cases'] ?? null) ? $evidence['cases'] : []) === $expectedCaseIds;
}

/** Return the two explicitly reviewed ordered gate inventories. */
function wp_fts_wc_expected_gate_inventory_fingerprints(): array
{
    return [
        'preliminary' => [
            'count' => 1170,
            'sha256' => '0419c613811a13d49755af028011543c41d31a8f0bbd4a2acf65e03f1c5a4e25',
        ],
        'final' => [
            'count' => 2647,
            'sha256' => 'ca53417ea9628ff92fc9087c5097cdc0928a3d409b50b222a2671a2c4f989492',
        ],
    ];
}

/** Match an ordered gate list without allowing self-rehashed shrinkage. */
function wp_fts_wc_gate_inventory_fingerprint_matches(mixed $gateIds, string $phase): bool
{
    $expected = wp_fts_wc_expected_gate_inventory_fingerprints()[$phase] ?? null;
    if (!is_array($expected)
        || !is_array($gateIds)
        || !array_is_list($gateIds)
        || count($gateIds) !== ($expected['count'] ?? null)
        || count(array_filter($gateIds, static fn(mixed $id): bool => is_string($id) && $id !== '' && trim($id) === $id)) !== count($gateIds)
        || count(array_unique($gateIds)) !== count($gateIds)
    ) {
        return false;
    }

    $actualHash = wp_fts_wc_canonical_hash($gateIds);

    return is_string($expected['sha256'] ?? null)
        && hash_equals((string) $expected['sha256'], $actualHash);
}

/**
 * Reject a phase artifact that could otherwise pass by omitting its gate list.
 *
 * @param array<string,mixed> $evidence
 * @param string[] $requiredGateIds
 * @return array<int,array<string,mixed>>
 */
function wp_fts_wc_require_evidence_gates(
    array $evidence,
    string $label,
    array $requiredGateIds,
    ?string $schema = null
): array {
    if ($schema !== null && ($evidence['schema'] ?? null) !== $schema) {
        throw new RuntimeException("{$label} evidence has the wrong schema.");
    }
    if (($evidence['status'] ?? null) !== 'PASS') {
        throw new RuntimeException("{$label} evidence is not PASS.");
    }
    $gates = is_array($evidence['gates'] ?? null) ? array_values($evidence['gates']) : [];
    if ($gates === []) {
        throw new RuntimeException("{$label} evidence has no gates.");
    }
    $ids = [];
    foreach ($gates as $gate) {
        if (
            !is_array($gate)
            || !is_string($gate['id'] ?? null)
            || trim((string) $gate['id']) === ''
            || !array_key_exists('expected', $gate)
            || !array_key_exists('actual', $gate)
            || !is_bool($gate['passed'] ?? null)
        ) {
            throw new RuntimeException("{$label} evidence contains a malformed gate.");
        }
        if (isset($ids[$gate['id']])) {
            throw new RuntimeException("{$label} evidence repeats gate {$gate['id']}.");
        }
        $ids[$gate['id']] = true;
    }
    $actualGateIds = array_keys($ids);
    if ($actualGateIds !== $requiredGateIds) {
        $missing = array_values(array_diff($requiredGateIds, $actualGateIds));
        $unexpected = array_values(array_diff($actualGateIds, $requiredGateIds));
        throw new RuntimeException("{$label} evidence gate inventory differs; missing=" . implode(',', $missing) . '; unexpected=' . implode(',', $unexpected));
    }
    if (!wp_fts_wc_gates_pass($gates)) {
        throw new RuntimeException("{$label} evidence has failed gates: " . implode(', ', wp_fts_wc_gate_failures($gates)));
    }

    return $gates;
}

/**
 * @return array<string,mixed>
 */
function wp_fts_wc_manifest(): array
{
    $manifest = get_option(WP_FTS_WC_MANIFEST_OPTION, null);
    if (!is_array($manifest) || ($manifest['schema'] ?? null) !== 'relational-worst-case-corpus-v1') {
        throw new RuntimeException('Worst-case corpus manifest is missing. Run setup through the wrapper first.');
    }
    $expectedHash = $manifest['sha256'] ?? null;
    $hashInput = $manifest;
    unset($hashInput['sha256']);
    wp_fts_wc_assert(is_string($expectedHash) && hash_equals($expectedHash, wp_fts_wc_canonical_hash($hashInput)), 'Corpus manifest hash does not match its contents.');
    wp_fts_wc_assert(($manifest['source_sha'] ?? null) === wp_fts_wc_required_env('WP_FTS_SOURCE_SHA'), 'Corpus and tested source SHA differ.');
    wp_fts_wc_assert(($manifest['zip_sha256'] ?? null) === wp_fts_wc_required_env('WP_FTS_ZIP_SHA256'), 'Corpus and installed ZIP SHA-256 differ.');
    wp_fts_wc_assert(($manifest['harness_sha256'] ?? null) === wp_fts_wc_required_env('WP_FTS_HARNESS_SHA256'), 'Corpus and acceptance harness SHA-256 differ.');
    wp_fts_wc_assert(($manifest['lane_id'] ?? null) === wp_fts_wc_required_env('WP_FTS_WC_LANE_ID'), 'Corpus and stable lane identity differ.');

    return $manifest;
}

/**
 * Hash evidence after deterministic associative-key ordering.
 *
 * Feed JSON tokens directly into the hash context: finalization already owns
 * the complete report, so a sorted copy plus one complete JSON string can
 * exceed the same 128-MiB PHP limit that the report is meant to validate.
 */
function wp_fts_wc_canonical_hash(mixed $value): string
{
    $context = hash_init('sha256');
    $flags = JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR;
    $append = static function (mixed $node) use (&$append, $context, $flags): void {
        if (!is_array($node)) {
            hash_update($context, json_encode($node, $flags));
            return;
        }

        if (array_is_list($node)) {
            hash_update($context, '[');
            foreach ($node as $index => $child) {
                if ($index > 0) {
                    hash_update($context, ',');
                }
                $append($child);
            }
            hash_update($context, ']');
            return;
        }

        $keys = array_keys($node);
        sort($keys, SORT_STRING);
        hash_update($context, '{');
        foreach ($keys as $index => $key) {
            if ($index > 0) {
                hash_update($context, ',');
            }
            hash_update($context, json_encode((string) $key, $flags) . ':');
            $append($node[$key]);
        }
        hash_update($context, '}');
    };
    $append($value);

    return hash_final($context);
}

/** Fail before a diagnostic vector can make the compact evidence unbounded. */
function wp_fts_wc_assert_json_evidence_bytes(mixed $value, int $maxBytes, string $label): void
{
    wp_fts_wc_assert($maxBytes > 0, "{$label} has an invalid byte bound.");
    $json = json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR);
    wp_fts_wc_assert(strlen($json) <= $maxBytes, "{$label} exceeds its {$maxBytes}-byte compact JSON bound.");
}

/** Sort maps recursively while preserving list order and scalar types. */
function wp_fts_wc_canonicalize(mixed $value): mixed
{
    if (!is_array($value)) {
        return $value;
    }
    if (array_is_list($value)) {
        return array_map('wp_fts_wc_canonicalize', $value);
    }
    ksort($value, SORT_STRING);
    foreach ($value as $key => $child) {
        $value[$key] = wp_fts_wc_canonicalize($child);
    }

    return $value;
}

/**
 * @return array<string,mixed>
 */
function wp_fts_wc_read_json(string $path): array
{
    $json = @file_get_contents($path);
    if (!is_string($json)) {
        throw new RuntimeException("Could not read required JSON evidence: {$path}");
    }
    $value = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    if (!is_array($value)) {
        throw new RuntimeException("JSON evidence is not an object: {$path}");
    }

    return $value;
}

/**
 * @param array<string,mixed> $value
 */
function wp_fts_wc_write_json(string $path, array $value): void
{
    $directory = dirname($path);
    if (!is_dir($directory) && !mkdir($directory, 0777, true) && !is_dir($directory)) {
        throw new RuntimeException("Could not create report directory: {$directory}");
    }
    $temporary = $path . '.tmp.' . getmypid();
    $handle = @fopen($temporary, 'xb');
    if (!is_resource($handle)) {
        throw new RuntimeException("Could not atomically write report: {$path}");
    }

    $flags = JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION | JSON_THROW_ON_ERROR;
    $write = static function (string $bytes) use ($handle, $path): void {
        while ($bytes !== '') {
            $written = fwrite($handle, $bytes);
            if (!is_int($written) || $written <= 0) {
                throw new RuntimeException("Could not atomically write report: {$path}");
            }
            $bytes = (string) substr($bytes, $written);
        }
    };
    $append = static function (mixed $node, int $depth) use (&$append, $flags, $write): void {
        $object = is_object($node);
        if ($node instanceof JsonSerializable) {
            $node = $node->jsonSerialize();
            $object = is_object($node);
        }
        if ($object) {
            $node = get_object_vars($node);
        }
        if (!is_array($node)) {
            $write(json_encode($node, $flags));
            return;
        }
        if ($node === []) {
            $write($object ? '{}' : '[]');
            return;
        }

        $list = !$object && array_is_list($node);
        $write($list ? "[\n" : "{\n");
        $last = array_key_last($node);
        foreach ($node as $key => $child) {
            $write(str_repeat('    ', $depth + 1));
            if (!$list) {
                $write(json_encode((string) $key, $flags) . ': ');
            }
            $append($child, $depth + 1);
            $write($key === $last ? "\n" : ",\n");
        }
        $write(str_repeat('    ', $depth) . ($list ? ']' : '}'));
    };

    try {
        if (!flock($handle, LOCK_EX)) {
            throw new RuntimeException("Could not atomically write report: {$path}");
        }
        $append($value, 0);
        $write("\n");
        if (!fflush($handle)) {
            throw new RuntimeException("Could not atomically write report: {$path}");
        }
        flock($handle, LOCK_UN);
        fclose($handle);
    } catch (Throwable $error) {
        @flock($handle, LOCK_UN);
        @fclose($handle);
        @unlink($temporary);
        throw $error;
    }
    if (!rename($temporary, $path)) {
        @unlink($temporary);
        throw new RuntimeException("Could not atomically write report: {$path}");
    }
}

/** Resolve and create only the wrapper-supplied evidence directory. */
function wp_fts_wc_evidence_dir(): string
{
    $path = wp_fts_wc_required_env('WP_FTS_WC_EVIDENCE_DIR');
    if (!is_dir($path) && !mkdir($path, 0777, true) && !is_dir($path)) {
        throw new RuntimeException("Could not create evidence directory: {$path}");
    }

    return rtrim($path, '/\\');
}

/** Keep the final report at one stable path consumed by the wrapper. */
function wp_fts_wc_evidence_path(): string
{
    return wp_fts_wc_evidence_dir() . '/relational-fts-evidence.json';
}

/** Reject missing or blank wrapper inputs rather than weakening the proof. */
function wp_fts_wc_required_env(string $name): string
{
    $value = getenv($name);
    if (!is_string($value) || trim($value) === '') {
        throw new RuntimeException("Required environment variable is missing: {$name}");
    }

    return trim($value);
}

/** Parse a required decimal environment value without coercive syntax. */
function wp_fts_wc_required_positive_int_env(string $name): int
{
    $value = wp_fts_wc_required_env($name);
    if ($value === '' || strspn($value, '0123456789') !== strlen($value) || (int) $value <= 0) {
        throw new RuntimeException("{$name} must be a positive integer.");
    }

    return (int) $value;
}

/** Parse a required unsigned decimal environment value including zero. */
function wp_fts_wc_required_non_negative_int_env(string $name): int
{
    $value = wp_fts_wc_required_env($name);
    if ($value === '' || strspn($value, '0123456789') !== strlen($value)) {
        throw new RuntimeException("{$name} must be a non-negative integer.");
    }

    return (int) $value;
}

/** Read Linux process RSS counters rather than relying on PHP allocator totals. */
function wp_fts_wc_rss_bytes(string $field): int
{
    $contents = @file('/proc/self/status', FILE_IGNORE_NEW_LINES);
    if (!is_array($contents)) {
        throw new RuntimeException('Linux /proc/self/status is required for real RSS evidence.');
    }
    foreach ($contents as $line) {
        $prefix = $field . ':';
        if (!str_starts_with($line, $prefix)) {
            continue;
        }
        $parts = array_values(array_filter(explode(' ', trim(substr($line, strlen($prefix)))), static fn(string $part): bool => $part !== ''));
        if ($parts === [] || !wp_fts_wc_is_ascii_digits($parts[0])) {
            break;
        }
        return (int) $parts[0] * 1024;
    }

    throw new RuntimeException("Could not read {$field} from /proc/self/status.");
}

/** Allowlist generated SQL identifiers before interpolation. */
function wp_fts_wc_identifier(string $identifier): string
{
    if ($identifier === '' || strspn($identifier, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_') !== strlen($identifier)) {
        throw new RuntimeException("Unsafe generated SQL identifier: {$identifier}");
    }

    return $identifier;
}

/** Convert a monotonic nanosecond start time to elapsed milliseconds. */
function wp_fts_wc_elapsed_ms(int $started): float
{
    return (hrtime(true) - $started) / 1_000_000;
}

/** Invoke the private writer boundary for destructive fixture mutations. */
function wp_fts_wc_run_writer_fixture(string $source, callable $writer, array $options = []): array
{
    $method = new ReflectionMethod(WP_FTS_Plugin::class, 'run_index_writer_with_lock');
    $method->setAccessible(true);

    return $method->invoke(null, $source, $writer, $options);
}

/** Turn every failed acceptance invariant into a hard process failure. */
function wp_fts_wc_assert(bool $condition, string $message): void
{
    if (!$condition) {
        throw new RuntimeException($message);
    }
}

/** Reach the private production storage factory only from this fixture. */
function wp_fts_wc_storage_fixture(bool $ensureSchema = false): WP_FTS_Relational_Storage
{
    $method = new ReflectionMethod(WP_FTS_Plugin::class, 'storage');
    $method->setAccessible(true);

    return $method->invoke(null, $ensureSchema);
}
